fn v2_value_string<'a>(value: &'a Value, field: &str) -> Result<&'a str, StoreError> {
    value
        .get(field)
        .and_then(Value::as_str)
        .filter(|text| !text.is_empty())
        .ok_or_else(|| StoreError::InvalidData(format!("V2 particle field {field} is missing")))
}

fn v2_value_u64(value: &Value, field: &str) -> Result<u64, StoreError> {
    value.get(field).and_then(Value::as_u64).ok_or_else(|| {
        StoreError::InvalidData(format!("V2 particle field {field} is not an integer"))
    })
}

fn v2_value_bool(value: &Value, field: &str) -> Result<bool, StoreError> {
    value
        .get(field)
        .and_then(Value::as_bool)
        .ok_or_else(|| StoreError::InvalidData(format!("V2 particle field {field} is not boolean")))
}

fn v2_frames(value: &Value) -> Result<Vec<&Value>, StoreError> {
    value
        .get("frames")
        .and_then(Value::as_array)
        .map(|frames| frames.iter().collect())
        .ok_or_else(|| {
            StoreError::InvalidData("V2 particle sequence frames are missing".to_owned())
        })
}

fn v2_normalized_value(value: &Value) -> Value {
    let mut normalized = value.clone();
    if let Some(object) = normalized.as_object_mut() {
        object.insert("canonical_sha256".to_owned(), Value::String(String::new()));
        object.insert("created_at".to_owned(), Value::String(String::new()));
        if let Some(frames) = object.get_mut("frames").and_then(Value::as_array_mut) {
            for frame in frames {
                if let Some(frame_object) = frame.as_object_mut() {
                    frame_object
                        .insert("canonical_sha256".to_owned(), Value::String(String::new()));
                    frame_object.insert("created_at".to_owned(), Value::String(String::new()));
                }
            }
        }
    }
    normalized
}

fn v2_canonical_value(value: &Value) -> Value {
    let mut canonical = value.clone();
    if let Some(object) = canonical.as_object_mut() {
        object.insert("canonical_sha256".to_owned(), Value::String(String::new()));
        if let Some(frames) = object.get_mut("frames").and_then(Value::as_array_mut) {
            for frame in frames {
                if let Some(frame_object) = frame.as_object_mut() {
                    frame_object
                        .insert("canonical_sha256".to_owned(), Value::String(String::new()));
                }
            }
        }
    }
    canonical
}

fn same_fictional_energy_vfx_animated_socket_particles_sequence_v2_value(
    left: &Value,
    right: &Value,
) -> bool {
    let left = v2_normalized_value(left);
    let right = v2_normalized_value(right);
    canonical_json_bytes(&left).ok() == canonical_json_bytes(&right).ok()
}

fn v2_invalid(message: impl Into<String>) -> StoreError {
    StoreError::InvalidData(message.into())
}

fn v2_binding_mismatch(code: &str, message: &str) -> StoreError {
    StoreError::Contract {
        code: code.to_owned(),
        message: message.to_owned(),
    }
}

fn validate_fictional_energy_vfx_animated_socket_particles_sequence_v2_value(
    value: &Value,
) -> Result<(), StoreError> {
    let schema_version = v2_value_string(value, "schema_version")?;
    if schema_version != "FictionalEnergyVfxAnimatedSocketParticlesSequence@2" {
        return Err(v2_invalid(
            "V2 animated particle sequence schema is invalid",
        ));
    }
    let key = v2_value_string(value, "sequence_key_sha256")?;
    if !is_sha256(key) || !is_opaque_id(v2_value_string(value, "project_id")?) {
        return Err(v2_invalid(
            "V2 animated particle sequence identity is invalid",
        ));
    }
    for field in [
        "geometry_candidate_state_sha256",
        "geometry_delivery_manifest_object_sha256",
        "geometry_artifact_sha256",
        "appearance_candidate_state_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
        "material_surface_quality_report_object_sha256",
        "material_surface_quality_canonical_sha256",
        "geometry_preservation_projection_sha256",
        "projection_key_sha256",
        "projection_object_sha256",
        "projection_canonical_sha256",
        "animated_socket_materialization_key_sha256",
        "animated_artifact_sha256",
        "animated_socket_anchor_set_object_sha256",
        "animated_socket_anchor_set_canonical_sha256",
        "appearance_anchor_set_object_sha256",
        "appearance_anchor_set_canonical_sha256",
        "anchor_binding_sha256",
        "animation_clip_object_sha256",
        "animation_clip_canonical_sha256",
        "animation_receipt_object_sha256",
        "animation_receipt_canonical_sha256",
        "vfx_profile_object_sha256",
        "vfx_profile_canonical_sha256",
        "socket_node_id_encoding_sha256",
        "socket_roles_sha256",
        "camera_object_sha256",
        "camera_identity_sha256",
        "render_profile_sha256",
        "render_worker_build_cohort_sha256",
        "sample_schedule_sha256",
        "input_sha256",
    ] {
        if !is_sha256(v2_value_string(value, field)?) {
            return Err(v2_invalid(format!(
                "V2 animated particle hash {field} is invalid"
            )));
        }
    }
    for field in [
        "geometry_candidate_id",
        "appearance_candidate_id",
        "material_surface_quality_id",
        "animation_clip_id",
    ] {
        if !is_opaque_id(v2_value_string(value, field)?) {
            return Err(v2_invalid(format!(
                "V2 animated particle ID {field} is invalid"
            )));
        }
    }
    if v2_value_string(value, "geometry_candidate_id")?
        == v2_value_string(value, "appearance_candidate_id")?
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_CANDIDATE_COLLISION",
            "V2 geometry and appearance candidates must be distinct",
        ));
    }
    if v2_value_string(value, "geometry_artifact_sha256")?
        == v2_value_string(value, "appearance_artifact_sha256")?
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_ARTIFACT_COLLISION",
            "V2 geometry and appearance artifacts must be distinct",
        ));
    }
    let sample_count = v2_value_u64(value, "sample_count")?;
    let sample_ticks = value
        .get("sample_time_ticks")
        .and_then(Value::as_array)
        .ok_or_else(|| v2_invalid("V2 sample_time_ticks is missing"))?;
    if !(1..=16).contains(&sample_count)
        || sample_ticks.len() != sample_count as usize
        || sample_ticks.windows(2).any(|pair| {
            pair[0].as_u64().unwrap_or(u64::MAX) >= pair[1].as_u64().unwrap_or(u64::MAX)
        })
        || sample_ticks
            .iter()
            .any(|tick| tick.as_u64().is_none_or(|tick| tick > 1_000_000))
    {
        return Err(v2_invalid("V2 sample schedule is invalid"));
    }
    let frames = v2_frames(value)?;
    if frames.len() != sample_count as usize {
        return Err(v2_invalid(
            "V2 particle frame count differs from sample count",
        ));
    }
    for (ordinal, frame) in frames.iter().enumerate() {
        let frame_schema = v2_value_string(frame, "schema_version")?;
        if frame_schema != "FictionalEnergyVfxAnimatedSocketParticlesSequenceFrame@2"
            || v2_value_u64(frame, "frame_index")? != ordinal as u64
            || v2_value_u64(frame, "sample_time_ticks")?
                != sample_ticks[ordinal].as_u64().unwrap_or(u64::MAX)
        {
            return Err(v2_invalid(
                "V2 particle frame order or sample time is invalid",
            ));
        }
        for field in [
            "projection_frame_canonical_sha256",
            "projection_socket_transform_inventory_sha256",
            "projection_socket_transform_readback_sha256",
            "base_frame_key_sha256",
            "bloom_key_sha256",
            "emitter_socket_bindings_sha256",
            "input_sha256",
            "particle_key_sha256",
            "particle_seed_sha256",
            "render_set_object_sha256",
            "receipt_object_sha256",
            "particle_color_object_sha256",
            "particle_id_object_sha256",
            "particle_depth_object_sha256",
        ] {
            if !is_sha256(v2_value_string(frame, field)?) {
                return Err(v2_invalid(format!(
                    "V2 particle frame hash {field} is invalid"
                )));
            }
        }
        let mut normalized = (*frame).clone();
        if let Some(object) = normalized.as_object_mut() {
            object.insert("canonical_sha256".to_owned(), Value::String(String::new()));
        }
        let expected = canonical_json_hash(&normalized);
        if v2_value_string(frame, "canonical_sha256")? != expected
            || v2_value_string(frame, "created_at")?.len() > 128
        {
            return Err(v2_invalid("V2 particle frame canonical binding is invalid"));
        }
    }
    if v2_value_string(value, "frame_scope")? != "lod0-animation-particles-frame-range-1-16@2"
        || v2_value_string(value, "particles_sequence_policy")?
            != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PROJECTION_POLICY
        || v2_value_string(value, "emitter_binding_policy")?
            != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_EMITTER_POLICY
        || v2_value_string(value, "transform_projection_policy")?
            != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_POLICY
        || v2_value_string(value, "sequence_status")?
            != "runtime-owned-durable-fictional-energy-vfx-animated-socket-particles-sequence-v2"
        || v2_value_string(value, "anchor_binding_policy")?
            != "geometry-appearance-anchor-role-owner-trs-equivalent@1"
        || v2_value_string(value, "geometry_preservation_status")?
            != "source-output-renderable-geometry-byte-exact"
        || v2_value_string(value, "quality_status")? != "structural_only"
        || v2_value_string(value, "visual_quality_status")? != "NOT_PROVEN"
        || v2_value_string(value, "commercial_fps_quality_status")? != "NOT_PROVEN"
        || v2_value_string(value, "human_review_status")? != "NOT_RUN"
        || v2_value_string(value, "commercial_engine_status")? != "NOT_RUN"
        || !v2_value_bool(value, "runtime_write_performed")?
        || !v2_value_bool(value, "restart_hash_verified")?
        || v2_value_bool(value, "candidate_confirmed")?
        || v2_value_bool(value, "version_created")?
        || v2_value_bool(value, "export_performed")?
        || v2_value_bool(value, "actual_engine_roundtrip")?
        || v2_value_bool(value, "production_stage_advanced")?
    {
        return Err(v2_invalid(
            "V2 animated particle status or policy is invalid",
        ));
    }
    if v2_value_string(value, "created_at")?.len() > 128 {
        return Err(v2_invalid("V2 animated particle created_at is invalid"));
    }
    let expected = canonical_json_hash(&v2_canonical_value(value));
    if v2_value_string(value, "canonical_sha256")? != expected {
        return Err(v2_invalid("V2 animated particle canonical hash is invalid"));
    }
    let _ = key;
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_particles_sequence_v2_receipt_bytes(
    bytes: &[u8],
    sequence: &Value,
    object: &CasObjectRecord,
) -> Result<(), StoreError> {
    if object.schema_version != "CasObject@1"
        || object.mime != GAME_ASSET_DELIVERY_JSON_MIME
        || object.kind != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_KIND
        || object.size_bytes == 0
        || object.size_bytes > MAX_GAME_ASSET_DELIVERY_JSON_BYTES
        || object.size_bytes != bytes.len() as u64
        || sha256_hex(bytes) != object.sha256
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_RECEIPT_INVALID",
            "V2 animated particle receipt metadata is invalid",
        ));
    }
    let receipt: Value = serde_json::from_slice(bytes).map_err(|error| {
        v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_RECEIPT_INVALID",
            &format!("V2 animated particle receipt JSON is invalid: {error}"),
        )
    })?;
    if canonical_json_bytes(&receipt).map_err(|error| v2_invalid(error.to_string()))? != bytes {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_RECEIPT_CANONICAL_MISMATCH",
            "V2 animated particle receipt is not canonical JSON",
        ));
    }
    if !same_fictional_energy_vfx_animated_socket_particles_sequence_v2_value(&receipt, sequence) {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_RECEIPT_BINDING_MISMATCH",
            "V2 animated particle receipt differs from the sequence",
        ));
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_animated_socket_particles_v2_object(
    connection: &Connection,
    hash: &str,
    expected_mime: &str,
    expected_kinds: &[&str],
    max_bytes: u64,
    role: &str,
) -> Result<(), StoreError> {
    let row: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![hash],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((size, mime, kind, reachability)) = row else {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_CAS_OBJECT_MISSING",
            &format!("V2 particle {role} CAS object is missing"),
        ));
    };
    if size <= 0
        || u64::try_from(size).unwrap_or(u64::MAX) > max_bytes
        || mime != expected_mime
        || !expected_kinds.contains(&kind.as_str())
        || !matches!(reachability.as_str(), "temporary" | "reachable")
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_CAS_OBJECT_INVALID",
            &format!("V2 particle {role} CAS metadata is invalid"),
        ));
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_animated_socket_particles_sequence_v2_objects(
    connection: &Connection,
    value: &Value,
    receipt: &CasObjectRecord,
) -> Result<(), StoreError> {
    let json_max = MAX_GAME_ASSET_DELIVERY_JSON_BYTES;
    let glb_max = 64 * 1024 * 1024;
    let checks: [(&str, &str, &[&str], u64, &str); 13] = [
        (
            "geometry_delivery_manifest_object_sha256",
            GAME_ASSET_DELIVERY_JSON_MIME,
            &["game-asset-delivery-manifest"],
            json_max,
            "geometry delivery",
        ),
        (
            "appearance_delivery_manifest_object_sha256",
            GAME_ASSET_DELIVERY_JSON_MIME,
            &["game-asset-delivery-manifest"],
            json_max,
            "appearance delivery",
        ),
        (
            "geometry_artifact_sha256",
            "model/gltf-binary",
            &["geometry-glb"],
            glb_max,
            "geometry artifact",
        ),
        (
            "appearance_artifact_sha256",
            "model/gltf-binary",
            &["appearance-glb", "appearance-v2-glb"],
            glb_max,
            "appearance artifact",
        ),
        (
            "material_surface_quality_report_object_sha256",
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_KIND],
            json_max,
            "material quality report",
        ),
        (
            "animated_socket_anchor_set_object_sha256",
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[GAME_WEAPON_ANCHOR_SET_KIND],
            json_max,
            "geometry AnchorSet",
        ),
        (
            "appearance_anchor_set_object_sha256",
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[GAME_WEAPON_ANCHOR_SET_KIND],
            json_max,
            "appearance AnchorSet",
        ),
        (
            "projection_object_sha256",
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_KIND],
            MAX_GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_BYTES,
            "projection",
        ),
        (
            "animated_artifact_sha256",
            "model/gltf-binary",
            &[MECHANICAL_ANIMATION_GLB_V2_KIND],
            MAX_MECHANICAL_ANIMATION_GLB_V2_BYTES,
            "animated artifact",
        ),
        (
            "animation_clip_object_sha256",
            MECHANICAL_ANIMATION_CLIP_V2_MIME,
            &[MECHANICAL_ANIMATION_CLIP_V2_KIND],
            MAX_MECHANICAL_ANIMATION_CLIP_V2_BYTES,
            "animation clip",
        ),
        (
            "animation_receipt_object_sha256",
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[MECHANICAL_ANIMATION_GLB_V2_RECEIPT_KIND],
            MAX_MECHANICAL_ANIMATION_GLB_V2_RECEIPT_BYTES,
            "animation receipt",
        ),
        (
            "vfx_profile_object_sha256",
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[FICTIONAL_ENERGY_VFX_PROFILE_KIND],
            json_max,
            "VFX profile",
        ),
        (
            "camera_object_sha256",
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[FICTIONAL_ENERGY_VFX_CAMERA_KIND],
            json_max,
            "camera",
        ),
    ];
    for (field, mime, kinds, max, role) in checks {
        ensure_fictional_energy_vfx_animated_socket_particles_v2_object(
            connection,
            v2_value_string(value, field)?,
            mime,
            kinds,
            max,
            role,
        )?;
    }
    let receipt_meta = CasObjectRecord {
        schema_version: "CasObject@1".to_owned(),
        sha256: receipt.sha256.clone(),
        size_bytes: receipt.size_bytes,
        mime: receipt.mime.clone(),
        kind: receipt.kind.clone(),
        reachability: receipt.reachability.clone(),
        created_at: receipt.created_at.clone(),
    };
    if receipt_meta.kind != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_KIND
        || receipt_meta.mime != GAME_ASSET_DELIVERY_JSON_MIME
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_RECEIPT_INVALID",
            "V2 particle sequence receipt kind is invalid",
        ));
    }
    ensure_fictional_energy_vfx_animated_socket_particles_v2_object(
        connection,
        &receipt.sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        &[FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_KIND],
        json_max,
        "sequence receipt",
    )?;
    for frame in v2_frames(value)? {
        for (field, mime, kind, max, role) in [
            (
                "render_set_object_sha256",
                GAME_ASSET_DELIVERY_JSON_MIME,
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_RENDER_SET_KIND,
                json_max,
                "frame render set",
            ),
            (
                "receipt_object_sha256",
                GAME_ASSET_DELIVERY_JSON_MIME,
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_FRAME_RECEIPT_KIND,
                json_max,
                "frame receipt",
            ),
            (
                "particle_color_object_sha256",
                "image/png",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_COLOR_KIND,
                u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
                "particle color",
            ),
            (
                "particle_id_object_sha256",
                "image/png",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_ID_KIND,
                u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
                "particle ID",
            ),
            (
                "particle_depth_object_sha256",
                "image/png",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_DEPTH_KIND,
                u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
                "particle depth",
            ),
        ] {
            ensure_fictional_energy_vfx_animated_socket_particles_v2_object(
                connection,
                v2_value_string(frame, field)?,
                mime,
                &[kind],
                max,
                role,
            )?;
        }
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_particles_sequence_v2_parent_row(
    connection: &Connection,
    value: &Value,
    sequence_receipt_object_sha256: &str,
) -> Result<(), StoreError> {
    let key = v2_value_string(value, "sequence_key_sha256")?;
    let columns: Option<String> = connection
        .query_row(
            "SELECT json_object(
                'schema_version', schema_version,
                'sequence_key_sha256', sequence_key_sha256,
                'project_id', project_id,
                'geometry_candidate_id', geometry_candidate_id,
                'geometry_candidate_state_sha256', geometry_candidate_state_sha256,
                'geometry_delivery_manifest_object_sha256', geometry_delivery_manifest_object_sha256,
                'geometry_artifact_sha256', geometry_artifact_sha256,
                'appearance_candidate_id', appearance_candidate_id,
                'appearance_candidate_state_sha256', appearance_candidate_state_sha256,
                'appearance_delivery_manifest_object_sha256', appearance_delivery_manifest_object_sha256,
                'appearance_artifact_sha256', appearance_artifact_sha256,
                'projection_key_sha256', projection_key_sha256,
                'projection_object_sha256', projection_object_sha256,
                'projection_canonical_sha256', projection_canonical_sha256,
                'animated_socket_materialization_key_sha256', animated_socket_materialization_key_sha256,
                'animated_artifact_sha256', animated_artifact_sha256,
                'sample_count', sample_count,
                'sample_time_ticks_json', sample_time_ticks_json,
                'transform_projection_policy', transform_projection_policy,
                'sequence_receipt_object_sha256', sequence_receipt_object_sha256,
                'canonical_sha256', canonical_sha256,
                'created_at', created_at
            ) FROM fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_links
             WHERE sequence_key_sha256 = ?1",
            params![key],
            |row| row.get(0),
        )
        .optional()?;
    let Some(columns) = columns else {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PARENT_ROW_MISSING",
            "V2 particle sequence parent row is missing",
        ));
    };
    let columns: Value = serde_json::from_str(&columns).map_err(|error| {
        v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PARENT_ROW_INVALID",
            &format!("V2 particle sequence parent scalar row is invalid: {error}"),
        )
    })?;
    for field in [
        "schema_version",
        "sequence_key_sha256",
        "project_id",
        "geometry_candidate_id",
        "geometry_candidate_state_sha256",
        "geometry_delivery_manifest_object_sha256",
        "geometry_artifact_sha256",
        "appearance_candidate_id",
        "appearance_candidate_state_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
        "projection_key_sha256",
        "projection_object_sha256",
        "projection_canonical_sha256",
        "animated_socket_materialization_key_sha256",
        "animated_artifact_sha256",
        "sample_count",
        "transform_projection_policy",
        "canonical_sha256",
        "created_at",
    ] {
        if columns.get(field) != value.get(field) {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PARENT_ROW_MISMATCH",
                &format!("V2 particle parent scalar {field} differs from payload"),
            ));
        }
    }
    if columns
        .get("sequence_receipt_object_sha256")
        .and_then(Value::as_str)
        != Some(sequence_receipt_object_sha256)
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PARENT_ROW_MISMATCH",
            "V2 particle parent receipt scalar differs from the linked receipt object",
        ));
    }
    let stored_ticks = columns
        .get("sample_time_ticks_json")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PARENT_ROW_INVALID",
                "V2 particle parent sample ticks scalar is missing",
            )
        })?;
    let stored_ticks: Value = serde_json::from_str(stored_ticks).map_err(|error| {
        v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PARENT_ROW_INVALID",
            &format!("V2 particle parent sample ticks scalar is invalid: {error}"),
        )
    })?;
    if stored_ticks != value["sample_time_ticks"] {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PARENT_ROW_MISMATCH",
            "V2 particle parent sample ticks differ from payload",
        ));
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_particles_sequence_v2_frames(
    connection: &Connection,
    value: &Value,
) -> Result<(), StoreError> {
    let key = v2_value_string(value, "sequence_key_sha256")?;
    let expected = v2_frames(value)?;
    let mut statement = connection.prepare(
        "SELECT payload_json FROM fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_frames WHERE sequence_key_sha256 = ?1 ORDER BY frame_index ASC",
    )?;
    let rows = statement.query_map(params![key], |row| row.get::<_, String>(0))?;
    let actual = rows
        .collect::<Result<Vec<_>, _>>()
        .map_err(StoreError::Sqlite)?;
    if actual.len() != expected.len()
        || actual
            .iter()
            .zip(expected.iter())
            .any(|(stored, expected)| {
                serde_json::from_str::<Value>(stored)
                    .ok()
                    .is_none_or(|stored| {
                        !same_fictional_energy_vfx_animated_socket_particles_sequence_v2_value(
                            &stored, expected,
                        )
                    })
            })
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_FRAME_BINDING_MISMATCH",
            "V2 particle child rows differ from the sequence frames",
        ));
    }
    let projection_key = v2_value_string(value, "projection_key_sha256")?;
    for frame in expected {
        let frame_index = v2_value_u64(frame, "frame_index")?;
        let child_columns: Option<String> = connection
            .query_row(
                "SELECT json_object(
                    'schema_version', schema_version,
                    'frame_index', frame_index,
                    'sample_time_ticks', sample_time_ticks,
                    'projection_frame_canonical_sha256', projection_frame_canonical_sha256,
                    'projection_socket_transform_inventory_sha256', projection_socket_transform_inventory_sha256,
                    'projection_socket_transform_readback_sha256', projection_socket_transform_readback_sha256,
                    'canonical_sha256', canonical_sha256,
                    'created_at', created_at
                ) FROM fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_frames
                 WHERE sequence_key_sha256 = ?1 AND frame_index = ?2",
                params![key, frame_index],
                |row| row.get(0),
            )
            .optional()?;
        let Some(child_columns) = child_columns else {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_FRAME_ROW_MISSING",
                "V2 particle frame child row is missing",
            ));
        };
        let child_columns: Value = serde_json::from_str(&child_columns).map_err(|error| {
            v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_FRAME_ROW_INVALID",
                &format!("V2 particle frame child scalar row is invalid: {error}"),
            )
        })?;
        for field in [
            "schema_version",
            "frame_index",
            "sample_time_ticks",
            "projection_frame_canonical_sha256",
            "projection_socket_transform_inventory_sha256",
            "projection_socket_transform_readback_sha256",
            "canonical_sha256",
            "created_at",
        ] {
            if child_columns.get(field) != frame.get(field) {
                return Err(v2_binding_mismatch(
                    "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_FRAME_ROW_MISMATCH",
                    &format!("V2 particle frame scalar {field} differs from payload"),
                ));
            }
        }
        let projection_frame: Option<(u64, String, String, String)> = connection
            .query_row(
                "SELECT sample_time_ticks, projection_frame_canonical_sha256, socket_transform_inventory_sha256, socket_transform_readback_sha256 FROM game_weapon_animated_glb_socket_transform_projection_v2_frames WHERE projection_key_sha256 = ?1 AND frame_index = ?2",
                params![
                    projection_key,
                    frame_index
                ],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .optional()?;
        let Some((sample_time_ticks, canonical, inventory, readback)) = projection_frame else {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PROJECTION_FRAME_MISSING",
                "V2 particle frame is not backed by a Projection@2 frame",
            ));
        };
        if sample_time_ticks != v2_value_u64(frame, "sample_time_ticks")?
            || canonical != v2_value_string(frame, "projection_frame_canonical_sha256")?
            || inventory != v2_value_string(frame, "projection_socket_transform_inventory_sha256")?
            || readback != v2_value_string(frame, "projection_socket_transform_readback_sha256")?
        {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PROJECTION_FRAME_BINDING_MISMATCH",
                "V2 particle frame projection canonical/readback differs",
            ));
        }
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_particles_sequence_v2_bindings(
    connection: &Connection,
    value: &Value,
) -> Result<(), StoreError> {
    let project = v2_value_string(value, "project_id")?;
    let geometry_candidate = v2_value_string(value, "geometry_candidate_id")?;
    let appearance_candidate = v2_value_string(value, "appearance_candidate_id")?;
    let geometry_delivery = v2_value_string(value, "geometry_delivery_manifest_object_sha256")?;
    let appearance_delivery = v2_value_string(value, "appearance_delivery_manifest_object_sha256")?;
    let geometry_artifact = v2_value_string(value, "geometry_artifact_sha256")?;
    let appearance_artifact = v2_value_string(value, "appearance_artifact_sha256")?;
    let quality_id = v2_value_string(value, "material_surface_quality_id")?;
    let quality: Option<(String, String, String)> = connection
        .query_row(
            "SELECT payload_json, report_object_sha256, canonical_sha256 FROM candidate_material_surface_quality_links WHERE material_surface_quality_id = ?1",
            params![quality_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    let Some((quality_payload, quality_report, quality_canonical)) = quality else {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_MATERIAL_SURFACE_MISSING",
            "V2 material-surface quality link is unavailable",
        ));
    };
    let quality_record: CandidateMaterialSurfaceQualityRecord =
        serde_json::from_str(&quality_payload).map_err(|error| v2_invalid(error.to_string()))?;
    validate_candidate_material_surface_quality(&quality_record)?;
    if quality_record.project_id != project
        || quality_record.source_candidate_id != geometry_candidate
        || quality_record.source_candidate_state_sha256
            != v2_value_string(value, "geometry_candidate_state_sha256")?
        || quality_record.source_artifact_sha256 != geometry_artifact
        || quality_record.output_candidate_id != appearance_candidate
        || quality_record.output_candidate_state_sha256
            != v2_value_string(value, "appearance_candidate_state_sha256")?
        || quality_record.output_artifact_sha256 != appearance_artifact
        || quality_report
            != v2_value_string(value, "material_surface_quality_report_object_sha256")?
        || quality_canonical != v2_value_string(value, "material_surface_quality_canonical_sha256")?
        || quality_record.geometry_preservation_projection_sha256
            != v2_value_string(value, "geometry_preservation_projection_sha256")?
        || quality_record.geometry_preservation_status
            != v2_value_string(value, "geometry_preservation_status")?
        || !quality_record.hard_gate_passed
        || quality_record.validator_status != "passed"
        || quality_record.source_output_candidate_binding_status != "distinct-candidates-verified"
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_MATERIAL_SURFACE_BINDING_MISMATCH",
            "V2 material-surface quality does not bind both candidates exactly",
        ));
    }
    for (field, candidate, artifact, role) in [
        (
            "geometry_delivery_manifest_object_sha256",
            geometry_candidate,
            geometry_artifact,
            "geometry",
        ),
        (
            "appearance_delivery_manifest_object_sha256",
            appearance_candidate,
            appearance_artifact,
            "appearance",
        ),
    ] {
        let delivery: Option<(String, String, String)> = connection
            .query_row(
                "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
                params![field_value(value, field)?],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .optional()?;
        if delivery.as_ref().map(|row| row.0.as_str()) != Some(project)
            || delivery.as_ref().map(|row| row.1.as_str()) != Some(candidate)
            || delivery.as_ref().map(|row| row.2.as_str()) != Some(artifact)
        {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_DELIVERY_BINDING_MISMATCH",
                &format!("V2 {role} delivery does not bind candidate/artifact"),
            ));
        }
    }
    let geometry_anchor = v2_value_string(value, "animated_socket_anchor_set_object_sha256")?;
    let appearance_anchor = v2_value_string(value, "appearance_anchor_set_object_sha256")?;
    for (delivery, anchor, role) in [
        (geometry_delivery, geometry_anchor, "geometry AnchorSet"),
        (
            appearance_delivery,
            appearance_anchor,
            "appearance AnchorSet",
        ),
    ] {
        let row: Option<(String, String)> = connection
            .query_row(
                "SELECT project_id, anchor_set_object_sha256 FROM game_weapon_anchor_links WHERE delivery_manifest_object_sha256 = ?1",
                params![delivery],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()?;
        if row.as_ref().map(|row| row.0.as_str()) != Some(project)
            || row.as_ref().map(|row| row.1.as_str()) != Some(anchor)
        {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_ANCHOR_BINDING_MISMATCH",
                &format!("V2 {role} does not bind its delivery"),
            ));
        }
    }
    let projection: Option<(
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        i64,
        String,
        String,
        String,
    )> = connection
        .query_row(
            "SELECT project_id, appearance_candidate_id, appearance_candidate_state_sha256, appearance_delivery_manifest_object_sha256, appearance_artifact_sha256, anchor_set_object_sha256, anchor_set_canonical_sha256, animation_clip_id, animation_clip_object_sha256, animation_clip_canonical_sha256, animation_receipt_object_sha256, animation_receipt_canonical_sha256, animated_socket_materialization_key_sha256, animated_artifact_sha256, socket_node_id_encoding_sha256, socket_roles_sha256, sample_schedule_sha256, sample_count, sample_time_ticks_json, projection_object_sha256, canonical_sha256 FROM game_weapon_animated_glb_socket_transform_projection_v2_links WHERE projection_key_sha256 = ?1",
            params![v2_value_string(value, "projection_key_sha256")?],
            |row| {
                Ok((
                    row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?,
                    row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?,
                    row.get(10)?, row.get(11)?, row.get(12)?, row.get(13)?, row.get(14)?,
                    row.get(15)?, row.get(16)?, row.get(17)?, row.get(18)?, row.get(19)?,
                    row.get(20)?,
                ))
            },
        )
        .optional()?;
    if projection.as_ref().map(|row| row.0.as_str()) != Some(project)
        || projection.as_ref().map(|row| row.1.as_str()) != Some(appearance_candidate)
        || projection.as_ref().map(|row| row.2.as_str())
            != Some(v2_value_string(value, "appearance_candidate_state_sha256")?)
        || projection.as_ref().map(|row| row.3.as_str()) != Some(appearance_delivery)
        || projection.as_ref().map(|row| row.4.as_str()) != Some(appearance_artifact)
        || projection.as_ref().map(|row| row.5.as_str()) != Some(appearance_anchor)
        || projection.as_ref().map(|row| row.6.as_str())
            != Some(v2_value_string(
                value,
                "appearance_anchor_set_canonical_sha256",
            )?)
        || projection.as_ref().map(|row| row.7.as_str())
            != Some(v2_value_string(value, "animation_clip_id")?)
        || projection.as_ref().map(|row| row.8.as_str())
            != Some(v2_value_string(value, "animation_clip_object_sha256")?)
        || projection.as_ref().map(|row| row.9.as_str())
            != Some(v2_value_string(value, "animation_clip_canonical_sha256")?)
        || projection.as_ref().map(|row| row.10.as_str())
            != Some(v2_value_string(value, "animation_receipt_object_sha256")?)
        || projection.as_ref().map(|row| row.11.as_str())
            != Some(v2_value_string(
                value,
                "animation_receipt_canonical_sha256",
            )?)
        || projection.as_ref().map(|row| row.12.as_str())
            != Some(v2_value_string(
                value,
                "animated_socket_materialization_key_sha256",
            )?)
        || projection.as_ref().map(|row| row.13.as_str())
            != Some(v2_value_string(value, "animated_artifact_sha256")?)
        || projection.as_ref().map(|row| row.14.as_str())
            != Some(v2_value_string(value, "socket_node_id_encoding_sha256")?)
        || projection.as_ref().map(|row| row.15.as_str())
            != Some(v2_value_string(value, "socket_roles_sha256")?)
        || projection.as_ref().map(|row| row.16.as_str())
            != Some(v2_value_string(value, "sample_schedule_sha256")?)
        || projection
            .as_ref()
            .and_then(|row| u64::try_from(row.17).ok())
            != Some(v2_value_u64(value, "sample_count")?)
        || projection.as_ref().map(|row| row.18.as_str())
            != Some(canonical_json_string(&value["sample_time_ticks"])?.as_str())
        || projection.as_ref().map(|row| row.19.as_str())
            != Some(v2_value_string(value, "projection_object_sha256")?)
        || projection.as_ref().map(|row| row.20.as_str())
            != Some(v2_value_string(value, "projection_canonical_sha256")?)
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PROJECTION_BINDING_MISMATCH",
            "V2 projection does not bind the appearance source",
        ));
    }
    let profile: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, vfx_profile_object_sha256, anchor_set_object_sha256 FROM fictional_energy_vfx_links WHERE delivery_manifest_object_sha256 = ?1",
            params![appearance_delivery],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if profile.as_ref().map(|row| row.0.as_str()) != Some(project)
        || profile.as_ref().map(|row| row.1.as_str())
            != Some(v2_value_string(value, "vfx_profile_object_sha256")?)
        || profile.as_ref().map(|row| row.2.as_str()) != Some(appearance_anchor)
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_PROFILE_BINDING_MISMATCH",
            "V2 VFX profile does not bind appearance source",
        ));
    }
    for frame in v2_frames(value)? {
        let base: Option<(String, String, String, String, String, String, String, String, String)> =
            connection
                .query_row(
                    "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, camera_object_sha256, camera_identity_sha256, render_profile_sha256, render_worker_build_cohort_sha256 FROM fictional_energy_vfx_frame_links WHERE frame_key_sha256 = ?1",
                    params![v2_value_string(frame, "base_frame_key_sha256")?],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?)),
                )
                .optional()?;
        let bloom: Option<(String, String, String, String, String, String, String, String, String, String)> =
            connection
                .query_row(
                    "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, base_frame_key_sha256, camera_object_sha256, camera_identity_sha256, render_profile_sha256, render_worker_build_cohort_sha256 FROM fictional_energy_vfx_bloom_frame_links WHERE bloom_key_sha256 = ?1",
                    params![v2_value_string(frame, "bloom_key_sha256")?],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?)),
                )
                .optional()?;
        let expected_profile = v2_value_string(value, "vfx_profile_object_sha256")?;
        let expected_camera = v2_value_string(value, "camera_object_sha256")?;
        let expected_camera_identity = v2_value_string(value, "camera_identity_sha256")?;
        let expected_render_profile = v2_value_string(value, "render_profile_sha256")?;
        let expected_cohort = v2_value_string(value, "render_worker_build_cohort_sha256")?;
        let base_matches = base.as_ref().is_some_and(|row| {
            row.0 == project
                && row.1 == appearance_delivery
                && row.2 == expected_profile
                && row.3 == appearance_candidate
                && row.4 == appearance_artifact
                && row.5 == expected_camera
                && row.6 == expected_camera_identity
                && row.7 == expected_render_profile
                && row.8 == expected_cohort
        });
        let bloom_matches = bloom.as_ref().is_some_and(|row| {
            row.0 == project
                && row.1 == appearance_delivery
                && row.2 == expected_profile
                && row.3 == appearance_candidate
                && row.4 == appearance_artifact
                && row.5 == v2_value_string(frame, "base_frame_key_sha256").unwrap_or_default()
                && row.6 == expected_camera
                && row.7 == expected_camera_identity
                && row.8 == expected_render_profile
                && row.9 == expected_cohort
        });
        if !base_matches || !bloom_matches {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_V2_FRAME_BINDING_MISMATCH",
                "V2 base/Bloom frame does not bind the appearance delivery exactly",
            ));
        }
    }
    Ok(())
}

fn field_value<'a>(value: &'a Value, field: &str) -> Result<&'a str, StoreError> {
    v2_value_string(value, field)
}

fn fictional_energy_vfx_animated_socket_particles_sequence_v2_reachable_hashes(
    connection: &Connection,
    value: &Value,
    receipt: Option<&str>,
) -> Result<Vec<String>, StoreError> {
    let receipt = match receipt {
        Some(hash) => hash.to_owned(),
        None => connection.query_row(
            "SELECT sequence_receipt_object_sha256 FROM fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_links WHERE sequence_key_sha256 = ?1",
            params![v2_value_string(value, "sequence_key_sha256")?],
            |row| row.get(0),
        )?,
    };
    let mut hashes = vec![
        receipt,
        v2_value_string(value, "geometry_delivery_manifest_object_sha256")?.to_owned(),
        v2_value_string(value, "geometry_artifact_sha256")?.to_owned(),
        v2_value_string(value, "appearance_delivery_manifest_object_sha256")?.to_owned(),
        v2_value_string(value, "appearance_artifact_sha256")?.to_owned(),
        v2_value_string(value, "material_surface_quality_report_object_sha256")?.to_owned(),
        v2_value_string(value, "animated_socket_anchor_set_object_sha256")?.to_owned(),
        v2_value_string(value, "appearance_anchor_set_object_sha256")?.to_owned(),
        v2_value_string(value, "projection_object_sha256")?.to_owned(),
        v2_value_string(value, "animated_artifact_sha256")?.to_owned(),
        v2_value_string(value, "animation_clip_object_sha256")?.to_owned(),
        v2_value_string(value, "animation_receipt_object_sha256")?.to_owned(),
        v2_value_string(value, "vfx_profile_object_sha256")?.to_owned(),
        v2_value_string(value, "camera_object_sha256")?.to_owned(),
    ];
    if let Some((artifact, receipt)) = connection
        .query_row(
            "SELECT derived_animated_socket_artifact_sha256, derived_animated_socket_receipt_object_sha256 FROM game_weapon_animated_glb_socket_transform_projection_v2_links WHERE projection_key_sha256 = ?1",
            params![v2_value_string(value, "projection_key_sha256")?],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?
    {
        hashes.extend([artifact, receipt]);
    }
    if let Some((artifact, receipt)) = connection
        .query_row(
            "SELECT derived_animated_socket_artifact_sha256, receipt_object_sha256 FROM game_weapon_animated_glb_socket_materialization_v2_links WHERE animated_socket_materialization_key_sha256 = ?1",
            params![v2_value_string(value, "animated_socket_materialization_key_sha256")?],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?
    {
        hashes.extend([artifact, receipt]);
    }
    for frame in v2_frames(value)? {
        hashes.extend([
            v2_value_string(frame, "render_set_object_sha256")?.to_owned(),
            v2_value_string(frame, "receipt_object_sha256")?.to_owned(),
            v2_value_string(frame, "particle_color_object_sha256")?.to_owned(),
            v2_value_string(frame, "particle_id_object_sha256")?.to_owned(),
            v2_value_string(frame, "particle_depth_object_sha256")?.to_owned(),
        ]);
    }
    hashes.sort();
    hashes.dedup();
    Ok(hashes)
}

fn trails_v2_frames(value: &Value) -> Result<Vec<&Value>, StoreError> {
    value
        .get("frames")
        .and_then(Value::as_array)
        .map(|frames| frames.iter().collect())
        .ok_or_else(|| v2_invalid("V2 trails sequence frames are missing"))
}

fn trails_v2_hash<'a>(value: &'a Value, field: &str) -> Result<&'a str, StoreError> {
    let hash = v2_value_string(value, field)?;
    if !is_sha256(hash) {
        return Err(v2_invalid(format!("V2 trails hash {field} is invalid")));
    }
    Ok(hash)
}

fn same_fictional_energy_vfx_animated_socket_trails_sequence_v2_value(
    left: &Value,
    right: &Value,
) -> bool {
    let left = v2_normalized_value(left);
    let right = v2_normalized_value(right);
    canonical_json_bytes(&left).ok() == canonical_json_bytes(&right).ok()
}

fn validate_fictional_energy_vfx_animated_socket_trails_sequence_v2_value(
    value: &Value,
) -> Result<(), StoreError> {
    if v2_value_string(value, "schema_version")?
        != "FictionalEnergyVfxAnimatedSocketTrailsSequence@2"
    {
        return Err(v2_invalid("V2 animated trails sequence schema is invalid"));
    }
    let key = trails_v2_hash(value, "sequence_key_sha256")?;
    if !is_opaque_id(v2_value_string(value, "project_id")?) {
        return Err(v2_invalid("V2 animated trails project identity is invalid"));
    }
    for field in [
        "geometry_candidate_state_sha256",
        "geometry_delivery_manifest_object_sha256",
        "geometry_artifact_sha256",
        "appearance_candidate_state_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
        "material_surface_quality_report_object_sha256",
        "material_surface_quality_canonical_sha256",
        "geometry_preservation_projection_sha256",
        "projection_key_sha256",
        "projection_object_sha256",
        "projection_canonical_sha256",
        "particle_sequence_key_sha256",
        "particle_sequence_canonical_sha256",
        "animated_socket_materialization_key_sha256",
        "animated_artifact_sha256",
        "animated_socket_anchor_set_object_sha256",
        "animated_socket_anchor_set_canonical_sha256",
        "appearance_anchor_set_object_sha256",
        "appearance_anchor_set_canonical_sha256",
        "anchor_binding_sha256",
        "animation_clip_object_sha256",
        "animation_clip_canonical_sha256",
        "animation_receipt_object_sha256",
        "animation_receipt_canonical_sha256",
        "vfx_profile_object_sha256",
        "vfx_profile_canonical_sha256",
        "socket_node_id_encoding_sha256",
        "socket_roles_sha256",
        "camera_object_sha256",
        "camera_identity_sha256",
        "render_profile_sha256",
        "render_worker_build_cohort_sha256",
        "sample_schedule_sha256",
        "input_sha256",
    ] {
        let _ = trails_v2_hash(value, field)?;
    }
    for field in [
        "geometry_candidate_id",
        "appearance_candidate_id",
        "material_surface_quality_id",
        "animation_clip_id",
    ] {
        if !is_opaque_id(v2_value_string(value, field)?) {
            return Err(v2_invalid(format!("V2 trails ID {field} is invalid")));
        }
    }
    if v2_value_string(value, "geometry_candidate_id")?
        == v2_value_string(value, "appearance_candidate_id")?
        || v2_value_string(value, "geometry_artifact_sha256")?
            == v2_value_string(value, "appearance_artifact_sha256")?
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_CANDIDATE_COLLISION",
            "V2 trails geometry and appearance bindings must be distinct",
        ));
    }
    let sample_count = v2_value_u64(value, "sample_count")?;
    let sample_ticks = value
        .get("sample_time_ticks")
        .and_then(Value::as_array)
        .ok_or_else(|| v2_invalid("V2 trails sample_time_ticks is missing"))?;
    if !(1..=15).contains(&sample_count)
        || sample_ticks.len() != sample_count as usize
        || sample_ticks.windows(2).any(|pair| {
            pair[0].as_u64().unwrap_or(u64::MAX) >= pair[1].as_u64().unwrap_or(u64::MAX)
        })
        || sample_ticks
            .iter()
            .any(|tick| tick.as_u64().is_none_or(|tick| tick > 1_000_000))
    {
        return Err(v2_invalid("V2 trails sample schedule is invalid"));
    }
    if v2_value_string(value, "frame_scope")?
        != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_FRAME_SCOPE
        || v2_value_string(value, "trails_sequence_policy")?
            != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_POLICY
        || v2_value_string(value, "history_policy")?
            != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_HISTORY_POLICY
        || v2_value_string(value, "history_pre_roll_policy")?
            != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_HISTORY_PREROLL_POLICY
        || v2_value_string(value, "anchor_binding_policy")?
            != "geometry-appearance-anchor-role-owner-trs-equivalent@1"
        || v2_value_string(value, "geometry_preservation_status")?
            != "source-output-renderable-geometry-byte-exact"
        || v2_value_string(value, "sequence_status")?
            != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_STATUS
        || v2_value_string(value, "quality_status")? != "structural_only"
        || v2_value_string(value, "visual_quality_status")? != "NOT_PROVEN"
        || v2_value_string(value, "commercial_fps_quality_status")? != "NOT_PROVEN"
        || v2_value_string(value, "human_review_status")? != "NOT_RUN"
        || v2_value_string(value, "commercial_engine_status")? != "NOT_RUN"
        || !v2_value_bool(value, "runtime_write_performed")?
        || !v2_value_bool(value, "restart_hash_verified")?
        || v2_value_bool(value, "candidate_confirmed")?
        || v2_value_bool(value, "version_created")?
        || v2_value_bool(value, "export_performed")?
        || v2_value_bool(value, "actual_engine_roundtrip")?
        || v2_value_bool(value, "production_stage_advanced")?
    {
        return Err(v2_invalid("V2 trails policy or status is invalid"));
    }
    if v2_value_u64(value, "trail_count")? != 2
        || value.get("trail_emitter_roles")
            != Some(&serde_json::json!(["muzzle-vfx", "energy-core-vfx"]))
    {
        return Err(v2_invalid("V2 trails emitter roles are invalid"));
    }
    let frames = trails_v2_frames(value)?;
    if frames.len() != sample_count as usize {
        return Err(v2_invalid(
            "V2 trails frame count differs from sample count",
        ));
    }
    for (ordinal, frame) in frames.iter().enumerate() {
        if v2_value_string(frame, "schema_version")?
            != "FictionalEnergyVfxAnimatedSocketTrailsSequenceFrame@2"
            || v2_value_u64(frame, "frame_index")? != ordinal as u64
            || v2_value_u64(frame, "sample_time_ticks")?
                != sample_ticks[ordinal].as_u64().unwrap_or(u64::MAX)
            || v2_value_u64(frame, "current_projection_frame_index")? != ordinal as u64 + 1
            || v2_value_u64(frame, "current_particle_frame_index")? != ordinal as u64 + 1
            || v2_value_u64(frame, "previous_projection_frame_index")? != ordinal as u64
            || v2_value_u64(frame, "previous_particle_frame_index")? != ordinal as u64
        {
            return Err(v2_invalid(
                "V2 trails frame order or source index is invalid",
            ));
        }
        for field in [
            "current_particle_key_sha256",
            "current_particle_frame_canonical_sha256",
            "current_projection_frame_canonical_sha256",
            "current_projection_socket_transform_inventory_sha256",
            "current_projection_socket_transform_readback_sha256",
            "previous_particle_sequence_frame_canonical_sha256",
            "previous_projection_frame_canonical_sha256",
            "previous_projection_socket_transform_inventory_sha256",
            "previous_projection_socket_transform_readback_sha256",
            "projection_sample_set_sha256",
            "particle_sequence_key_sha256",
            "base_frame_key_sha256",
            "bloom_key_sha256",
            "camera_object_sha256",
            "camera_identity_sha256",
            "render_profile_sha256",
            "render_worker_build_cohort_sha256",
            "trail_key_sha256",
            "trail_seed_sha256",
            "trail_inventory_sha256",
            "trail_id_encoding_sha256",
            "emitter_binding_sha256",
            "trail_color_object_sha256",
            "trail_id_object_sha256",
            "trail_depth_object_sha256",
            "render_set_object_sha256",
            "receipt_object_sha256",
        ] {
            if !is_sha256(v2_value_string(frame, field)?) {
                return Err(v2_invalid(format!(
                    "V2 trails frame hash {field} is invalid"
                )));
            }
        }
        if v2_value_string(frame, "history_origin")?
            != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_HISTORY_PREROLL_POLICY
            || v2_value_u64(frame, "trail_count")? != 2
            || frame.get("trail_emitter_roles")
                != Some(&serde_json::json!(["muzzle-vfx", "energy-core-vfx"]))
        {
            return Err(v2_invalid("V2 trails frame policy or roles are invalid"));
        }
        let history = frame
            .get("history_samples")
            .and_then(Value::as_array)
            .ok_or_else(|| v2_invalid("V2 trails history is missing"))?;
        let expected_history = (ordinal as u64 + 1).min(8) as usize;
        if history.len() != expected_history {
            return Err(v2_invalid("V2 trails history length is invalid"));
        }
        let first_history = ordinal as u64 + 1 - expected_history as u64;
        let mut previous_ordinal = None;
        for (history_ordinal, sample) in history.iter().enumerate() {
            if v2_value_u64(sample, "history_ordinal")? != history_ordinal as u64
                || previous_ordinal.is_some_and(|last| last + 1 != history_ordinal as u64)
            {
                return Err(v2_invalid("V2 trails history ordinal is invalid"));
            }
            previous_ordinal = Some(history_ordinal as u64);
            let expected_frame = first_history + history_ordinal as u64;
            if v2_value_u64(sample, "projection_frame_index")? != expected_frame
                || v2_value_u64(sample, "particle_frame_index")? != expected_frame
            {
                return Err(v2_invalid("V2 trails history frame index is invalid"));
            }
            for field in [
                "projection_key_sha256",
                "projection_frame_canonical_sha256",
                "projection_socket_transform_inventory_sha256",
                "projection_socket_transform_readback_sha256",
                "particle_sequence_key_sha256",
                "particle_key_sha256",
                "particle_frame_canonical_sha256",
            ] {
                if !is_sha256(v2_value_string(sample, field)?) {
                    return Err(v2_invalid(format!(
                        "V2 trails history hash {field} is invalid"
                    )));
                }
            }
            if v2_value_u64(sample, "sample_time_ticks")? > 1_000_000 {
                return Err(v2_invalid("V2 trails history sample time is invalid"));
            }
        }
        let trails = frame
            .get("trails")
            .and_then(Value::as_array)
            .ok_or_else(|| v2_invalid("V2 trails frame trails are missing"))?;
        if trails.len() != 2 {
            return Err(v2_invalid("V2 trails frame trail count is invalid"));
        }
        for (trail_index, trail) in trails.iter().enumerate() {
            let expected_role = if trail_index == 0 {
                "muzzle-vfx"
            } else {
                "energy-core-vfx"
            };
            if v2_value_string(trail, "emitter_role")? != expected_role
                || v2_value_u64(trail, "trail_id")? != if trail_index == 0 { 10000 } else { 20000 }
            {
                return Err(v2_invalid("V2 trail role or id is invalid"));
            }
            let points = trail
                .get("points")
                .and_then(Value::as_array)
                .ok_or_else(|| v2_invalid("V2 trail points are missing"))?;
            if !(2..=9).contains(&points.len()) {
                return Err(v2_invalid("V2 trail point count is invalid"));
            }
            for point in points {
                if v2_value_u64(point, "source_frame_index")? > 15
                    || v2_value_u64(point, "source_particle_frame_index")? > 15
                    || v2_value_u64(point, "source_particle_id")?
                        != if trail_index == 0 { 10000 } else { 20000 }
                    || v2_value_u64(point, "sample_time_ticks")? > 1_000_000
                    || point
                        .get("local_offset_micrometers")
                        .and_then(Value::as_array)
                        .is_none_or(|values| values.len() != 3)
                    || point
                        .get("world_position_micrometers")
                        .and_then(Value::as_array)
                        .is_none_or(|values| values.len() != 3)
                    || point
                        .get("depth_micrometers")
                        .and_then(Value::as_u64)
                        .is_none()
                {
                    return Err(v2_invalid("V2 trail point shape is invalid"));
                }
                if !is_sha256(v2_value_string(point, "source_particle_key_sha256")?) {
                    return Err(v2_invalid("V2 trail point particle binding is invalid"));
                }
            }
        }
        let mut frame_canonical = (*frame).clone();
        if let Some(object) = frame_canonical.as_object_mut() {
            object.insert("canonical_sha256".to_owned(), Value::String(String::new()));
        }
        if v2_value_string(frame, "canonical_sha256")? != canonical_json_hash(&frame_canonical)
            || v2_value_string(frame, "created_at")?.len() > 128
        {
            return Err(v2_invalid("V2 trails frame canonical binding is invalid"));
        }
    }
    if v2_value_string(value, "created_at")?.len() > 128 {
        return Err(v2_invalid("V2 trails created_at is invalid"));
    }
    if v2_value_string(value, "canonical_sha256")?
        != canonical_json_hash(&v2_canonical_value(value))
    {
        return Err(v2_invalid("V2 trails canonical binding is invalid"));
    }
    let _ = key;
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_trails_v2_receipt_bytes(
    bytes: &[u8],
    sequence: &Value,
    object: &CasObjectRecord,
) -> Result<(), StoreError> {
    if object.schema_version != "CasObject@1"
        || object.mime != GAME_ASSET_DELIVERY_JSON_MIME
        || object.kind != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_SEQUENCE_RECEIPT_KIND
        || object.size_bytes == 0
        || object.size_bytes > MAX_GAME_ASSET_DELIVERY_JSON_BYTES
        || object.size_bytes != bytes.len() as u64
        || sha256_hex(bytes) != object.sha256
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_RECEIPT_INVALID",
            "V2 animated trails sequence receipt metadata is invalid",
        ));
    }
    let receipt: Value = serde_json::from_slice(bytes).map_err(|error| {
        v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_RECEIPT_INVALID",
            &format!("V2 animated trails sequence receipt JSON is invalid: {error}"),
        )
    })?;
    if canonical_json_bytes(&receipt).map_err(|error| v2_invalid(error.to_string()))? != bytes {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_RECEIPT_CANONICAL_MISMATCH",
            "V2 animated trails sequence receipt is not canonical JSON",
        ));
    }
    if !same_fictional_energy_vfx_animated_socket_trails_sequence_v2_value(&receipt, sequence) {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_RECEIPT_BINDING_MISMATCH",
            "V2 animated trails sequence receipt differs from the sequence",
        ));
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_animated_socket_trails_v2_object(
    connection: &Connection,
    hash: &str,
    expected_mime: &str,
    expected_kind: &str,
    max_bytes: u64,
    role: &str,
) -> Result<(), StoreError> {
    let row: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![hash],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((size, mime, kind, reachability)) = row else {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_CAS_OBJECT_MISSING",
            &format!("V2 trails {role} CAS object is missing"),
        ));
    };
    if size <= 0
        || u64::try_from(size).unwrap_or(u64::MAX) > max_bytes
        || mime != expected_mime
        || kind != expected_kind
        || !matches!(reachability.as_str(), "temporary" | "reachable")
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_CAS_OBJECT_INVALID",
            &format!("V2 trails {role} CAS metadata is invalid"),
        ));
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_animated_socket_trails_v2_objects(
    connection: &Connection,
    value: &Value,
    receipt: &CasObjectRecord,
) -> Result<(), StoreError> {
    let json_max = MAX_GAME_ASSET_DELIVERY_JSON_BYTES;
    let glb_max = 64 * 1024 * 1024;
    for (field, kind, max, role) in [
        (
            "geometry_delivery_manifest_object_sha256",
            "game-asset-delivery-manifest",
            json_max,
            "geometry delivery",
        ),
        (
            "appearance_delivery_manifest_object_sha256",
            "game-asset-delivery-manifest",
            json_max,
            "appearance delivery",
        ),
        (
            "geometry_artifact_sha256",
            "geometry-glb",
            glb_max,
            "geometry artifact",
        ),
        (
            "appearance_artifact_sha256",
            "appearance-glb",
            glb_max,
            "appearance artifact",
        ),
        (
            "material_surface_quality_report_object_sha256",
            CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_KIND,
            json_max,
            "material surface quality report",
        ),
        (
            "animated_socket_anchor_set_object_sha256",
            GAME_WEAPON_ANCHOR_SET_KIND,
            json_max,
            "geometry AnchorSet",
        ),
        (
            "appearance_anchor_set_object_sha256",
            GAME_WEAPON_ANCHOR_SET_KIND,
            json_max,
            "appearance AnchorSet",
        ),
        (
            "projection_object_sha256",
            GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_KIND,
            MAX_GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_BYTES,
            "Projection@2",
        ),
        (
            "animated_artifact_sha256",
            GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZED_GLB_V2_KIND,
            64 * 1024 * 1024,
            "animated socket artifact",
        ),
        (
            "animation_clip_object_sha256",
            MECHANICAL_ANIMATION_CLIP_V2_KIND,
            MAX_MECHANICAL_ANIMATION_CLIP_V2_BYTES,
            "animation clip",
        ),
        (
            "animation_receipt_object_sha256",
            MECHANICAL_ANIMATION_GLB_V2_RECEIPT_KIND,
            MAX_MECHANICAL_ANIMATION_GLB_V2_RECEIPT_BYTES,
            "animation receipt",
        ),
        (
            "vfx_profile_object_sha256",
            FICTIONAL_ENERGY_VFX_PROFILE_KIND,
            json_max,
            "VFX profile",
        ),
        (
            "camera_object_sha256",
            FICTIONAL_ENERGY_VFX_CAMERA_KIND,
            json_max,
            "camera",
        ),
    ] {
        let mime = if field == "geometry_artifact_sha256"
            || field == "appearance_artifact_sha256"
            || field == "animated_artifact_sha256"
        {
            "model/gltf-binary"
        } else if field == "animation_clip_object_sha256" {
            MECHANICAL_ANIMATION_CLIP_V2_MIME
        } else if field == "animation_receipt_object_sha256" {
            MECHANICAL_ANIMATION_GLB_V2_RECEIPT_MIME
        } else {
            GAME_ASSET_DELIVERY_JSON_MIME
        };
        let result = ensure_fictional_energy_vfx_animated_socket_trails_v2_object(
            connection,
            trails_v2_hash(value, field)?,
            mime,
            kind,
            max,
            role,
        );
        if let Err(error) = result {
            if field == "appearance_artifact_sha256" {
                ensure_fictional_energy_vfx_animated_socket_trails_v2_object(
                    connection,
                    trails_v2_hash(value, field)?,
                    mime,
                    "appearance-v2-glb",
                    max,
                    role,
                )?;
            } else {
                return Err(error);
            }
        }
    }
    ensure_fictional_energy_vfx_animated_socket_trails_v2_object(
        connection,
        &receipt.sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_SEQUENCE_RECEIPT_KIND,
        json_max,
        "sequence receipt",
    )?;
    if receipt.schema_version != "CasObject@1"
        || receipt.mime != GAME_ASSET_DELIVERY_JSON_MIME
        || receipt.kind != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_SEQUENCE_RECEIPT_KIND
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_RECEIPT_INVALID",
            "V2 trails sequence receipt kind or mime is invalid",
        ));
    }
    for frame in trails_v2_frames(value)? {
        for (field, kind, mime, max, role) in [
            (
                "render_set_object_sha256",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_RENDER_SET_KIND,
                GAME_ASSET_DELIVERY_JSON_MIME,
                json_max,
                "trail frame render set",
            ),
            (
                "receipt_object_sha256",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_FRAME_RECEIPT_KIND,
                GAME_ASSET_DELIVERY_JSON_MIME,
                json_max,
                "trail frame receipt",
            ),
            (
                "trail_color_object_sha256",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_COLOR_KIND,
                "image/png",
                u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
                "trail color",
            ),
            (
                "trail_id_object_sha256",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_ID_KIND,
                "image/png",
                u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
                "trail ID",
            ),
            (
                "trail_depth_object_sha256",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_DEPTH_KIND,
                "image/png",
                u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
                "trail depth",
            ),
        ] {
            ensure_fictional_energy_vfx_animated_socket_trails_v2_object(
                connection,
                v2_value_string(frame, field)?,
                mime,
                kind,
                max,
                role,
            )?;
        }
    }
    Ok(())
}

fn validate_trails_v2_candidate_delivery_binding(
    connection: &Connection,
    value: &Value,
    candidate_field: &str,
    state_field: &str,
    delivery_field: &str,
    artifact_field: &str,
) -> Result<(), StoreError> {
    let project = v2_value_string(value, "project_id")?;
    let candidate = v2_value_string(value, candidate_field)?;
    let state = v2_value_string(value, state_field)?;
    let delivery = v2_value_string(value, delivery_field)?;
    let artifact = v2_value_string(value, artifact_field)?;
    let candidate_row: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, state, prepared_object_sha256 FROM candidates WHERE candidate_id = ?1",
            params![candidate],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if candidate_row.as_ref().map(|row| row.0.as_str()) != Some(project)
        || candidate_row.as_ref().map(|row| row.1.as_str()) != Some(state)
        || candidate_row.as_ref().map(|row| row.2.as_str()) != Some(artifact)
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_CANDIDATE_BINDING_MISMATCH",
            "V2 trails candidate does not bind project/state/artifact",
        ));
    }
    let delivery_row: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![delivery],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if delivery_row.as_ref().map(|row| row.0.as_str()) != Some(project)
        || delivery_row.as_ref().map(|row| row.1.as_str()) != Some(candidate)
        || delivery_row.as_ref().map(|row| row.2.as_str()) != Some(artifact)
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_DELIVERY_BINDING_MISMATCH",
            "V2 trails delivery does not bind project/candidate/artifact",
        ));
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_trails_v2_bindings(
    connection: &Connection,
    value: &Value,
) -> Result<(), StoreError> {
    validate_trails_v2_candidate_delivery_binding(
        connection,
        value,
        "geometry_candidate_id",
        "geometry_candidate_state_sha256",
        "geometry_delivery_manifest_object_sha256",
        "geometry_artifact_sha256",
    )?;
    validate_trails_v2_candidate_delivery_binding(
        connection,
        value,
        "appearance_candidate_id",
        "appearance_candidate_state_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
    )?;
    let project = v2_value_string(value, "project_id")?;
    let geometry_delivery = v2_value_string(value, "geometry_delivery_manifest_object_sha256")?;
    let appearance_delivery = v2_value_string(value, "appearance_delivery_manifest_object_sha256")?;
    let geometry_anchor = v2_value_string(value, "animated_socket_anchor_set_object_sha256")?;
    let appearance_anchor = v2_value_string(value, "appearance_anchor_set_object_sha256")?;
    let quality: Option<(String, String, String)> = connection
        .query_row(
            "SELECT payload_json, report_object_sha256, canonical_sha256 FROM candidate_material_surface_quality_links WHERE material_surface_quality_id = ?1",
            params![v2_value_string(value, "material_surface_quality_id")?],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    let Some((quality_payload, quality_report, quality_canonical)) = quality else {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_MATERIAL_SURFACE_MISSING",
            "V2 trails material-surface quality link is unavailable",
        ));
    };
    let quality: Value = serde_json::from_str(&quality_payload)
        .map_err(|error| v2_invalid(format!("V2 trails quality payload is invalid: {error}")))?;
    let quality_matches = quality.get("project_id").and_then(Value::as_str) == Some(project)
        && quality.get("source_candidate_id").and_then(Value::as_str)
            == Some(v2_value_string(value, "geometry_candidate_id")?)
        && quality
            .get("source_candidate_state_sha256")
            .and_then(Value::as_str)
            == Some(v2_value_string(value, "geometry_candidate_state_sha256")?)
        && quality
            .get("source_artifact_sha256")
            .and_then(Value::as_str)
            == Some(v2_value_string(value, "geometry_artifact_sha256")?)
        && quality.get("output_candidate_id").and_then(Value::as_str)
            == Some(v2_value_string(value, "appearance_candidate_id")?)
        && quality
            .get("output_candidate_state_sha256")
            .and_then(Value::as_str)
            == Some(v2_value_string(value, "appearance_candidate_state_sha256")?)
        && quality
            .get("output_artifact_sha256")
            .and_then(Value::as_str)
            == Some(v2_value_string(value, "appearance_artifact_sha256")?)
        && quality_report
            == v2_value_string(value, "material_surface_quality_report_object_sha256")?
        && quality_canonical
            == v2_value_string(value, "material_surface_quality_canonical_sha256")?
        && quality
            .get("geometry_preservation_projection_sha256")
            .and_then(Value::as_str)
            == Some(v2_value_string(
                value,
                "geometry_preservation_projection_sha256",
            )?)
        && quality
            .get("geometry_preservation_status")
            .and_then(Value::as_str)
            == Some(v2_value_string(value, "geometry_preservation_status")?)
        && quality.get("hard_gate_passed").and_then(Value::as_bool) == Some(true)
        && quality.get("validator_status").and_then(Value::as_str) == Some("passed");
    if !quality_matches {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_MATERIAL_SURFACE_BINDING_MISMATCH",
            "V2 trails material-surface quality does not bind both candidates exactly",
        ));
    }
    for (delivery, anchor, role) in [
        (geometry_delivery, geometry_anchor, "geometry AnchorSet"),
        (
            appearance_delivery,
            appearance_anchor,
            "appearance AnchorSet",
        ),
    ] {
        let row: Option<(String, String)> = connection
            .query_row(
                "SELECT project_id, anchor_set_object_sha256 FROM game_weapon_anchor_links WHERE delivery_manifest_object_sha256 = ?1",
                params![delivery],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()?;
        if row.as_ref().map(|row| row.0.as_str()) != Some(project)
            || row.as_ref().map(|row| row.1.as_str()) != Some(anchor)
        {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_ANCHOR_BINDING_MISMATCH",
                &format!("V2 trails {role} does not bind its delivery"),
            ));
        }
    }
    let projection: Option<String> = connection
        .query_row(
            "SELECT payload_json FROM game_weapon_animated_glb_socket_transform_projection_v2_links WHERE projection_key_sha256 = ?1",
            params![v2_value_string(value, "projection_key_sha256")?],
            |row| row.get(0),
        )
        .optional()?;
    let Some(projection_payload) = projection else {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PROJECTION_MISSING",
            "V2 trails requires Projection@2",
        ));
    };
    let projection: Value = serde_json::from_str(&projection_payload)
        .map_err(|error| v2_invalid(format!("V2 trails projection payload is invalid: {error}")))?;
    for (source, target) in [
        ("project_id", "project_id"),
        ("appearance_candidate_id", "appearance_candidate_id"),
        (
            "appearance_candidate_state_sha256",
            "appearance_candidate_state_sha256",
        ),
        (
            "appearance_delivery_manifest_object_sha256",
            "appearance_delivery_manifest_object_sha256",
        ),
        ("appearance_artifact_sha256", "appearance_artifact_sha256"),
        ("animation_clip_id", "animation_clip_id"),
        (
            "animation_clip_object_sha256",
            "animation_clip_object_sha256",
        ),
        (
            "animation_clip_canonical_sha256",
            "animation_clip_canonical_sha256",
        ),
        (
            "animation_receipt_object_sha256",
            "animation_receipt_object_sha256",
        ),
        (
            "animation_receipt_canonical_sha256",
            "animation_receipt_canonical_sha256",
        ),
        (
            "animated_socket_materialization_key_sha256",
            "animated_socket_materialization_key_sha256",
        ),
        ("animated_artifact_sha256", "animated_artifact_sha256"),
        (
            "anchor_set_object_sha256",
            "appearance_anchor_set_object_sha256",
        ),
        (
            "anchor_set_canonical_sha256",
            "appearance_anchor_set_canonical_sha256",
        ),
        (
            "socket_node_id_encoding_sha256",
            "socket_node_id_encoding_sha256",
        ),
        ("socket_roles_sha256", "socket_roles_sha256"),
        ("sample_schedule_sha256", "sample_schedule_sha256"),
        ("projection_object_sha256", "projection_object_sha256"),
        ("canonical_sha256", "projection_canonical_sha256"),
    ] {
        if projection.get(source) != value.get(target) {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PROJECTION_BINDING_MISMATCH",
                &format!("V2 trails Projection@2 field {source} differs"),
            ));
        }
    }
    let particle_payload: Option<String> = connection
        .query_row(
            "SELECT payload_json FROM fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_links WHERE sequence_key_sha256 = ?1",
            params![v2_value_string(value, "particle_sequence_key_sha256")?],
            |row| row.get(0),
        )
        .optional()?;
    let Some(particle_payload) = particle_payload else {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PARTICLES_MISSING",
            "V2 trails requires projection-aware Particles@2",
        ));
    };
    let particle: Value = serde_json::from_str(&particle_payload)
        .map_err(|error| v2_invalid(format!("V2 trails particle payload is invalid: {error}")))?;
    validate_fictional_energy_vfx_animated_socket_particles_sequence_v2_value(&particle)?;
    for field in [
        "project_id",
        "geometry_candidate_id",
        "geometry_candidate_state_sha256",
        "geometry_delivery_manifest_object_sha256",
        "geometry_artifact_sha256",
        "appearance_candidate_id",
        "appearance_candidate_state_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
        "material_surface_quality_id",
        "material_surface_quality_report_object_sha256",
        "material_surface_quality_canonical_sha256",
        "geometry_preservation_projection_sha256",
        "geometry_preservation_status",
        "projection_key_sha256",
        "projection_object_sha256",
        "projection_canonical_sha256",
        "animated_socket_materialization_key_sha256",
        "animated_artifact_sha256",
        "animated_socket_anchor_set_object_sha256",
        "animated_socket_anchor_set_canonical_sha256",
        "appearance_anchor_set_object_sha256",
        "appearance_anchor_set_canonical_sha256",
        "anchor_binding_policy",
        "anchor_binding_sha256",
        "animation_clip_id",
        "animation_clip_object_sha256",
        "animation_clip_canonical_sha256",
        "animation_receipt_object_sha256",
        "animation_receipt_canonical_sha256",
        "vfx_profile_object_sha256",
        "vfx_profile_canonical_sha256",
        "socket_node_id_encoding_sha256",
        "socket_roles_sha256",
        "camera_object_sha256",
        "camera_identity_sha256",
        "render_profile_sha256",
        "render_worker_build_cohort_sha256",
        "sample_schedule_sha256",
    ] {
        if particle.get(field) != value.get(field) {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PARTICLES_BINDING_MISMATCH",
                &format!("V2 trails Particles@2 field {field} differs"),
            ));
        }
    }
    let particle_ticks = particle
        .get("sample_time_ticks")
        .and_then(Value::as_array)
        .ok_or_else(|| v2_invalid("V2 particle sample ticks are missing"))?;
    let projection_ticks = projection
        .get("sample_time_ticks")
        .and_then(Value::as_array)
        .ok_or_else(|| v2_invalid("V2 projection sample ticks are missing"))?;
    let trails_ticks = value
        .get("sample_time_ticks")
        .and_then(Value::as_array)
        .ok_or_else(|| v2_invalid("V2 trails sample ticks are missing"))?;
    for (index, tick) in trails_ticks.iter().enumerate() {
        let source_index = index + 1;
        if particle_ticks.get(source_index) != Some(tick)
            || projection_ticks.get(source_index) != Some(tick)
        {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_SAMPLE_BINDING_MISMATCH",
                "V2 trails output samples do not equal Projection@2/Particles@2 samples",
            ));
        }
    }
    for frame in trails_v2_frames(value)? {
        let frame_index = v2_value_u64(frame, "frame_index")?;
        let current_index = v2_value_u64(frame, "current_projection_frame_index")?;
        let previous_index = v2_value_u64(frame, "previous_projection_frame_index")?;
        let projection_frame = |index: u64| -> Result<
            Option<(u64, String, String, String, String)>,
            StoreError,
        > {
            connection
                .query_row(
                    "SELECT sample_time_ticks, projection_frame_canonical_sha256, socket_transform_inventory_sha256, socket_transform_readback_sha256, canonical_sha256 FROM game_weapon_animated_glb_socket_transform_projection_v2_frames WHERE projection_key_sha256 = ?1 AND frame_index = ?2",
                    params![v2_value_string(value, "projection_key_sha256")?, index],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
                )
                .optional()
                .map_err(StoreError::Sqlite)
        };
        let particle_frame =
            |index: u64| -> Result<Option<(u64, String, String, String)>, StoreError> {
                connection
                .query_row(
                    "SELECT sample_time_ticks, particle_key_sha256, canonical_sha256, projection_frame_canonical_sha256 FROM fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_frames WHERE sequence_key_sha256 = ?1 AND frame_index = ?2",
                    params![v2_value_string(value, "particle_sequence_key_sha256")?, index],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
                )
                .optional()
                .map_err(StoreError::Sqlite)
            };
        let Some((
            projection_tick,
            projection_canonical,
            projection_inventory,
            projection_readback,
            _,
        )) = projection_frame(current_index)?
        else {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PROJECTION_FRAME_MISSING",
                "V2 trails current Projection@2 frame is missing",
            ));
        };
        let Some((particle_tick, particle_key, particle_canonical, _)) =
            particle_frame(current_index)?
        else {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PARTICLE_FRAME_MISSING",
                "V2 trails current Particles@2 frame is missing",
            ));
        };
        if projection_tick != v2_value_u64(frame, "sample_time_ticks")?
            || particle_tick != projection_tick
            || projection_canonical
                != v2_value_string(frame, "current_projection_frame_canonical_sha256")?
            || projection_inventory
                != v2_value_string(
                    frame,
                    "current_projection_socket_transform_inventory_sha256",
                )?
            || projection_readback
                != v2_value_string(frame, "current_projection_socket_transform_readback_sha256")?
            || particle_key != v2_value_string(frame, "current_particle_key_sha256")?
            || particle_canonical
                != v2_value_string(frame, "current_particle_frame_canonical_sha256")?
        {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_FRAME_BINDING_MISMATCH",
                "V2 trails current projection/particle frame differs",
            ));
        }
        let Some((
            _,
            previous_projection_canonical,
            previous_projection_inventory,
            previous_projection_readback,
            _,
        )) = projection_frame(previous_index)?
        else {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PROJECTION_PREROLL_MISSING",
                "V2 trails previous Projection@2 frame is missing",
            ));
        };
        let Some((_, _, previous_particle_canonical, _)) =
            particle_frame(v2_value_u64(frame, "previous_particle_frame_index")?)?
        else {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PARTICLE_PREROLL_MISSING",
                "V2 trails previous Particles@2 frame is missing",
            ));
        };
        if previous_projection_canonical
            != v2_value_string(frame, "previous_projection_frame_canonical_sha256")?
            || previous_projection_inventory
                != v2_value_string(
                    frame,
                    "previous_projection_socket_transform_inventory_sha256",
                )?
            || previous_projection_readback
                != v2_value_string(
                    frame,
                    "previous_projection_socket_transform_readback_sha256",
                )?
            || previous_particle_canonical
                != v2_value_string(frame, "previous_particle_sequence_frame_canonical_sha256")?
        {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PREVIOUS_FRAME_BINDING_MISMATCH",
                "V2 trails previous projection/particle frame differs",
            ));
        }
        let base: Option<(String, String, String, String, String, String, String, String, String)> = connection
            .query_row(
                "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, camera_object_sha256, camera_identity_sha256, render_profile_sha256, render_worker_build_cohort_sha256 FROM fictional_energy_vfx_frame_links WHERE frame_key_sha256 = ?1",
                params![v2_value_string(frame, "base_frame_key_sha256")?],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?)),
            )
            .optional()?;
        let bloom: Option<(String, String, String, String, String, String, String, String, String, String)> = connection
            .query_row(
                "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, base_frame_key_sha256, camera_object_sha256, camera_identity_sha256, render_profile_sha256, render_worker_build_cohort_sha256 FROM fictional_energy_vfx_bloom_frame_links WHERE bloom_key_sha256 = ?1",
                params![v2_value_string(frame, "bloom_key_sha256")?],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?)),
            )
            .optional()?;
        let expected = (
            project,
            appearance_delivery,
            v2_value_string(value, "vfx_profile_object_sha256")?,
            v2_value_string(value, "appearance_candidate_id")?,
            v2_value_string(value, "appearance_artifact_sha256")?,
            v2_value_string(value, "camera_object_sha256")?,
            v2_value_string(value, "camera_identity_sha256")?,
            v2_value_string(value, "render_profile_sha256")?,
            v2_value_string(value, "render_worker_build_cohort_sha256")?,
        );
        if !base.as_ref().is_some_and(|row| {
            row.0 == expected.0
                && row.1 == expected.1
                && row.2 == expected.2
                && row.3 == expected.3
                && row.4 == expected.4
                && row.5 == expected.5
                && row.6 == expected.6
                && row.7 == expected.7
                && row.8 == expected.8
        }) || !bloom.as_ref().is_some_and(|row| {
            row.0 == expected.0
                && row.1 == expected.1
                && row.2 == expected.2
                && row.3 == expected.3
                && row.4 == expected.4
                && row.6 == expected.5
                && row.7 == expected.6
                && row.8 == expected.7
                && row.9 == expected.8
        }) || bloom.as_ref().map(|row| row.5.as_str())
            != Some(v2_value_string(frame, "base_frame_key_sha256")?)
        {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_BASE_BLOOM_BINDING_MISMATCH",
                "V2 trails base/Bloom frame does not bind appearance source",
            ));
        }
        let history = frame
            .get("history_samples")
            .and_then(Value::as_array)
            .ok_or_else(|| v2_invalid("V2 trails frame history is missing"))?;
        for sample in history {
            if v2_value_string(sample, "projection_key_sha256")?
                != v2_value_string(value, "projection_key_sha256")?
                || v2_value_string(sample, "particle_sequence_key_sha256")?
                    != v2_value_string(value, "particle_sequence_key_sha256")?
            {
                return Err(v2_binding_mismatch(
                    "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_HISTORY_BINDING_MISMATCH",
                    "V2 trails history retargets a Projection@2 or Particles@2 parent",
                ));
            }
            let history_projection =
                projection_frame(v2_value_u64(sample, "projection_frame_index")?)?.ok_or_else(
                    || {
                        v2_binding_mismatch(
                            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_HISTORY_FRAME_MISSING",
                            "V2 trails history Projection@2 frame is missing",
                        )
                    },
                )?;
            let history_particle = particle_frame(v2_value_u64(sample, "particle_frame_index")?)?
                .ok_or_else(|| {
                v2_binding_mismatch(
                    "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_HISTORY_FRAME_MISSING",
                    "V2 trails history Particles@2 frame is missing",
                )
            })?;
            if history_projection.0 != v2_value_u64(sample, "sample_time_ticks")?
                || history_projection.1
                    != v2_value_string(sample, "projection_frame_canonical_sha256")?
                || history_projection.2
                    != v2_value_string(sample, "projection_socket_transform_inventory_sha256")?
                || history_projection.3
                    != v2_value_string(sample, "projection_socket_transform_readback_sha256")?
                || history_particle.1 != v2_value_string(sample, "particle_key_sha256")?
                || history_particle.2 != v2_value_string(sample, "particle_frame_canonical_sha256")?
            {
                return Err(v2_binding_mismatch(
                    "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_HISTORY_FRAME_BINDING_MISMATCH",
                    "V2 trails history frame readback differs from its parent",
                ));
            }
        }
        let _ = frame_index;
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_trails_v2_parent_row(
    connection: &Connection,
    value: &Value,
    receipt_sha256: &str,
) -> Result<(), StoreError> {
    let key = trails_v2_hash(value, "sequence_key_sha256")?;
    let row: Option<(String, String, String, String, String)> = connection
        .query_row(
            "SELECT payload_json, sequence_receipt_object_sha256, sample_time_ticks_json, trail_emitter_roles_json, canonical_sha256 FROM fictional_energy_vfx_animated_socket_trails_v2_projection_sequence_links WHERE sequence_key_sha256 = ?1",
            params![key],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .optional()?;
    let Some((payload_json, stored_receipt, ticks_json, roles_json, canonical)) = row else {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PARENT_ROW_MISSING",
            "V2 trails parent row is missing",
        ));
    };
    let stored: Value = serde_json::from_str(&payload_json).map_err(|error| {
        v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PARENT_ROW_INVALID",
            &format!("V2 trails parent payload is invalid: {error}"),
        )
    })?;
    if stored_receipt != receipt_sha256
        || !same_fictional_energy_vfx_animated_socket_trails_sequence_v2_value(&stored, value)
        || ticks_json
            != canonical_json_string(
                value
                    .get("sample_time_ticks")
                    .ok_or_else(|| v2_invalid("V2 trails sample ticks missing"))?,
            )?
        || roles_json
            != canonical_json_string(
                value
                    .get("trail_emitter_roles")
                    .ok_or_else(|| v2_invalid("V2 trails roles missing"))?,
            )?
        || canonical != v2_value_string(value, "canonical_sha256")?
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_PARENT_ROW_MISMATCH",
            "V2 trails parent scalar/payload/receipt differs",
        ));
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_trails_v2_child_rows(
    connection: &Connection,
    value: &Value,
) -> Result<(), StoreError> {
    let key = trails_v2_hash(value, "sequence_key_sha256")?;
    let expected = trails_v2_frames(value)?;
    let mut statement = connection.prepare(
        "SELECT payload_json FROM fictional_energy_vfx_animated_socket_trails_v2_projection_sequence_frames WHERE sequence_key_sha256 = ?1 ORDER BY frame_index ASC",
    )?;
    let rows = statement.query_map(params![key], |row| row.get::<_, String>(0))?;
    let actual = rows.collect::<Result<Vec<_>, _>>()?;
    if actual.len() != expected.len()
        || actual
            .iter()
            .zip(expected.iter())
            .any(|(stored, expected)| {
                serde_json::from_str::<Value>(stored)
                    .ok()
                    .is_none_or(|stored| {
                        !same_fictional_energy_vfx_animated_socket_trails_sequence_v2_value(
                            &stored, expected,
                        )
                    })
            })
    {
        return Err(v2_binding_mismatch(
            "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_FRAME_ROW_MISMATCH",
            "V2 trails child rows differ from payload frames",
        ));
    }
    for frame in expected {
        let frame_index = v2_value_u64(frame, "frame_index")?;
        let stored_history: Vec<(u64, String, u64, String, String, String, String, u64, String, String, u64)> = connection
            .prepare(
                "SELECT history_ordinal, projection_key_sha256, projection_frame_index, projection_frame_canonical_sha256, projection_socket_transform_inventory_sha256, projection_socket_transform_readback_sha256, particle_sequence_key_sha256, particle_frame_index, particle_key_sha256, particle_frame_canonical_sha256, sample_time_ticks FROM fictional_energy_vfx_animated_socket_trails_v2_projection_sequence_frame_history WHERE sequence_key_sha256 = ?1 AND frame_index = ?2 ORDER BY history_ordinal ASC",
            )?
            .query_map(params![key, frame_index], |row| {
                Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?, row.get(10)?))
            })?
            .collect::<Result<Vec<_>, _>>()?;
        let history = frame
            .get("history_samples")
            .and_then(Value::as_array)
            .ok_or_else(|| v2_invalid("V2 trails frame history is missing"))?;
        if stored_history.len() != history.len()
            || stored_history
                .iter()
                .zip(history.iter())
                .any(|(stored, expected)| {
                    stored.0 != v2_value_u64(expected, "history_ordinal").unwrap_or(u64::MAX)
                        || stored.1
                            != v2_value_string(expected, "projection_key_sha256")
                                .unwrap_or_default()
                        || stored.2
                            != v2_value_u64(expected, "projection_frame_index").unwrap_or(u64::MAX)
                        || stored.3
                            != v2_value_string(expected, "projection_frame_canonical_sha256")
                                .unwrap_or_default()
                        || stored.4
                            != v2_value_string(
                                expected,
                                "projection_socket_transform_inventory_sha256",
                            )
                            .unwrap_or_default()
                        || stored.5
                            != v2_value_string(
                                expected,
                                "projection_socket_transform_readback_sha256",
                            )
                            .unwrap_or_default()
                        || stored.6
                            != v2_value_string(expected, "particle_sequence_key_sha256")
                                .unwrap_or_default()
                        || stored.7
                            != v2_value_u64(expected, "particle_frame_index").unwrap_or(u64::MAX)
                        || stored.8
                            != v2_value_string(expected, "particle_key_sha256").unwrap_or_default()
                        || stored.9
                            != v2_value_string(expected, "particle_frame_canonical_sha256")
                                .unwrap_or_default()
                        || stored.10
                            != v2_value_u64(expected, "sample_time_ticks").unwrap_or(u64::MAX)
                })
        {
            return Err(v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_V2_HISTORY_ROW_MISMATCH",
                "V2 trails history rows differ from payload",
            ));
        }
    }
    Ok(())
}

fn fictional_energy_vfx_animated_socket_trails_v2_reachable_hashes(
    connection: &Connection,
    value: &Value,
    receipt: &str,
) -> Result<Vec<String>, StoreError> {
    let mut hashes = vec![receipt.to_owned()];
    for field in [
        "geometry_delivery_manifest_object_sha256",
        "geometry_artifact_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
        "material_surface_quality_report_object_sha256",
        "animated_socket_anchor_set_object_sha256",
        "appearance_anchor_set_object_sha256",
        "projection_object_sha256",
        "animated_artifact_sha256",
        "animation_clip_object_sha256",
        "animation_receipt_object_sha256",
        "vfx_profile_object_sha256",
        "camera_object_sha256",
    ] {
        hashes.push(trails_v2_hash(value, field)?.to_owned());
    }
    if let Some((artifact, receipt)) = connection
        .query_row(
            "SELECT derived_animated_socket_artifact_sha256, derived_animated_socket_receipt_object_sha256 FROM game_weapon_animated_glb_socket_transform_projection_v2_links WHERE projection_key_sha256 = ?1",
            params![trails_v2_hash(value, "projection_key_sha256")?],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?
    {
        hashes.extend([artifact, receipt]);
    }
    if let Some((artifact, receipt)) = connection
        .query_row(
            "SELECT derived_animated_socket_artifact_sha256, receipt_object_sha256 FROM game_weapon_animated_glb_socket_materialization_v2_links WHERE animated_socket_materialization_key_sha256 = ?1",
            params![trails_v2_hash(value, "animated_socket_materialization_key_sha256")?],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?
    {
        hashes.extend([artifact, receipt]);
    }
    if let Some((particle_receipt, particle_payload)) = connection
        .query_row(
            "SELECT sequence_receipt_object_sha256, payload_json FROM fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_links WHERE sequence_key_sha256 = ?1",
            params![trails_v2_hash(value, "particle_sequence_key_sha256")?],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
        )
        .optional()?
    {
        hashes.push(particle_receipt);
        if let Ok(particle) = serde_json::from_str::<Value>(&particle_payload) {
            for frame in v2_frames(&particle)? {
                for field in [
                    "render_set_object_sha256",
                    "receipt_object_sha256",
                    "particle_color_object_sha256",
                    "particle_id_object_sha256",
                    "particle_depth_object_sha256",
                ] {
                    if let Ok(hash) = v2_value_string(frame, field) {
                        hashes.push(hash.to_owned());
                    }
                }
            }
        }
    }
    for frame in trails_v2_frames(value)? {
        for field in [
            "render_set_object_sha256",
            "receipt_object_sha256",
            "trail_color_object_sha256",
            "trail_id_object_sha256",
            "trail_depth_object_sha256",
        ] {
            hashes.push(v2_value_string(frame, field)?.to_owned());
        }
        if let Some((base_hashes, bloom_hashes)) = connection
            .query_row(
                "SELECT f.render_set_object_sha256 || ',' || f.receipt_object_sha256 || ',' || f.beauty_object_sha256 || ',' || f.silhouette_object_sha256 || ',' || f.depth_object_sha256 || ',' || f.normal_object_sha256 || ',' || f.ao_object_sha256 || ',' || f.part_id_object_sha256 || ',' || f.material_id_object_sha256 || ',' || f.wireframe_object_sha256 || ',' || f.uv_stretch_object_sha256, b.render_set_object_sha256 || ',' || b.receipt_object_sha256 || ',' || b.source_object_sha256 || ',' || b.contribution_object_sha256 FROM fictional_energy_vfx_frame_links f JOIN fictional_energy_vfx_bloom_frame_links b ON b.bloom_key_sha256 = ?2 WHERE f.frame_key_sha256 = ?1",
                params![v2_value_string(frame, "base_frame_key_sha256")?, v2_value_string(frame, "bloom_key_sha256")?],
                |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
            )
            .optional()?
        {
            hashes.extend(base_hashes.split(',').map(str::to_owned));
            hashes.extend(bloom_hashes.split(',').map(str::to_owned));
        }
    }
    hashes.sort();
    hashes.dedup();
    Ok(hashes)
}

