#[derive(Debug, thiserror::Error)]
pub enum StoreError {
    #[error("SQLite error: {0}")]
    Sqlite(#[from] rusqlite::Error),
    #[error("CAS error: {0}")]
    Cas(#[from] CasError),
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("invalid runtime data: {0}")]
    InvalidData(String),
    #[error("{code}: {message}")]
    Contract { code: String, message: String },
    #[error("database backup is unavailable for an in-memory store")]
    BackupUnavailable,
    #[error("database migration version is unsupported")]
    MigrationVersionUnsupported,
    #[error("legacy database is not a ForgeCAD Runtime V1 database")]
    LegacyDatabaseRejected,
    #[error("store mutex is poisoned")]
    LockPoisoned,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum GeometryPrepareSingleFlightOutcome {
    Committed(String),
    Failed(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct GeometryPrepareSingleFlightIdentity {
    project_id: String,
    tool: String,
    request_sha256: String,
}

#[derive(Debug)]
struct GeometryPrepareSingleFlightState {
    outcome: Option<GeometryPrepareSingleFlightOutcome>,
}

#[derive(Debug)]
struct GeometryPrepareSingleFlight {
    identity: GeometryPrepareSingleFlightIdentity,
    state: Mutex<GeometryPrepareSingleFlightState>,
    condition: Condvar,
}

pub struct GeometryPrepareSingleFlightGuard {
    key: String,
    flight: Arc<GeometryPrepareSingleFlight>,
    flights: Arc<Mutex<HashMap<String, Arc<GeometryPrepareSingleFlight>>>>,
    owner: bool,
}

impl GeometryPrepareSingleFlightGuard {
    pub fn is_owner(&self) -> bool {
        self.owner
    }

    fn complete_best_effort(&self, outcome: GeometryPrepareSingleFlightOutcome) {
        if !self.owner {
            return;
        }
        if let Ok(mut state) = self.flight.state.lock() {
            if state.outcome.is_none() {
                state.outcome = Some(outcome);
                self.flight.condition.notify_all();
            }
        }
        if let Ok(mut flights) = self.flights.lock() {
            if flights
                .get(&self.key)
                .is_some_and(|flight| Arc::ptr_eq(flight, &self.flight))
            {
                flights.remove(&self.key);
            }
        }
    }
}

impl Drop for GeometryPrepareSingleFlightGuard {
    fn drop(&mut self) {
        // Every owner must wake waiters even when an early Runtime return or a
        // panic bypasses the normal exact-prepare completion branch.  A
        // dropped owner is retryable and never creates a durable idempotency
        // row.
        self.complete_best_effort(GeometryPrepareSingleFlightOutcome::Failed(
            "GEOMETRY_PREPARE_SINGLE_FLIGHT_OWNER_DROPPED".to_owned(),
        ));
    }
}

#[derive(Debug)]
pub struct CasReservation {
    token: String,
    reservations: Arc<Mutex<HashMap<String, HashSet<String>>>>,
}

impl Drop for CasReservation {
    fn drop(&mut self) {
        if let Ok(mut reservations) = self.reservations.lock() {
            reservations.retain(|_, owners| {
                owners.remove(&self.token);
                !owners.is_empty()
            });
        }
    }
}

#[derive(Clone)]
pub struct Store {
    connection: Arc<Mutex<Connection>>,
    cas: CasStore,
    cas_mutation_lock: Arc<Mutex<()>>,
    geometry_prepare_flights: Arc<Mutex<HashMap<String, Arc<GeometryPrepareSingleFlight>>>>,
    cas_reservations: Arc<Mutex<HashMap<String, HashSet<String>>>>,
    database_path: Option<PathBuf>,
}

