    /// Read and independently revalidate one material-surface quality bridge.
    /// This is intentionally read-only: it never repairs reachability and
    /// never advances the production-stage head.
    pub fn get_candidate_material_surface_quality(
        &self,
        material_surface_quality_id: &str,
    ) -> Result<Option<CandidateMaterialSurfaceQualityRecord>, StoreError> {
        if !is_opaque_id(material_surface_quality_id) {
            return Err(StoreError::InvalidData(
                "candidate material-surface quality id is invalid".to_owned(),
            ));
        }
        let connection = self.lock_connection()?;
        let stored: Option<(CandidateMaterialSurfaceQualityRecord, String)> = connection
            .query_row(
                "SELECT payload_json, report_object_sha256 FROM candidate_material_surface_quality_links WHERE material_surface_quality_id = ?1",
                params![material_surface_quality_id],
                |row| {
                    let payload: String = row.get(0)?;
                    let record = serde_json::from_str::<CandidateMaterialSurfaceQualityRecord>(&payload)
                        .map_err(|error| rusqlite::Error::FromSqlConversionFailure(
                            0,
                            rusqlite::types::Type::Text,
                            Box::new(error),
                        ))?;
                    Ok((record, row.get(1)?))
                },
            )
            .optional()?;
        let Some((quality, report_sha256)) = stored else {
            return Ok(None);
        };
        validate_candidate_material_surface_quality(&quality)?;
        ensure_candidate_material_surface_quality_row_binding(
            &connection,
            material_surface_quality_id,
            &quality,
            &report_sha256,
        )?;
        let report_object =
            read_candidate_material_surface_quality_report_object(&connection, &report_sha256)?;
        ensure_candidate_material_surface_quality_bindings_in_transaction(
            &connection,
            &quality,
            &report_object,
        )?;
        let hashes = candidate_material_surface_quality_reachable_hashes(
            &connection,
            &quality,
            &report_sha256,
        )?;
        drop(connection);
        validate_candidate_material_surface_quality_source_cas(self, &quality)?;
        for hash in hashes {
            self.cas
                .read_verified_bounded(
                    &hash,
                    MAX_CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_BYTES.max(64 * 1024 * 1024),
                )
                .map_err(StoreError::Cas)?;
        }
        validate_candidate_material_surface_quality_report_bytes(
            &self
                .cas
                .read_verified_bounded(
                    &report_sha256,
                    MAX_CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_BYTES,
                )
                .map_err(StoreError::Cas)?,
            &quality,
        )?;
        Ok(Some(quality))
    }

