    pub fn get_fictional_energy_vfx_animated_socket_trails_bloom_sequence_v2(
        &self,
        sequence_key_sha256: &str,
    ) -> Result<Option<FictionalEnergyVfxAnimatedSocketTrailsBloomSequenceV2>, StoreError> {
        if !is_sha256(sequence_key_sha256) {
            return Err(StoreError::InvalidData(
                "V2 animated TrailsBloom sequence key is invalid".to_owned(),
            ));
        }
        let connection = self.lock_connection()?;
        let row: Option<(String, String)> = connection
            .query_row(
                "SELECT payload_json, sequence_receipt_object_sha256 FROM fictional_energy_vfx_animated_socket_trails_bloom_v2_projection_sequence_links WHERE sequence_key_sha256 = ?1",
                params![sequence_key_sha256],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()?;
        let Some((payload_json, receipt_sha256)) = row else {
            return Ok(None);
        };
        let value: Value = serde_json::from_str(&payload_json).map_err(|error| {
            v2_binding_mismatch(
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_BLOOM_V2_CORRUPT",
                &format!("stored V2 TrailsBloom sequence is invalid: {error}"),
            )
        })?;
        validate_fictional_energy_vfx_animated_socket_trails_bloom_sequence_v2_value(&value)?;
        validate_fictional_energy_vfx_animated_socket_trails_bloom_v2_bindings(
            &connection,
            &value,
        )?;
        validate_fictional_energy_vfx_animated_socket_trails_bloom_v2_parent_columns(
            &connection,
            &value,
        )?;
        validate_fictional_energy_vfx_animated_socket_trails_bloom_v2_child_rows(
            &connection,
            &value,
        )?;
        let receipt = cas_object_record_for_connection(&connection, &receipt_sha256)?;
        ensure_fictional_energy_vfx_animated_socket_trails_bloom_v2_objects(
            &connection,
            &value,
            &receipt,
        )?;
        let hashes = fictional_energy_vfx_animated_socket_trails_bloom_v2_reachable_hashes(
            &connection,
            &value,
            &receipt_sha256,
        )?;
        drop(connection);
        for hash in hashes {
            self.cas
                .read_verified_bounded(&hash, 64 * 1024 * 1024)
                .map_err(StoreError::Cas)?;
        }
        let receipt_bytes = self
            .cas
            .read_verified_bounded(&receipt_sha256, MAX_GAME_ASSET_DELIVERY_JSON_BYTES)
            .map_err(StoreError::Cas)?;
        validate_fictional_energy_vfx_animated_socket_trails_bloom_v2_receipt_bytes(
            &receipt_bytes,
            &value,
            &receipt,
        )?;
        serde_json::from_value(value)
            .map(Some)
            .map_err(|error| StoreError::InvalidData(error.to_string()))
    }

