    /// Persist one immutable FPS-FORM-04 structural form-quality receipt.
    /// CrossViewEvidenceBundle@1 remains the authoritative owner of the
    /// per-view RenderSet/ComparisonReport/QualityReport objects; this link
    /// stores exact child projections so later mutable compatibility-index
    /// upserts cannot retarget a historical quality record.
    pub fn record_production_weapon_form_quality(
        &self,
        quality: &ProductionWeaponFormQualityRecord,
        receipt_object: &CasObjectRecord,
    ) -> Result<ProductionWeaponFormQualityRecord, StoreError> {
        self.record_production_weapon_form_quality_with_replay(quality, receipt_object)
            .map(|(record, _replayed)| record)
    }

    pub fn record_production_weapon_form_quality_with_replay(
        &self,
        quality: &ProductionWeaponFormQualityRecord,
        receipt_object: &CasObjectRecord,
    ) -> Result<(ProductionWeaponFormQualityRecord, bool), StoreError> {
        let mut normalized = quality.clone();
        if !normalized.receipt_object_sha256.is_empty()
            && normalized.receipt_object_sha256 != receipt_object.sha256
        {
            return Err(StoreError::Contract {
                code: "PRODUCTION_WEAPON_FORM_QUALITY_RECEIPT_BINDING_MISMATCH".to_owned(),
                message: "form quality receipt hash differs from the supplied CAS object"
                    .to_owned(),
            });
        }
        normalized.receipt_object_sha256 = receipt_object.sha256.clone();
        validate_production_weapon_form_quality(&normalized)?;
        let payload_json = production_weapon_form_quality_payload_json(&normalized)?;
        ensure_production_weapon_form_quality_receipt(&self.cas, receipt_object, &payload_json)?;

        let mut connection = self.lock_connection()?;
        let transaction = connection.transaction()?;
        let result = record_production_weapon_form_quality_in_transaction(
            &transaction,
            &self.cas,
            &normalized,
            receipt_object,
            &payload_json,
        )?;
        transaction.commit()?;
        Ok(result)
    }

