    /// Persist one additive passing ProductionWeaponFormQuality@2 report.
    /// The @1 quality report and FormArt@1 parent are immutable source links;
    /// this transaction owns exactly one V2 report JSON object.
    pub fn record_production_weapon_form_quality_v2(
        &self,
        quality: &ProductionWeaponFormQualityV2Record,
        receipt_object: &CasObjectRecord,
    ) -> Result<ProductionWeaponFormQualityV2Record, StoreError> {
        self.record_production_weapon_form_quality_v2_with_replay(quality, receipt_object)
            .map(|(record, _)| record)
    }

    pub fn record_production_weapon_form_quality_v2_with_replay(
        &self,
        quality: &ProductionWeaponFormQualityV2Record,
        receipt_object: &CasObjectRecord,
    ) -> Result<(ProductionWeaponFormQualityV2Record, bool), StoreError> {
        let mut normalized = quality.clone();
        if !normalized.receipt_object_sha256.is_empty()
            && normalized.receipt_object_sha256 != receipt_object.sha256
        {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_RECEIPT_BINDING_MISMATCH",
                "V2 report receipt hash differs from supplied CAS object",
            ));
        }
        normalized.receipt_object_sha256 = receipt_object.sha256.clone();
        validate_production_weapon_form_quality_v2(&normalized)?;
        let payload_json = production_weapon_form_quality_v2_payload_json(&normalized)?;
        ensure_production_weapon_form_quality_v2_receipt(&self.cas, receipt_object, &payload_json)?;
        let mut connection = self.lock_connection()?;
        let transaction = connection.transaction()?;
        let result = record_production_weapon_form_quality_v2_in_transaction(
            &transaction,
            &self.cas,
            &normalized,
            receipt_object,
            &payload_json,
        )?;
        transaction.commit()?;
        Ok(result)
    }

