fn read_production_stage_transition_v2_columns(
    connection: &Connection,
    transition_id: &str,
) -> Result<Option<ProductionStageTransitionV2Columns>, StoreError> {
    let row: Option<(String, String)> = connection
        .query_row(
            "SELECT payload_json, receipt_object_sha256 FROM agentic_production_stage_transitions_v2 WHERE transition_id = ?1",
            params![transition_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((payload_json, receipt_object_sha256)) = row else {
        return Ok(None);
    };
    let record: ProductionStageTransitionV2Record =
        serde_json::from_str(&payload_json).map_err(|error| {
            StoreError::InvalidData(format!(
                "invalid V2 production-stage transition payload: {error}"
            ))
        })?;
    validate_production_stage_transition_v2(&record)?;
    let expected = production_stage_transition_v2_column_values(
        &record,
        &receipt_object_sha256,
        &payload_json,
    );
    let stored: Vec<String> = connection.query_row(
        "SELECT transition_id, session_id, project_id, root_candidate_id, root_candidate_role, root_candidate_state_sha256, source_artifact_id, root_artifact_sha256, previous_head_candidate_id, previous_head_candidate_role, previous_head_candidate_state_sha256, previous_head_artifact_id, previous_head_artifact_sha256, previous_head_stage, head_candidate_id, head_candidate_role, head_candidate_state_sha256, output_artifact_id, head_artifact_sha256, from_stage, to_stage, topology_quality_id, topology_quality_status, topology_quality_report_object_sha256, topology_quality_canonical_sha256, material_surface_quality_id, material_surface_quality_status, material_surface_quality_report_object_sha256, material_surface_quality_canonical_sha256, candidate_binding_status, reference_id, reference_sha256, camera_hash, evidence_sha256, approval_receipt_id, approval_session_id, approval_expires_at, approval_summary_sha256, parent_topology_transition_id, parent_topology_transition_sha256, parent_topology_transition_schema_version, gate_status, status, input_sha256, receipt_object_sha256, canonical_sha256, payload_json, created_at FROM agentic_production_stage_transitions_v2 WHERE transition_id = ?1",
        params![transition_id],
        |row| {
            let count = row.as_ref().column_count();
            (0..count).map(|index| row.get(index)).collect()
        },
    )?;
    if stored != expected {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V2_PAYLOAD_BINDING_MISMATCH".to_owned(),
            message: "V2 transition payload does not match SQLite columns".to_owned(),
        });
    }
    Ok(Some(ProductionStageTransitionV2Columns {
        record,
        receipt_object_sha256,
        payload_json,
    }))
}

fn read_production_stage_transition_receipt(
    connection: &Connection,
    columns: &ProductionStageTransitionColumns,
) -> Result<CasObjectRecord, StoreError> {
    connection
        .query_row(
            "SELECT sha256, size_bytes, mime, kind, reachability, created_at FROM objects WHERE sha256 = ?1",
            params![columns.receipt_object_sha256],
            |row| {
                Ok(CasObjectRecord {
                    schema_version: "CasObject@1".to_owned(),
                    sha256: row.get(0)?,
                    size_bytes: u64::try_from(row.get::<_, i64>(1)?).map_err(|_| {
                        rusqlite::Error::FromSqlConversionFailure(
                            1,
                            rusqlite::types::Type::Integer,
                            "negative V1 receipt size".into(),
                        )
                    })?,
                    mime: row.get(2)?,
                    kind: row.get(3)?,
                    reachability: row.get(4)?,
                    created_at: row.get(5)?,
                })
            },
        )
        .map_err(StoreError::from)
}

