fn read_production_stage_transition_v3_columns(
    connection: &Connection,
    transition_id: &str,
) -> Result<Option<ProductionStageTransitionV3Columns>, StoreError> {
    let row: Option<(String, String)> = connection
        .query_row(
            "SELECT payload_json, receipt_object_sha256 FROM agentic_production_stage_transitions_v3 WHERE transition_id = ?1",
            params![transition_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((payload_json, receipt_object_sha256)) = row else {
        return Ok(None);
    };
    let mut record: ProductionStageTransitionV3Record = serde_json::from_str(&payload_json)
        .map_err(|error| {
            StoreError::InvalidData(format!(
                "invalid V3 production-stage transition payload: {error}"
            ))
        })?;
    validate_production_stage_transition_v3(&record)?;
    if record.transition_id != transition_id
        || (!record.receipt_object_sha256.is_empty()
            && record.receipt_object_sha256 != receipt_object_sha256)
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_PAYLOAD_KEY_MISMATCH".to_owned(),
            message: "V3 transition payload key or receipt binding differs from SQLite".to_owned(),
        });
    }
    record.receipt_object_sha256 = receipt_object_sha256.clone();
    validate_production_stage_transition_v3(&record)?;
    let expected = production_stage_transition_v3_column_values(&record, &payload_json);
    let stored: Vec<Option<String>> = connection.query_row(
        "SELECT transition_id, session_id, project_id, root_candidate_id, root_candidate_role, root_candidate_state_sha256, source_artifact_id, root_artifact_sha256, previous_head_candidate_id, previous_head_candidate_role, previous_head_candidate_state_sha256, previous_head_artifact_id, previous_head_artifact_sha256, previous_head_stage, head_candidate_id, head_candidate_role, head_candidate_state_sha256, output_artifact_id, head_artifact_sha256, from_stage, to_stage, candidate_binding_status, reference_id, reference_sha256, camera_hash, camera_lock_id, camera_lock_canonical_sha256, camera_rig_object_sha256, camera_rig_canonical_sha256, camera_lock_receipt_object_sha256, camera_lock_source_transition_id, camera_lock_source_transition_sha256, camera_lock_source_head_canonical_sha256, evidence_sha256, reference_canvas_object_sha256, quality_report_object_sha256, comparison_report_object_sha256, design_spec_object_sha256, visual_receipt_object_sha256, human_review_receipt_object_sha256, engine_validation_receipt_object_sha256, distribution_receipt_object_sha256, structural_status, visual_status, human_status, engine_status, distribution_status, approval_receipt_id, approval_session_id, approval_expires_at, approval_summary_sha256, request_key_sha256, parent_transition_id, parent_transition_sha256, parent_transition_schema_version, gate_status, status, input_sha256, receipt_object_sha256, canonical_sha256, payload_json, created_at FROM agentic_production_stage_transitions_v3 WHERE transition_id = ?1",
        params![transition_id],
        |row| {
            let count = row.as_ref().column_count();
            (0..count).map(|index| row.get(index)).collect()
        },
    )?;
    if stored != expected {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_PAYLOAD_BINDING_MISMATCH".to_owned(),
            message: "V3 transition payload does not match SQLite columns".to_owned(),
        });
    }
    Ok(Some(ProductionStageTransitionV3Columns {
        record,
        receipt_object_sha256,
        payload_json,
    }))
}

fn read_production_stage_head_v3_record(
    connection: &Connection,
    session_id: &str,
    project_id: &str,
    root_candidate_id: &str,
) -> Result<Option<ProductionStageHeadV3Record>, StoreError> {
    let payload_json: Option<String> = connection
        .query_row(
            "SELECT payload_json FROM agentic_production_stage_heads_v3 WHERE session_id = ?1 AND project_id = ?2 AND root_candidate_id = ?3",
            params![session_id, project_id, root_candidate_id],
            |row| row.get(0),
        )
        .optional()?;
    let Some(payload_json) = payload_json else {
        return Ok(None);
    };
    let head: ProductionStageHeadV3Record =
        serde_json::from_str(&payload_json).map_err(|error| {
            StoreError::InvalidData(format!("invalid V3 production-stage head payload: {error}"))
        })?;
    validate_production_stage_head_v3(&head)?;
    let expected_payload = production_stage_head_v3_payload_json(&head)?;
    if expected_payload != payload_json {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_HEAD_V3_PAYLOAD_MISMATCH".to_owned(),
            message: "V3 production-stage head payload differs from its canonical projection"
                .to_owned(),
        });
    }
    let projection_json =
        production_stage_v3_compatibility_projection_json(&head.compatibility_projection)?;
    let expected = production_stage_head_v3_column_values(&head, &projection_json, &payload_json);
    let stored: Vec<Option<String>> = connection.query_row(
        "SELECT session_id, project_id, root_candidate_id, root_candidate_role, root_candidate_state_sha256, source_artifact_id, root_artifact_sha256, root_stage, previous_head_candidate_id, previous_head_candidate_role, previous_head_candidate_state_sha256, previous_head_artifact_id, previous_head_artifact_sha256, previous_head_stage, head_candidate_id, head_candidate_role, head_candidate_state_sha256, output_artifact_id, head_artifact_sha256, head_stage, candidate_binding_status, reference_id, reference_sha256, camera_hash, camera_lock_id, camera_lock_canonical_sha256, camera_rig_object_sha256, camera_rig_canonical_sha256, camera_lock_receipt_object_sha256, camera_lock_source_transition_id, camera_lock_source_transition_sha256, camera_lock_source_head_canonical_sha256, evidence_sha256, reference_canvas_object_sha256, quality_report_object_sha256, comparison_report_object_sha256, design_spec_object_sha256, visual_receipt_object_sha256, human_review_receipt_object_sha256, engine_validation_receipt_object_sha256, distribution_receipt_object_sha256, structural_status, visual_status, human_status, engine_status, distribution_status, approval_receipt_id, approval_session_id, approval_expires_at, approval_summary_sha256, head_transition_id, head_transition_sha256, compatibility_projection_json, CAST(candidate_confirmed AS TEXT), CAST(version_created AS TEXT), CAST(export_performed AS TEXT), materialization_status, canonical_sha256, payload_json, updated_at FROM agentic_production_stage_heads_v3 WHERE session_id = ?1 AND project_id = ?2 AND root_candidate_id = ?3",
        params![session_id, project_id, root_candidate_id],
        |row| {
            let count = row.as_ref().column_count();
            (0..count).map(|index| row.get(index)).collect()
        },
    )?;
    if stored != expected {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_HEAD_V3_PAYLOAD_BINDING_MISMATCH".to_owned(),
            message: "V3 head payload does not match SQLite columns".to_owned(),
        });
    }
    Ok(Some(head))
}

fn ensure_production_stage_v3_object(
    connection: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    sha256: &str,
    label: &str,
) -> Result<(), StoreError> {
    let Some((size_bytes, reachability)) = connection
        .query_row(
            "SELECT size_bytes, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get::<_, i64>(0)?, row.get::<_, String>(1)?)),
        )
        .optional()?
    else {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_CAS_UNAVAILABLE".to_owned(),
            message: format!("V3 {label} CAS object is not registered"),
        });
    };
    if size_bytes < 0 || !matches!(reachability.as_str(), "temporary" | "reachable") {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_CAS_METADATA_INVALID".to_owned(),
            message: format!("V3 {label} CAS metadata is invalid"),
        });
    }
    cas.verify(
        sha256,
        u64::try_from(size_bytes).map_err(|_| StoreError::InvalidData(label.to_owned()))?,
    )?;
    Ok(())
}

fn v3_session_payload_hash(payload: &Value, field: &str) -> Result<String, StoreError> {
    payload
        .get(field)
        .and_then(Value::as_str)
        .filter(|value| is_sha256(value))
        .map(str::to_owned)
        .ok_or_else(|| StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_SESSION_PAYLOAD_INVALID".to_owned(),
            message: format!("V3 session payload does not contain a valid {field}"),
        })
}

fn ensure_production_stage_transition_v3_bindings(
    connection: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    transition: &ProductionStageTransitionV3Record,
    receipt_object: &CasObjectRecord,
) -> Result<(), StoreError> {
    let session: Option<(
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
    )> = connection
        .query_row(
            "SELECT project_id, candidate_id, candidate_state_sha256, reference_id, reference_sha256, camera_hash, evidence_sha256, object_sha256, payload_json FROM agentic_design_sessions WHERE session_id = ?1",
            params![transition.session_id],
            |row| {
                Ok((
                    row.get(0)?,
                    row.get(1)?,
                    row.get(2)?,
                    row.get(3)?,
                    row.get(4)?,
                    row.get(5)?,
                    row.get(6)?,
                    row.get(7)?,
                    row.get(8)?,
                ))
            },
        )
        .optional()?;
    let Some((
        session_project,
        session_candidate,
        session_state,
        session_reference,
        session_reference_sha,
        session_camera,
        session_evidence,
        session_object_sha,
        session_payload_json,
    )) = session
    else {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_SESSION_NOT_FOUND".to_owned(),
            message: "V3 transition session is unavailable".to_owned(),
        });
    };
    if session_project != transition.project_id
        || session_candidate != transition.root_candidate_id
        || session_state != transition.root_candidate_state_sha256
        || session_reference != transition.reference_id
        || session_reference_sha != transition.reference_sha256
        || session_camera != transition.camera_hash
        || session_evidence != transition.evidence_sha256
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_SESSION_BINDING_MISMATCH".to_owned(),
            message: "V3 transition is outside the exact session binding".to_owned(),
        });
    }
    let session_payload: Value =
        serde_json::from_str(&session_payload_json).map_err(|error| StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_SESSION_PAYLOAD_INVALID".to_owned(),
            message: format!("V3 session payload cannot be decoded: {error}"),
        })?;
    let session_canvas_sha = v3_session_payload_hash(&session_payload, "reference_canvas_sha256")?;
    let session_design_spec_sha = v3_session_payload_hash(&session_payload, "design_spec_sha256")?;
    if session_canvas_sha != transition.reference_canvas_object_sha256
        || session_design_spec_sha != transition.design_spec_object_sha256
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_SESSION_CAS_BINDING_MISMATCH".to_owned(),
            message: "V3 canvas/design-spec hashes do not match the durable session payload"
                .to_owned(),
        });
    }

    let candidate: Option<(String, Option<String>, Option<String>, String)> = connection
        .query_row(
            "SELECT project_id, prepared_object_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
            params![transition.root_candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((candidate_project, prepared_object_id, prepared_object_sha, candidate_state)) =
        candidate
    else {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_CANDIDATE_NOT_FOUND".to_owned(),
            message: "V3 candidate is unavailable".to_owned(),
        });
    };
    if candidate_project != transition.project_id
        || candidate_state != transition.root_candidate_state_sha256
        || prepared_object_id.as_deref() != Some(transition.source_artifact_id.as_str())
        || prepared_object_sha.as_deref() != Some(transition.root_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_CANDIDATE_BINDING_MISMATCH".to_owned(),
            message: "V3 candidate state or artifact binding differs".to_owned(),
        });
    }

    let reference: Option<(String, String)> = connection
        .query_row(
            "SELECT project_id, object_sha256 FROM reference_evidence WHERE reference_id = ?1",
            params![transition.reference_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if reference.as_ref().map(|value| value.0.as_str()) != Some(transition.project_id.as_str())
        || reference.as_ref().map(|value| value.1.as_str())
            != Some(transition.reference_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_REFERENCE_BINDING_MISMATCH".to_owned(),
            message: "V3 reference is outside the session project/hash binding".to_owned(),
        });
    }
    if !transition.receipt_object_sha256.is_empty()
        && transition.receipt_object_sha256 != receipt_object.sha256
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_TRANSITION_V3_RECEIPT_BINDING_MISMATCH".to_owned(),
            message: "V3 receipt object is not the transition receipt".to_owned(),
        });
    }
    for (hash, label) in [
        (session_object_sha.as_str(), "session"),
        (transition.root_artifact_sha256.as_str(), "root artifact"),
        (transition.head_artifact_sha256.as_str(), "head artifact"),
        (transition.reference_sha256.as_str(), "reference"),
        (
            transition.reference_canvas_object_sha256.as_str(),
            "reference canvas",
        ),
        (transition.design_spec_object_sha256.as_str(), "design spec"),
        (receipt_object.sha256.as_str(), "transition receipt"),
    ] {
        ensure_production_stage_v3_object(connection, cas, hash, label)?;
    }
    ensure_production_stage_transition_v3_receipt_row(connection, receipt_object)?;
    ensure_production_stage_camera_lock_binding(connection, cas, transition)?;
    ensure_production_stage_form_binding(connection, cas, transition)?;
    Ok(())
}

fn ensure_production_stage_camera_lock_binding(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    transition: &ProductionStageTransitionV3Record,
) -> Result<(), StoreError> {
    if !production_stage_v3_is_camera_edge(transition) {
        return Ok(());
    }
    let lock_id = transition
        .camera_lock_id
        .as_deref()
        .ok_or_else(|| StoreError::Contract {
            code: "PRODUCTION_STAGE_CAMERA_LOCK_MISSING".to_owned(),
            message: "camera-calibrated transition has no camera lock id".to_owned(),
        })?;
    let parent_id =
        transition
            .parent_transition_id
            .as_deref()
            .ok_or_else(|| StoreError::Contract {
                code: "PRODUCTION_STAGE_CAMERA_PARENT_MISSING".to_owned(),
                message: "camera-calibrated transition has no parent transition".to_owned(),
            })?;
    let parent_sha = transition
        .parent_transition_sha256
        .as_deref()
        .ok_or_else(|| StoreError::Contract {
            code: "PRODUCTION_STAGE_CAMERA_PARENT_HASH_MISSING".to_owned(),
            message: "camera-calibrated transition has no parent hash".to_owned(),
        })?;
    let Some(lock) = read_production_camera_lock_columns(transaction, lock_id)? else {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_CAMERA_LOCK_NOT_FOUND".to_owned(),
            message: "camera-calibrated transition references a missing camera lock".to_owned(),
        });
    };
    let Some(parent_columns) = read_production_stage_transition_v3_columns(transaction, parent_id)?
    else {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_CAMERA_PARENT_NOT_FOUND".to_owned(),
            message: "camera-calibrated transition references a missing parent".to_owned(),
        });
    };
    let parent = parent_columns.record;
    let parent_head = production_stage_head_v3_from_transition(&parent)?;
    if !production_stage_v3_is_first_edge(&parent)
        || parent.transition_id != parent_id
        || parent.canonical_sha256 != parent_sha
        || transition.camera_lock_source_transition_id.as_deref() != Some(parent_id)
        || transition.camera_lock_source_transition_sha256.as_deref() != Some(parent_sha)
        || transition
            .camera_lock_source_head_canonical_sha256
            .as_deref()
            != Some(parent_head.canonical_sha256.as_str())
        || lock.source_transition_id != parent_id
        || lock.source_transition_sha256 != parent_sha
        || lock.source_head_canonical_sha256 != parent_head.canonical_sha256
        || lock.session_id != transition.session_id
        || lock.project_id != transition.project_id
        || lock.candidate_id != transition.root_candidate_id
        || lock.candidate_state_sha256 != transition.root_candidate_state_sha256
        || lock.artifact_id != transition.source_artifact_id
        || lock.artifact_sha256 != transition.root_artifact_sha256
        || lock.reference_id != transition.reference_id
        || lock.reference_sha256 != transition.reference_sha256
        || lock.reference_canvas_object_sha256 != transition.reference_canvas_object_sha256
        || lock.design_spec_object_sha256 != transition.design_spec_object_sha256
        || transition.camera_lock_canonical_sha256.as_deref()
            != Some(lock.canonical_sha256.as_str())
        || transition.camera_rig_object_sha256.as_deref()
            != Some(lock.camera_rig_object_sha256.as_str())
        || transition.camera_rig_canonical_sha256.as_deref()
            != Some(lock.camera_rig_canonical_sha256.as_str())
        || transition.camera_lock_receipt_object_sha256.as_deref()
            != Some(lock.receipt_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_CAMERA_LOCK_BINDING_MISMATCH".to_owned(),
            message: "camera lock, parent transition and current stage bindings differ".to_owned(),
        });
    }

    let load_object = |sha256: &str, label: &str| -> Result<CasObjectRecord, StoreError> {
        transaction
            .query_row(
                "SELECT sha256, size_bytes, mime, kind, reachability, created_at FROM objects WHERE sha256 = ?1",
                params![sha256],
                |row| {
                    Ok(CasObjectRecord {
                        schema_version: "CasObject@1".to_owned(),
                        sha256: row.get(0)?,
                        size_bytes: u64::try_from(row.get::<_, i64>(1)?).map_err(|_| {
                            rusqlite::Error::FromSqlConversionFailure(
                                1,
                                rusqlite::types::Type::Integer,
                                format!("negative {label} size").into(),
                            )
                        })?,
                        mime: row.get(2)?,
                        kind: row.get(3)?,
                        reachability: row.get(4)?,
                        created_at: row.get(5)?,
                    })
                },
            )
            .optional()?
            .ok_or_else(|| StoreError::Contract {
                code: "PRODUCTION_STAGE_CAMERA_LOCK_CAS_MISSING".to_owned(),
                message: format!("camera lock {label} object is missing"),
            })
    };
    let rig = load_object(&lock.camera_rig_object_sha256, "rig")?;
    let lock_receipt = load_object(&lock.receipt_object_sha256, "receipt")?;
    ensure_production_camera_lock_object_row(
        transaction,
        &rig,
        PRODUCTION_CAMERA_LOCK_JSON_MIME,
        PRODUCTION_CAMERA_LOCK_RIG_KIND,
        "camera rig",
        true,
    )?;
    ensure_production_camera_lock_object_row(
        transaction,
        &lock_receipt,
        PRODUCTION_CAMERA_LOCK_JSON_MIME,
        PRODUCTION_CAMERA_LOCK_RECEIPT_KIND,
        "receipt",
        true,
    )?;
    ensure_production_camera_lock_rig(
        cas,
        &rig,
        &lock.project_id,
        &lock.candidate_id,
        &lock.camera_rig_canonical_sha256,
    )?;
    let lock_payload = production_camera_lock_payload_json(&lock)?;
    ensure_production_camera_lock_receipt(cas, &lock_receipt, &lock_payload)?;

    let parent_receipt = load_object(&parent_columns.receipt_object_sha256, "parent receipt")?;
    ensure_production_stage_transition_v3_receipt(
        cas,
        &parent_receipt,
        &parent_columns.payload_json,
    )?;
    ensure_production_stage_transition_v3_receipt_row(transaction, &parent_receipt)?;
    Ok(())
}

fn ensure_production_stage_form_binding(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    transition: &ProductionStageTransitionV3Record,
) -> Result<(), StoreError> {
    if !production_stage_v3_is_form_edge(transition) {
        return Ok(());
    }
    let error = |code: &str, message: &str| StoreError::Contract {
        code: code.to_owned(),
        message: message.to_owned(),
    };
    let parent_id = transition.parent_transition_id.as_deref().ok_or_else(|| {
        error(
            "PRODUCTION_STAGE_FORM_PARENT_MISSING",
            "form transition has no parent transition",
        )
    })?;
    let parent_sha256 = transition
        .parent_transition_sha256
        .as_deref()
        .ok_or_else(|| {
            error(
                "PRODUCTION_STAGE_FORM_PARENT_MISSING",
                "form transition has no parent transition hash",
            )
        })?;
    let parent_columns = read_production_stage_transition_v3_columns(transaction, parent_id)?
        .ok_or_else(|| {
            error(
                "PRODUCTION_STAGE_FORM_PARENT_NOT_FOUND",
                "form transition parent is unavailable",
            )
        })?;
    let parent = &parent_columns.record;
    let parent_head = production_stage_head_v3_from_transition(parent)?;
    if parent.canonical_sha256 != parent_sha256
        || parent.to_stage != transition.from_stage
        || parent.session_id != transition.session_id
        || parent.project_id != transition.project_id
        || parent.root_candidate_id != transition.root_candidate_id
        || parent.head_candidate_state_sha256 != transition.root_candidate_state_sha256
        || parent.output_artifact_id != transition.source_artifact_id
        || parent.head_artifact_sha256 != transition.root_artifact_sha256
    {
        return Err(error(
            "PRODUCTION_STAGE_FORM_PARENT_BINDING_MISMATCH",
            "form transition is not bound to the exact source-stage parent",
        ));
    }

    let lock_id = transition.camera_lock_id.as_deref().ok_or_else(|| {
        error(
            "PRODUCTION_STAGE_FORM_CAMERA_LOCK_MISSING",
            "form transition has no camera lock",
        )
    })?;
    let lock = read_production_camera_lock_in_transaction(transaction, cas, lock_id)?.ok_or_else(
        || {
            error(
                "PRODUCTION_STAGE_FORM_CAMERA_LOCK_NOT_FOUND",
                "form transition camera lock is unavailable",
            )
        },
    )?;
    if lock.session_id != transition.session_id
        || lock.project_id != transition.project_id
        || lock.candidate_id != transition.root_candidate_id
        || lock.candidate_state_sha256 != transition.root_candidate_state_sha256
        || lock.artifact_id != transition.source_artifact_id
        || lock.artifact_sha256 != transition.root_artifact_sha256
        || lock.reference_id != transition.reference_id
        || lock.reference_sha256 != transition.reference_sha256
        || lock.reference_canvas_object_sha256 != transition.reference_canvas_object_sha256
        || lock.design_spec_object_sha256 != transition.design_spec_object_sha256
        || transition.camera_lock_canonical_sha256.as_deref()
            != Some(lock.canonical_sha256.as_str())
        || transition.camera_rig_object_sha256.as_deref()
            != Some(lock.camera_rig_object_sha256.as_str())
        || transition.camera_rig_canonical_sha256.as_deref()
            != Some(lock.camera_rig_canonical_sha256.as_str())
        || transition.camera_lock_receipt_object_sha256.as_deref()
            != Some(lock.receipt_object_sha256.as_str())
        || transition.camera_lock_source_transition_id.as_deref()
            != Some(lock.source_transition_id.as_str())
        || transition.camera_lock_source_transition_sha256.as_deref()
            != Some(lock.source_transition_sha256.as_str())
        || transition
            .camera_lock_source_head_canonical_sha256
            .as_deref()
            != Some(lock.source_head_canonical_sha256.as_str())
    {
        return Err(error(
            "PRODUCTION_STAGE_FORM_CAMERA_LOCK_BINDING_MISMATCH",
            "form transition camera lock differs from the candidate/source binding",
        ));
    }

    let quality_report_sha256 = transition
        .quality_report_object_sha256
        .as_deref()
        .ok_or_else(|| {
            error(
                "PRODUCTION_STAGE_FORM_QUALITY_MISSING",
                "form transition has no FormQuality@2 report",
            )
        })?;
    let quality_id: Option<String> = transaction
        .query_row(
            "SELECT form_quality_id FROM production_weapon_form_quality_v2_links WHERE receipt_object_sha256 = ?1",
            params![quality_report_sha256],
            |row| row.get(0),
        )
        .optional()?;
    let quality_id = quality_id.ok_or_else(|| {
        error(
            "PRODUCTION_STAGE_FORM_QUALITY_NOT_FOUND",
            "form transition FormQuality@2 report is unavailable",
        )
    })?;
    let quality =
        read_production_weapon_form_quality_v2_in_transaction(transaction, cas, &quality_id)?
            .ok_or_else(|| {
                error(
                    "PRODUCTION_STAGE_FORM_QUALITY_NOT_FOUND",
                    "form transition FormQuality@2 row is unavailable",
                )
            })?;
    let visual_receipt_sha256 = transition
        .visual_receipt_object_sha256
        .as_deref()
        .ok_or_else(|| {
            error(
                "PRODUCTION_STAGE_FORM_ART_MISSING",
                "form transition has no FormArt@1 receipt",
            )
        })?;
    if quality.receipt_object_sha256 != quality_report_sha256
        || quality.form_art_evidence_object_sha256 != visual_receipt_sha256
        || quality.session_id != transition.session_id
        || quality.project_id != transition.project_id
        || quality.source_stage != transition.from_stage
        || quality.target_stage != transition.to_stage
        || quality.current_source_head_transition_id != parent.transition_id
        || quality.current_source_head_transition_sha256 != parent.canonical_sha256
        || quality.current_source_head_canonical_sha256 != parent_head.canonical_sha256
        || quality.current_source_head_stage != parent_head.head_stage
        || quality.candidate_id != transition.root_candidate_id
        || quality.candidate_state_sha256 != transition.root_candidate_state_sha256
        || quality.artifact_id != transition.source_artifact_id
        || quality.artifact_sha256 != transition.root_artifact_sha256
        || quality.reference_id != transition.reference_id
        || quality.reference_sha256 != transition.reference_sha256
        || quality.reference_canvas_object_sha256 != transition.reference_canvas_object_sha256
        || quality.design_spec_object_sha256 != transition.design_spec_object_sha256
        || quality.camera_hash != transition.camera_hash
        || quality.camera_lock_id != lock.camera_lock_id
        || quality.camera_lock_canonical_sha256 != lock.canonical_sha256
        || quality.camera_rig_object_sha256 != lock.camera_rig_object_sha256
        || quality.camera_rig_canonical_sha256 != lock.camera_rig_canonical_sha256
        || quality.camera_lock_receipt_object_sha256 != lock.receipt_object_sha256
        || !quality.hard_gate_passed
        || !quality.form_gate_passed
        || quality.validator_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_VALIDATOR_STATUS
        || quality.structural_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_STRUCTURAL_STATUS
        || quality.visual_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_VISUAL_STATUS
        || quality.human_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_HUMAN_STATUS
        || quality.engine_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_ENGINE_STATUS
        || quality.distribution_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_DISTRIBUTION_STATUS
        || quality.quality_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_QUALITY_STATUS
    {
        return Err(error(
            "PRODUCTION_STAGE_FORM_QUALITY_BINDING_MISMATCH",
            "FormQuality@2 is not bound to the exact source head and form edge",
        ));
    }

    let art_id: Option<String> = transaction
        .query_row(
            "SELECT art_evidence_id FROM production_weapon_form_art_evidence_links WHERE receipt_object_sha256 = ?1",
            params![visual_receipt_sha256],
            |row| row.get(0),
        )
        .optional()?;
    let art_id = art_id.ok_or_else(|| {
        error(
            "PRODUCTION_STAGE_FORM_ART_NOT_FOUND",
            "form transition FormArt@1 receipt is unavailable",
        )
    })?;
    let art = read_production_weapon_form_art_evidence_in_transaction(transaction, cas, &art_id)?
        .ok_or_else(|| {
        error(
            "PRODUCTION_STAGE_FORM_ART_NOT_FOUND",
            "form transition FormArt@1 row is unavailable",
        )
    })?;
    if art.receipt_object_sha256 != visual_receipt_sha256
        || art.session_id != transition.session_id
        || art.project_id != transition.project_id
        || art.candidate_id != transition.root_candidate_id
        || art.candidate_state_sha256 != transition.root_candidate_state_sha256
        || art.artifact_id != transition.source_artifact_id
        || art.artifact_sha256 != transition.root_artifact_sha256
        || art.reference_canvas_object_sha256 != transition.reference_canvas_object_sha256
        || art.design_spec_object_sha256 != transition.design_spec_object_sha256
        || art.camera_lock_id != lock.camera_lock_id
        || art.camera_lock_canonical_sha256 != lock.canonical_sha256
        || art.camera_rig_object_sha256 != lock.camera_rig_object_sha256
        || art.camera_rig_canonical_sha256 != lock.camera_rig_canonical_sha256
        || art.camera_lock_receipt_object_sha256 != lock.receipt_object_sha256
        || art.quality_status != PRODUCTION_WEAPON_FORM_ART_EVIDENCE_QUALITY_STATUS
    {
        return Err(error(
            "PRODUCTION_STAGE_FORM_ART_BINDING_MISMATCH",
            "FormArt@1 is not bound to the exact form edge",
        ));
    }
    Ok(())
}

fn production_stage_transition_v3_reachable_hashes(
    connection: &rusqlite::Transaction<'_>,
    transition: &ProductionStageTransitionV3Record,
    receipt_object_sha256: &str,
) -> Result<Vec<String>, StoreError> {
    let session_object: String = connection.query_row(
        "SELECT object_sha256 FROM agentic_design_sessions WHERE session_id = ?1",
        params![transition.session_id],
        |row| row.get(0),
    )?;
    let reference_object: String = connection.query_row(
        "SELECT object_sha256 FROM reference_evidence WHERE reference_id = ?1",
        params![transition.reference_id],
        |row| row.get(0),
    )?;
    let mut hashes = vec![
        session_object,
        reference_object,
        transition.root_artifact_sha256.clone(),
        transition.head_artifact_sha256.clone(),
        transition.reference_canvas_object_sha256.clone(),
        transition.design_spec_object_sha256.clone(),
        receipt_object_sha256.to_owned(),
    ];
    if !production_stage_v3_is_first_edge(transition) {
        if let Some(rig) = transition.camera_rig_object_sha256.as_ref() {
            hashes.push(rig.clone());
        }
        if let Some(lock_receipt) = transition.camera_lock_receipt_object_sha256.as_ref() {
            hashes.push(lock_receipt.clone());
        }
        if let Some(parent_id) = transition.parent_transition_id.as_ref() {
            let parent_receipt: String = connection.query_row(
                "SELECT receipt_object_sha256 FROM agentic_production_stage_transitions_v3 WHERE transition_id = ?1",
                params![parent_id],
                |row| row.get(0),
            )?;
            hashes.push(parent_receipt);
        }
    }
    for hash in [
        transition.quality_report_object_sha256.as_ref(),
        transition.comparison_report_object_sha256.as_ref(),
        transition.visual_receipt_object_sha256.as_ref(),
        transition.human_review_receipt_object_sha256.as_ref(),
        transition.engine_validation_receipt_object_sha256.as_ref(),
        transition.distribution_receipt_object_sha256.as_ref(),
    ]
    .into_iter()
    .flatten()
    {
        hashes.push(hash.clone());
    }
    hashes.sort();
    hashes.dedup();
    validate_reachable_hashes(&hashes)?;
    Ok(hashes)
}

fn read_production_stage_transition_v3_for_connection(
    connection: &mut Connection,
    cas: &CasStore,
    transition_id: &str,
) -> Result<Option<ProductionStageTransitionV3Record>, StoreError> {
    let transaction = connection.transaction()?;
    let result =
        read_production_stage_transition_v3_in_transaction(&transaction, cas, transition_id)?
            .map(|(transition, _head)| transition);
    transaction.rollback()?;
    Ok(result)
}

fn read_production_stage_transition_v3_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    transition_id: &str,
) -> Result<
    Option<(
        ProductionStageTransitionV3Record,
        ProductionStageHeadV3Record,
    )>,
    StoreError,
> {
    let Some(columns) = read_production_stage_transition_v3_columns(transaction, transition_id)?
    else {
        return Ok(None);
    };
    let receipt: CasObjectRecord = transaction.query_row(
        "SELECT sha256, size_bytes, mime, kind, reachability, created_at FROM objects WHERE sha256 = ?1",
        params![columns.receipt_object_sha256],
        |row| {
            Ok(CasObjectRecord {
                schema_version: "CasObject@1".to_owned(),
                sha256: row.get(0)?,
                size_bytes: u64::try_from(row.get::<_, i64>(1)?).map_err(|_| {
                    rusqlite::Error::FromSqlConversionFailure(
                        1,
                        rusqlite::types::Type::Integer,
                        "negative V3 receipt size".into(),
                    )
                })?,
                mime: row.get(2)?,
                kind: row.get(3)?,
                reachability: row.get(4)?,
                created_at: row.get(5)?,
            })
        },
    )?;
    ensure_production_stage_transition_v3_receipt(cas, &receipt, &columns.payload_json)?;
    ensure_production_stage_transition_v3_receipt_row(transaction, &receipt)?;
    let head = read_production_stage_head_v3_record(
        transaction,
        &columns.record.session_id,
        &columns.record.project_id,
        &columns.record.root_candidate_id,
    )?
    .ok_or_else(|| StoreError::Contract {
        code: "PRODUCTION_STAGE_HEAD_V3_MISSING".to_owned(),
        message: "V3 transition has no durable head row".to_owned(),
    })?;
    let owns_current_head = head.head_transition_id == columns.record.transition_id
        && head.head_transition_sha256 == columns.record.canonical_sha256;
    let has_durable_descendant: bool = if owns_current_head {
        false
    } else {
        transaction.query_row(
            "SELECT EXISTS(SELECT 1 FROM agentic_production_stage_transitions_v3 WHERE session_id = ?1 AND project_id = ?2 AND root_candidate_id = ?3 AND parent_transition_id = ?4 AND parent_transition_sha256 = ?5)",
            params![
                columns.record.session_id,
                columns.record.project_id,
                columns.record.root_candidate_id,
                columns.record.transition_id,
                columns.record.canonical_sha256,
            ],
            |row| row.get::<_, i64>(0),
        )? != 0
    };
    if (!owns_current_head && !has_durable_descendant)
        || head.session_id != columns.record.session_id
        || head.project_id != columns.record.project_id
        || head.root_candidate_id != columns.record.root_candidate_id
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_HEAD_V3_TRANSITION_MISMATCH".to_owned(),
            message: "V3 head neither owns nor descends from the requested transition".to_owned(),
        });
    }
    ensure_production_stage_transition_v3_bindings(transaction, cas, &columns.record, &receipt)?;
    let reachable = production_stage_transition_v3_reachable_hashes(
        transaction,
        &columns.record,
        &receipt.sha256,
    )?;
    for hash in reachable {
        let status: Option<String> = transaction
            .query_row(
                "SELECT reachability FROM objects WHERE sha256 = ?1",
                params![hash],
                |row| row.get(0),
            )
            .optional()?;
        if status.as_deref() != Some("reachable") {
            return Err(StoreError::Contract {
                code: "PRODUCTION_STAGE_TRANSITION_V3_REACHABILITY_MISMATCH".to_owned(),
                message: "V3 transition or ancestor CAS input is not reachable".to_owned(),
            });
        }
    }
    Ok(Some((columns.record, head)))
}

fn read_production_stage_head_v3_for_connection(
    connection: &mut Connection,
    cas: &CasStore,
    session_id: &str,
    project_id: &str,
    root_candidate_id: &str,
) -> Result<Option<ProductionStageHeadV3Record>, StoreError> {
    let transaction = connection.transaction()?;
    let Some(head) = read_production_stage_head_v3_record(
        &transaction,
        session_id,
        project_id,
        root_candidate_id,
    )?
    else {
        transaction.rollback()?;
        return Ok(None);
    };
    let transition = read_production_stage_transition_v3_in_transaction(
        &transaction,
        cas,
        &head.head_transition_id,
    )?
    .ok_or_else(|| StoreError::Contract {
        code: "PRODUCTION_STAGE_TRANSITION_V3_MISSING".to_owned(),
        message: "V3 head transition is unavailable".to_owned(),
    })?;
    if transition.1 != head {
        return Err(StoreError::Contract {
            code: "PRODUCTION_STAGE_HEAD_V3_TRANSITION_MISMATCH".to_owned(),
            message: "V3 head transition binding differs".to_owned(),
        });
    }
    transaction.rollback()?;
    Ok(Some(head))
}

fn read_production_weapon_high_low_bake_preflight_child(
    connection: &Connection,
    table: &str,
    columns: &str,
    bake_receipt_id: &str,
) -> Result<Option<Vec<Option<String>>>, StoreError> {
    let query = format!("SELECT {columns} FROM {table} WHERE bake_receipt_id = ?1");
    Ok(connection
        .query_row(&query, params![bake_receipt_id], |row| {
            let count = row.as_ref().column_count();
            (0..count)
                .map(|index| row.get::<_, Option<String>>(index))
                .collect::<Result<Vec<_>, _>>()
        })
        .optional()?)
}

fn production_weapon_high_low_preflight_row_value(
    row: Option<&Vec<Option<String>>>,
    index: usize,
) -> Option<&str> {
    row.and_then(|values| values.get(index))
        .and_then(|value| value.as_deref())
}

fn production_weapon_high_low_preflight_object(
    connection: &Connection,
    cas: &CasStore,
    hash: &str,
    label: &str,
) -> Result<(), StoreError> {
    if !is_sha256(hash) {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_HASH_INVALID",
            format!("{label} is not a SHA-256"),
        ));
    }
    let size_bytes: Option<i64> = connection
        .query_row(
            "SELECT size_bytes FROM objects WHERE sha256 = ?1",
            params![hash],
            |row| row.get(0),
        )
        .optional()?;
    let Some(size_bytes) = size_bytes else {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_OBJECT_MISSING",
            format!("{label} is not registered in the Runtime object index"),
        ));
    };
    let size_bytes = u64::try_from(size_bytes).map_err(|_| {
        production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_OBJECT_INVALID",
            format!("{label} has a negative object size"),
        )
    })?;
    cas.verify(hash, size_bytes)?;
    Ok(())
}

fn production_weapon_high_low_preflight_payload(
    payload_json: &str,
    label: &str,
    bake_receipt_id: &str,
) -> Result<(), StoreError> {
    let value: Value = serde_json::from_str(payload_json).map_err(|error| {
        production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_PAYLOAD_INVALID",
            format!("{label} payload is not valid JSON: {error}"),
        )
    })?;
    if !value.is_object() {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_PAYLOAD_INVALID",
            format!("{label} payload is not a JSON object"),
        ));
    }
    if let Some(schema_version) = value.get("schema_version") {
        if !schema_version
            .as_str()
            .is_some_and(|schema| schema.starts_with("ProductionWeapon"))
        {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_PAYLOAD_INVALID",
                format!("{label} payload has an invalid schema_version"),
            ));
        }
    }
    if let Some(stored_receipt_id) = value.get("bake_receipt_id") {
        if stored_receipt_id.as_str() != Some(bake_receipt_id) {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_BINDING_MISMATCH",
                format!("{label} payload bake_receipt_id differs from SQLite"),
            ));
        }
    }
    if let Some(canonical_sha256) = value.get("canonical_sha256") {
        if !canonical_sha256.as_str().is_some_and(is_sha256) {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_PAYLOAD_INVALID",
                format!("{label} payload canonical_sha256 is invalid"),
            ));
        }
    }
    Ok(())
}

fn production_weapon_high_low_preflight_validate_child(
    connection: &Connection,
    cas: &CasStore,
    row: Option<&Vec<Option<String>>>,
    bake_receipt_id: &str,
    expected_receipt_object_sha256: &str,
    child_name: &str,
    expected_id: Option<&str>,
    object_hashes: &[(&str, usize)],
    receipt_index: Option<usize>,
    payload_index: usize,
) -> Result<bool, StoreError> {
    let Some(row) = row else {
        return Ok(false);
    };
    let child_id =
        production_weapon_high_low_preflight_row_value(Some(row), 0).ok_or_else(|| {
            production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_ROW_INVALID",
                format!("{child_name} child row has no id"),
            )
        })?;
    if !is_opaque_id(child_id) || expected_id.is_some_and(|expected| expected != child_id) {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_BINDING_MISMATCH",
            format!("{child_name} child id is invalid or not bound to its parent"),
        ));
    }
    for (label, index) in object_hashes {
        let hash =
            production_weapon_high_low_preflight_row_value(Some(row), *index).ok_or_else(|| {
                production_weapon_high_low_error(
                    "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_ROW_INVALID",
                    format!("{child_name} child is missing {label}"),
                )
            })?;
        production_weapon_high_low_preflight_object(connection, cas, hash, label)?;
    }
    if let Some(index) = receipt_index {
        let receipt_hash = production_weapon_high_low_preflight_row_value(Some(row), index)
            .ok_or_else(|| {
                production_weapon_high_low_error(
                    "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_ROW_INVALID",
                    format!("{child_name} child is missing receipt_object_sha256"),
                )
            })?;
        if !is_sha256(receipt_hash) {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_HASH_INVALID",
                format!("{child_name} child receipt_object_sha256 is invalid"),
            ));
        }
        if receipt_hash != expected_receipt_object_sha256 {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_BINDING_MISMATCH",
                format!("{child_name} child receipt object differs from its parent"),
            ));
        }
    }
    let payload = production_weapon_high_low_preflight_row_value(Some(row), payload_index)
        .ok_or_else(|| {
            production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_ROW_INVALID",
                format!("{child_name} child is missing payload_json"),
            )
        })?;
    production_weapon_high_low_preflight_payload(payload, child_name, bake_receipt_id)?;
    Ok(true)
}

fn production_weapon_high_low_preflight_owned_objects(
    owned_objects_json: &str,
    bake_receipt_id: &str,
) -> Result<(), StoreError> {
    let value: Value = serde_json::from_str(owned_objects_json).map_err(|error| {
        production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_ROW_INVALID",
            format!("bake link {bake_receipt_id} owned_objects_json is invalid: {error}"),
        )
    })?;
    let Some(objects) = value.as_array() else {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_ROW_INVALID",
            format!("bake link {bake_receipt_id} owned_objects_json is not an array"),
        ));
    };
    if objects
        .iter()
        .any(|object| !object.as_str().is_some_and(is_sha256))
    {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_HASH_INVALID",
            format!("bake link {bake_receipt_id} owned_objects_json contains a non-hash"),
        ));
    }
    Ok(())
}

fn read_production_weapon_high_low_bake_preflight_sources(
    connection: &Connection,
    cas: &CasStore,
    head: Option<&ProductionStageHeadV3Record>,
    project_id: &str,
    session_id: &str,
    candidate_id: &str,
) -> Result<Vec<ProductionWeaponHighLowBakePreflightSourceSummary>, StoreError> {
    // Formal rows are meaningful only relative to the current immutable V3
    // head.  With no head there is no stage binding to inspect, and historical
    // rows must not be promoted into present-tense readiness evidence.
    let Some(head) = head else {
        return Ok(Vec::new());
    };
    let parent_rows = {
        let mut statement = connection.prepare(
            "SELECT bake_receipt_id, source_stage, target_stage, source_stage_head_transition_id, source_candidate_id, high_candidate_id, low_candidate_id, cage_artifact_sha256, receipt_object_sha256, canonical_sha256, payload_json, owned_objects_json FROM production_weapon_high_low_bake_links WHERE project_id = ?1 AND session_id = ?2 AND source_candidate_id = ?3 AND source_stage_head_transition_id = ?4 ORDER BY created_at DESC, bake_receipt_id ASC",
        )?;
        let rows = statement.query_map(
            params![
                project_id,
                session_id,
                candidate_id,
                head.head_transition_id
            ],
            |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, String>(4)?,
                    row.get::<_, String>(5)?,
                    row.get::<_, String>(6)?,
                    row.get::<_, String>(7)?,
                    row.get::<_, String>(8)?,
                    row.get::<_, String>(9)?,
                    row.get::<_, String>(10)?,
                    row.get::<_, String>(11)?,
                ))
            },
        )?;
        let collected = rows.collect::<Result<Vec<_>, _>>()?;
        collected
    };
    let mut summaries = Vec::with_capacity(parent_rows.len());
    for (
        bake_receipt_id,
        source_stage,
        target_stage,
        source_stage_head_transition_id,
        source_candidate_id,
        high_candidate_id,
        low_candidate_id,
        cage_artifact_sha256,
        receipt_object_sha256,
        canonical_sha256,
        payload_json,
        owned_objects_json,
    ) in parent_rows
    {
        if !is_opaque_id(&bake_receipt_id)
            || !is_opaque_id(&source_stage_head_transition_id)
            || !is_opaque_id(&source_candidate_id)
            || !is_opaque_id(&high_candidate_id)
            || !is_opaque_id(&low_candidate_id)
            || high_candidate_id == low_candidate_id
            || source_candidate_id == high_candidate_id
            || source_candidate_id == low_candidate_id
        {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_BINDING_MISMATCH",
                format!("bake link {bake_receipt_id} has invalid candidate binding"),
            ));
        }
        let transition_scope: Option<(String, String, String, String, String)> = connection
            .query_row(
                "SELECT session_id, project_id, root_candidate_id, from_stage, to_stage FROM agentic_production_stage_transitions_v3 WHERE transition_id = ?1",
                params![source_stage_head_transition_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
            )
            .optional()?;
        let Some((
            transition_session_id,
            transition_project_id,
            transition_root_candidate_id,
            _transition_from_stage,
            transition_to_stage,
        )) = transition_scope
        else {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_HEAD_MISMATCH",
                format!("bake link {bake_receipt_id} source transition is missing"),
            ));
        };
        if transition_session_id != session_id
            || transition_project_id != project_id
            || transition_root_candidate_id != candidate_id
            || transition_to_stage != head.head_stage
            || source_stage != head.head_stage
        {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_HEAD_MISMATCH",
                format!(
                    "bake link {bake_receipt_id} source stage or transition scope differs from the current head"
                ),
            ));
        }
        let stage_pair_valid = PRODUCTION_WEAPON_HIGH_LOW_SOURCE_STAGES
            .iter()
            .zip(PRODUCTION_WEAPON_HIGH_LOW_TARGET_STAGES.iter())
            .any(|(source, target)| *source == source_stage && *target == target_stage);
        if !stage_pair_valid {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_ROW_INVALID",
                format!("bake link {bake_receipt_id} has invalid stage binding"),
            ));
        }
        if head.session_id != session_id
            || head.project_id != project_id
            || head.root_candidate_id != candidate_id
            || head.head_transition_id != source_stage_head_transition_id
        {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_HEAD_MISMATCH",
                format!("bake link {bake_receipt_id} is not bound to the current V3 head"),
            ));
        }

        for (label, linked_candidate_id) in [
            ("source_candidate_id", source_candidate_id.as_str()),
            ("high_candidate_id", high_candidate_id.as_str()),
            ("low_candidate_id", low_candidate_id.as_str()),
        ] {
            let linked_project_id: Option<String> = connection
                .query_row(
                    "SELECT project_id FROM candidates WHERE candidate_id = ?1",
                    params![linked_candidate_id],
                    |row| row.get(0),
                )
                .optional()?;
            if linked_project_id.as_deref() != Some(project_id) {
                return Err(production_weapon_high_low_error(
                    "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_BINDING_MISMATCH",
                    format!("bake link {bake_receipt_id} {label} crosses project scope"),
                ));
            }
        }
        if !is_sha256(&canonical_sha256) {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_HASH_INVALID",
                format!("bake link {bake_receipt_id} canonical_sha256 is invalid"),
            ));
        }
        production_weapon_high_low_preflight_object(
            connection,
            cas,
            &receipt_object_sha256,
            "bake link receipt_object_sha256",
        )?;
        production_weapon_high_low_preflight_object(
            connection,
            cas,
            &cage_artifact_sha256,
            "bake link cage_artifact_sha256",
        )?;
        production_weapon_high_low_preflight_payload(&payload_json, "bake link", &bake_receipt_id)?;
        production_weapon_high_low_preflight_owned_objects(&owned_objects_json, &bake_receipt_id)?;

        let high = read_production_weapon_high_low_bake_preflight_child(
            connection,
            "production_weapon_high_low_bake_high",
            "high_artifact_id, high_artifact_sha256, high_artifact_readback_object_sha256, receipt_object_sha256, payload_json",
            &bake_receipt_id,
        )?;
        let low = read_production_weapon_high_low_bake_preflight_child(
            connection,
            "production_weapon_high_low_bake_low",
            "low_artifact_id, low_artifact_sha256, low_artifact_readback_object_sha256, receipt_object_sha256, payload_json",
            &bake_receipt_id,
        )?;
        let cage = read_production_weapon_high_low_bake_preflight_child(
            connection,
            "production_weapon_high_low_bake_cage",
            "cage_artifact_id, cage_artifact_sha256, cage_artifact_readback_object_sha256, receipt_object_sha256, payload_json",
            &bake_receipt_id,
        )?;
        let correspondence = read_production_weapon_high_low_bake_preflight_child(
            connection,
            "production_weapon_high_low_bake_correspondence",
            "correspondence_id, mapping_object_sha256, receipt_object_sha256, payload_json",
            &bake_receipt_id,
        )?;
        let plan = read_production_weapon_high_low_bake_preflight_child(
            connection,
            "production_weapon_high_low_bake_plan",
            "bake_plan_id, plan_object_sha256, receipt_object_sha256, payload_json",
            &bake_receipt_id,
        )?;
        let diagnostic = read_production_weapon_high_low_bake_preflight_child(
            connection,
            "production_weapon_high_low_bake_diagnostic",
            "diagnostic_id, diagnostic_object_sha256, receipt_object_sha256, payload_json",
            &bake_receipt_id,
        )?;
        let receipt = read_production_weapon_high_low_bake_preflight_child(
            connection,
            "production_weapon_high_low_bake_receipts",
            "bake_receipt_id, payload_json",
            &bake_receipt_id,
        )?;

        let high_exists = production_weapon_high_low_preflight_validate_child(
            connection,
            cas,
            high.as_ref(),
            &bake_receipt_id,
            &receipt_object_sha256,
            "high",
            None,
            &[
                ("high_artifact_sha256", 1),
                ("high_artifact_readback_object_sha256", 2),
            ],
            Some(3),
            4,
        )?;
        let low_exists = production_weapon_high_low_preflight_validate_child(
            connection,
            cas,
            low.as_ref(),
            &bake_receipt_id,
            &receipt_object_sha256,
            "low",
            None,
            &[
                ("low_artifact_sha256", 1),
                ("low_artifact_readback_object_sha256", 2),
            ],
            Some(3),
            4,
        )?;
        let cage_exists = production_weapon_high_low_preflight_validate_child(
            connection,
            cas,
            cage.as_ref(),
            &bake_receipt_id,
            &receipt_object_sha256,
            "cage",
            None,
            &[
                ("cage_artifact_sha256", 1),
                ("cage_artifact_readback_object_sha256", 2),
            ],
            Some(3),
            4,
        )?;
        if cage_exists
            && production_weapon_high_low_preflight_row_value(cage.as_ref(), 1)
                != Some(cage_artifact_sha256.as_str())
        {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_PREFLIGHT_BINDING_MISMATCH",
                format!("bake link {bake_receipt_id} cage hash differs from its child"),
            ));
        }
        let correspondence_exists = production_weapon_high_low_preflight_validate_child(
            connection,
            cas,
            correspondence.as_ref(),
            &bake_receipt_id,
            &receipt_object_sha256,
            "correspondence",
            None,
            &[("mapping_object_sha256", 1)],
            Some(2),
            3,
        )?;
        let plan_exists = production_weapon_high_low_preflight_validate_child(
            connection,
            cas,
            plan.as_ref(),
            &bake_receipt_id,
            &receipt_object_sha256,
            "plan",
            None,
            &[("plan_object_sha256", 1)],
            Some(2),
            3,
        )?;
        let diagnostic_exists = production_weapon_high_low_preflight_validate_child(
            connection,
            cas,
            diagnostic.as_ref(),
            &bake_receipt_id,
            &receipt_object_sha256,
            "diagnostic",
            None,
            &[("diagnostic_object_sha256", 1)],
            Some(2),
            3,
        )?;
        let receipt_exists = production_weapon_high_low_preflight_validate_child(
            connection,
            cas,
            receipt.as_ref(),
            &bake_receipt_id,
            &receipt_object_sha256,
            "receipt",
            Some(&bake_receipt_id),
            &[],
            None,
            1,
        )?;
        // This projection proves only row/CAS presence.  Typed record,
        // canonical, role and bake-policy validation remains a separate formal
        // producer/get gate, so presence must never be promoted to completion.
        let formal_rows_present = high_exists
            && low_exists
            && cage_exists
            && correspondence_exists
            && plan_exists
            && diagnostic_exists
            && receipt_exists;
        summaries.push(ProductionWeaponHighLowBakePreflightSourceSummary {
            bake_receipt_id,
            link_exists: true,
            high_exists,
            low_exists,
            cage_exists,
            correspondence_exists,
            plan_exists,
            diagnostic_exists,
            receipt_exists,
            formal_rows_present,
            canonical_sha256,
            receipt_object_sha256,
            cage_artifact_sha256,
            high_artifact_sha256: production_weapon_high_low_preflight_row_value(high.as_ref(), 1)
                .map(str::to_owned),
            high_artifact_readback_object_sha256: production_weapon_high_low_preflight_row_value(
                high.as_ref(),
                2,
            )
            .map(str::to_owned),
            low_artifact_sha256: production_weapon_high_low_preflight_row_value(low.as_ref(), 1)
                .map(str::to_owned),
            low_artifact_readback_object_sha256: production_weapon_high_low_preflight_row_value(
                low.as_ref(),
                2,
            )
            .map(str::to_owned),
            cage_artifact_readback_object_sha256: production_weapon_high_low_preflight_row_value(
                cage.as_ref(),
                2,
            )
            .map(str::to_owned),
            correspondence_object_sha256: production_weapon_high_low_preflight_row_value(
                correspondence.as_ref(),
                1,
            )
            .map(str::to_owned),
            bake_plan_object_sha256: production_weapon_high_low_preflight_row_value(
                plan.as_ref(),
                1,
            )
            .map(str::to_owned),
            diagnostic_object_sha256: production_weapon_high_low_preflight_row_value(
                diagnostic.as_ref(),
                1,
            )
            .map(str::to_owned),
        });
    }
    Ok(summaries)
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct CrossViewEvidenceCasRef {
    view_kind: String,
    side: String,
    role: String,
    object_sha256: String,
}

fn validate_cross_view_evidence_record(
    evidence: &CrossViewEvidenceRecord,
) -> Result<(), StoreError> {
    if !is_sha256(&evidence.bundle_object_sha256)
        || !is_opaque_id(&evidence.candidate_id)
        || !is_opaque_id(&evidence.project_id)
        || !is_opaque_id(&evidence.session_id)
        || !is_sha256(&evidence.reference_canvas_sha256)
        || !matches!(
            evidence.aggregate_status.as_str(),
            "PARTIAL_VISIBLE_VIEW_PASS" | "QUALITY_TARGET_NOT_MET" | "BLOCKED_REFERENCE_COVERAGE"
        )
        || evidence.created_at.is_empty()
        || evidence.updated_at.is_empty()
        || evidence.created_at.len() > 128
        || evidence.updated_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "cross-view evidence identity or status is invalid".to_owned(),
        ));
    }
    Ok(())
}

fn read_cross_view_evidence_row(
    row: &rusqlite::Row<'_>,
) -> Result<CrossViewEvidenceRecord, rusqlite::Error> {
    Ok(CrossViewEvidenceRecord {
        bundle_object_sha256: row.get(0)?,
        candidate_id: row.get(1)?,
        project_id: row.get(2)?,
        session_id: row.get(3)?,
        reference_canvas_sha256: row.get(4)?,
        aggregate_status: row.get(5)?,
        hard_gate_passed: row.get::<_, i64>(6)? != 0,
        created_at: row.get(7)?,
        updated_at: row.get(8)?,
    })
}

fn read_cross_view_evidence_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    bundle_object_sha256: &str,
) -> Result<Option<CrossViewEvidenceRecord>, StoreError> {
    Ok(transaction
        .query_row(
            "SELECT bundle_object_sha256, candidate_id, project_id, session_id, reference_canvas_sha256, aggregate_status, hard_gate_passed, created_at, updated_at FROM cross_view_evidence WHERE bundle_object_sha256 = ?1",
            params![bundle_object_sha256],
            read_cross_view_evidence_row,
        )
        .optional()?)
}

fn read_cross_view_evidence_by_identity_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    project_id: &str,
    session_id: &str,
    candidate_id: &str,
    reference_canvas_sha256: &str,
) -> Result<Option<CrossViewEvidenceRecord>, StoreError> {
    Ok(transaction
        .query_row(
            "SELECT bundle_object_sha256, candidate_id, project_id, session_id, reference_canvas_sha256, aggregate_status, hard_gate_passed, created_at, updated_at FROM cross_view_evidence WHERE project_id = ?1 AND session_id = ?2 AND candidate_id = ?3 AND reference_canvas_sha256 = ?4 ORDER BY updated_at DESC, bundle_object_sha256 ASC LIMIT 1",
            params![project_id, session_id, candidate_id, reference_canvas_sha256],
            read_cross_view_evidence_row,
        )
        .optional()?)
}

fn read_cross_view_bundle_object(
    transaction: &rusqlite::Transaction<'_>,
    sha256: &str,
) -> Result<CasObjectRecord, StoreError> {
    transaction
        .query_row(
            "SELECT sha256, size_bytes, mime, kind, reachability, created_at FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| {
                let size = row.get::<_, i64>(1)?;
                Ok(CasObjectRecord {
                    schema_version: "CasObject@1".to_owned(),
                    sha256: row.get(0)?,
                    size_bytes: u64::try_from(size).map_err(|_| {
                        rusqlite::Error::FromSqlConversionFailure(
                            1,
                            rusqlite::types::Type::Integer,
                            "negative CrossView bundle size".into(),
                        )
                    })?,
                    mime: row.get(2)?,
                    kind: row.get(3)?,
                    reachability: row.get(4)?,
                    created_at: row.get(5)?,
                })
            },
        )
        .optional()?
        .ok_or_else(|| StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_CAS_MISSING".to_owned(),
            message: "CrossViewEvidenceBundle CAS object is not registered".to_owned(),
        })
}

fn same_cross_view_evidence(
    existing: &CrossViewEvidenceRecord,
    incoming: &CrossViewEvidenceRecord,
) -> bool {
    existing.bundle_object_sha256 == incoming.bundle_object_sha256
        && existing.candidate_id == incoming.candidate_id
        && existing.project_id == incoming.project_id
        && existing.session_id == incoming.session_id
        && existing.reference_canvas_sha256 == incoming.reference_canvas_sha256
        && existing.aggregate_status == incoming.aggregate_status
        && existing.hard_gate_passed == incoming.hard_gate_passed
}

fn ensure_cross_view_evidence_bundle_binding(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    evidence: &CrossViewEvidenceRecord,
    bundle_object: &CasObjectRecord,
    require_reachable: bool,
) -> Result<Vec<CrossViewEvidenceCasRef>, StoreError> {
    validate_cross_view_evidence_record(evidence)?;
    if bundle_object.schema_version != "CasObject@1"
        || bundle_object.sha256 != evidence.bundle_object_sha256
        || bundle_object.mime != "application/json"
        || bundle_object.kind != "cross-view-evidence-bundle"
        || bundle_object.size_bytes == 0
        || bundle_object.size_bytes > MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES
        || !matches!(
            bundle_object.reachability.as_str(),
            "temporary" | "reachable"
        )
        || (require_reachable && bundle_object.reachability != "reachable")
        || bundle_object.created_at.is_empty()
    {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_CAS_METADATA_INVALID".to_owned(),
            message: "CrossViewEvidenceBundle CAS metadata is invalid".to_owned(),
        });
    }
    let stored = read_cross_view_bundle_object(transaction, &bundle_object.sha256)?;
    if stored.size_bytes != bundle_object.size_bytes
        || stored.mime != bundle_object.mime
        || stored.kind != bundle_object.kind
        || (require_reachable && stored.reachability != "reachable")
    {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_CAS_METADATA_INVALID".to_owned(),
            message: "CrossViewEvidenceBundle SQLite metadata differs".to_owned(),
        });
    }
    cas.verify(&bundle_object.sha256, bundle_object.size_bytes)?;
    let bytes = cas.read_verified_bounded(
        &bundle_object.sha256,
        MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
    )?;
    let bundle: Value = serde_json::from_slice(&bytes).map_err(|error| StoreError::Contract {
        code: "CROSS_VIEW_EVIDENCE_JSON_INVALID".to_owned(),
        message: format!("CrossViewEvidenceBundle JSON is invalid: {error}"),
    })?;
    ensure_form_quality_cross_view_structure(&bundle)?;
    let supplied_canonical = bundle
        .get("canonical_sha256")
        .and_then(Value::as_str)
        .ok_or_else(|| StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_CANONICAL_MISMATCH".to_owned(),
            message: "CrossViewEvidenceBundle canonical hash is missing".to_owned(),
        })?;
    let mut canonical = bundle.clone();
    canonical["canonical_sha256"] = Value::String(String::new());
    let canonical_matches = canonical_json_hash(&canonical) == supplied_canonical;
    let project_matches =
        bundle.get("project_id").and_then(Value::as_str) == Some(&evidence.project_id);
    let session_matches =
        bundle.get("session_id").and_then(Value::as_str) == Some(&evidence.session_id);
    let candidate_matches =
        bundle.get("candidate_id").and_then(Value::as_str) == Some(&evidence.candidate_id);
    let canvas_matches = bundle
        .get("reference_canvas_sha256")
        .and_then(Value::as_str)
        == Some(&evidence.reference_canvas_sha256);
    let aggregate_matches =
        bundle.get("aggregate_status").and_then(Value::as_str) == Some(&evidence.aggregate_status);
    let hard_gate_matches =
        bundle.get("hard_gate_passed").and_then(Value::as_bool) == Some(evidence.hard_gate_passed);
    if !canonical_matches
        || !project_matches
        || !session_matches
        || !candidate_matches
        || !canvas_matches
        || !aggregate_matches
        || !hard_gate_matches
    {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_BINDING_MISMATCH".to_owned(),
            message: format!(
                "CrossViewEvidenceBundle binding differs: canonical={canonical_matches} project={project_matches} session={session_matches} candidate={candidate_matches} canvas={canvas_matches} aggregate={aggregate_matches} hard_gate={hard_gate_matches}"
            ),
        });
    }

    let candidate: Option<(String, String, String)> = transaction
        .query_row(
            "SELECT project_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
            params![evidence.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    let Some((candidate_project, artifact_sha256, candidate_state_sha256)) = candidate else {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_CANDIDATE_MISSING".to_owned(),
            message: "CrossView candidate is unavailable".to_owned(),
        });
    };
    if candidate_project != evidence.project_id
        || bundle.get("artifact_sha256").and_then(Value::as_str) != Some(&artifact_sha256)
        || bundle.get("candidate_state_sha256").and_then(Value::as_str)
            != Some(&candidate_state_sha256)
    {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_CANDIDATE_BINDING_MISMATCH".to_owned(),
            message: "CrossView candidate state or artifact binding differs".to_owned(),
        });
    }
    let program_sha256: Option<String> = transaction
        .query_row(
            "SELECT geometry_program_sha256 FROM geometry_candidate_evidence WHERE candidate_id = ?1 AND project_id = ?2",
            params![evidence.candidate_id, evidence.project_id],
            |row| row.get(0),
        )
        .optional()?;
    if program_sha256.as_deref() != bundle.get("program_sha256").and_then(Value::as_str) {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_PROGRAM_BINDING_MISMATCH".to_owned(),
            message: "CrossView GeometryProgram binding differs".to_owned(),
        });
    }
    let evaluations = bundle["view_evaluations"]
        .as_array()
        .expect("CrossView structure already checked");
    let mut baseline_candidate_id: Option<String> = None;
    for evaluation in evaluations {
        let view_id = evaluation["view_id"]
            .as_str()
            .expect("CrossView structure already checked");
        for (side, field, expected_candidate_id) in [
            ("baseline", "baseline_render_set_sha256", None),
            (
                "proposal",
                "proposal_render_set_sha256",
                Some(evidence.candidate_id.as_str()),
            ),
        ] {
            let render_set_sha256 = evaluation[field]
                .as_str()
                .expect("CrossView structure already checked");
            let render_set = form_quality_json_object(
                transaction,
                cas,
                render_set_sha256,
                field,
                Some(PRODUCTION_WEAPON_FORM_QUALITY_RENDER_SET_KIND),
                require_reachable,
            )?;
            let child_candidate_id = render_set
                .get("candidate_id")
                .and_then(Value::as_str)
                .filter(|value| is_opaque_id(value))
                .ok_or_else(|| StoreError::Contract {
                    code: "CROSS_VIEW_EVIDENCE_CHILD_BINDING_MISMATCH".to_owned(),
                    message: format!("CrossView {side} RenderSet candidate is invalid"),
                })?;
            let child_view_id = render_set
                .get("view_id")
                .and_then(Value::as_str)
                .filter(|value| is_opaque_id(value));
            let reference_id = evaluation["reference_id"]
                .as_str()
                .expect("CrossView structure already checked");
            let camera_hash = evaluation["camera_hash"]
                .as_str()
                .expect("CrossView structure already checked");
            if child_view_id.is_none()
                || (side == "proposal" && child_view_id != Some(view_id))
                || render_set.get("reference_id").and_then(Value::as_str) != Some(reference_id)
                || render_set.get("camera_hash").and_then(Value::as_str) != Some(camera_hash)
                || expected_candidate_id.is_some_and(|expected| expected != child_candidate_id)
            {
                return Err(StoreError::Contract {
                    code: "CROSS_VIEW_EVIDENCE_CHILD_BINDING_MISMATCH".to_owned(),
                    message: format!("CrossView {side} RenderSet binding differs"),
                });
            }
            if side == "baseline" {
                if baseline_candidate_id
                    .as_deref()
                    .is_some_and(|expected| expected != child_candidate_id)
                {
                    return Err(StoreError::Contract {
                        code: "CROSS_VIEW_EVIDENCE_BASELINE_BINDING_MISMATCH".to_owned(),
                        message: "CrossView baseline candidate differs between views".to_owned(),
                    });
                }
                baseline_candidate_id = Some(child_candidate_id.to_owned());
            }
        }
    }
    let baseline_candidate_id = baseline_candidate_id.ok_or_else(|| StoreError::Contract {
        code: "CROSS_VIEW_EVIDENCE_BASELINE_MISSING".to_owned(),
        message: "CrossView baseline candidate is unavailable".to_owned(),
    })?;
    let baseline: Option<(String, String)> = transaction
        .query_row(
            "SELECT project_id, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
            params![baseline_candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((baseline_project, baseline_state)) = baseline else {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_BASELINE_MISSING".to_owned(),
            message: "CrossView baseline candidate is unavailable".to_owned(),
        });
    };
    let session: Option<(String, String, String, String)> = transaction
        .query_row(
            "SELECT project_id, candidate_id, candidate_state_sha256, payload_json FROM agentic_design_sessions WHERE session_id = ?1",
            params![evidence.session_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((session_project, session_candidate, session_state, session_payload)) = session else {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_SESSION_MISSING".to_owned(),
            message: "CrossView AgenticSession is unavailable".to_owned(),
        });
    };
    let session_value: Value =
        serde_json::from_str(&session_payload).map_err(|error| StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_SESSION_INVALID".to_owned(),
            message: format!("CrossView AgenticSession payload is invalid: {error}"),
        })?;
    if session_project != evidence.project_id
        || baseline_project != evidence.project_id
        || session_candidate != baseline_candidate_id
        || session_state != baseline_state
        || session_value
            .get("reference_canvas_sha256")
            .and_then(Value::as_str)
            != Some(&evidence.reference_canvas_sha256)
    {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_SESSION_BINDING_MISMATCH".to_owned(),
            message: "CrossView AgenticSession binding differs".to_owned(),
        });
    }

    let mut refs = vec![CrossViewEvidenceCasRef {
        view_kind: "__bundle__".to_owned(),
        side: "bundle".to_owned(),
        role: "bundle".to_owned(),
        object_sha256: evidence.bundle_object_sha256.clone(),
    }];
    for evaluation in evaluations {
        let view_kind = evaluation["kind"]
            .as_str()
            .expect("CrossView structure already checked")
            .to_owned();
        for (side, role, field, expected_kind) in [
            (
                "baseline",
                "render-set",
                "baseline_render_set_sha256",
                PRODUCTION_WEAPON_FORM_QUALITY_RENDER_SET_KIND,
            ),
            (
                "baseline",
                "comparison-report",
                "baseline_comparison_report_sha256",
                PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_KIND,
            ),
            (
                "baseline",
                "quality-report",
                "baseline_quality_report_sha256",
                PRODUCTION_WEAPON_FORM_QUALITY_QUALITY_REPORT_KIND,
            ),
            (
                "proposal",
                "render-set",
                "proposal_render_set_sha256",
                PRODUCTION_WEAPON_FORM_QUALITY_RENDER_SET_KIND,
            ),
            (
                "proposal",
                "comparison-report",
                "proposal_comparison_report_sha256",
                PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_KIND,
            ),
            (
                "proposal",
                "quality-report",
                "proposal_quality_report_sha256",
                PRODUCTION_WEAPON_FORM_QUALITY_QUALITY_REPORT_KIND,
            ),
        ] {
            let sha256 = evaluation[field]
                .as_str()
                .expect("CrossView structure already checked");
            let object = read_form_quality_object(
                transaction,
                cas,
                sha256,
                field,
                Some(expected_kind),
                require_reachable,
                MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
            )?;
            if object.mime != "application/json" {
                return Err(StoreError::Contract {
                    code: "CROSS_VIEW_EVIDENCE_CHILD_MIME_INVALID".to_owned(),
                    message: format!("CrossView child {field} is not JSON"),
                });
            }
            refs.push(CrossViewEvidenceCasRef {
                view_kind: view_kind.clone(),
                side: side.to_owned(),
                role: role.to_owned(),
                object_sha256: sha256.to_owned(),
            });
        }
    }
    Ok(refs)
}

fn insert_cross_view_evidence_cas_refs(
    transaction: &rusqlite::Transaction<'_>,
    evidence: &CrossViewEvidenceRecord,
    refs: &[CrossViewEvidenceCasRef],
) -> Result<(), StoreError> {
    for reference in refs {
        transaction.execute(
            "INSERT INTO cross_view_evidence_cas_refs (bundle_object_sha256, view_kind, side, role, object_sha256) VALUES (?1, ?2, ?3, ?4, ?5)",
            params![
                evidence.bundle_object_sha256,
                reference.view_kind,
                reference.side,
                reference.role,
                reference.object_sha256,
            ],
        )?;
    }
    Ok(())
}

fn ensure_cross_view_evidence_cas_refs(
    transaction: &rusqlite::Transaction<'_>,
    evidence: &CrossViewEvidenceRecord,
    expected: &[CrossViewEvidenceCasRef],
) -> Result<(), StoreError> {
    let mut statement = transaction.prepare(
        "SELECT view_kind, side, role, object_sha256 FROM cross_view_evidence_cas_refs WHERE bundle_object_sha256 = ?1 ORDER BY view_kind, side, role",
    )?;
    let rows = statement.query_map(params![evidence.bundle_object_sha256], |row| {
        Ok(CrossViewEvidenceCasRef {
            view_kind: row.get(0)?,
            side: row.get(1)?,
            role: row.get(2)?,
            object_sha256: row.get(3)?,
        })
    })?;
    let actual = rows.collect::<Result<std::collections::BTreeSet<_>, _>>()?;
    let expected = expected
        .iter()
        .cloned()
        .collect::<std::collections::BTreeSet<_>>();
    if actual != expected {
        return Err(StoreError::Contract {
            code: "CROSS_VIEW_EVIDENCE_CAS_REFS_MISMATCH".to_owned(),
            message: "CrossView durable CAS dependency set differs".to_owned(),
        });
    }
    Ok(())
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProductionCameraLockPrepared {
    record: ProductionCameraLockRecord,
    payload_json: String,
}

fn validate_production_weapon_form_quality_evidence_binding(
    binding: &ProductionWeaponFormQualityEvidenceBinding,
    cross_view_sha256: &str,
    design_spec_sha256: &str,
) -> Result<(), StoreError> {
    if !matches!(
        binding.source_kind.as_str(),
        "cross-view-evidence-bundle" | "design-spec" | "not-proven"
    ) || !matches!(
        binding.status.as_str(),
        "PASS" | "QUALITY_TARGET_NOT_MET" | "NOT_PROVEN" | "BLOCKED"
    ) {
        return Err(StoreError::InvalidData(
            "ProductionWeaponFormQuality evidence binding is malformed".to_owned(),
        ));
    }
    match binding.source_kind.as_str() {
        "not-proven" => {
            if binding.source_object_sha256.is_some()
                || binding.evidence_object_sha256.is_some()
                || binding.status != "NOT_PROVEN"
            {
                return Err(StoreError::Contract {
                    code: "PRODUCTION_WEAPON_FORM_QUALITY_EVIDENCE_NOT_PROVEN_MISMATCH".to_owned(),
                    message: "NOT_PROVEN evidence must not claim a source or evidence object"
                        .to_owned(),
                });
            }
        }
        "cross-view-evidence-bundle" => {
            if binding.source_object_sha256.as_deref() != Some(cross_view_sha256)
                || binding
                    .evidence_object_sha256
                    .as_deref()
                    .is_none_or(|hash| !is_sha256(hash))
            {
                return Err(StoreError::Contract {
                    code: "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVIDENCE_MISMATCH".to_owned(),
                    message: "form evidence is not bound to the CrossView bundle".to_owned(),
                });
            }
        }
        "design-spec" => {
            if binding.source_object_sha256.as_deref() != Some(design_spec_sha256)
                || binding
                    .evidence_object_sha256
                    .as_deref()
                    .is_none_or(|hash| !is_sha256(hash))
            {
                return Err(StoreError::Contract {
                    code: "PRODUCTION_WEAPON_FORM_QUALITY_DESIGN_SPEC_EVIDENCE_MISMATCH".to_owned(),
                    message: "form evidence is not bound to the DesignSpec".to_owned(),
                });
            }
        }
        _ => unreachable!(),
    }
    Ok(())
}

fn validate_production_weapon_form_quality(
    record: &ProductionWeaponFormQualityRecord,
) -> Result<(), StoreError> {
    let ids = [
        record.form_quality_id.as_str(),
        record.session_id.as_str(),
        record.project_id.as_str(),
        record.camera_calibrated_head_transition_id.as_str(),
        record.camera_calibrated_head_candidate_id.as_str(),
        record.camera_calibrated_head_artifact_id.as_str(),
        record.candidate_id.as_str(),
        record.artifact_id.as_str(),
        record.reference_id.as_str(),
        record.camera_lock_id.as_str(),
        record.camera_lock_source_transition_id.as_str(),
    ];
    let hashes = [
        record.camera_calibrated_head_transition_sha256.as_str(),
        record.camera_calibrated_head_canonical_sha256.as_str(),
        record
            .camera_calibrated_head_candidate_state_sha256
            .as_str(),
        record.camera_calibrated_head_artifact_sha256.as_str(),
        record.candidate_state_sha256.as_str(),
        record.artifact_sha256.as_str(),
        record.reference_sha256.as_str(),
        record.reference_canvas_object_sha256.as_str(),
        record.reference_canvas_canonical_sha256.as_str(),
        record.design_spec_object_sha256.as_str(),
        record.design_spec_canonical_sha256.as_str(),
        record.camera_lock_canonical_sha256.as_str(),
        record.camera_rig_object_sha256.as_str(),
        record.camera_rig_canonical_sha256.as_str(),
        record.camera_lock_receipt_object_sha256.as_str(),
        record.camera_lock_source_transition_sha256.as_str(),
        record.camera_lock_source_head_canonical_sha256.as_str(),
        record.cross_view_evidence_object_sha256.as_str(),
        record.cross_view_evidence_canonical_sha256.as_str(),
        record.form_evidence_object_sha256.as_str(),
        record.form_evidence_canonical_sha256.as_str(),
        record.form_quality_policy_sha256.as_str(),
        record.threshold_policy_sha256.as_str(),
        record.request_sha256.as_str(),
        record.input_sha256.as_str(),
        record.canonical_sha256.as_str(),
    ];
    let previous_valid = match (
        record.previous_form_quality_id.as_deref(),
        record.previous_form_quality_report_object_sha256.as_deref(),
        record.previous_form_quality_canonical_sha256.as_deref(),
    ) {
        (None, None, None) => true,
        (Some(id), Some(report), Some(canonical)) => {
            is_opaque_id(id) && is_sha256(report) && is_sha256(canonical)
        }
        _ => false,
    };
    let expected_stage = PRODUCTION_WEAPON_FORM_QUALITY_FORM_STAGES
        .iter()
        .position(|stage| *stage == record.form_stage);
    let expected_reviewed = PRODUCTION_WEAPON_FORM_QUALITY_REVIEWED_REFERENCE_VIEW_KINDS
        .iter()
        .map(|value| (*value).to_owned())
        .collect::<Vec<_>>();
    let expected_fixed = PRODUCTION_WEAPON_FORM_QUALITY_FIXED_CAMERA_VIEW_KINDS
        .iter()
        .map(|value| (*value).to_owned())
        .collect::<Vec<_>>();
    let expected_source = expected_stage
        .and_then(|index| PRODUCTION_WEAPON_FORM_QUALITY_SOURCE_STAGES.get(index))
        .copied();
    let expected_target = expected_stage
        .and_then(|index| PRODUCTION_WEAPON_FORM_QUALITY_TARGET_STAGES.get(index))
        .copied();
    let expected_views = expected_reviewed.clone();
    let previous_binding_expected = if record.form_stage == "blockout" {
        true
    } else {
        previous_valid
    };
    let views_ok = record.form_view_evaluations.len() == expected_views.len()
        && record
            .form_view_evaluations
            .iter()
            .zip(expected_views.iter())
            .all(|(view, expected)| {
                let current_not_proven = |binding: &ProductionWeaponFormQualityEvidenceBinding| {
                    binding.source_kind == "not-proven"
                        && binding.source_object_sha256.is_none()
                        && binding.evidence_object_sha256.is_none()
                        && binding.status == "NOT_PROVEN"
                };
                view.view_kind == *expected
                    && is_opaque_id(&view.view_id)
                    && validate_production_weapon_form_quality_evidence_binding(
                        &view.part_id_evidence.source,
                        &record.cross_view_evidence_object_sha256,
                        &record.design_spec_object_sha256,
                    )
                    .is_ok()
                    && validate_production_weapon_form_quality_evidence_binding(
                        &view.negative_space_evidence.source,
                        &record.cross_view_evidence_object_sha256,
                        &record.design_spec_object_sha256,
                    )
                    .is_ok()
                    && validate_production_weapon_form_quality_evidence_binding(
                        &view.line_flow_evidence.source,
                        &record.cross_view_evidence_object_sha256,
                        &record.design_spec_object_sha256,
                    )
                    .is_ok()
                    // ProductionWeaponFormQuality@1 has no Runtime-owned
                    // Part-ID, negative-space or line-flow receipt yet.  Do
                    // not let a direct Store caller turn diagnostic arrays
                    // into visual truth.
                    && current_not_proven(&view.part_id_evidence.source)
                    && current_not_proven(&view.negative_space_evidence.source)
                    && current_not_proven(&view.line_flow_evidence.source)
                    && matches!(
                        view.no_regression.status.as_str(),
                        "NOT_APPLICABLE" | "NOT_PROVEN" | "PASS" | "FAILED"
                    )
            });
    let hard_gate_all = record.hard_gate.stage_head_binding
        && record.hard_gate.camera_lock_binding
        && record.hard_gate.same_candidate_artifact
        && record.hard_gate.reviewed_reference_views
        && record.hard_gate.fixed_camera_views
        && record.hard_gate.cross_view_evidence_binding
        && record.hard_gate.form_view_evaluations
        && record.hard_gate.part_id_evidence
        && record.hard_gate.negative_space_evidence
        && record.hard_gate.line_flow_evidence
        && record.hard_gate.threshold_policy_binding;
    let form_gate_all = record.form_gate.layer_status == record.layer_status
        && record.form_gate.all_view_thresholds
        && record.form_gate.all_view_no_regression
        && record.form_gate.previous_form_quality_binding == previous_binding_expected;
    if record.schema_version != PRODUCTION_WEAPON_FORM_QUALITY_SCHEMA_VERSION
        || ids.iter().any(|value| !is_opaque_id(value))
        || hashes.iter().any(|value| !is_sha256(value))
        || record.camera_calibrated_head_stage != "camera-calibrated"
        || expected_source != Some(record.source_stage.as_str())
        || expected_target != Some(record.target_stage.as_str())
        || record.reviewed_reference_view_kinds != expected_reviewed
        || record.fixed_camera_view_kinds != expected_fixed
        || record.cross_view_evidence_view_kinds != expected_views
        || !views_ok
        || !previous_valid
        || record.hard_gate.part_id_evidence
        || record.hard_gate.negative_space_evidence
        || record.hard_gate.line_flow_evidence
        || record.hard_gate_passed
        || record.validator_status != "failed"
        || record.form_gate_passed
        || record.layer_status != "QUALITY_TARGET_NOT_MET"
        || record.visual_status != "QUALITY_TARGET_NOT_MET"
        || record.hard_gate_passed != hard_gate_all
        || (record.validator_status == "passed" && (!record.hard_gate_passed || !hard_gate_all))
        || record.form_gate_passed != (record.hard_gate_passed && form_gate_all)
        || (record.form_gate_passed
            && (record.layer_status != "PASS_STAGE_VISUAL"
                || record.visual_status != "PASS_STAGE_VISUAL"))
        || (record.form_stage == "blockout"
            && (record.previous_form_quality_id.is_some()
                || record.previous_form_quality_report_object_sha256.is_some()
                || record.previous_form_quality_canonical_sha256.is_some()))
        || (record.form_stage != "blockout"
            && (record.previous_form_quality_id.is_none()
                || record.previous_form_quality_report_object_sha256.is_none()
                || record.previous_form_quality_canonical_sha256.is_none()))
        || record.form_quality_policy != PRODUCTION_WEAPON_FORM_QUALITY_POLICY
        || record.threshold_policy != PRODUCTION_WEAPON_FORM_QUALITY_THRESHOLD_POLICY
        || !matches!(
            record.layer_status.as_str(),
            "NOT_RUN" | "BLOCKED" | "QUALITY_TARGET_NOT_MET" | "PASS_STAGE_VISUAL"
        )
        || !matches!(record.validator_status.as_str(), "passed" | "failed")
        || !matches!(
            record.structural_status.as_str(),
            "NOT_RUN" | "BLOCKED" | "PASS_SOURCE_STRUCTURAL"
        )
        || !matches!(
            record.visual_status.as_str(),
            "NOT_RUN" | "BLOCKED" | "QUALITY_TARGET_NOT_MET" | "PASS_STAGE_VISUAL"
        )
        || !matches!(
            record.human_status.as_str(),
            "NOT_RUN" | "BLOCKED" | "REJECTED" | "PASS_HUMAN_ART_REVIEW"
        )
        || !matches!(
            record.engine_status.as_str(),
            "NOT_RUN" | "BLOCKED" | "FAILED" | "PASS_ENGINE_VALIDATION"
        )
        || !matches!(
            record.distribution_status.as_str(),
            "NOT_RUN" | "BLOCKED" | "FAILED" | "PASS_DISTRIBUTION"
        )
        || record.quality_status != "structural_only"
        || !record.runtime_write_performed
        || record.production_stage_advanced
        || record.candidate_confirmed
        || record.version_created
        || record.export_performed
        || record.created_at.is_empty()
        || record.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "ProductionWeaponFormQuality@1 record is malformed".to_owned(),
        ));
    }
    let mut canonical = record.clone();
    canonical.receipt_object_sha256.clear();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if expected != record.canonical_sha256 {
        return Err(StoreError::Contract {
            code: "PRODUCTION_WEAPON_FORM_QUALITY_CANONICAL_MISMATCH".to_owned(),
            message: "ProductionWeaponFormQuality@1 canonical hash differs".to_owned(),
        });
    }
    Ok(())
}

fn production_weapon_form_quality_payload_json(
    record: &ProductionWeaponFormQualityRecord,
) -> Result<String, StoreError> {
    let mut value =
        serde_json::to_value(record).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    value["receipt_object_sha256"] = Value::String(String::new());
    let bytes =
        canonical_json_bytes(&value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if bytes.is_empty() || bytes.len() as u64 > MAX_PRODUCTION_WEAPON_FORM_QUALITY_PAYLOAD_BYTES {
        return Err(StoreError::InvalidData(
            "ProductionWeaponFormQuality@1 payload exceeds its bounded capacity".to_owned(),
        ));
    }
    String::from_utf8(bytes).map_err(|error| StoreError::InvalidData(error.to_string()))
}

fn ensure_production_weapon_form_quality_receipt(
    cas: &CasStore,
    object: &CasObjectRecord,
    payload_json: &str,
) -> Result<(), StoreError> {
    if object.schema_version != "CasObject@1"
        || !is_sha256(&object.sha256)
        || object.mime != PRODUCTION_WEAPON_FORM_QUALITY_JSON_MIME
        || object.kind != PRODUCTION_WEAPON_FORM_QUALITY_RECEIPT_KIND
        || object.size_bytes == 0
        || object.size_bytes > MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES
        || object.size_bytes != payload_json.len() as u64
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || object.created_at.is_empty()
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_WEAPON_FORM_QUALITY_RECEIPT_INVALID".to_owned(),
            message: "form-quality receipt CAS metadata is invalid".to_owned(),
        });
    }
    cas.verify(&object.sha256, object.size_bytes)?;
    let bytes = cas.read_verified_bounded(
        &object.sha256,
        MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
    )?;
    if bytes != payload_json.as_bytes() {
        return Err(StoreError::Contract {
            code: "PRODUCTION_WEAPON_FORM_QUALITY_RECEIPT_BINDING_MISMATCH".to_owned(),
            message: "form-quality receipt bytes differ from its canonical record".to_owned(),
        });
    }
    Ok(())
}

fn form_quality_error(code: &str, message: impl Into<String>) -> StoreError {
    StoreError::Contract {
        code: code.to_owned(),
        message: message.into(),
    }
}

fn read_form_quality_object(
    connection: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    sha256: &str,
    label: &str,
    expected_kind: Option<&str>,
    require_reachable: bool,
    max_bytes: u64,
) -> Result<CasObjectRecord, StoreError> {
    let object: Option<CasObjectRecord> = connection
        .query_row(
            "SELECT sha256, size_bytes, mime, kind, reachability, created_at FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| {
                Ok(CasObjectRecord {
                    schema_version: "CasObject@1".to_owned(),
                    sha256: row.get(0)?,
                    size_bytes: u64::try_from(row.get::<_, i64>(1)?).map_err(|_| {
                        rusqlite::Error::FromSqlConversionFailure(
                            1,
                            rusqlite::types::Type::Integer,
                            format!("negative {label} size").into(),
                        )
                    })?,
                    mime: row.get(2)?,
                    kind: row.get(3)?,
                    reachability: row.get(4)?,
                    created_at: row.get(5)?,
                })
            },
        )
        .optional()?;
    let Some(object) = object else {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CAS_MISSING",
            format!("form-quality {label} object is missing"),
        ));
    };
    if object.size_bytes == 0
        || object.size_bytes > max_bytes
        || !is_sha256(&object.sha256)
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || (require_reachable && object.reachability != "reachable")
        || expected_kind.is_some_and(|kind| {
            object.kind != kind
                && !matches!(
                    (kind, object.kind.as_str()),
                    ("reference-canvas", "agentic-reference-canvas")
                        | ("design-spec", "agentic-design-spec")
                )
        })
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CAS_METADATA_INVALID",
            format!(
                "form-quality {label} object metadata is invalid: expected_kind={:?} actual_kind={} size_bytes={} reachability={}",
                expected_kind, object.kind, object.size_bytes, object.reachability
            ),
        ));
    }
    cas.verify(&object.sha256, object.size_bytes)?;
    Ok(object)
}

fn form_quality_json_object(
    connection: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    sha256: &str,
    label: &str,
    expected_kind: Option<&str>,
    require_reachable: bool,
) -> Result<Value, StoreError> {
    let object = read_form_quality_object(
        connection,
        cas,
        sha256,
        label,
        expected_kind,
        require_reachable,
        MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
    )?;
    if object.mime != PRODUCTION_WEAPON_FORM_QUALITY_JSON_MIME {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_JSON_MIME_INVALID",
            format!("form-quality {label} is not JSON"),
        ));
    }
    let bytes = cas.read_verified_bounded(
        &object.sha256,
        MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
    )?;
    serde_json::from_slice(&bytes).map_err(|error| {
        form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_JSON_INVALID",
            format!("form-quality {label} JSON is invalid: {error}"),
        )
    })
}

fn ensure_form_quality_evidence_object(
    connection: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    binding: &ProductionWeaponFormQualityEvidenceBinding,
    label: &str,
    require_reachable: bool,
) -> Result<(), StoreError> {
    if binding.source_kind == "not-proven" {
        return Ok(());
    }
    let source_hash = binding.source_object_sha256.as_deref().ok_or_else(|| {
        form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_EVIDENCE_SOURCE_MISSING",
            format!("{label} source object is missing"),
        )
    })?;
    let expected_source_kind = match binding.source_kind.as_str() {
        "cross-view-evidence-bundle" => Some("cross-view-evidence-bundle"),
        "design-spec" => Some("design-spec"),
        _ => None,
    };
    if expected_source_kind.is_none() {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_EVIDENCE_SOURCE_INVALID",
            format!("{label} source kind is not supported"),
        ));
    }
    let _ = form_quality_json_object(
        connection,
        cas,
        source_hash,
        label,
        expected_source_kind,
        require_reachable,
    )?;
    let Some(hash) = binding.evidence_object_sha256.as_deref() else {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_EVIDENCE_MISSING",
            format!("{label} evidence object is missing"),
        ));
    };
    let _ = form_quality_json_object(connection, cas, hash, label, None, require_reachable)?;
    Ok(())
}

fn ensure_form_quality_canonical_value(
    value: &Value,
    expected_schema: &str,
    label: &str,
) -> Result<(), StoreError> {
    if value.get("schema_version").and_then(Value::as_str) != Some(expected_schema) {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_VIEW_SCHEMA_INVALID",
            format!("{label} schema is not {expected_schema}"),
        ));
    }
    let supplied = value
        .get("canonical_sha256")
        .and_then(Value::as_str)
        .filter(|hash| is_sha256(hash))
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_VIEW_CANONICAL_INVALID",
                format!("{label} canonical hash is invalid"),
            )
        })?;
    let mut canonical = value.clone();
    canonical["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&canonical) != supplied {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_VIEW_CANONICAL_MISMATCH",
            format!("{label} canonical hash differs from its bytes"),
        ));
    }
    Ok(())
}

fn ensure_form_quality_exact_object(
    value: &Value,
    required: &[&str],
    optional: &[&str],
    label: &str,
) -> Result<(), StoreError> {
    let object = value.as_object().ok_or_else(|| {
        form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_VIEW_OBJECT_INVALID",
            format!("{label} is not an object"),
        )
    })?;
    if required.iter().any(|key| !object.contains_key(*key))
        || object
            .keys()
            .any(|key| !required.contains(&key.as_str()) && !optional.contains(&key.as_str()))
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_VIEW_FIELDS_INVALID",
            format!("{label} fields are not closed"),
        ));
    }
    Ok(())
}

fn ensure_form_quality_render_structure(value: &Value, label: &str) -> Result<(), StoreError> {
    ensure_form_quality_exact_object(
        value,
        &[
            "schema_version",
            "render_set_id",
            "candidate_id",
            "artifact_sha256",
            "program_sha256",
            "reference_id",
            "camera_hash",
            "camera_object_sha256",
            "renderer_hash",
            "render_profile",
            "render_profile_sha256",
            "aov_definition_sha256",
            "color_pipeline_sha256",
            "id_palette_definition_sha256",
            "render_worker_build_cohort_sha256",
            "render_worker_binding_status",
            "width",
            "height",
            "passes",
            "pass_artifacts",
            "canonical_sha256",
        ],
        &["view_id"],
        label,
    )?;
    let object = value.as_object().expect("checked object");
    for key in [
        "artifact_sha256",
        "program_sha256",
        "camera_hash",
        "camera_object_sha256",
        "renderer_hash",
        "render_profile_sha256",
        "aov_definition_sha256",
        "color_pipeline_sha256",
        "id_palette_definition_sha256",
    ] {
        if object
            .get(key)
            .and_then(Value::as_str)
            .is_none_or(|hash| !is_sha256(hash))
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_HASH_INVALID",
                format!("{label}.{key} is invalid"),
            ));
        }
    }
    if object.get("width").and_then(Value::as_u64) != Some(512)
        || object.get("height").and_then(Value::as_u64) != Some(512)
        || !object.get("render_profile").is_some_and(Value::is_object)
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_PROFILE_INVALID",
            format!("{label} render profile or dimensions are invalid"),
        ));
    }
    let expected = [
        "beauty",
        "silhouette",
        "depth",
        "normal",
        "ao",
        "part-id",
        "material-id",
        "wireframe",
        "uv-stretch",
    ];
    let passes = object
        .get("passes")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_PASSES_INVALID",
                format!("{label} has no fixed pass list"),
            )
        })?;
    if passes.iter().map(Value::as_str).collect::<Option<Vec<_>>>() != Some(expected.to_vec()) {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_PASSES_INVALID",
            format!("{label} pass order differs"),
        ));
    }
    let artifacts = object
        .get("pass_artifacts")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_PASSES_INVALID",
                format!("{label} pass artifacts are missing"),
            )
        })?;
    if artifacts.len() != expected.len() {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_PASSES_INVALID",
            format!("{label} pass artifact count differs"),
        ));
    }
    for pass in expected {
        let artifact = artifacts.get(pass).ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_PASSES_INVALID",
                format!("{label} is missing pass {pass}"),
            )
        })?;
        ensure_form_quality_exact_object(
            artifact,
            &[
                "sha256",
                "mime",
                "size_bytes",
                "width",
                "height",
                "channels",
                "color_space",
            ],
            &[],
            &format!("{label}.{pass}"),
        )?;
        let artifact = artifact.as_object().expect("checked object");
        if artifact
            .get("sha256")
            .and_then(Value::as_str)
            .is_none_or(|hash| !is_sha256(hash))
            || artifact.get("mime").and_then(Value::as_str) != Some("image/png")
            || artifact
                .get("size_bytes")
                .and_then(Value::as_u64)
                .unwrap_or(0)
                == 0
            || artifact.get("width").and_then(Value::as_u64) != Some(512)
            || artifact.get("height").and_then(Value::as_u64) != Some(512)
            || artifact.get("channels").and_then(Value::as_str) != Some("rgba8")
            || artifact.get("color_space").and_then(Value::as_str)
                != Some(if pass == "beauty" { "srgb" } else { "data" })
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_PASS_INVALID",
                format!("{label}.{pass} metadata is invalid"),
            ));
        }
    }
    Ok(())
}

fn ensure_form_quality_png_cas_object(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    metadata: &Value,
    expected_kind: &str,
    label: &str,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let object = metadata.as_object().ok_or_else(|| {
        form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_PNG_METADATA_INVALID",
            format!("{label} metadata is not an object"),
        )
    })?;
    let sha256 = object
        .get("sha256")
        .and_then(Value::as_str)
        .filter(|hash| is_sha256(hash))
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_PNG_METADATA_INVALID",
                format!("{label} SHA-256 is invalid"),
            )
        })?;
    let declared_size = object
        .get("size_bytes")
        .and_then(Value::as_u64)
        .filter(|size| *size > 0)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_PNG_METADATA_INVALID",
                format!("{label} size is invalid"),
            )
        })?;
    let object_record = read_form_quality_object(
        transaction,
        cas,
        sha256,
        label,
        Some(expected_kind),
        require_reachable,
        u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
    )?;
    let bytes = cas.read_verified_bounded(
        sha256,
        u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
    )?;
    if object_record.mime != "image/png"
        || object_record.sha256 != sha256
        || object_record.size_bytes != declared_size
        || bytes.len() as u64 != declared_size
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_PNG_METADATA_INVALID",
            format!("{label} CAS metadata or bytes differ from its projection"),
        ));
    }
    Ok(())
}

fn ensure_form_quality_png_cas_hash(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    sha256: &str,
    expected_kind: &str,
    label: &str,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let object_record = read_form_quality_object(
        transaction,
        cas,
        sha256,
        label,
        Some(expected_kind),
        require_reachable,
        u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
    )?;
    let bytes = cas.read_verified_bounded(
        sha256,
        u64::try_from(MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES).unwrap_or(4 * 1024 * 1024),
    )?;
    if object_record.mime != "image/png"
        || object_record.sha256 != sha256
        || bytes.len() as u64 != object_record.size_bytes
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_PNG_METADATA_INVALID",
            format!("{label} CAS metadata or bytes are not a verified PNG"),
        ));
    }
    Ok(())
}

fn ensure_form_quality_render_pass_cas_objects(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    value: &Value,
    label: &str,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let artifacts = value
        .get("pass_artifacts")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_PASSES_INVALID",
                format!("{label} pass artifacts are missing"),
            )
        })?;
    for pass in [
        "beauty",
        "silhouette",
        "depth",
        "normal",
        "ao",
        "part-id",
        "material-id",
        "wireframe",
        "uv-stretch",
    ] {
        let metadata = artifacts.get(pass).ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_PASSES_INVALID",
                format!("{label} is missing pass {pass}"),
            )
        })?;
        ensure_form_quality_png_cas_object(
            transaction,
            cas,
            metadata,
            &format!("render-pass-{pass}"),
            &format!("{label}.{pass}"),
            require_reachable,
        )?;
    }
    Ok(())
}

fn ensure_form_quality_comparison_structure(value: &Value, label: &str) -> Result<(), StoreError> {
    ensure_form_quality_exact_object(
        value,
        &[
            "schema_version",
            "report_id",
            "candidate_id",
            "artifact_sha256",
            "reference_id",
            "reference_sha256",
            "render_set_hash",
            "camera_hash",
            "mask",
            "metrics",
            "status",
            "canonical_sha256",
        ],
        &["benchmark_eligibility", "view_id"],
        label,
    )?;
    let object = value.as_object().expect("checked object");
    if !matches!(
        object.get("status").and_then(Value::as_str),
        Some("PARTIAL_VISIBLE_VIEW_PASS" | "QUALITY_TARGET_NOT_MET" | "BLOCKED_REFERENCE_COVERAGE")
    ) {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_STATUS_INVALID",
            format!("{label} status is invalid"),
        ));
    }
    let mask = object.get("mask").ok_or_else(|| {
        form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_MASK_INVALID",
            format!("{label} mask is missing"),
        )
    })?;
    ensure_form_quality_exact_object(
        mask,
        &["method", "revision", "sha256", "width", "height"],
        &[],
        &format!("{label}.mask"),
    )?;
    let mask = mask.as_object().expect("checked object");
    if mask
        .get("sha256")
        .and_then(Value::as_str)
        .is_none_or(|hash| !is_sha256(hash))
        || mask.get("width").and_then(Value::as_u64) != Some(512)
        || mask.get("height").and_then(Value::as_u64) != Some(512)
        || !matches!(
            mask.get("method").and_then(Value::as_str),
            Some("local-border-flood-fill-morphology" | "silhouette-target")
        )
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_MASK_INVALID",
            format!("{label} mask metadata is invalid"),
        ));
    }
    let metric_names = [
        "silhouette_iou",
        "boundary_f1_4px",
        "bbox_edge_error",
        "centroid_error",
        "landmark_coverage",
        "landmark_nme",
        "region_median_iou",
        "critical_region_min_iou",
    ];
    let metrics = object.get("metrics").ok_or_else(|| {
        form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_METRICS_INVALID",
            format!("{label} metrics are missing"),
        )
    })?;
    ensure_form_quality_exact_object(metrics, &metric_names, &[], &format!("{label}.metrics"))?;
    let metrics = metrics.as_object().expect("checked object");
    if metric_names.iter().any(|name| {
        metrics
            .get(*name)
            .and_then(Value::as_f64)
            .is_none_or(|value| !value.is_finite() || !(0.0..=1.0).contains(&value))
    }) {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_METRICS_INVALID",
            format!("{label} metrics are invalid"),
        ));
    }
    Ok(())
}

fn ensure_form_quality_quality_structure(value: &Value, label: &str) -> Result<(), StoreError> {
    ensure_form_quality_exact_object(
        value,
        &[
            "schema_version",
            "quality_report_id",
            "candidate_id",
            "artifact_sha256",
            "program_sha256",
            "reference_id",
            "reference_sha256",
            "render_set_hash",
            "comparison_report_hash",
            "human_receipt_hash",
            "structural_status",
            "visual_status",
            "hard_gate_passed",
            "threshold_revision",
            "threshold_policy_sha256",
            "threshold_source",
            "metric_gate_results",
            "limitations",
            "canonical_sha256",
        ],
        &["benchmark_eligibility", "view_id"],
        label,
    )?;
    let object = value.as_object().expect("checked object");
    let visual_status = object.get("visual_status").and_then(Value::as_str);
    let hard_gate = object.get("hard_gate_passed").and_then(Value::as_bool);
    if !matches!(
        object.get("structural_status").and_then(Value::as_str),
        Some("passed" | "failed" | "not-run")
    ) || !matches!(
        visual_status,
        Some(
            "PARTIAL_VISIBLE_VIEW_PASS"
                | "QUALITY_TARGET_NOT_MET"
                | "BLOCKED_REFERENCE_COVERAGE"
                | "not-run"
        )
    ) || hard_gate != Some(visual_status == Some("PARTIAL_VISIBLE_VIEW_PASS"))
        || object
            .get("threshold_policy_sha256")
            .and_then(Value::as_str)
            .is_none_or(|hash| !is_sha256(hash))
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_QUALITY_STATUS_INVALID",
            format!("{label} status or threshold binding is invalid"),
        ));
    }
    let gates = object
        .get("metric_gate_results")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_QUALITY_METRICS_INVALID",
                format!("{label} metric gates are missing"),
            )
        })?;
    let mut seen = std::collections::BTreeSet::new();
    for gate in gates {
        ensure_form_quality_exact_object(
            gate,
            &[
                "metric_name",
                "direction",
                "observed",
                "threshold",
                "status",
            ],
            &[],
            &format!("{label}.metric_gate"),
        )?;
        let gate = gate.as_object().expect("checked object");
        let name = gate
            .get("metric_name")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if name.is_empty()
            || !seen.insert(name.to_owned())
            || !matches!(
                gate.get("direction").and_then(Value::as_str),
                Some("min" | "max")
            )
            || gate
                .get("threshold")
                .and_then(Value::as_f64)
                .is_none_or(|value| !value.is_finite())
            || gate.get("observed").is_none_or(|value| {
                !value.is_null() && value.as_f64().is_none_or(|number| !number.is_finite())
            })
            || !matches!(
                gate.get("status").and_then(Value::as_str),
                Some("passed" | "failed" | "not-run")
            )
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_QUALITY_METRICS_INVALID",
                format!("{label} metric gate is invalid"),
            ));
        }
    }
    if object
        .get("limitations")
        .and_then(Value::as_array)
        .is_none_or(|values| {
            values
                .iter()
                .any(|value| value.as_str().is_none_or(str::is_empty))
        })
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_QUALITY_LIMITATIONS_INVALID",
            format!("{label} limitations are invalid"),
        ));
    }
    Ok(())
}

fn ensure_form_quality_view_triplet(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    bundle_view: &Value,
    quality: &ProductionWeaponFormQualityRecord,
    view: &ProductionWeaponFormQualityViewRecord,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let camera_hash = bundle_view
        .get("camera_hash")
        .and_then(Value::as_str)
        .filter(|hash| is_sha256(hash))
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CAMERA_HASH_INVALID",
                "view camera hash is invalid",
            )
        })?;
    let view_id = view.view_id.as_str();
    let reference_id = bundle_view
        .get("reference_id")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_VIEW_REFERENCE_INVALID",
                "view reference id is missing",
            )
        })?;
    let reference_sha = bundle_view
        .get("reference_sha256")
        .and_then(Value::as_str)
        .filter(|hash| is_sha256(hash))
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_VIEW_REFERENCE_INVALID",
                "view reference hash is invalid",
            )
        })?;

    let verify_render = |hash: &str, label: &str| -> Result<Value, StoreError> {
        let render = form_quality_json_object(
            transaction,
            cas,
            hash,
            label,
            Some(PRODUCTION_WEAPON_FORM_QUALITY_RENDER_SET_KIND),
            require_reachable,
        )?;
        ensure_form_quality_canonical_value(&render, "RenderSet@2", label)?;
        ensure_form_quality_render_structure(&render, label)?;
        ensure_form_quality_render_pass_cas_objects(
            transaction,
            cas,
            &render,
            label,
            require_reachable,
        )?;
        if render
            .get("candidate_id")
            .and_then(Value::as_str)
            .is_none_or(|id| !is_opaque_id(id))
            || render.get("candidate_id").and_then(Value::as_str)
                != Some(quality.candidate_id.as_str())
            || render
                .get("artifact_sha256")
                .and_then(Value::as_str)
                .is_none_or(|sha| !is_sha256(sha))
            || render.get("reference_id").and_then(Value::as_str) != Some(reference_id)
            || render.get("camera_hash").and_then(Value::as_str) != Some(camera_hash)
            || render.get("view_id").and_then(Value::as_str) != Some(view_id)
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_BINDING_MISMATCH",
                format!("{label} RenderSet binding differs"),
            ));
        }
        if render
            .get("artifact_sha256")
            .and_then(Value::as_str)
            .is_none_or(|sha| !is_sha256(sha))
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_RENDER_ARTIFACT_INVALID",
                format!("{label} RenderSet artifact hash is invalid"),
            ));
        }
        Ok(render)
    };
    let verify_comparison =
        |hash: &str, label: &str, render: &Value, render_hash: &str| -> Result<Value, StoreError> {
            let comparison = form_quality_json_object(
                transaction,
                cas,
                hash,
                label,
                Some(PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_KIND),
                require_reachable,
            )?;
            ensure_form_quality_canonical_value(&comparison, "ReferenceComparisonReport@1", label)?;
            ensure_form_quality_comparison_structure(&comparison, label)?;
            let mask_sha256 = comparison
                .get("mask")
                .and_then(|value| value.get("sha256"))
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    form_quality_error(
                        "PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_MASK_INVALID",
                        format!("{label} comparison mask is missing"),
                    )
                })?;
            ensure_form_quality_png_cas_hash(
                transaction,
                cas,
                mask_sha256,
                "reference-silhouette-mask-v1",
                &format!("{label}.mask"),
                require_reachable,
            )?;
            if comparison
                .get("candidate_id")
                .and_then(Value::as_str)
                .is_none_or(|id| !is_opaque_id(id))
                || comparison.get("candidate_id").and_then(Value::as_str)
                    != Some(quality.candidate_id.as_str())
                || comparison.get("artifact_sha256").and_then(Value::as_str)
                    != render.get("artifact_sha256").and_then(Value::as_str)
                || comparison.get("reference_id").and_then(Value::as_str) != Some(reference_id)
                || comparison.get("reference_sha256").and_then(Value::as_str) != Some(reference_sha)
                || comparison.get("camera_hash").and_then(Value::as_str) != Some(camera_hash)
                || comparison.get("render_set_hash").and_then(Value::as_str) != Some(render_hash)
                || comparison.get("view_id").and_then(Value::as_str) != Some(view_id)
            {
                return Err(form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_BINDING_MISMATCH",
                    format!("{label} ComparisonReport binding differs"),
                ));
            }
            if comparison.get("candidate_id").and_then(Value::as_str)
                != render.get("candidate_id").and_then(Value::as_str)
            {
                return Err(form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_COMPARISON_CANDIDATE_BINDING_MISMATCH",
                    format!("{label} ComparisonReport candidate differs from RenderSet"),
                ));
            }
            Ok(comparison)
        };
    let verify_quality = |hash: &str,
                          label: &str,
                          render: &Value,
                          render_hash: &str,
                          comparison_hash: &str|
     -> Result<Value, StoreError> {
        let report = form_quality_json_object(
            transaction,
            cas,
            hash,
            label,
            Some(PRODUCTION_WEAPON_FORM_QUALITY_QUALITY_REPORT_KIND),
            require_reachable,
        )?;
        ensure_form_quality_canonical_value(&report, "QualityReport@2", label)?;
        ensure_form_quality_quality_structure(&report, label)?;
        if report.get("candidate_id").and_then(Value::as_str)
            != render.get("candidate_id").and_then(Value::as_str)
            || report.get("artifact_sha256").and_then(Value::as_str)
                != render.get("artifact_sha256").and_then(Value::as_str)
            || report.get("reference_id").and_then(Value::as_str) != Some(reference_id)
            || report.get("reference_sha256").and_then(Value::as_str) != Some(reference_sha)
            || report.get("render_set_hash").and_then(Value::as_str) != Some(render_hash)
            || report.get("comparison_report_hash").and_then(Value::as_str) != Some(comparison_hash)
            || report.get("view_id").and_then(Value::as_str) != Some(view_id)
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_QUALITY_BINDING_MISMATCH",
                format!("{label} QualityReport binding differs"),
            ));
        }
        Ok(report)
    };

    for (prefix, render_field, comparison_field, quality_field) in [
        (
            "baseline",
            "baseline_render_set_sha256",
            "baseline_comparison_report_sha256",
            "baseline_quality_report_sha256",
        ),
        (
            "proposal",
            "proposal_render_set_sha256",
            "proposal_comparison_report_sha256",
            "proposal_quality_report_sha256",
        ),
    ] {
        let render_hash = form_quality_value_sha(bundle_view, render_field)?;
        let comparison_hash = form_quality_value_sha(bundle_view, comparison_field)?;
        let quality_hash = form_quality_value_sha(bundle_view, quality_field)?;
        let render = verify_render(render_hash, &format!("{prefix} render set"))?;
        if prefix == "proposal"
            && (render.get("candidate_id").and_then(Value::as_str)
                != Some(quality.candidate_id.as_str())
                || render.get("artifact_sha256").and_then(Value::as_str)
                    != Some(quality.artifact_sha256.as_str()))
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_PROPOSAL_BINDING_MISMATCH",
                "proposal RenderSet is not bound to the form candidate",
            ));
        }
        let comparison = verify_comparison(
            comparison_hash,
            &format!("{prefix} comparison"),
            &render,
            render_hash,
        )?;
        if prefix == "proposal"
            && comparison.get("artifact_sha256").and_then(Value::as_str)
                != Some(quality.artifact_sha256.as_str())
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_PROPOSAL_BINDING_MISMATCH",
                "proposal ComparisonReport is not bound to the form artifact",
            ));
        }
        let report = verify_quality(
            quality_hash,
            &format!("{prefix} quality report"),
            &render,
            render_hash,
            comparison_hash,
        )?;
        if prefix == "proposal"
            && (report.get("candidate_id").and_then(Value::as_str)
                != Some(quality.candidate_id.as_str())
                || report.get("artifact_sha256").and_then(Value::as_str)
                    != Some(quality.artifact_sha256.as_str()))
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_PROPOSAL_BINDING_MISMATCH",
                "proposal QualityReport is not bound to the form artifact",
            ));
        }
    }
    Ok(())
}

fn ensure_form_quality_cross_view_structure(bundle: &Value) -> Result<(), StoreError> {
    ensure_form_quality_exact_object(
        bundle,
        &[
            "schema_version",
            "bundle_id",
            "project_id",
            "session_id",
            "candidate_id",
            "candidate_state_sha256",
            "artifact_sha256",
            "program_sha256",
            "reference_canvas_sha256",
            "coverage",
            "view_evaluations",
            "aggregate_status",
            "hard_gate_passed",
            "baseline_score",
            "proposal_score",
            "strict_improvement",
            "non_regressing",
            "promotion",
            "limitations",
            "canonical_sha256",
        ],
        &[],
        "CrossViewEvidenceBundle@1",
    )?;
    let object = bundle.as_object().expect("checked object");
    if object.get("schema_version").and_then(Value::as_str) != Some("CrossViewEvidenceBundle@1")
        || ["bundle_id", "project_id", "session_id", "candidate_id"]
            .iter()
            .any(|field| {
                object
                    .get(*field)
                    .and_then(Value::as_str)
                    .is_none_or(|value| !is_opaque_id(value))
            })
        || [
            "candidate_state_sha256",
            "artifact_sha256",
            "program_sha256",
            "reference_canvas_sha256",
            "canonical_sha256",
        ]
        .iter()
        .any(|field| {
            object
                .get(*field)
                .and_then(Value::as_str)
                .is_none_or(|value| !is_sha256(value))
        })
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_STRUCTURE_INVALID",
            "CrossViewEvidenceBundle identity or hash fields are invalid",
        ));
    }

    let view_kinds = [
        "front",
        "back",
        "left",
        "right",
        "top",
        "bottom",
        "perspective",
        "three-quarter",
        "front-three-quarter",
        "rear-three-quarter",
        "material",
        "detail",
    ];
    let validate_kind_array = |value: &Value,
                               field: &str,
                               min: usize,
                               max: usize|
     -> Result<std::collections::BTreeSet<String>, StoreError> {
        let values = value.get(field).and_then(Value::as_array).ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
                format!("CrossViewEvidenceBundle coverage.{field} is missing"),
            )
        })?;
        if values.len() < min || values.len() > max {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
                format!("CrossViewEvidenceBundle coverage.{field} length is invalid"),
            ));
        }
        let mut result = std::collections::BTreeSet::new();
        for value in values {
            let kind = value.as_str().ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
                    format!("CrossViewEvidenceBundle coverage.{field} contains non-string"),
                )
            })?;
            if !view_kinds.contains(&kind) || !result.insert(kind.to_owned()) {
                return Err(form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_COVERAGE_INVALID",
                    format!(
                        "CrossViewEvidenceBundle coverage.{field} has invalid or duplicate view"
                    ),
                ));
            }
        }
        Ok(result)
    };
    let coverage = object.get("coverage").ok_or_else(|| {
        form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_COVERAGE_INVALID",
            "CrossViewEvidenceBundle coverage is missing",
        )
    })?;
    ensure_form_quality_exact_object(
        coverage,
        &[
            "required_views",
            "supplied_views",
            "missing_views",
            "coverage_status",
            "hq_360_status",
            "evidence_refs",
        ],
        &[],
        "CrossViewEvidenceBundle.coverage",
    )?;
    let required_views = validate_kind_array(coverage, "required_views", 5, 9)?;
    let supplied_views = validate_kind_array(coverage, "supplied_views", 1, 9)?;
    let missing_views = validate_kind_array(coverage, "missing_views", 0, 9)?;
    let covered_views = supplied_views
        .union(&missing_views)
        .cloned()
        .collect::<std::collections::BTreeSet<_>>();
    if !supplied_views.is_disjoint(&missing_views) || required_views != covered_views {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
            "CrossViewEvidenceBundle coverage does not partition required views",
        ));
    }
    let coverage_status = coverage
        .get("coverage_status")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_COVERAGE_INVALID",
                "CrossViewEvidenceBundle coverage status is missing",
            )
        })?;
    let hq_status = coverage
        .get("hq_360_status")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_COVERAGE_INVALID",
                "CrossViewEvidenceBundle HQ status is missing",
            )
        })?;
    let coverage_complete = missing_views.is_empty();
    if coverage_complete {
        if coverage_status != "complete"
            || hq_status != "eligible"
            || !["front", "back", "left", "right", "rear-three-quarter"]
                .iter()
                .all(|kind| required_views.contains(*kind))
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
                "complete CrossView coverage is not eligible or lacks required views",
            ));
        }
    } else if !matches!(coverage_status, "partial" | "blocked")
        || hq_status != "BLOCKED_REFERENCE_COVERAGE"
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
            "incomplete CrossView coverage is not blocked",
        ));
    }
    let evidence_refs = coverage
        .get("evidence_refs")
        .and_then(Value::as_array)
        .filter(|refs| (1..=16).contains(&refs.len()))
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
                "CrossView coverage evidence refs are invalid",
            )
        })?;
    let mut evidence_seen = std::collections::BTreeSet::new();
    for reference in evidence_refs {
        ensure_form_quality_exact_object(
            reference,
            &["kind", "sha256"],
            &[],
            "coverage.evidence_ref",
        )?;
        let reference = reference.as_object().expect("checked object");
        let kind = reference
            .get("kind")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
                    "CrossView coverage evidence kind is missing",
                )
            })?;
        if !matches!(
            kind,
            "reference"
                | "artifact"
                | "render"
                | "comparison"
                | "quality"
                | "camera"
                | "scene"
                | "checkpoint"
                | "version"
                | "design-spec"
                | "visual-evidence"
                | "other"
        ) || reference
            .get("sha256")
            .and_then(Value::as_str)
            .is_none_or(|sha| !is_sha256(sha))
            || !evidence_seen.insert((kind.to_owned(), reference["sha256"].to_string()))
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
                "CrossView coverage evidence ref is invalid or duplicated",
            ));
        }
    }

    let metrics_fields = [
        "silhouette_iou",
        "boundary_f1_4px",
        "bbox_edge_error",
        "centroid_error",
        "landmark_coverage",
        "landmark_nme",
        "region_median_iou",
        "critical_region_min_iou",
    ];
    let evaluations = object
        .get("view_evaluations")
        .and_then(Value::as_array)
        .filter(|values| (2..=8).contains(&values.len()))
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVALUATIONS_INVALID",
                "CrossView view evaluations count is invalid",
            )
        })?;
    let mut seen_ids = std::collections::BTreeSet::new();
    let mut seen_kinds = std::collections::BTreeSet::new();
    let mut all_proposal_pass = true;
    let mut all_non_regressing = true;
    let mut all_strict_improvement = true;
    for evaluation in evaluations {
        ensure_form_quality_exact_object(
            evaluation,
            &[
                "view_id",
                "kind",
                "visibility",
                "confidence",
                "reference_id",
                "reference_sha256",
                "camera_hash",
                "baseline_status",
                "proposal_status",
                "baseline_render_set_sha256",
                "baseline_comparison_report_sha256",
                "baseline_quality_report_sha256",
                "proposal_render_set_sha256",
                "proposal_comparison_report_sha256",
                "proposal_quality_report_sha256",
                "baseline_metrics",
                "proposal_metrics",
                "non_regressing",
                "strict_improvement",
            ],
            &[],
            "CrossViewEvidenceBundle.view_evaluation",
        )?;
        let evaluation = evaluation.as_object().expect("checked object");
        let view_id = evaluation
            .get("view_id")
            .and_then(Value::as_str)
            .filter(|id| is_opaque_id(id))
            .ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVALUATIONS_INVALID",
                    "CrossView view_id is invalid",
                )
            })?;
        let kind = evaluation
            .get("kind")
            .and_then(Value::as_str)
            .filter(|kind| view_kinds.contains(kind))
            .ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVALUATIONS_INVALID",
                    "CrossView view kind is invalid",
                )
            })?;
        if !seen_ids.insert(view_id.to_owned()) || !seen_kinds.insert(kind.to_owned()) {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVALUATIONS_INVALID",
                "CrossView view id or kind is duplicated",
            ));
        }
        if !matches!(
            evaluation.get("visibility").and_then(Value::as_str),
            Some("observed" | "inferred" | "unknown")
        ) || evaluation
            .get("confidence")
            .and_then(Value::as_f64)
            .is_none_or(|value| !value.is_finite() || !(0.0..=1.0).contains(&value))
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVALUATIONS_INVALID",
                "CrossView visibility or confidence is invalid",
            ));
        }
        for field in [
            "reference_sha256",
            "camera_hash",
            "baseline_render_set_sha256",
            "baseline_comparison_report_sha256",
            "baseline_quality_report_sha256",
            "proposal_render_set_sha256",
            "proposal_comparison_report_sha256",
            "proposal_quality_report_sha256",
        ] {
            if evaluation
                .get(field)
                .and_then(Value::as_str)
                .is_none_or(|sha| !is_sha256(sha))
            {
                return Err(form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVALUATIONS_INVALID",
                    format!("CrossView evaluation {field} is invalid"),
                ));
            }
        }
        for field in ["baseline_status", "proposal_status"] {
            if !matches!(
                evaluation.get(field).and_then(Value::as_str),
                Some(
                    "PARTIAL_VISIBLE_VIEW_PASS"
                        | "QUALITY_TARGET_NOT_MET"
                        | "BLOCKED_REFERENCE_COVERAGE"
                )
            ) {
                return Err(form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVALUATIONS_INVALID",
                    format!("CrossView evaluation {field} is invalid"),
                ));
            }
        }
        for field in ["baseline_metrics", "proposal_metrics"] {
            let metrics = evaluation.get(field).ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_METRICS_INVALID",
                    format!("CrossView evaluation {field} is missing"),
                )
            })?;
            ensure_form_quality_exact_object(metrics, &metrics_fields, &[], field)?;
            if metrics_fields.iter().any(|metric| {
                metrics
                    .get(*metric)
                    .and_then(Value::as_f64)
                    .is_none_or(|value| !value.is_finite() || !(0.0..=1.0).contains(&value))
            }) {
                return Err(form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_METRICS_INVALID",
                    format!("CrossView evaluation {field} contains invalid metrics"),
                ));
            }
        }
        let proposal_pass = evaluation.get("proposal_status").and_then(Value::as_str)
            == Some("PARTIAL_VISIBLE_VIEW_PASS");
        let non_regressing = evaluation
            .get("non_regressing")
            .and_then(Value::as_bool)
            .ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVALUATIONS_INVALID",
                    "CrossView non_regressing is invalid",
                )
            })?;
        let strict_improvement = evaluation
            .get("strict_improvement")
            .and_then(Value::as_bool)
            .ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_EVALUATIONS_INVALID",
                    "CrossView strict_improvement is invalid",
                )
            })?;
        all_proposal_pass &= proposal_pass;
        all_non_regressing &= non_regressing;
        all_strict_improvement &= strict_improvement;
    }
    if supplied_views != seen_kinds {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_COVERAGE_INVALID",
            "CrossView supplied views do not match evaluations",
        ));
    }
    let expected_aggregate = if !coverage_complete {
        "BLOCKED_REFERENCE_COVERAGE"
    } else if all_proposal_pass {
        "PARTIAL_VISIBLE_VIEW_PASS"
    } else {
        "QUALITY_TARGET_NOT_MET"
    };
    if object.get("aggregate_status").and_then(Value::as_str) != Some(expected_aggregate)
        || object.get("hard_gate_passed").and_then(Value::as_bool)
            != Some(coverage_complete && all_proposal_pass)
        || object.get("non_regressing").and_then(Value::as_bool) != Some(all_non_regressing)
        || object.get("strict_improvement").and_then(Value::as_bool)
            != Some(all_strict_improvement && all_proposal_pass)
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_AGGREGATE_INVALID",
            "CrossView aggregate gate fields do not match per-view evidence",
        ));
    }
    for field in ["baseline_score", "proposal_score"] {
        if object
            .get(field)
            .and_then(Value::as_f64)
            .is_none_or(|value| !value.is_finite() || !(0.0..=8.0).contains(&value))
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_AGGREGATE_INVALID",
                format!("CrossView {field} is invalid"),
            ));
        }
    }
    let expected_promotion = if all_strict_improvement && all_proposal_pass {
        "reviewable"
    } else if all_non_regressing {
        "not-improved"
    } else {
        "rejected-regression"
    };
    let promotion = object.get("promotion").ok_or_else(|| {
        form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_PROMOTION_INVALID",
            "CrossView promotion is missing",
        )
    })?;
    ensure_form_quality_exact_object(
        promotion,
        &["status", "confirm_allowed"],
        &[],
        "CrossViewEvidenceBundle.promotion",
    )?;
    if promotion.get("status").and_then(Value::as_str) != Some(expected_promotion)
        || promotion.get("confirm_allowed") != Some(&Value::Bool(false))
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_PROMOTION_INVALID",
            "CrossView promotion does not match aggregate gates",
        ));
    }
    let limitations = object
        .get("limitations")
        .and_then(Value::as_array)
        .filter(|values| (1..=16).contains(&values.len()))
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_LIMITATIONS_INVALID",
                "CrossView limitations are missing or out of bounds",
            )
        })?;
    let mut limitation_seen = std::collections::BTreeSet::new();
    for limitation in limitations {
        let text = limitation
            .as_str()
            .filter(|text| !text.is_empty() && text.len() <= 256)
            .ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_LIMITATIONS_INVALID",
                    "CrossView limitation is invalid",
                )
            })?;
        if !limitation_seen.insert(text.to_owned()) {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_LIMITATIONS_INVALID",
                "CrossView limitations contain duplicates",
            ));
        }
    }
    Ok(())
}

fn ensure_production_weapon_form_quality_cross_view_binding(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    quality: &ProductionWeaponFormQualityRecord,
    require_reachable: bool,
) -> Result<Vec<Value>, StoreError> {
    let bundle = form_quality_json_object(
        transaction,
        cas,
        &quality.cross_view_evidence_object_sha256,
        "cross-view evidence bundle",
        Some("cross-view-evidence-bundle"),
        require_reachable,
    )?;
    if bundle.get("schema_version").and_then(Value::as_str) != Some("CrossViewEvidenceBundle@1")
        || bundle.get("project_id").and_then(Value::as_str) != Some(quality.project_id.as_str())
        || bundle.get("session_id").and_then(Value::as_str) != Some(quality.session_id.as_str())
        || bundle.get("candidate_id").and_then(Value::as_str) != Some(quality.candidate_id.as_str())
        || bundle.get("candidate_state_sha256").and_then(Value::as_str)
            != Some(quality.candidate_state_sha256.as_str())
        || bundle.get("artifact_sha256").and_then(Value::as_str)
            != Some(quality.artifact_sha256.as_str())
        || bundle
            .get("reference_canvas_sha256")
            .and_then(Value::as_str)
            != Some(quality.reference_canvas_object_sha256.as_str())
        || bundle.get("canonical_sha256").and_then(Value::as_str)
            != Some(quality.cross_view_evidence_canonical_sha256.as_str())
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_BINDING_MISMATCH",
            "CrossViewEvidenceBundle parent binding differs",
        ));
    }
    ensure_form_quality_cross_view_structure(&bundle)?;
    let mut bundle_canonical = bundle.clone();
    bundle_canonical["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&bundle_canonical) != quality.cross_view_evidence_canonical_sha256 {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_CANONICAL_MISMATCH",
            "CrossViewEvidenceBundle canonical hash differs",
        ));
    }
    let canvas = form_quality_json_object(
        transaction,
        cas,
        &quality.reference_canvas_object_sha256,
        "reference canvas",
        Some("reference-canvas"),
        require_reachable,
    )?;
    ensure_form_quality_canonical_value(&canvas, "ReferenceCanvas@1", "reference canvas")?;
    if canvas.get("canonical_sha256").and_then(Value::as_str)
        != Some(quality.reference_canvas_canonical_sha256.as_str())
        || canvas.get("project_id").and_then(Value::as_str) != Some(quality.project_id.as_str())
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_REFERENCE_CANVAS_BINDING_MISMATCH",
            "ReferenceCanvas binding differs from the form-quality record",
        ));
    }
    let canvas_views = canvas
        .get("views")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_REFERENCE_CANVAS_VIEWS_MISSING",
                "ReferenceCanvas has no views",
            )
        })?;
    let mut canvas_by_id = std::collections::BTreeMap::new();
    for canvas_view in canvas_views {
        let object = canvas_view.as_object().ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_REFERENCE_CANVAS_VIEW_INVALID",
                "ReferenceCanvas view is malformed",
            )
        })?;
        let view_id = object
            .get("view_id")
            .and_then(Value::as_str)
            .filter(|value| is_opaque_id(value))
            .ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_REFERENCE_CANVAS_VIEW_INVALID",
                    "ReferenceCanvas view_id is invalid",
                )
            })?;
        if canvas_by_id
            .insert(view_id.to_owned(), canvas_view)
            .is_some()
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_REFERENCE_CANVAS_VIEW_CONFLICT",
                "ReferenceCanvas contains duplicate view_id",
            ));
        }
    }
    let bundle_views = bundle
        .get("view_evaluations")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_VIEWS_MISSING",
                "CrossViewEvidenceBundle has no view evaluations",
            )
        })?;
    if bundle_views.len() != PRODUCTION_WEAPON_FORM_QUALITY_REVIEWED_REFERENCE_VIEW_KINDS.len()
        || bundle_views.len() != quality.form_view_evaluations.len()
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_VIEWS_INCOMPLETE",
            "CrossViewEvidenceBundle must contain exactly the six form views",
        ));
    }
    let mut selected = Vec::with_capacity(quality.form_view_evaluations.len());
    let mut seen = std::collections::HashSet::new();
    for view in &quality.form_view_evaluations {
        let Some(bundle_view) = bundle_views.iter().find(|candidate| {
            candidate.get("view_id").and_then(Value::as_str) == Some(view.view_id.as_str())
        }) else {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_VIEW_MISSING",
                format!("CrossViewEvidenceBundle is missing view {}", view.view_id),
            ));
        };
        let bundle_reference_id = bundle_view
            .get("reference_id")
            .and_then(Value::as_str)
            .filter(|value| is_opaque_id(value));
        let bundle_reference_sha256 = bundle_view
            .get("reference_sha256")
            .and_then(Value::as_str)
            .filter(|value| is_sha256(value));
        let canvas_view = canvas_by_id.get(&view.view_id).ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_REFERENCE_CANVAS_VIEW_MISSING",
                format!("ReferenceCanvas is missing view {}", view.view_id),
            )
        })?;
        if !seen.insert(view.view_id.clone())
            || bundle_view.get("kind").and_then(Value::as_str) != Some(view.view_kind.as_str())
            || bundle_view
                .get("view_id")
                .and_then(Value::as_str)
                .is_none_or(|value| !is_opaque_id(value))
            || bundle_reference_id.is_none()
            || bundle_reference_sha256.is_none()
            || bundle_view
                .get("camera_hash")
                .and_then(Value::as_str)
                .is_none_or(|value| !is_sha256(value))
            || canvas_view.get("kind").and_then(Value::as_str) != Some(view.view_kind.as_str())
            || canvas_view.get("reference_id").and_then(Value::as_str) != bundle_reference_id
            || canvas_view.get("reference_sha256").and_then(Value::as_str)
                != bundle_reference_sha256
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_VIEW_BINDING_MISMATCH",
                format!(
                    "CrossViewEvidenceBundle view {} binding differs",
                    view.view_id
                ),
            ));
        }
        let bundle_reference_id = bundle_reference_id.unwrap_or_default();
        let bundle_reference_sha256 = bundle_reference_sha256.unwrap_or_default();
        let reference_binding: Option<(String, String)> = transaction
            .query_row(
                "SELECT project_id, object_sha256 FROM reference_evidence WHERE reference_id = ?1",
                params![bundle_reference_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()?;
        if reference_binding.as_ref().map(|value| value.0.as_str())
            != Some(quality.project_id.as_str())
            || reference_binding.as_ref().map(|value| value.1.as_str())
                != Some(bundle_reference_sha256)
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_VIEW_REFERENCE_BINDING_MISMATCH",
                format!(
                    "CrossView view {} reference is outside the project",
                    view.view_id
                ),
            ));
        }
        let _ = read_form_quality_object(
            transaction,
            cas,
            bundle_reference_sha256,
            "CrossView view reference",
            None,
            require_reachable,
            64 * 1024 * 1024,
        )?;
        ensure_form_quality_view_triplet(
            transaction,
            cas,
            bundle_view,
            quality,
            view,
            require_reachable,
        )?;
        ensure_form_quality_evidence_object(
            transaction,
            cas,
            &view.part_id_evidence.source,
            "part-id evidence",
            require_reachable,
        )?;
        ensure_form_quality_evidence_object(
            transaction,
            cas,
            &view.negative_space_evidence.source,
            "negative-space evidence",
            require_reachable,
        )?;
        ensure_form_quality_evidence_object(
            transaction,
            cas,
            &view.line_flow_evidence.source,
            "line-flow evidence",
            require_reachable,
        )?;
        selected.push(bundle_view.clone());
    }
    Ok(selected)
}

fn ensure_production_weapon_form_quality_stage_bindings(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    quality: &ProductionWeaponFormQualityRecord,
    require_reachable: bool,
) -> Result<ProductionStageHeadV3Record, StoreError> {
    let root_candidate_id: Option<String> = transaction
        .query_row(
            "SELECT root_candidate_id FROM agentic_production_stage_heads_v3 WHERE session_id = ?1 AND project_id = ?2 AND head_candidate_id = ?3 ORDER BY updated_at DESC LIMIT 1",
            params![quality.session_id, quality.project_id, quality.camera_calibrated_head_candidate_id],
            |row| row.get(0),
        )
        .optional()?;
    let Some(root_candidate_id) = root_candidate_id else {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_HEAD_MISSING",
            "camera-calibrated current head is missing",
        ));
    };
    let Some(head) = read_production_stage_head_v3_record(
        transaction,
        &quality.session_id,
        &quality.project_id,
        &root_candidate_id,
    )?
    else {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_HEAD_MISSING",
            "camera-calibrated current head is missing",
        ));
    };
    let Some(transition_columns) =
        read_production_stage_transition_v3_columns(transaction, &head.head_transition_id)?
    else {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_TRANSITION_MISSING",
            "camera-calibrated head transition is missing",
        ));
    };
    let transition = transition_columns.record;
    if head.head_stage != "camera-calibrated"
        || head.head_candidate_id != quality.camera_calibrated_head_candidate_id
        || head.head_candidate_state_sha256 != quality.camera_calibrated_head_candidate_state_sha256
        || head.output_artifact_id != quality.camera_calibrated_head_artifact_id
        || head.head_artifact_sha256 != quality.camera_calibrated_head_artifact_sha256
        || head.head_transition_id != quality.camera_calibrated_head_transition_id
        || head.head_transition_sha256 != quality.camera_calibrated_head_transition_sha256
        || head.session_id != quality.session_id
        || head.project_id != quality.project_id
        || transition.transition_id != quality.camera_calibrated_head_transition_id
        || transition.canonical_sha256 != quality.camera_calibrated_head_transition_sha256
        || transition.from_stage != PRODUCTION_STAGE_V3_CAMERA_FROM_STAGE
        || transition.to_stage != PRODUCTION_STAGE_V3_CAMERA_TO_STAGE
        || transition.head_candidate_id != quality.camera_calibrated_head_candidate_id
        || transition.head_candidate_state_sha256
            != quality.camera_calibrated_head_candidate_state_sha256
        || transition.output_artifact_id != quality.camera_calibrated_head_artifact_id
        || transition.head_artifact_sha256 != quality.camera_calibrated_head_artifact_sha256
        || transition.reference_id != quality.reference_id
        || transition.reference_sha256 != quality.reference_sha256
        || transition.reference_canvas_object_sha256 != quality.reference_canvas_object_sha256
        || transition.design_spec_object_sha256 != quality.design_spec_object_sha256
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_HEAD_BINDING_MISMATCH",
            "current camera-calibrated head or source transition differs",
        ));
    }
    let Some(lock) =
        read_production_camera_lock_in_transaction(transaction, cas, &quality.camera_lock_id)?
    else {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CAMERA_LOCK_MISSING",
            "camera lock is missing",
        ));
    };
    if lock.session_id != quality.session_id
        || lock.project_id != quality.project_id
        || lock.source_transition_id != quality.camera_lock_source_transition_id
        || lock.source_transition_sha256 != quality.camera_lock_source_transition_sha256
        || lock.source_head_canonical_sha256 != quality.camera_lock_source_head_canonical_sha256
        || lock.camera_lock_id != quality.camera_lock_id
        || lock.canonical_sha256 != quality.camera_lock_canonical_sha256
        || lock.candidate_id != quality.candidate_id
        || lock.candidate_state_sha256 != quality.candidate_state_sha256
        || lock.artifact_id != quality.artifact_id
        || lock.artifact_sha256 != quality.artifact_sha256
        || lock.reference_id != quality.reference_id
        || lock.reference_sha256 != quality.reference_sha256
        || lock.reference_canvas_object_sha256 != quality.reference_canvas_object_sha256
        || lock.reference_canvas_canonical_sha256 != quality.reference_canvas_canonical_sha256
        || lock.design_spec_object_sha256 != quality.design_spec_object_sha256
        || lock.design_spec_canonical_sha256 != quality.design_spec_canonical_sha256
        || lock.camera_rig_object_sha256 != quality.camera_rig_object_sha256
        || lock.camera_rig_canonical_sha256 != quality.camera_rig_canonical_sha256
        || lock.receipt_object_sha256 != quality.camera_lock_receipt_object_sha256
        || transition.camera_lock_id.as_deref() != Some(quality.camera_lock_id.as_str())
        || transition.camera_lock_canonical_sha256.as_deref()
            != Some(quality.camera_lock_canonical_sha256.as_str())
        || transition.camera_rig_object_sha256.as_deref()
            != Some(quality.camera_rig_object_sha256.as_str())
        || transition.camera_rig_canonical_sha256.as_deref()
            != Some(quality.camera_rig_canonical_sha256.as_str())
        || transition.camera_lock_receipt_object_sha256.as_deref()
            != Some(quality.camera_lock_receipt_object_sha256.as_str())
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CAMERA_LOCK_BINDING_MISMATCH",
            "CameraLock@1 is not bound to the current head and candidate",
        ));
    }
    let candidate: Option<(String, Option<String>, Option<String>, String)> = transaction
        .query_row(
            "SELECT project_id, prepared_object_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
            params![quality.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((candidate_project, prepared_id, prepared_sha, candidate_state)) = candidate else {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CANDIDATE_MISSING",
            "form candidate is missing",
        ));
    };
    if candidate_project != quality.project_id
        || prepared_id.as_deref() != Some(quality.artifact_id.as_str())
        || prepared_sha.as_deref() != Some(quality.artifact_sha256.as_str())
        || candidate_state != quality.candidate_state_sha256
        || quality.candidate_id != quality.camera_calibrated_head_candidate_id
        || quality.candidate_state_sha256 != quality.camera_calibrated_head_candidate_state_sha256
        || quality.artifact_id != quality.camera_calibrated_head_artifact_id
        || quality.artifact_sha256 != quality.camera_calibrated_head_artifact_sha256
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CANDIDATE_BINDING_MISMATCH",
            "candidate, state or artifact differs from the camera-calibrated head",
        ));
    }
    let reference: Option<(String, String)> = transaction
        .query_row(
            "SELECT project_id, object_sha256 FROM reference_evidence WHERE reference_id = ?1",
            params![quality.reference_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if reference.as_ref().map(|value| value.0.as_str()) != Some(quality.project_id.as_str())
        || reference.as_ref().map(|value| value.1.as_str())
            != Some(quality.reference_sha256.as_str())
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_REFERENCE_BINDING_MISMATCH",
            "reference is outside the project or hash binding",
        ));
    }
    if quality.form_stage != "blockout" {
        let previous_id = quality.previous_form_quality_id.as_deref().ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_PREVIOUS_MISSING",
                "non-blockout form quality has no previous record",
            )
        })?;
        let previous_row: Option<(String, String)> = transaction
            .query_row(
                "SELECT payload_json, receipt_object_sha256 FROM production_weapon_form_quality_links WHERE form_quality_id = ?1",
                params![previous_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()?;
        let Some((previous_payload, previous_receipt_sha256)) = previous_row else {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_PREVIOUS_NOT_FOUND",
                "previous form quality row is unavailable",
            ));
        };
        let mut previous: ProductionWeaponFormQualityRecord =
            serde_json::from_str(&previous_payload).map_err(|error| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_PREVIOUS_INVALID",
                    error.to_string(),
                )
            })?;
        previous.receipt_object_sha256 = previous_receipt_sha256.clone();
        validate_production_weapon_form_quality(&previous)?;
        if previous.form_quality_id != previous_id
            || previous.session_id != quality.session_id
            || previous.project_id != quality.project_id
            || previous.candidate_id != quality.candidate_id
            || previous.candidate_state_sha256 != quality.candidate_state_sha256
            || previous.artifact_id != quality.artifact_id
            || previous.artifact_sha256 != quality.artifact_sha256
            || previous.target_stage != quality.source_stage
            || quality
                .previous_form_quality_report_object_sha256
                .as_deref()
                != Some(previous.receipt_object_sha256.as_str())
            || quality.previous_form_quality_canonical_sha256.as_deref()
                != Some(previous.canonical_sha256.as_str())
            || production_weapon_form_quality_payload_json(&previous)? != previous_payload
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_PREVIOUS_BINDING_MISMATCH",
                "previous form quality is not the exact prior stage record",
            ));
        }
        let previous_receipt = read_form_quality_object(
            transaction,
            cas,
            &previous_receipt_sha256,
            "previous form-quality receipt",
            Some(PRODUCTION_WEAPON_FORM_QUALITY_RECEIPT_KIND),
            require_reachable,
            MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
        )?;
        ensure_production_weapon_form_quality_receipt(cas, &previous_receipt, &previous_payload)?;
    }
    for (hash, label, max) in [
        (
            &quality.artifact_sha256,
            "candidate artifact",
            64 * 1024 * 1024,
        ),
        (&quality.reference_sha256, "reference", 64 * 1024 * 1024),
        (
            &quality.reference_canvas_object_sha256,
            "reference canvas",
            MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
        ),
        (
            &quality.design_spec_object_sha256,
            "design spec",
            MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
        ),
    ] {
        let _ =
            read_form_quality_object(transaction, cas, hash, label, None, require_reachable, max)?;
    }
    let canvas = form_quality_json_object(
        transaction,
        cas,
        &quality.reference_canvas_object_sha256,
        "reference canvas",
        Some("reference-canvas"),
        require_reachable,
    )?;
    ensure_form_quality_canonical_value(&canvas, "ReferenceCanvas@1", "reference canvas")?;
    if canvas.get("canonical_sha256").and_then(Value::as_str)
        != Some(quality.reference_canvas_canonical_sha256.as_str())
        || canvas.get("project_id").and_then(Value::as_str) != Some(quality.project_id.as_str())
        || canvas
            .get("reference_set_sha256")
            .and_then(Value::as_str)
            .is_none_or(|hash| !is_sha256(hash))
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_REFERENCE_CANVAS_BINDING_MISMATCH",
            "ReferenceCanvas is outside the project or has no reference set hash",
        ));
    }
    let canvas_id = canvas
        .get("canvas_id")
        .and_then(Value::as_str)
        .filter(|id| is_opaque_id(id))
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_REFERENCE_CANVAS_INVALID",
                "ReferenceCanvas canvas_id is invalid",
            )
        })?;
    let spec = form_quality_json_object(
        transaction,
        cas,
        &quality.design_spec_object_sha256,
        "design spec",
        Some("design-spec"),
        require_reachable,
    )?;
    ensure_form_quality_canonical_value(&spec, "DesignSpec@1", "design spec")?;
    if spec.get("canonical_sha256").and_then(Value::as_str)
        != Some(quality.design_spec_canonical_sha256.as_str())
        || spec.get("project_id").and_then(Value::as_str) != Some(quality.project_id.as_str())
        || spec.get("reference_canvas_id").and_then(Value::as_str) != Some(canvas_id)
        || spec.get("reference_canvas_sha256").and_then(Value::as_str)
            != Some(quality.reference_canvas_object_sha256.as_str())
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_DESIGN_SPEC_BINDING_MISMATCH",
            "DesignSpec is outside the project or reference canvas",
        ));
    }
    Ok(head)
}

fn ensure_production_weapon_form_quality_form_evidence_binding(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    quality: &ProductionWeaponFormQualityRecord,
    require_reachable: bool,
) -> Result<(), StoreError> {
    if !is_sha256(&quality.form_evidence_object_sha256)
        || !is_sha256(&quality.form_evidence_canonical_sha256)
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_FORM_EVIDENCE_INVALID",
            "FORM typed evidence hashes are invalid",
        ));
    }
    let parent = form_quality_json_object(
        transaction,
        cas,
        &quality.form_evidence_object_sha256,
        "form evidence parent",
        Some(PRODUCTION_WEAPON_FORM_EVIDENCE_PARENT_RECEIPT_KIND),
        require_reachable,
    )?;
    ensure_form_quality_canonical_value(
        &parent,
        "ProductionWeaponFormEvidence@1",
        "form evidence parent",
    )?;
    if !production_weapon_form_quality_parent_receipt_self_reference_is_cleared(&parent)
        || parent.get("canonical_sha256").and_then(Value::as_str)
            != Some(quality.form_evidence_canonical_sha256.as_str())
        || parent.get("session_id").and_then(Value::as_str) != Some(quality.session_id.as_str())
        || parent.get("project_id").and_then(Value::as_str) != Some(quality.project_id.as_str())
        || parent.get("candidate_id").and_then(Value::as_str) != Some(quality.candidate_id.as_str())
        || parent.get("candidate_state_sha256").and_then(Value::as_str)
            != Some(quality.candidate_state_sha256.as_str())
        || parent.get("artifact_id").and_then(Value::as_str) != Some(quality.artifact_id.as_str())
        || parent.get("artifact_sha256").and_then(Value::as_str)
            != Some(quality.artifact_sha256.as_str())
        || parent
            .get("reference_canvas_object_sha256")
            .and_then(Value::as_str)
            != Some(quality.reference_canvas_object_sha256.as_str())
        || parent
            .get("reference_canvas_canonical_sha256")
            .and_then(Value::as_str)
            != Some(quality.reference_canvas_canonical_sha256.as_str())
        || parent
            .get("design_spec_object_sha256")
            .and_then(Value::as_str)
            != Some(quality.design_spec_object_sha256.as_str())
        || parent
            .get("design_spec_canonical_sha256")
            .and_then(Value::as_str)
            != Some(quality.design_spec_canonical_sha256.as_str())
        || parent.get("camera_lock_id").and_then(Value::as_str)
            != Some(quality.camera_lock_id.as_str())
        || parent
            .get("camera_lock_canonical_sha256")
            .and_then(Value::as_str)
            != Some(quality.camera_lock_canonical_sha256.as_str())
        || parent
            .get("camera_rig_object_sha256")
            .and_then(Value::as_str)
            != Some(quality.camera_rig_object_sha256.as_str())
        || parent
            .get("camera_rig_canonical_sha256")
            .and_then(Value::as_str)
            != Some(quality.camera_rig_canonical_sha256.as_str())
        || parent
            .get("camera_lock_receipt_object_sha256")
            .and_then(Value::as_str)
            != Some(quality.camera_lock_receipt_object_sha256.as_str())
        || parent
            .get("camera_lock_source_transition_id")
            .and_then(Value::as_str)
            != Some(quality.camera_lock_source_transition_id.as_str())
        || parent
            .get("camera_lock_source_transition_sha256")
            .and_then(Value::as_str)
            != Some(quality.camera_lock_source_transition_sha256.as_str())
        || parent
            .get("camera_lock_source_head_canonical_sha256")
            .and_then(Value::as_str)
            != Some(quality.camera_lock_source_head_canonical_sha256.as_str())
        || parent.get("quality_status").and_then(Value::as_str) != Some("NOT_PROVEN")
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_FORM_EVIDENCE_BINDING_MISMATCH",
            "FORM typed evidence parent is outside the quality binding",
        ));
    }
    let evidence_id = parent
        .get("form_evidence_id")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_FORM_EVIDENCE_INVALID",
                "FORM typed evidence id is missing",
            )
        })?;
    let stored =
        read_production_weapon_form_evidence_in_transaction(transaction, cas, evidence_id)?
            .ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_FORM_EVIDENCE_MISSING",
                    "FORM typed evidence parent row is missing",
                )
            })?;
    if stored.receipt_object_sha256 != quality.form_evidence_object_sha256
        || stored.canonical_sha256 != quality.form_evidence_canonical_sha256
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_FORM_EVIDENCE_BINDING_MISMATCH",
            "FORM typed evidence row differs from its parent receipt",
        ));
    }
    Ok(())
}

fn production_weapon_form_quality_parent_receipt_self_reference_is_cleared(parent: &Value) -> bool {
    parent.get("receipt_object_sha256").and_then(Value::as_str) == Some("")
}

fn production_weapon_form_quality_json_fields(
    record: &ProductionWeaponFormQualityRecord,
) -> Result<(String, String, String, String), StoreError> {
    Ok((
        canonical_json_string(&record.reviewed_reference_view_kinds)?,
        canonical_json_string(&record.fixed_camera_view_kinds)?,
        canonical_json_string(&record.cross_view_evidence_view_kinds)?,
        canonical_json_string(&record.form_view_evaluations)?,
    ))
}

fn production_weapon_form_quality_view_payload(
    view: &ProductionWeaponFormQualityViewRecord,
) -> Result<(String, String), StoreError> {
    let value =
        serde_json::to_value(view).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let bytes =
        canonical_json_bytes(&value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let payload =
        String::from_utf8(bytes).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    Ok((payload, canonical_json_hash(&value)))
}

fn form_quality_value_sha<'a>(value: &'a Value, field: &str) -> Result<&'a str, StoreError> {
    value
        .get(field)
        .and_then(Value::as_str)
        .filter(|hash| is_sha256(hash))
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_OBJECT_INVALID",
                format!("CrossViewEvidenceBundle field {field} is not a SHA-256"),
            )
        })
}

fn production_weapon_form_quality_reachable_hashes(
    transaction: &rusqlite::Transaction<'_>,
    quality: &ProductionWeaponFormQualityRecord,
    bundle_views: &[Value],
) -> Result<Vec<String>, StoreError> {
    let mut hashes = vec![
        quality.receipt_object_sha256.clone(),
        quality.artifact_sha256.clone(),
        quality.camera_calibrated_head_artifact_sha256.clone(),
        quality.reference_sha256.clone(),
        quality.reference_canvas_object_sha256.clone(),
        quality.design_spec_object_sha256.clone(),
        quality.camera_rig_object_sha256.clone(),
        quality.camera_lock_receipt_object_sha256.clone(),
        quality.cross_view_evidence_object_sha256.clone(),
        quality.form_evidence_object_sha256.clone(),
    ];
    hashes.push(transaction.query_row(
        "SELECT object_sha256 FROM agentic_design_sessions WHERE session_id = ?1",
        params![quality.session_id],
        |row| row.get(0),
    )?);
    if let Some(previous) = quality.previous_form_quality_report_object_sha256.as_ref() {
        hashes.push(previous.clone());
    }
    for transition_id in [
        quality.camera_calibrated_head_transition_id.as_str(),
        quality.camera_lock_source_transition_id.as_str(),
    ] {
        let receipt: String = transaction.query_row(
            "SELECT receipt_object_sha256 FROM agentic_production_stage_transitions_v3 WHERE transition_id = ?1",
            params![transition_id],
            |row| row.get(0),
        )?;
        hashes.push(receipt);
    }
    for value in bundle_views {
        let reference_sha256 = value
            .get("reference_sha256")
            .and_then(Value::as_str)
            .filter(|hash| is_sha256(hash))
            .ok_or_else(|| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_VIEW_REFERENCE_INVALID",
                    "CrossView view reference hash is invalid",
                )
            })?;
        hashes.push(reference_sha256.to_owned());
        for field in [
            "baseline_render_set_sha256",
            "baseline_comparison_report_sha256",
            "baseline_quality_report_sha256",
            "proposal_render_set_sha256",
            "proposal_comparison_report_sha256",
            "proposal_quality_report_sha256",
        ] {
            hashes.push(form_quality_value_sha(value, field)?.to_owned());
        }
    }
    let mut cas_refs = transaction.prepare(
        "SELECT object_sha256 FROM production_weapon_form_quality_cas_refs WHERE form_quality_id = ?1",
    )?;
    let cas_rows = cas_refs.query_map(params![quality.form_quality_id], |row| row.get(0))?;
    for hash in cas_rows {
        hashes.push(hash?);
    }
    for view in &quality.form_view_evaluations {
        for binding in [
            &view.part_id_evidence.source,
            &view.negative_space_evidence.source,
            &view.line_flow_evidence.source,
        ] {
            if let Some(hash) = binding.source_object_sha256.as_ref() {
                hashes.push(hash.clone());
            }
            if let Some(hash) = binding.evidence_object_sha256.as_ref() {
                hashes.push(hash.clone());
            }
        }
    }
    hashes.sort();
    hashes.dedup();
    validate_reachable_hashes(&hashes)?;
    Ok(hashes)
}

