fn ensure_production_weapon_form_quality_children(
    transaction: &rusqlite::Transaction<'_>,
    quality: &ProductionWeaponFormQualityRecord,
    bundle_views: &[Value],
) -> Result<(), StoreError> {
    let count: i64 = transaction.query_row(
        "SELECT COUNT(*) FROM production_weapon_form_quality_views WHERE form_quality_id = ?1",
        params![quality.form_quality_id],
        |row| row.get(0),
    )?;
    if count != quality.form_view_evaluations.len() as i64 {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_CHILD_COUNT_MISMATCH",
            "form-quality link does not have exactly six view rows",
        ));
    }
    for (ordinal, view) in quality.form_view_evaluations.iter().enumerate() {
        let expected_payload = production_weapon_form_quality_view_payload(view)?;
        let bundle_view = bundle_views.get(ordinal).ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CROSS_VIEW_VIEWS_INCOMPLETE",
                "CrossViewEvidenceBundle view order is incomplete",
            )
        })?;
        let expected_hash = |field: &str| form_quality_value_sha(bundle_view, field);
        let row: Option<Vec<Option<String>>> = transaction
            .query_row(
                "SELECT CAST(view_ordinal AS TEXT), view_id, reference_id, reference_sha256, camera_hash, bundle_object_sha256, baseline_render_set_object_sha256, baseline_comparison_report_object_sha256, baseline_quality_report_object_sha256, proposal_render_set_object_sha256, proposal_comparison_report_object_sha256, proposal_quality_report_object_sha256, canonical_sha256, payload_json FROM production_weapon_form_quality_views WHERE form_quality_id = ?1 AND view_kind = ?2",
                params![quality.form_quality_id, view.view_kind],
                |row| {
                    let count = row.as_ref().column_count();
                    (0..count).map(|index| row.get(index)).collect()
                },
            )
            .optional()?;
        let Some(stored) = row else {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CHILD_MISSING",
                format!("view child {} is missing", view.view_kind),
            ));
        };
        let stored_value = |index: usize| stored[index].as_deref().unwrap_or_default();
        if stored_value(0) != ordinal.to_string()
            || stored_value(1) != view.view_id
            || stored_value(2)
                != bundle_view
                    .get("reference_id")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
            || stored_value(3)
                != bundle_view
                    .get("reference_sha256")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
            || stored_value(4)
                != bundle_view
                    .get("camera_hash")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
            || stored_value(5) != quality.cross_view_evidence_object_sha256
            || stored_value(6) != expected_hash("baseline_render_set_sha256")?
            || stored_value(7) != expected_hash("baseline_comparison_report_sha256")?
            || stored_value(8) != expected_hash("baseline_quality_report_sha256")?
            || stored_value(9) != expected_hash("proposal_render_set_sha256")?
            || stored_value(10) != expected_hash("proposal_comparison_report_sha256")?
            || stored_value(11) != expected_hash("proposal_quality_report_sha256")?
            || stored_value(12) != expected_payload.1
            || stored_value(13) != expected_payload.0
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CHILD_BINDING_MISMATCH",
                format!("view child {} binding differs", view.view_kind),
            ));
        }
        let direct: Vec<Option<String>> = transaction.query_row(
            "SELECT part_id_source_kind, part_id_source_object_sha256, part_id_evidence_object_sha256, part_id_status, negative_space_source_kind, negative_space_source_object_sha256, negative_space_evidence_object_sha256, negative_space_status, line_flow_source_kind, line_flow_source_object_sha256, line_flow_evidence_object_sha256, line_flow_status, no_regression_status, CAST(metrics_not_regressed AS TEXT), CAST(part_id_not_regressed AS TEXT), CAST(negative_space_not_regressed AS TEXT), CAST(line_flow_not_regressed AS TEXT) FROM production_weapon_form_quality_views WHERE form_quality_id = ?1 AND view_kind = ?2",
            params![quality.form_quality_id, view.view_kind],
            |row| {
                let count = row.as_ref().column_count();
                (0..count).map(|index| row.get(index)).collect()
            },
        )?;
        let expected_direct = vec![
            Some(view.part_id_evidence.source.source_kind.clone()),
            view.part_id_evidence.source.source_object_sha256.clone(),
            view.part_id_evidence.source.evidence_object_sha256.clone(),
            Some(view.part_id_evidence.source.status.clone()),
            Some(view.negative_space_evidence.source.source_kind.clone()),
            view.negative_space_evidence
                .source
                .source_object_sha256
                .clone(),
            view.negative_space_evidence
                .source
                .evidence_object_sha256
                .clone(),
            Some(view.negative_space_evidence.source.status.clone()),
            Some(view.line_flow_evidence.source.source_kind.clone()),
            view.line_flow_evidence.source.source_object_sha256.clone(),
            view.line_flow_evidence
                .source
                .evidence_object_sha256
                .clone(),
            Some(view.line_flow_evidence.source.status.clone()),
            Some(view.no_regression.status.clone()),
            Some((view.no_regression.metrics_not_regressed as i64).to_string()),
            Some((view.no_regression.part_id_not_regressed as i64).to_string()),
            Some((view.no_regression.negative_space_not_regressed as i64).to_string()),
            Some((view.no_regression.line_flow_not_regressed as i64).to_string()),
        ];
        if direct != expected_direct {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CHILD_EVIDENCE_BINDING_MISMATCH",
                format!("view child {} evidence projection differs", view.view_kind),
            ));
        }
    }
    Ok(())
}

fn read_production_weapon_form_quality_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    form_quality_id: &str,
) -> Result<Option<ProductionWeaponFormQualityRecord>, StoreError> {
    let row: Option<(String, String, Option<String>, Option<String>)> = transaction
        .query_row(
            "SELECT payload_json, receipt_object_sha256, form_evidence_object_sha256, form_evidence_canonical_sha256 FROM production_weapon_form_quality_links WHERE form_quality_id = ?1",
            params![form_quality_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((payload_json, receipt_sha256, form_evidence_sha256, form_evidence_canonical)) = row
    else {
        return Ok(None);
    };
    let mut quality: ProductionWeaponFormQualityRecord = serde_json::from_str(&payload_json)
        .map_err(|error| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_PAYLOAD_INVALID",
                error.to_string(),
            )
        })?;
    quality.receipt_object_sha256 = receipt_sha256.clone();
    validate_production_weapon_form_quality(&quality)?;
    if quality.form_quality_id != form_quality_id
        || production_weapon_form_quality_payload_json(&quality)? != payload_json
        || form_evidence_sha256.as_deref() != Some(quality.form_evidence_object_sha256.as_str())
        || form_evidence_canonical.as_deref()
            != Some(quality.form_evidence_canonical_sha256.as_str())
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_PAYLOAD_BINDING_MISMATCH",
            "stored form-quality payload differs from its SQLite binding",
        ));
    }
    let receipt = read_form_quality_object(
        transaction,
        cas,
        &receipt_sha256,
        "form-quality receipt",
        Some(PRODUCTION_WEAPON_FORM_QUALITY_RECEIPT_KIND),
        true,
        MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
    )?;
    ensure_production_weapon_form_quality_receipt(cas, &receipt, &payload_json)?;
    let bundle_views =
        ensure_production_weapon_form_quality_cross_view_binding(transaction, cas, &quality, true)?;
    ensure_production_weapon_form_quality_stage_bindings(transaction, cas, &quality, true)?;
    ensure_production_weapon_form_quality_form_evidence_binding(transaction, cas, &quality, true)?;
    ensure_production_weapon_form_quality_children(transaction, &quality, &bundle_views)?;
    ensure_production_weapon_form_quality_cas_refs(
        transaction,
        cas,
        &quality,
        &bundle_views,
        true,
    )?;
    Ok(Some(quality))
}

fn read_production_weapon_form_quality_for_connection(
    connection: &mut Connection,
    cas: &CasStore,
    form_quality_id: &str,
) -> Result<Option<ProductionWeaponFormQualityRecord>, StoreError> {
    let transaction = connection.transaction()?;
    let result =
        read_production_weapon_form_quality_in_transaction(&transaction, cas, form_quality_id)?;
    transaction.rollback()?;
    Ok(result)
}

fn same_production_weapon_form_quality(
    left: &ProductionWeaponFormQualityRecord,
    right: &ProductionWeaponFormQualityRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left.receipt_object_sha256.clear();
    right.receipt_object_sha256.clear();
    left == right
}

fn record_production_weapon_form_quality_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    quality: &ProductionWeaponFormQualityRecord,
    receipt_object: &CasObjectRecord,
    payload_json: &str,
) -> Result<(ProductionWeaponFormQualityRecord, bool), StoreError> {
    let receipt = read_form_quality_object(
        transaction,
        cas,
        &receipt_object.sha256,
        "form-quality receipt",
        Some(PRODUCTION_WEAPON_FORM_QUALITY_RECEIPT_KIND),
        false,
        MAX_PRODUCTION_WEAPON_FORM_QUALITY_OBJECT_BYTES,
    )?;
    if receipt.size_bytes != receipt_object.size_bytes
        || receipt.mime != receipt_object.mime
        || receipt.kind != receipt_object.kind
    {
        return Err(form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_RECEIPT_METADATA_MISMATCH",
            "supplied form-quality receipt differs from the registered CAS object",
        ));
    }
    ensure_production_weapon_form_quality_receipt(cas, &receipt, payload_json)?;
    let bundle_views =
        ensure_production_weapon_form_quality_cross_view_binding(transaction, cas, quality, false)?;
    ensure_production_weapon_form_quality_stage_bindings(transaction, cas, quality, false)?;
    ensure_production_weapon_form_quality_form_evidence_binding(transaction, cas, quality, false)?;

    let existing: Option<(String, String)> = transaction
        .query_row(
            "SELECT payload_json, receipt_object_sha256 FROM production_weapon_form_quality_links WHERE form_quality_id = ?1",
            params![quality.form_quality_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if let Some((existing_payload, existing_receipt_sha256)) = existing {
        let mut existing_quality: ProductionWeaponFormQualityRecord =
            serde_json::from_str(&existing_payload).map_err(|error| {
                form_quality_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_PAYLOAD_INVALID",
                    error.to_string(),
                )
            })?;
        existing_quality.receipt_object_sha256 = existing_receipt_sha256.clone();
        validate_production_weapon_form_quality(&existing_quality)?;
        if !same_production_weapon_form_quality(&existing_quality, quality)
            || existing_receipt_sha256 != quality.receipt_object_sha256
        {
            return Err(form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_CONFLICT",
                "form_quality_id is already bound to different form evidence",
            ));
        }
        let existing_bundle_views = ensure_production_weapon_form_quality_cross_view_binding(
            transaction,
            cas,
            &existing_quality,
            false,
        )?;
        ensure_production_weapon_form_quality_children(
            transaction,
            &existing_quality,
            &existing_bundle_views,
        )?;
        ensure_production_weapon_form_quality_cas_refs(
            transaction,
            cas,
            &existing_quality,
            &existing_bundle_views,
            false,
        )?;
        let mut reachable = production_weapon_form_quality_reachable_hashes(
            transaction,
            &existing_quality,
            &existing_bundle_views,
        )?;
        reachable.push(existing_receipt_sha256);
        reachable.sort();
        reachable.dedup();
        mark_reachable_in_transaction(transaction, &reachable)?;
        let verified = read_production_weapon_form_quality_in_transaction(
            transaction,
            cas,
            &existing_quality.form_quality_id,
        )?
        .ok_or_else(|| {
            form_quality_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_REPLAY_MISSING",
                "form-quality replay disappeared",
            )
        })?;
        return Ok((verified, true));
    }

    production_weapon_form_quality_insert(transaction, quality, payload_json, &bundle_views)?;
    production_weapon_form_quality_insert_cas_refs(transaction, cas, quality, &bundle_views)?;
    let mut reachable =
        production_weapon_form_quality_reachable_hashes(transaction, quality, &bundle_views)?;
    reachable.push(receipt_object.sha256.clone());
    reachable.sort();
    reachable.dedup();
    mark_reachable_in_transaction(transaction, &reachable)?;
    let verified = read_production_weapon_form_quality_in_transaction(
        transaction,
        cas,
        &quality.form_quality_id,
    )?
    .ok_or_else(|| {
        form_quality_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_WRITE_MISSING",
            "form-quality row disappeared before commit",
        )
    })?;
    Ok((verified, false))
}

struct ProductionWeaponFormEvidencePrepared {
    record: ProductionWeaponFormEvidenceRecord,
    parent_payload_json: String,
}

fn production_weapon_form_evidence_error(code: &str, message: impl Into<String>) -> StoreError {
    StoreError::Contract {
        code: code.to_owned(),
        message: message.into(),
    }
}

fn validate_production_weapon_form_evidence_observation(
    observation: &ProductionWeaponFormEvidenceObservation,
    expected_kind: &str,
    label: &str,
) -> Result<(), StoreError> {
    if observation.evidence_kind != expected_kind
        || !["observed", "inferred", "unknown"].contains(&observation.observation_status.as_str())
        || observation.quality_status != "NOT_PROVEN"
    {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_OBSERVATION_INVALID",
            format!("{label} observation is invalid"),
        ));
    }
    Ok(())
}

fn validate_production_weapon_form_evidence_view(
    view: &ProductionWeaponFormEvidenceViewRecord,
    parent: &ProductionWeaponFormEvidenceRecord,
    expected_kind: &str,
) -> Result<(), StoreError> {
    if view.schema_version != "ProductionWeaponFormEvidenceView@1"
        || view.project_id != parent.project_id
        || view.candidate_id != parent.candidate_id
        || view.candidate_state_sha256 != parent.candidate_state_sha256
        || view.artifact_id != parent.artifact_id
        || view.artifact_sha256 != parent.artifact_sha256
        || view.view_kind != expected_kind
        || !is_opaque_id(&view.view_id)
        || !is_opaque_id(&view.reference_id)
        || view.render_set_view_id != view.view_id
        || !is_sha256(&view.reference_sha256)
        || !is_sha256(&view.camera_hash)
        || !is_sha256(&view.camera_canonical_sha256)
        || !is_sha256(&view.render_set_object_sha256)
        || !is_sha256(&view.render_set_canonical_sha256)
        || !is_sha256(&view.receipt_object_sha256)
        || !["observed", "inferred", "unknown"].contains(&view.view_observation_status.as_str())
        || view.quality_status != "NOT_PROVEN"
        || !is_sha256(&view.canonical_sha256)
        || view.created_at.is_empty()
        || view.created_at.len() > 128
    {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_VIEW_INVALID",
            format!("view {expected_kind} is malformed"),
        ));
    }
    validate_production_weapon_form_evidence_observation(
        &view.part_id_evidence.observation,
        "part-id",
        "part-id",
    )?;
    validate_production_weapon_form_evidence_observation(
        &view.negative_space_evidence.observation,
        "negative-space",
        "negative-space",
    )?;
    validate_production_weapon_form_evidence_observation(
        &view.line_flow_evidence.observation,
        "line-flow",
        "line-flow",
    )?;
    let unique_strings = |values: &[String]| {
        values.len() <= 512
            && values.iter().all(|value| is_opaque_id(value))
            && values
                .iter()
                .collect::<std::collections::BTreeSet<_>>()
                .len()
                == values.len()
    };
    if !unique_strings(&view.part_id_evidence.expected_part_ids)
        || !unique_strings(&view.part_id_evidence.observed_part_ids)
        || !unique_strings(&view.part_id_evidence.missing_part_ids)
        || !unique_strings(&view.part_id_evidence.unexpected_part_ids)
        || view.negative_space_evidence.expected_count > 512
        || view.negative_space_evidence.observed_count > 512
        || view.negative_space_evidence.missing_count > 512
        || view.negative_space_evidence.sealed_count > 512
        || view.line_flow_evidence.expected_count > 512
        || view.line_flow_evidence.observed_count > 512
        || view.part_id_evidence.coverage_milli > 1000
        || view.negative_space_evidence.coverage_milli > 1000
        || view.line_flow_evidence.coverage_milli > 1000
        || view.line_flow_evidence.continuity_milli > 1000
        || view.line_flow_evidence.deviation_milli > 100_000
    {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_OBSERVATION_INVALID",
            format!("view {expected_kind} observation bounds are invalid"),
        ));
    }
    let mut canonical =
        serde_json::to_value(view).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    canonical["receipt_object_sha256"] = Value::String(String::new());
    canonical["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&canonical) != view.canonical_sha256 {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_VIEW_CANONICAL_MISMATCH",
            format!("view {expected_kind} canonical differs"),
        ));
    }
    Ok(())
}

fn validate_production_weapon_form_evidence(
    record: &ProductionWeaponFormEvidenceRecord,
) -> Result<(), StoreError> {
    let ids = [
        record.form_evidence_id.as_str(),
        record.session_id.as_str(),
        record.project_id.as_str(),
        record.candidate_id.as_str(),
        record.artifact_id.as_str(),
        record.camera_lock_id.as_str(),
        record.camera_lock_source_transition_id.as_str(),
    ];
    let hashes = [
        record.candidate_state_sha256.as_str(),
        record.artifact_sha256.as_str(),
        record.reference_canvas_object_sha256.as_str(),
        record.reference_canvas_canonical_sha256.as_str(),
        record.design_spec_object_sha256.as_str(),
        record.design_spec_canonical_sha256.as_str(),
        record.camera_lock_canonical_sha256.as_str(),
        record.camera_rig_object_sha256.as_str(),
        record.camera_rig_canonical_sha256.as_str(),
        record.camera_lock_receipt_object_sha256.as_str(),
        record.camera_lock_source_transition_sha256.as_str(),
        record.camera_lock_source_head_canonical_sha256.as_str(),
        record.evidence_policy_sha256.as_str(),
        record.request_sha256.as_str(),
        record.input_sha256.as_str(),
        record.receipt_object_sha256.as_str(),
        record.canonical_sha256.as_str(),
    ];
    let expected_views = [
        "front",
        "back",
        "left",
        "right",
        "top",
        "rear-three-quarter",
    ]
    .iter()
    .map(|value| (*value).to_owned())
    .collect::<Vec<_>>();
    if record.schema_version != "ProductionWeaponFormEvidence@1"
        || ids.iter().any(|value| !is_opaque_id(value))
        || hashes.iter().any(|value| !is_sha256(value))
        || record.reference_canvas_object_sha256 == record.design_spec_object_sha256
        || record.view_kinds != expected_views
        || record.views.len() != expected_views.len()
        || record.evidence_policy != "production-weapon-form-evidence-six-view-typed-observation@1"
        || record.evidence_policy_sha256
            != sha256_hex(b"production-weapon-form-evidence-six-view-typed-observation@1")
        || record.quality_status != "NOT_PROVEN"
        || !record.runtime_write_performed
        || record.production_stage_advanced
        || record.candidate_confirmed
        || record.version_created
        || record.export_performed
        || record.created_at.is_empty()
        || record.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "ProductionWeaponFormEvidence@1 record is malformed".to_owned(),
        ));
    }
    let mut ids_seen = std::collections::BTreeSet::new();
    for (view, expected) in record.views.iter().zip(expected_views.iter()) {
        if !ids_seen.insert(view.view_id.as_str()) {
            return Err(production_weapon_form_evidence_error(
                "PRODUCTION_WEAPON_FORM_EVIDENCE_VIEW_DUPLICATE",
                "form evidence view id is duplicated",
            ));
        }
        validate_production_weapon_form_evidence_view(view, record, expected)?;
    }
    let mut canonical =
        serde_json::to_value(record).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    canonical["receipt_object_sha256"] = Value::String(String::new());
    canonical["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&canonical) != record.canonical_sha256 {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_CANONICAL_MISMATCH",
            "form evidence canonical differs",
        ));
    }
    Ok(())
}

fn production_weapon_form_evidence_view_payload(
    view: &ProductionWeaponFormEvidenceViewRecord,
) -> Result<String, StoreError> {
    let mut value =
        serde_json::to_value(view).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    value["receipt_object_sha256"] = Value::String(String::new());
    let bytes =
        canonical_json_bytes(&value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if bytes.is_empty() || bytes.len() as u64 > MAX_PRODUCTION_WEAPON_FORM_EVIDENCE_PAYLOAD_BYTES {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_PAYLOAD_TOO_LARGE",
            "form evidence view receipt exceeds 1 MiB",
        ));
    }
    String::from_utf8(bytes).map_err(|error| StoreError::InvalidData(error.to_string()))
}

fn production_weapon_form_evidence_payload(
    record: &ProductionWeaponFormEvidenceRecord,
) -> Result<String, StoreError> {
    let mut value =
        serde_json::to_value(record).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    value["receipt_object_sha256"] = Value::String(String::new());
    let bytes =
        canonical_json_bytes(&value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if bytes.is_empty() || bytes.len() as u64 > MAX_PRODUCTION_WEAPON_FORM_EVIDENCE_PAYLOAD_BYTES {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_PAYLOAD_TOO_LARGE",
            "form evidence receipt exceeds 1 MiB",
        ));
    }
    String::from_utf8(bytes).map_err(|error| StoreError::InvalidData(error.to_string()))
}

fn ensure_production_weapon_form_evidence_receipt(
    cas: &CasStore,
    object: &CasObjectRecord,
    expected_kind: &str,
    payload: &str,
) -> Result<(), StoreError> {
    if object.schema_version != "CasObject@1"
        || !is_sha256(&object.sha256)
        || object.mime != PRODUCTION_WEAPON_FORM_EVIDENCE_JSON_MIME
        || object.kind != expected_kind
        || object.size_bytes == 0
        || object.size_bytes > MAX_PRODUCTION_WEAPON_FORM_EVIDENCE_OBJECT_BYTES
        || object.size_bytes != payload.len() as u64
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || object.created_at.is_empty()
    {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_RECEIPT_INVALID",
            "form evidence receipt metadata is invalid",
        ));
    }
    cas.verify(&object.sha256, object.size_bytes)?;
    let bytes = cas.read_verified_bounded(
        &object.sha256,
        MAX_PRODUCTION_WEAPON_FORM_EVIDENCE_OBJECT_BYTES,
    )?;
    if bytes != payload.as_bytes() || sha256_hex(&bytes) != object.sha256 {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_RECEIPT_BINDING_MISMATCH",
            "form evidence receipt bytes differ from its canonical projection",
        ));
    }
    Ok(())
}

fn validate_and_prepare_production_weapon_form_evidence(
    record: &ProductionWeaponFormEvidenceRecord,
    child_objects: &[CasObjectRecord],
    parent_object: &CasObjectRecord,
    cas: &CasStore,
) -> Result<ProductionWeaponFormEvidencePrepared, StoreError> {
    if parent_object.sha256 != record.receipt_object_sha256 {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_RECEIPT_BINDING_MISMATCH",
            "parent receipt hash differs from the record",
        ));
    }
    if child_objects.len() != 6 || record.views.len() != 6 {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_CHILD_COUNT_MISMATCH",
            "form evidence requires exactly six child receipts",
        ));
    }
    validate_production_weapon_form_evidence(record)?;
    let parent_payload = production_weapon_form_evidence_payload(record)?;
    ensure_production_weapon_form_evidence_receipt(
        cas,
        parent_object,
        PRODUCTION_WEAPON_FORM_EVIDENCE_PARENT_RECEIPT_KIND,
        &parent_payload,
    )?;
    for (view, object) in record.views.iter().zip(child_objects.iter()) {
        if object.sha256 != view.receipt_object_sha256 {
            return Err(production_weapon_form_evidence_error(
                "PRODUCTION_WEAPON_FORM_EVIDENCE_VIEW_RECEIPT_BINDING_MISMATCH",
                "view receipt hash differs from the view record",
            ));
        }
        let payload = production_weapon_form_evidence_view_payload(view)?;
        ensure_production_weapon_form_evidence_receipt(
            cas,
            object,
            PRODUCTION_WEAPON_FORM_EVIDENCE_VIEW_RECEIPT_KIND,
            &payload,
        )?;
    }
    Ok(ProductionWeaponFormEvidencePrepared {
        record: record.clone(),
        parent_payload_json: parent_payload,
    })
}

fn ensure_production_weapon_form_evidence_bindings(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    record: &ProductionWeaponFormEvidenceRecord,
    require_reachable: bool,
) -> Result<Vec<String>, StoreError> {
    let candidate: Option<(String, String, Option<String>, Option<String>)> = transaction
        .query_row(
            "SELECT project_id, canonical_sha256, prepared_object_id, prepared_object_sha256 FROM candidates WHERE candidate_id = ?1",
            params![record.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((project_id, state_sha, artifact_id, artifact_sha)) = candidate else {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_CANDIDATE_MISSING",
            "form evidence candidate is unavailable",
        ));
    };
    if project_id != record.project_id
        || state_sha != record.candidate_state_sha256
        || artifact_id.as_deref() != Some(record.artifact_id.as_str())
        || artifact_sha.as_deref() != Some(record.artifact_sha256.as_str())
    {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_CANDIDATE_BINDING_MISMATCH",
            "form evidence candidate/artifact binding differs",
        ));
    }
    let artifact = read_form_quality_object(
        transaction,
        cas,
        &record.artifact_sha256,
        "form evidence artifact",
        None,
        require_reachable,
        64 * 1024 * 1024,
    )?;
    if artifact.mime != "model/gltf-binary"
        || !matches!(
            artifact.kind.as_str(),
            "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
        )
    {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_ARTIFACT_INVALID",
            "form evidence artifact is not an allowed GLB",
        ));
    }
    let session: Option<(String, String)> = transaction
        .query_row(
            "SELECT project_id, candidate_id FROM agentic_design_sessions WHERE session_id = ?1",
            params![record.session_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if session.as_ref() != Some(&(record.project_id.clone(), record.candidate_id.clone())) {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_SESSION_BINDING_MISMATCH",
            "form evidence session is outside the project/candidate",
        ));
    }
    let lock =
        read_production_camera_lock_in_transaction(transaction, cas, &record.camera_lock_id)?
            .ok_or_else(|| {
                production_weapon_form_evidence_error(
                    "PRODUCTION_WEAPON_FORM_EVIDENCE_CAMERA_LOCK_MISSING",
                    "camera lock is unavailable",
                )
            })?;
    if lock.session_id != record.session_id
        || lock.project_id != record.project_id
        || lock.candidate_id != record.candidate_id
        || lock.candidate_state_sha256 != record.candidate_state_sha256
        || lock.artifact_id != record.artifact_id
        || lock.artifact_sha256 != record.artifact_sha256
        || lock.canonical_sha256 != record.camera_lock_canonical_sha256
        || lock.reference_canvas_object_sha256 != record.reference_canvas_object_sha256
        || lock.reference_canvas_canonical_sha256 != record.reference_canvas_canonical_sha256
        || lock.design_spec_object_sha256 != record.design_spec_object_sha256
        || lock.design_spec_canonical_sha256 != record.design_spec_canonical_sha256
        || lock.camera_rig_object_sha256 != record.camera_rig_object_sha256
        || lock.camera_rig_canonical_sha256 != record.camera_rig_canonical_sha256
        || lock.receipt_object_sha256 != record.camera_lock_receipt_object_sha256
        || lock.source_transition_id != record.camera_lock_source_transition_id
        || lock.source_transition_sha256 != record.camera_lock_source_transition_sha256
        || lock.source_head_canonical_sha256 != record.camera_lock_source_head_canonical_sha256
    {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_CAMERA_LOCK_BINDING_MISMATCH",
            "form evidence CameraLock binding differs",
        ));
    }
    let canvas = form_quality_json_object(
        transaction,
        cas,
        &record.reference_canvas_object_sha256,
        "form evidence reference canvas",
        Some("reference-canvas"),
        require_reachable,
    )?;
    ensure_form_quality_canonical_value(&canvas, "ReferenceCanvas@1", "form evidence canvas")?;
    if canvas.get("project_id").and_then(Value::as_str) != Some(record.project_id.as_str())
        || canvas.get("canonical_sha256").and_then(Value::as_str)
            != Some(record.reference_canvas_canonical_sha256.as_str())
    {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_CANVAS_BINDING_MISMATCH",
            "reference canvas binding differs",
        ));
    }
    let spec = form_quality_json_object(
        transaction,
        cas,
        &record.design_spec_object_sha256,
        "form evidence design spec",
        Some("design-spec"),
        require_reachable,
    )?;
    ensure_form_quality_canonical_value(&spec, "DesignSpec@1", "form evidence design spec")?;
    if spec.get("project_id").and_then(Value::as_str) != Some(record.project_id.as_str())
        || spec.get("canonical_sha256").and_then(Value::as_str)
            != Some(record.design_spec_canonical_sha256.as_str())
        || spec.get("reference_canvas_sha256").and_then(Value::as_str)
            != Some(record.reference_canvas_object_sha256.as_str())
    {
        return Err(production_weapon_form_evidence_error(
            "PRODUCTION_WEAPON_FORM_EVIDENCE_DESIGN_SPEC_BINDING_MISMATCH",
            "design spec binding differs",
        ));
    }
    let mut roots = vec![
        record.artifact_sha256.clone(),
        record.reference_canvas_object_sha256.clone(),
        record.design_spec_object_sha256.clone(),
        record.camera_rig_object_sha256.clone(),
        record.camera_lock_receipt_object_sha256.clone(),
    ];
    for view in &record.views {
        let reference = read_form_quality_object(
            transaction,
            cas,
            &view.reference_sha256,
            &format!("form evidence {} reference", view.view_kind),
            None,
            require_reachable,
            64 * 1024 * 1024,
        )?;
        if reference.mime != "image/png" && reference.mime != "image/jpeg" {
            return Err(production_weapon_form_evidence_error(
                "PRODUCTION_WEAPON_FORM_EVIDENCE_REFERENCE_INVALID",
                "form evidence reference bytes are not an image",
            ));
        }
        let reference_row: Option<(String, String)> = transaction
            .query_row(
                "SELECT project_id, object_sha256 FROM reference_evidence WHERE reference_id = ?1",
                params![view.reference_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()?;
        if reference_row.as_ref()
            != Some(&(record.project_id.clone(), view.reference_sha256.clone()))
        {
            return Err(production_weapon_form_evidence_error(
                "PRODUCTION_WEAPON_FORM_EVIDENCE_REFERENCE_BINDING_MISMATCH",
                "form evidence reference binding differs",
            ));
        }
        let render = form_quality_json_object(
            transaction,
            cas,
            &view.render_set_object_sha256,
            &format!("form evidence {} RenderSet", view.view_kind),
            Some("render-set-v2"),
            require_reachable,
        )?;
        ensure_form_quality_canonical_value(&render, "RenderSet@2", "form evidence RenderSet")?;
        ensure_form_quality_render_structure(
            &render,
            &format!("form evidence {} RenderSet", view.view_kind),
        )?;
        ensure_form_quality_render_pass_cas_objects(
            transaction,
            cas,
            &render,
            &format!("form evidence {} RenderSet", view.view_kind),
            require_reachable,
        )?;
        if render.get("candidate_id").and_then(Value::as_str) != Some(record.candidate_id.as_str())
            || render.get("artifact_sha256").and_then(Value::as_str)
                != Some(record.artifact_sha256.as_str())
            || render.get("reference_id").and_then(Value::as_str)
                != Some(view.reference_id.as_str())
            || render.get("camera_hash").and_then(Value::as_str) != Some(view.camera_hash.as_str())
            || render.get("view_id").and_then(Value::as_str) != Some(view.view_id.as_str())
            || render.get("canonical_sha256").and_then(Value::as_str)
                != Some(view.render_set_canonical_sha256.as_str())
        {
            return Err(production_weapon_form_evidence_error(
                "PRODUCTION_WEAPON_FORM_EVIDENCE_RENDER_SET_BINDING_MISMATCH",
                format!("{} RenderSet binding differs", view.view_kind),
            ));
        }
        roots.push(view.reference_sha256.clone());
        roots.push(view.render_set_object_sha256.clone());
        roots.push(view.receipt_object_sha256.clone());
        let pass_artifacts = render
            .get("pass_artifacts")
            .and_then(Value::as_object)
            .expect("validated RenderSet pass artifacts");
        for pass in [
            "beauty",
            "silhouette",
            "depth",
            "normal",
            "ao",
            "part-id",
            "material-id",
            "wireframe",
            "uv-stretch",
        ] {
            roots.push(
                pass_artifacts
                    .get(pass)
                    .and_then(|artifact| artifact.get("sha256"))
                    .and_then(Value::as_str)
                    .expect("validated RenderSet pass SHA-256")
                    .to_owned(),
            );
        }
    }
    validate_reachable_hashes(&roots)?;
    Ok(roots)
}

