fn read_production_weapon_form_art_proposal_evidence_by_receipt_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    receipt_object_sha256: &str,
) -> Result<Option<ProductionWeaponFormArtProposalEvidenceRecord>, StoreError> {
    let identity: Option<String> = transaction
        .query_row(
            "SELECT identity_sha256 FROM production_weapon_form_art_proposal_evidence_links WHERE receipt_object_sha256 = ?1",
            params![receipt_object_sha256],
            |row| row.get(0),
        )
        .optional()?;
    match identity {
        Some(identity) => {
            read_production_weapon_form_art_proposal_evidence_by_identity_in_transaction(
                transaction,
                &identity,
            )
        }
        None => Ok(None),
    }
}

fn read_production_weapon_form_art_proposal_evidence_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    identity_sha256: &str,
    require_reachable: bool,
) -> Result<Option<ProductionWeaponFormArtProposalEvidenceRecord>, StoreError> {
    let Some(record) =
        read_production_weapon_form_art_proposal_evidence_by_identity_in_transaction(
            transaction,
            identity_sha256,
        )?
    else {
        return Ok(None);
    };
    let receipt_object = read_form_quality_object(
        transaction,
        cas,
        &record.receipt_object_sha256,
        "proposal FormArt evidence receipt",
        Some(PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_RECEIPT_KIND),
        require_reachable,
        MAX_PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_OBJECT_BYTES,
    )?;
    let (receipt_record, receipt) = proposal_evidence_receipt_record(cas, &receipt_object)?;
    if receipt_record != record {
        return Err(production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_ROW_MISMATCH",
            "proposal FormArt evidence SQLite row differs from its CAS receipt",
        ));
    }
    let roots = ensure_production_weapon_form_art_proposal_evidence_bindings(
        transaction,
        cas,
        &record,
        &receipt,
        require_reachable,
    )?;
    if require_reachable {
        for hash in roots {
            let reachability: Option<String> = transaction
                .query_row(
                    "SELECT reachability FROM objects WHERE sha256 = ?1",
                    params![hash],
                    |row| row.get(0),
                )
                .optional()?;
            if reachability.as_deref() != Some("reachable") {
                return Err(production_weapon_form_art_proposal_evidence_error(
                    "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_UNREACHABLE",
                    "proposal FormArt evidence dependency is not reachable",
                ));
            }
        }
    }
    Ok(Some(record))
}

fn prepare_production_weapon_form_art_proposal_evidence_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    receipt_object: &CasObjectRecord,
    require_reachable: bool,
) -> Result<
    (
        ProductionWeaponFormArtProposalEvidenceRecord,
        Value,
        Vec<String>,
    ),
    StoreError,
> {
    let authoritative_receipt = read_form_quality_object(
        transaction,
        cas,
        &receipt_object.sha256,
        "proposal FormArt evidence receipt",
        Some(PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_RECEIPT_KIND),
        require_reachable,
        MAX_PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_OBJECT_BYTES,
    )?;
    let (record, receipt) = proposal_evidence_receipt_record(cas, &authoritative_receipt)?;
    let mut roots = ensure_production_weapon_form_art_proposal_evidence_bindings(
        transaction,
        cas,
        &record,
        &receipt,
        require_reachable,
    )?;
    roots.push(receipt_object.sha256.clone());
    roots.sort();
    roots.dedup();
    validate_reachable_hashes(&roots)?;
    Ok((record, receipt, roots))
}

fn proposal_evidence_object(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    sha256: &str,
    label: &str,
    expected_kind: Option<&str>,
    require_reachable: bool,
    max_bytes: u64,
) -> Result<CasObjectRecord, StoreError> {
    read_form_quality_object(
        transaction,
        cas,
        sha256,
        label,
        expected_kind,
        require_reachable,
        max_bytes,
    )
    .map_err(|error| match error {
        StoreError::Contract { .. } => error,
        other => production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_CAS_INVALID",
            format!("{label} CAS object is invalid: {other}"),
        ),
    })
}

fn proposal_evidence_artifact_object(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    sha256: &str,
    label: &str,
    require_reachable: bool,
) -> Result<CasObjectRecord, StoreError> {
    let object = proposal_evidence_object(
        transaction,
        cas,
        sha256,
        label,
        Some("geometry-glb"),
        require_reachable,
        64 * 1024 * 1024,
    )?;
    if object.mime != "model/gltf-binary" {
        return Err(production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_ARTIFACT_INVALID",
            format!("{label} is not a GLB artifact"),
        ));
    }
    Ok(object)
}

fn proposal_evidence_png_object(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    sha256: &str,
    label: &str,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let object = proposal_evidence_object(
        transaction,
        cas,
        sha256,
        label,
        None,
        require_reachable,
        MAX_PRODUCTION_WEAPON_FORM_ART_EVIDENCE_AOV_BYTES,
    )?;
    if object.mime != "image/png" {
        return Err(production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_AOV_INVALID",
            format!("{label} is not a PNG AOV"),
        ));
    }
    Ok(())
}

fn proposal_evidence_roots(value: &Value) -> Result<Vec<String>, StoreError> {
    let mut roots = Vec::new();
    for field in [
        "source_artifact_sha256",
        "source_form_art_evidence_object_sha256",
        "proposal_artifact_sha256",
        "cross_view_evidence_bundle_sha256",
        "reference_canvas_object_sha256",
        "design_spec_object_sha256",
        "camera_rig_object_sha256",
        "camera_lock_receipt_object_sha256",
    ] {
        roots.push(proposal_evidence_hash(value, field)?);
    }
    let source_camera_evidence_kind = value
        .get("source_camera_evidence_kind")
        .and_then(Value::as_str)
        .unwrap_or("historical-form-art-camera");
    if source_camera_evidence_kind == "fresh-same-cohort-baseline-rig-v2" {
        roots.push(proposal_evidence_hash(
            value,
            "source_fresh_baseline_receipt_object_sha256",
        )?);
    }
    let views = value["views"].as_array().ok_or_else(|| {
        production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_VIEWS_INVALID",
            "proposal FormArt evidence views are missing",
        )
    })?;
    for view in views {
        for field in [
            "camera_object_sha256",
            "render_set_object_sha256",
            "silhouette_pass_object_sha256",
            "part_id_pass_object_sha256",
            "depth_pass_object_sha256",
            "normal_pass_object_sha256",
            "target_object_sha256",
        ] {
            roots.push(proposal_evidence_hash(view, field)?);
        }
        roots.push(proposal_evidence_hash(
            view,
            if source_camera_evidence_kind == "fresh-same-cohort-baseline-rig-v2" {
                "source_fresh_baseline_view_receipt_object_sha256"
            } else {
                "source_form_evidence_view_receipt_object_sha256"
            },
        )?);
    }
    roots.sort();
    roots.dedup();
    Ok(roots)
}

fn ensure_production_weapon_form_art_proposal_evidence_bindings(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    record: &ProductionWeaponFormArtProposalEvidenceRecord,
    receipt: &Value,
    require_reachable: bool,
) -> Result<Vec<String>, StoreError> {
    let source_camera_evidence_kind = receipt
        .get("source_camera_evidence_kind")
        .and_then(Value::as_str)
        .unwrap_or("historical-form-art-camera");
    let candidate =
        |candidate_id: &str| -> Result<Option<(String, String, Option<String>)>, StoreError> {
            transaction
            .query_row(
                "SELECT project_id, canonical_sha256, prepared_object_sha256 FROM candidates WHERE candidate_id = ?1",
                params![candidate_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .optional()
            .map_err(StoreError::from)
        };
    let source = candidate(&record.source_candidate_id)?;
    let proposal = candidate(&record.proposal_candidate_id)?;
    if source.as_ref().map(|row| row.0.as_str()) != Some(record.project_id.as_str())
        || source.as_ref().map(|row| row.1.as_str())
            != Some(record.source_candidate_state_sha256.as_str())
        || source.as_ref().and_then(|row| row.2.as_deref())
            != Some(record.source_artifact_sha256.as_str())
        || proposal.as_ref().map(|row| row.0.as_str()) != Some(record.project_id.as_str())
        || proposal.as_ref().map(|row| row.1.as_str())
            != Some(record.proposal_candidate_state_sha256.as_str())
        || proposal.as_ref().and_then(|row| row.2.as_deref())
            != Some(record.proposal_artifact_sha256.as_str())
    {
        return Err(production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_CANDIDATE_BINDING_MISMATCH",
            "proposal FormArt evidence source/proposal candidate binding differs",
        ));
    }

    let _ = proposal_evidence_artifact_object(
        transaction,
        cas,
        &record.source_artifact_sha256,
        "source artifact",
        require_reachable,
    )?;
    let _ = proposal_evidence_artifact_object(
        transaction,
        cas,
        &record.proposal_artifact_sha256,
        "proposal artifact",
        require_reachable,
    )?;
    let source_form_art = form_quality_json_object(
        transaction,
        cas,
        &record.source_form_art_evidence_object_sha256,
        "source FormArt evidence",
        Some(PRODUCTION_WEAPON_FORM_ART_EVIDENCE_PARENT_RECEIPT_KIND),
        require_reachable,
    )?;
    if source_form_art
        .get("art_evidence_id")
        .and_then(Value::as_str)
        != Some(record.source_form_art_evidence_id.as_str())
        || source_form_art.get("project_id").and_then(Value::as_str)
            != Some(record.project_id.as_str())
        || source_form_art.get("session_id").and_then(Value::as_str)
            != Some(record.session_id.as_str())
        || source_form_art.get("candidate_id").and_then(Value::as_str)
            != Some(record.source_candidate_id.as_str())
        || source_form_art
            .get("canonical_sha256")
            .and_then(Value::as_str)
            != Some(record.source_form_art_evidence_canonical_sha256.as_str())
    {
        return Err(production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_SOURCE_FORM_ART_MISMATCH",
            "source FormArt evidence binding differs",
        ));
    }

    let canvas = form_quality_json_object(
        transaction,
        cas,
        &record.reference_canvas_object_sha256,
        "reference canvas",
        Some("reference-canvas"),
        require_reachable,
    )?;
    let design_spec = form_quality_json_object(
        transaction,
        cas,
        &record.design_spec_object_sha256,
        "design spec",
        Some("design-spec"),
        require_reachable,
    )?;
    let camera_rig = form_quality_json_object(
        transaction,
        cas,
        &record.camera_rig_object_sha256,
        "camera rig",
        None,
        require_reachable,
    )?;
    let camera_lock = form_quality_json_object(
        transaction,
        cas,
        &record.camera_lock_receipt_object_sha256,
        "camera lock receipt",
        None,
        require_reachable,
    )?;
    if canvas.get("canonical_sha256").and_then(Value::as_str)
        != Some(record.reference_canvas_canonical_sha256.as_str())
        || design_spec.get("canonical_sha256").and_then(Value::as_str)
            != Some(record.design_spec_canonical_sha256.as_str())
        || camera_rig.get("canonical_sha256").and_then(Value::as_str)
            != Some(record.camera_rig_canonical_sha256.as_str())
        || camera_lock.get("camera_lock_id").and_then(Value::as_str)
            != Some(record.camera_lock_id.as_str())
        || camera_lock.get("canonical_sha256").and_then(Value::as_str)
            != Some(record.camera_lock_canonical_sha256.as_str())
    {
        return Err(production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_SOURCE_BINDING_MISMATCH",
            "ReferenceCanvas, DesignSpec, CameraRig or CameraLock binding differs",
        ));
    }

    let fresh_baseline = if source_camera_evidence_kind == "fresh-same-cohort-baseline-rig-v2" {
        let baseline_hash =
            proposal_evidence_hash(receipt, "source_fresh_baseline_receipt_object_sha256")?;
        let baseline = form_quality_json_object(
            transaction,
            cas,
            &baseline_hash,
            "fresh source FormArt baseline",
            Some(PRODUCTION_WEAPON_FORM_ART_BASELINE_PARENT_OBJECT_KIND),
            require_reachable,
        )?;
        if baseline.get("baseline_id").and_then(Value::as_str)
            != receipt
                .get("source_fresh_baseline_id")
                .and_then(Value::as_str)
            || baseline.get("canonical_sha256").and_then(Value::as_str)
                != receipt
                    .get("source_fresh_baseline_canonical_sha256")
                    .and_then(Value::as_str)
            || baseline.get("project_id").and_then(Value::as_str)
                != Some(record.project_id.as_str())
            || baseline.get("session_id").and_then(Value::as_str)
                != Some(record.session_id.as_str())
            || baseline.get("candidate_id").and_then(Value::as_str)
                != Some(record.source_candidate_id.as_str())
            || baseline
                .get("candidate_state_sha256")
                .and_then(Value::as_str)
                != Some(record.source_candidate_state_sha256.as_str())
            || baseline.get("artifact_sha256").and_then(Value::as_str)
                != Some(record.source_artifact_sha256.as_str())
            || baseline
                .get("registration_lineage_id")
                .and_then(Value::as_str)
                != receipt
                    .get("source_registration_lineage_id")
                    .and_then(Value::as_str)
            || baseline
                .get("registration_lineage_canonical_sha256")
                .and_then(Value::as_str)
                != receipt
                    .get("source_registration_lineage_canonical_sha256")
                    .and_then(Value::as_str)
            || baseline.get("registered_rig_v2_id").and_then(Value::as_str)
                != receipt
                    .get("source_registered_rig_v2_id")
                    .and_then(Value::as_str)
        {
            return Err(production_weapon_form_art_proposal_evidence_error(
                "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_FRESH_BASELINE_BINDING_MISMATCH",
                "fresh source FormArt baseline binding differs",
            ));
        }
        Some(baseline)
    } else {
        None
    };

    let bundle = form_quality_json_object(
        transaction,
        cas,
        &record.cross_view_evidence_bundle_sha256,
        "proposal CrossView evidence bundle",
        None,
        require_reachable,
    )?;
    if bundle.get("schema_version").and_then(Value::as_str) != Some("CrossViewEvidenceBundle@1")
        || bundle.get("project_id").and_then(Value::as_str) != Some(record.project_id.as_str())
        || bundle.get("session_id").and_then(Value::as_str) != Some(record.session_id.as_str())
        || bundle.get("candidate_id").and_then(Value::as_str)
            != Some(record.proposal_candidate_id.as_str())
        || bundle.get("candidate_state_sha256").and_then(Value::as_str)
            != Some(record.proposal_candidate_state_sha256.as_str())
        || bundle.get("artifact_sha256").and_then(Value::as_str)
            != Some(record.proposal_artifact_sha256.as_str())
    {
        return Err(production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_CROSS_VIEW_MISMATCH",
            "proposal CrossView evidence binding differs",
        ));
    }

    let bundle_views = bundle
        .get("view_evaluations")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            production_weapon_form_art_proposal_evidence_error(
                "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_CROSS_VIEW_MISMATCH",
                "proposal CrossView evidence has no views",
            )
        })?;
    let receipt_views = receipt["views"].as_array().ok_or_else(|| {
        production_weapon_form_art_proposal_evidence_error(
            "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_VIEWS_INVALID",
            "proposal FormArt evidence views are missing",
        )
    })?;
    for view in receipt_views {
        let kind = proposal_evidence_text(view, "view_kind")?;
        let bundle_view = bundle_views
            .iter()
            .find(|candidate| candidate.get("kind").and_then(Value::as_str) == Some(kind))
            .ok_or_else(|| {
                production_weapon_form_art_proposal_evidence_error(
                    "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_CROSS_VIEW_MISMATCH",
                    format!("proposal CrossView evidence is missing {kind}"),
                )
            })?;
        let render_hash = proposal_evidence_hash(view, "render_set_object_sha256")?;
        if bundle_view
            .get("proposal_render_set_sha256")
            .and_then(Value::as_str)
            != Some(render_hash.as_str())
        {
            return Err(production_weapon_form_art_proposal_evidence_error(
                "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_RENDER_BINDING_MISMATCH",
                format!("proposal RenderSet {kind} differs from CrossView evidence"),
            ));
        }
        let render = form_quality_json_object(
            transaction,
            cas,
            &render_hash,
            "proposal RenderSet",
            Some(PRODUCTION_WEAPON_FORM_QUALITY_RENDER_SET_KIND),
            require_reachable,
        )?;
        if render.get("candidate_id").and_then(Value::as_str)
            != Some(record.proposal_candidate_id.as_str())
            || render.get("artifact_sha256").and_then(Value::as_str)
                != Some(record.proposal_artifact_sha256.as_str())
            || render.get("view_id").and_then(Value::as_str)
                != view.get("view_id").and_then(Value::as_str)
            || render.get("reference_id").and_then(Value::as_str)
                != view.get("reference_id").and_then(Value::as_str)
            || render.get("camera_hash").and_then(Value::as_str)
                != view.get("camera_hash").and_then(Value::as_str)
            || render.get("canonical_sha256").and_then(Value::as_str)
                != view
                    .get("render_set_canonical_sha256")
                    .and_then(Value::as_str)
        {
            return Err(production_weapon_form_art_proposal_evidence_error(
                "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_RENDER_BINDING_MISMATCH",
                format!("proposal RenderSet {kind} binding differs"),
            ));
        }
        for (receipt_field, pass_name) in [
            ("silhouette_pass_object_sha256", "silhouette"),
            ("part_id_pass_object_sha256", "part-id"),
            ("depth_pass_object_sha256", "depth"),
            ("normal_pass_object_sha256", "normal"),
        ] {
            let hash = proposal_evidence_hash(view, receipt_field)?;
            if render
                .pointer(&format!("/pass_artifacts/{pass_name}/sha256"))
                .and_then(Value::as_str)
                != Some(hash.as_str())
            {
                return Err(production_weapon_form_art_proposal_evidence_error(
                    "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_AOV_BINDING_MISMATCH",
                    format!("proposal {kind} {pass_name} AOV binding differs"),
                ));
            }
            proposal_evidence_png_object(transaction, cas, &hash, pass_name, require_reachable)?;
        }
        for field in ["camera_object_sha256", "target_object_sha256"] {
            let hash = proposal_evidence_hash(view, field)?;
            let _ = proposal_evidence_object(
                transaction,
                cas,
                &hash,
                field,
                None,
                require_reachable,
                MAX_PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_OBJECT_BYTES,
            )?;
        }
        let source_receipt_field =
            if source_camera_evidence_kind == "fresh-same-cohort-baseline-rig-v2" {
                "source_fresh_baseline_view_receipt_object_sha256"
            } else {
                "source_form_evidence_view_receipt_object_sha256"
            };
        let source_receipt_hash = proposal_evidence_hash(view, source_receipt_field)?;
        let _ = proposal_evidence_object(
            transaction,
            cas,
            &source_receipt_hash,
            source_receipt_field,
            None,
            require_reachable,
            MAX_PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_OBJECT_BYTES,
        )?;
        if let Some(baseline) = fresh_baseline.as_ref() {
            let baseline_view = baseline
                .get("views")
                .and_then(Value::as_array)
                .and_then(|views| {
                    views.iter().find(|baseline_view| {
                        baseline_view.get("view_kind").and_then(Value::as_str) == Some(kind)
                    })
                });
            if baseline_view.and_then(|baseline_view| {
                baseline_view
                    .get("receipt_object_sha256")
                    .and_then(Value::as_str)
            }) != Some(source_receipt_hash.as_str())
            {
                return Err(production_weapon_form_art_proposal_evidence_error(
                    "PRODUCTION_WEAPON_FORM_ART_PROPOSAL_EVIDENCE_FRESH_BASELINE_VIEW_BINDING_MISMATCH",
                    format!("fresh source FormArt baseline {kind} view receipt differs"),
                ));
            }
        }
    }
    proposal_evidence_roots(receipt)
}

fn form_quality_v2_error(code: &str, message: impl Into<String>) -> StoreError {
    StoreError::Contract {
        code: code.to_owned(),
        message: message.into(),
    }
}

fn production_weapon_form_quality_v2_view_payload(
    view: &ProductionWeaponFormQualityV2ViewDecision,
) -> Result<(String, String), StoreError> {
    let value = serde_json::to_value(view).map_err(|error| {
        form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_SERIALIZE",
            error.to_string(),
        )
    })?;
    let bytes = canonical_json_bytes(&value).map_err(|error| {
        form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CANONICAL",
            error.to_string(),
        )
    })?;
    Ok((
        String::from_utf8(bytes).map_err(|error| {
            form_quality_v2_error("PRODUCTION_WEAPON_FORM_QUALITY_V2_UTF8", error.to_string())
        })?,
        canonical_json_hash(&value),
    ))
}

fn production_weapon_form_quality_v2_payload_json(
    record: &ProductionWeaponFormQualityV2Record,
) -> Result<String, StoreError> {
    let mut value = serde_json::to_value(record).map_err(|error| {
        form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_SERIALIZE",
            error.to_string(),
        )
    })?;
    value["receipt_object_sha256"] = Value::String(String::new());
    let bytes = canonical_json_bytes(&value).map_err(|error| {
        form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CANONICAL",
            error.to_string(),
        )
    })?;
    if bytes.is_empty() || bytes.len() as u64 > MAX_PRODUCTION_WEAPON_FORM_QUALITY_V2_PAYLOAD_BYTES
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_PAYLOAD_BOUNDED",
            "V2 form-quality report exceeds the 1 MiB bound",
        ));
    }
    String::from_utf8(bytes).map_err(|error| {
        form_quality_v2_error("PRODUCTION_WEAPON_FORM_QUALITY_V2_UTF8", error.to_string())
    })
}

fn ensure_production_weapon_form_quality_v2_receipt(
    cas: &CasStore,
    object: &CasObjectRecord,
    payload_json: &str,
) -> Result<(), StoreError> {
    if object.schema_version != "CasObject@1"
        || !is_sha256(&object.sha256)
        || object.mime != PRODUCTION_WEAPON_FORM_QUALITY_V2_JSON_MIME
        || object.kind != PRODUCTION_WEAPON_FORM_QUALITY_V2_REPORT_KIND
        || object.size_bytes == 0
        || object.size_bytes > MAX_PRODUCTION_WEAPON_FORM_QUALITY_V2_OBJECT_BYTES
        || object.size_bytes != payload_json.len() as u64
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || object.created_at.is_empty()
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_REPORT_METADATA_INVALID",
            "V2 report CAS metadata is invalid",
        ));
    }
    cas.verify(&object.sha256, object.size_bytes)?;
    let bytes = cas.read_verified_bounded(
        &object.sha256,
        MAX_PRODUCTION_WEAPON_FORM_QUALITY_V2_OBJECT_BYTES,
    )?;
    if bytes != payload_json.as_bytes() {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_REPORT_BINDING_MISMATCH",
            "V2 report bytes differ from its canonical projection",
        ));
    }
    Ok(())
}

fn validate_production_weapon_form_quality_v2(
    record: &ProductionWeaponFormQualityV2Record,
) -> Result<(), StoreError> {
    let ids = [
        record.form_quality_id.as_str(),
        record.session_id.as_str(),
        record.project_id.as_str(),
        record.current_source_head_transition_id.as_str(),
        record.current_source_head_stage.as_str(),
        record.current_source_head_candidate_id.as_str(),
        record.current_source_head_artifact_id.as_str(),
        record.candidate_id.as_str(),
        record.artifact_id.as_str(),
        record.reference_id.as_str(),
        record.camera_lock_id.as_str(),
        record.camera_lock_source_transition_id.as_str(),
    ];
    let hashes = [
        record.current_source_head_transition_sha256.as_str(),
        record.current_source_head_canonical_sha256.as_str(),
        record.current_source_head_candidate_state_sha256.as_str(),
        record.current_source_head_artifact_sha256.as_str(),
        record.candidate_state_sha256.as_str(),
        record.artifact_sha256.as_str(),
        record.reference_sha256.as_str(),
        record.reference_canvas_object_sha256.as_str(),
        record.reference_canvas_canonical_sha256.as_str(),
        record.design_spec_object_sha256.as_str(),
        record.design_spec_canonical_sha256.as_str(),
        record.camera_hash.as_str(),
        record.camera_lock_canonical_sha256.as_str(),
        record.camera_rig_object_sha256.as_str(),
        record.camera_rig_canonical_sha256.as_str(),
        record.camera_lock_receipt_object_sha256.as_str(),
        record.camera_lock_source_transition_sha256.as_str(),
        record.camera_lock_source_head_canonical_sha256.as_str(),
        record.legacy_form_quality_object_sha256.as_str(),
        record.legacy_form_quality_canonical_sha256.as_str(),
        record.form_art_evidence_object_sha256.as_str(),
        record.form_art_evidence_canonical_sha256.as_str(),
        record.form_quality_policy_sha256.as_str(),
        record.threshold_policy_sha256.as_str(),
        record.request_sha256.as_str(),
        record.input_sha256.as_str(),
        record.canonical_sha256.as_str(),
    ];
    let previous_valid = match (
        record.previous_form_quality_id.as_deref(),
        record.previous_form_quality_report_object_sha256.as_deref(),
        record.previous_form_quality_canonical_sha256.as_deref(),
    ) {
        (None, None, None) => true,
        (Some(id), Some(report), Some(canonical)) => {
            is_opaque_id(id) && is_sha256(report) && is_sha256(canonical)
        }
        _ => false,
    };
    let stage_index = PRODUCTION_WEAPON_FORM_QUALITY_V2_FORM_STAGES
        .iter()
        .position(|stage| *stage == record.form_stage);
    let expected_source = stage_index
        .and_then(|index| PRODUCTION_WEAPON_FORM_QUALITY_V2_SOURCE_STAGES.get(index))
        .copied();
    let expected_target = stage_index
        .and_then(|index| PRODUCTION_WEAPON_FORM_QUALITY_V2_TARGET_STAGES.get(index))
        .copied();
    let expected_views = PRODUCTION_WEAPON_FORM_QUALITY_V2_VIEW_KINDS
        .iter()
        .map(|value| (*value).to_owned())
        .collect::<Vec<_>>();
    let expected_fixed = PRODUCTION_WEAPON_FORM_QUALITY_V2_FIXED_CAMERA_VIEW_KINDS
        .iter()
        .map(|value| (*value).to_owned())
        .collect::<Vec<_>>();
    let aggregate_ok = record.aggregate
        == ProductionWeaponFormQualityV2Aggregate {
            view_count: 6,
            all_cross_view_thresholds_passed: true,
            all_no_regression_passed: true,
            all_part_id_passed: true,
            all_negative_space_passed: true,
            all_line_flow_passed: true,
            all_view_passed: true,
        };
    let views_ok = record.view_decisions.len() == expected_views.len()
        && record
            .view_decisions
            .iter()
            .zip(expected_views.iter())
            .all(|(view, expected)| {
                view.view_kind == *expected
                    && is_opaque_id(&view.legacy_form_quality_view_id)
                    && is_sha256(&view.legacy_form_quality_view_canonical_sha256)
                    && is_opaque_id(&view.form_art_view_id)
                    && is_sha256(&view.form_art_view_canonical_sha256)
                    && is_sha256(&view.form_art_view_receipt_object_sha256)
                    && is_sha256(&view.target_object_sha256)
                    && is_sha256(&view.target_canonical_sha256)
                    && is_sha256(&view.silhouette_pass_object_sha256)
                    && is_sha256(&view.part_id_pass_object_sha256)
                    && is_sha256(&view.depth_pass_object_sha256)
                    && is_sha256(&view.normal_pass_object_sha256)
                    && view.cross_view_thresholds_passed
                    && view.no_regression_passed
                    && view.part_id_passed
                    && view.negative_space_passed
                    && view.line_flow_passed
                    && view.view_passed
            });
    let optional_ids = [
        &record.source_candidate_id,
        &record.source_artifact_id,
        &record.source_fresh_baseline_id,
        &record.source_registration_lineage_id,
        &record.source_registered_rig_v2_id,
        &record.proposal_candidate_id,
        &record.proposal_artifact_id,
        &record.proposal_form_art_evidence_id,
    ];
    let optional_hashes = [
        &record.source_candidate_state_sha256,
        &record.source_artifact_sha256,
        &record.source_fresh_baseline_canonical_sha256,
        &record.source_fresh_baseline_receipt_object_sha256,
        &record.source_registration_lineage_canonical_sha256,
        &record.source_registration_lineage_receipt_object_sha256,
        &record.source_registered_rig_v2_object_sha256,
        &record.source_registered_rig_v2_canonical_sha256,
        &record.source_runtime_build_cohort_sha256,
        &record.proposal_candidate_state_sha256,
        &record.proposal_artifact_sha256,
        &record.proposal_artifact_readback_sha256,
        &record.proposal_worker_build_cohort_sha256,
        &record.cross_view_evidence_bundle_sha256,
        &record.proposal_form_art_evidence_object_sha256,
        &record.proposal_form_art_evidence_canonical_sha256,
        &record.proposal_part_id_evidence_sha256,
        &record.proposal_negative_space_evidence_sha256,
        &record.proposal_line_flow_evidence_sha256,
    ];
    let optional_values_valid = optional_ids
        .iter()
        .all(|value| value.as_deref().is_none_or(is_opaque_id))
        && optional_hashes
            .iter()
            .all(|value| value.as_deref().is_none_or(is_sha256));
    let scope_values = optional_ids
        .iter()
        .chain(optional_hashes.iter())
        .map(|value| value.is_some())
        .collect::<Vec<_>>();
    let evidence_scope_valid = match record.evidence_source_kind.as_str() {
        "legacy-source" => scope_values.iter().all(|present| !present),
        "fresh-baseline-proposal" => {
            scope_values.iter().all(|present| *present)
                && record.source_candidate_id.as_deref() == Some(record.candidate_id.as_str())
                && record.source_candidate_state_sha256.as_deref()
                    == Some(record.candidate_state_sha256.as_str())
                && record.source_artifact_id.as_deref() == Some(record.artifact_id.as_str())
                && record.source_artifact_sha256.as_deref() == Some(record.artifact_sha256.as_str())
                && record.proposal_candidate_id.as_deref() != Some(record.candidate_id.as_str())
                && record.proposal_artifact_id.as_deref() != Some(record.artifact_id.as_str())
        }
        _ => false,
    };
    if record.schema_version != PRODUCTION_WEAPON_FORM_QUALITY_V2_SCHEMA_VERSION
        || ids.iter().any(|value| !is_opaque_id(value))
        || hashes.iter().any(|value| !is_sha256(value))
        || !optional_values_valid
        || !evidence_scope_valid
        || expected_source != Some(record.source_stage.as_str())
        || expected_target != Some(record.target_stage.as_str())
        || record.current_source_head_stage != record.source_stage
        || record.current_source_head_candidate_id != record.candidate_id
        || record.current_source_head_candidate_state_sha256 != record.candidate_state_sha256
        || record.current_source_head_artifact_id != record.artifact_id
        || record.current_source_head_artifact_sha256 != record.artifact_sha256
        || record.reviewed_reference_view_kinds != expected_views
        || record.fixed_camera_view_kinds != expected_fixed
        || !views_ok
        || !aggregate_ok
        || !previous_valid
        || (record.form_stage == "blockout"
            && (record.previous_form_quality_id.is_some()
                || record.previous_form_quality_report_object_sha256.is_some()
                || record.previous_form_quality_canonical_sha256.is_some()))
        || (record.form_stage != "blockout"
            && (record.previous_form_quality_id.is_none()
                || record.previous_form_quality_report_object_sha256.is_none()
                || record.previous_form_quality_canonical_sha256.is_none()))
        || record.form_quality_policy != PRODUCTION_WEAPON_FORM_QUALITY_V2_POLICY
        || record.threshold_policy != PRODUCTION_WEAPON_FORM_QUALITY_V2_THRESHOLD_POLICY
        || !record.hard_gate_passed
        || !record.form_gate_passed
        || record.validator_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_VALIDATOR_STATUS
        || record.structural_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_STRUCTURAL_STATUS
        || record.visual_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_VISUAL_STATUS
        || record.human_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_HUMAN_STATUS
        || record.engine_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_ENGINE_STATUS
        || record.distribution_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_DISTRIBUTION_STATUS
        || record.quality_status != PRODUCTION_WEAPON_FORM_QUALITY_V2_QUALITY_STATUS
        || !record.runtime_write_performed
        || record.production_stage_advanced
        || record.candidate_confirmed
        || record.version_created
        || record.export_performed
        || record.created_at.is_empty()
        || record.created_at.len() > 128
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_RECORD_INVALID",
            "ProductionWeaponFormQuality@2 record is malformed",
        ));
    }
    let mut canonical = record.clone();
    canonical.receipt_object_sha256.clear();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(&serde_json::to_value(&canonical).map_err(|error| {
        form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_SERIALIZE",
            error.to_string(),
        )
    })?);
    if expected != record.canonical_sha256 {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CANONICAL_MISMATCH",
            "V2 form-quality canonical hash differs",
        ));
    }
    Ok(())
}

fn same_production_weapon_form_quality_v2(
    left: &ProductionWeaponFormQualityV2Record,
    right: &ProductionWeaponFormQualityV2Record,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left.receipt_object_sha256.clear();
    right.receipt_object_sha256.clear();
    left == right
}

fn ensure_production_weapon_form_quality_v2_view_thresholds(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    view: &ProductionWeaponFormArtEvidenceViewRecord,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let target = form_quality_json_object(
        transaction,
        cas,
        &view.target_object_sha256,
        &format!("{} V2 silhouette target", view.view_kind),
        Some("silhouette-target-v1"),
        require_reachable,
    )?;
    ensure_form_quality_canonical_value(
        &target,
        "SilhouetteTarget@1",
        &format!("{} silhouette target", view.view_kind),
    )?;
    if target.get("reference_id").and_then(Value::as_str) != Some(view.reference_id.as_str())
        || target.get("reference_sha256").and_then(Value::as_str)
            != Some(view.reference_sha256.as_str())
        || target.get("canonical_sha256").and_then(Value::as_str)
            != Some(view.target_canonical_sha256.as_str())
        || target.get("source").and_then(Value::as_str) != Some("user_refined")
        || target.get("annotation_status").and_then(Value::as_str) != Some("user_confirmed")
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_TARGET_NOT_CONFIRMED",
            format!(
                "{} target is not user-confirmed refined evidence",
                view.view_kind
            ),
        ));
    }
    let structure = target.get("visual_structure").ok_or_else(|| {
        form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_VISUAL_STRUCTURE_MISSING",
            format!("{} target has no ReferenceVisualStructure", view.view_kind),
        )
    })?;
    ensure_form_quality_canonical_value(
        structure,
        "ReferenceVisualStructure@1",
        &format!("{} visual structure", view.view_kind),
    )?;
    if structure.get("review_status").and_then(Value::as_str) != Some("user_confirmed")
        || structure.get("canonical_sha256").and_then(Value::as_str)
            != Some(view.visual_structure_canonical_sha256.as_str())
        || view.visual_structure_review_status != "user_confirmed"
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_VISUAL_STRUCTURE_NOT_CONFIRMED",
            format!("{} visual structure is not user-confirmed", view.view_kind),
        ));
    }
    if view.part_id_status != "observed"
        || view.part_id_expected_count == 0
        || view.part_id_observed_count != view.part_id_expected_count
        || view.part_id_coverage_milli != 1000
        || view.part_id_missing_count != 0
        || view.part_id_unexpected_count != 0
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_PART_ID_THRESHOLD_FAILED",
            format!(
                "{} Part-ID coverage is below the V2 threshold",
                view.view_kind
            ),
        ));
    }

    let regions = structure
        .get("regions")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_VISUAL_STRUCTURE_INVALID",
                format!("{} regions are missing", view.view_kind),
            )
        })?;
    let subtract_regions = regions
        .iter()
        .filter(|region| region.get("mask_operation").and_then(Value::as_str) == Some("subtract"))
        .collect::<Vec<_>>();
    if subtract_regions.is_empty() {
        if view.negative_space_status != "not-applicable" || !view.negative_space_rows.is_empty() {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_NEGATIVE_SPACE_THRESHOLD_FAILED",
                format!(
                    "{} negative-space must be confirmed not-applicable",
                    view.view_kind
                ),
            ));
        }
    } else {
        if view.negative_space_status != "observed"
            || view.negative_space_rows.len() != subtract_regions.len()
        {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_NEGATIVE_SPACE_THRESHOLD_FAILED",
                format!("{} negative-space rows are incomplete", view.view_kind),
            ));
        }
        let mut seen = HashSet::new();
        for (region, row) in subtract_regions.iter().zip(view.negative_space_rows.iter()) {
            let structure_id = region
                .get("structure_id")
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    form_quality_v2_error(
                        "PRODUCTION_WEAPON_FORM_QUALITY_V2_NEGATIVE_SPACE_INVALID",
                        format!("{} negative-space region has no id", view.view_kind),
                    )
                })?;
            if region.get("visual_role").and_then(Value::as_str) != Some("open-frame")
                || region.get("visibility").and_then(Value::as_str) != Some("observed")
                || region.get("boundary_relationship").and_then(Value::as_str) != Some("enclosed")
                || !seen.insert(row.structure_id.as_str())
                || row.structure_id != structure_id
                || row.expected_region_canonical_sha256 != canonical_json_hash(region)
                || row.status != "observed"
                || row.iou_milli < PRODUCTION_WEAPON_FORM_ART_EVIDENCE_VOID_IOU_MIN_MILLI
                || row.boundary_f1_milli
                    < PRODUCTION_WEAPON_FORM_ART_EVIDENCE_VOID_BOUNDARY_F1_MIN_MILLI
                || row.area_ratio_milli
                    < PRODUCTION_WEAPON_FORM_ART_EVIDENCE_VOID_AREA_RATIO_MIN_MILLI
                || row.area_ratio_milli
                    > PRODUCTION_WEAPON_FORM_ART_EVIDENCE_VOID_AREA_RATIO_MAX_MILLI
                || row.centroid_error_milli
                    > PRODUCTION_WEAPON_FORM_ART_EVIDENCE_VOID_CENTROID_MAX_MILLI
                || row.sealed
                || row.missing
            {
                return Err(form_quality_v2_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_V2_NEGATIVE_SPACE_THRESHOLD_FAILED",
                    format!("{} negative-space threshold failed", view.view_kind),
                ));
            }
        }
    }

    let line_flows = structure
        .get("line_flows")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_VISUAL_STRUCTURE_INVALID",
                format!("{} line flows are missing", view.view_kind),
            )
        })?;
    if line_flows.is_empty() {
        if view.line_flow_status != "not-applicable" || !view.line_flow_rows.is_empty() {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_LINE_FLOW_THRESHOLD_FAILED",
                format!(
                    "{} line flow must be confirmed not-applicable",
                    view.view_kind
                ),
            ));
        }
    } else {
        if view.line_flow_status != "observed" || view.line_flow_rows.len() != line_flows.len() {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_LINE_FLOW_THRESHOLD_FAILED",
                format!("{} line-flow rows are incomplete", view.view_kind),
            ));
        }
        let mut seen = HashSet::new();
        for (flow, row) in line_flows.iter().zip(view.line_flow_rows.iter()) {
            let line_flow_id = flow
                .get("line_flow_id")
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    form_quality_v2_error(
                        "PRODUCTION_WEAPON_FORM_QUALITY_V2_LINE_FLOW_INVALID",
                        format!("{} line flow has no id", view.view_kind),
                    )
                })?;
            if !seen.insert(row.line_flow_id.as_str())
                || row.line_flow_id != line_flow_id
                || row.expected_line_canonical_sha256 != canonical_json_hash(flow)
                || row.status != "observed"
                || row.coverage_milli < PRODUCTION_WEAPON_FORM_ART_EVIDENCE_LINE_COVERAGE_MIN_MILLI
                || row.continuity_milli
                    < PRODUCTION_WEAPON_FORM_ART_EVIDENCE_LINE_CONTINUITY_MIN_MILLI
                || row.symmetric_chamfer_milli
                    > PRODUCTION_WEAPON_FORM_ART_EVIDENCE_LINE_CHAMFER_MAX_MILLI
                || row.max_deviation_milli
                    > PRODUCTION_WEAPON_FORM_ART_EVIDENCE_LINE_DEVIATION_MAX_MILLI
                || row.direction_order_milli
                    < PRODUCTION_WEAPON_FORM_ART_EVIDENCE_LINE_DIRECTION_MIN_MILLI
                || row.duplicate_crossing_count
                    > PRODUCTION_WEAPON_FORM_ART_EVIDENCE_LINE_DUPLICATE_CROSSING_MAX
            {
                return Err(form_quality_v2_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_V2_LINE_FLOW_THRESHOLD_FAILED",
                    format!("{} line-flow threshold failed", view.view_kind),
                ));
            }
        }
    }
    Ok(())
}

fn production_weapon_form_quality_v2_legacy_metrics_no_regression_passes(
    no_regression: &ProductionWeaponFormQualityNoRegression,
) -> bool {
    matches!(no_regression.status.as_str(), "PASS" | "NOT_PROVEN")
        && no_regression.metrics_not_regressed
}

fn production_stage_v3_head_descends_from_transition(
    transaction: &rusqlite::Transaction<'_>,
    head: &ProductionStageHeadV3Record,
    ancestor_transition_id: &str,
    ancestor_transition_sha256: &str,
) -> Result<bool, StoreError> {
    let mut cursor_id = head.head_transition_id.clone();
    let mut cursor_sha256 = head.head_transition_sha256.clone();
    for _ in 0..PRODUCTION_STAGE_V3_STAGES.len() {
        if cursor_id == ancestor_transition_id && cursor_sha256 == ancestor_transition_sha256 {
            return Ok(true);
        }
        let Some(columns) = read_production_stage_transition_v3_columns(transaction, &cursor_id)?
        else {
            return Ok(false);
        };
        if columns.record.canonical_sha256 != cursor_sha256 {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_HEAD_LINEAGE_MISMATCH",
                "durable V3 head lineage hash differs",
            ));
        }
        let (Some(parent_id), Some(parent_sha256)) = (
            columns.record.parent_transition_id,
            columns.record.parent_transition_sha256,
        ) else {
            return Ok(false);
        };
        cursor_id = parent_id;
        cursor_sha256 = parent_sha256;
    }
    Ok(false)
}

fn ensure_production_weapon_form_quality_v2_bindings(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    quality: &ProductionWeaponFormQualityV2Record,
    require_reachable: bool,
) -> Result<Vec<String>, StoreError> {
    let legacy_value = form_quality_json_object(
        transaction,
        cas,
        &quality.legacy_form_quality_object_sha256,
        "legacy form-quality report",
        Some(PRODUCTION_WEAPON_FORM_QUALITY_RECEIPT_KIND),
        require_reachable,
    )?;
    let legacy_id = legacy_value
        .get("form_quality_id")
        .and_then(Value::as_str)
        .filter(|value| is_opaque_id(value))
        .ok_or_else(|| {
            form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_LEGACY_INVALID",
                "legacy FormQuality@1 report has no valid id",
            )
        })?;
    let legacy = read_production_weapon_form_quality_in_transaction(transaction, cas, legacy_id)?
        .ok_or_else(|| {
        form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_LEGACY_MISSING",
            "legacy FormQuality@1 row is missing",
        )
    })?;
    if !legacy.form_gate.all_view_thresholds || !legacy.form_gate.all_view_no_regression {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_LEGACY_FORM_GATE_FAILED",
            "legacy FormQuality@1 aggregate gate did not pass",
        ));
    }
    let cross_view = form_quality_json_object(
        transaction,
        cas,
        &legacy.cross_view_evidence_object_sha256,
        "legacy CrossViewEvidenceBundle",
        Some("cross-view-evidence-bundle"),
        require_reachable,
    )?;
    ensure_form_quality_cross_view_structure(&cross_view)?;
    if cross_view.get("hard_gate_passed").and_then(Value::as_bool) != Some(true)
        || cross_view.get("non_regressing").and_then(Value::as_bool) != Some(true)
        || cross_view.get("aggregate_status").and_then(Value::as_str)
            != Some("PARTIAL_VISIBLE_VIEW_PASS")
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CROSS_VIEW_GATE_FAILED",
            "legacy CrossViewEvidenceBundle aggregate gate did not pass",
        ));
    }
    let cross_view_evaluations = cross_view
        .get("view_evaluations")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_CROSS_VIEW_INVALID",
                "legacy CrossViewEvidenceBundle has no view evaluations",
            )
        })?;
    if cross_view_evaluations.len() != PRODUCTION_WEAPON_FORM_QUALITY_V2_VIEW_KINDS.len() {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CROSS_VIEW_GATE_FAILED",
            "legacy CrossViewEvidenceBundle does not contain exactly six V2 views",
        ));
    }
    let mut cross_view_kinds = HashSet::new();
    for evaluation in cross_view_evaluations {
        let kind = evaluation
            .get("kind")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                form_quality_v2_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_V2_CROSS_VIEW_INVALID",
                    "legacy CrossView view kind is missing",
                )
            })?;
        if !PRODUCTION_WEAPON_FORM_QUALITY_V2_VIEW_KINDS.contains(&kind)
            || !cross_view_kinds.insert(kind.to_owned())
            || evaluation.get("proposal_status").and_then(Value::as_str)
                != Some("PARTIAL_VISIBLE_VIEW_PASS")
            || evaluation.get("non_regressing").and_then(Value::as_bool) != Some(true)
        {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_CROSS_VIEW_GATE_FAILED",
                format!("legacy CrossView view {kind} did not pass"),
            ));
        }
    }
    if cross_view_kinds.len() != PRODUCTION_WEAPON_FORM_QUALITY_V2_VIEW_KINDS.len() {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CROSS_VIEW_GATE_FAILED",
            "legacy CrossViewEvidenceBundle view set is incomplete",
        ));
    }
    if legacy.receipt_object_sha256 != quality.legacy_form_quality_object_sha256
        || legacy.canonical_sha256 != quality.legacy_form_quality_canonical_sha256
        || legacy.form_quality_id != legacy_id
        || legacy.session_id != quality.session_id
        || legacy.project_id != quality.project_id
        || legacy.form_stage != quality.form_stage
        || legacy.source_stage != quality.source_stage
        || legacy.target_stage != quality.target_stage
        || legacy.candidate_id != quality.candidate_id
        || legacy.candidate_state_sha256 != quality.candidate_state_sha256
        || legacy.artifact_id != quality.artifact_id
        || legacy.artifact_sha256 != quality.artifact_sha256
        || legacy.reference_id != quality.reference_id
        || legacy.reference_sha256 != quality.reference_sha256
        || legacy.reference_canvas_object_sha256 != quality.reference_canvas_object_sha256
        || legacy.reference_canvas_canonical_sha256 != quality.reference_canvas_canonical_sha256
        || legacy.design_spec_object_sha256 != quality.design_spec_object_sha256
        || legacy.design_spec_canonical_sha256 != quality.design_spec_canonical_sha256
        || legacy.camera_lock_id != quality.camera_lock_id
        || legacy.camera_lock_canonical_sha256 != quality.camera_lock_canonical_sha256
        || legacy.camera_rig_object_sha256 != quality.camera_rig_object_sha256
        || legacy.camera_rig_canonical_sha256 != quality.camera_rig_canonical_sha256
        || legacy.camera_lock_receipt_object_sha256 != quality.camera_lock_receipt_object_sha256
        || legacy.camera_lock_source_transition_id != quality.camera_lock_source_transition_id
        || legacy.camera_lock_source_transition_sha256
            != quality.camera_lock_source_transition_sha256
        || legacy.camera_lock_source_head_canonical_sha256
            != quality.camera_lock_source_head_canonical_sha256
        || legacy.reviewed_reference_view_kinds != quality.reviewed_reference_view_kinds
        || legacy.fixed_camera_view_kinds != quality.fixed_camera_view_kinds
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_LEGACY_BINDING_MISMATCH",
            "legacy FormQuality@1 report is not bound to the V2 candidate/edge",
        ));
    }

    let art_value = form_quality_json_object(
        transaction,
        cas,
        &quality.form_art_evidence_object_sha256,
        "form-art evidence parent",
        Some(PRODUCTION_WEAPON_FORM_ART_EVIDENCE_PARENT_RECEIPT_KIND),
        require_reachable,
    )?;
    let art_id = art_value
        .get("art_evidence_id")
        .and_then(Value::as_str)
        .filter(|value| is_opaque_id(value))
        .ok_or_else(|| {
            form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_ART_INVALID",
                "FormArt@1 parent has no valid id",
            )
        })?;
    let art = read_production_weapon_form_art_evidence_in_transaction(transaction, cas, art_id)?
        .ok_or_else(|| {
            form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_ART_MISSING",
                "FormArt@1 parent row is missing",
            )
        })?;
    if art.receipt_object_sha256 != quality.form_art_evidence_object_sha256
        || art.canonical_sha256 != quality.form_art_evidence_canonical_sha256
        || art.session_id != quality.session_id
        || art.project_id != quality.project_id
        || art.candidate_id != quality.candidate_id
        || art.candidate_state_sha256 != quality.candidate_state_sha256
        || art.artifact_id != quality.artifact_id
        || art.artifact_sha256 != quality.artifact_sha256
        || art.reference_canvas_object_sha256 != quality.reference_canvas_object_sha256
        || art.reference_canvas_canonical_sha256 != quality.reference_canvas_canonical_sha256
        || art.design_spec_object_sha256 != quality.design_spec_object_sha256
        || art.design_spec_canonical_sha256 != quality.design_spec_canonical_sha256
        || art.camera_lock_id != quality.camera_lock_id
        || art.camera_lock_canonical_sha256 != quality.camera_lock_canonical_sha256
        || art.camera_rig_object_sha256 != quality.camera_rig_object_sha256
        || art.camera_rig_canonical_sha256 != quality.camera_rig_canonical_sha256
        || art.camera_lock_receipt_object_sha256 != quality.camera_lock_receipt_object_sha256
        || art.camera_lock_source_transition_id != quality.camera_lock_source_transition_id
        || art.camera_lock_source_transition_sha256 != quality.camera_lock_source_transition_sha256
        || art.camera_lock_source_head_canonical_sha256
            != quality.camera_lock_source_head_canonical_sha256
        || art.quality_status != "NOT_PROVEN"
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_ART_BINDING_MISMATCH",
            "FormArt@1 parent is not bound to the V2 candidate/edge",
        ));
    }

    let proposal_value = if quality.evidence_source_kind == "fresh-baseline-proposal" {
        let proposal_object_sha256 = quality
            .proposal_form_art_evidence_object_sha256
            .as_deref()
            .ok_or_else(|| {
                form_quality_v2_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_V2_PROPOSAL_EVIDENCE_MISSING",
                    "fresh proposal evidence object is missing",
                )
            })?;
        let proposal = form_quality_json_object(
            transaction,
            cas,
            proposal_object_sha256,
            "proposal FormArt evidence",
            Some("production-weapon-form-art-proposal-evidence"),
            require_reachable,
        )?;
        let proposal_canonical = proposal
            .get("canonical_sha256")
            .and_then(Value::as_str)
            .filter(|value| is_sha256(value))
            .ok_or_else(|| {
                form_quality_v2_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_V2_PROPOSAL_EVIDENCE_INVALID",
                    "fresh proposal evidence canonical is missing",
                )
            })?;
        let mut proposal_preimage = proposal.clone();
        proposal_preimage["canonical_sha256"] = Value::String(String::new());
        let proposal_views = proposal
            .get("views")
            .and_then(Value::as_array)
            .filter(|views| views.len() == PRODUCTION_WEAPON_FORM_QUALITY_V2_VIEW_KINDS.len())
            .ok_or_else(|| {
                form_quality_v2_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_V2_PROPOSAL_EVIDENCE_INVALID",
                    "fresh proposal evidence does not contain six views",
                )
            })?;
        let part_id_hash = canonical_json_hash(&serde_json::json!(proposal_views
            .iter()
            .map(|view| serde_json::json!({
                "view_kind": view.get("view_kind"),
                "part_id_pass_object_sha256": view.get("part_id_pass_object_sha256"),
                "part_id_status": view.get("part_id_status"),
            }))
            .collect::<Vec<_>>()));
        let negative_space_hash = canonical_json_hash(&serde_json::json!(proposal_views
            .iter()
            .map(|view| serde_json::json!({
                "view_kind": view.get("view_kind"),
                "negative_space_status": view.get("negative_space_status"),
                "negative_space_observations": view.get("negative_space_observations"),
            }))
            .collect::<Vec<_>>()));
        let line_flow_hash = canonical_json_hash(&serde_json::json!(proposal_views
            .iter()
            .map(|view| serde_json::json!({
                "view_kind": view.get("view_kind"),
                "line_flow_status": view.get("line_flow_status"),
                "line_flow_observations": view.get("line_flow_observations"),
            }))
            .collect::<Vec<_>>()));
        if proposal_canonical
            != quality
                .proposal_form_art_evidence_canonical_sha256
                .as_deref()
                .unwrap_or_default()
            || canonical_json_hash(&proposal_preimage) != proposal_canonical
            || proposal.get("project_id").and_then(Value::as_str)
                != Some(quality.project_id.as_str())
            || proposal.get("session_id").and_then(Value::as_str)
                != Some(quality.session_id.as_str())
            || proposal.get("source_candidate_id").and_then(Value::as_str)
                != quality.source_candidate_id.as_deref()
            || proposal
                .get("source_candidate_state_sha256")
                .and_then(Value::as_str)
                != quality.source_candidate_state_sha256.as_deref()
            || proposal
                .get("source_artifact_sha256")
                .and_then(Value::as_str)
                != quality.source_artifact_sha256.as_deref()
            || proposal
                .get("source_form_art_evidence_id")
                .and_then(Value::as_str)
                != quality.proposal_form_art_evidence_id.as_deref()
            || proposal
                .get("source_form_art_evidence_object_sha256")
                .and_then(Value::as_str)
                != Some(quality.form_art_evidence_object_sha256.as_str())
            || proposal
                .get("source_form_art_evidence_canonical_sha256")
                .and_then(Value::as_str)
                != Some(quality.form_art_evidence_canonical_sha256.as_str())
            || proposal
                .get("source_fresh_baseline_id")
                .and_then(Value::as_str)
                != quality.source_fresh_baseline_id.as_deref()
            || proposal
                .get("source_fresh_baseline_canonical_sha256")
                .and_then(Value::as_str)
                != quality.source_fresh_baseline_canonical_sha256.as_deref()
            || proposal
                .get("source_fresh_baseline_receipt_object_sha256")
                .and_then(Value::as_str)
                != quality
                    .source_fresh_baseline_receipt_object_sha256
                    .as_deref()
            || proposal
                .get("source_registration_lineage_id")
                .and_then(Value::as_str)
                != quality.source_registration_lineage_id.as_deref()
            || proposal
                .get("source_registration_lineage_canonical_sha256")
                .and_then(Value::as_str)
                != quality
                    .source_registration_lineage_canonical_sha256
                    .as_deref()
            || proposal
                .get("source_registered_rig_v2_id")
                .and_then(Value::as_str)
                != quality.source_registered_rig_v2_id.as_deref()
            || proposal
                .get("proposal_candidate_id")
                .and_then(Value::as_str)
                != quality.proposal_candidate_id.as_deref()
            || proposal
                .get("proposal_candidate_state_sha256")
                .and_then(Value::as_str)
                != quality.proposal_candidate_state_sha256.as_deref()
            || proposal
                .get("proposal_artifact_sha256")
                .and_then(Value::as_str)
                != quality.proposal_artifact_sha256.as_deref()
            || proposal
                .get("proposal_artifact_readback_sha256")
                .and_then(Value::as_str)
                != quality.proposal_artifact_readback_sha256.as_deref()
            || proposal
                .get("worker_build_cohort_sha256")
                .and_then(Value::as_str)
                != quality.proposal_worker_build_cohort_sha256.as_deref()
            || proposal
                .get("cross_view_evidence_bundle_sha256")
                .and_then(Value::as_str)
                != quality.cross_view_evidence_bundle_sha256.as_deref()
            || quality.proposal_part_id_evidence_sha256.as_deref() != Some(part_id_hash.as_str())
            || quality.proposal_negative_space_evidence_sha256.as_deref()
                != Some(negative_space_hash.as_str())
            || quality.proposal_line_flow_evidence_sha256.as_deref()
                != Some(line_flow_hash.as_str())
            || proposal.get("part_id_all_views_observed") != Some(&Value::Bool(true))
            || proposal.get("negative_space_all_views_resolved") != Some(&Value::Bool(true))
            || proposal.get("line_flow_all_views_resolved") != Some(&Value::Bool(true))
            || proposal.get("strict_owner_void_all_views_passed") != Some(&Value::Bool(true))
            || proposal.get("proposal_form_art_evidence_ready") != Some(&Value::Bool(true))
            || proposal.get("status").and_then(Value::as_str)
                != Some("READY_PROPOSAL_FORM_ART_EVIDENCE")
        {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_PROPOSAL_EVIDENCE_BINDING_MISMATCH",
                "fresh proposal evidence differs from the V2 dual-scope record",
            ));
        }
        Some(proposal)
    } else {
        None
    };

    // FormArt@1 is an evidence projection, not an authority on its own
    // status fields. Re-read every bound SilhouetteTarget and its confirmed
    // ReferenceVisualStructure here so a direct Store caller cannot promote
    // forged Part-ID/negative-space/line-flow rows to a V2 PASS.
    for view in &art.views {
        ensure_production_weapon_form_quality_v2_view_thresholds(
            transaction,
            cas,
            view,
            require_reachable,
        )?;
    }

    let transition_columns = read_production_stage_transition_v3_columns(
        transaction,
        &quality.current_source_head_transition_id,
    )?
    .ok_or_else(|| {
        form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_SOURCE_TRANSITION_MISSING",
            "current source-head transition is missing",
        )
    })?;
    let transition = transition_columns.record;
    let Some(head) = read_production_stage_head_v3_record(
        transaction,
        &quality.session_id,
        &quality.project_id,
        &transition.root_candidate_id,
    )?
    else {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_SOURCE_HEAD_MISSING",
            "current source-stage head is missing",
        ));
    };
    let source_head = production_stage_head_v3_from_transition(&transition)?;
    let head_descends_from_source = production_stage_v3_head_descends_from_transition(
        transaction,
        &head,
        &transition.transition_id,
        &transition.canonical_sha256,
    )?;
    if transition.transition_id != quality.current_source_head_transition_id
        || transition.canonical_sha256 != quality.current_source_head_transition_sha256
        || transition.to_stage != quality.source_stage
        || transition.head_candidate_id != quality.current_source_head_candidate_id
        || transition.head_candidate_state_sha256
            != quality.current_source_head_candidate_state_sha256
        || transition.output_artifact_id != quality.current_source_head_artifact_id
        || transition.head_artifact_sha256 != quality.current_source_head_artifact_sha256
        || transition.session_id != quality.session_id
        || transition.project_id != quality.project_id
        || transition.reference_id != quality.reference_id
        || transition.reference_sha256 != quality.reference_sha256
        || transition.camera_hash != quality.camera_hash
        || source_head.head_transition_id != quality.current_source_head_transition_id
        || source_head.head_transition_sha256 != quality.current_source_head_transition_sha256
        || source_head.canonical_sha256 != quality.current_source_head_canonical_sha256
        || source_head.head_stage != quality.current_source_head_stage
        || source_head.head_candidate_id != quality.current_source_head_candidate_id
        || source_head.head_candidate_state_sha256
            != quality.current_source_head_candidate_state_sha256
        || source_head.output_artifact_id != quality.current_source_head_artifact_id
        || source_head.head_artifact_sha256 != quality.current_source_head_artifact_sha256
        || head.session_id != quality.session_id
        || head.project_id != quality.project_id
        || head.camera_hash != quality.camera_hash
        || !head_descends_from_source
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_SOURCE_HEAD_BINDING_MISMATCH",
            "current source head or transition differs from V2 record",
        ));
    }
    if source_head.camera_lock_id.as_deref() != Some(quality.camera_lock_id.as_str())
        || source_head.camera_lock_canonical_sha256.as_deref()
            != Some(quality.camera_lock_canonical_sha256.as_str())
        || source_head.camera_rig_object_sha256.as_deref()
            != Some(quality.camera_rig_object_sha256.as_str())
        || source_head.camera_rig_canonical_sha256.as_deref()
            != Some(quality.camera_rig_canonical_sha256.as_str())
        || source_head.camera_lock_receipt_object_sha256.as_deref()
            != Some(quality.camera_lock_receipt_object_sha256.as_str())
        || source_head.camera_lock_source_transition_id.as_deref()
            != Some(quality.camera_lock_source_transition_id.as_str())
        || source_head.camera_lock_source_transition_sha256.as_deref()
            != Some(quality.camera_lock_source_transition_sha256.as_str())
        || source_head
            .camera_lock_source_head_canonical_sha256
            .as_deref()
            != Some(quality.camera_lock_source_head_canonical_sha256.as_str())
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CAMERA_BINDING_MISMATCH",
            "source head camera lock differs from V2 record",
        ));
    }
    let Some(lock) = read_production_camera_lock_columns(transaction, &quality.camera_lock_id)?
    else {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CAMERA_LOCK_MISSING",
            "camera lock is missing",
        ));
    };
    if lock.session_id != quality.session_id
        || lock.project_id != quality.project_id
        || lock.source_transition_id != quality.camera_lock_source_transition_id
        || lock.source_transition_sha256 != quality.camera_lock_source_transition_sha256
        || lock.source_head_canonical_sha256 != quality.camera_lock_source_head_canonical_sha256
        || lock.canonical_sha256 != quality.camera_lock_canonical_sha256
        || lock.camera_lock_id != quality.camera_lock_id
        || lock.candidate_id != quality.candidate_id
        || lock.candidate_state_sha256 != quality.candidate_state_sha256
        || lock.artifact_id != quality.artifact_id
        || lock.artifact_sha256 != quality.artifact_sha256
        || lock.reference_id != quality.reference_id
        || lock.reference_sha256 != quality.reference_sha256
        || lock.reference_canvas_object_sha256 != quality.reference_canvas_object_sha256
        || lock.reference_canvas_canonical_sha256 != quality.reference_canvas_canonical_sha256
        || lock.design_spec_object_sha256 != quality.design_spec_object_sha256
        || lock.design_spec_canonical_sha256 != quality.design_spec_canonical_sha256
        || lock.camera_rig_object_sha256 != quality.camera_rig_object_sha256
        || lock.camera_rig_canonical_sha256 != quality.camera_rig_canonical_sha256
        || lock.receipt_object_sha256 != quality.camera_lock_receipt_object_sha256
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CAMERA_LOCK_BINDING_MISMATCH",
            "camera lock is not bound to V2 candidate/source head",
        ));
    }

    let candidate: Option<(String, Option<String>, Option<String>, String)> = transaction
        .query_row(
            "SELECT project_id, prepared_object_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
            params![quality.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((candidate_project, prepared_id, prepared_sha, candidate_state)) = candidate else {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CANDIDATE_MISSING",
            "V2 candidate is missing",
        ));
    };
    if candidate_project != quality.project_id
        || prepared_id.as_deref() != Some(quality.artifact_id.as_str())
        || prepared_sha.as_deref() != Some(quality.artifact_sha256.as_str())
        || candidate_state != quality.candidate_state_sha256
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CANDIDATE_BINDING_MISMATCH",
            "V2 candidate state or artifact differs",
        ));
    }
    if quality.evidence_source_kind == "fresh-baseline-proposal" {
        let proposal_candidate_id = quality.proposal_candidate_id.as_deref().unwrap_or_default();
        let proposal_candidate: Option<(String, Option<String>, Option<String>, String)> =
            transaction
                .query_row(
                    "SELECT project_id, prepared_object_id, prepared_object_sha256, canonical_sha256 FROM candidates WHERE candidate_id = ?1",
                    params![proposal_candidate_id],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
                )
                .optional()?;
        let Some((proposal_project, proposal_prepared_id, proposal_prepared_sha, proposal_state)) =
            proposal_candidate
        else {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_PROPOSAL_CANDIDATE_MISSING",
                "evaluated proposal candidate is missing",
            ));
        };
        if proposal_project != quality.project_id
            || proposal_prepared_id.as_deref() != quality.proposal_artifact_id.as_deref()
            || proposal_prepared_sha.as_deref() != quality.proposal_artifact_sha256.as_deref()
            || Some(proposal_state.as_str()) != quality.proposal_candidate_state_sha256.as_deref()
        {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_PROPOSAL_CANDIDATE_BINDING_MISMATCH",
                "evaluated proposal candidate state or artifact differs",
            ));
        }
        let proposal_cross_view = form_quality_json_object(
            transaction,
            cas,
            quality
                .cross_view_evidence_bundle_sha256
                .as_deref()
                .unwrap_or_default(),
            "proposal CrossViewEvidenceBundle",
            Some("cross-view-evidence-bundle"),
            require_reachable,
        )?;
        ensure_form_quality_cross_view_structure(&proposal_cross_view)?;
        if proposal_cross_view
            .get("candidate_id")
            .and_then(Value::as_str)
            != quality.proposal_candidate_id.as_deref()
            || proposal_cross_view
                .get("candidate_state_sha256")
                .and_then(Value::as_str)
                != quality.proposal_candidate_state_sha256.as_deref()
            || proposal_cross_view
                .get("artifact_sha256")
                .and_then(Value::as_str)
                != quality.proposal_artifact_sha256.as_deref()
            || proposal_cross_view
                .get("hard_gate_passed")
                .and_then(Value::as_bool)
                != Some(true)
            || proposal_cross_view
                .get("non_regressing")
                .and_then(Value::as_bool)
                != Some(true)
            || proposal_cross_view
                .get("aggregate_status")
                .and_then(Value::as_str)
                != Some("PARTIAL_VISIBLE_VIEW_PASS")
        {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_PROPOSAL_CROSS_VIEW_BINDING_MISMATCH",
                "proposal CrossViewEvidenceBundle is not a passing evaluated-candidate bundle",
            ));
        }
    }

    let mut roots = vec![
        quality.legacy_form_quality_object_sha256.clone(),
        quality.form_art_evidence_object_sha256.clone(),
        quality.artifact_sha256.clone(),
        quality.reference_sha256.clone(),
        quality.reference_canvas_object_sha256.clone(),
        quality.design_spec_object_sha256.clone(),
        quality.camera_rig_object_sha256.clone(),
        quality.camera_lock_receipt_object_sha256.clone(),
        transition_columns.receipt_object_sha256,
        quality.receipt_object_sha256.clone(),
    ];
    if let Some(proposal) = proposal_value.as_ref() {
        if let Some(hash) = quality.proposal_form_art_evidence_object_sha256.as_ref() {
            roots.push(hash.clone());
        }
        if let Some(hash) = quality.cross_view_evidence_bundle_sha256.as_ref() {
            roots.push(hash.clone());
        }
        roots.extend(
            proposal
                .get("views")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .flat_map(|view| {
                    [
                        "target_object_sha256",
                        "silhouette_pass_object_sha256",
                        "part_id_pass_object_sha256",
                        "depth_pass_object_sha256",
                        "normal_pass_object_sha256",
                    ]
                    .into_iter()
                    .filter_map(|field| view.get(field).and_then(Value::as_str).map(str::to_owned))
                }),
        );
    }
    roots.extend(art.views.iter().flat_map(|view| {
        [
            view.form_evidence_view_receipt_object_sha256.clone(),
            view.target_object_sha256.clone(),
            view.silhouette_pass_object_sha256.clone(),
            view.part_id_pass_object_sha256.clone(),
            view.depth_pass_object_sha256.clone(),
            view.normal_pass_object_sha256.clone(),
        ]
    }));
    roots.extend(
        transaction
            .prepare("SELECT object_sha256 FROM production_weapon_form_quality_cas_refs WHERE form_quality_id = ?1")?
            .query_map(params![legacy.form_quality_id], |row| row.get::<_, String>(0))?
            .collect::<Result<Vec<_>, _>>()?,
    );
    if let Some(previous_id) = quality.previous_form_quality_id.as_deref() {
        if previous_id == quality.form_quality_id {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_PREVIOUS_SELF_REFERENCE",
                "previous V2 quality cannot reference itself",
            ));
        }
        let Some(previous) =
            read_production_weapon_form_quality_v2_in_transaction(transaction, cas, previous_id)?
        else {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_PREVIOUS_MISSING",
                "previous V2 quality is missing",
            ));
        };
        if previous.session_id != quality.session_id
            || previous.project_id != quality.project_id
            || previous.candidate_id != quality.candidate_id
            || previous.candidate_state_sha256 != quality.candidate_state_sha256
            || previous.artifact_id != quality.artifact_id
            || previous.artifact_sha256 != quality.artifact_sha256
            || previous.target_stage != quality.source_stage
            || quality
                .previous_form_quality_report_object_sha256
                .as_deref()
                != Some(previous.receipt_object_sha256.as_str())
            || quality.previous_form_quality_canonical_sha256.as_deref()
                != Some(previous.canonical_sha256.as_str())
        {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_PREVIOUS_BINDING_MISMATCH",
                "previous V2 quality is not the exact prior edge",
            ));
        }
        roots.push(previous.receipt_object_sha256);
    }

    for (ordinal, (decision, expected_kind)) in quality
        .view_decisions
        .iter()
        .zip(PRODUCTION_WEAPON_FORM_QUALITY_V2_VIEW_KINDS.iter())
        .enumerate()
    {
        let Some(legacy_view) = legacy
            .form_view_evaluations
            .iter()
            .find(|view| view.view_kind == *expected_kind)
        else {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_LEGACY_VIEW_MISSING",
                format!("legacy view {expected_kind} is missing"),
            ));
        };
        let Some(art_view) = art.views.get(ordinal) else {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_ART_VIEW_MISSING",
                format!("FormArt view {expected_kind} is missing"),
            ));
        };
        let legacy_view_canonical =
            canonical_json_hash(&serde_json::to_value(legacy_view).map_err(|error| {
                form_quality_v2_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_V2_SERIALIZE",
                    error.to_string(),
                )
            })?);
        let proposal_view = proposal_value
            .as_ref()
            .and_then(|value| value.get("views"))
            .and_then(Value::as_array)
            .and_then(|views| views.get(ordinal));
        let matches_hash = |field: &str, source_value: &str, actual: &str| {
            actual
                == proposal_view
                    .and_then(|view| view.get(field))
                    .and_then(Value::as_str)
                    .unwrap_or(source_value)
        };
        if decision.view_kind != *expected_kind
            || decision.legacy_form_quality_view_id != legacy_view.view_id
            || decision.legacy_form_quality_view_canonical_sha256 != legacy_view_canonical
            || decision.form_art_view_id != art_view.view_id
            || decision.form_art_view_canonical_sha256 != art_view.canonical_sha256
            || decision.form_art_view_receipt_object_sha256 != art_view.receipt_object_sha256
            || !matches_hash(
                "target_object_sha256",
                &art_view.target_object_sha256,
                &decision.target_object_sha256,
            )
            || !matches_hash(
                "target_canonical_sha256",
                &art_view.target_canonical_sha256,
                &decision.target_canonical_sha256,
            )
            || !matches_hash(
                "silhouette_pass_object_sha256",
                &art_view.silhouette_pass_object_sha256,
                &decision.silhouette_pass_object_sha256,
            )
            || !matches_hash(
                "part_id_pass_object_sha256",
                &art_view.part_id_pass_object_sha256,
                &decision.part_id_pass_object_sha256,
            )
            || !matches_hash(
                "depth_pass_object_sha256",
                &art_view.depth_pass_object_sha256,
                &decision.depth_pass_object_sha256,
            )
            || !matches_hash(
                "normal_pass_object_sha256",
                &art_view.normal_pass_object_sha256,
                &decision.normal_pass_object_sha256,
            )
        {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_VIEW_BINDING_MISMATCH",
                format!("V2 view {expected_kind} is not bound to @1 sources"),
            ));
        }
        // FormQuality@1 is the immutable CrossView/metric parent. The V2
        // transaction separately validates every Part-ID, negative-space and
        // line-flow row against the user-confirmed FormArt@1 target below;
        // requiring the legacy diagnostic booleans here would make the chain
        // unsatisfiable because the @1 producer correctly leaves them
        // NOT_PROVEN.
        if !production_weapon_form_quality_v2_legacy_metrics_no_regression_passes(
            &legacy_view.no_regression,
        ) {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_LEGACY_THRESHOLD_FAILED",
                format!(
                    "legacy view {expected_kind} has not passed CrossView metric no-regression"
                ),
            ));
        }
    }
    roots.sort();
    roots.dedup();
    validate_reachable_hashes(&roots)?;
    Ok(roots)
}

fn ensure_production_weapon_form_quality_v2_children(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    quality: &ProductionWeaponFormQualityV2Record,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let mut statement = transaction.prepare(
        "SELECT view_ordinal, schema_version, view_kind, legacy_form_quality_view_id, legacy_form_quality_view_canonical_sha256, form_art_view_id, form_art_view_canonical_sha256, form_art_view_receipt_object_sha256, target_object_sha256, target_canonical_sha256, silhouette_pass_object_sha256, part_id_pass_object_sha256, depth_pass_object_sha256, normal_pass_object_sha256, cross_view_thresholds_passed, no_regression_passed, part_id_passed, negative_space_passed, line_flow_passed, view_passed, canonical_sha256, created_at, payload_json FROM production_weapon_form_quality_v2_views WHERE form_quality_id = ?1 ORDER BY view_ordinal ASC",
    )?;
    let rows = statement.query_map(params![quality.form_quality_id], |row| {
        let ordinal: i64 = row.get(0)?;
        let count = row.as_ref().column_count();
        Ok((
            ordinal,
            (1..count)
                .map(|index| row.get::<_, Option<String>>(index))
                .collect::<Result<Vec<_>, _>>()?,
        ))
    })?;
    let stored = rows.collect::<Result<Vec<_>, _>>()?;
    if stored.len() != PRODUCTION_WEAPON_FORM_QUALITY_V2_VIEW_KINDS.len() {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_CHILD_COUNT_MISMATCH",
            "V2 form-quality link must contain exactly six view rows",
        ));
    }
    for (ordinal, (stored_ordinal, columns)) in stored.into_iter().enumerate() {
        if stored_ordinal != ordinal as i64 {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_CHILD_ORDINAL_MISMATCH",
                "V2 form-quality view ordinals are not contiguous",
            ));
        }
        let expected = quality.view_decisions.get(ordinal).ok_or_else(|| {
            form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_CHILD_MISSING",
                "V2 form-quality decision is missing",
            )
        })?;
        let (payload, canonical) = production_weapon_form_quality_v2_view_payload(expected)?;
        let values = production_weapon_form_quality_v2_view_columns(expected, &payload, &canonical);
        let mut expected_columns = Vec::with_capacity(22);
        expected_columns.push(Some(
            PRODUCTION_WEAPON_FORM_QUALITY_V2_VIEW_SCHEMA_VERSION.to_owned(),
        ));
        expected_columns.extend(values.into_iter().take(18));
        expected_columns.push(Some(quality.created_at.clone()));
        expected_columns.push(Some(canonical));
        expected_columns.push(Some(payload));
        if columns != expected_columns {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_CHILD_BINDING_MISMATCH",
                format!(
                    "stored V2 view row {} differs from its decision",
                    expected.view_kind
                ),
            ));
        }
        let art_view_receipt = read_form_quality_object(
            transaction,
            cas,
            &expected.form_art_view_receipt_object_sha256,
            &format!("{} FormArt view receipt", expected.view_kind),
            Some(PRODUCTION_WEAPON_FORM_ART_EVIDENCE_VIEW_RECEIPT_KIND),
            require_reachable,
            MAX_PRODUCTION_WEAPON_FORM_ART_EVIDENCE_OBJECT_BYTES,
        )?;
        if art_view_receipt.mime != "application/json" {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_CHILD_RECEIPT_MIME_INVALID",
                format!("{} FormArt view receipt is not JSON", expected.view_kind),
            ));
        }
    }
    Ok(())
}

fn read_production_weapon_form_quality_v2_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    form_quality_id: &str,
) -> Result<Option<ProductionWeaponFormQualityV2Record>, StoreError> {
    let row: Option<(String, String)> = transaction
        .query_row(
            "SELECT payload_json, receipt_object_sha256 FROM production_weapon_form_quality_v2_links WHERE form_quality_id = ?1",
            params![form_quality_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((payload, receipt_sha)) = row else {
        return Ok(None);
    };
    let mut quality: ProductionWeaponFormQualityV2Record =
        serde_json::from_str(&payload).map_err(|error| {
            form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_PAYLOAD_INVALID",
                error.to_string(),
            )
        })?;
    quality.receipt_object_sha256 = receipt_sha.clone();
    validate_production_weapon_form_quality_v2(&quality)?;
    if production_weapon_form_quality_v2_payload_json(&quality)? != payload {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_PAYLOAD_BINDING_MISMATCH",
            "stored V2 parent payload differs from its SQLite binding",
        ));
    }
    let parent_columns: Vec<Option<String>> = transaction.query_row(
        "SELECT schema_version, form_quality_id, session_id, project_id, form_stage, source_stage, target_stage, current_source_head_transition_id, current_source_head_transition_sha256, current_source_head_canonical_sha256, current_source_head_stage, current_source_head_candidate_id, current_source_head_candidate_state_sha256, current_source_head_artifact_id, current_source_head_artifact_sha256, candidate_id, candidate_state_sha256, artifact_id, artifact_sha256, reference_id, reference_sha256, reference_canvas_object_sha256, reference_canvas_canonical_sha256, design_spec_object_sha256, design_spec_canonical_sha256, camera_hash, camera_lock_id, camera_lock_canonical_sha256, camera_rig_object_sha256, camera_rig_canonical_sha256, camera_lock_receipt_object_sha256, camera_lock_source_transition_id, camera_lock_source_transition_sha256, camera_lock_source_head_canonical_sha256, reviewed_reference_view_kinds_json, fixed_camera_view_kinds_json, legacy_form_quality_object_sha256, legacy_form_quality_canonical_sha256, form_art_evidence_object_sha256, form_art_evidence_canonical_sha256, view_decisions_json, aggregate_json, previous_form_quality_id, previous_form_quality_report_object_sha256, previous_form_quality_canonical_sha256, form_quality_policy, form_quality_policy_sha256, threshold_policy, threshold_policy_sha256, CAST(hard_gate_passed AS TEXT), CAST(form_gate_passed AS TEXT), validator_status, structural_status, visual_status, human_status, engine_status, distribution_status, quality_status, CAST(runtime_write_performed AS TEXT), CAST(production_stage_advanced AS TEXT), CAST(candidate_confirmed AS TEXT), CAST(version_created AS TEXT), CAST(export_performed AS TEXT), request_sha256, input_sha256, receipt_object_sha256, canonical_sha256, created_at, payload_json FROM production_weapon_form_quality_v2_links WHERE form_quality_id = ?1",
        params![form_quality_id],
        |row| {
            let count = row.as_ref().column_count();
            (0..count).map(|index| row.get(index)).collect()
        },
    )?;
    let expected_parent_columns =
        production_weapon_form_quality_v2_parent_columns(&quality, &payload)?;
    if parent_columns != expected_parent_columns {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_PARENT_BINDING_MISMATCH",
            "stored V2 parent scalar columns differ",
        ));
    }
    let receipt = read_form_quality_object(
        transaction,
        cas,
        &receipt_sha,
        "V2 form-quality report",
        Some(PRODUCTION_WEAPON_FORM_QUALITY_V2_REPORT_KIND),
        true,
        MAX_PRODUCTION_WEAPON_FORM_QUALITY_V2_OBJECT_BYTES,
    )?;
    ensure_production_weapon_form_quality_v2_receipt(cas, &receipt, &payload)?;
    ensure_production_weapon_form_quality_v2_bindings(transaction, cas, &quality, true)?;
    ensure_production_weapon_form_quality_v2_children(transaction, cas, &quality, true)?;
    Ok(Some(quality))
}

fn read_production_weapon_form_quality_v2_for_connection(
    connection: &mut Connection,
    cas: &CasStore,
    form_quality_id: &str,
) -> Result<Option<ProductionWeaponFormQualityV2Record>, StoreError> {
    let transaction = connection.transaction()?;
    let result =
        read_production_weapon_form_quality_v2_in_transaction(&transaction, cas, form_quality_id)?;
    transaction.rollback()?;
    Ok(result)
}

fn record_production_weapon_form_quality_v2_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    quality: &ProductionWeaponFormQualityV2Record,
    receipt_object: &CasObjectRecord,
    payload: &str,
) -> Result<(ProductionWeaponFormQualityV2Record, bool), StoreError> {
    let registered = read_form_quality_object(
        transaction,
        cas,
        &receipt_object.sha256,
        "V2 form-quality report",
        Some(PRODUCTION_WEAPON_FORM_QUALITY_V2_REPORT_KIND),
        false,
        MAX_PRODUCTION_WEAPON_FORM_QUALITY_V2_OBJECT_BYTES,
    )?;
    if registered.sha256 != receipt_object.sha256
        || registered.size_bytes != receipt_object.size_bytes
        || registered.mime != receipt_object.mime
        || registered.kind != receipt_object.kind
        || registered.created_at != receipt_object.created_at
    {
        return Err(form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_REPORT_METADATA_MISMATCH",
            "supplied V2 report metadata differs from the registered CAS object",
        ));
    }
    ensure_production_weapon_form_quality_v2_receipt(cas, &registered, payload)?;
    let roots =
        ensure_production_weapon_form_quality_v2_bindings(transaction, cas, quality, false)?;
    let existing: Option<(String, String)> = transaction
        .query_row(
            "SELECT payload_json, receipt_object_sha256 FROM production_weapon_form_quality_v2_links WHERE form_quality_id = ?1",
            params![quality.form_quality_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if let Some((stored_payload, stored_receipt_sha)) = existing {
        let mut current: ProductionWeaponFormQualityV2Record =
            serde_json::from_str(&stored_payload).map_err(|error| {
                form_quality_v2_error(
                    "PRODUCTION_WEAPON_FORM_QUALITY_V2_PAYLOAD_INVALID",
                    error.to_string(),
                )
            })?;
        current.receipt_object_sha256 = stored_receipt_sha.clone();
        validate_production_weapon_form_quality_v2(&current)?;
        if !same_production_weapon_form_quality_v2(&current, quality)
            || stored_receipt_sha != quality.receipt_object_sha256
        {
            return Err(form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_CONFLICT",
                "form_quality_id is already bound to different V2 evidence",
            ));
        }
        let mut all_roots = roots;
        all_roots.push(receipt_object.sha256.clone());
        all_roots.sort();
        all_roots.dedup();
        mark_reachable_in_transaction(transaction, &all_roots)?;
        let verified = read_production_weapon_form_quality_v2_in_transaction(
            transaction,
            cas,
            &quality.form_quality_id,
        )?
        .ok_or_else(|| {
            form_quality_v2_error(
                "PRODUCTION_WEAPON_FORM_QUALITY_V2_REPLAY_MISSING",
                "V2 replay disappeared",
            )
        })?;
        return Ok((verified, true));
    }
    production_weapon_form_quality_v2_insert(transaction, quality, payload)?;
    let mut all_roots = roots;
    all_roots.push(receipt_object.sha256.clone());
    all_roots.sort();
    all_roots.dedup();
    mark_reachable_in_transaction(transaction, &all_roots)?;
    let verified = read_production_weapon_form_quality_v2_in_transaction(
        transaction,
        cas,
        &quality.form_quality_id,
    )?
    .ok_or_else(|| {
        form_quality_v2_error(
            "PRODUCTION_WEAPON_FORM_QUALITY_V2_WRITE_MISSING",
            "V2 row disappeared before commit",
        )
    })?;
    Ok((verified, false))
}

// FPS-HIGH-LOW-CAGE-05 is intentionally kept in one immutable Store
// transaction.  The public API above is deliberately small; these helpers
// own the closed-field, cross-record and CAS checks so a direct Store caller
// cannot bypass the Runtime's structural gate.
const MAX_PRODUCTION_WEAPON_HIGH_LOW_GLTF_BYTES: u64 = 256 * 1024 * 1024;
const MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES: u64 = 8 * 1024 * 1024;
const MAX_PRODUCTION_WEAPON_HIGH_LOW_OBJECTS: usize = 256;

// FPS-LOW-RETOPO-CAGE-STORE-01 is an additive source bundle.  It is kept
// separate from the formal High->Low Bake tables above because this slice is
// deliberately non-promoting: it records a bounded Low retopology and its
// topology-correspondent Cage, but it cannot advance ProductionStage@3.
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SCHEMA: &str =
    "ProductionWeaponRetopologyCageSourceBundle@1";
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_POLICY: &str =
    "bounded-low-retopology-topology-correspondent-cage-source-only@1";
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_STATUS: &str =
    "runtime-owned-durable-production-weapon-retopology-cage-source-bundle";
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_LOW_KIND: &str =
    PRODUCTION_WEAPON_LOW_ARTIFACT_KIND;
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CAGE_KIND: &str =
    PRODUCTION_WEAPON_CAGE_ARTIFACT_KIND;
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_LOW_MESH_KIND: &str =
    "production-weapon-low-mesh";
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CORRESPONDENCE_KIND: &str =
    PRODUCTION_WEAPON_HIGH_LOW_CORRESPONDENCE_KIND;
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_OFFSET_FIELD_KIND: &str =
    "production-weapon-cage-offset-field";
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_KIND: &str =
    "production-weapon-retopology-cage-source-bundle-receipt";
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_SCHEMA: &str =
    "ProductionWeaponRetopologyCageSourceBundleReceipt@1";
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_LOW_READBACK_SCHEMA: &str =
    "ProductionWeaponLowArtifactReadback@1";
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CAGE_READBACK_SCHEMA: &str =
    "ProductionWeaponCageArtifactReadback@1";
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CAGE_WORKER_POLICY: &str =
    "exact-low-topology-per-vertex-normal-offset@1";

// These are the exact keys emitted by Runtime::make_receipt.  Keep this list
// closed: a source bundle receipt is a restart binding, not an extensible
// diagnostic bag.  In particular, unknown request/worker fields must not be
// smuggled into a durable link and silently escape replay validation.
const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_FIELDS: &[&str] = &[
    "schema_version",
    "bundle_key_sha256",
    "source_high_artifact_sha256",
    "source_candidate_state_sha256",
    "source_high_artifact_readback_object_sha256",
    "low_artifact_sha256",
    "cage_artifact_sha256",
    "low_mesh_object_sha256",
    "correspondence_object_sha256",
    "cage_offset_field_object_sha256",
    "low_worker_replay_count",
    "cage_worker_replay_count",
    "worker_build_cohort_sha256",
    "request_sha256",
    "target_triangle_count",
    "max_collapses",
    "locked_vertices",
    "offset_m",
    "max_offset_m",
    "max_coordinate_abs_m",
    "low_result_canonical_sha256",
    "cage_result_canonical_sha256",
    "low_mesh_sha256",
    "cage_mesh_sha256",
    "offset_field_sha256",
    "quality_status",
    "visual_quality_status",
    "production_stage_advanced",
    "candidate_confirmed",
    "version_created",
    "export_performed",
    "canonical_sha256",
];

