fn production_weapon_high_low_error(code: &str, message: impl Into<String>) -> StoreError {
    StoreError::Contract {
        code: code.to_owned(),
        message: message.into(),
    }
}

fn high_low_value_string<'a>(value: &'a Value, field: &str) -> Option<&'a str> {
    value.get(field).and_then(Value::as_str)
}

fn high_low_require_string(value: &Value, field: &str, expected: &str) -> Result<(), StoreError> {
    if high_low_value_string(value, field) != Some(expected) {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_CONTRACT_MISMATCH",
            format!("{field} is not {expected}"),
        ));
    }
    Ok(())
}

fn high_low_require_bool(value: &Value, field: &str, expected: bool) -> Result<(), StoreError> {
    if value.get(field).and_then(Value::as_bool) != Some(expected) {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_CONTRACT_MISMATCH",
            format!("{field} has an invalid value"),
        ));
    }
    Ok(())
}

fn high_low_require_u64(value: &Value, field: &str, expected: u64) -> Result<(), StoreError> {
    if value.get(field).and_then(Value::as_u64) != Some(expected) {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_CONTRACT_MISMATCH",
            format!("{field} has an invalid value"),
        ));
    }
    Ok(())
}

fn high_low_validate_json_shape(value: &Value, path: &str) -> Result<(), StoreError> {
    match value {
        Value::Object(fields) => {
            for (field, child) in fields {
                let child_path = format!("{path}.{field}");
                if field.ends_with("_id") {
                    if !child.as_str().is_some_and(is_opaque_id) {
                        return Err(production_weapon_high_low_error(
                            "PRODUCTION_WEAPON_HIGH_LOW_ID_INVALID",
                            format!("{child_path} is not an opaque id"),
                        ));
                    }
                } else if field.ends_with("_ids") {
                    let values = child.as_array().ok_or_else(|| {
                        production_weapon_high_low_error(
                            "PRODUCTION_WEAPON_HIGH_LOW_ID_INVALID",
                            format!("{child_path} is not an id array"),
                        )
                    })?;
                    if values.len() > 256
                        || values
                            .iter()
                            .any(|item| !item.as_str().is_some_and(is_opaque_id))
                    {
                        return Err(production_weapon_high_low_error(
                            "PRODUCTION_WEAPON_HIGH_LOW_ID_INVALID",
                            format!("{child_path} contains an invalid id"),
                        ));
                    }
                } else if field.ends_with("_sha256") {
                    if !child.as_str().is_some_and(is_sha256) {
                        return Err(production_weapon_high_low_error(
                            "PRODUCTION_WEAPON_HIGH_LOW_HASH_INVALID",
                            format!("{child_path} is not a SHA-256"),
                        ));
                    }
                } else if field.ends_with("_sha256s") {
                    let values = child.as_array().ok_or_else(|| {
                        production_weapon_high_low_error(
                            "PRODUCTION_WEAPON_HIGH_LOW_HASH_INVALID",
                            format!("{child_path} is not a hash array"),
                        )
                    })?;
                    if values.len() > 256
                        || values
                            .iter()
                            .any(|item| !item.as_str().is_some_and(is_sha256))
                    {
                        return Err(production_weapon_high_low_error(
                            "PRODUCTION_WEAPON_HIGH_LOW_HASH_INVALID",
                            format!("{child_path} contains an invalid hash"),
                        ));
                    }
                } else if field == "created_at" {
                    if !child
                        .as_str()
                        .is_some_and(|text| !text.is_empty() && text.len() <= 128)
                    {
                        return Err(production_weapon_high_low_error(
                            "PRODUCTION_WEAPON_HIGH_LOW_CREATED_AT_INVALID",
                            format!("{child_path} is invalid"),
                        ));
                    }
                } else if field == "limitations" {
                    let values = child.as_array().ok_or_else(|| {
                        production_weapon_high_low_error(
                            "PRODUCTION_WEAPON_HIGH_LOW_LIMITATIONS_INVALID",
                            format!("{child_path} is not an array"),
                        )
                    })?;
                    if values.is_empty()
                        || values.len() > 32
                        || values.iter().any(|item| {
                            !item
                                .as_str()
                                .is_some_and(|text| !text.is_empty() && text.len() <= 512)
                        })
                    {
                        return Err(production_weapon_high_low_error(
                            "PRODUCTION_WEAPON_HIGH_LOW_LIMITATIONS_INVALID",
                            format!("{child_path} is invalid"),
                        ));
                    }
                }
                high_low_validate_json_shape(child, &child_path)?;
            }
        }
        Value::Array(values) => {
            for (index, child) in values.iter().enumerate() {
                high_low_validate_json_shape(child, &format!("{path}[{index}]"))?;
            }
        }
        Value::Number(number) if number.as_f64().is_none() => {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_NUMBER_INVALID",
                format!("{path} is not finite"),
            ));
        }
        _ => {}
    }
    Ok(())
}

fn production_weapon_high_low_payload_value<T: Serialize>(
    record: &T,
    label: &str,
) -> Result<Value, StoreError> {
    let value = serde_json::to_value(record).map_err(|error| {
        production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PAYLOAD_INVALID",
            format!("{label}: {error}"),
        )
    })?;
    let schema_version = value
        .get("schema_version")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if !schema_version.starts_with("ProductionWeapon") {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_SCHEMA_INVALID",
            format!("{label} has an invalid schema version"),
        ));
    }
    high_low_validate_json_shape(&value, label)?;
    let canonical = value
        .get("canonical_sha256")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_CANONICAL_INVALID",
                format!("{label} canonical hash is missing"),
            )
        })?
        .to_owned();
    let mut canonical_value = value.clone();
    canonical_value["receipt_object_sha256"] = Value::String(String::new());
    canonical_value["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&canonical_value) != canonical {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_CANONICAL_MISMATCH",
            format!("{label} canonical hash differs"),
        ));
    }
    high_low_require_string(&value, "quality_status", "structural_only")?;
    high_low_require_bool(&value, "runtime_write_performed", true)?;
    for field in [
        "production_stage_advanced",
        "candidate_confirmed",
        "version_created",
        "export_performed",
    ] {
        high_low_require_bool(&value, field, false)?;
    }
    if value.get("stage_advance_allowed").is_some() {
        high_low_require_bool(&value, "stage_advance_allowed", false)?;
    }
    for field in [
        "structural_status",
        "visual_status",
        "human_status",
        "engine_status",
        "distribution_status",
    ] {
        let valid = match field {
            "structural_status" => ["NOT_RUN", "BLOCKED", "PASS_SOURCE_STRUCTURAL"]
                .contains(&high_low_value_string(&value, field).unwrap_or("")),
            "visual_status" => ["NOT_RUN", "BLOCKED", "QUALITY_TARGET_NOT_MET", "NOT_PROVEN"]
                .contains(&high_low_value_string(&value, field).unwrap_or("")),
            "human_status" => ["NOT_RUN", "BLOCKED", "REJECTED", "PASS_HUMAN_ART_REVIEW"]
                .contains(&high_low_value_string(&value, field).unwrap_or("")),
            "engine_status" => ["NOT_RUN", "BLOCKED", "FAILED", "PASS_ENGINE_VALIDATION"]
                .contains(&high_low_value_string(&value, field).unwrap_or("")),
            _ => ["NOT_RUN", "BLOCKED", "FAILED", "PASS_DISTRIBUTION"]
                .contains(&high_low_value_string(&value, field).unwrap_or("")),
        };
        if !valid {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_STATUS_INVALID",
                format!("{label}.{field} is invalid"),
            ));
        }
    }
    Ok(value)
}

fn production_weapon_high_low_payload_json(value: &Value) -> Result<String, StoreError> {
    let mut payload = value.clone();
    payload["receipt_object_sha256"] = Value::String(String::new());
    let bytes = canonical_json_bytes(&payload).map_err(|error| {
        production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PAYLOAD_INVALID",
            error.to_string(),
        )
    })?;
    if bytes.is_empty() || bytes.len() as u64 > MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PAYLOAD_TOO_LARGE",
            "high-low JSON payload exceeds its bound",
        ));
    }
    String::from_utf8(bytes).map_err(|error| {
        production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_PAYLOAD_INVALID",
            error.to_string(),
        )
    })
}

fn high_low_add_role(
    roles: &mut HashMap<String, ProductionWeaponHighLowObjectRole>,
    sha256: &str,
    label: &str,
    expected_mime: Option<&str>,
    expected_kind: Option<&str>,
    max_bytes: u64,
    allow_png: bool,
) -> Result<(), StoreError> {
    if !is_sha256(sha256) {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_HASH_INVALID",
            format!("{label} is not a SHA-256"),
        ));
    }
    if let Some(existing) = roles.get_mut(sha256) {
        if existing
            .expected_mime
            .as_deref()
            .zip(expected_mime)
            .is_some_and(|(left, right)| left != right)
            || existing
                .expected_kind
                .as_deref()
                .zip(expected_kind)
                .is_some_and(|(left, right)| left != right)
        {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_CAS_ROLE_CONFLICT",
                format!("{label} reuses a hash with incompatible CAS roles"),
            ));
        }
        if existing.expected_mime.is_none() {
            existing.expected_mime = expected_mime.map(str::to_owned);
        }
        if existing.expected_kind.is_none() {
            existing.expected_kind = expected_kind.map(str::to_owned);
            existing.expected_kinds = expected_kind
                .map(|kind| vec![kind.to_owned()])
                .unwrap_or_default();
        }
        existing.max_bytes = existing.max_bytes.min(max_bytes);
        existing.allow_png |= allow_png;
        return Ok(());
    }
    roles.insert(
        sha256.to_owned(),
        ProductionWeaponHighLowObjectRole {
            sha256: sha256.to_owned(),
            label: label.to_owned(),
            expected_mime: expected_mime.map(str::to_owned),
            expected_kind: expected_kind.map(str::to_owned),
            expected_kinds: expected_kind
                .map(|kind| vec![kind.to_owned()])
                .unwrap_or_default(),
            max_bytes,
            allow_png,
        },
    );
    Ok(())
}

fn high_low_add_role_with_kinds(
    roles: &mut HashMap<String, ProductionWeaponHighLowObjectRole>,
    sha256: &str,
    label: &str,
    expected_mime: Option<&str>,
    expected_kinds: &[&str],
    max_bytes: u64,
    allow_png: bool,
) -> Result<(), StoreError> {
    if expected_kinds.is_empty() {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_CAS_ROLE_CONFLICT",
            format!("{label} has no closed CAS kind allowlist"),
        ));
    }
    if !is_sha256(sha256) {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_HASH_INVALID",
            format!("{label} is not a SHA-256"),
        ));
    }
    let expected_kinds = expected_kinds
        .iter()
        .map(|kind| (*kind).to_owned())
        .collect::<Vec<_>>();
    if let Some(existing) = roles.get(sha256) {
        if existing.expected_mime.as_deref() != expected_mime
            || existing.expected_kinds != expected_kinds
        {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_CAS_ROLE_CONFLICT",
                format!("{label} reuses a hash with incompatible CAS roles"),
            ));
        }
        return Ok(());
    }
    roles.insert(
        sha256.to_owned(),
        ProductionWeaponHighLowObjectRole {
            sha256: sha256.to_owned(),
            label: label.to_owned(),
            expected_mime: expected_mime.map(str::to_owned),
            expected_kind: (expected_kinds.len() == 1).then(|| expected_kinds[0].clone()),
            expected_kinds,
            max_bytes,
            allow_png,
        },
    );
    Ok(())
}

const PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_FIELDS: &[&str] = &[
    "schema_version",
    "bundle_key_sha256",
    "project_id",
    "source_candidate_id",
    "source_candidate_state_sha256",
    "source_high_artifact_sha256",
    "source_high_artifact_readback_object_sha256",
    "low_artifact_sha256",
    "low_artifact_readback_object_sha256",
    "cage_artifact_sha256",
    "cage_artifact_readback_object_sha256",
    "low_mesh_object_sha256",
    "correspondence_object_sha256",
    "cage_offset_field_object_sha256",
    "receipt_object_sha256",
    "low_retopology_policy",
    "cage_policy",
    "source_status",
    "quality_status",
    "visual_quality_status",
    "human_review_status",
    "commercial_engine_status",
    "runtime_write_performed",
    "production_stage_advanced",
    "candidate_confirmed",
    "version_created",
    "export_performed",
    "request_sha256",
    "canonical_sha256",
    "created_at",
];

fn production_weapon_retopology_cage_source_bundle_error(
    code: &str,
    message: impl Into<String>,
) -> StoreError {
    StoreError::Contract {
        code: code.to_owned(),
        message: message.into(),
    }
}

fn retopo_bundle_string<'a>(value: &'a Value, field: &str) -> Result<&'a str, StoreError> {
    value
        .get(field)
        .and_then(Value::as_str)
        .filter(|text| !text.is_empty())
        .ok_or_else(|| {
            production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_FIELD_INVALID",
                format!("{field} is missing or empty"),
            )
        })
}

fn retopo_bundle_bool(value: &Value, field: &str) -> Result<bool, StoreError> {
    value.get(field).and_then(Value::as_bool).ok_or_else(|| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_FIELD_INVALID",
            format!("{field} is not boolean"),
        )
    })
}

fn retopo_bundle_normalized(value: &Value) -> Result<Value, StoreError> {
    let mut normalized = value.clone();
    let object = normalized.as_object_mut().ok_or_else(|| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_PAYLOAD_INVALID",
            "bundle is not a JSON object",
        )
    })?;
    for field in [
        "bundle_key_sha256",
        "receipt_object_sha256",
        "canonical_sha256",
        "created_at",
    ] {
        object.insert(field.to_owned(), Value::String(String::new()));
    }
    Ok(normalized)
}

fn retopo_bundle_payload_json(value: &Value) -> Result<String, StoreError> {
    let bytes = canonical_json_bytes(value).map_err(|error| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_PAYLOAD_INVALID",
            error.to_string(),
        )
    })?;
    if bytes.is_empty() || bytes.len() as u64 > MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_PAYLOAD_TOO_LARGE",
            "bundle payload exceeds the bounded JSON limit",
        ));
    }
    String::from_utf8(bytes).map_err(|error| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_PAYLOAD_INVALID",
            error.to_string(),
        )
    })
}

fn validate_production_weapon_retopology_cage_source_bundle_value(
    value: &Value,
) -> Result<String, StoreError> {
    let object = value.as_object().ok_or_else(|| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_PAYLOAD_INVALID",
            "bundle is not a JSON object",
        )
    })?;
    if object.len() != PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_FIELDS.len()
        || object.keys().any(|field| {
            !PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_FIELDS.contains(&field.as_str())
        })
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_FIELDS_INVALID",
            "bundle contains an unknown or missing field",
        ));
    }
    if retopo_bundle_string(value, "schema_version")?
        != PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SCHEMA
        || !is_sha256(retopo_bundle_string(value, "bundle_key_sha256")?)
        || !is_opaque_id(retopo_bundle_string(value, "project_id")?)
        || !is_opaque_id(retopo_bundle_string(value, "source_candidate_id")?)
        || !is_sha256(retopo_bundle_string(
            value,
            "source_candidate_state_sha256",
        )?)
        || !is_sha256(retopo_bundle_string(value, "source_high_artifact_sha256")?)
        || !is_sha256(retopo_bundle_string(
            value,
            "source_high_artifact_readback_object_sha256",
        )?)
        || !is_sha256(retopo_bundle_string(value, "low_artifact_sha256")?)
        || !is_sha256(retopo_bundle_string(
            value,
            "low_artifact_readback_object_sha256",
        )?)
        || !is_sha256(retopo_bundle_string(value, "cage_artifact_sha256")?)
        || !is_sha256(retopo_bundle_string(
            value,
            "cage_artifact_readback_object_sha256",
        )?)
        || !is_sha256(retopo_bundle_string(value, "low_mesh_object_sha256")?)
        || !is_sha256(retopo_bundle_string(value, "correspondence_object_sha256")?)
        || !is_sha256(retopo_bundle_string(
            value,
            "cage_offset_field_object_sha256",
        )?)
        || !is_sha256(retopo_bundle_string(value, "receipt_object_sha256")?)
        || !is_sha256(retopo_bundle_string(value, "request_sha256")?)
        || !is_sha256(retopo_bundle_string(value, "canonical_sha256")?)
        || retopo_bundle_string(value, "low_retopology_policy")?
            != PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_POLICY
        || retopo_bundle_string(value, "cage_policy")?
            != PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_POLICY
        || retopo_bundle_string(value, "source_status")?
            != PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_STATUS
        || retopo_bundle_string(value, "quality_status")? != "structural_only"
        || retopo_bundle_string(value, "visual_quality_status")? != "NOT_PROVEN"
        || retopo_bundle_string(value, "human_review_status")? != "NOT_RUN"
        || retopo_bundle_string(value, "commercial_engine_status")? != "NOT_RUN"
        || retopo_bundle_string(value, "created_at")?.is_empty()
        || retopo_bundle_string(value, "created_at")?.len() > 128
        || !retopo_bundle_bool(value, "runtime_write_performed")?
        || retopo_bundle_bool(value, "production_stage_advanced")?
        || retopo_bundle_bool(value, "candidate_confirmed")?
        || retopo_bundle_bool(value, "version_created")?
        || retopo_bundle_bool(value, "export_performed")?
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CONTRACT_INVALID",
            "bundle identity, policy, status or flags are invalid",
        ));
    }
    let normalized = retopo_bundle_normalized(value)?;
    let expected = canonical_json_hash(&normalized);
    if expected != retopo_bundle_string(value, "bundle_key_sha256")?
        || expected != retopo_bundle_string(value, "canonical_sha256")?
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CANONICAL_MISMATCH",
            "bundle key/canonical hash does not match the normalized payload",
        ));
    }
    Ok(expected)
}

fn same_production_weapon_retopology_cage_source_bundle(left: &Value, right: &Value) -> bool {
    let normalize = |value: &Value| {
        let mut value = value.clone();
        if let Some(object) = value.as_object_mut() {
            object.insert("canonical_sha256".to_owned(), Value::String(String::new()));
            object.insert("created_at".to_owned(), Value::String(String::new()));
        }
        value
    };
    canonical_json_bytes(&normalize(left)).ok() == canonical_json_bytes(&normalize(right)).ok()
}

fn production_weapon_retopology_cage_source_bundle_object_roles(
    value: &Value,
) -> Result<Vec<ProductionWeaponHighLowObjectRole>, StoreError> {
    let mut roles = HashMap::new();
    let glb = |roles: &mut HashMap<String, ProductionWeaponHighLowObjectRole>,
               hash: &str,
               label: &str,
               kind: &str| {
        high_low_add_role(
            roles,
            hash,
            label,
            Some("model/gltf-binary"),
            Some(kind),
            MAX_PRODUCTION_WEAPON_HIGH_LOW_GLTF_BYTES,
            false,
        )
    };
    let json = |roles: &mut HashMap<String, ProductionWeaponHighLowObjectRole>,
                hash: &str,
                label: &str,
                kind: &str| {
        high_low_add_role(
            roles,
            hash,
            label,
            Some("application/json"),
            Some(kind),
            MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES,
            false,
        )
    };
    let json_kinds = |roles: &mut HashMap<String, ProductionWeaponHighLowObjectRole>,
                      hash: &str,
                      label: &str,
                      kinds: &[&str]| {
        high_low_add_role_with_kinds(
            roles,
            hash,
            label,
            Some("application/json"),
            kinds,
            MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES,
            false,
        )
    };
    high_low_add_role_with_kinds(
        &mut roles,
        retopo_bundle_string(value, "source_high_artifact_sha256")?,
        "source high artifact",
        Some("model/gltf-binary"),
        &[
            "geometry-glb",
            "appearance-glb",
            "appearance-v2-glb",
            PRODUCTION_WEAPON_HIGH_ARTIFACT_KIND,
        ],
        MAX_PRODUCTION_WEAPON_HIGH_LOW_GLTF_BYTES,
        false,
    )?;
    high_low_add_role_with_kinds(
        &mut roles,
        retopo_bundle_string(value, "source_high_artifact_readback_object_sha256")?,
        "source high readback",
        Some("application/json"),
        &[
            "geometry-artifact-readback-v2",
            "appearance-v2-artifact-readback",
        ],
        MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES,
        false,
    )?;
    glb(
        &mut roles,
        retopo_bundle_string(value, "low_artifact_sha256")?,
        "low artifact",
        PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_LOW_KIND,
    )?;
    json_kinds(
        &mut roles,
        retopo_bundle_string(value, "low_artifact_readback_object_sha256")?,
        "low readback",
        &[
            PRODUCTION_WEAPON_LOW_ARTIFACT_RECEIPT_KIND,
            "geometry-artifact-readback-v2",
            "appearance-v2-artifact-readback",
        ],
    )?;
    glb(
        &mut roles,
        retopo_bundle_string(value, "cage_artifact_sha256")?,
        "cage artifact",
        PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CAGE_KIND,
    )?;
    json_kinds(
        &mut roles,
        retopo_bundle_string(value, "cage_artifact_readback_object_sha256")?,
        "cage readback",
        &[
            PRODUCTION_WEAPON_CAGE_ARTIFACT_RECEIPT_KIND,
            "geometry-artifact-readback-v2",
            "appearance-v2-artifact-readback",
        ],
    )?;
    json(
        &mut roles,
        retopo_bundle_string(value, "low_mesh_object_sha256")?,
        "low mesh",
        PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_LOW_MESH_KIND,
    )?;
    json(
        &mut roles,
        retopo_bundle_string(value, "correspondence_object_sha256")?,
        "correspondence",
        PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CORRESPONDENCE_KIND,
    )?;
    json(
        &mut roles,
        retopo_bundle_string(value, "cage_offset_field_object_sha256")?,
        "cage offset field",
        PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_OFFSET_FIELD_KIND,
    )?;
    json(
        &mut roles,
        retopo_bundle_string(value, "receipt_object_sha256")?,
        "bundle receipt",
        PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_KIND,
    )?;
    Ok(roles.into_values().collect())
}

fn ensure_production_weapon_retopology_cage_source_bundle_object(
    connection: &Connection,
    cas: &CasStore,
    role: &ProductionWeaponHighLowObjectRole,
) -> Result<(), StoreError> {
    let Some(expected_mime) = role.expected_mime.as_deref() else {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_ROLE_INVALID",
            format!("{} has no closed metadata role", role.label),
        ));
    };
    if role.expected_kinds.is_empty() {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_ROLE_INVALID",
            format!("{} has no closed metadata kind allowlist", role.label),
        ));
    }
    let row: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![role.sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((size, mime, kind, reachability)) = row else {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CAS_UNAVAILABLE",
            format!("{} is not registered", role.label),
        ));
    };
    if size <= 0
        || u64::try_from(size).unwrap_or(u64::MAX) > role.max_bytes
        || mime != expected_mime
        || !role.expected_kinds.iter().any(|expected| expected == &kind)
        || !matches!(reachability.as_str(), "temporary" | "reachable")
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CAS_METADATA_MISMATCH",
            format!("{} metadata differs", role.label),
        ));
    }
    cas.verify(
        &role.sha256,
        u64::try_from(size).map_err(|_| {
            production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CAS_METADATA_MISMATCH",
                format!("{} size is invalid", role.label),
            )
        })?,
    )?;
    Ok(())
}

fn validate_production_weapon_retopology_cage_source_bundle_json(
    cas: &CasStore,
    value: &Value,
    field: &str,
    expected_schema: Option<&str>,
    max_bytes: u64,
) -> Result<Value, StoreError> {
    let hash = retopo_bundle_string(value, field)?;
    let bytes = cas.read_verified_bounded(hash, max_bytes)?;
    let payload: Value = serde_json::from_slice(&bytes).map_err(|error| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_JSON_INVALID",
            format!("{field} is not canonical JSON: {error}"),
        )
    })?;
    if !payload.is_object() {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_JSON_INVALID",
            format!("{field} is not a JSON object"),
        ));
    }
    if let Some(expected_schema) = expected_schema {
        if payload.get("schema_version").and_then(Value::as_str) != Some(expected_schema) {
            return Err(production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_JSON_SCHEMA_INVALID",
                format!("{field} schema version differs"),
            ));
        }
    }
    if let Some(canonical) = payload.get("canonical_sha256").and_then(Value::as_str) {
        let mut normalized = payload.clone();
        normalized["canonical_sha256"] = Value::String(String::new());
        if canonical_json_hash(&normalized) != canonical {
            return Err(production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_JSON_CANONICAL_MISMATCH",
                format!("{field} canonical hash differs"),
            ));
        }
    } else {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_JSON_CANONICAL_MISSING",
            format!("{field} canonical hash is missing"),
        ));
    }
    Ok(payload)
}

fn validate_production_weapon_retopology_cage_source_bundle_json_bindings(
    payload: &Value,
    bundle: &Value,
    bindings: &[(&str, &str)],
) -> Result<(), StoreError> {
    for (json_field, bundle_field) in bindings {
        if payload.get(*json_field) != bundle.get(*bundle_field) {
            return Err(production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_JSON_BINDING_MISMATCH",
                format!("sidecar field {json_field} differs from bundle field {bundle_field}"),
            ));
        }
    }
    Ok(())
}

fn validate_production_weapon_retopology_cage_source_bundle_source_readback(
    cas: &CasStore,
    value: &Value,
) -> Result<(), StoreError> {
    let hash = retopo_bundle_string(value, "source_high_artifact_readback_object_sha256")?;
    let source_artifact = retopo_bundle_string(value, "source_high_artifact_sha256")?;
    let candidate_id = retopo_bundle_string(value, "source_candidate_id")?;
    let bytes = cas.read_verified_bounded(hash, MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES)?;
    let readback: Value = serde_json::from_slice(&bytes).map_err(|error| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SOURCE_READBACK_INVALID",
            format!("source high ArtifactReadback is not canonical JSON: {error}"),
        )
    })?;
    let object = readback.as_object().ok_or_else(|| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SOURCE_READBACK_INVALID",
            "source high ArtifactReadback is not an object",
        )
    })?;
    let string = |field: &str| {
        object.get(field).and_then(Value::as_str).ok_or_else(|| {
            production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SOURCE_READBACK_INVALID",
                format!("source high ArtifactReadback.{field} is missing"),
            )
        })
    };
    if string("schema_version")? != "ArtifactReadback@2"
        || string("artifact_id")? != source_artifact
        || string("object_sha256")? != source_artifact
        || string("candidate_id")? != candidate_id
        || string("mime")? != "model/gltf-binary"
        || object.get("validator_status").and_then(Value::as_str) != Some("passed")
        || object.get("hard_gate_passed").and_then(Value::as_bool) != Some(true)
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SOURCE_READBACK_BINDING_MISMATCH",
            "source high ArtifactReadback does not bind the candidate GLB",
        ));
    }
    let canonical = string("canonical_sha256")?;
    if !is_sha256(canonical) {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SOURCE_READBACK_CANONICAL_INVALID",
            "source high ArtifactReadback canonical hash is invalid",
        ));
    }
    let mut normalized = readback.clone();
    normalized["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&normalized) != canonical {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SOURCE_READBACK_CANONICAL_MISMATCH",
            "source high ArtifactReadback canonical hash differs",
        ));
    }
    Ok(())
}

fn validate_production_weapon_retopology_cage_source_bundle_derived_readback(
    cas: &CasStore,
    value: &Value,
    readback_field: &str,
    artifact_field: &str,
    artifact_schema: &str,
    source_binding_field: &str,
    source_binding_hash: &str,
) -> Result<(), StoreError> {
    let readback_hash = retopo_bundle_string(value, readback_field)?;
    let artifact_hash = retopo_bundle_string(value, artifact_field)?;
    let bytes =
        cas.read_verified_bounded(readback_hash, MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES)?;
    let readback: Value = serde_json::from_slice(&bytes).map_err(|error| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_DERIVED_READBACK_INVALID",
            format!("{readback_field} is not canonical JSON: {error}"),
        )
    })?;
    let object = readback.as_object().ok_or_else(|| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_DERIVED_READBACK_INVALID",
            format!("{readback_field} is not an object"),
        )
    })?;
    let schema = object
        .get("schema_version")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_DERIVED_READBACK_INVALID",
                format!("{readback_field}.schema_version is missing"),
            )
        })?;
    if schema != artifact_schema {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_DERIVED_READBACK_BINDING_MISMATCH",
            format!("{readback_field} schema differs from {artifact_schema}"),
        ));
    }
    let expected_fields = [
        "schema_version",
        "artifact_sha256",
        source_binding_field,
        "worker_readback",
        "canonical_sha256",
    ];
    if object.len() != expected_fields.len()
        || object
            .keys()
            .any(|field| !expected_fields.contains(&field.as_str()))
        || object.get("artifact_sha256").and_then(Value::as_str) != Some(artifact_hash)
        || object.get(source_binding_field).and_then(Value::as_str) != Some(source_binding_hash)
        || !object
            .get("artifact_sha256")
            .and_then(Value::as_str)
            .is_some_and(is_sha256)
        || !object
            .get(source_binding_field)
            .and_then(Value::as_str)
            .is_some_and(is_sha256)
        || !object.get("worker_readback").is_some_and(Value::is_object)
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_DERIVED_READBACK_BINDING_MISMATCH",
            format!("{readback_field} does not bind {artifact_field} and its source"),
        ));
    }
    let canonical = object
        .get("canonical_sha256")
        .and_then(Value::as_str)
        .filter(|hash| is_sha256(hash))
        .ok_or_else(|| {
            production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_DERIVED_READBACK_CANONICAL_INVALID",
                format!("{readback_field}.canonical_sha256 is missing"),
            )
        })?;
    let mut normalized = readback.clone();
    normalized["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&normalized) != canonical {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_DERIVED_READBACK_CANONICAL_MISMATCH",
            format!("{readback_field} canonical hash differs"),
        ));
    }
    Ok(())
}

fn validate_production_weapon_retopology_cage_source_bundle_receipt(
    cas: &CasStore,
    value: &Value,
) -> Result<(), StoreError> {
    let hash = retopo_bundle_string(value, "receipt_object_sha256")?;
    let bytes = cas.read_verified_bounded(hash, MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES)?;
    let receipt: Value = serde_json::from_slice(&bytes).map_err(|error| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_INVALID",
            format!("receipt is not canonical JSON: {error}"),
        )
    })?;
    let object = receipt.as_object().ok_or_else(|| {
        production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_INVALID",
            "receipt is not an object",
        )
    })?;
    if object.get("schema_version").and_then(Value::as_str)
        != Some(PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_SCHEMA)
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_SCHEMA_INVALID",
            "receipt schema version differs",
        ));
    }
    if object.len() != PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_FIELDS.len()
        || object.keys().any(|field| {
            !PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_FIELDS
                .contains(&field.as_str())
        })
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_FIELDS_INVALID",
            "receipt contains an unknown or missing field",
        ));
    }
    for (receipt_field, bundle_field) in [
        ("bundle_key_sha256", "bundle_key_sha256"),
        ("source_high_artifact_sha256", "source_high_artifact_sha256"),
        (
            "source_candidate_state_sha256",
            "source_candidate_state_sha256",
        ),
        (
            "source_high_artifact_readback_object_sha256",
            "source_high_artifact_readback_object_sha256",
        ),
        ("low_artifact_sha256", "low_artifact_sha256"),
        ("cage_artifact_sha256", "cage_artifact_sha256"),
        ("low_mesh_object_sha256", "low_mesh_object_sha256"),
        (
            "correspondence_object_sha256",
            "correspondence_object_sha256",
        ),
        (
            "cage_offset_field_object_sha256",
            "cage_offset_field_object_sha256",
        ),
        ("request_sha256", "request_sha256"),
    ] {
        if object.get(receipt_field) != value.get(bundle_field) {
            return Err(production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_BINDING_MISMATCH",
                format!("receipt field {receipt_field} differs from bundle"),
            ));
        }
    }
    for field in [
        "bundle_key_sha256",
        "source_high_artifact_sha256",
        "source_candidate_state_sha256",
        "source_high_artifact_readback_object_sha256",
        "low_artifact_sha256",
        "cage_artifact_sha256",
        "low_mesh_object_sha256",
        "correspondence_object_sha256",
        "cage_offset_field_object_sha256",
        "request_sha256",
        "worker_build_cohort_sha256",
        "low_result_canonical_sha256",
        "cage_result_canonical_sha256",
        "low_mesh_sha256",
        "cage_mesh_sha256",
        "offset_field_sha256",
    ] {
        if !object
            .get(field)
            .and_then(Value::as_str)
            .is_some_and(is_sha256)
        {
            return Err(production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_FIELD_INVALID",
                format!("receipt field {field} is not a SHA-256"),
            ));
        }
    }
    if object
        .get("low_worker_replay_count")
        .and_then(Value::as_u64)
        != Some(2)
        || object
            .get("cage_worker_replay_count")
            .and_then(Value::as_u64)
            != Some(2)
        || object.get("quality_status").and_then(Value::as_str) != Some("structural_only")
        || object.get("visual_quality_status").and_then(Value::as_str) != Some("NOT_PROVEN")
        || object
            .get("production_stage_advanced")
            .and_then(Value::as_bool)
            != Some(false)
        || object.get("candidate_confirmed").and_then(Value::as_bool) != Some(false)
        || object.get("version_created").and_then(Value::as_bool) != Some(false)
        || object.get("export_performed").and_then(Value::as_bool) != Some(false)
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_STATUS_INVALID",
            "receipt replay/status flags differ",
        ));
    }
    for field in ["target_triangle_count", "max_collapses"] {
        if object
            .get(field)
            .and_then(Value::as_u64)
            .is_none_or(|value| value == 0 || value > 1_000_000)
        {
            return Err(production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_REQUEST_INVALID",
                format!("receipt field {field} is outside its bound"),
            ));
        }
    }
    let locked_vertices = object
        .get("locked_vertices")
        .and_then(Value::as_array)
        .filter(|values| values.len() <= 16_384)
        .ok_or_else(|| {
            production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_REQUEST_INVALID",
                "receipt locked_vertices is invalid",
            )
        })?;
    for vertex in locked_vertices {
        let vertex = vertex.as_object().ok_or_else(|| {
            production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_REQUEST_INVALID",
                "receipt locked vertex is not an object",
            )
        })?;
        if vertex.len() != 2
            || vertex
                .keys()
                .any(|field| !["primitive_ordinal", "vertex_index"].contains(&field.as_str()))
            || vertex.values().any(|field| field.as_u64().is_none())
        {
            return Err(production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_REQUEST_INVALID",
                "receipt locked vertex fields are invalid",
            ));
        }
    }
    let offset_m = object.get("offset_m").and_then(Value::as_f64);
    let max_offset_m = object.get("max_offset_m").and_then(Value::as_f64);
    let max_coordinate_abs_m = object.get("max_coordinate_abs_m").and_then(Value::as_f64);
    if offset_m.is_none_or(|value| !value.is_finite() || value <= 0.0)
        || max_offset_m.is_none_or(|value| !value.is_finite() || value <= 0.0)
        || max_coordinate_abs_m.is_none_or(|value| !value.is_finite() || value <= 0.0)
        || offset_m > max_offset_m
        || max_offset_m > Some(1.0)
        || max_coordinate_abs_m > Some(1_000.0)
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_REQUEST_INVALID",
            "receipt cage bounds are invalid",
        ));
    }
    let canonical = object
        .get("canonical_sha256")
        .and_then(Value::as_str)
        .filter(|hash| is_sha256(hash))
        .ok_or_else(|| {
            production_weapon_retopology_cage_source_bundle_error(
                "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_CANONICAL_INVALID",
                "receipt canonical hash is missing",
            )
        })?;
    let mut normalized = receipt.clone();
    normalized["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&normalized) != canonical {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_CANONICAL_MISMATCH",
            "receipt canonical hash differs",
        ));
    }
    Ok(())
}

fn validate_production_weapon_retopology_cage_source_bundle_rows(
    connection: &Connection,
    cas: &CasStore,
    value: &Value,
    roles: &[ProductionWeaponHighLowObjectRole],
) -> Result<(), StoreError> {
    validate_production_weapon_retopology_cage_source_bundle_value(value)?;
    let project_id = retopo_bundle_string(value, "project_id")?;
    let candidate_id = retopo_bundle_string(value, "source_candidate_id")?;
    let candidate: Option<(String, String, Option<String>, Option<String>)> = connection
        .query_row(
            "SELECT project_id, canonical_sha256, prepared_object_id, prepared_object_sha256 FROM candidates WHERE candidate_id = ?1",
            params![candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((candidate_project, candidate_state, prepared_id, prepared_sha)) = candidate else {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SOURCE_UNAVAILABLE",
            "source candidate is not registered",
        ));
    };
    if candidate_project != project_id
        || candidate_state != retopo_bundle_string(value, "source_candidate_state_sha256")?
        || prepared_sha.as_deref()
            != Some(retopo_bundle_string(value, "source_high_artifact_sha256")?)
        || prepared_id.is_none()
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_SOURCE_BINDING_MISMATCH",
            "source candidate/project/state/high artifact binding differs",
        ));
    }
    for role in roles {
        ensure_production_weapon_retopology_cage_source_bundle_object(connection, cas, role)?;
    }
    validate_production_weapon_retopology_cage_source_bundle_source_readback(cas, value)?;
    validate_production_weapon_retopology_cage_source_bundle_derived_readback(
        cas,
        value,
        "low_artifact_readback_object_sha256",
        "low_artifact_sha256",
        PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_LOW_READBACK_SCHEMA,
        "source_high_artifact_sha256",
        retopo_bundle_string(value, "source_high_artifact_sha256")?,
    )?;
    validate_production_weapon_retopology_cage_source_bundle_derived_readback(
        cas,
        value,
        "cage_artifact_readback_object_sha256",
        "cage_artifact_sha256",
        PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CAGE_READBACK_SCHEMA,
        "source_low_artifact_sha256",
        retopo_bundle_string(value, "low_artifact_sha256")?,
    )?;
    let low_mesh = validate_production_weapon_retopology_cage_source_bundle_json(
        cas,
        value,
        "low_mesh_object_sha256",
        Some("ProductionWeaponLowMesh@1"),
        MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES,
    )?;
    validate_production_weapon_retopology_cage_source_bundle_json_bindings(
        &low_mesh,
        value,
        &[
            ("source_high_artifact_sha256", "source_high_artifact_sha256"),
            ("low_artifact_sha256", "low_artifact_sha256"),
        ],
    )?;
    let correspondence = validate_production_weapon_retopology_cage_source_bundle_json(
        cas,
        value,
        "correspondence_object_sha256",
        Some("ProductionWeaponHighLowCorrespondence@1"),
        MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES,
    )?;
    validate_production_weapon_retopology_cage_source_bundle_json_bindings(
        &correspondence,
        value,
        &[
            ("source_high_artifact_sha256", "source_high_artifact_sha256"),
            ("low_artifact_sha256", "low_artifact_sha256"),
        ],
    )?;
    let offset = validate_production_weapon_retopology_cage_source_bundle_json(
        cas,
        value,
        "cage_offset_field_object_sha256",
        Some("ProductionWeaponCageOffsetField@1"),
        MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES,
    )?;
    validate_production_weapon_retopology_cage_source_bundle_json_bindings(
        &offset,
        value,
        &[
            ("source_low_artifact_sha256", "low_artifact_sha256"),
            ("cage_artifact_sha256", "cage_artifact_sha256"),
        ],
    )?;
    if offset.get("offset_field_policy").and_then(Value::as_str)
        != Some(PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_CAGE_WORKER_POLICY)
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_JSON_BINDING_MISMATCH",
            "cage offset sidecar policy differs",
        ));
    }
    validate_production_weapon_retopology_cage_source_bundle_receipt(cas, value)
}

fn validate_production_weapon_retopology_cage_source_bundle_stored_columns(
    connection: &Connection,
    value: &Value,
) -> Result<(), StoreError> {
    let key = retopo_bundle_string(value, "bundle_key_sha256")?;
    let stored: Option<Vec<Option<String>>> = connection
        .query_row(
            "SELECT schema_version, bundle_key_sha256, project_id, source_candidate_id, source_candidate_state_sha256, source_high_artifact_sha256, source_high_artifact_readback_object_sha256, low_artifact_sha256, low_artifact_readback_object_sha256, cage_artifact_sha256, cage_artifact_readback_object_sha256, low_mesh_object_sha256, correspondence_object_sha256, cage_offset_field_object_sha256, receipt_object_sha256, low_retopology_policy, cage_policy, source_status, quality_status, visual_quality_status, human_review_status, commercial_engine_status, CAST(runtime_write_performed AS TEXT), CAST(production_stage_advanced AS TEXT), CAST(candidate_confirmed AS TEXT), CAST(version_created AS TEXT), CAST(export_performed AS TEXT), request_sha256, canonical_sha256, created_at, payload_json FROM production_weapon_retopology_cage_source_bundle_links WHERE bundle_key_sha256 = ?1",
            params![key],
            |row| {
                let count = row.as_ref().column_count();
                (0..count)
                    .map(|index| row.get(index))
                    .collect::<Result<Vec<Option<String>>, _>>()
            },
        )
        .optional()?;
    let Some(stored) = stored else {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_ROW_MISSING",
            "bundle scalar row is missing",
        ));
    };
    let text = |field: &str| retopo_bundle_string(value, field).map(str::to_owned);
    let boolean = |field: &str| {
        retopo_bundle_bool(value, field).map(|flag| if flag { "1" } else { "0" }.to_owned())
    };
    let expected = vec![
        Some(text("schema_version")?),
        Some(text("bundle_key_sha256")?),
        Some(text("project_id")?),
        Some(text("source_candidate_id")?),
        Some(text("source_candidate_state_sha256")?),
        Some(text("source_high_artifact_sha256")?),
        Some(text("source_high_artifact_readback_object_sha256")?),
        Some(text("low_artifact_sha256")?),
        Some(text("low_artifact_readback_object_sha256")?),
        Some(text("cage_artifact_sha256")?),
        Some(text("cage_artifact_readback_object_sha256")?),
        Some(text("low_mesh_object_sha256")?),
        Some(text("correspondence_object_sha256")?),
        Some(text("cage_offset_field_object_sha256")?),
        Some(text("receipt_object_sha256")?),
        Some(text("low_retopology_policy")?),
        Some(text("cage_policy")?),
        Some(text("source_status")?),
        Some(text("quality_status")?),
        Some(text("visual_quality_status")?),
        Some(text("human_review_status")?),
        Some(text("commercial_engine_status")?),
        Some(boolean("runtime_write_performed")?),
        Some(boolean("production_stage_advanced")?),
        Some(boolean("candidate_confirmed")?),
        Some(boolean("version_created")?),
        Some(boolean("export_performed")?),
        Some(text("request_sha256")?),
        Some(text("canonical_sha256")?),
        Some(text("created_at")?),
        Some(retopo_bundle_payload_json(value)?),
    ];
    if stored != expected {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_PARENT_BINDING_MISMATCH",
            "stored parent scalar columns differ from canonical payload",
        ));
    }
    Ok(())
}

fn prepare_production_weapon_retopology_cage_source_bundle(
    cas: &CasStore,
    value: &Value,
    receipt_object: &CasObjectRecord,
) -> Result<ProductionWeaponRetopologyCageSourceBundlePrepared, StoreError> {
    let bundle_key_sha256 = validate_production_weapon_retopology_cage_source_bundle_value(value)?;
    if receipt_object.schema_version != "CasObject@1"
        || receipt_object.sha256 != retopo_bundle_string(value, "receipt_object_sha256")?
        || receipt_object.mime != "application/json"
        || receipt_object.kind != PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_KIND
        || receipt_object.size_bytes == 0
        || receipt_object.size_bytes > MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES
        || !matches!(
            receipt_object.reachability.as_str(),
            "temporary" | "reachable"
        )
    {
        return Err(production_weapon_retopology_cage_source_bundle_error(
            "PRODUCTION_WEAPON_RETOPOLOGY_CAGE_SOURCE_BUNDLE_RECEIPT_METADATA_INVALID",
            "receipt CAS metadata does not match the closed bundle role",
        ));
    }
    cas.verify(&receipt_object.sha256, receipt_object.size_bytes)?;
    validate_production_weapon_retopology_cage_source_bundle_receipt(cas, value)?;
    let payload_json = retopo_bundle_payload_json(value)?;
    Ok(ProductionWeaponRetopologyCageSourceBundlePrepared {
        value: value.clone(),
        payload_json,
        bundle_key_sha256,
        object_roles: production_weapon_retopology_cage_source_bundle_object_roles(value)?,
    })
}

fn production_weapon_high_low_object_roles(
    high: &ProductionWeaponHighArtifactRecord,
    low: &ProductionWeaponLowArtifactRecord,
    cage: &ProductionWeaponCageArtifactRecord,
    correspondence: &ProductionWeaponHighLowCorrespondenceRecord,
    plan: &ProductionWeaponHighLowBakePlanRecord,
    diagnostic: &ProductionWeaponHighLowDiagnosticRecord,
    receipt: &ProductionWeaponHighLowBakeReceiptRecord,
) -> Result<Vec<ProductionWeaponHighLowObjectRole>, StoreError> {
    let mut roles = HashMap::new();
    let glb = |roles: &mut HashMap<String, ProductionWeaponHighLowObjectRole>,
               hash: &str,
               label: &str,
               kind: Option<&str>| {
        high_low_add_role(
            roles,
            hash,
            label,
            Some("model/gltf-binary"),
            kind,
            MAX_PRODUCTION_WEAPON_HIGH_LOW_GLTF_BYTES,
            false,
        )
    };
    let json = |roles: &mut HashMap<String, ProductionWeaponHighLowObjectRole>,
                hash: &str,
                label: &str,
                kind: Option<&str>| {
        high_low_add_role(
            roles,
            hash,
            label,
            Some("application/json"),
            kind,
            MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES,
            false,
        )
    };
    glb(
        &mut roles,
        &high.source_artifact_sha256,
        "high source artifact",
        None,
    )?;
    glb(
        &mut roles,
        &high.high_artifact_sha256,
        "high artifact",
        Some(PRODUCTION_WEAPON_HIGH_ARTIFACT_KIND),
    )?;
    json(
        &mut roles,
        &high.high_artifact_readback_object_sha256,
        "high readback",
        Some(PRODUCTION_WEAPON_HIGH_ARTIFACT_RECEIPT_KIND),
    )?;
    json(
        &mut roles,
        &high.receipt_object_sha256,
        "high receipt",
        Some(PRODUCTION_WEAPON_HIGH_ARTIFACT_RECEIPT_KIND),
    )?;
    json(
        &mut roles,
        &high.high_geometry_program_object_sha256,
        "high geometry program",
        None,
    )?;
    json(
        &mut roles,
        &high.high_detail_graph_object_sha256,
        "high detail graph",
        None,
    )?;
    glb(
        &mut roles,
        &low.source_high_artifact_sha256,
        "low source high artifact",
        None,
    )?;
    glb(
        &mut roles,
        &low.low_artifact_sha256,
        "low artifact",
        Some(PRODUCTION_WEAPON_LOW_ARTIFACT_KIND),
    )?;
    json(
        &mut roles,
        &low.low_artifact_readback_object_sha256,
        "low readback",
        Some(PRODUCTION_WEAPON_LOW_ARTIFACT_RECEIPT_KIND),
    )?;
    json(
        &mut roles,
        &low.receipt_object_sha256,
        "low receipt",
        Some(PRODUCTION_WEAPON_LOW_ARTIFACT_RECEIPT_KIND),
    )?;
    json(
        &mut roles,
        &low.low_geometry_program_object_sha256,
        "low geometry program",
        None,
    )?;
    json(
        &mut roles,
        &low.low_authoring_topology_object_sha256,
        "low authoring topology",
        None,
    )?;
    glb(
        &mut roles,
        &cage.source_high_artifact_sha256,
        "cage source high artifact",
        None,
    )?;
    glb(
        &mut roles,
        &cage.source_low_artifact_sha256,
        "cage source low artifact",
        None,
    )?;
    glb(
        &mut roles,
        &cage.cage_artifact_sha256,
        "cage artifact",
        Some(PRODUCTION_WEAPON_CAGE_ARTIFACT_KIND),
    )?;
    json(
        &mut roles,
        &cage.cage_artifact_readback_object_sha256,
        "cage readback",
        Some(PRODUCTION_WEAPON_CAGE_ARTIFACT_RECEIPT_KIND),
    )?;
    json(
        &mut roles,
        &cage.receipt_object_sha256,
        "cage receipt",
        Some(PRODUCTION_WEAPON_CAGE_ARTIFACT_RECEIPT_KIND),
    )?;
    json(
        &mut roles,
        &cage.cage_geometry_program_object_sha256,
        "cage geometry program",
        None,
    )?;
    json(
        &mut roles,
        &cage.cage_offset_field_object_sha256,
        "cage offset field",
        None,
    )?;
    json(
        &mut roles,
        &correspondence.mapping_object_sha256,
        "correspondence mapping",
        Some(PRODUCTION_WEAPON_HIGH_LOW_CORRESPONDENCE_KIND),
    )?;
    json(
        &mut roles,
        &correspondence.receipt_object_sha256,
        "correspondence receipt",
        Some(PRODUCTION_WEAPON_HIGH_LOW_CORRESPONDENCE_KIND),
    )?;
    json(
        &mut roles,
        &plan.correspondence_object_sha256,
        "plan correspondence",
        Some(PRODUCTION_WEAPON_HIGH_LOW_CORRESPONDENCE_KIND),
    )?;
    json(
        &mut roles,
        &plan.receipt_object_sha256,
        "plan receipt",
        Some(PRODUCTION_WEAPON_HIGH_LOW_BAKE_PLAN_KIND),
    )?;
    json(
        &mut roles,
        &diagnostic.bake_plan_object_sha256,
        "diagnostic plan",
        Some(PRODUCTION_WEAPON_HIGH_LOW_BAKE_PLAN_KIND),
    )?;
    json(
        &mut roles,
        &diagnostic.distance_histogram_object_sha256,
        "distance histogram",
        Some(PRODUCTION_WEAPON_HIGH_LOW_DIAGNOSTIC_KIND),
    )?;
    json(
        &mut roles,
        &diagnostic.diagnostic_heatmap_object_sha256,
        "diagnostic heatmap",
        Some(PRODUCTION_WEAPON_HIGH_LOW_DIAGNOSTIC_KIND),
    )?;
    json(
        &mut roles,
        &diagnostic.receipt_object_sha256,
        "diagnostic receipt",
        Some(PRODUCTION_WEAPON_HIGH_LOW_DIAGNOSTIC_KIND),
    )?;
    json(
        &mut roles,
        &receipt.receipt_object_sha256,
        "bake receipt",
        Some(PRODUCTION_WEAPON_HIGH_LOW_BAKE_RECEIPT_KIND),
    )?;
    for (index, hash) in receipt.bake_output_object_sha256s.iter().enumerate() {
        high_low_add_role(
            &mut roles,
            hash,
            &format!("bake output {index}"),
            None,
            None,
            MAX_PRODUCTION_WEAPON_HIGH_LOW_JSON_BYTES,
            true,
        )?;
    }
    Ok(roles.into_values().collect())
}

fn high_low_validate_record_contracts(
    high: &ProductionWeaponHighArtifactRecord,
    low: &ProductionWeaponLowArtifactRecord,
    cage: &ProductionWeaponCageArtifactRecord,
    correspondence: &ProductionWeaponHighLowCorrespondenceRecord,
    plan: &ProductionWeaponHighLowBakePlanRecord,
    diagnostic: &ProductionWeaponHighLowDiagnosticRecord,
    receipt: &ProductionWeaponHighLowBakeReceiptRecord,
) -> Result<Vec<Value>, StoreError> {
    let values = vec![
        production_weapon_high_low_payload_value(high, "high")?,
        production_weapon_high_low_payload_value(low, "low")?,
        production_weapon_high_low_payload_value(cage, "cage")?,
        production_weapon_high_low_payload_value(correspondence, "correspondence")?,
        production_weapon_high_low_payload_value(plan, "plan")?,
        production_weapon_high_low_payload_value(diagnostic, "diagnostic")?,
        production_weapon_high_low_payload_value(receipt, "receipt")?,
    ];
    for (index, schema) in [
        (0, "ProductionWeaponHighArtifact@1"),
        (1, "ProductionWeaponLowArtifact@1"),
        (2, "ProductionWeaponCageArtifact@1"),
        (3, "ProductionWeaponHighLowCorrespondence@1"),
        (4, "ProductionWeaponHighLowBakePlan@1"),
        (5, "ProductionWeaponHighLowDiagnostic@1"),
        (6, "ProductionWeaponHighLowBakeReceipt@1"),
    ] {
        high_low_require_string(&values[index], "schema_version", schema)?;
    }
    for (index, field, expected) in [
        (0, "high_policy", PRODUCTION_WEAPON_HIGH_ARTIFACT_POLICY),
        (
            1,
            "low_retopology_policy",
            PRODUCTION_WEAPON_LOW_ARTIFACT_POLICY,
        ),
        (2, "cage_policy", PRODUCTION_WEAPON_CAGE_ARTIFACT_POLICY),
        (
            3,
            "correspondence_policy",
            PRODUCTION_WEAPON_HIGH_LOW_CORRESPONDENCE_POLICY,
        ),
        (
            4,
            "bake_policy",
            PRODUCTION_WEAPON_HIGH_LOW_BAKE_PLAN_POLICY,
        ),
        (
            5,
            "diagnostic_policy",
            PRODUCTION_WEAPON_HIGH_LOW_DIAGNOSTIC_POLICY,
        ),
        (6, "bake_policy", PRODUCTION_WEAPON_HIGH_LOW_BAKE_POLICY),
    ] {
        high_low_require_string(&values[index], field, expected)?;
    }
    for (index, field, expected) in [
        (
            0,
            "high_artifact_kind",
            PRODUCTION_WEAPON_HIGH_ARTIFACT_KIND,
        ),
        (1, "low_artifact_kind", PRODUCTION_WEAPON_LOW_ARTIFACT_KIND),
        (
            2,
            "cage_artifact_kind",
            PRODUCTION_WEAPON_CAGE_ARTIFACT_KIND,
        ),
    ] {
        high_low_require_string(&values[index], field, expected)?;
    }
    for (index, field) in [(0, "high_mime"), (1, "low_mime"), (2, "cage_mime")] {
        high_low_require_string(&values[index], field, "model/gltf-binary")?;
    }
    for (index, field) in [
        (0, "high_worker_replay_count"),
        (1, "low_worker_replay_count"),
        (2, "cage_worker_replay_count"),
        (3, "worker_replay_count"),
        (4, "worker_replay_count"),
        (5, "worker_replay_count"),
    ] {
        high_low_require_u64(&values[index], field, 2)?;
    }
    for (index, field) in [
        (0, "high_replay_byte_exact"),
        (1, "low_replay_byte_exact"),
        (2, "cage_replay_byte_exact"),
        (3, "replay_byte_exact"),
        (4, "replay_byte_exact"),
        (5, "replay_byte_exact"),
    ] {
        high_low_require_bool(&values[index], field, true)?;
    }
    high_low_require_string(&values[1], "low_authoring_topology_status", "complete")?;
    high_low_require_string(&values[1], "low_uv_status", "passed")?;
    high_low_require_string(&values[1], "low_tangent_status", "passed")?;
    for index in [4usize, 5] {
        high_low_require_string(&values[index], "normal_convention", "OpenGL+Y")?;
        high_low_require_string(
            &values[index],
            "bake_mode",
            PRODUCTION_WEAPON_HIGH_LOW_BAKE_MODE,
        )?;
        high_low_require_bool(&values[index], "surface_bake_reuse_allowed", false)?;
    }
    high_low_require_bool(&values[4], "diagnostic_required", true)?;
    high_low_require_bool(&values[6], "stage_advance_allowed", false)?;
    let expected_semantics = [
        "tangent-normal",
        "ao",
        "curvature",
        "thickness",
        "position",
        "object-id",
        "material-id",
        "part-id",
    ];
    let actual_semantics = values[4]
        .get("output_semantics")
        .and_then(Value::as_array)
        .map(|items| items.iter().filter_map(Value::as_str).collect::<Vec<_>>());
    if actual_semantics != Some(expected_semantics.to_vec()) {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_OUTPUT_SEMANTICS_INVALID",
            "bake plan output semantics differ",
        ));
    }
    let gate_scope = high_low_value_string(&values[6], "gate_scope").unwrap_or_default();
    let edge = match gate_scope {
        "high-artifact" => ("secondary-form-approved", "high-poly-approved"),
        "low-artifact" => ("high-poly-approved", "low-poly-approved"),
        "cage-artifact" => ("low-poly-approved", "cage-approved"),
        "high-low-bake" => ("cage-approved", "bake-approved"),
        _ => {
            return Err(production_weapon_high_low_error(
                "PRODUCTION_WEAPON_HIGH_LOW_GATE_SCOPE_INVALID",
                "unknown bake gate scope",
            ))
        }
    };
    high_low_require_string(&values[6], "source_stage", edge.0)?;
    high_low_require_string(&values[6], "target_stage", edge.1)?;
    if !production_stage_v3_is_adjacent(edge.0, edge.1) {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_STAGE_EDGE_INVALID",
            "bake gate is not an adjacent stage edge",
        ));
    }
    if high.high_candidate_id == low.low_candidate_id
        || high.high_artifact_sha256 == low.low_artifact_sha256
        || high.high_artifact_sha256 == cage.cage_artifact_sha256
        || low.low_artifact_sha256 == cage.cage_artifact_sha256
        || high.source_candidate_id == high.high_candidate_id
        || high.source_candidate_id == low.low_candidate_id
    {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_DISTINCT_BINDING_INVALID",
            "high, low, cage and source bindings must remain distinct",
        ));
    }
    if correspondence.part_pairs.len() > 256
        || correspondence.part_ids.len() > 256
        || correspondence.material_zone_ids.len() > 256
        || correspondence
            .part_pairs
            .iter()
            .map(|pair| pair.part_id.as_str())
            .collect::<HashSet<_>>()
            .len()
            != correspondence.part_pairs.len()
    {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_CORRESPONDENCE_INVALID",
            "correspondence exceeds its bounded unique part identity set",
        ));
    }
    for field in ["session_id", "project_id"] {
        let expected = high_low_value_string(&values[0], field);
        for value in values.iter().skip(1) {
            if high_low_value_string(value, field) != expected {
                return Err(production_weapon_high_low_error(
                    "PRODUCTION_WEAPON_HIGH_LOW_BINDING_MISMATCH",
                    format!("{field} differs across records"),
                ));
            }
        }
    }
    for field in [
        "source_stage_head_transition_id",
        "source_stage_head_transition_sha256",
        "source_stage_head_canonical_sha256",
        "source_stage_head_stage",
    ] {
        let expected = high_low_value_string(&values[0], field);
        for value in [&values[1], &values[2], &values[4], &values[5], &values[6]] {
            if high_low_value_string(value, field) != expected {
                return Err(production_weapon_high_low_error(
                    "PRODUCTION_WEAPON_HIGH_LOW_BINDING_MISMATCH",
                    format!("{field} differs across records"),
                ));
            }
        }
    }
    for (field, source_index, values_to_check) in [
        ("high_candidate_id", 0usize, [3usize, 4, 5, 6].as_slice()),
        ("high_artifact_sha256", 0usize, [3usize, 4, 5, 6].as_slice()),
        ("low_candidate_id", 1usize, [3usize, 4, 5, 6].as_slice()),
        ("low_artifact_sha256", 1usize, [3usize, 4, 5, 6].as_slice()),
        ("cage_artifact_sha256", 2usize, [3usize, 4, 5, 6].as_slice()),
    ] {
        let expected = high_low_value_string(&values[source_index], field);
        for index in values_to_check {
            if high_low_value_string(&values[*index], field) != expected {
                return Err(production_weapon_high_low_error(
                    "PRODUCTION_WEAPON_HIGH_LOW_BINDING_MISMATCH",
                    format!("{field} differs across records"),
                ));
            }
        }
    }
    Ok(values)
}

fn high_low_record_field_eq(
    values: &[Value],
    left_index: usize,
    left_field: &str,
    right_index: usize,
    right_field: &str,
    binding: &str,
) -> Result<(), StoreError> {
    let left = high_low_value_string(&values[left_index], left_field);
    let right = high_low_value_string(&values[right_index], right_field);
    if left.is_none() || left != right {
        return Err(production_weapon_high_low_error(
            "PRODUCTION_WEAPON_HIGH_LOW_BINDING_MISMATCH",
            format!("{binding} differs across records"),
        ));
    }
    Ok(())
}

