fn read_production_camera_lock_registration_lineage_columns(
    connection: &Connection,
    registration_lineage_id: &str,
) -> Result<Option<ProductionCameraLockRegistrationLineageRecord>, StoreError> {
    let row: Option<(String, String)> = connection
        .query_row(
            "SELECT payload_json, receipt_object_sha256 FROM agentic_production_camera_lock_registration_lineages WHERE registration_lineage_id = ?1",
            params![registration_lineage_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((payload_json, receipt_object_sha256)) = row else {
        return Ok(None);
    };
    let mut record: ProductionCameraLockRegistrationLineageRecord =
        serde_json::from_str(&payload_json).map_err(|error| {
            StoreError::InvalidData(format!(
                "invalid ProductionCameraLockRegistrationLineage@1 payload: {error}"
            ))
        })?;
    if record.registration_lineage_id != registration_lineage_id
        || (!record.receipt_object_sha256.is_empty()
            && record.receipt_object_sha256 != receipt_object_sha256)
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_PAYLOAD_KEY_MISMATCH".to_owned(),
            message: "camera lock registration lineage payload key or receipt binding differs"
                .to_owned(),
        });
    }
    record.receipt_object_sha256 = receipt_object_sha256;
    validate_production_camera_lock_registration_lineage_record(&record)?;
    if production_camera_lock_registration_lineage_payload_json(&record)? != payload_json {
        return Err(StoreError::Contract {
            code: "PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_PAYLOAD_MISMATCH".to_owned(),
            message: "camera lock registration lineage payload is not canonical".to_owned(),
        });
    }
    let expected =
        production_camera_lock_registration_lineage_column_values(&record, &payload_json);
    let stored: Vec<Option<String>> = connection.query_row(
        "SELECT schema_version, registration_lineage_id, camera_lock_id, camera_lock_canonical_sha256, camera_lock_receipt_object_sha256, session_id, project_id, source_transition_id, source_transition_sha256, source_head_canonical_sha256, candidate_id, candidate_state_sha256, artifact_id, artifact_sha256, reference_id, reference_sha256, reference_canvas_object_sha256, reference_canvas_canonical_sha256, design_spec_object_sha256, design_spec_canonical_sha256, subject_camera_rig_object_sha256, subject_camera_rig_canonical_sha256, geometry_program_object_sha256, geometry_program_sha256, semantic_landmark_ordering_object_sha256, semantic_landmark_ordering_canonical_sha256, authored_orientation_object_sha256, authored_orientation_canonical_sha256, authored_orientation_approval_receipt_object_sha256, registered_rig_v2_object_sha256, registered_rig_v2_canonical_sha256, lineage_policy, CAST(promotable AS TEXT), input_sha256, request_key_sha256, receipt_object_sha256, canonical_sha256, payload_json, created_at FROM agentic_production_camera_lock_registration_lineages WHERE registration_lineage_id = ?1",
        params![registration_lineage_id],
        |row| {
            let count = row.as_ref().column_count();
            (0..count).map(|index| row.get(index)).collect()
        },
    )?;
    if stored != expected {
        return Err(StoreError::Contract {
            code: "PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_COLUMN_MISMATCH".to_owned(),
            message: "camera lock registration lineage payload does not match SQLite columns"
                .to_owned(),
        });
    }
    Ok(Some(record))
}

