fn validate_production_camera_lock_registration_lineage_json_bindings(
    cas: &CasStore,
    record: &ProductionCameraLockRegistrationLineageRecord,
    geometry_program: &Value,
    semantic_ordering: &Value,
    authored_orientation: &Value,
    registered_rig_v2: &Value,
) -> Result<(), StoreError> {
    let binding_fields = [
        (
            "semantic ordering project",
            semantic_ordering.get("project_id").and_then(Value::as_str),
            record.project_id.as_str(),
        ),
        (
            "semantic ordering candidate",
            semantic_ordering
                .get("candidate_id")
                .and_then(Value::as_str),
            record.candidate_id.as_str(),
        ),
        (
            "semantic ordering state",
            semantic_ordering
                .get("candidate_state_sha256")
                .and_then(Value::as_str),
            record.candidate_state_sha256.as_str(),
        ),
        (
            "semantic ordering artifact",
            semantic_ordering
                .get("artifact_sha256")
                .and_then(Value::as_str),
            record.artifact_sha256.as_str(),
        ),
        (
            "semantic ordering reference",
            semantic_ordering
                .get("reference_sha256")
                .and_then(Value::as_str),
            record.reference_sha256.as_str(),
        ),
        (
            "semantic ordering subject rig",
            semantic_ordering
                .get("subject_camera_rig_object_sha256")
                .and_then(Value::as_str),
            record.subject_camera_rig_object_sha256.as_str(),
        ),
        (
            "semantic ordering subject rig canonical",
            semantic_ordering
                .get("subject_camera_rig_canonical_sha256")
                .and_then(Value::as_str),
            record.subject_camera_rig_canonical_sha256.as_str(),
        ),
        (
            "authored orientation project",
            authored_orientation
                .get("project_id")
                .and_then(Value::as_str),
            record.project_id.as_str(),
        ),
        (
            "authored orientation candidate",
            authored_orientation
                .get("candidate_id")
                .and_then(Value::as_str),
            record.candidate_id.as_str(),
        ),
        (
            "authored orientation state",
            authored_orientation
                .get("candidate_state_sha256")
                .and_then(Value::as_str),
            record.candidate_state_sha256.as_str(),
        ),
        (
            "authored orientation artifact",
            authored_orientation
                .get("artifact_sha256")
                .and_then(Value::as_str),
            record.artifact_sha256.as_str(),
        ),
        (
            "authored orientation reference",
            authored_orientation
                .get("reference_id")
                .and_then(Value::as_str),
            record.reference_id.as_str(),
        ),
        (
            "authored orientation reference hash",
            authored_orientation
                .get("reference_sha256")
                .and_then(Value::as_str),
            record.reference_sha256.as_str(),
        ),
        (
            "registered rig v2 project",
            registered_rig_v2.get("project_id").and_then(Value::as_str),
            record.project_id.as_str(),
        ),
        (
            "registered rig v2 candidate",
            registered_rig_v2
                .get("candidate_id")
                .and_then(Value::as_str),
            record.candidate_id.as_str(),
        ),
        (
            "registered rig v2 state",
            registered_rig_v2
                .get("candidate_state_sha256")
                .and_then(Value::as_str),
            record.candidate_state_sha256.as_str(),
        ),
        (
            "registered rig v2 artifact",
            registered_rig_v2
                .get("artifact_sha256")
                .and_then(Value::as_str),
            record.artifact_sha256.as_str(),
        ),
        (
            "registered rig v2 camera lock",
            registered_rig_v2
                .get("camera_lock_id")
                .and_then(Value::as_str),
            record.camera_lock_id.as_str(),
        ),
        (
            "registered rig v2 camera lock canonical",
            registered_rig_v2
                .get("camera_lock_canonical_sha256")
                .and_then(Value::as_str),
            record.camera_lock_canonical_sha256.as_str(),
        ),
        (
            "registered rig v2 semantic object",
            registered_rig_v2
                .get("semantic_landmark_ordering_object_sha256")
                .and_then(Value::as_str),
            record.semantic_landmark_ordering_object_sha256.as_str(),
        ),
        (
            "registered rig v2 semantic canonical",
            registered_rig_v2
                .get("semantic_landmark_ordering_canonical_sha256")
                .and_then(Value::as_str),
            record.semantic_landmark_ordering_canonical_sha256.as_str(),
        ),
        (
            "registered rig v2 orientation object",
            registered_rig_v2
                .get("rear_three_quarter_authored_orientation_object_sha256")
                .and_then(Value::as_str),
            record.authored_orientation_object_sha256.as_str(),
        ),
        (
            "registered rig v2 orientation canonical",
            registered_rig_v2
                .get("rear_three_quarter_authored_orientation_canonical_sha256")
                .and_then(Value::as_str),
            record.authored_orientation_canonical_sha256.as_str(),
        ),
    ];
    if let Some((field, _, _)) = binding_fields
        .into_iter()
        .find(|(_, actual, expected)| *actual != Some(*expected))
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_JSON_BINDING_MISMATCH".to_owned(),
            message: format!("camera lock registration lineage {field} differs"),
        });
    }
    if geometry_program
        .get("schema_version")
        .and_then(Value::as_str)
        != Some(PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_GEOMETRY_PROGRAM_SCHEMA_VERSION)
        || semantic_ordering
            .get("schema_version")
            .and_then(Value::as_str)
            != Some(PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_SEMANTIC_ORDERING_SCHEMA_VERSION)
        || authored_orientation
            .get("schema_version")
            .and_then(Value::as_str)
            != Some(PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_AUTHORED_ORIENTATION_SCHEMA_VERSION)
        || registered_rig_v2
            .get("schema_version")
            .and_then(Value::as_str)
            != Some(PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_REGISTERED_RIG_V2_SCHEMA_VERSION)
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_SCHEMA_MISMATCH".to_owned(),
            message: "camera lock registration lineage child schema is invalid".to_owned(),
        });
    }
    let orientation_promotable = authored_orientation
        .get("promotable")
        .and_then(Value::as_bool)
        == Some(true)
        && authored_orientation.get("status").and_then(Value::as_str)
            == Some("APPROVED_AUTHORED_REFERENCE_ORIENTATION")
        && authored_orientation
            .pointer("/orientation_provenance/orientation_explicitly_authored")
            .and_then(Value::as_bool)
            == Some(true)
        && authored_orientation
            .pointer("/orientation_provenance/source")
            .and_then(Value::as_str)
            == Some("user-authored-orientation-receipt")
        && authored_orientation
            .pointer("/orientation_provenance/authored_receipt_sha256")
            .and_then(Value::as_str)
            .is_some_and(is_sha256);
    if !orientation_promotable {
        return Err(StoreError::Contract {
            code: "BLOCKED_AUTHORED_REAR_THREE_QUARTER_ORIENTATION".to_owned(),
            message: "blocked authored orientation cannot create a camera registration lineage"
                .to_owned(),
        });
    }
    let approval_receipt_object_sha256 = record
        .authored_orientation_approval_receipt_object_sha256
        .as_deref()
        .filter(|hash| is_sha256(hash))
        .ok_or_else(|| StoreError::Contract {
            code: "BLOCKED_AUTHORED_ORIENTATION_APPROVAL_RECEIPT".to_owned(),
            message: "promotable camera registration lineage requires a CAS-backed authored orientation approval receipt"
                .to_owned(),
        })?;
    if authored_orientation
        .pointer("/orientation_provenance/authored_receipt_sha256")
        .and_then(Value::as_str)
        != Some(approval_receipt_object_sha256)
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_BINDING_MISMATCH".to_owned(),
            message:
                "authored orientation provenance must bind the exact approval receipt CAS object"
                    .to_owned(),
        });
    }
    let _ = cas;
    Ok(())
}

fn production_camera_lock_registration_lineage_reachable_hashes(
    transaction: &rusqlite::Transaction<'_>,
    parent: &ProductionCameraLockRecord,
    record: &ProductionCameraLockRegistrationLineageRecord,
) -> Result<Vec<String>, StoreError> {
    let mut hashes = vec![
        parent.camera_rig_object_sha256.clone(),
        parent.receipt_object_sha256.clone(),
        record.camera_lock_receipt_object_sha256.clone(),
        record.artifact_sha256.clone(),
        record.reference_sha256.clone(),
        record.reference_canvas_object_sha256.clone(),
        record.design_spec_object_sha256.clone(),
        record.subject_camera_rig_object_sha256.clone(),
        record.geometry_program_object_sha256.clone(),
        record.semantic_landmark_ordering_object_sha256.clone(),
        record.authored_orientation_object_sha256.clone(),
        record.registered_rig_v2_object_sha256.clone(),
        record.receipt_object_sha256.clone(),
    ];
    if let Some(hash) = record
        .authored_orientation_approval_receipt_object_sha256
        .clone()
    {
        hashes.push(hash);
    }
    let _ = transaction;
    hashes.sort();
    hashes.dedup();
    validate_reachable_hashes(&hashes)?;
    Ok(hashes)
}

fn read_production_camera_lock_registration_lineage_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    registration_lineage_id: &str,
) -> Result<Option<ProductionCameraLockRegistrationLineageRecord>, StoreError> {
    let Some(record) = read_production_camera_lock_registration_lineage_columns(
        transaction,
        registration_lineage_id,
    )?
    else {
        return Ok(None);
    };
    let parent =
        ensure_production_camera_lock_registration_lineage_parent(transaction, cas, &record)?;
    let generic_hashes = [
        (
            &record.camera_lock_receipt_object_sha256,
            "camera lock receipt",
            64 * 1024 * 1024,
        ),
        (&record.artifact_sha256, "artifact", 64 * 1024 * 1024),
        (&record.reference_sha256, "reference", 64 * 1024 * 1024),
        (
            &record.reference_canvas_object_sha256,
            "reference canvas",
            64 * 1024 * 1024,
        ),
        (
            &record.design_spec_object_sha256,
            "design spec",
            64 * 1024 * 1024,
        ),
        (
            &record.subject_camera_rig_object_sha256,
            "subject camera rig",
            MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        ),
        (
            &record.geometry_program_object_sha256,
            "geometry program",
            MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        ),
        (
            &record.semantic_landmark_ordering_object_sha256,
            "semantic ordering",
            MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        ),
        (
            &record.authored_orientation_object_sha256,
            "authored orientation",
            MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        ),
        (
            &record.registered_rig_v2_object_sha256,
            "registered rig v2",
            MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        ),
        (
            &record.receipt_object_sha256,
            "lineage receipt",
            MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        ),
    ];
    for (hash, label, max_bytes) in generic_hashes {
        let _ = read_production_camera_lock_registration_lineage_object(
            transaction,
            cas,
            hash,
            label,
            max_bytes,
            false,
            true,
        )?;
    }
    let lineage_receipt = read_production_camera_lock_registration_lineage_object(
        transaction,
        cas,
        &record.receipt_object_sha256,
        "lineage receipt",
        MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        true,
        true,
    )?;
    if lineage_receipt.kind != PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_RECEIPT_KIND {
        return Err(StoreError::Contract {
            code: "PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_RECEIPT_METADATA_INVALID".to_owned(),
            message: "camera lock registration lineage receipt kind is invalid".to_owned(),
        });
    }
    if let Some(hash) = record
        .authored_orientation_approval_receipt_object_sha256
        .as_deref()
    {
        let _ = read_production_camera_lock_registration_lineage_object(
            transaction,
            cas,
            hash,
            "authored orientation approval receipt",
            MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
            true,
            true,
        )?;
    }
    let subject_rig = read_production_camera_lock_registration_lineage_object(
        transaction,
        cas,
        &record.subject_camera_rig_object_sha256,
        "subject camera rig",
        MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        true,
        true,
    )?;
    let geometry_program = read_production_camera_lock_registration_lineage_object(
        transaction,
        cas,
        &record.geometry_program_object_sha256,
        "geometry program",
        MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        true,
        true,
    )?;
    let semantic_object = read_production_camera_lock_registration_lineage_object(
        transaction,
        cas,
        &record.semantic_landmark_ordering_object_sha256,
        "semantic ordering",
        MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        true,
        true,
    )?;
    let authored_object = read_production_camera_lock_registration_lineage_object(
        transaction,
        cas,
        &record.authored_orientation_object_sha256,
        "authored orientation",
        MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        true,
        true,
    )?;
    let rig_v2_object = read_production_camera_lock_registration_lineage_object(
        transaction,
        cas,
        &record.registered_rig_v2_object_sha256,
        "registered rig v2",
        MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
        true,
        true,
    )?;
    ensure_production_camera_lock_registration_lineage_kind(
        &semantic_object,
        PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_SEMANTIC_KIND,
        "semantic ordering",
    )?;
    ensure_production_camera_lock_registration_lineage_kind(
        &authored_object,
        PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_ORIENTATION_KIND,
        "authored orientation",
    )?;
    ensure_production_camera_lock_registration_lineage_kind(
        &rig_v2_object,
        PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_RIG_V2_KIND,
        "registered rig v2",
    )?;
    let semantic_ordering = verify_production_camera_lock_registration_lineage_json(
        cas,
        &semantic_object,
        &record.semantic_landmark_ordering_canonical_sha256,
        "semantic ordering",
    )?;
    let authored_orientation = verify_production_camera_lock_registration_lineage_json(
        cas,
        &authored_object,
        &record.authored_orientation_canonical_sha256,
        "authored orientation",
    )?;
    let registered_rig_v2 = verify_production_camera_lock_registration_lineage_json(
        cas,
        &rig_v2_object,
        &record.registered_rig_v2_canonical_sha256,
        "registered rig v2",
    )?;
    let _ = verify_production_camera_lock_registration_lineage_json(
        cas,
        &subject_rig,
        &record.subject_camera_rig_canonical_sha256,
        "subject camera rig",
    )?;
    let geometry_program = verify_production_camera_lock_registration_lineage_geometry_program(
        cas,
        &geometry_program,
        &record.geometry_program_sha256,
    )?;
    validate_production_camera_lock_registration_lineage_json_bindings(
        cas,
        &record,
        &geometry_program,
        &semantic_ordering,
        &authored_orientation,
        &registered_rig_v2,
    )?;
    let receipt = cas.read_verified_bounded(
        &record.receipt_object_sha256,
        MAX_PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_OBJECT_BYTES,
    )?;
    if receipt.as_slice()
        != production_camera_lock_registration_lineage_payload_json(&record)?.as_bytes()
    {
        return Err(StoreError::Contract {
            code: "PRODUCTION_CAMERA_LOCK_REGISTRATION_LINEAGE_RECEIPT_MISMATCH".to_owned(),
            message: "camera lock registration lineage receipt does not match payload".to_owned(),
        });
    }
    let _ = parent;
    Ok(Some(record))
}

fn read_production_camera_lock_registration_lineage_for_connection(
    connection: &mut Connection,
    cas: &CasStore,
    registration_lineage_id: &str,
) -> Result<Option<ProductionCameraLockRegistrationLineageRecord>, StoreError> {
    let transaction = connection.transaction()?;
    let result = read_production_camera_lock_registration_lineage_in_transaction(
        &transaction,
        cas,
        registration_lineage_id,
    )?;
    transaction.rollback()?;
    Ok(result)
}

