fn agentic_action_run_payload_json(record: &AgenticActionRunRecord) -> Result<String, StoreError> {
    let bytes = agentic_action_run_payload_bytes(record)?;
    if bytes.len() > 256 * 1024 {
        return Err(StoreError::InvalidData(
            "agentic action run payload exceeds bounded metadata capacity".to_owned(),
        ));
    }
    String::from_utf8(bytes).map_err(|error| StoreError::InvalidData(error.to_string()))
}

fn ensure_agentic_object(
    cas: &CasStore,
    object: &CasObjectRecord,
    expected_sha256: Option<&str>,
    payload: &str,
) -> Result<(), StoreError> {
    if expected_sha256 != Some(object.sha256.as_str())
        || sha256_hex(payload.as_bytes()) != object.sha256
    {
        return Err(StoreError::InvalidData(
            "agentic CAS object hash does not match canonical payload".to_owned(),
        ));
    }
    cas.verify(&object.sha256, object.size_bytes)?;
    Ok(())
}

fn validate_agentic_action_run_object(object: &CasObjectRecord) -> Result<(), StoreError> {
    if object.schema_version != "CasObject@1"
        || !is_sha256(&object.sha256)
        || i64::try_from(object.size_bytes).is_err()
        || object.mime != "application/json"
        || !is_opaque_id(&object.kind)
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || object.created_at.is_empty()
        || object.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "agentic action run CAS metadata is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn ensure_agentic_action_run_object_row(
    transaction: &rusqlite::Transaction<'_>,
    object: &CasObjectRecord,
) -> Result<(), StoreError> {
    let stored: Option<(i64, String, String, String)> = transaction
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![object.sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((size_bytes, mime, kind, reachability)) = stored else {
        return Err(StoreError::Contract {
            code: "AGENTIC_ACTION_RUN_CAS_OBJECT_UNAVAILABLE".to_owned(),
            message: "action run CAS object is not registered in SQLite".to_owned(),
        });
    };
    if size_bytes != i64::try_from(object.size_bytes).unwrap_or(i64::MAX)
        || mime != object.mime
        || kind != object.kind
        || !matches!(reachability.as_str(), "temporary" | "reachable")
    {
        return Err(StoreError::InvalidData(
            "action run CAS metadata differs from SQLite".to_owned(),
        ));
    }
    Ok(())
}

fn ensure_agentic_binding_rows(
    transaction: &rusqlite::Transaction<'_>,
    project_id: &str,
    candidate_id: &str,
    reference_id: &str,
    reference_sha256: &str,
) -> Result<(), StoreError> {
    let candidate_project: Option<String> = transaction
        .query_row(
            "SELECT project_id FROM candidates WHERE candidate_id = ?1",
            params![candidate_id],
            |row| row.get(0),
        )
        .optional()?;
    if candidate_project.as_deref() != Some(project_id) {
        return Err(StoreError::Contract {
            code: "AGENTIC_CANDIDATE_SCOPE_DENIED".to_owned(),
            message: "candidate is not in the requested project".to_owned(),
        });
    }
    let reference: Option<(String, String)> = transaction
        .query_row(
            "SELECT project_id, object_sha256 FROM reference_evidence WHERE reference_id = ?1",
            params![reference_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if reference.as_ref().map(|value| value.0.as_str()) != Some(project_id)
        || reference.as_ref().map(|value| value.1.as_str()) != Some(reference_sha256)
    {
        return Err(StoreError::Contract {
            code: "AGENTIC_REFERENCE_SCOPE_DENIED".to_owned(),
            message: "reference is not bound to the requested project/hash".to_owned(),
        });
    }
    Ok(())
}

fn ensure_agentic_action_run_binding_rows(
    transaction: &rusqlite::Transaction<'_>,
    run: &AgenticActionRunRecord,
) -> Result<(), StoreError> {
    let candidate_project: Option<String> = transaction
        .query_row(
            "SELECT project_id FROM candidates WHERE candidate_id = ?1",
            params![run.candidate_id],
            |row| row.get(0),
        )
        .optional()?;
    if candidate_project.as_deref() != Some(run.project_id.as_str()) {
        return Err(StoreError::Contract {
            code: "AGENTIC_ACTION_RUN_CANDIDATE_SCOPE_DENIED".to_owned(),
            message: "action run candidate is not in the requested project".to_owned(),
        });
    }

    let session: Option<(String, String)> = transaction
        .query_row(
            "SELECT project_id, candidate_id FROM agentic_design_sessions WHERE session_id = ?1",
            params![run.session_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((session_project, session_candidate)) = session else {
        return Err(StoreError::Contract {
            code: "AGENTIC_ACTION_RUN_SESSION_NOT_FOUND".to_owned(),
            message: "action run requires a persisted DesignSession".to_owned(),
        });
    };
    if session_project != run.project_id || session_candidate != run.candidate_id {
        return Err(StoreError::Contract {
            code: "AGENTIC_ACTION_RUN_BINDING_MISMATCH".to_owned(),
            message: "action run session, project and candidate bindings differ".to_owned(),
        });
    }

    if let Some(checkpoint_id) = run.checkpoint_id.as_deref() {
        let checkpoint: Option<(String, String, String, String)> = transaction
            .query_row(
                "SELECT session_id, project_id, candidate_id, canonical_sha256 FROM agentic_design_checkpoints WHERE checkpoint_id = ?1",
                params![checkpoint_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .optional()?;
        if checkpoint.as_ref().map(|value| {
            value.0 != run.session_id
                || value.1 != run.project_id
                || value.2 != run.candidate_id
                || Some(value.3.as_str()) != run.checkpoint_sha256.as_deref()
        }) != Some(false)
        {
            return Err(StoreError::Contract {
                code: "AGENTIC_ACTION_RUN_CHECKPOINT_MISMATCH".to_owned(),
                message: "action run checkpoint pointer is unavailable or out of scope".to_owned(),
            });
        }
    }
    Ok(())
}

fn ensure_design_action_run_binding_rows(
    transaction: &rusqlite::Transaction<'_>,
    run: &Value,
) -> Result<(), StoreError> {
    let object = run
        .as_object()
        .ok_or_else(|| StoreError::InvalidData("DesignActionRun is not an object".to_owned()))?;
    let project_id = object["project_id"].as_str().ok_or_else(|| {
        StoreError::InvalidData("DesignActionRun project_id is missing".to_owned())
    })?;
    let candidate_id = object["candidate_id"].as_str().ok_or_else(|| {
        StoreError::InvalidData("DesignActionRun candidate_id is missing".to_owned())
    })?;
    let session_id = object["session_id"].as_str().ok_or_else(|| {
        StoreError::InvalidData("DesignActionRun session_id is missing".to_owned())
    })?;
    let candidate_project: Option<String> = transaction
        .query_row(
            "SELECT project_id FROM candidates WHERE candidate_id = ?1",
            params![candidate_id],
            |row| row.get(0),
        )
        .optional()?;
    if candidate_project.as_deref() != Some(project_id) {
        return Err(StoreError::Contract {
            code: "DESIGN_ACTION_RUN_CANDIDATE_SCOPE_DENIED".to_owned(),
            message: "DesignActionRun candidate is not in the requested project".to_owned(),
        });
    }
    let session: Option<(String, String)> = transaction
        .query_row(
            "SELECT project_id, candidate_id FROM agentic_design_sessions WHERE session_id = ?1",
            params![session_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((session_project, session_candidate)) = session else {
        return Err(StoreError::Contract {
            code: "DESIGN_ACTION_RUN_SESSION_NOT_FOUND".to_owned(),
            message: "DesignActionRun requires a persisted DesignSession".to_owned(),
        });
    };
    if session_project != project_id || session_candidate != candidate_id {
        return Err(StoreError::Contract {
            code: "DESIGN_ACTION_RUN_BINDING_MISMATCH".to_owned(),
            message: "DesignActionRun session, project and candidate bindings differ".to_owned(),
        });
    }
    if let Some(checkpoint_id) = object.get("checkpoint_id").and_then(Value::as_str) {
        let checkpoint_hash = object
            .get("checkpoint_hash")
            .and_then(Value::as_str)
            .ok_or_else(|| StoreError::Contract {
                code: "DESIGN_ACTION_RUN_CHECKPOINT_MISMATCH".to_owned(),
                message: "DesignActionRun checkpoint hash is required".to_owned(),
            })?;
        let checkpoint: Option<(String, String, String, String)> = transaction
            .query_row(
                "SELECT session_id, project_id, candidate_id, canonical_sha256 FROM agentic_design_checkpoints WHERE checkpoint_id = ?1",
                params![checkpoint_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .optional()?;
        if checkpoint.as_ref().map(|value| {
            value.0 != session_id
                || value.1 != project_id
                || value.2 != candidate_id
                || value.3 != checkpoint_hash
        }) != Some(false)
        {
            return Err(StoreError::Contract {
                code: "DESIGN_ACTION_RUN_CHECKPOINT_MISMATCH".to_owned(),
                message: "DesignActionRun checkpoint pointer is unavailable or out of scope"
                    .to_owned(),
            });
        }
    }
    Ok(())
}

fn validate_agentic_metadata(value: &Value, depth: usize) -> Result<(), StoreError> {
    if depth > 12 {
        return Err(StoreError::InvalidData(
            "agentic metadata nesting exceeds the bounded limit".to_owned(),
        ));
    }
    match value {
        Value::Null | Value::Bool(_) | Value::Number(_) => Ok(()),
        Value::String(text) => {
            if text.len() > 4096
                || text.starts_with('/')
                || text.starts_with('\\')
                || text.starts_with("file:")
                || text.starts_with("data:")
                || text.starts_with("http:")
                || text.starts_with("https:")
                || text.contains("-----BEGIN")
            {
                return Err(StoreError::InvalidData(
                    "agentic metadata contains a path, URL, secret or oversized string".to_owned(),
                ));
            }
            Ok(())
        }
        Value::Array(values) => {
            if values.len() > 256 {
                return Err(StoreError::InvalidData(
                    "agentic metadata array exceeds the bounded limit".to_owned(),
                ));
            }
            for value in values {
                validate_agentic_metadata(value, depth + 1)?;
            }
            Ok(())
        }
        Value::Object(values) => {
            for (key, value) in values {
                let lowered = key.to_ascii_lowercase();
                let forbidden_field = lowered.split(['_', '-', '.']).any(|part| {
                    matches!(
                        part,
                        "path"
                            | "url"
                            | "secret"
                            | "token"
                            | "password"
                            | "script"
                            | "command"
                            | "shell"
                            | "bytes"
                            | "base64"
                            | "prompt"
                    )
                }) || lowered.contains("api_key")
                    || lowered.contains("apikey");
                if forbidden_field {
                    return Err(StoreError::InvalidData(format!(
                        "agentic metadata contains a forbidden field: {key}"
                    )));
                }
                validate_agentic_metadata(value, depth + 1)?;
            }
            Ok(())
        }
    }
}

fn validate_hash_pair(
    id: &Option<String>,
    hash: &Option<String>,
    label: &str,
) -> Result<(), StoreError> {
    match (id, hash) {
        (None, None) => Ok(()),
        (Some(id), Some(hash)) if is_opaque_id(id) && is_sha256(hash) => Ok(()),
        _ => Err(StoreError::InvalidData(format!(
            "agentic {label} id/hash pair is malformed"
        ))),
    }
}

fn validate_agentic_session(session: &AgenticSessionRecord) -> Result<(), StoreError> {
    if session.schema_version != "DesignSession@1"
        || !is_opaque_id(&session.session_id)
        || !is_opaque_id(&session.project_id)
        || !is_opaque_id(&session.candidate_id)
        || session.revision < 0
        || !is_sha256(&session.candidate_state_sha256)
        || !is_opaque_id(&session.design_spec_id)
        || !is_sha256(&session.design_spec_sha256)
        || !is_opaque_id(&session.reference_canvas_id)
        || !is_sha256(&session.reference_canvas_sha256)
        || !is_opaque_id(&session.reference_id)
        || !is_sha256(&session.reference_sha256)
        || !is_sha256(&session.camera_hash)
        || !is_sha256(&session.evidence_sha256)
        || !is_sha256(&session.observation_sha256)
        || !is_opaque_id(&session.current_stage)
        || !is_opaque_id(&session.status)
        || !is_opaque_id(&session.quality_status)
        || session
            .object_sha256
            .as_deref()
            .is_none_or(|hash| !is_sha256(hash))
        || !is_sha256(&session.canonical_sha256)
        || session.created_at.is_empty()
        || session.updated_at.is_empty()
        || !session.stage_gate.is_object()
        || !session.rollback.is_object()
        || session.next_actions.is_empty()
        || session.next_actions.len() > 8
        || session.checkpoint_ids.len() > 128
        || session.checkpoint_ids.iter().any(|id| !is_opaque_id(id))
        || session
            .checkpoint_ids
            .windows(2)
            .any(|pair| pair[0] == pair[1])
    {
        return Err(StoreError::InvalidData(
            "agentic DesignSession record is malformed".to_owned(),
        ));
    }
    validate_hash_pair(
        &session.current_version_id,
        &session.current_version_sha256,
        "current version",
    )?;
    validate_hash_pair(
        &session.current_checkpoint_id,
        &session.current_checkpoint_sha256,
        "current checkpoint",
    )?;
    if let Some(checkpoint_id) = session.current_checkpoint_id.as_deref() {
        if !session.checkpoint_ids.iter().any(|id| id == checkpoint_id) {
            return Err(StoreError::InvalidData(
                "current checkpoint is absent from session history".to_owned(),
            ));
        }
    }
    validate_agentic_metadata(
        &serde_json::to_value(session)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
        0,
    )
}

fn validate_agentic_checkpoint(checkpoint: &AgenticCheckpointRecord) -> Result<(), StoreError> {
    if checkpoint.schema_version != "DesignCheckpoint@1"
        || !is_opaque_id(&checkpoint.checkpoint_id)
        || !is_opaque_id(&checkpoint.session_id)
        || !is_opaque_id(&checkpoint.project_id)
        || !is_opaque_id(&checkpoint.candidate_id)
        || checkpoint.revision < 0
        || !is_opaque_id(&checkpoint.stage)
        || !is_opaque_id(&checkpoint.checkpoint_type)
        || !is_sha256(&checkpoint.candidate_state_sha256)
        || !is_sha256(&checkpoint.artifact_sha256)
        || !is_opaque_id(&checkpoint.reference_id)
        || !is_sha256(&checkpoint.reference_sha256)
        || !is_sha256(&checkpoint.camera_hash)
        || !is_sha256(&checkpoint.input_sha256)
        || !is_sha256(&checkpoint.evidence_sha256)
        || !is_sha256(&checkpoint.observation_sha256)
        || !is_sha256(&checkpoint.canonical_sha256)
        || checkpoint
            .object_sha256
            .as_deref()
            .is_none_or(|hash| !is_sha256(hash))
        || !checkpoint.immutable
        || checkpoint.runtime_write
        || !checkpoint.stage_gate.is_object()
        || !checkpoint.rollback.is_object()
        || checkpoint.created_at.is_empty()
        || checkpoint.observed.iter().any(|value| !is_opaque_id(value))
        || checkpoint.inferred.iter().any(|value| !is_opaque_id(value))
        || checkpoint.unknown.iter().any(|value| !is_opaque_id(value))
        || checkpoint
            .failed_gates
            .iter()
            .any(|value| !is_opaque_id(value))
        || checkpoint
            .allowed_actions
            .iter()
            .any(|value| !is_opaque_id(value))
        || checkpoint
            .locked_actions
            .iter()
            .any(|value| !is_opaque_id(value))
    {
        return Err(StoreError::InvalidData(
            "agentic DesignCheckpoint record is malformed".to_owned(),
        ));
    }
    validate_hash_pair(
        &checkpoint.version_id,
        &checkpoint.version_sha256,
        "checkpoint version",
    )?;
    validate_hash_pair(
        &checkpoint.parent_checkpoint_id,
        &checkpoint.parent_checkpoint_sha256,
        "checkpoint parent",
    )?;
    validate_agentic_metadata(
        &serde_json::to_value(checkpoint)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
        0,
    )
}

fn validate_agentic_action_run(run: &AgenticActionRunRecord) -> Result<(), StoreError> {
    if run.schema_version != "AgenticActionRun@1"
        || !is_opaque_id(&run.run_id)
        || !is_opaque_id(&run.session_id)
        || !is_opaque_id(&run.project_id)
        || !is_opaque_id(&run.candidate_id)
        || !is_sha256(&run.input_sha256)
        || !matches!(
            run.status.as_str(),
            "queued"
                | "running"
                | "waiting_for_input"
                | "succeeded"
                | "completed"
                | "failed"
                | "cancelled"
                | "blocked"
        )
        || (run.completed_stage != "none" && !is_opaque_id(&run.completed_stage))
        || !run.immutable
        || run
            .object_sha256
            .as_deref()
            .is_some_and(|hash| !is_sha256(hash))
        || !is_sha256(&run.canonical_sha256)
        || run.created_at.is_empty()
        || run.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "agentic action run record is malformed".to_owned(),
        ));
    }
    validate_hash_pair(
        &run.checkpoint_id,
        &run.checkpoint_sha256,
        "action run checkpoint",
    )?;
    validate_agentic_action_stage_results(&run.stage_results)?;
    let value =
        serde_json::to_value(run).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    validate_agentic_metadata(&value, 0)?;
    validate_agentic_action_run_text(&value, 0)?;
    let expected_canonical_sha256 = agentic_action_run_canonical_sha256(run)?;
    if run.canonical_sha256 != expected_canonical_sha256 {
        return Err(StoreError::Contract {
            code: "AGENTIC_ACTION_RUN_CANONICAL_HASH_MISMATCH".to_owned(),
            message: "action run canonical hash does not match its immutable fields".to_owned(),
        });
    }
    Ok(())
}

fn validate_design_action_run_value(value: &Value) -> Result<(), StoreError> {
    const REQUIRED: &[&str] = &[
        "schema_version",
        "run_id",
        "session_id",
        "project_id",
        "candidate_id",
        "reference_id",
        "reference_sha256",
        "camera_hash",
        "input_sha256",
        "observation_sha256",
        "action",
        "requested_stage",
        "status",
        "completed_stage",
        "stage_results",
        "quality_status",
        "failed_gates",
        "allowed_actions",
        "locked_actions",
        "checkpoint_id",
        "checkpoint_hash",
        "optimization_job_id",
        "optimization_intent_sha256",
        "runtime_write",
        "persistent_user_data_touched",
        "canonical_sha256",
    ];
    let object = value
        .as_object()
        .ok_or_else(|| StoreError::InvalidData("DesignActionRun must be an object".to_owned()))?;
    if object
        .keys()
        .any(|key| !REQUIRED.contains(&key.as_str()) && key != "proposal")
        || REQUIRED.iter().any(|key| !object.contains_key(*key))
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun has missing or unknown fields".to_owned(),
        ));
    }
    if object.get("schema_version").and_then(Value::as_str) != Some("DesignActionRun@1") {
        return Err(StoreError::InvalidData(
            "DesignActionRun schema version is unsupported".to_owned(),
        ));
    }
    for key in [
        "run_id",
        "session_id",
        "project_id",
        "candidate_id",
        "reference_id",
    ] {
        if object
            .get(key)
            .and_then(Value::as_str)
            .is_none_or(|value| !is_opaque_id(value))
        {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun {key} is malformed"
            )));
        }
    }
    for key in [
        "reference_sha256",
        "camera_hash",
        "input_sha256",
        "observation_sha256",
        "canonical_sha256",
    ] {
        if object
            .get(key)
            .and_then(Value::as_str)
            .is_none_or(|value| !is_sha256(value))
        {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun {key} is not a SHA-256"
            )));
        }
    }
    if object.get("runtime_write") != Some(&Value::Bool(false))
        || object.get("persistent_user_data_touched") != Some(&Value::Bool(false))
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun must remain Runtime-write and persistent-data false".to_owned(),
        ));
    }
    if object
        .get("requested_stage")
        .and_then(Value::as_str)
        .is_none_or(|stage| {
            !matches!(
                stage,
                "reference-canvas"
                    | "primary-form"
                    | "secondary-structure"
                    | "tertiary-detail"
                    | "uv-pbr"
                    | "final-review"
            )
        })
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun requested_stage is unsupported".to_owned(),
        ));
    }
    if object
        .get("status")
        .and_then(Value::as_str)
        .is_none_or(|status| {
            !matches!(
                status,
                "prepared" | "running" | "completed" | "failed" | "blocked"
            )
        })
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun status is unsupported".to_owned(),
        ));
    }
    if let Some(stage) = object.get("completed_stage").and_then(Value::as_str) {
        if !matches!(
            stage,
            "prepare" | "compile" | "readback" | "render" | "evaluate"
        ) {
            return Err(StoreError::InvalidData(
                "DesignActionRun completed_stage is unsupported".to_owned(),
            ));
        }
    } else if !object.get("completed_stage").is_some_and(Value::is_null) {
        return Err(StoreError::InvalidData(
            "DesignActionRun completed_stage must be null or a pipeline stage".to_owned(),
        ));
    }
    if object
        .get("quality_status")
        .and_then(Value::as_str)
        .is_none_or(|status| {
            !matches!(
                status,
                "PARTIAL_VISIBLE_VIEW_PASS"
                    | "QUALITY_TARGET_NOT_MET"
                    | "BLOCKED_REFERENCE_COVERAGE"
                    | "not-run"
                    | "unknown"
            )
        })
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun quality_status is unsupported".to_owned(),
        ));
    }
    validate_design_action_array(object, "failed_gates", true)?;
    validate_design_action_array(object, "allowed_actions", true)?;
    validate_design_action_array(object, "locked_actions", true)?;
    let allowed = object["allowed_actions"]
        .as_array()
        .expect("validated action array");
    let locked = object["locked_actions"]
        .as_array()
        .expect("validated action array");
    if allowed
        .iter()
        .any(|value| matches!(value.as_str(), Some("confirm" | "export")))
        || !locked.iter().any(|value| value.as_str() == Some("confirm"))
        || !locked.iter().any(|value| value.as_str() == Some("export"))
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun approval locks are not fail-closed".to_owned(),
        ));
    }
    let checkpoint_id = object.get("checkpoint_id").expect("required checkpoint_id");
    let checkpoint_hash = object
        .get("checkpoint_hash")
        .expect("required checkpoint_hash");
    if checkpoint_id.is_null() != checkpoint_hash.is_null()
        || checkpoint_hash
            .as_str()
            .is_some_and(|value| !is_sha256(value))
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun checkpoint id/hash must be paired".to_owned(),
        ));
    }
    let optimization_job_id = object
        .get("optimization_job_id")
        .expect("required optimization_job_id");
    let optimization_intent_sha256 = object
        .get("optimization_intent_sha256")
        .expect("required optimization_intent_sha256");
    if optimization_job_id.is_null() != optimization_intent_sha256.is_null()
        || (!optimization_job_id.is_null()
            && !optimization_job_id.as_str().is_some_and(is_opaque_id))
        || (!optimization_intent_sha256.is_null()
            && !optimization_intent_sha256.as_str().is_some_and(is_sha256))
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun optimization job/id hash must be paired".to_owned(),
        ));
    }
    let action = object
        .get("action")
        .and_then(Value::as_object)
        .ok_or_else(|| StoreError::InvalidData("DesignActionRun action is missing".to_owned()))?;
    if action
        .get("action_id")
        .and_then(Value::as_str)
        .is_none_or(|value| !is_opaque_id(value))
        || action.get("bounded") != Some(&Value::Bool(true))
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun action is not bounded".to_owned(),
        ));
    }
    let stages = object
        .get("stage_results")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            StoreError::InvalidData("DesignActionRun stage_results is missing".to_owned())
        })?;
    const PIPELINE: &[&str] = &["prepare", "compile", "readback", "render", "evaluate"];
    if stages.len() != PIPELINE.len() || PIPELINE.iter().any(|stage| !stages.contains_key(*stage)) {
        return Err(StoreError::InvalidData(
            "DesignActionRun stage_results must contain exactly five pipeline stages".to_owned(),
        ));
    }
    for stage in PIPELINE {
        let result = stages[*stage].as_object().ok_or_else(|| {
            StoreError::InvalidData(format!("DesignActionRun {stage} result is malformed"))
        })?;
        if result
            .keys()
            .any(|key| !matches!(key.as_str(), "status" | "hash" | "reason"))
            || !result.contains_key("status")
            || !result.contains_key("hash")
            || !result.contains_key("reason")
        {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun {stage} result fields are invalid"
            )));
        }
        let status = result["status"].as_str().ok_or_else(|| {
            StoreError::InvalidData(format!("DesignActionRun {stage} status is missing"))
        })?;
        if !matches!(
            status,
            "not-run" | "running" | "completed" | "failed" | "blocked"
        ) {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun {stage} status is unsupported"
            )));
        }
        if result["hash"].as_str().is_some_and(|hash| !is_sha256(hash))
            || (!result["hash"].is_null() && result["hash"].as_str().is_none())
        {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun {stage} hash is malformed"
            )));
        }
        let reason = result["reason"].as_str();
        if matches!(status, "not-run" | "running" | "failed" | "blocked")
            && reason.is_none_or(str::is_empty)
        {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun {stage} reason is required"
            )));
        }
        if status == "completed" && result["hash"].is_null() {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun {stage} completed result needs a hash"
            )));
        }
        if let Some(reason) = reason {
            if reason.len() > 512 || reason.contains("://") || reason.starts_with('/') {
                return Err(StoreError::InvalidData(format!(
                    "DesignActionRun {stage} reason contains unsafe text"
                )));
            }
        } else if !result["reason"].is_null() {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun {stage} reason must be text or null"
            )));
        }
    }
    validate_agentic_metadata(value, 0)?;
    validate_agentic_action_run_text(value, 0)?;
    if let Some(proposal) = object.get("proposal") {
        validate_design_action_proposal_value(proposal)?;
    }
    let mut canonical = value.clone();
    canonical["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&canonical) != object["canonical_sha256"].as_str().unwrap_or_default() {
        return Err(StoreError::Contract {
            code: "DESIGN_ACTION_RUN_CANONICAL_HASH_MISMATCH".to_owned(),
            message: "DesignActionRun canonical hash does not match immutable fields".to_owned(),
        });
    }
    Ok(())
}

fn validate_design_action_proposal_value(value: &Value) -> Result<(), StoreError> {
    const REQUIRED: &[&str] = &[
        "intent_sha256",
        "intent_object_sha256",
        "candidate_id",
        "candidate_state_sha256",
        "artifact_sha256",
        "geometry_program_sha256",
        "render_set_sha256",
        "comparison_report_sha256",
        "quality_report_sha256",
        "visual_status",
        "baseline_score",
        "proposal_score",
        "strict_improvement",
        "non_regressing",
        "promotion",
        "confirm_allowed",
    ];
    let object = value.as_object().ok_or_else(|| {
        StoreError::InvalidData("DesignActionRun proposal must be an object".to_owned())
    })?;
    if object
        .keys()
        .any(|key| !REQUIRED.contains(&key.as_str()) && key != "cross_view_evidence_sha256")
        || REQUIRED.iter().any(|key| !object.contains_key(*key))
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun proposal has missing or unknown fields".to_owned(),
        ));
    }
    for key in ["candidate_id"] {
        if object
            .get(key)
            .and_then(Value::as_str)
            .is_none_or(|value| !is_opaque_id(value))
        {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun proposal {key} is malformed"
            )));
        }
    }
    for key in [
        "intent_sha256",
        "intent_object_sha256",
        "candidate_state_sha256",
        "artifact_sha256",
        "geometry_program_sha256",
        "render_set_sha256",
        "comparison_report_sha256",
        "quality_report_sha256",
    ] {
        if object
            .get(key)
            .and_then(Value::as_str)
            .is_none_or(|value| !is_sha256(value))
        {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun proposal {key} is not a SHA-256"
            )));
        }
    }
    if !matches!(
        object.get("visual_status").and_then(Value::as_str),
        Some("PARTIAL_VISIBLE_VIEW_PASS" | "QUALITY_TARGET_NOT_MET" | "BLOCKED_REFERENCE_COVERAGE")
    ) || !matches!(
        object.get("promotion").and_then(Value::as_str),
        Some("reviewable" | "not-improved" | "rejected-regression")
    ) || object.get("confirm_allowed") != Some(&Value::Bool(false))
    {
        return Err(StoreError::InvalidData(
            "DesignActionRun proposal gate fields are invalid".to_owned(),
        ));
    }
    for key in ["baseline_score", "proposal_score"] {
        let score = object.get(key).and_then(Value::as_f64).ok_or_else(|| {
            StoreError::InvalidData(format!("DesignActionRun proposal {key} is invalid"))
        })?;
        if !score.is_finite() || !(0.0..=8.0).contains(&score) {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun proposal {key} is out of bounds"
            )));
        }
    }
    for key in ["strict_improvement", "non_regressing"] {
        if !object.get(key).is_some_and(Value::is_boolean) {
            return Err(StoreError::InvalidData(format!(
                "DesignActionRun proposal {key} must be boolean"
            )));
        }
    }
    if let Some(value) = object.get("cross_view_evidence_sha256") {
        if !value.is_null() && value.as_str().is_none_or(|value| !is_sha256(value)) {
            return Err(StoreError::InvalidData(
                "DesignActionRun proposal cross_view_evidence_sha256 is invalid".to_owned(),
            ));
        }
    }
    Ok(())
}

fn validate_design_action_array(
    object: &serde_json::Map<String, Value>,
    key: &str,
    non_empty: bool,
) -> Result<(), StoreError> {
    let values = object
        .get(key)
        .and_then(Value::as_array)
        .ok_or_else(|| StoreError::InvalidData(format!("DesignActionRun {key} is not an array")))?;
    if non_empty && values.is_empty() && key == "locked_actions" {
        return Err(StoreError::InvalidData(format!(
            "DesignActionRun {key} is empty"
        )));
    }
    if values.len() > 24
        || values.iter().any(|value| {
            value
                .as_str()
                .is_none_or(|value| !is_opaque_id(value) || value.len() > 64)
        })
    {
        return Err(StoreError::InvalidData(format!(
            "DesignActionRun {key} contains an invalid capability"
        )));
    }
    Ok(())
}

fn validate_agentic_action_stage_results(value: &Value) -> Result<(), StoreError> {
    match value {
        Value::Object(stages) => {
            if stages.len() > 32 {
                return Err(StoreError::InvalidData(
                    "agentic action run has too many stage results".to_owned(),
                ));
            }
            for (stage, result) in stages {
                if !is_opaque_id(stage) {
                    return Err(StoreError::InvalidData(
                        "agentic action run stage id is malformed".to_owned(),
                    ));
                }
                validate_agentic_action_stage_result(result, false)?;
            }
            Ok(())
        }
        Value::Array(results) => {
            if results.len() > 32 {
                return Err(StoreError::InvalidData(
                    "agentic action run has too many stage results".to_owned(),
                ));
            }
            let mut stage_ids = std::collections::BTreeSet::new();
            for result in results {
                let stage = result
                    .as_object()
                    .and_then(|object| object.get("stage"))
                    .and_then(Value::as_str)
                    .ok_or_else(|| {
                        StoreError::InvalidData(
                            "array action stage result must include a stage id".to_owned(),
                        )
                    })?;
                if !stage_ids.insert(stage.to_owned()) {
                    return Err(StoreError::InvalidData(
                        "agentic action stage results contain a duplicate stage".to_owned(),
                    ));
                }
                validate_agentic_action_stage_result(result, true)?;
            }
            Ok(())
        }
        _ => Err(StoreError::InvalidData(
            "agentic action stage_results must be an object or array".to_owned(),
        )),
    }
}

fn validate_agentic_action_stage_result(
    value: &Value,
    requires_stage: bool,
) -> Result<(), StoreError> {
    const ALLOWED_FIELDS: &[&str] = &[
        "stage",
        "status",
        "result_sha256",
        "output_sha256",
        "summary_sha256",
        "error_code",
        "checkpoint_id",
        "checkpoint_sha256",
        "canonical_sha256",
        "completed_at",
    ];
    let object = value.as_object().ok_or_else(|| {
        StoreError::InvalidData("agentic action stage result must be an object".to_owned())
    })?;
    for key in object.keys() {
        if !ALLOWED_FIELDS.contains(&key.as_str()) {
            return Err(StoreError::InvalidData(format!(
                "unknown agentic action stage result field: {key}"
            )));
        }
    }
    if requires_stage {
        let stage = object
            .get("stage")
            .and_then(Value::as_str)
            .filter(|value| is_opaque_id(value))
            .ok_or_else(|| {
                StoreError::InvalidData("agentic action stage id is malformed".to_owned())
            })?;
        if stage.is_empty() {
            return Err(StoreError::InvalidData(
                "agentic action stage id is empty".to_owned(),
            ));
        }
    } else if object.contains_key("stage") {
        return Err(StoreError::InvalidData(
            "object action stage result must not repeat its stage id".to_owned(),
        ));
    }
    let status = object
        .get("status")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            StoreError::InvalidData("agentic action stage result status is required".to_owned())
        })?;
    if !matches!(
        status,
        "queued"
            | "running"
            | "waiting_for_input"
            | "succeeded"
            | "completed"
            | "failed"
            | "cancelled"
            | "blocked"
            | "skipped"
    ) {
        return Err(StoreError::InvalidData(
            "agentic action stage result status is unsupported".to_owned(),
        ));
    }
    for field in [
        "result_sha256",
        "output_sha256",
        "summary_sha256",
        "checkpoint_sha256",
        "canonical_sha256",
    ] {
        if let Some(value) = object.get(field) {
            if value.as_str().is_none_or(|hash| !is_sha256(hash)) {
                return Err(StoreError::InvalidData(format!(
                    "agentic action stage result field {field} is not a SHA-256"
                )));
            }
        }
    }
    if let Some(value) = object.get("checkpoint_id") {
        if value.as_str().is_none_or(|id| !is_opaque_id(id)) {
            return Err(StoreError::InvalidData(
                "agentic action stage checkpoint id is malformed".to_owned(),
            ));
        }
        if object.get("checkpoint_sha256").is_none() {
            return Err(StoreError::InvalidData(
                "agentic action stage checkpoint hash is required with its id".to_owned(),
            ));
        }
    } else if object.contains_key("checkpoint_sha256") {
        return Err(StoreError::InvalidData(
            "agentic action stage checkpoint id is required with its hash".to_owned(),
        ));
    }
    if let Some(value) = object.get("error_code") {
        if value.as_str().is_none_or(|code| !is_opaque_id(code)) {
            return Err(StoreError::InvalidData(
                "agentic action stage error code is malformed".to_owned(),
            ));
        }
    }
    if let Some(value) = object.get("completed_at") {
        if value
            .as_str()
            .is_none_or(|timestamp| timestamp.is_empty() || timestamp.len() > 64)
        {
            return Err(StoreError::InvalidData(
                "agentic action stage completed_at is malformed".to_owned(),
            ));
        }
    }
    Ok(())
}

fn validate_agentic_action_run_text(value: &Value, depth: usize) -> Result<(), StoreError> {
    if depth > 12 {
        return Err(StoreError::InvalidData(
            "agentic action metadata nesting exceeds the bounded limit".to_owned(),
        ));
    }
    match value {
        Value::String(text) => {
            let lowered = text.to_ascii_lowercase();
            if lowered.contains("://")
                || lowered.starts_with("javascript:")
                || lowered.starts_with("ftp:")
                || lowered.starts_with("bearer ")
                || lowered.starts_with("sk-")
                || lowered.contains("-----begin")
            {
                return Err(StoreError::InvalidData(
                    "agentic action metadata contains a URL, secret or executable reference"
                        .to_owned(),
                ));
            }
            Ok(())
        }
        Value::Array(values) => {
            for value in values {
                validate_agentic_action_run_text(value, depth + 1)?;
            }
            Ok(())
        }
        Value::Object(values) => {
            for value in values.values() {
                validate_agentic_action_run_text(value, depth + 1)?;
            }
            Ok(())
        }
        Value::Null | Value::Bool(_) | Value::Number(_) => Ok(()),
    }
}

fn validate_geometry_candidate_evidence(
    evidence: &GeometryCandidateEvidenceRecord,
) -> Result<(), StoreError> {
    if evidence.schema_version != "GeometryCandidateEvidence@1"
        || !is_opaque_id(&evidence.candidate_id)
        || !is_opaque_id(&evidence.project_id)
        || !is_opaque_id(&evidence.quality_report_id)
        || evidence.created_at.is_empty()
        || evidence.created_at.len() > 64
        || !is_sha256(&evidence.geometry_program_sha256)
        || !is_sha256(&evidence.geometry_program_object_sha256)
        || !is_sha256(&evidence.operator_catalog_sha256)
        || !is_sha256(&evidence.readback_config_sha256)
        || !is_sha256(&evidence.artifact_object_sha256)
        || !is_sha256(&evidence.artifact_readback_object_sha256)
        || !is_sha256(&evidence.quality_report_object_sha256)
        || !is_sha256(&evidence.canonical_sha256)
    {
        return Err(StoreError::InvalidData(
            "geometry candidate evidence is malformed".to_owned(),
        ));
    }
    match (&evidence.reference_id, &evidence.reference_sha256) {
        (None, None) => Ok(()),
        (Some(reference_id), Some(reference_sha256))
            if is_opaque_id(reference_id) && is_sha256(reference_sha256) =>
        {
            Ok(())
        }
        _ => Err(StoreError::InvalidData(
            "geometry candidate reference evidence is malformed".to_owned(),
        )),
    }
}

fn canonical_json_string<T: Serialize>(value: &T) -> Result<String, StoreError> {
    let value =
        serde_json::to_value(value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let bytes =
        canonical_json_bytes(&value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    String::from_utf8(bytes).map_err(|error| StoreError::InvalidData(error.to_string()))
}

fn candidate_topology_quality_payload_json(
    quality: &CandidateTopologyQualityRecord,
) -> Result<String, StoreError> {
    canonical_json_string(quality)
}

fn same_candidate_topology_quality(
    left: &CandidateTopologyQualityRecord,
    right: &CandidateTopologyQualityRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

fn validate_candidate_topology_quality(
    quality: &CandidateTopologyQualityRecord,
) -> Result<(), StoreError> {
    let mut canonical = quality.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let all_gate_passed = quality.hard_gate.finite_geometry
        && quality.hard_gate.valid_indices
        && quality.hard_gate.non_degenerate_triangles
        && quality.hard_gate.boundary_policy
        && quality.hard_gate.manifold
        && quality.hard_gate.orientation
        && quality.hard_gate.counts_within_budget
        && quality.hard_gate.triangle_aspect_ratio
        && quality.hard_gate.vertex_valence
        && quality.hard_gate.normal_integrity
        && quality.hard_gate.uv_integrity
        && quality.hard_gate.tangent_integrity
        && quality.hard_gate.semantic_coverage;
    let threshold_valid = quality.thresholds.max_triangle_aspect_ratio.is_finite()
        && quality.thresholds.max_triangle_aspect_ratio > 0.0
        && quality.thresholds.max_triangle_aspect_ratio <= 1_000_000.0
        && quality.thresholds.max_vertex_valence > 0
        && quality.thresholds.max_vertex_valence <= 250_000
        && quality.thresholds.min_triangle_area_m2.is_finite()
        && quality.thresholds.min_triangle_area_m2 >= 0.0
        && quality.thresholds.min_triangle_area_m2 <= 1_000_000.0
        && (0.0..=1.0).contains(&quality.thresholds.min_semantic_part_coverage)
        && (0.0..=1.0).contains(&quality.thresholds.min_semantic_material_zone_coverage)
        && (0.0..=1.0).contains(&quality.thresholds.min_semantic_source_node_coverage);
    let metric_valid = quality.metrics.part_count > 0
        && quality.metrics.part_count <= 512
        && quality.metrics.solid_part_count <= quality.metrics.part_count
        && quality.metrics.non_solid_part_count <= quality.metrics.part_count
        && quality.metrics.solid_part_count + quality.metrics.non_solid_part_count
            == quality.metrics.part_count
        && quality.metrics.triangle_count > 0
        && quality.metrics.triangle_count <= 250_000
        && quality.metrics.vertex_count > 0
        && quality.metrics.vertex_count <= 250_000
        && quality.metrics.edge_count > 0
        && quality.metrics.edge_count <= 500_000
        && quality.metrics.min_triangle_area_m2.is_finite()
        && quality.metrics.min_triangle_area_m2 >= 0.0
        && quality.metrics.min_triangle_area_m2 <= 1_000_000.0
        && quality.metrics.max_triangle_aspect_ratio.is_finite()
        && quality.metrics.max_triangle_aspect_ratio >= 0.0
        && quality.metrics.max_triangle_aspect_ratio <= 1_000_000.0
        && quality.metrics.max_vertex_valence <= 250_000
        && quality.metrics.semantic_part_coverage.is_finite()
        && quality.metrics.semantic_material_zone_coverage.is_finite()
        && quality.metrics.semantic_source_node_coverage.is_finite()
        && (0.0..=1.0).contains(&quality.metrics.semantic_part_coverage)
        && (0.0..=1.0).contains(&quality.metrics.semantic_material_zone_coverage)
        && (0.0..=1.0).contains(&quality.metrics.semantic_source_node_coverage)
        && quality.metrics.invalid_index_count <= 1_000_000
        && quality.metrics.non_finite_count <= 1_000_000
        && quality.metrics.degenerate_triangle_count <= 1_000_000
        && quality.metrics.boundary_edge_count <= 1_000_000
        && quality.metrics.non_manifold_edge_count <= 1_000_000
        && quality.metrics.orientation_conflict_count <= 1_000_000
        && quality.metrics.winding_error_count <= 1_000_000
        && quality.metrics.solid_boundary_violation_count <= 1_000_000
        && quality.metrics.normal_non_finite_count <= 1_000_000
        && quality.metrics.normal_non_unit_count <= 1_000_000
        && quality.metrics.normal_alignment_error_count <= 1_000_000
        && quality.metrics.uv_non_finite_count <= 1_000_000
        && quality.metrics.uv_degenerate_triangle_count <= 1_000_000
        && quality.metrics.tangent_non_finite_count <= 1_000_000
        && quality.metrics.tangent_orthogonality_error_count <= 1_000_000
        && quality.metrics.tangent_handedness_error_count <= 1_000_000;
    let ids_valid = !quality.part_ids.is_empty()
        && quality.part_ids.len() <= 512
        && quality.part_ids.iter().all(|id| is_opaque_id(id))
        && quality.part_ids.iter().collect::<HashSet<_>>().len() == quality.part_ids.len()
        && quality.part_topology_snapshot_sha256s.len() == quality.part_ids.len()
        && quality
            .part_topology_snapshot_sha256s
            .iter()
            .all(|hash| is_sha256(hash))
        && quality
            .part_topology_snapshot_sha256s
            .iter()
            .collect::<HashSet<_>>()
            .len()
            == quality.part_topology_snapshot_sha256s.len()
        && quality.part_authoring_topology_sha256s.len() == quality.part_ids.len()
        && quality
            .part_authoring_topology_sha256s
            .iter()
            .all(|hash| hash.as_deref().is_none_or(is_sha256));
    let authoring_valid = match quality.authoring_topology_status.as_str() {
        "complete" => quality
            .part_authoring_topology_sha256s
            .iter()
            .all(Option::is_some),
        "not-available" => quality
            .part_authoring_topology_sha256s
            .iter()
            .all(Option::is_none),
        "partial" => true,
        _ => false,
    };
    if quality.schema_version != "CandidateTopologyQuality@1"
        || !is_opaque_id(&quality.topology_quality_id)
        || !is_opaque_id(&quality.project_id)
        || !is_opaque_id(&quality.candidate_id)
        || !is_sha256(&quality.candidate_state_sha256)
        || !is_opaque_id(&quality.artifact_id)
        || !is_sha256(&quality.artifact_sha256)
        || !is_sha256(&quality.artifact_readback_sha256)
        || !is_sha256(&quality.artifact_readback_object_sha256)
        || !is_sha256(&quality.geometry_candidate_evidence_sha256)
        || !is_sha256(&quality.geometry_program_sha256)
        || !is_sha256(&quality.geometry_program_object_sha256)
        || !is_sha256(&quality.operator_catalog_sha256)
        || !is_sha256(&quality.readback_config_sha256)
        || !is_sha256(&quality.part_inventory_sha256)
        || !is_sha256(&quality.topology_quality_policy_sha256)
        || !is_sha256(&quality.request_sha256)
        || !is_sha256(&quality.input_sha256)
        || quality.topology_quality_policy != CANDIDATE_TOPOLOGY_QUALITY_POLICY
        || quality.from_stage != "gray-model"
        || quality.to_stage != "topology"
        || !matches!(
            quality.topology_status.as_str(),
            "closed_manifold" | "open_surface" | "non_manifold"
        )
        || !matches!(quality.validator_status.as_str(), "passed" | "failed")
        || (quality.hard_gate_passed && (!all_gate_passed || quality.validator_status != "passed"))
        || (quality.validator_status == "passed" && !quality.hard_gate_passed)
        || quality.edge_flow_status != "NOT_PROVEN"
        || quality.artistic_quality_status != "NOT_PROVEN"
        || quality.visual_quality_status != "NOT_PROVEN"
        || quality.materialization_status != CANDIDATE_TOPOLOGY_QUALITY_STATUS
        || quality.quality_status != "structural_only"
        || !quality.runtime_write_performed
        || quality.candidate_confirmed
        || quality.version_created
        || quality.export_performed
        || quality.metrics.part_count as usize != quality.part_ids.len()
        || quality.metrics.solid_boundary_violation_count > 0
            && quality.hard_gate.boundary_policy
            && quality.hard_gate_passed
        || !threshold_valid
        || !metric_valid
        || !ids_valid
        || !authoring_valid
        || quality.canonical_sha256 != expected_canonical
        || quality.created_at.is_empty()
        || quality.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "candidate topology quality record is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn validate_candidate_topology_quality_report_bytes(
    bytes: &[u8],
    quality: &CandidateTopologyQualityRecord,
) -> Result<(), StoreError> {
    if bytes.is_empty() || bytes.len() as u64 > MAX_CANDIDATE_TOPOLOGY_QUALITY_REPORT_BYTES {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_REPORT_BUDGET_EXCEEDED".to_owned(),
            message: "candidate topology quality report exceeds the 1 MiB bound".to_owned(),
        });
    }
    let report: CandidateTopologyQualityRecord =
        serde_json::from_slice(bytes).map_err(|error| StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_REPORT_INVALID".to_owned(),
            message: format!("candidate topology quality report is not a valid record: {error}"),
        })?;
    validate_candidate_topology_quality(&report)?;
    if !same_candidate_topology_quality(&report, quality) {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_REPORT_BINDING_MISMATCH".to_owned(),
            message: "candidate topology quality report differs from its durable record".to_owned(),
        });
    }
    Ok(())
}

fn validate_candidate_topology_quality_artifact_readback(
    bytes: &[u8],
    quality: &CandidateTopologyQualityRecord,
    artifact_size_bytes: u64,
) -> Result<(), StoreError> {
    let value: Value = serde_json::from_slice(bytes).map_err(|error| StoreError::Contract {
        code: "CANDIDATE_TOPOLOGY_QUALITY_READBACK_INVALID".to_owned(),
        message: format!("ArtifactReadback is not valid JSON: {error}"),
    })?;
    let object = value.as_object().ok_or_else(|| StoreError::Contract {
        code: "CANDIDATE_TOPOLOGY_QUALITY_READBACK_INVALID".to_owned(),
        message: "ArtifactReadback must be a JSON object".to_owned(),
    })?;
    let string = |field: &str| {
        object
            .get(field)
            .and_then(Value::as_str)
            .ok_or_else(|| StoreError::Contract {
                code: "CANDIDATE_TOPOLOGY_QUALITY_READBACK_BINDING_MISMATCH".to_owned(),
                message: format!("ArtifactReadback.{field} is missing or malformed"),
            })
    };
    if string("schema_version")? != "ArtifactReadback@2"
        // ArtifactReadback@2 identifies the immutable GLB object by its
        // content hash. CandidateTopologyQuality.artifact_id is the
        // candidate's stable prepared-object identifier, so the readback ID
        // must bind artifact_sha256 instead of conflating those two IDs.
        || string("artifact_id")? != quality.artifact_sha256
        || string("candidate_id")? != quality.candidate_id
        || string("object_sha256")? != quality.artifact_sha256
        || string("mime")? != "model/gltf-binary"
        || string("program_sha256")? != quality.geometry_program_sha256
        || string("operator_catalog_sha256")? != quality.operator_catalog_sha256
        || string("readback_config_sha256")? != quality.readback_config_sha256
        || string("canonical_sha256")? != quality.artifact_readback_sha256
        || object.get("size_bytes").and_then(Value::as_u64) != Some(artifact_size_bytes)
        || string("validator_status")? != "passed"
        || object.get("hard_gate_passed").and_then(Value::as_bool) != Some(true)
    {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_READBACK_BINDING_MISMATCH".to_owned(),
            message: "ArtifactReadback does not exactly bind topology quality".to_owned(),
        });
    }
    let readback_part_ids = object
        .get("part_ids")
        .and_then(Value::as_array)
        .ok_or_else(|| StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_PART_INVENTORY_MISMATCH".to_owned(),
            message: "ArtifactReadback.part_ids is missing".to_owned(),
        })?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(str::to_owned)
                .ok_or_else(|| StoreError::Contract {
                    code: "CANDIDATE_TOPOLOGY_QUALITY_PART_INVENTORY_MISMATCH".to_owned(),
                    message: "ArtifactReadback.part_ids contains a non-string".to_owned(),
                })
        })
        .collect::<Result<Vec<_>, _>>()?;
    if readback_part_ids != quality.part_ids {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_PART_INVENTORY_MISMATCH".to_owned(),
            message: "topology quality Part inventory differs from ArtifactReadback".to_owned(),
        });
    }
    let source_node_ids = value_string_set(object, "source_node_ids")?;
    let material_zone_ids = value_string_set(object, "material_zone_ids")?;
    let bindings = object
        .get("part_bindings")
        .and_then(Value::as_array)
        .ok_or_else(|| StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_PART_INVENTORY_MISMATCH".to_owned(),
            message: "ArtifactReadback.part_bindings is missing".to_owned(),
        })?;
    if bindings.len() != quality.part_ids.len() {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_PART_INVENTORY_MISMATCH".to_owned(),
            message: "ArtifactReadback.part_bindings does not cover every Part".to_owned(),
        });
    }
    let mut solid_count = 0_u64;
    for (index, binding) in bindings.iter().enumerate() {
        let binding = binding.as_object().ok_or_else(|| StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_PART_INVENTORY_MISMATCH".to_owned(),
            message: "ArtifactReadback.part_bindings contains a non-object".to_owned(),
        })?;
        let part_id = binding.get("part_id").and_then(Value::as_str);
        let source_node_id = binding.get("source_node_id").and_then(Value::as_str);
        let material_zone_id = binding.get("material_zone_id").and_then(Value::as_str);
        if part_id != Some(quality.part_ids[index].as_str())
            || source_node_id.is_none_or(|id| !source_node_ids.contains(id))
            || material_zone_id.is_none_or(|id| !material_zone_ids.contains(id))
            || binding
                .get("triangle_count")
                .and_then(Value::as_u64)
                .is_none()
        {
            return Err(StoreError::Contract {
                code: "CANDIDATE_TOPOLOGY_QUALITY_PART_INVENTORY_MISMATCH".to_owned(),
                message: "ArtifactReadback Part binding is incomplete or reordered".to_owned(),
            });
        }
        if binding.get("solid").and_then(Value::as_bool) == Some(true) {
            solid_count += 1;
        }
    }
    if solid_count != quality.metrics.solid_part_count
        || quality.metrics.non_solid_part_count
            != quality.metrics.part_count.saturating_sub(solid_count)
    {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_SOLID_INVENTORY_MISMATCH".to_owned(),
            message: "solid/non-solid Part counts differ from ArtifactReadback".to_owned(),
        });
    }
    let integrity = object
        .get("integrity")
        .and_then(Value::as_object)
        .ok_or_else(|| StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_READBACK_INVALID".to_owned(),
            message: "ArtifactReadback.integrity is missing".to_owned(),
        })?;
    if integrity.get("glb_parse_status").and_then(Value::as_str) != Some("passed")
        || integrity.get("invalid_index_count").and_then(Value::as_u64) != Some(0)
        || integrity.get("non_finite_count").and_then(Value::as_u64) != Some(0)
        || integrity
            .get("degenerate_triangle_count")
            .and_then(Value::as_u64)
            != Some(0)
        || integrity
            .get("non_manifold_edge_count")
            .and_then(Value::as_u64)
            != Some(0)
        || integrity.get("winding_error_count").and_then(Value::as_u64) != Some(0)
        || integrity.get("part_coverage").and_then(Value::as_f64) != Some(1.0)
        || integrity.get("source_coverage").and_then(Value::as_f64) != Some(1.0)
        || integrity
            .get("material_zone_coverage")
            .and_then(Value::as_f64)
            != Some(1.0)
    {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_READBACK_GATE_FAILED".to_owned(),
            message: "ArtifactReadback does not satisfy the source structural gate".to_owned(),
        });
    }
    Ok(())
}

fn value_string_set(
    object: &serde_json::Map<String, Value>,
    field: &str,
) -> Result<HashSet<String>, StoreError> {
    let values =
        object
            .get(field)
            .and_then(Value::as_array)
            .ok_or_else(|| StoreError::Contract {
                code: "CANDIDATE_TOPOLOGY_QUALITY_READBACK_INVALID".to_owned(),
                message: format!("ArtifactReadback.{field} is missing"),
            })?;
    let mut result = HashSet::new();
    for value in values {
        let text = value.as_str().ok_or_else(|| StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_READBACK_INVALID".to_owned(),
            message: format!("ArtifactReadback.{field} contains a non-string"),
        })?;
        if !is_opaque_id(text) || !result.insert(text.to_owned()) {
            return Err(StoreError::Contract {
                code: "CANDIDATE_TOPOLOGY_QUALITY_READBACK_INVALID".to_owned(),
                message: format!("ArtifactReadback.{field} is not a unique identifier list"),
            });
        }
    }
    Ok(result)
}

fn ensure_candidate_topology_quality_binding_in_transaction(
    connection: &Connection,
    quality: &CandidateTopologyQualityRecord,
    report_object: &CasObjectRecord,
) -> Result<String, StoreError> {
    let candidate: Option<(String, Option<String>, String, i64)> = connection
        .query_row(
            "SELECT project_id, prepared_object_sha256, canonical_sha256, quality_hard_gate_passed FROM candidates WHERE candidate_id = ?1",
            params![quality.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((project_id, prepared_artifact, candidate_state, quality_hard_gate_passed)) =
        candidate
    else {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_CANDIDATE_NOT_FOUND".to_owned(),
            message: "candidate is unavailable for topology quality".to_owned(),
        });
    };
    if project_id != quality.project_id
        || prepared_artifact.as_deref() != Some(quality.artifact_sha256.as_str())
        || candidate_state != quality.candidate_state_sha256
        || quality_hard_gate_passed != 1
    {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_CANDIDATE_BINDING_MISMATCH".to_owned(),
            message: "topology quality does not bind the candidate state/artifact".to_owned(),
        });
    }
    let evidence: Option<(String, String, String, String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, artifact_object_sha256, artifact_readback_object_sha256, canonical_sha256, geometry_program_sha256, geometry_program_object_sha256, operator_catalog_sha256, readback_config_sha256 FROM geometry_candidate_evidence WHERE candidate_id = ?1",
            params![quality.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?)),
        )
        .optional()?;
    let Some((
        evidence_project,
        evidence_artifact,
        evidence_readback,
        evidence_canonical,
        evidence_program,
        evidence_program_object,
        evidence_catalog,
        evidence_config,
    )) = evidence
    else {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_EVIDENCE_NOT_FOUND".to_owned(),
            message: "geometry candidate evidence is unavailable".to_owned(),
        });
    };
    if evidence_project != quality.project_id
        || evidence_artifact != quality.artifact_sha256
        || evidence_readback != quality.artifact_readback_object_sha256
        || evidence_canonical != quality.geometry_candidate_evidence_sha256
        || evidence_program != quality.geometry_program_sha256
        || evidence_program_object != quality.geometry_program_object_sha256
        || evidence_catalog != quality.operator_catalog_sha256
        || evidence_config != quality.readback_config_sha256
    {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_EVIDENCE_BINDING_MISMATCH".to_owned(),
            message: "topology quality differs from durable geometry evidence".to_owned(),
        });
    }
    ensure_candidate_topology_quality_object_in_transaction(
        connection,
        report_object,
        CANDIDATE_TOPOLOGY_QUALITY_REPORT_MIME,
        CANDIDATE_TOPOLOGY_QUALITY_REPORT_KIND,
        MAX_CANDIDATE_TOPOLOGY_QUALITY_REPORT_BYTES,
    )?;
    ensure_topology_quality_source_object_metadata(
        connection,
        &quality.artifact_sha256,
        "artifact",
    )?;
    ensure_topology_quality_source_object_metadata(
        connection,
        &quality.artifact_readback_object_sha256,
        "readback",
    )?;
    ensure_topology_quality_source_object_metadata(
        connection,
        &quality.geometry_program_object_sha256,
        "program",
    )?;
    let source_quality_report_object_sha256: String = connection.query_row(
        "SELECT quality_report_object_sha256 FROM geometry_candidate_evidence WHERE candidate_id = ?1",
        params![quality.candidate_id],
        |row| row.get(0),
    )?;
    ensure_topology_quality_source_object_metadata(
        connection,
        &source_quality_report_object_sha256,
        "quality",
    )?;
    Ok(source_quality_report_object_sha256)
}

fn ensure_candidate_topology_quality_row_binding(
    connection: &Connection,
    topology_quality_id: &str,
    quality: &CandidateTopologyQualityRecord,
    report_object_sha256: &str,
) -> Result<(), StoreError> {
    let row: Option<(
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
    )> = connection
        .query_row(
            "SELECT project_id, candidate_id, candidate_state_sha256, artifact_id, artifact_sha256, artifact_readback_sha256, artifact_readback_object_sha256, geometry_candidate_evidence_sha256, geometry_program_sha256, geometry_program_object_sha256, operator_catalog_sha256, readback_config_sha256, part_inventory_sha256, part_ids_json, part_topology_snapshot_sha256s_json, authoring_topology_status, part_authoring_topology_sha256s_json FROM candidate_topology_quality_links WHERE topology_quality_id = ?1",
            params![topology_quality_id],
            |row| {
                Ok((
                    row.get(0)?,
                    row.get(1)?,
                    row.get(2)?,
                    row.get(3)?,
                    row.get(4)?,
                    row.get(5)?,
                    row.get(6)?,
                    row.get(7)?,
                    row.get(8)?,
                    row.get(9)?,
                    row.get(10)?,
                    row.get(11)?,
                    row.get(12)?,
                    row.get(13)?,
                    row.get(14)?,
                    row.get(15)?,
                    row.get(16)?,
                ))
            },
        )
        .optional()?;
    let Some(row) = row else {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_ROW_MISSING".to_owned(),
            message: "candidate topology quality row disappeared".to_owned(),
        });
    };
    let expected_part_ids = canonical_json_string(&quality.part_ids)?;
    let expected_snapshots = canonical_json_string(&quality.part_topology_snapshot_sha256s)?;
    let expected_authoring = canonical_json_string(&quality.part_authoring_topology_sha256s)?;
    if row.0 != quality.project_id
        || row.1 != quality.candidate_id
        || row.2 != quality.candidate_state_sha256
        || row.3 != quality.artifact_id
        || row.4 != quality.artifact_sha256
        || row.5 != quality.artifact_readback_sha256
        || row.6 != quality.artifact_readback_object_sha256
        || row.7 != quality.geometry_candidate_evidence_sha256
        || row.8 != quality.geometry_program_sha256
        || row.9 != quality.geometry_program_object_sha256
        || row.10 != quality.operator_catalog_sha256
        || row.11 != quality.readback_config_sha256
        || row.12 != quality.part_inventory_sha256
        || row.13 != expected_part_ids
        || row.14 != expected_snapshots
        || row.15 != quality.authoring_topology_status
        || row.16 != expected_authoring
    {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_ROW_BINDING_MISMATCH".to_owned(),
            message: "candidate topology quality SQLite binding differs from payload".to_owned(),
        });
    }
    let stored_report: String = connection.query_row(
        "SELECT report_object_sha256 FROM candidate_topology_quality_links WHERE topology_quality_id = ?1",
        params![topology_quality_id],
        |row| row.get(0),
    )?;
    if stored_report != report_object_sha256 {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_ROW_REPORT_MISMATCH".to_owned(),
            message: "candidate topology quality report binding differs from SQLite".to_owned(),
        });
    }
    Ok(())
}

fn ensure_candidate_topology_quality_object_in_transaction(
    connection: &Connection,
    object: &CasObjectRecord,
    expected_mime: &str,
    expected_kind: &str,
    max_bytes: u64,
) -> Result<(), StoreError> {
    let stored: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![object.sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((size_bytes, mime, kind, reachability)) = stored else {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_OBJECT_UNAVAILABLE".to_owned(),
            message: "topology quality object is not registered".to_owned(),
        });
    };
    if mime != expected_mime
        || kind != expected_kind
        || size_bytes <= 0
        || u64::try_from(size_bytes).unwrap_or(u64::MAX) > max_bytes
        || !matches!(reachability.as_str(), "temporary" | "reachable")
        || size_bytes != i64::try_from(object.size_bytes).unwrap_or(i64::MAX)
    {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_OBJECT_INVALID".to_owned(),
            message: "topology quality object metadata is invalid".to_owned(),
        });
    }
    Ok(())
}

fn ensure_topology_quality_source_object_metadata(
    connection: &Connection,
    sha256: &str,
    role: &str,
) -> Result<(), StoreError> {
    let (size_bytes, mime, kind, reachability): (i64, String, String, String) = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .map_err(|_| StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_SOURCE_OBJECT_UNAVAILABLE".to_owned(),
            message: format!("topology quality {role} object is unavailable"),
        })?;
    let valid = match role {
        "artifact" => {
            mime == "model/gltf-binary"
                && matches!(
                    kind.as_str(),
                    "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
                )
                && size_bytes > 0
                && size_bytes <= 64 * 1024 * 1024
        }
        "readback" => {
            mime == "application/json"
                && matches!(
                    kind.as_str(),
                    "geometry-artifact-readback-v2" | "appearance-v2-artifact-readback"
                )
                && size_bytes > 0
                && size_bytes
                    <= i64::try_from(MAX_CANDIDATE_TOPOLOGY_QUALITY_REPORT_BYTES)
                        .unwrap_or(i64::MAX)
        }
        "program" => {
            mime == "application/json"
                && kind == "geometry-program-v2"
                && size_bytes > 0
                && size_bytes
                    <= i64::try_from(MAX_CANDIDATE_TOPOLOGY_QUALITY_REPORT_BYTES)
                        .unwrap_or(i64::MAX)
        }
        "quality" => {
            mime == "application/json"
                && kind == "geometry-quality-report"
                && size_bytes > 0
                && size_bytes
                    <= i64::try_from(MAX_CANDIDATE_TOPOLOGY_QUALITY_REPORT_BYTES)
                        .unwrap_or(i64::MAX)
        }
        _ => false,
    };
    if !valid || !matches!(reachability.as_str(), "temporary" | "reachable") {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_SOURCE_OBJECT_INVALID".to_owned(),
            message: format!("topology quality {role} object metadata is invalid"),
        });
    }
    Ok(())
}

fn read_candidate_topology_quality_report_object(
    connection: &Connection,
    sha256: &str,
) -> Result<CasObjectRecord, StoreError> {
    let row: Option<(i64, String, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability, created_at FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .optional()?;
    let Some((size_bytes, mime, kind, reachability, created_at)) = row else {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_REPORT_UNAVAILABLE".to_owned(),
            message: "candidate topology quality report object is unavailable".to_owned(),
        });
    };
    let size_bytes = u64::try_from(size_bytes).map_err(|_| StoreError::Contract {
        code: "CANDIDATE_TOPOLOGY_QUALITY_REPORT_INVALID".to_owned(),
        message: "candidate topology quality report size is invalid".to_owned(),
    })?;
    if mime != CANDIDATE_TOPOLOGY_QUALITY_REPORT_MIME
        || kind != CANDIDATE_TOPOLOGY_QUALITY_REPORT_KIND
        || size_bytes == 0
        || size_bytes > MAX_CANDIDATE_TOPOLOGY_QUALITY_REPORT_BYTES
        || !matches!(reachability.as_str(), "temporary" | "reachable")
    {
        return Err(StoreError::Contract {
            code: "CANDIDATE_TOPOLOGY_QUALITY_REPORT_INVALID".to_owned(),
            message: "candidate topology quality report metadata is invalid".to_owned(),
        });
    }
    Ok(CasObjectRecord {
        schema_version: "CasObject@1".to_owned(),
        sha256: sha256.to_owned(),
        size_bytes,
        mime,
        kind,
        reachability,
        created_at,
    })
}

