fn candidate_topology_quality_reachable_hashes(
    quality: &CandidateTopologyQualityRecord,
    source_quality_report_object_sha256: &str,
    report_object_sha256: &str,
) -> Vec<String> {
    let mut hashes = vec![
        quality.artifact_sha256.clone(),
        quality.artifact_readback_object_sha256.clone(),
        quality.geometry_program_object_sha256.clone(),
        source_quality_report_object_sha256.to_owned(),
        report_object_sha256.to_owned(),
    ];
    hashes.sort();
    hashes.dedup();
    hashes
}

fn candidate_material_surface_quality_payload_json(
    quality: &CandidateMaterialSurfaceQualityRecord,
) -> Result<String, StoreError> {
    let value = serde_json::to_value(quality)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let bytes =
        canonical_json_bytes(&value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    String::from_utf8(bytes).map_err(|error| StoreError::InvalidData(error.to_string()))
}

fn same_candidate_material_surface_quality(
    left: &CandidateMaterialSurfaceQualityRecord,
    right: &CandidateMaterialSurfaceQualityRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

fn candidate_material_surface_quality_hard_gate_passed(
    gate: &CandidateMaterialSurfaceQualityHardGate,
) -> bool {
    gate.distinct_candidates
        && gate.source_topology_quality
        && gate.source_artifact_readback
        && gate.output_artifact_readback
        && gate.geometry_preserved
        && gate.appearance_source_lineage
        && gate.material_pack_2k
        && gate.texture_build_v2
        && gate.surface_bake_v1
        && gate.uv_integrity
        && gate.tangent_integrity
        && gate.material_provenance
}

fn validate_candidate_material_surface_quality(
    quality: &CandidateMaterialSurfaceQualityRecord,
) -> Result<(), StoreError> {
    let mut canonical = quality.clone();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let ids = [
        quality.material_surface_quality_id.as_str(),
        quality.project_id.as_str(),
        quality.source_candidate_id.as_str(),
        quality.source_artifact_id.as_str(),
        quality.source_topology_quality_id.as_str(),
        quality.output_candidate_id.as_str(),
        quality.output_artifact_id.as_str(),
    ];
    let hashes = [
        quality.source_candidate_state_sha256.as_str(),
        quality.source_artifact_sha256.as_str(),
        quality.source_artifact_readback_sha256.as_str(),
        quality.source_artifact_readback_object_sha256.as_str(),
        quality.source_geometry_candidate_evidence_sha256.as_str(),
        quality.source_geometry_program_sha256.as_str(),
        quality
            .source_topology_quality_report_object_sha256
            .as_str(),
        quality.source_topology_quality_canonical_sha256.as_str(),
        quality.output_candidate_state_sha256.as_str(),
        quality.output_artifact_sha256.as_str(),
        quality.output_artifact_readback_sha256.as_str(),
        quality.output_artifact_readback_object_sha256.as_str(),
        quality.output_geometry_program_sha256.as_str(),
        quality
            .appearance_source_lineage_sidecar_object_sha256
            .as_str(),
        quality.appearance_source_lineage_canonical_sha256.as_str(),
        quality.appearance_program_object_sha256.as_str(),
        quality.appearance_program_sha256.as_str(),
        quality.material_layer_stack_sha256.as_str(),
        quality.material_pack_manifest_object_sha256.as_str(),
        quality.material_pack_manifest_sha256.as_str(),
        quality.material_pack_provenance_sha256.as_str(),
        quality.texture_build_receipt_object_sha256.as_str(),
        quality.texture_build_receipt_canonical_sha256.as_str(),
        quality
            .candidate_surface_bake_receipt_object_sha256
            .as_str(),
        quality
            .candidate_surface_bake_receipt_canonical_sha256
            .as_str(),
        quality.uv_binding_sha256.as_str(),
        quality.tangent_binding_sha256.as_str(),
        quality.material_zone_inventory_sha256.as_str(),
        quality.material_provenance_sha256.as_str(),
        quality.geometry_preservation_projection_sha256.as_str(),
        quality.material_surface_quality_policy_sha256.as_str(),
        quality.request_sha256.as_str(),
        quality.input_sha256.as_str(),
        quality.canonical_sha256.as_str(),
    ];
    if quality.schema_version != "CandidateMaterialSurfaceQuality@1"
        || ids.iter().any(|value| !is_opaque_id(value))
        || hashes.iter().any(|value| !is_sha256(value))
        || quality.source_candidate_id == quality.output_candidate_id
        || quality.material_pack_id != "forgecad-fictional-energy-weapon-2k"
        || quality.material_pack_version != "1.0.0"
        || quality.material_pack_license_spdx != "CC0-1.0"
        || quality.lod_scope != CANDIDATE_MATERIAL_SURFACE_QUALITY_LOD_SCOPE
        || quality.source_output_candidate_binding_status != "distinct-candidates-verified"
        || quality.geometry_preservation_status != "source-output-renderable-geometry-byte-exact"
        || quality.material_surface_quality_policy != CANDIDATE_MATERIAL_SURFACE_QUALITY_POLICY
        || quality.from_stage != "topology"
        || quality.to_stage != "material-surface"
        || !matches!(quality.validator_status.as_str(), "passed" | "failed")
        || quality.hard_gate_passed != (quality.validator_status == "passed")
        || (quality.hard_gate_passed
            && !candidate_material_surface_quality_hard_gate_passed(&quality.hard_gate))
        || quality.visual_quality_status != "NOT_PROVEN"
        || quality.artistic_quality_status != "NOT_PROVEN"
        || quality.human_review_status != "NOT_RUN"
        || quality.commercial_fps_quality_status != "NOT_PROVEN"
        || quality.commercial_engine_status != "NOT_RUN"
        || quality.materialization_status != CANDIDATE_MATERIAL_SURFACE_QUALITY_STATUS
        || quality.quality_status != "structural_only"
        || !quality.runtime_write_performed
        || quality.production_stage_advanced
        || quality.candidate_confirmed
        || quality.version_created
        || quality.export_performed
        || quality.canonical_sha256 != expected
        || quality.created_at.is_empty()
        || quality.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "candidate material-surface quality record is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn validate_candidate_material_surface_quality_report_bytes(
    bytes: &[u8],
    quality: &CandidateMaterialSurfaceQualityRecord,
) -> Result<(), StoreError> {
    let report: CandidateMaterialSurfaceQualityRecord =
        serde_json::from_slice(bytes).map_err(|error| StoreError::Contract {
            code: "CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_INVALID".to_owned(),
            message: format!("material-surface quality report is not valid JSON: {error}"),
        })?;
    validate_candidate_material_surface_quality(&report)?;
    if !same_candidate_material_surface_quality(&report, quality) {
        return Err(StoreError::Contract {
            code: "CANDIDATE_MATERIAL_SURFACE_QUALITY_REPORT_BINDING_MISMATCH".to_owned(),
            message: "material-surface quality report differs from the durable record".to_owned(),
        });
    }
    Ok(())
}

