fn game_weapon_animated_glb_socket_materialization_reachable_hashes(
    link: &GameWeaponAnimatedGlbSocketMaterializationLinkRecord,
) -> Vec<String> {
    vec![
        // The source animation pair is immutable Runtime-owned input, not an
        // owned output, but this durable link is an explicit consumer of both
        // objects and must keep them reachable across rollback/GC.
        link.animated_artifact_sha256.clone(),
        link.animation_receipt_object_sha256.clone(),
        link.derived_animated_socket_artifact_sha256.clone(),
        link.receipt_object_sha256.clone(),
    ]
}

fn ensure_game_weapon_animated_glb_socket_object(
    connection: &Connection,
    sha256: &str,
    expected_mime: &str,
    expected_kind: &str,
    max_bytes: i64,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= max_bytes
            && mime == expected_mime
            && kind == expected_kind
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_CAS_OBJECT_INVALID".to_owned(),
            message: "animated socket materialization CAS metadata is missing or differs"
                .to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_animated_glb_socket_source_object(
    connection: &Connection,
    sha256: &str,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= 64 * 1024 * 1024
            && mime == "model/gltf-binary"
            && matches!(
                kind.as_str(),
                "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
            )
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_SOURCE_ARTIFACT_INVALID".to_owned(),
            message: "animated socket materialization source GLB metadata is invalid".to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_animated_glb_socket_materialization_objects(
    connection: &Connection,
    link: &GameWeaponAnimatedGlbSocketMaterializationLinkRecord,
) -> Result<(), StoreError> {
    ensure_game_weapon_animated_glb_socket_source_object(connection, &link.lod0_artifact_sha256)?;
    ensure_game_weapon_animated_glb_socket_source_object(connection, &link.source_artifact_sha256)?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &link.animated_artifact_sha256,
        "model/gltf-binary",
        "mechanical-animation-glb",
        64 * 1024 * 1024,
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &link.animation_receipt_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        "mechanical-animation-glb-receipt",
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &link.anchor_set_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        GAME_WEAPON_ANCHOR_SET_KIND,
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &link.derived_animated_socket_artifact_sha256,
        "model/gltf-binary",
        GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZED_GLB_KIND,
        64 * 1024 * 1024,
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &link.receipt_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_RECEIPT_KIND,
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_materialization_binding_in_transaction(
    connection: &Connection,
    link: &GameWeaponAnimatedGlbSocketMaterializationLinkRecord,
) -> Result<(), StoreError> {
    let delivery: Option<(String, String, String, Option<String>)> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256, animation_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((delivery_project, delivery_candidate, delivery_lod0, delivery_animation)) = delivery
    else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_DELIVERY_BINDING_MISMATCH".to_owned(),
            message: "animated socket materialization delivery link is unavailable".to_owned(),
        });
    };
    if delivery_project != link.project_id
        || delivery_candidate != link.candidate_id
        || delivery_lod0 != link.lod0_artifact_sha256
        || link.source_artifact_sha256 != link.lod0_artifact_sha256
        || delivery_animation
            .as_deref()
            .is_some_and(|animation| animation != link.animated_artifact_sha256)
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_DELIVERY_BINDING_MISMATCH".to_owned(),
            message:
                "animated socket materialization source differs from delivery LOD0 or animation"
                    .to_owned(),
        });
    }

    let candidate: Option<(String, String, Option<String>, Option<String>)> = connection
        .query_row(
            "SELECT project_id, canonical_sha256, prepared_object_sha256, manifest_hash FROM candidates WHERE candidate_id = ?1",
            params![link.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((candidate_project, candidate_state, prepared, manifest)) = candidate else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_CANDIDATE_BINDING_MISMATCH".to_owned(),
            message: "animated socket materialization source candidate is unavailable".to_owned(),
        });
    };
    if candidate_project != link.project_id
        || candidate_state != link.candidate_state_sha256
        || prepared.as_deref() != Some(link.source_artifact_sha256.as_str())
        || manifest.as_deref() != Some(link.source_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_CANDIDATE_BINDING_MISMATCH".to_owned(),
            message: "animated socket materialization candidate/artifact binding differs"
                .to_owned(),
        });
    }

    let anchor: Option<(String, String)> = connection
        .query_row(
            "SELECT project_id, anchor_set_object_sha256 FROM game_weapon_anchor_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if anchor.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
        || anchor.as_ref().map(|value| value.1.as_str())
            != Some(link.anchor_set_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_ANCHOR_BINDING_MISMATCH".to_owned(),
            message: "animated socket materialization AnchorSet differs from durable anchor link"
                .to_owned(),
        });
    }
    Ok(())
}

fn game_weapon_animated_glb_socket_materialization_v2_value(
    link: &GameWeaponAnimatedGlbSocketMaterializationV2LinkRecord,
) -> Result<Value, StoreError> {
    serde_json::to_value(link).map_err(|error| StoreError::InvalidData(error.to_string()))
}

fn game_weapon_animated_glb_socket_materialization_v2_value_string<'a>(
    value: &'a Value,
    field: &str,
) -> Result<&'a str, StoreError> {
    value
        .get(field)
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            StoreError::InvalidData(format!(
                "V2 animated socket materialization field {field} is missing"
            ))
        })
}

fn game_weapon_animated_glb_socket_materialization_v2_value_bool(
    value: &Value,
    field: &str,
) -> Result<bool, StoreError> {
    value.get(field).and_then(Value::as_bool).ok_or_else(|| {
        StoreError::InvalidData(format!(
            "V2 animated socket materialization field {field} is not boolean"
        ))
    })
}

fn game_weapon_animated_glb_socket_materialization_v2_link_from_payload_row(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<GameWeaponAnimatedGlbSocketMaterializationV2LinkRecord> {
    let payload: String = row.get(0)?;
    serde_json::from_str(&payload).map_err(|error| {
        rusqlite::Error::FromSqlConversionFailure(0, rusqlite::types::Type::Text, Box::new(error))
    })
}

fn same_game_weapon_animated_glb_socket_materialization_v2_link(
    left: &GameWeaponAnimatedGlbSocketMaterializationV2LinkRecord,
    right: &GameWeaponAnimatedGlbSocketMaterializationV2LinkRecord,
) -> bool {
    let Ok(mut left) = game_weapon_animated_glb_socket_materialization_v2_value(left) else {
        return false;
    };
    let Ok(mut right) = game_weapon_animated_glb_socket_materialization_v2_value(right) else {
        return false;
    };
    for value in [&mut left, &mut right] {
        if let Some(object) = value.as_object_mut() {
            object.insert("canonical_sha256".to_owned(), Value::String(String::new()));
            object.insert("created_at".to_owned(), Value::String(String::new()));
        }
    }
    canonical_json_bytes(&left).ok() == canonical_json_bytes(&right).ok()
}

fn game_weapon_animated_glb_socket_materialization_v2_derived_keys(
    value: &Value,
) -> Result<(String, String), StoreError> {
    let request = serde_json::json!({
        "schema_version":"GameWeaponAnimatedGlbSocketMaterializationPrepareRequest@2",
        "project_id":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "project_id")?,
        "appearance_candidate_id":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "appearance_candidate_id")?,
        "appearance_candidate_state_sha256":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "appearance_candidate_state_sha256")?,
        "clip_id":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "clip_id")?,
        "clip_object_sha256":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "clip_object_sha256")?,
        "clip_sha256":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "clip_sha256")?,
        "appearance_delivery_manifest_object_sha256":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "appearance_delivery_manifest_object_sha256")?,
        "anchor_set_object_sha256":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "anchor_set_object_sha256")?,
        "anchor_set_canonical_sha256":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "anchor_set_canonical_sha256")?,
        "materialization_policy":game_weapon_animated_glb_socket_materialization_v2_value_string(value, "socket_materialization_policy")?,
    });
    let request_sha256 = canonical_json_hash(&request);
    let mut business = request;
    business
        .as_object_mut()
        .expect("derived V2 request is an object")
        .remove("schema_version");
    Ok((request_sha256, canonical_json_hash(&business)))
}

fn validate_game_weapon_animated_glb_socket_materialization_v2_link(
    link: &GameWeaponAnimatedGlbSocketMaterializationV2LinkRecord,
) -> Result<(), StoreError> {
    let value = game_weapon_animated_glb_socket_materialization_v2_value(link)?;
    if game_weapon_animated_glb_socket_materialization_v2_value_string(&value, "schema_version")?
        != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_SCHEMA
    {
        return Err(StoreError::InvalidData(
            "V2 animated socket materialization schema is invalid".to_owned(),
        ));
    }
    let (expected_request_sha256, expected_key_sha256) =
        game_weapon_animated_glb_socket_materialization_v2_derived_keys(&value)?;
    if game_weapon_animated_glb_socket_materialization_v2_value_string(&value, "request_sha256")?
        != expected_request_sha256
        || game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "animated_socket_materialization_key_sha256",
        )? != expected_key_sha256
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_DERIVED_KEY_MISMATCH".to_owned(),
            message: "V2 animated socket key/request hashes do not bind the frozen prepare fields"
                .to_owned(),
        });
    }
    for field in [
        "animated_socket_materialization_key_sha256",
        "appearance_candidate_state_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
        "appearance_artifact_readback_sha256",
        "animation_glb_key_sha256",
        "animated_artifact_sha256",
        "animated_artifact_readback_sha256",
        "animation_receipt_object_sha256",
        "animation_receipt_canonical_sha256",
        "clip_object_sha256",
        "clip_sha256",
        "anchor_set_object_sha256",
        "anchor_set_canonical_sha256",
        "request_sha256",
        "socket_node_id_encoding_sha256",
        "derived_animated_socket_artifact_sha256",
        "derived_animated_socket_artifact_readback_sha256",
        "receipt_object_sha256",
        "canonical_sha256",
    ] {
        if !is_sha256(
            game_weapon_animated_glb_socket_materialization_v2_value_string(&value, field)?,
        ) {
            return Err(StoreError::InvalidData(format!(
                "V2 animated socket materialization hash {field} is invalid"
            )));
        }
    }
    for field in ["project_id", "appearance_candidate_id", "clip_id"] {
        if !is_opaque_id(
            game_weapon_animated_glb_socket_materialization_v2_value_string(&value, field)?,
        ) {
            return Err(StoreError::InvalidData(format!(
                "V2 animated socket materialization identity {field} is invalid"
            )));
        }
    }
    if game_weapon_animated_glb_socket_materialization_v2_value_string(
        &value,
        "socket_materialization_policy",
    )? != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_POLICY
        || game_weapon_animated_glb_socket_materialization_v2_value_string(&value, "lod_scope")?
            != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_LOD_SCOPE
        || game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "validator_status",
        )? != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_VALIDATOR_STATUS
        || !game_weapon_animated_glb_socket_materialization_v2_value_bool(
            &value,
            "hard_gate_passed",
        )?
        || game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "materialization_status",
        )? != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_STATUS
        || game_weapon_animated_glb_socket_materialization_v2_value_string(
            &value,
            "quality_status",
        )? != "structural_only"
        || game_weapon_animated_glb_socket_materialization_v2_value_string(&value, "created_at")?
            .len()
            > 128
    {
        return Err(StoreError::InvalidData(
            "V2 animated socket materialization policy/status is invalid".to_owned(),
        ));
    }
    let mut canonical = value.clone();
    canonical["canonical_sha256"] = Value::String(String::new());
    let expected = canonical_json_hash(&canonical);
    if game_weapon_animated_glb_socket_materialization_v2_value_string(&value, "canonical_sha256")?
        != expected
    {
        return Err(StoreError::InvalidData(
            "V2 animated socket materialization canonical hash is invalid".to_owned(),
        ));
    }
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_materialization_v2_receipt_bytes(
    bytes: &[u8],
    link: &Value,
) -> Result<(), StoreError> {
    let receipt: Value = serde_json::from_slice(bytes).map_err(|error| StoreError::Contract {
        code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_INVALID".to_owned(),
        message: format!("V2 animated socket receipt JSON is invalid: {error}"),
    })?;
    if canonical_json_bytes(&receipt).map_err(|error| StoreError::InvalidData(error.to_string()))?
        != bytes
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_CANONICAL_MISMATCH".to_owned(),
            message: "V2 animated socket receipt is not canonical JSON".to_owned(),
        });
    }
    let typed_receipt: GameWeaponAnimatedGlbSocketMaterializationV2ReceiptRecord =
        serde_json::from_value(receipt.clone()).map_err(|error| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_INVALID".to_owned(),
            message: format!(
                "V2 animated socket receipt does not match its closed Contract: {error}"
            ),
        })?;
    let typed_value = serde_json::to_value(&typed_receipt)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if typed_value != receipt {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_UNKNOWN_FIELDS".to_owned(),
            message: "V2 animated socket receipt contains unknown or omitted Contract fields"
                .to_owned(),
        });
    }
    if game_weapon_animated_glb_socket_materialization_v2_value_string(&receipt, "schema_version")?
        != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_RECEIPT_SCHEMA
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_INVALID".to_owned(),
            message: "V2 animated socket receipt schema is invalid".to_owned(),
        });
    }
    let mut canonical = receipt.clone();
    canonical["canonical_sha256"] = Value::String(String::new());
    if game_weapon_animated_glb_socket_materialization_v2_value_string(
        &receipt,
        "canonical_sha256",
    )? != canonical_json_hash(&canonical)
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_CANONICAL_MISMATCH".to_owned(),
            message: "V2 animated socket receipt canonical hash is invalid".to_owned(),
        });
    }
    for field in [
        "source_animation_projection_sha256",
        "derived_animation_projection_sha256",
        "source_animation_validation_sha256",
        "derived_animation_validation_sha256",
        "source_renderable_inventory_sha256",
        "derived_renderable_inventory_sha256",
        "source_bin_sha256",
        "derived_bin_sha256",
        "source_appearance_material_projection_sha256",
        "derived_appearance_material_projection_sha256",
        "sampling_policy_sha256",
        "socket_node_inventory_sha256",
    ] {
        if !is_sha256(
            game_weapon_animated_glb_socket_materialization_v2_value_string(&receipt, field)?,
        ) {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_HASH_INVALID".to_owned(),
                message: format!("V2 animated socket receipt hash {field} is invalid"),
            });
        }
    }
    for field in [
        "animated_socket_materialization_key_sha256",
        "project_id",
        "appearance_candidate_id",
        "appearance_candidate_state_sha256",
        "appearance_delivery_manifest_object_sha256",
        "appearance_artifact_sha256",
        "appearance_artifact_readback_sha256",
        "animation_glb_key_sha256",
        "animated_artifact_sha256",
        "animated_artifact_readback_sha256",
        "animation_receipt_object_sha256",
        "animation_receipt_canonical_sha256",
        "clip_id",
        "clip_object_sha256",
        "clip_sha256",
        "anchor_set_object_sha256",
        "anchor_set_canonical_sha256",
        "request_sha256",
        "socket_materialization_policy",
        "lod_scope",
        "socket_node_id_encoding_sha256",
        "derived_animated_socket_artifact_sha256",
        "derived_animated_socket_artifact_readback_sha256",
    ] {
        if receipt.get(field) != link.get(field) {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_BINDING_MISMATCH".to_owned(),
                message: format!("V2 animated socket receipt field {field} differs from link"),
            });
        }
    }
    let kinds = receipt
        .get("owned_cas_kinds")
        .and_then(Value::as_array)
        .ok_or_else(|| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_INVALID".to_owned(),
            message: "V2 animated socket receipt owned CAS kind list is missing".to_owned(),
        })?;
    let expected_kinds = [
        Value::String(GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZED_GLB_V2_KIND.to_owned()),
        Value::String(GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_RECEIPT_KIND.to_owned()),
    ];
    if kinds.as_slice() != expected_kinds {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_OWNERSHIP_MISMATCH".to_owned(),
            message: "V2 animated socket receipt must declare exactly two owned CAS kinds"
                .to_owned(),
        });
    }
    for (field, expected) in [
        ("animations_preserved", true),
        ("channels_preserved", true),
        ("samplers_preserved", true),
        ("renderable_projection_exact", true),
        ("bin_byte_exact", true),
        ("source_static_projection_exact", true),
        ("appearance_material_projection_exact", true),
        ("material_pack_identity_exact", true),
        ("no_skinning", true),
        ("no_morph_targets", true),
        ("socket_nodes_materialized", true),
        ("runtime_write_performed", true),
        ("restart_hash_verified", true),
        ("candidate_confirmed", false),
        ("version_created", false),
        ("export_performed", false),
        ("production_stage_advanced", false),
        ("actual_engine_roundtrip", false),
        ("functional_semantics", false),
        ("hard_gate_passed", true),
    ] {
        if receipt.get(field).and_then(Value::as_bool) != Some(expected) {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_STATUS_MISMATCH".to_owned(),
                message: format!("V2 animated socket receipt boolean {field} is invalid"),
            });
        }
    }
    for (field, expected) in [
        (
            "materialization_status",
            GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_STATUS,
        ),
        (
            "validator_status",
            GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_VALIDATOR_STATUS,
        ),
        ("quality_status", "structural_only"),
        ("visual_quality_status", "NOT_PROVEN"),
        ("commercial_fps_quality_status", "NOT_PROVEN"),
        ("human_review_status", "NOT_RUN"),
        ("commercial_engine_status", "NOT_RUN"),
    ] {
        if receipt.get(field).and_then(Value::as_str) != Some(expected) {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_STATUS_MISMATCH".to_owned(),
                message: format!("V2 animated socket receipt status {field} is invalid"),
            });
        }
    }
    if !(2..=16).contains(&typed_receipt.sample_time_ticks.len())
        || typed_receipt
            .sample_time_ticks
            .iter()
            .any(|tick| *tick > 1_000_000)
        || typed_receipt
            .sample_time_ticks
            .windows(2)
            .any(|pair| pair[0] >= pair[1])
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_SAMPLE_SCHEDULE_INVALID".to_owned(),
            message:
                "V2 animated socket receipt sample ticks are not a bounded increasing schedule"
                    .to_owned(),
        });
    }
    let part_ids: HashSet<&str> = typed_receipt.part_ids.iter().map(String::as_str).collect();
    if !(1..=64).contains(&typed_receipt.part_ids.len())
        || part_ids.len() != typed_receipt.part_ids.len()
        || typed_receipt
            .part_ids
            .iter()
            .any(|part_id| !is_opaque_id(part_id))
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_PART_INVENTORY_INVALID".to_owned(),
            message: "V2 animated socket receipt Part inventory is invalid".to_owned(),
        });
    }
    if !(2..=128).contains(&typed_receipt.sampler_count)
        || !(2..=128).contains(&typed_receipt.channel_count)
        || !(1..=64).contains(&typed_receipt.node_count)
        || !(1..=64).contains(&typed_receipt.source_node_count)
        || !(7..=70).contains(&typed_receipt.derived_node_count)
        || !(3..=129).contains(&typed_receipt.accessor_count_added)
        || !(3..=129).contains(&typed_receipt.buffer_view_count_added)
        || typed_receipt.socket_node_count != 6
        || typed_receipt.socket_nodes.len() != 6
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_COUNTS_INVALID".to_owned(),
            message: "V2 animated socket receipt counts are outside the closed schema bounds"
                .to_owned(),
        });
    }
    let expected_roles = [
        "weapon-root",
        "grip-primary",
        "muzzle-vfx",
        "magazine-well",
        "sight-primary",
        "energy-core-vfx",
    ];
    let mut roles = HashSet::new();
    let mut socket_ids = HashSet::new();
    let mut anchor_ids = HashSet::new();
    let mut node_names = HashSet::new();
    for node in &typed_receipt.socket_nodes {
        if !expected_roles.contains(&node.role.as_str())
            || !roles.insert(node.role.as_str())
            || !is_opaque_id(&node.socket_node_id)
            || !socket_ids.insert(node.socket_node_id.as_str())
            || !is_opaque_id(&node.anchor_id)
            || !anchor_ids.insert(node.anchor_id.as_str())
            || !is_opaque_id(&node.node_name)
            || !node_names.insert(node.node_name.as_str())
            || node.node_kind != "empty"
            || !matches!(
                node.parent_kind.as_str(),
                "synthetic-scene-root" | "part-node"
            )
            || node
                .parent_node_name
                .as_deref()
                .is_some_and(|name| !is_opaque_id(name))
            || node
                .owner_part_id
                .as_deref()
                .is_some_and(|part_id| !is_opaque_id(part_id))
            || node.local_translation_m.len() != 3
            || node.local_rotation_quat_xyzw.len() != 4
            || node.local_scale_xyz != vec![1.0, 1.0, 1.0]
            || node
                .local_translation_m
                .iter()
                .any(|value| !value.is_finite() || !(-10.0..=10.0).contains(value))
            || node
                .local_rotation_quat_xyzw
                .iter()
                .any(|value| !value.is_finite() || !(-1.0..=1.0).contains(value))
        {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_SOCKET_NODES_INVALID".to_owned(),
                message: "V2 animated socket receipt must contain six unique closed socket nodes"
                    .to_owned(),
            });
        }
    }
    if roles.len() != expected_roles.len()
        || expected_roles.iter().any(|role| !roles.contains(role))
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_SOCKET_ROLES_INVALID".to_owned(),
            message: "V2 animated socket receipt socket roles are not exactly the six closed roles"
                .to_owned(),
        });
    }
    if typed_receipt.semantic_scope != "fictional-nonfunctional-game-visual-authoring-only@1"
        || typed_receipt.functional_semantics
        || typed_receipt.limitations
            != vec![
                "appearance-candidate-bound-rigid-Part-TRS-only".to_owned(),
                "scheduled-integer-ticks-and-LINEAR-interpolation-only".to_owned(),
                "no-skinning-morph-targets-armature-IK-constraints-NLA-or-drivers".to_owned(),
                "source-BIN-and-appearance-material-projection-must-remain-exact".to_owned(),
                "structural-readback-does-not-prove-visual-quality-or-engine-roundtrip".to_owned(),
            ]
        || typed_receipt.created_at.is_empty()
        || typed_receipt.created_at.len() > 64
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_RECEIPT_SEMANTIC_BOUNDARY_INVALID".to_owned(),
            message: "V2 animated socket receipt semantic scope, limitations or timestamp differs"
                .to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_animated_glb_socket_materialization_v2_object(
    connection: &Connection,
    hash: &str,
    expected_mime: &str,
    expected_kinds: &[&str],
    max_bytes: u64,
    role: &str,
) -> Result<(), StoreError> {
    let object: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![hash],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((size, mime, kind, reachability)) = object else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_CAS_OBJECT_MISSING".to_owned(),
            message: format!("V2 animated socket {role} CAS object is missing"),
        });
    };
    if size <= 0
        || u64::try_from(size).unwrap_or(u64::MAX) > max_bytes
        || mime != expected_mime
        || !expected_kinds.contains(&kind.as_str())
        || !matches!(reachability.as_str(), "temporary" | "reachable")
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_V2_CAS_OBJECT_INVALID".to_owned(),
            message: format!("V2 animated socket {role} CAS object metadata is invalid"),
        });
    }
    Ok(())
}

