fn read_game_weapon_animated_glb_socket_transform_projection_v2_frames(
    connection: &Connection,
    projection_key_sha256: &str,
) -> Result<Vec<GameWeaponAnimatedGlbSocketTransformProjectionV2Frame>, StoreError> {
    let mut statement = connection.prepare(
        "SELECT json_object(
            'schema_version', schema_version,
            'projection_key_sha256', projection_key_sha256,
            'frame_index', frame_index,
            'sample_time_ticks', sample_time_ticks,
            'source_animation_sample_sha256', source_animation_sample_sha256,
            'derived_socket_sample_sha256', derived_socket_sample_sha256,
            'socket_transform_inventory_sha256', socket_transform_inventory_sha256,
            'socket_transform_readback_sha256', socket_transform_readback_sha256,
            'projection_frame_canonical_sha256', projection_frame_canonical_sha256,
            'canonical_sha256', canonical_sha256,
            'created_at', created_at
        ), payload_json
        FROM game_weapon_animated_glb_socket_transform_projection_v2_frames
        WHERE projection_key_sha256 = ?1 ORDER BY frame_index ASC",
    )?;
    let mut rows = statement.query(params![projection_key_sha256])?;
    let mut frames = Vec::new();
    while let Some(row) = rows.next()? {
        let columns: String = row.get(0)?;
        let payload: String = row.get(1)?;
        let frame: GameWeaponAnimatedGlbSocketTransformProjectionV2Frame =
            serde_json::from_str(&payload).map_err(|error| StoreError::Contract {
                code:
                    "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_FRAME_PAYLOAD_INVALID"
                        .to_owned(),
                message: format!("V2 projection frame payload is invalid: {error}"),
            })?;
        let typed_value = serde_json::to_value(&frame)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?;
        let canonical_payload = canonical_json_bytes(&typed_value)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?;
        if canonical_payload.as_slice() != payload.as_bytes() {
            return Err(StoreError::Contract {
                code:
                    "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_FRAME_PAYLOAD_MISMATCH"
                        .to_owned(),
                message: "V2 projection frame payload is not canonical".to_owned(),
            });
        }
        validate_game_weapon_animated_glb_socket_transform_projection_v2_frame_columns(
            &columns, &frame,
        )?;
        frames.push(frame);
    }
    Ok(frames)
}

fn same_game_weapon_animated_glb_socket_transform_projection_v2(
    left: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
    right: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    for frame in &mut left.frames {
        frame.created_at.clear();
        frame.canonical_sha256.clear();
    }
    for frame in &mut right.frames {
        frame.created_at.clear();
        frame.canonical_sha256.clear();
    }
    left == right
}

