fn projection_v2_request_preimage(
    projection: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
) -> Result<Value, StoreError> {
    let value = serde_json::to_value(projection)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let object = value.as_object().ok_or_else(|| {
        StoreError::InvalidData("V2 transform projection is not a JSON object".to_owned())
    })?;
    let mut preimage = serde_json::Map::new();
    for field in GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_PREIMAGE_FIELDS {
        let value = object.get(*field).ok_or_else(|| {
            StoreError::InvalidData(format!("V2 transform projection field {field} is missing"))
        })?;
        let value = if *field == "schema_version" {
            Value::String(
                "GameWeaponAnimatedGlbSocketTransformProjectionPrepareRequest@2".to_owned(),
            )
        } else {
            value.clone()
        };
        preimage.insert((*field).to_owned(), value);
    }
    Ok(Value::Object(preimage))
}

fn validate_game_weapon_animated_glb_socket_transform_projection_v2_request_hashes(
    projection: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
) -> Result<(), StoreError> {
    let expected_input_sha256 = canonical_json_hash(&projection_v2_request_preimage(projection)?);
    if projection.input_sha256 != expected_input_sha256
        || projection.projection_key_sha256 != expected_input_sha256
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_INPUT_KEY_MISMATCH"
                .to_owned(),
            message: "V2 projection input/key hash differs from the request preimage".to_owned(),
        });
    }
    let roles = serde_json::to_value(&projection.socket_roles)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if projection.socket_roles_sha256 != canonical_json_hash(&roles) {
        return Err(StoreError::Contract {
            code:
                "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_ROLES_HASH_MISMATCH"
                    .to_owned(),
            message: "V2 projection socket role hash differs from socket_roles".to_owned(),
        });
    }
    let schedule = serde_json::json!({
        "frame_scope": projection.frame_scope,
        "sample_time_ticks": projection.sample_time_ticks,
        "timebase_hz": projection.timebase_hz,
    });
    if projection.sample_schedule_sha256 != canonical_json_hash(&schedule) {
        return Err(StoreError::Contract {
            code:
                "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SAMPLE_SCHEDULE_HASH_MISMATCH"
                    .to_owned(),
            message: "V2 projection sample schedule hash differs from frame_scope/ticks/timebase"
                .to_owned(),
        });
    }
    Ok(())
}

fn projection_v2_canonical_f32(value: f32) -> f32 {
    if value == 0.0 {
        0.0
    } else {
        value
    }
}

fn projection_v2_f32_json_number(value: f32) -> f64 {
    projection_v2_canonical_f32(value)
        .to_string()
        .parse::<f64>()
        .expect("finite f32 has a finite shortest decimal representation")
}

fn projection_v2_pose_f32(
    pose: &forgecad_contracts::GameWeaponAnimatedGlbSocketTransformProjectionV2Pose,
) -> ([f32; 3], [f32; 4]) {
    (
        [
            pose.translation_m[0] as f32,
            pose.translation_m[1] as f32,
            pose.translation_m[2] as f32,
        ],
        [
            pose.rotation_quat_xyzw[0] as f32,
            pose.rotation_quat_xyzw[1] as f32,
            pose.rotation_quat_xyzw[2] as f32,
            pose.rotation_quat_xyzw[3] as f32,
        ],
    )
}

fn projection_v2_matrix_from_pose(
    pose: &forgecad_contracts::GameWeaponAnimatedGlbSocketTransformProjectionV2Pose,
) -> Vec<f64> {
    let (translation, [x, y, z, w]) = projection_v2_pose_f32(pose);
    let xx = x * x;
    let yy = y * y;
    let zz = z * z;
    let xy = x * y;
    let xz = x * z;
    let yz = y * z;
    let xw = x * w;
    let yw = y * w;
    let zw = z * w;
    [
        1.0 - 2.0 * (yy + zz),
        2.0 * (xy + zw),
        2.0 * (xz - yw),
        0.0,
        2.0 * (xy - zw),
        1.0 - 2.0 * (xx + zz),
        2.0 * (yz + xw),
        0.0,
        2.0 * (xz + yw),
        2.0 * (yz - xw),
        1.0 - 2.0 * (xx + yy),
        0.0,
        translation[0],
        translation[1],
        translation[2],
        1.0,
    ]
    .into_iter()
    .map(projection_v2_f32_json_number)
    .collect()
}

fn projection_v2_quaternion_normalize(mut value: [f32; 4]) -> [f32; 4] {
    let norm = value
        .iter()
        .map(|component| *component * *component)
        .sum::<f32>()
        .sqrt();
    if !norm.is_finite() || norm < 1.0e-7 {
        return [0.0, 0.0, 0.0, 1.0];
    }
    for component in &mut value {
        *component = projection_v2_canonical_f32(*component / norm);
    }
    let flip = value[3] < 0.0
        || (value[3] == 0.0
            && (value[0] < 0.0
                || (value[0] == 0.0 && value[1] < 0.0)
                || (value[0] == 0.0 && value[1] == 0.0 && value[2] < 0.0)));
    if flip {
        for component in &mut value {
            *component = projection_v2_canonical_f32(-*component);
        }
    }
    value
}

fn projection_v2_quaternion_multiply_raw(left: [f32; 4], right: [f32; 4]) -> [f32; 4] {
    [
        left[3] * right[0] + left[0] * right[3] + left[1] * right[2] - left[2] * right[1],
        left[3] * right[1] - left[0] * right[2] + left[1] * right[3] + left[2] * right[0],
        left[3] * right[2] + left[0] * right[1] - left[1] * right[0] + left[2] * right[3],
        left[3] * right[3] - left[0] * right[0] - left[1] * right[1] - left[2] * right[2],
    ]
}

fn projection_v2_quaternion_multiply(left: [f32; 4], right: [f32; 4]) -> [f32; 4] {
    projection_v2_quaternion_normalize(projection_v2_quaternion_multiply_raw(left, right))
}

fn projection_v2_rotate_vector(rotation: [f32; 4], vector: [f32; 3]) -> [f32; 3] {
    let q_vector = [vector[0], vector[1], vector[2], 0.0];
    let inverse = [-rotation[0], -rotation[1], -rotation[2], rotation[3]];
    let result = projection_v2_quaternion_multiply_raw(
        projection_v2_quaternion_multiply_raw(rotation, q_vector),
        inverse,
    );
    [
        projection_v2_canonical_f32(result[0]),
        projection_v2_canonical_f32(result[1]),
        projection_v2_canonical_f32(result[2]),
    ]
}

fn projection_v2_compose_poses(
    parent: &forgecad_contracts::GameWeaponAnimatedGlbSocketTransformProjectionV2Pose,
    local: &forgecad_contracts::GameWeaponAnimatedGlbSocketTransformProjectionV2Pose,
) -> ([f32; 3], [f32; 4]) {
    let (parent_translation, parent_rotation) = projection_v2_pose_f32(parent);
    let (local_translation, local_rotation) = projection_v2_pose_f32(local);
    let rotated_local = projection_v2_rotate_vector(parent_rotation, local_translation);
    let translation = [
        projection_v2_canonical_f32(parent_translation[0] + rotated_local[0]),
        projection_v2_canonical_f32(parent_translation[1] + rotated_local[1]),
        projection_v2_canonical_f32(parent_translation[2] + rotated_local[2]),
    ];
    (
        translation,
        projection_v2_quaternion_multiply(parent_rotation, local_rotation),
    )
}

fn projection_v2_pose_from_f32(translation: [f32; 3], rotation: [f32; 4]) -> Vec<f64> {
    translation
        .into_iter()
        .map(projection_v2_f32_json_number)
        .chain(rotation.into_iter().map(projection_v2_f32_json_number))
        .collect()
}

fn projection_v2_approx_equal(left: f64, right: f64) -> bool {
    let tolerance = 1.0e-4 + 1.0e-6 * left.abs().max(right.abs());
    (left - right).abs() <= tolerance
}

fn projection_v2_validate_matrix(
    matrix: &[f64],
    expected: &[f64],
    label: &str,
) -> Result<(), StoreError> {
    if matrix.len() != 16
        || expected.len() != 16
        || matrix.iter().zip(expected).any(|(actual, expected)| {
            !actual.is_finite() || !projection_v2_approx_equal(*actual, *expected)
        })
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_MATRIX_MISMATCH"
                .to_owned(),
            message: format!("V2 projection {label} matrix does not match its TRS"),
        });
    }
    Ok(())
}

fn projection_v2_matrix_multiply(left: &[f64], right: &[f64]) -> Vec<f64> {
    let mut result = vec![0.0; 16];
    for column in 0..4 {
        for row in 0..4 {
            result[column * 4 + row] = (0..4)
                .map(|index| left[index * 4 + row] * right[column * 4 + index])
                .sum();
        }
    }
    result
}

fn validate_projection_v2_socket_transform_math(
    socket: &forgecad_contracts::GameWeaponAnimatedGlbSocketTransformProjectionV2SocketTransform,
) -> Result<(), StoreError> {
    projection_v2_validate_matrix(
        &socket.local_matrix_4x4,
        &projection_v2_matrix_from_pose(&socket.local_transform),
        "local",
    )?;
    projection_v2_validate_matrix(
        &socket.parent_world_matrix_4x4,
        &projection_v2_matrix_from_pose(&socket.parent_world_transform),
        "parent-world",
    )?;
    projection_v2_validate_matrix(
        &socket.composed_world_matrix_4x4,
        &projection_v2_matrix_from_pose(&socket.composed_world_transform),
        "composed-world",
    )?;
    let composed_matrix =
        projection_v2_matrix_multiply(&socket.parent_world_matrix_4x4, &socket.local_matrix_4x4);
    projection_v2_validate_matrix(
        &socket.composed_world_matrix_4x4,
        &composed_matrix,
        "composed-world parent*local",
    )?;
    let (expected_translation, expected_rotation) =
        projection_v2_compose_poses(&socket.parent_world_transform, &socket.local_transform);
    let expected_pose = projection_v2_pose_from_f32(expected_translation, expected_rotation);
    let actual_pose = socket
        .composed_world_transform
        .translation_m
        .iter()
        .chain(socket.composed_world_transform.rotation_quat_xyzw.iter())
        .copied()
        .collect::<Vec<_>>();
    if actual_pose.len() != expected_pose.len()
        || actual_pose
            .iter()
            .zip(expected_pose)
            .any(|(actual, expected)| !projection_v2_approx_equal(*actual, expected))
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_COMPOSED_TRS_MISMATCH"
                .to_owned(),
            message: "V2 projection composed TRS does not equal parent*local".to_owned(),
        });
    }
    Ok(())
}

fn valid_projection_v2_pose(
    pose: &forgecad_contracts::GameWeaponAnimatedGlbSocketTransformProjectionV2Pose,
) -> bool {
    if pose.translation_m.len() != 3
        || pose.rotation_quat_xyzw.len() != 4
        || pose.scale_xyz != [1.0, 1.0, 1.0]
        || pose
            .translation_m
            .iter()
            .any(|value| !value.is_finite() || !(-1000.0..=1000.0).contains(value))
        || pose
            .rotation_quat_xyzw
            .iter()
            .any(|value| !value.is_finite() || !(-1.0..=1.0).contains(value))
    {
        return false;
    }
    let norm_squared: f64 = pose
        .rotation_quat_xyzw
        .iter()
        .map(|value| value * value)
        .sum();
    (norm_squared - 1.0).abs() <= 1.0e-5
}

fn valid_projection_v2_matrix(matrix: &[f64]) -> bool {
    matrix.len() == 16
        && matrix
            .iter()
            .all(|value| value.is_finite() && (-1_000_000.0..=1_000_000.0).contains(value))
}

fn validate_game_weapon_animated_glb_socket_transform_projection_v2(
    projection: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
) -> Result<(), StoreError> {
    const ROLES: [&str; 6] = [
        "weapon-root",
        "grip-primary",
        "muzzle-vfx",
        "magazine-well",
        "sight-primary",
        "energy-core-vfx",
    ];
    const LIMITATIONS: [&str; 9] = [
        "appearance-candidate-bound-mechanical-animation-glb-v2-and-animated-socket-v2",
        "parent-clip-sample-exact-or-bounded-sixteen-samples",
        "flat-identity-rest-part-hierarchy-only",
        "nested-part-hierarchy-rejected",
        "matrix-and-shear-rejected",
        "structural-transform-readback-only",
        "no-visual-quality-or-likeness-pass",
        "no-commercial-engine-roundtrip",
        "no-functional-weapon-semantics",
    ];
    validate_game_weapon_animated_glb_socket_transform_projection_v2_request_hashes(projection)?;
    for hash in [
        &projection.projection_key_sha256,
        &projection.appearance_candidate_state_sha256,
        &projection.appearance_delivery_manifest_object_sha256,
        &projection.appearance_artifact_sha256,
        &projection.appearance_artifact_readback_sha256,
        &projection.animation_clip_object_sha256,
        &projection.animation_clip_canonical_sha256,
        &projection.animation_glb_key_sha256,
        &projection.animated_artifact_sha256,
        &projection.animated_artifact_readback_sha256,
        &projection.animation_receipt_object_sha256,
        &projection.animation_receipt_canonical_sha256,
        &projection.animated_socket_materialization_key_sha256,
        &projection.derived_animated_socket_artifact_sha256,
        &projection.derived_animated_socket_artifact_readback_sha256,
        &projection.derived_animated_socket_receipt_object_sha256,
        &projection.derived_animated_socket_receipt_canonical_sha256,
        &projection.anchor_set_object_sha256,
        &projection.anchor_set_canonical_sha256,
        &projection.socket_node_id_encoding_sha256,
        &projection.socket_node_inventory_sha256,
        &projection.socket_roles_sha256,
        &projection.part_hierarchy_sha256,
        &projection.sampling_policy_sha256,
        &projection.sample_schedule_sha256,
        &projection.input_sha256,
        &projection.canonical_sha256,
    ] {
        if !is_sha256(hash) {
            return Err(StoreError::InvalidData(
                "V2 animated socket transform projection contains an invalid hash".to_owned(),
            ));
        }
    }
    if projection.schema_version != "GameWeaponAnimatedGlbSocketTransformProjection@2"
        || !is_opaque_id(&projection.project_id)
        || !is_opaque_id(&projection.appearance_candidate_id)
        || !is_opaque_id(&projection.animation_clip_id)
        || projection
            .socket_roles
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>()
            != ROLES
        || projection.part_hierarchy_policy != "flat-identity-rest-part-hierarchy-only@2"
        || projection.transform_representation_policy
            != "trs-quaternion-no-shear-plus-column-major-matrix@2"
        || projection.frame_scope
            != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_FRAME_SCOPE
        || projection.timebase_hz != 1000
        || projection.transform_projection_policy
            != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_POLICY
        || projection.coordinate_system != "forgecad-rh-y-up-m@1"
        || projection.transform_convention
            != "column-vector-parent-world-times-trs-quaternion-xyzw@1"
        || projection.float_quantization_policy != "f32-round-nearest-canonical-json@1"
        || projection.projection_status
            != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_STATUS
        || projection.quality_status != "structural_only"
        || projection.visual_quality_status != "NOT_PROVEN"
        || projection.commercial_fps_quality_status != "NOT_PROVEN"
        || projection.human_review_status != "NOT_RUN"
        || projection.commercial_engine_status != "NOT_RUN"
        || !projection.runtime_write_performed
        || !projection.restart_hash_verified
        || projection.candidate_confirmed
        || projection.version_created
        || projection.export_performed
        || projection.actual_engine_roundtrip
        || projection.production_stage_advanced
        || projection
            .limitations
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>()
            != LIMITATIONS
        || projection.created_at.is_empty()
        || projection.created_at.len() > 64
        || !(1..=16).contains(&projection.sample_count)
        || projection.sample_count as usize != projection.sample_time_ticks.len()
        || projection.sample_count as usize != projection.frames.len()
        || projection
            .sample_time_ticks
            .iter()
            .any(|tick| *tick > 1_000_000)
        || projection
            .sample_time_ticks
            .windows(2)
            .any(|pair| pair[0] >= pair[1])
    {
        return Err(StoreError::InvalidData(
            "V2 animated socket transform projection policy or bounded schedule is malformed"
                .to_owned(),
        ));
    }

    let mut baseline_identity: Option<
        Vec<(
            String,
            String,
            String,
            u64,
            i64,
            String,
            Option<String>,
            String,
            String,
            Option<String>,
        )>,
    > = None;
    for (index, frame) in projection.frames.iter().enumerate() {
        for hash in [
            &frame.source_animation_sample_sha256,
            &frame.derived_socket_sample_sha256,
            &frame.socket_transform_inventory_sha256,
            &frame.socket_transform_readback_sha256,
            &frame.projection_frame_canonical_sha256,
            &frame.canonical_sha256,
        ] {
            if !is_sha256(hash) {
                return Err(StoreError::InvalidData(
                    "V2 transform projection frame contains an invalid hash".to_owned(),
                ));
            }
        }
        if frame.schema_version != "GameWeaponAnimatedGlbSocketTransformProjectionFrame@2"
            || frame.projection_key_sha256 != projection.projection_key_sha256
            || frame.frame_index != index as u64
            || frame.sample_time_ticks != projection.sample_time_ticks[index]
            || frame.socket_transforms.len() != 6
            || frame.created_at.is_empty()
            || frame.created_at.len() > 64
        {
            return Err(StoreError::InvalidData(
                "V2 transform projection frame order, tick or socket count is invalid".to_owned(),
            ));
        }
        let mut socket_ids = HashSet::new();
        let mut anchor_ids = HashSet::new();
        let mut node_names = HashSet::new();
        let mut node_indices = HashSet::new();
        let mut identities = Vec::new();
        for (socket_index, socket) in frame.socket_transforms.iter().enumerate() {
            if socket.role != ROLES[socket_index]
                || !is_opaque_id(&socket.socket_node_id)
                || !socket_ids.insert(socket.socket_node_id.as_str())
                || !is_opaque_id(&socket.anchor_id)
                || !anchor_ids.insert(socket.anchor_id.as_str())
                || !is_opaque_id(&socket.node_name)
                || !node_names.insert(socket.node_name.as_str())
                || !node_indices.insert(socket.node_index)
                || socket.node_index > 4095
                || !(-1..=4095).contains(&socket.parent_node_index)
                || socket.node_kind != "empty"
                || !matches!(
                    socket.parent_kind.as_str(),
                    "synthetic-scene-root" | "part-node"
                )
                || socket
                    .parent_node_name
                    .as_deref()
                    .is_some_and(|name| !is_opaque_id(name))
                || socket
                    .owner_part_id
                    .as_deref()
                    .is_some_and(|part| !is_opaque_id(part))
                || (socket.parent_node_index < 0
                    && (socket.parent_kind != "synthetic-scene-root"
                        || socket.parent_node_name.is_some()
                        || socket.owner_part_id.is_some()))
                || (socket.parent_node_index >= 0
                    && (socket.parent_kind != "part-node"
                        || socket.parent_node_name.is_none()
                        || socket.owner_part_id.is_none()
                        || socket.parent_node_index >= socket.node_index as i64))
                || !valid_projection_v2_pose(&socket.local_transform)
                || !valid_projection_v2_pose(&socket.parent_world_transform)
                || !valid_projection_v2_pose(&socket.composed_world_transform)
                || !valid_projection_v2_matrix(&socket.local_matrix_4x4)
                || !valid_projection_v2_matrix(&socket.parent_world_matrix_4x4)
                || !valid_projection_v2_matrix(&socket.composed_world_matrix_4x4)
            {
                return Err(StoreError::InvalidData(
                    "V2 transform projection socket inventory is malformed".to_owned(),
                ));
            }
            validate_projection_v2_socket_transform_math(socket)?;
            identities.push((
                socket.socket_node_id.clone(),
                socket.anchor_id.clone(),
                socket.role.clone(),
                socket.node_index,
                socket.parent_node_index,
                socket.node_name.clone(),
                socket.parent_node_name.clone(),
                socket.node_kind.clone(),
                socket.parent_kind.clone(),
                socket.owner_part_id.clone(),
            ));
        }
        if baseline_identity
            .as_ref()
            .is_some_and(|baseline| baseline != &identities)
        {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_RETARGET"
                    .to_owned(),
                message: "V2 projection socket identities changed between frames".to_owned(),
            });
        }
        baseline_identity.get_or_insert(identities);
        let mut canonical_frame = frame.clone();
        canonical_frame.canonical_sha256.clear();
        if canonical_json_hash(
            &serde_json::to_value(&canonical_frame)
                .map_err(|error| StoreError::InvalidData(error.to_string()))?,
        ) != frame.canonical_sha256
        {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_FRAME_CANONICAL_MISMATCH"
                    .to_owned(),
                message: "V2 projection frame canonical hash differs".to_owned(),
            });
        }
    }
    let mut canonical = projection.clone();
    canonical.canonical_sha256.clear();
    if canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    ) != projection.canonical_sha256
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_CANONICAL_MISMATCH"
                .to_owned(),
            message: "V2 projection canonical hash differs".to_owned(),
        });
    }
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_transform_projection_v2_socket_receipt_binding(
    projection: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
    receipt: &GameWeaponAnimatedGlbSocketMaterializationV2ReceiptRecord,
) -> Result<(), StoreError> {
    if receipt.socket_nodes.len() != 6
        || receipt.socket_node_count != 6
        || receipt.socket_node_inventory_sha256 != projection.socket_node_inventory_sha256
        || receipt.socket_node_id_encoding_sha256 != projection.socket_node_id_encoding_sha256
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_RECEIPT_MISMATCH"
                .to_owned(),
            message: "V2 projection socket receipt inventory binding differs".to_owned(),
        });
    }
    for frame in &projection.frames {
        for (socket_index, socket) in frame.socket_transforms.iter().enumerate() {
            let receipt_node = receipt
                .socket_nodes
                .iter()
                .find(|node| node.role == socket.role)
                .ok_or_else(|| StoreError::Contract {
                    code:
                        "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_NODE_MISSING"
                            .to_owned(),
                    message: format!(
                        "V2 projection frame {} socket role {} is absent from AnimatedSocket@2 receipt",
                        frame.frame_index, socket.role
                    ),
                })?;
            let exact_identity = receipt_node.socket_node_id == socket.socket_node_id
                && receipt_node.anchor_id == socket.anchor_id
                && receipt_node.role == socket.role
                && receipt_node.node_name == socket.node_name
                && receipt_node.node_kind == socket.node_kind
                && receipt_node.parent_kind == socket.parent_kind
                && receipt_node.parent_node_name == socket.parent_node_name
                && receipt_node.owner_part_id == socket.owner_part_id;
            let local_translation_matches = receipt_node
                .local_translation_m
                .iter()
                .zip(&socket.local_transform.translation_m)
                .all(|(left, right)| projection_v2_approx_equal(*left, *right));
            let local_rotation_matches = receipt_node
                .local_rotation_quat_xyzw
                .iter()
                .zip(&socket.local_transform.rotation_quat_xyzw)
                .all(|(left, right)| projection_v2_approx_equal(*left, *right));
            let local_scale_matches = receipt_node
                .local_scale_xyz
                .iter()
                .zip(&socket.local_transform.scale_xyz)
                .all(|(left, right)| projection_v2_approx_equal(*left, *right));
            if socket.role != projection.socket_roles[socket_index]
                || !exact_identity
                || !local_translation_matches
                || !local_rotation_matches
                || !local_scale_matches
            {
                return Err(StoreError::Contract {
                    code:
                        "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_NODE_MISMATCH"
                            .to_owned(),
                    message: format!(
                        "V2 projection frame {} socket {} differs from AnimatedSocket@2 receipt",
                        frame.frame_index, socket.role
                    ),
                });
            }
        }
    }
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_transform_projection_v2_object_bytes(
    bytes: &[u8],
    projection: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
    object: &CasObjectRecord,
) -> Result<(), StoreError> {
    let value: Value = serde_json::from_slice(bytes).map_err(|error| StoreError::Contract {
        code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_OBJECT_INVALID".to_owned(),
        message: format!("V2 projection object JSON is invalid: {error}"),
    })?;
    let typed: GameWeaponAnimatedGlbSocketTransformProjectionV2 =
        serde_json::from_value(value.clone()).map_err(|error| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_OBJECT_INVALID"
                .to_owned(),
            message: format!("V2 projection object contract is invalid: {error}"),
        })?;
    let typed_value =
        serde_json::to_value(&typed).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let canonical = canonical_json_bytes(&typed_value)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if typed != *projection
        || typed_value != value
        || canonical != bytes
        || object.schema_version != "CasObject@1"
        || object.sha256 != sha256_hex(bytes)
        || object.mime != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_MIME
        || object.kind != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_KIND
        || object.size_bytes != bytes.len() as u64
        || object.size_bytes == 0
        || object.size_bytes > MAX_GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_BYTES
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_OBJECT_BINDING_MISMATCH"
                .to_owned(),
            message: "V2 projection object metadata or canonical payload differs".to_owned(),
        });
    }
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_transform_projection_v2_source_bindings(
    store: &Store,
    projection: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
) -> Result<(), StoreError> {
    let animation = store
        .get_mechanical_animation_glb_v2_link(&projection.animation_glb_key_sha256)?
        .ok_or_else(|| StoreError::Contract {
            code:
                "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_ANIMATION_PARENT_MISSING"
                    .to_owned(),
            message: "V2 projection MechanicalAnimationGlb@2 parent is unavailable".to_owned(),
        })?;
    if animation.project_id != projection.project_id
        || animation.appearance_candidate_id != projection.appearance_candidate_id
        || animation.appearance_candidate_state_sha256
            != projection.appearance_candidate_state_sha256
        || animation.appearance_artifact_sha256 != projection.appearance_artifact_sha256
        || animation.appearance_artifact_readback_sha256
            != projection.appearance_artifact_readback_sha256
        || animation.clip_id != projection.animation_clip_id
        || animation.clip_object_sha256 != projection.animation_clip_object_sha256
        || animation.clip_sha256 != projection.animation_clip_canonical_sha256
        || animation.animated_artifact_sha256 != projection.animated_artifact_sha256
        || animation.animated_artifact_readback_sha256
            != projection.animated_artifact_readback_sha256
        || animation.receipt_object_sha256 != projection.animation_receipt_object_sha256
        || animation.receipt_canonical_sha256 != projection.animation_receipt_canonical_sha256
        || animation.sampling_policy_sha256 != projection.sampling_policy_sha256
    {
        return Err(StoreError::Contract {
            code:
                "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_ANIMATION_PARENT_MISMATCH"
                    .to_owned(),
            message: "V2 projection differs from its MechanicalAnimationGlb@2 parent".to_owned(),
        });
    }
    let animation_receipt_bytes = store
        .cas
        .read_verified_bounded(
            &projection.animation_receipt_object_sha256,
            MAX_MECHANICAL_ANIMATION_GLB_V2_RECEIPT_BYTES,
        )
        .map_err(StoreError::Cas)?;
    let animation_receipt: MechanicalAnimationGlbV2ReceiptRecord =
        serde_json::from_slice(&animation_receipt_bytes).map_err(|error| StoreError::Contract {
            code:
                "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_ANIMATION_RECEIPT_INVALID"
                    .to_owned(),
            message: format!("V2 projection animation receipt is invalid: {error}"),
        })?;
    if animation_receipt.sample_time_ticks.len() < projection.sample_time_ticks.len()
        || projection
            .sample_time_ticks
            .iter()
            .any(|tick| !animation_receipt.sample_time_ticks.contains(tick))
        || animation_receipt.timebase_hz != projection.timebase_hz
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SAMPLE_PARENT_MISMATCH"
                .to_owned(),
            message: "V2 projection sample schedule is outside the Clip@2 animation receipt"
                .to_owned(),
        });
    }

    let socket = store
        .get_game_weapon_animated_glb_socket_materialization_v2_link(
            &projection.animated_socket_materialization_key_sha256,
        )?
        .ok_or_else(|| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_PARENT_MISSING"
                .to_owned(),
            message: "V2 projection AnimatedSocket@2 parent is unavailable".to_owned(),
        })?;
    if socket.project_id != projection.project_id
        || socket.appearance_candidate_id != projection.appearance_candidate_id
        || socket.appearance_candidate_state_sha256 != projection.appearance_candidate_state_sha256
        || socket.appearance_delivery_manifest_object_sha256
            != projection.appearance_delivery_manifest_object_sha256
        || socket.appearance_artifact_sha256 != projection.appearance_artifact_sha256
        || socket.appearance_artifact_readback_sha256
            != projection.appearance_artifact_readback_sha256
        || socket.animation_glb_key_sha256 != projection.animation_glb_key_sha256
        || socket.animated_artifact_sha256 != projection.animated_artifact_sha256
        || socket.animated_artifact_readback_sha256 != projection.animated_artifact_readback_sha256
        || socket.animation_receipt_object_sha256 != projection.animation_receipt_object_sha256
        || socket.animation_receipt_canonical_sha256
            != projection.animation_receipt_canonical_sha256
        || socket.clip_id != projection.animation_clip_id
        || socket.clip_object_sha256 != projection.animation_clip_object_sha256
        || socket.clip_sha256 != projection.animation_clip_canonical_sha256
        || socket.anchor_set_object_sha256 != projection.anchor_set_object_sha256
        || socket.anchor_set_canonical_sha256 != projection.anchor_set_canonical_sha256
        || socket.socket_node_id_encoding_sha256 != projection.socket_node_id_encoding_sha256
        || socket.derived_animated_socket_artifact_sha256
            != projection.derived_animated_socket_artifact_sha256
        || socket.derived_animated_socket_artifact_readback_sha256
            != projection.derived_animated_socket_artifact_readback_sha256
        || socket.receipt_object_sha256 != projection.derived_animated_socket_receipt_object_sha256
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_PARENT_MISMATCH"
                .to_owned(),
            message: "V2 projection differs from its AnimatedSocket@2 parent".to_owned(),
        });
    }
    let socket_receipt_bytes = store
        .cas
        .read_verified_bounded(
            &projection.derived_animated_socket_receipt_object_sha256,
            MAX_GAME_ASSET_DELIVERY_JSON_BYTES,
        )
        .map_err(StoreError::Cas)?;
    let socket_receipt: GameWeaponAnimatedGlbSocketMaterializationV2ReceiptRecord =
        serde_json::from_slice(&socket_receipt_bytes).map_err(|error| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_RECEIPT_INVALID"
                .to_owned(),
            message: format!("V2 projection socket receipt is invalid: {error}"),
        })?;
    if socket_receipt.canonical_sha256
        != projection.derived_animated_socket_receipt_canonical_sha256
        || socket_receipt.socket_node_inventory_sha256 != projection.socket_node_inventory_sha256
        || socket_receipt.socket_node_count != 6
        || socket_receipt.sample_time_ticks.len() < projection.sample_time_ticks.len()
        || projection
            .sample_time_ticks
            .iter()
            .any(|tick| !socket_receipt.sample_time_ticks.contains(tick))
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_RECEIPT_MISMATCH"
                .to_owned(),
            message: "V2 projection socket receipt inventory or schedule differs".to_owned(),
        });
    }
    validate_game_weapon_animated_glb_socket_transform_projection_v2_socket_receipt_binding(
        projection,
        &socket_receipt,
    )?;
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_transform_projection_v2_bindings_in_transaction(
    connection: &Connection,
    projection: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
) -> Result<(), StoreError> {
    let key_is_cas: Option<i64> = connection
        .query_row(
            "SELECT 1 FROM objects WHERE sha256 = ?1",
            params![projection.projection_key_sha256],
            |row| row.get(0),
        )
        .optional()?;
    if key_is_cas.is_some() {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_KEY_IS_CAS".to_owned(),
            message: "V2 projection lookup key must not be an objects row".to_owned(),
        });
    }
    let candidate: Option<(String, String, Option<String>, Option<String>)> = connection
        .query_row(
            "SELECT project_id, canonical_sha256, prepared_object_sha256, manifest_hash FROM candidates WHERE candidate_id = ?1",
            params![projection.appearance_candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if candidate.as_ref().map(|row| row.0.as_str()) != Some(projection.project_id.as_str())
        || candidate.as_ref().map(|row| row.1.as_str())
            != Some(projection.appearance_candidate_state_sha256.as_str())
        || candidate.as_ref().and_then(|row| row.2.as_deref())
            != Some(projection.appearance_artifact_sha256.as_str())
        || candidate.as_ref().and_then(|row| row.3.as_deref())
            != Some(projection.appearance_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_CANDIDATE_MISMATCH"
                .to_owned(),
            message: "V2 projection appearance candidate binding differs".to_owned(),
        });
    }
    let delivery: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![projection.appearance_delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if delivery.as_ref().map(|row| row.0.as_str()) != Some(projection.project_id.as_str())
        || delivery.as_ref().map(|row| row.1.as_str())
            != Some(projection.appearance_candidate_id.as_str())
        || delivery.as_ref().map(|row| row.2.as_str())
            != Some(projection.appearance_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_DELIVERY_MISMATCH"
                .to_owned(),
            message: "V2 projection appearance delivery binding differs".to_owned(),
        });
    }
    let anchor: Option<(String, String)> = connection
        .query_row(
            "SELECT project_id, anchor_set_object_sha256 FROM game_weapon_anchor_links WHERE delivery_manifest_object_sha256 = ?1",
            params![projection.appearance_delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if anchor.as_ref().map(|row| row.0.as_str()) != Some(projection.project_id.as_str())
        || anchor.as_ref().map(|row| row.1.as_str())
            != Some(projection.anchor_set_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_ANCHOR_MISMATCH"
                .to_owned(),
            message: "V2 projection AnchorSet differs from its delivery".to_owned(),
        });
    }
    let animation_count: i64 = connection.query_row(
        "SELECT COUNT(*) FROM mechanical_animation_glb_v2_links WHERE animation_glb_key_sha256 = ?1 AND project_id = ?2 AND appearance_candidate_id = ?3 AND appearance_candidate_state_sha256 = ?4 AND appearance_artifact_sha256 = ?5 AND appearance_artifact_readback_sha256 = ?6 AND clip_id = ?7 AND clip_object_sha256 = ?8 AND clip_sha256 = ?9 AND animated_artifact_sha256 = ?10 AND animated_artifact_readback_sha256 = ?11 AND receipt_object_sha256 = ?12 AND receipt_canonical_sha256 = ?13 AND sampling_policy_sha256 = ?14",
        params![projection.animation_glb_key_sha256, projection.project_id, projection.appearance_candidate_id, projection.appearance_candidate_state_sha256, projection.appearance_artifact_sha256, projection.appearance_artifact_readback_sha256, projection.animation_clip_id, projection.animation_clip_object_sha256, projection.animation_clip_canonical_sha256, projection.animated_artifact_sha256, projection.animated_artifact_readback_sha256, projection.animation_receipt_object_sha256, projection.animation_receipt_canonical_sha256, projection.sampling_policy_sha256],
        |row| row.get(0),
    )?;
    let socket_count: i64 = connection.query_row(
        "SELECT COUNT(*) FROM game_weapon_animated_glb_socket_materialization_v2_links WHERE animated_socket_materialization_key_sha256 = ?1 AND project_id = ?2 AND appearance_candidate_id = ?3 AND appearance_candidate_state_sha256 = ?4 AND appearance_delivery_manifest_object_sha256 = ?5 AND appearance_artifact_sha256 = ?6 AND appearance_artifact_readback_sha256 = ?7 AND animation_glb_key_sha256 = ?8 AND animated_artifact_sha256 = ?9 AND animated_artifact_readback_sha256 = ?10 AND animation_receipt_object_sha256 = ?11 AND animation_receipt_canonical_sha256 = ?12 AND clip_id = ?13 AND clip_object_sha256 = ?14 AND clip_sha256 = ?15 AND anchor_set_object_sha256 = ?16 AND anchor_set_canonical_sha256 = ?17 AND socket_node_id_encoding_sha256 = ?18 AND derived_animated_socket_artifact_sha256 = ?19 AND derived_animated_socket_artifact_readback_sha256 = ?20 AND receipt_object_sha256 = ?21",
        params![projection.animated_socket_materialization_key_sha256, projection.project_id, projection.appearance_candidate_id, projection.appearance_candidate_state_sha256, projection.appearance_delivery_manifest_object_sha256, projection.appearance_artifact_sha256, projection.appearance_artifact_readback_sha256, projection.animation_glb_key_sha256, projection.animated_artifact_sha256, projection.animated_artifact_readback_sha256, projection.animation_receipt_object_sha256, projection.animation_receipt_canonical_sha256, projection.animation_clip_id, projection.animation_clip_object_sha256, projection.animation_clip_canonical_sha256, projection.anchor_set_object_sha256, projection.anchor_set_canonical_sha256, projection.socket_node_id_encoding_sha256, projection.derived_animated_socket_artifact_sha256, projection.derived_animated_socket_artifact_readback_sha256, projection.derived_animated_socket_receipt_object_sha256],
        |row| row.get(0),
    )?;
    if animation_count != 1 || socket_count != 1 {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_PARENT_MISMATCH"
                .to_owned(),
            message: "V2 projection MechanicalAnimationGlb@2 or AnimatedSocket@2 FK differs"
                .to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_animated_glb_socket_transform_projection_v2_objects(
    connection: &Connection,
    projection: &GameWeaponAnimatedGlbSocketTransformProjectionV2,
    projection_object: &CasObjectRecord,
) -> Result<(), StoreError> {
    for (hash, mime, kinds, max_bytes, role) in [
        (
            projection.appearance_artifact_sha256.as_str(),
            "model/gltf-binary",
            &["appearance-glb", "appearance-v2-glb"][..],
            64 * 1024 * 1024,
            "appearance artifact",
        ),
        (
            projection.animated_artifact_sha256.as_str(),
            "model/gltf-binary",
            &[MECHANICAL_ANIMATION_GLB_V2_KIND][..],
            MAX_MECHANICAL_ANIMATION_GLB_V2_BYTES,
            "animated artifact",
        ),
        (
            projection.animation_receipt_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[MECHANICAL_ANIMATION_GLB_V2_RECEIPT_KIND][..],
            MAX_MECHANICAL_ANIMATION_GLB_V2_RECEIPT_BYTES,
            "animation receipt",
        ),
        (
            projection.animation_clip_object_sha256.as_str(),
            MECHANICAL_ANIMATION_CLIP_V2_MIME,
            &[MECHANICAL_ANIMATION_CLIP_V2_KIND][..],
            MAX_MECHANICAL_ANIMATION_CLIP_V2_BYTES,
            "Clip@2",
        ),
        (
            projection.anchor_set_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[GAME_WEAPON_ANCHOR_SET_KIND][..],
            MAX_GAME_ASSET_DELIVERY_JSON_BYTES,
            "AnchorSet",
        ),
        (
            projection.derived_animated_socket_artifact_sha256.as_str(),
            "model/gltf-binary",
            &[GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZED_GLB_V2_KIND][..],
            64 * 1024 * 1024,
            "derived animated socket artifact",
        ),
        (
            projection
                .derived_animated_socket_receipt_object_sha256
                .as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            &[GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_V2_RECEIPT_KIND][..],
            MAX_GAME_ASSET_DELIVERY_JSON_BYTES,
            "derived animated socket receipt",
        ),
    ] {
        ensure_game_weapon_animated_glb_socket_materialization_v2_object(
            connection, hash, mime, kinds, max_bytes, role,
        )?;
    }
    ensure_game_weapon_animated_glb_socket_materialization_v2_object(
        connection,
        &projection_object.sha256,
        GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_MIME,
        &[GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_KIND],
        MAX_GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_BYTES,
        "owned projection object",
    )?;
    let stored: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![projection_object.sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let expected_size = i64::try_from(projection_object.size_bytes).unwrap_or(i64::MAX);
    if stored
        .as_ref()
        .is_none_or(|(size, mime, kind, reachability)| {
            *size != expected_size
                || mime != &projection_object.mime
                || kind != &projection_object.kind
                || !matches!(reachability.as_str(), "temporary" | "reachable")
        })
    {
        return Err(StoreError::Contract {
            code:
                "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_OBJECT_METADATA_MISMATCH"
                    .to_owned(),
            message: "V2 projection object metadata differs from SQLite".to_owned(),
        });
    }
    Ok(())
}

fn projection_object_record(
    connection: &Connection,
    sha256: &str,
) -> Result<CasObjectRecord, StoreError> {
    connection
        .query_row(
            "SELECT sha256, size_bytes, mime, kind, reachability, created_at FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| {
                let size_bytes: i64 = row.get(1)?;
                Ok(CasObjectRecord {
                    schema_version: "CasObject@1".to_owned(),
                    sha256: row.get(0)?,
                    size_bytes: u64::try_from(size_bytes).map_err(|_| {
                        rusqlite::Error::FromSqlConversionFailure(
                            1,
                            rusqlite::types::Type::Integer,
                            "negative projection object size".into(),
                        )
                    })?,
                    mime: row.get(2)?,
                    kind: row.get(3)?,
                    reachability: row.get(4)?,
                    created_at: row.get(5)?,
                })
            },
        )
        .optional()?
        .ok_or_else(|| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_OBJECT_UNAVAILABLE"
                .to_owned(),
            message: "transform projection CAS object is not registered".to_owned(),
        })
}

fn validate_projection_receipt_field(
    object: &serde_json::Map<String, Value>,
    field: &str,
    expected: &str,
) -> bool {
    object.get(field).and_then(Value::as_str) == Some(expected)
}

fn validate_game_weapon_animated_glb_socket_transform_projection_source_receipts(
    animation_receipt_bytes: &[u8],
    derived_receipt_bytes: &[u8],
    projection: &GameWeaponAnimatedGlbSocketTransformProjection,
) -> Result<(), StoreError> {
    let animation_value: Value =
        serde_json::from_slice(animation_receipt_bytes).map_err(|error| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_SOURCE_RECEIPT_INVALID"
                .to_owned(),
            message: format!("source animation receipt JSON is invalid: {error}"),
        })?;
    let animation_object = animation_value
        .as_object()
        .ok_or_else(|| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_SOURCE_RECEIPT_INVALID"
                .to_owned(),
            message: "source animation receipt is not an object".to_owned(),
        })?;
    if !validate_projection_receipt_field(
        animation_object,
        "schema_version",
        "MechanicalAnimationGlbReceipt@1",
    ) || !validate_projection_receipt_field(
        animation_object,
        "project_id",
        &projection.project_id,
    ) || !validate_projection_receipt_field(
        animation_object,
        "candidate_id",
        &projection.candidate_id,
    ) || !validate_projection_receipt_field(
        animation_object,
        "candidate_state_sha256",
        &projection.candidate_state_sha256,
    ) || !validate_projection_receipt_field(
        animation_object,
        "source_artifact_sha256",
        &projection.source_artifact_sha256,
    ) || !validate_projection_receipt_field(
        animation_object,
        "artifact_readback_sha256",
        &projection.source_artifact_readback_sha256,
    ) || !validate_projection_receipt_field(
        animation_object,
        "animated_artifact_sha256",
        &projection.animated_artifact_sha256,
    ) || !validate_projection_receipt_field(
        animation_object,
        "clip_id",
        &projection.animation_clip_id,
    ) || !validate_projection_receipt_field(
        animation_object,
        "clip_object_sha256",
        &projection.animation_clip_object_sha256,
    ) || !validate_projection_receipt_field(
        animation_object,
        "clip_sha256",
        &projection.animation_clip_canonical_sha256,
    ) || animation_object.get("timebase_hz").and_then(Value::as_u64) != Some(1000)
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_SOURCE_RECEIPT_BINDING_MISMATCH"
                .to_owned(),
            message: "source animation receipt does not bind to the projection".to_owned(),
        });
    }

    let derived_value: Value =
        serde_json::from_slice(derived_receipt_bytes).map_err(|error| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_DERIVED_RECEIPT_INVALID"
                .to_owned(),
            message: format!("derived animated socket receipt JSON is invalid: {error}"),
        })?;
    let derived_object = derived_value
        .as_object()
        .ok_or_else(|| StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_DERIVED_RECEIPT_INVALID"
                .to_owned(),
            message: "derived animated socket receipt is not an object".to_owned(),
        })?;
    let derived_bindings = [
        (
            "schema_version",
            "GameWeaponAnimatedGlbSocketMaterializationReceipt@1",
        ),
        (
            "animated_socket_materialization_key_sha256",
            projection
                .animated_socket_materialization_key_sha256
                .as_str(),
        ),
        ("project_id", projection.project_id.as_str()),
        ("candidate_id", projection.candidate_id.as_str()),
        (
            "candidate_state_sha256",
            projection.candidate_state_sha256.as_str(),
        ),
        (
            "delivery_manifest_object_sha256",
            projection.delivery_manifest_object_sha256.as_str(),
        ),
        (
            "source_artifact_sha256",
            projection.source_artifact_sha256.as_str(),
        ),
        (
            "source_artifact_readback_sha256",
            projection.source_artifact_readback_sha256.as_str(),
        ),
        (
            "animated_artifact_sha256",
            projection.animated_artifact_sha256.as_str(),
        ),
        (
            "animated_artifact_readback_sha256",
            projection.animated_artifact_readback_sha256.as_str(),
        ),
        (
            "animation_receipt_object_sha256",
            projection.animation_receipt_object_sha256.as_str(),
        ),
        (
            "animation_receipt_canonical_sha256",
            projection.animation_receipt_canonical_sha256.as_str(),
        ),
        (
            "anchor_set_object_sha256",
            projection.anchor_set_object_sha256.as_str(),
        ),
        (
            "anchor_set_canonical_sha256",
            projection.anchor_set_canonical_sha256.as_str(),
        ),
        (
            "derived_animated_socket_artifact_sha256",
            projection.derived_animated_socket_artifact_sha256.as_str(),
        ),
        (
            "derived_animated_socket_artifact_readback_sha256",
            projection
                .derived_animated_socket_artifact_readback_sha256
                .as_str(),
        ),
        (
            "socket_node_id_encoding_sha256",
            projection.socket_node_id_encoding_sha256.as_str(),
        ),
        (
            "materialization_status",
            GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_STATUS,
        ),
        ("quality_status", "structural_only"),
    ];
    if derived_bindings.iter().any(|(field, expected)| {
        !validate_projection_receipt_field(derived_object, field, expected)
    }) || derived_object
        .get("socket_node_count")
        .and_then(Value::as_u64)
        != Some(6)
        || derived_object
            .get("runtime_write_performed")
            .and_then(Value::as_bool)
            != Some(true)
        || derived_object
            .get("restart_hash_verified")
            .and_then(Value::as_bool)
            != Some(true)
        || derived_object
            .get("candidate_confirmed")
            .and_then(Value::as_bool)
            != Some(false)
        || derived_object
            .get("export_performed")
            .and_then(Value::as_bool)
            != Some(false)
        || derived_object
            .get("actual_engine_roundtrip")
            .and_then(Value::as_bool)
            != Some(false)
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_DERIVED_RECEIPT_BINDING_MISMATCH"
                .to_owned(),
            message: "derived animated socket receipt does not bind to the projection".to_owned(),
        });
    }
    if animation_receipt_bytes
        != canonical_json_bytes(&animation_value)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?
        || derived_receipt_bytes
            != canonical_json_bytes(&derived_value)
                .map_err(|error| StoreError::InvalidData(error.to_string()))?
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_RECEIPT_CANONICAL_MISMATCH"
                .to_owned(),
            message: "source or derived socket receipt is not canonical JSON".to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_animated_glb_socket_transform_projection_object(
    connection: &Connection,
    object: &CasObjectRecord,
) -> Result<(), StoreError> {
    let stored: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![object.sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((size_bytes, mime, kind, reachability)) = stored else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_OBJECT_UNAVAILABLE"
                .to_owned(),
            message: "transform projection CAS object is not registered".to_owned(),
        });
    };
    if size_bytes != i64::try_from(object.size_bytes).unwrap_or(i64::MAX)
        || mime != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_MIME
        || kind != GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_KIND
        || !matches!(reachability.as_str(), "temporary" | "reachable")
        || object.size_bytes == 0
        || object.size_bytes > MAX_GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_BYTES
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_OBJECT_METADATA_MISMATCH"
                .to_owned(),
            message: "transform projection CAS metadata differs from SQLite".to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_animated_glb_socket_transform_projection_objects(
    connection: &Connection,
    projection: &GameWeaponAnimatedGlbSocketTransformProjection,
    projection_object: &CasObjectRecord,
) -> Result<(), StoreError> {
    ensure_game_weapon_animated_glb_socket_source_object(
        connection,
        &projection.source_artifact_sha256,
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &projection.animated_artifact_sha256,
        "model/gltf-binary",
        "mechanical-animation-glb",
        64 * 1024 * 1024,
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &projection.animation_receipt_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        "mechanical-animation-glb-receipt",
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &projection.derived_animated_socket_artifact_sha256,
        "model/gltf-binary",
        GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZED_GLB_KIND,
        64 * 1024 * 1024,
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &projection.derived_animated_socket_receipt_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_RECEIPT_KIND,
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &projection.anchor_set_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        GAME_WEAPON_ANCHOR_SET_KIND,
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    ensure_game_weapon_animated_glb_socket_object(
        connection,
        &projection.animation_clip_object_sha256,
        MECHANICAL_ANIMATION_CLIP_MIME,
        MECHANICAL_ANIMATION_CLIP_KIND,
        i64::try_from(MAX_MECHANICAL_ANIMATION_CLIP_BYTES).unwrap_or(i64::MAX),
    )?;
    ensure_game_weapon_animated_glb_socket_transform_projection_object(
        connection,
        projection_object,
    )?;
    Ok(())
}

fn validate_game_weapon_animated_glb_socket_transform_projection_binding_in_transaction(
    connection: &Connection,
    projection: &GameWeaponAnimatedGlbSocketTransformProjection,
) -> Result<(), StoreError> {
    let delivery: Option<(String, String, String, Option<String>)> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256, animation_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![projection.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((delivery_project, delivery_candidate, delivery_artifact, delivery_animation)) =
        delivery
    else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_DELIVERY_BINDING_MISMATCH"
                .to_owned(),
            message: "projection delivery link is unavailable".to_owned(),
        });
    };
    if delivery_project != projection.project_id
        || delivery_candidate != projection.candidate_id
        || delivery_artifact != projection.source_artifact_sha256
        || delivery_animation
            .as_deref()
            .is_some_and(|animation| animation != projection.animated_artifact_sha256)
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_DELIVERY_BINDING_MISMATCH"
                .to_owned(),
            message: "projection delivery/candidate/source animation binding differs".to_owned(),
        });
    }

    let candidate: Option<(String, String, Option<String>, Option<String>)> = connection
        .query_row(
            "SELECT project_id, canonical_sha256, prepared_object_sha256, manifest_hash FROM candidates WHERE candidate_id = ?1",
            params![projection.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((candidate_project, candidate_state, prepared, manifest)) = candidate else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_CANDIDATE_BINDING_MISMATCH"
                .to_owned(),
            message: "projection candidate is unavailable".to_owned(),
        });
    };
    if candidate_project != projection.project_id
        || candidate_state != projection.candidate_state_sha256
        || prepared.as_deref() != Some(projection.source_artifact_sha256.as_str())
        || manifest.as_deref() != Some(projection.source_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_CANDIDATE_BINDING_MISMATCH"
                .to_owned(),
            message: "projection candidate/state/source binding differs".to_owned(),
        });
    }

    let animated_socket: Option<(
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
        String,
    )> = connection
        .query_row(
            "SELECT project_id, candidate_id, candidate_state_sha256, delivery_manifest_object_sha256, source_artifact_sha256, animated_artifact_sha256, animation_receipt_object_sha256, animation_receipt_canonical_sha256, anchor_set_object_sha256, anchor_set_canonical_sha256, derived_animated_socket_artifact_sha256, derived_animated_socket_artifact_readback_sha256, receipt_object_sha256, animated_socket_materialization_key_sha256, lod_scope FROM game_weapon_animated_glb_socket_materialization_links WHERE animated_socket_materialization_key_sha256 = ?1",
            params![projection.animated_socket_materialization_key_sha256],
            |row| {
                Ok((
                    row.get(0)?,
                    row.get(1)?,
                    row.get(2)?,
                    row.get(3)?,
                    row.get(4)?,
                    row.get(5)?,
                    row.get(6)?,
                    row.get(7)?,
                    row.get(8)?,
                    row.get(9)?,
                    row.get(10)?,
                    row.get(11)?,
                    row.get(12)?,
                    row.get(13)?,
                    row.get(14)?,
                ))
            },
        )
        .optional()?;
    let Some(animated_socket) = animated_socket else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_SOCKET_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket materialization link is unavailable".to_owned(),
        });
    };
    if animated_socket.0 != projection.project_id
        || animated_socket.1 != projection.candidate_id
        || animated_socket.2 != projection.candidate_state_sha256
        || animated_socket.3 != projection.delivery_manifest_object_sha256
        || animated_socket.4 != projection.source_artifact_sha256
        || animated_socket.5 != projection.animated_artifact_sha256
        || animated_socket.6 != projection.animation_receipt_object_sha256
        || animated_socket.7 != projection.animation_receipt_canonical_sha256
        || animated_socket.8 != projection.anchor_set_object_sha256
        || animated_socket.9 != projection.anchor_set_canonical_sha256
        || animated_socket.10 != projection.derived_animated_socket_artifact_sha256
        || animated_socket.11 != projection.derived_animated_socket_artifact_readback_sha256
        || animated_socket.12 != projection.derived_animated_socket_receipt_object_sha256
        || animated_socket.13 != projection.animated_socket_materialization_key_sha256
        || animated_socket.14 != GAME_WEAPON_ANIMATED_GLB_SOCKET_MATERIALIZATION_LOD_SCOPE
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_SOCKET_BINDING_MISMATCH"
                .to_owned(),
            message: "projection animated socket source/derived binding differs".to_owned(),
        });
    }

    let anchor: Option<(String, String)> = connection
        .query_row(
            "SELECT project_id, anchor_set_object_sha256 FROM game_weapon_anchor_links WHERE delivery_manifest_object_sha256 = ?1",
            params![projection.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if anchor.as_ref().map(|value| value.0.as_str()) != Some(projection.project_id.as_str())
        || anchor.as_ref().map(|value| value.1.as_str())
            != Some(projection.anchor_set_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_ANCHOR_BINDING_MISMATCH"
                .to_owned(),
            message: "projection AnchorSet differs from durable anchor link".to_owned(),
        });
    }

    let clip: Option<(String, String, String, String, String)> = connection
        .query_row(
            "SELECT project_id, candidate_id, artifact_id, clip_object_sha256, clip_sha256 FROM mechanical_animation_clip_links WHERE candidate_id = ?1 AND clip_id = ?2",
            params![projection.candidate_id, projection.animation_clip_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .optional()?;
    if clip.as_ref().map(|value| value.0.as_str()) != Some(projection.project_id.as_str())
        || clip.as_ref().map(|value| value.1.as_str()) != Some(projection.candidate_id.as_str())
        || clip.as_ref().map(|value| value.2.as_str())
            != Some(projection.source_artifact_sha256.as_str())
        || clip.as_ref().map(|value| value.3.as_str())
            != Some(projection.animation_clip_object_sha256.as_str())
        || clip.as_ref().map(|value| value.4.as_str())
            != Some(projection.animation_clip_canonical_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_CLIP_BINDING_MISMATCH"
                .to_owned(),
            message: "projection animation clip binding differs".to_owned(),
        });
    }
    Ok(())
}

fn validate_game_weapon_glb_socket_materialization_link(
    link: &GameWeaponGlbSocketMaterializationLinkRecord,
    lods: &[GameWeaponGlbSocketMaterializationLodRecord],
) -> Result<(), StoreError> {
    let mut canonical = link.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if link.schema_version != "GameWeaponGlbSocketMaterializationLink@1"
        || !is_sha256(&link.socket_materialization_key_sha256)
        || !is_opaque_id(&link.project_id)
        || !is_sha256(&link.delivery_manifest_object_sha256)
        || !is_sha256(&link.anchor_set_object_sha256)
        || !is_sha256(&link.anchor_set_canonical_sha256)
        || !is_sha256(&link.request_sha256)
        || link.socket_materialization_policy != GAME_WEAPON_GLB_SOCKET_MATERIALIZATION_POLICY
        || link.lod_scope != GAME_WEAPON_GLB_SOCKET_MATERIALIZATION_LOD_SCOPE
        || !is_sha256(&link.socket_node_id_encoding_sha256)
        || !is_sha256(&link.receipt_object_sha256)
        || link.materialization_status != GAME_WEAPON_GLB_SOCKET_MATERIALIZATION_STATUS
        || link.canonical_sha256 != expected_canonical
        || link.created_at.is_empty()
        || link.created_at.len() > 128
        || lods.len() != 3
    {
        return Err(StoreError::InvalidData(
            "game weapon GLB socket materialization link is malformed".to_owned(),
        ));
    }
    let mut levels = [false; 3];
    for lod in lods {
        validate_game_weapon_glb_socket_materialization_lod(lod)?;
        if lod.socket_materialization_key_sha256 != link.socket_materialization_key_sha256
            || lod.lod_level > 2
        {
            return Err(StoreError::InvalidData(
                "game weapon GLB socket materialization LOD key differs".to_owned(),
            ));
        }
        let level = usize::try_from(lod.lod_level).map_err(|_| {
            StoreError::InvalidData(
                "game weapon GLB socket materialization LOD is invalid".to_owned(),
            )
        })?;
        if std::mem::replace(&mut levels[level], true) {
            return Err(StoreError::InvalidData(
                "game weapon GLB socket materialization LOD levels must be unique".to_owned(),
            ));
        }
    }
    if levels != [true, true, true] {
        return Err(StoreError::InvalidData(
            "game weapon GLB socket materialization requires exact LOD0/LOD1/LOD2".to_owned(),
        ));
    }
    Ok(())
}

fn validate_game_weapon_glb_socket_materialization_lod(
    lod: &GameWeaponGlbSocketMaterializationLodRecord,
) -> Result<(), StoreError> {
    let mut canonical = lod.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if lod.schema_version != "GameWeaponGlbSocketMaterializationLod@1"
        || !is_sha256(&lod.socket_materialization_key_sha256)
        || lod.lod_level > 2
        || !is_opaque_id(&lod.source_candidate_id)
        || !is_sha256(&lod.source_candidate_state_sha256)
        || !is_sha256(&lod.source_artifact_sha256)
        || !is_sha256(&lod.source_artifact_readback_sha256)
        || !is_sha256(&lod.derived_artifact_sha256)
        || !is_sha256(&lod.derived_artifact_readback_sha256)
        || !is_sha256(&lod.source_renderable_inventory_sha256)
        || !is_sha256(&lod.derived_renderable_inventory_sha256)
        || !is_sha256(&lod.socket_node_inventory_sha256)
        || lod.canonical_sha256 != expected_canonical
        || lod.created_at.is_empty()
        || lod.created_at.len() > 128
    {
        return Err(StoreError::InvalidData(
            "game weapon GLB socket materialization LOD is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn game_weapon_glb_socket_materialization_link_from_row(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<GameWeaponGlbSocketMaterializationLinkRecord> {
    Ok(GameWeaponGlbSocketMaterializationLinkRecord {
        schema_version: "GameWeaponGlbSocketMaterializationLink@1".to_owned(),
        socket_materialization_key_sha256: row.get(0)?,
        project_id: row.get(1)?,
        delivery_manifest_object_sha256: row.get(2)?,
        anchor_set_object_sha256: row.get(3)?,
        anchor_set_canonical_sha256: row.get(4)?,
        request_sha256: row.get(5)?,
        socket_materialization_policy: row.get(6)?,
        lod_scope: row.get(7)?,
        socket_node_id_encoding_sha256: row.get(8)?,
        receipt_object_sha256: row.get(9)?,
        materialization_status: row.get(10)?,
        canonical_sha256: row.get(11)?,
        created_at: row.get(12)?,
    })
}

fn game_weapon_glb_socket_materialization_lod_from_row(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<GameWeaponGlbSocketMaterializationLodRecord> {
    let lod_level: i64 = row.get(1)?;
    let lod_level = u64::try_from(lod_level).map_err(|error| {
        rusqlite::Error::FromSqlConversionFailure(
            1,
            rusqlite::types::Type::Integer,
            Box::new(error),
        )
    })?;
    Ok(GameWeaponGlbSocketMaterializationLodRecord {
        schema_version: "GameWeaponGlbSocketMaterializationLod@1".to_owned(),
        socket_materialization_key_sha256: row.get(0)?,
        lod_level,
        source_candidate_id: row.get(2)?,
        source_candidate_state_sha256: row.get(3)?,
        source_artifact_sha256: row.get(4)?,
        source_artifact_readback_sha256: row.get(5)?,
        derived_artifact_sha256: row.get(6)?,
        derived_artifact_readback_sha256: row.get(7)?,
        source_renderable_inventory_sha256: row.get(8)?,
        derived_renderable_inventory_sha256: row.get(9)?,
        socket_node_inventory_sha256: row.get(10)?,
        canonical_sha256: row.get(11)?,
        created_at: row.get(12)?,
    })
}

fn read_game_weapon_glb_socket_materialization_lods(
    connection: &Connection,
    key: &str,
) -> Result<Vec<GameWeaponGlbSocketMaterializationLodRecord>, StoreError> {
    let mut statement = connection.prepare(
        "SELECT socket_materialization_key_sha256, lod_level, source_candidate_id, source_candidate_state_sha256, source_artifact_sha256, source_artifact_readback_sha256, derived_artifact_sha256, derived_artifact_readback_sha256, source_renderable_inventory_sha256, derived_renderable_inventory_sha256, socket_node_inventory_sha256, canonical_sha256, created_at FROM game_weapon_glb_socket_materialization_lods WHERE socket_materialization_key_sha256 = ?1 ORDER BY lod_level ASC",
    )?;
    let rows = statement.query_map(
        params![key],
        game_weapon_glb_socket_materialization_lod_from_row,
    )?;
    Ok(rows.collect::<Result<Vec<_>, _>>()?)
}

fn same_game_weapon_glb_socket_materialization_link(
    left: &GameWeaponGlbSocketMaterializationLinkRecord,
    right: &GameWeaponGlbSocketMaterializationLinkRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

fn same_game_weapon_glb_socket_materialization_lods(
    left: &[GameWeaponGlbSocketMaterializationLodRecord],
    right: &[GameWeaponGlbSocketMaterializationLodRecord],
) -> bool {
    if left.len() != right.len() {
        return false;
    }
    left.iter().zip(right).all(|(left, right)| {
        let mut left = left.clone();
        let mut right = right.clone();
        left.created_at.clear();
        right.created_at.clear();
        left.canonical_sha256.clear();
        right.canonical_sha256.clear();
        left == right
    })
}

fn game_weapon_glb_socket_materialization_reachable_hashes(
    link: &GameWeaponGlbSocketMaterializationLinkRecord,
    lods: &[GameWeaponGlbSocketMaterializationLodRecord],
) -> Vec<String> {
    let mut hashes = vec![link.receipt_object_sha256.clone()];
    hashes.extend(lods.iter().map(|lod| lod.derived_artifact_sha256.clone()));
    hashes
}

fn ensure_game_weapon_glb_socket_materialization_object(
    connection: &Connection,
    sha256: &str,
    expected_mime: &str,
    expected_kind: &str,
    max_bytes: i64,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= max_bytes
            && mime == expected_mime
            && kind == expected_kind
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_CAS_OBJECT_INVALID".to_owned(),
            message: "socket materialization CAS metadata is missing or differs".to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_glb_socket_source_object(
    connection: &Connection,
    sha256: &str,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= 64 * 1024 * 1024
            && mime == "model/gltf-binary"
            && matches!(
                kind.as_str(),
                "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
            )
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_SOURCE_ARTIFACT_INVALID".to_owned(),
            message: "socket materialization source GLB metadata is invalid".to_owned(),
        });
    }
    Ok(())
}

fn ensure_game_weapon_glb_socket_materialization_objects(
    connection: &Connection,
    link: &GameWeaponGlbSocketMaterializationLinkRecord,
    lods: &[GameWeaponGlbSocketMaterializationLodRecord],
) -> Result<(), StoreError> {
    ensure_game_weapon_glb_socket_materialization_object(
        connection,
        &link.anchor_set_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        GAME_WEAPON_ANCHOR_SET_KIND,
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    ensure_game_weapon_glb_socket_materialization_object(
        connection,
        &link.receipt_object_sha256,
        GAME_ASSET_DELIVERY_JSON_MIME,
        GAME_WEAPON_GLB_SOCKET_MATERIALIZATION_RECEIPT_KIND,
        i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
    )?;
    for lod in lods {
        ensure_game_weapon_glb_socket_source_object(connection, &lod.source_artifact_sha256)?;
        ensure_game_weapon_glb_socket_materialization_object(
            connection,
            &lod.derived_artifact_sha256,
            "model/gltf-binary",
            GAME_WEAPON_GLB_SOCKET_MATERIALIZED_GLB_KIND,
            64 * 1024 * 1024,
        )?;
    }
    Ok(())
}

fn validate_game_weapon_glb_socket_materialization_binding_in_transaction(
    connection: &Connection,
    link: &GameWeaponGlbSocketMaterializationLinkRecord,
    lods: &[GameWeaponGlbSocketMaterializationLodRecord],
) -> Result<(), StoreError> {
    let delivery: Option<(String, [String; 3], [String; 3])> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod1_candidate_id, lod2_candidate_id, lod0_artifact_sha256, lod1_artifact_sha256, lod2_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| {
                Ok((
                    row.get(0)?,
                    [row.get(1)?, row.get(2)?, row.get(3)?],
                    [row.get(4)?, row.get(5)?, row.get(6)?],
                ))
            },
        )
        .optional()?;
    let Some((delivery_project, delivery_candidates, delivery_artifacts)) = delivery else {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_DELIVERY_BINDING_MISMATCH".to_owned(),
            message: "socket materialization delivery link is unavailable".to_owned(),
        });
    };
    if delivery_project != link.project_id {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_DELIVERY_BINDING_MISMATCH".to_owned(),
            message: "socket materialization project differs from delivery".to_owned(),
        });
    }
    let anchor: Option<(String, String)> = connection
        .query_row(
            "SELECT project_id, anchor_set_object_sha256 FROM game_weapon_anchor_links WHERE delivery_manifest_object_sha256 = ?1",
            params![link.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    if anchor.as_ref().map(|value| value.0.as_str()) != Some(link.project_id.as_str())
        || anchor.as_ref().map(|value| value.1.as_str())
            != Some(link.anchor_set_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "GAME_WEAPON_GLB_SOCKET_ANCHOR_BINDING_MISMATCH".to_owned(),
            message: "socket materialization AnchorSet differs from durable anchor link".to_owned(),
        });
    }
    for lod in lods {
        let level = usize::try_from(lod.lod_level).map_err(|_| {
            StoreError::InvalidData("socket materialization LOD level is invalid".to_owned())
        })?;
        let candidate: Option<(String, String, Option<String>, Option<String>)> = connection
            .query_row(
                "SELECT project_id, canonical_sha256, prepared_object_sha256, manifest_hash FROM candidates WHERE candidate_id = ?1",
                params![lod.source_candidate_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .optional()?;
        let Some((candidate_project, candidate_state, prepared, manifest)) = candidate else {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_GLB_SOCKET_CANDIDATE_BINDING_MISMATCH".to_owned(),
                message: "socket materialization source candidate is unavailable".to_owned(),
            });
        };
        if candidate_project != link.project_id
            || candidate_state != lod.source_candidate_state_sha256
            || prepared.as_deref() != Some(lod.source_artifact_sha256.as_str())
            || manifest.as_deref() != Some(lod.source_artifact_sha256.as_str())
            || delivery_candidates[level] != lod.source_candidate_id
            || delivery_artifacts[level] != lod.source_artifact_sha256
        {
            return Err(StoreError::Contract {
                code: "GAME_WEAPON_GLB_SOCKET_CANDIDATE_BINDING_MISMATCH".to_owned(),
                message:
                    "socket materialization source candidate/artifact binding differs from delivery"
                        .to_owned(),
            });
        }
    }
    Ok(())
}

