fn ensure_fictional_energy_vfx_frame_objects(
    connection: &Connection,
    link: &FictionalEnergyVfxFrameLinkRecord,
) -> Result<(), StoreError> {
    let json_objects = [
        (
            link.camera_object_sha256.as_str(),
            FICTIONAL_ENERGY_VFX_CAMERA_KIND,
        ),
        (
            link.render_set_object_sha256.as_str(),
            FICTIONAL_ENERGY_VFX_RENDER_SET_KIND,
        ),
        (
            link.receipt_object_sha256.as_str(),
            FICTIONAL_ENERGY_VFX_FRAME_RECEIPT_KIND,
        ),
    ];
    for (sha256, expected_kind) in json_objects {
        ensure_fictional_energy_vfx_frame_object(
            connection,
            sha256,
            "application/json",
            expected_kind,
            i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
        )?;
    }
    let pass_names = [
        "beauty",
        "silhouette",
        "depth",
        "normal",
        "ao",
        "part-id",
        "material-id",
        "wireframe",
        "uv-stretch",
    ];
    for (hash, pass) in link.pass_object_sha256s.iter().zip(pass_names) {
        ensure_fictional_energy_vfx_frame_object(
            connection,
            hash,
            "image/png",
            &format!("{FICTIONAL_ENERGY_VFX_PASS_KIND_PREFIX}{pass}"),
            MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES,
        )?;
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_frame_object(
    connection: &Connection,
    sha256: &str,
    expected_mime: &str,
    expected_kind: &str,
    max_bytes: i64,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= max_bytes
            && mime == expected_mime
            && kind == expected_kind
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_FRAME_CAS_OBJECT_INVALID".to_owned(),
            message: "frame CAS metadata is missing or differs from its fixed kind".to_owned(),
        });
    }
    Ok(())
}

