fn ensure_fictional_energy_vfx_particles_frame_objects(
    connection: &Connection,
    link: &FictionalEnergyVfxParticlesFrameLinkRecord,
) -> Result<(), StoreError> {
    for (hash, kind) in [
        (
            link.render_set_object_sha256.as_str(),
            FICTIONAL_ENERGY_VFX_PARTICLES_RENDER_SET_KIND,
        ),
        (
            link.receipt_object_sha256.as_str(),
            FICTIONAL_ENERGY_VFX_PARTICLES_FRAME_RECEIPT_KIND,
        ),
    ] {
        ensure_fictional_energy_vfx_frame_object(
            connection,
            hash,
            "application/json",
            kind,
            i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
        )?;
    }
    for (hash, kind) in [
        (
            link.particle_color_object_sha256.as_str(),
            FICTIONAL_ENERGY_VFX_PARTICLES_COLOR_KIND,
        ),
        (
            link.particle_id_object_sha256.as_str(),
            FICTIONAL_ENERGY_VFX_PARTICLES_ID_KIND,
        ),
        (
            link.particle_depth_object_sha256.as_str(),
            FICTIONAL_ENERGY_VFX_PARTICLES_DEPTH_KIND,
        ),
    ] {
        ensure_fictional_energy_vfx_frame_object(
            connection,
            hash,
            "image/png",
            kind,
            MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES,
        )?;
    }
    Ok(())
}

fn validate_fictional_energy_vfx_trails_frame_link(
    link: &FictionalEnergyVfxTrailsFrameLinkRecord,
) -> Result<(), StoreError> {
    let mut canonical = link.clone();
    canonical.canonical_sha256.clear();
    let expected = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let history_valid = (1..=4).contains(&link.particle_history_key_sha256s.len())
        && link
            .particle_history_key_sha256s
            .iter()
            .all(|value| is_sha256(value))
        && link
            .particle_history_key_sha256s
            .iter()
            .collect::<HashSet<_>>()
            .len()
            == link.particle_history_key_sha256s.len()
        && !link
            .particle_history_key_sha256s
            .contains(&link.current_particle_key_sha256);
    if link.schema_version != "FictionalEnergyVfxTrailsFrameLink@1"
        || !is_sha256(&link.trail_key_sha256)
        || !is_opaque_id(&link.project_id)
        || !is_sha256(&link.delivery_manifest_object_sha256)
        || !is_sha256(&link.vfx_profile_object_sha256)
        || !is_sha256(&link.anchor_set_object_sha256)
        || !is_opaque_id(&link.source_candidate_id)
        || !is_sha256(&link.source_artifact_sha256)
        || !is_sha256(&link.sample_request_sha256)
        || !is_sha256(&link.base_frame_key_sha256)
        || !is_sha256(&link.bloom_key_sha256)
        || !is_sha256(&link.current_particle_key_sha256)
        || !history_valid
        || !is_sha256(&link.camera_object_sha256)
        || !is_sha256(&link.camera_identity_sha256)
        || !is_sha256(&link.render_profile_sha256)
        || !is_sha256(&link.render_worker_build_cohort_sha256)
        || !is_sha256(&link.trail_seed_sha256)
        || !is_sha256(&link.node_inventory_sha256)
        || !is_sha256(&link.owner_world_transform_sha256)
        || !is_sha256(&link.trail_inventory_sha256)
        || !is_sha256(&link.trail_id_encoding_sha256)
        || !is_sha256(&link.render_set_object_sha256)
        || !is_sha256(&link.receipt_object_sha256)
        || !is_sha256(&link.trail_color_object_sha256)
        || !is_sha256(&link.trail_id_object_sha256)
        || !is_sha256(&link.trail_depth_object_sha256)
        || link.materialization_status
            != "runtime-owned-durable-fictional-energy-vfx-typed-trails-frame"
        || link.canonical_sha256 != expected
        || link.created_at.is_empty()
        || link.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "fictional energy VFX typed trails link is malformed".to_owned(),
        ));
    }
    Ok(())
}

