fn validate_fictional_energy_vfx_animated_socket_attachment(
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentRecord,
) -> Result<(), StoreError> {
    let mut canonical = attachment.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if attachment.schema_version != "FictionalEnergyVfxAnimatedSocketAttachment@1"
        || !is_sha256(&attachment.attachment_key_sha256)
        || !is_opaque_id(&attachment.project_id)
        || !is_sha256(&attachment.delivery_manifest_object_sha256)
        || !is_opaque_id(&attachment.candidate_id)
        || !is_sha256(&attachment.candidate_state_sha256)
        || !is_sha256(&attachment.source_artifact_sha256)
        || !is_sha256(&attachment.animated_socket_materialization_key_sha256)
        || !is_sha256(&attachment.animated_socket_anchor_set_object_sha256)
        || !is_sha256(&attachment.animated_socket_anchor_set_canonical_sha256)
        || !is_opaque_id(&attachment.animation_clip_id)
        || !is_sha256(&attachment.animation_clip_object_sha256)
        || !is_sha256(&attachment.animation_clip_canonical_sha256)
        || !is_sha256(&attachment.animated_artifact_sha256)
        || !is_sha256(&attachment.animation_receipt_object_sha256)
        || !is_sha256(&attachment.animation_receipt_canonical_sha256)
        || !is_sha256(&attachment.vfx_profile_object_sha256)
        || !is_sha256(&attachment.vfx_profile_canonical_sha256)
        || !is_sha256(&attachment.vfx_sequence_key_sha256)
        || !is_sha256(&attachment.vfx_sequence_canonical_sha256)
        || attachment.attachment_policy != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_POLICY
        || !is_sha256(&attachment.socket_node_id_encoding_sha256)
        || !is_sha256(&attachment.socket_roles_sha256)
        || attachment.frame_scope != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_FRAME_SCOPE
        || attachment.frames.is_empty()
        || attachment.frames.len() > 16
        || attachment.attachment_status != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_STATUS
        || attachment.canonical_sha256 != expected_canonical
        || attachment.created_at.is_empty()
        || attachment.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "fictional energy VFX animated socket attachment is malformed".to_owned(),
        ));
    }
    let mut previous_sample_time = None;
    for (ordinal, frame) in attachment.frames.iter().enumerate() {
        validate_fictional_energy_vfx_animated_socket_attachment_frame(
            frame,
            &attachment.attachment_key_sha256,
            ordinal,
        )?;
        if previous_sample_time.is_some_and(|previous| previous >= frame.sample_time_ticks) {
            return Err(StoreError::InvalidData(
                "animated socket attachment frame sample times must be strictly increasing"
                    .to_owned(),
            ));
        }
        previous_sample_time = Some(frame.sample_time_ticks);
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_attachment_frame(
    frame: &FictionalEnergyVfxAnimatedSocketAttachmentFrameRecord,
    attachment_key_sha256: &str,
    ordinal: usize,
) -> Result<(), StoreError> {
    let mut canonical = frame.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    if frame.schema_version != "FictionalEnergyVfxAnimatedSocketAttachmentFrame@1"
        || frame.attachment_key_sha256 != attachment_key_sha256
        || frame.frame_index != ordinal as u64
        || frame.frame_index > 15
        || frame.sample_time_ticks > 1_000_000
        || !is_sha256(&frame.animation_pose_readback_sha256)
        || !is_sha256(&frame.socket_transform_inventory_sha256)
        || !is_sha256(&frame.socket_transform_readback_sha256)
        || !is_sha256(&frame.emitter_socket_bindings_sha256)
        || !is_sha256(&frame.trail_socket_bindings_sha256)
        || !is_sha256(&frame.base_frame_key_sha256)
        || !is_sha256(&frame.bloom_key_sha256)
        || !is_sha256(&frame.particle_key_sha256)
        || !is_sha256(&frame.trail_key_sha256)
        || !is_sha256(&frame.trail_bloom_key_sha256)
        || frame.canonical_sha256 != expected_canonical
        || frame.created_at.is_empty()
        || frame.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "fictional energy VFX animated socket attachment frame is malformed".to_owned(),
        ));
    }
    Ok(())
}

