fn validate_fictional_energy_vfx_animated_socket_attachment_v2(
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentV2Record,
) -> Result<(), StoreError> {
    let mut canonical = attachment.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let hash_fields = [
        attachment.attachment_key_sha256.as_str(),
        attachment.delivery_manifest_object_sha256.as_str(),
        attachment.candidate_state_sha256.as_str(),
        attachment.source_artifact_sha256.as_str(),
        attachment
            .animated_socket_materialization_key_sha256
            .as_str(),
        attachment.animated_socket_anchor_set_object_sha256.as_str(),
        attachment
            .animated_socket_anchor_set_canonical_sha256
            .as_str(),
        attachment.animation_clip_object_sha256.as_str(),
        attachment.animation_clip_canonical_sha256.as_str(),
        attachment.animated_artifact_sha256.as_str(),
        attachment.animation_receipt_object_sha256.as_str(),
        attachment.animation_receipt_canonical_sha256.as_str(),
        attachment.vfx_profile_object_sha256.as_str(),
        attachment.vfx_profile_canonical_sha256.as_str(),
        attachment.projection_key_sha256.as_str(),
        attachment.projection_object_sha256.as_str(),
        attachment.projection_canonical_sha256.as_str(),
        attachment.particle_sequence_key_sha256.as_str(),
        attachment.particle_sequence_canonical_sha256.as_str(),
        attachment.trail_sequence_key_sha256.as_str(),
        attachment.trail_sequence_canonical_sha256.as_str(),
        attachment.trail_bloom_sequence_key_sha256.as_str(),
        attachment.trail_bloom_sequence_canonical_sha256.as_str(),
        attachment.socket_node_id_encoding_sha256.as_str(),
        attachment.socket_roles_sha256.as_str(),
    ];
    if attachment.schema_version != "FictionalEnergyVfxAnimatedSocketAttachment@2"
        || !is_opaque_id(&attachment.project_id)
        || !is_opaque_id(&attachment.candidate_id)
        || !is_opaque_id(&attachment.animation_clip_id)
        || hash_fields.iter().any(|value| !is_sha256(value))
        || attachment.attachment_policy != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_POLICY
        || attachment.frame_scope != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_FRAME_SCOPE
        || attachment.frames.is_empty()
        || attachment.frames.len() > 15
        || attachment.attachment_status != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_STATUS
        || attachment.canonical_sha256 != expected_canonical
        || attachment.created_at.is_empty()
        || attachment.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "fictional energy VFX animated socket attachment V2 is malformed".to_owned(),
        ));
    }
    let mut previous_sample_time = None;
    for (ordinal, frame) in attachment.frames.iter().enumerate() {
        validate_fictional_energy_vfx_animated_socket_attachment_v2_frame(
            frame,
            &attachment.attachment_key_sha256,
            ordinal,
        )?;
        if previous_sample_time.is_some_and(|previous| previous >= frame.sample_time_ticks) {
            return Err(StoreError::InvalidData(
                "animated socket attachment V2 frame sample times must be strictly increasing"
                    .to_owned(),
            ));
        }
        previous_sample_time = Some(frame.sample_time_ticks);
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_attachment_v2_frame(
    frame: &FictionalEnergyVfxAnimatedSocketAttachmentV2FrameRecord,
    attachment_key_sha256: &str,
    ordinal: usize,
) -> Result<(), StoreError> {
    let mut canonical = frame.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let hashes = [
        frame.animation_pose_readback_sha256.as_str(),
        frame.socket_transform_inventory_sha256.as_str(),
        frame.socket_transform_readback_sha256.as_str(),
        frame.emitter_socket_bindings_sha256.as_str(),
        frame.trail_socket_bindings_sha256.as_str(),
        frame.base_frame_key_sha256.as_str(),
        frame.bloom_key_sha256.as_str(),
        frame.particle_key_sha256.as_str(),
        frame.trail_key_sha256.as_str(),
        frame.trail_bloom_key_sha256.as_str(),
        frame.projection_frame_canonical_sha256.as_str(),
        frame.particle_sequence_frame_canonical_sha256.as_str(),
        frame.trail_sequence_frame_canonical_sha256.as_str(),
        frame.trail_bloom_sequence_frame_canonical_sha256.as_str(),
    ];
    if frame.schema_version != "FictionalEnergyVfxAnimatedSocketAttachmentFrame@2"
        || frame.attachment_key_sha256 != attachment_key_sha256
        || frame.frame_index != ordinal as u64
        || frame.frame_index > 14
        || frame.projection_frame_index != frame.frame_index + 1
        || frame.particle_sequence_frame_index != frame.frame_index + 1
        || frame.projection_frame_index > 15
        || frame.particle_sequence_frame_index > 15
        || frame.sample_time_ticks > 1_000_000
        || hashes.iter().any(|value| !is_sha256(value))
        || frame.canonical_sha256 != expected_canonical
        || frame.created_at.is_empty()
        || frame.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "fictional energy VFX animated socket attachment V2 frame is malformed".to_owned(),
        ));
    }
    Ok(())
}

