fn validate_fictional_energy_vfx_animated_socket_trails_sequence_frame(
    frame: &FictionalEnergyVfxAnimatedSocketTrailsSequenceFrame,
    ordinal: usize,
    expected_sample_time_ticks: u64,
) -> Result<(), StoreError> {
    let mut canonical = frame.clone();
    canonical.canonical_sha256.clear();
    let expected_canonical = canonical_json_hash(
        &serde_json::to_value(&canonical)
            .map_err(|error| StoreError::InvalidData(error.to_string()))?,
    );
    let history_valid = frame.history_samples.len().clamp(1, 8) == frame.history_samples.len()
        && frame
            .history_samples
            .iter()
            .enumerate()
            .all(|(index, sample)| {
                sample.history_ordinal == index as u64
                    && is_sha256(&sample.projection_key_sha256)
                    && sample.projection_frame_index <= 15
                    && is_sha256(&sample.projection_frame_canonical_sha256)
                    && is_sha256(&sample.projection_socket_transform_inventory_sha256)
                    && is_sha256(&sample.projection_socket_transform_readback_sha256)
                    && is_sha256(&sample.particle_sequence_key_sha256)
                    && sample.particle_frame_index <= 15
                    && is_sha256(&sample.particle_key_sha256)
                    && is_sha256(&sample.particle_frame_canonical_sha256)
                    && sample.sample_time_ticks < frame.sample_time_ticks
            })
        && frame
            .history_samples
            .windows(2)
            .all(|samples| samples[0].sample_time_ticks < samples[1].sample_time_ticks)
        && frame.history_samples.last().is_some_and(|sample| {
            sample.projection_frame_index == frame.previous_projection_frame_index
                && sample.particle_frame_index == frame.previous_particle_frame_index
                && sample.particle_sequence_key_sha256 == frame.particle_sequence_key_sha256
                && sample.particle_frame_canonical_sha256
                    == frame.previous_particle_sequence_frame_canonical_sha256
                && sample.projection_frame_canonical_sha256
                    == frame.previous_projection_frame_canonical_sha256
                && sample.projection_socket_transform_inventory_sha256
                    == frame.previous_projection_socket_transform_inventory_sha256
                && sample.projection_socket_transform_readback_sha256
                    == frame.previous_projection_socket_transform_readback_sha256
        });
    let trails_valid = frame.trail_count == 2
        && frame.trail_emitter_roles == vec!["muzzle-vfx".to_owned(), "energy-core-vfx".to_owned()]
        && frame.trails.len() == 2
        && frame.trails.iter().enumerate().all(|(index, trail)| {
            trail.emitter_role == frame.trail_emitter_roles[index]
                && trail.trail_id <= 65_535
                && !trail.points.is_empty()
                && trail.points.len() <= 9
                && trail.points.iter().all(|point| {
                    point.source_frame_index <= 15
                        && point.sample_time_ticks <= 1_000_000
                        && is_sha256(&point.source_particle_key_sha256)
                        && point.source_particle_frame_index <= 15
                })
        });
    if frame.schema_version != "FictionalEnergyVfxAnimatedSocketTrailsSequenceFrame@1"
        || frame.frame_index != ordinal as u64
        || frame.sample_time_ticks != expected_sample_time_ticks
        || frame.history_origin
            != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_HISTORY_PREROLL_POLICY
        || frame.current_projection_frame_index != ordinal as u64 + 1
        || frame.current_particle_frame_index != ordinal as u64 + 1
        || frame.previous_projection_frame_index != ordinal as u64
        || frame.previous_particle_frame_index != ordinal as u64
        || !is_sha256(&frame.current_particle_key_sha256)
        || !is_sha256(&frame.current_particle_frame_canonical_sha256)
        || !is_sha256(&frame.current_projection_frame_canonical_sha256)
        || !is_sha256(&frame.current_projection_socket_transform_inventory_sha256)
        || !is_sha256(&frame.current_projection_socket_transform_readback_sha256)
        || !is_sha256(&frame.previous_particle_sequence_frame_canonical_sha256)
        || !is_sha256(&frame.previous_projection_frame_canonical_sha256)
        || !is_sha256(&frame.previous_projection_socket_transform_inventory_sha256)
        || !is_sha256(&frame.previous_projection_socket_transform_readback_sha256)
        || !is_sha256(&frame.projection_sample_set_sha256)
        || !is_sha256(&frame.particle_sequence_key_sha256)
        || !is_sha256(&frame.base_frame_key_sha256)
        || !is_sha256(&frame.bloom_key_sha256)
        || !is_sha256(&frame.camera_object_sha256)
        || !is_sha256(&frame.camera_identity_sha256)
        || !is_sha256(&frame.render_profile_sha256)
        || !is_sha256(&frame.render_worker_build_cohort_sha256)
        || !history_valid
        || !trails_valid
        || !is_sha256(&frame.trail_key_sha256)
        || !is_sha256(&frame.trail_seed_sha256)
        || !is_sha256(&frame.trail_inventory_sha256)
        || !is_sha256(&frame.trail_id_encoding_sha256)
        || !is_sha256(&frame.emitter_binding_sha256)
        || !is_sha256(&frame.trail_color_object_sha256)
        || !is_sha256(&frame.trail_id_object_sha256)
        || !is_sha256(&frame.trail_depth_object_sha256)
        || !is_sha256(&frame.render_set_object_sha256)
        || !is_sha256(&frame.receipt_object_sha256)
        || frame.canonical_sha256 != expected_canonical
        || frame.created_at.is_empty()
        || frame.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "animated socket trails sequence frame is malformed".to_owned(),
        ));
    }
    Ok(())
}

