fn same_fictional_energy_vfx_animated_socket_particles_sequence(
    left: &FictionalEnergyVfxAnimatedSocketParticlesSequence,
    right: &FictionalEnergyVfxAnimatedSocketParticlesSequence,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left.created_at.clear();
    right.created_at.clear();
    for frame in &mut left.frames {
        frame.canonical_sha256.clear();
        frame.created_at.clear();
    }
    for frame in &mut right.frames {
        frame.canonical_sha256.clear();
        frame.created_at.clear();
    }
    left == right
}

fn same_fictional_energy_vfx_animated_socket_particles_projection_binding(
    projection: &GameWeaponAnimatedGlbSocketTransformProjection,
    sequence: &FictionalEnergyVfxAnimatedSocketParticlesSequence,
) -> bool {
    projection.projection_key_sha256 == sequence.projection_key_sha256
        && projection.project_id == sequence.project_id
        && projection.candidate_id == sequence.candidate_id
        && projection.candidate_state_sha256 == sequence.candidate_state_sha256
        && projection.delivery_manifest_object_sha256 == sequence.delivery_manifest_object_sha256
        && projection.source_artifact_sha256 == sequence.source_artifact_sha256
        && projection.animated_socket_materialization_key_sha256
            == sequence.animated_socket_materialization_key_sha256
        && projection.animated_artifact_sha256 == sequence.animated_artifact_sha256
        && projection.anchor_set_object_sha256 == sequence.animated_socket_anchor_set_object_sha256
        && projection.anchor_set_canonical_sha256
            == sequence.animated_socket_anchor_set_canonical_sha256
        && projection.animation_clip_id == sequence.animation_clip_id
        && projection.animation_clip_object_sha256 == sequence.animation_clip_object_sha256
        && projection.animation_clip_canonical_sha256 == sequence.animation_clip_canonical_sha256
        && projection.animation_receipt_object_sha256 == sequence.animation_receipt_object_sha256
        && projection.animation_receipt_canonical_sha256
            == sequence.animation_receipt_canonical_sha256
        && projection.socket_node_id_encoding_sha256 == sequence.socket_node_id_encoding_sha256
        && projection.socket_roles_sha256 == sequence.socket_roles_sha256
        && projection.sample_schedule_sha256 == sequence.sample_schedule_sha256
        && projection.sample_count == sequence.sample_count
        && projection.sample_time_ticks == sequence.sample_time_ticks
        && projection.transform_projection_policy == sequence.transform_projection_policy
        && projection.frames.len() == sequence.frames.len()
        && projection
            .frames
            .iter()
            .zip(&sequence.frames)
            .all(|(source, output)| {
                source.frame_index == output.frame_index
                    && source.sample_time_ticks == output.sample_time_ticks
                    && source.canonical_sha256 == output.projection_frame_canonical_sha256
                    && source.socket_transform_inventory_sha256
                        == output.projection_socket_transform_inventory_sha256
                    && source.socket_transform_readback_sha256
                        == output.projection_socket_transform_readback_sha256
            })
}

fn validate_fictional_energy_vfx_animated_socket_particles_sequence_receipt_bytes(
    bytes: &[u8],
    sequence: &FictionalEnergyVfxAnimatedSocketParticlesSequence,
    object: &CasObjectRecord,
) -> Result<(), StoreError> {
    if object.schema_version != "CasObject@1"
        || object.mime != GAME_ASSET_DELIVERY_JSON_MIME
        || object.kind != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_KIND
        || object.size_bytes == 0
        || object.size_bytes > MAX_GAME_ASSET_DELIVERY_JSON_BYTES
        || object.size_bytes != bytes.len() as u64
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || sha256_hex(bytes) != object.sha256
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_INVALID"
                .to_owned(),
            message: "animated particle sequence receipt metadata or bytes are invalid".to_owned(),
        });
    }
    let value: Value = serde_json::from_slice(bytes).map_err(|error| StoreError::Contract {
        code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_INVALID".to_owned(),
        message: format!("animated particle sequence receipt JSON is invalid: {error}"),
    })?;
    let canonical_bytes =
        canonical_json_bytes(&value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if canonical_bytes != bytes {
        return Err(StoreError::Contract {
            code:
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_CANONICAL_MISMATCH"
                    .to_owned(),
            message: "animated particle sequence receipt is not canonical JSON".to_owned(),
        });
    }
    let decoded: FictionalEnergyVfxAnimatedSocketParticlesSequence = serde_json::from_value(value)
        .map_err(|error| StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_INVALID"
                .to_owned(),
            message: format!("animated particle sequence receipt shape is invalid: {error}"),
        })?;
    if decoded != *sequence {
        return Err(StoreError::Contract {
            code:
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_BINDING_MISMATCH"
                    .to_owned(),
            message: "animated particle sequence receipt differs from the durable sequence"
                .to_owned(),
        });
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_animated_socket_particles_object(
    connection: &Connection,
    sha256: &str,
    expected_mime: &str,
    expected_kind: &str,
    max_bytes: i64,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= max_bytes
            && mime == expected_mime
            && kind == expected_kind
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_CAS_OBJECT_INVALID".to_owned(),
            message: "animated particle sequence CAS metadata is missing or differs".to_owned(),
        });
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_animated_socket_particles_sequence_objects(
    connection: &Connection,
    sequence: &FictionalEnergyVfxAnimatedSocketParticlesSequence,
    sequence_receipt_object: &CasObjectRecord,
) -> Result<(), StoreError> {
    if sequence_receipt_object.mime != GAME_ASSET_DELIVERY_JSON_MIME
        || sequence_receipt_object.kind
            != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_KIND
        || sequence_receipt_object.size_bytes == 0
        || sequence_receipt_object.size_bytes > MAX_GAME_ASSET_DELIVERY_JSON_BYTES
    {
        return Err(StoreError::Contract {
            code:
                "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_METADATA_INVALID"
                    .to_owned(),
            message: "animated particle sequence receipt metadata is invalid".to_owned(),
        });
    }
    for (hash, mime, kind, max_bytes) in [
        (
            sequence.delivery_manifest_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            "game-asset-delivery-manifest",
            i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
        ),
        (
            sequence.projection_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_KIND,
            i64::try_from(MAX_GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_BYTES)
                .unwrap_or(i64::MAX),
        ),
        (
            sequence.animated_artifact_sha256.as_str(),
            "model/gltf-binary",
            "mechanical-animation-glb",
            64 * 1024 * 1024,
        ),
        (
            sequence.animated_socket_anchor_set_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            GAME_WEAPON_ANCHOR_SET_KIND,
            i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
        ),
        (
            sequence.animation_clip_object_sha256.as_str(),
            MECHANICAL_ANIMATION_CLIP_MIME,
            MECHANICAL_ANIMATION_CLIP_KIND,
            i64::try_from(MAX_MECHANICAL_ANIMATION_CLIP_BYTES).unwrap_or(i64::MAX),
        ),
        (
            sequence.animation_receipt_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            "mechanical-animation-glb-receipt",
            i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
        ),
        (
            sequence.vfx_profile_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            FICTIONAL_ENERGY_VFX_PROFILE_KIND,
            i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
        ),
        (
            sequence.camera_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            FICTIONAL_ENERGY_VFX_CAMERA_KIND,
            i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
        ),
        (
            sequence_receipt_object.sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SEQUENCE_RECEIPT_KIND,
            i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
        ),
    ] {
        ensure_fictional_energy_vfx_animated_socket_particles_object(
            connection, hash, mime, kind, max_bytes,
        )?;
    }

    let source_metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sequence.source_artifact_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !source_metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= 64 * 1024 * 1024
            && mime == "model/gltf-binary"
            && matches!(
                kind.as_str(),
                "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
            )
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SOURCE_INVALID".to_owned(),
            message: "animated particle sequence source artifact metadata is invalid".to_owned(),
        });
    }
    for frame in &sequence.frames {
        for (hash, mime, kind, max_bytes) in [
            (
                frame.render_set_object_sha256.as_str(),
                GAME_ASSET_DELIVERY_JSON_MIME,
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_RENDER_SET_KIND,
                i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
            ),
            (
                frame.receipt_object_sha256.as_str(),
                GAME_ASSET_DELIVERY_JSON_MIME,
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_FRAME_RECEIPT_KIND,
                i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX),
            ),
            (
                frame.particle_color_object_sha256.as_str(),
                "image/png",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_COLOR_KIND,
                MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES,
            ),
            (
                frame.particle_id_object_sha256.as_str(),
                "image/png",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_ID_KIND,
                MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES,
            ),
            (
                frame.particle_depth_object_sha256.as_str(),
                "image/png",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_DEPTH_KIND,
                MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES,
            ),
        ] {
            ensure_fictional_energy_vfx_animated_socket_particles_object(
                connection, hash, mime, kind, max_bytes,
            )?;
        }
    }
    Ok(())
}

fn validate_fictional_energy_vfx_animated_socket_particles_sequence_binding_in_transaction(
    connection: &Connection,
    sequence: &FictionalEnergyVfxAnimatedSocketParticlesSequence,
) -> Result<(), StoreError> {
    let mut projection = connection
        .query_row(
            "SELECT schema_version, projection_key_sha256, project_id, candidate_id, candidate_state_sha256, delivery_manifest_object_sha256, source_artifact_sha256, source_artifact_readback_sha256, animated_artifact_sha256, animated_artifact_readback_sha256, animation_receipt_object_sha256, animation_receipt_canonical_sha256, animated_socket_materialization_key_sha256, derived_animated_socket_artifact_sha256, derived_animated_socket_artifact_readback_sha256, derived_animated_socket_receipt_object_sha256, derived_animated_socket_receipt_canonical_sha256, anchor_set_object_sha256, anchor_set_canonical_sha256, animation_clip_id, animation_clip_object_sha256, animation_clip_canonical_sha256, socket_node_id_encoding_sha256, socket_node_inventory_sha256, socket_roles_sha256, socket_roles_json, part_hierarchy_sha256, part_hierarchy_policy, transform_representation_policy, sample_schedule_sha256, sample_count, sample_time_ticks_json, frame_scope, timebase_hz, transform_projection_policy, coordinate_system, transform_convention, float_quantization_policy, input_sha256, projection_status, quality_status, visual_quality_status, commercial_fps_quality_status, human_review_status, commercial_engine_status, runtime_write_performed, restart_hash_verified, candidate_confirmed, version_created, export_performed, actual_engine_roundtrip, production_stage_advanced, limitations_json, canonical_sha256, created_at FROM game_weapon_animated_glb_socket_transform_projection_links WHERE projection_key_sha256 = ?1",
            params![sequence.projection_key_sha256],
            game_weapon_animated_glb_socket_transform_projection_from_row,
        )
        .optional()?
        .ok_or_else(|| StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_PROJECTION_MISSING".to_owned(),
            message: "animated particle sequence projection row is unavailable".to_owned(),
        })?;
    projection.frames = read_game_weapon_animated_glb_socket_transform_projection_frames(
        connection,
        &projection.projection_key_sha256,
    )?;
    validate_game_weapon_animated_glb_socket_transform_projection(&projection)?;
    validate_game_weapon_animated_glb_socket_transform_projection_binding_in_transaction(
        connection,
        &projection,
    )?;
    let projection_object_sha256: String = connection.query_row(
        "SELECT projection_object_sha256 FROM game_weapon_animated_glb_socket_transform_projection_links WHERE projection_key_sha256 = ?1",
        params![sequence.projection_key_sha256],
        |row| row.get(0),
    )?;
    if projection_object_sha256 != sequence.projection_object_sha256
        || !same_fictional_energy_vfx_animated_socket_particles_projection_binding(
            &projection,
            sequence,
        )
        || projection.canonical_sha256 != sequence.projection_canonical_sha256
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_PROJECTION_BINDING_MISMATCH"
                .to_owned(),
            message: "animated particle sequence projection binding differs".to_owned(),
        });
    }

    let delivery: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, lod0_candidate_id, lod0_artifact_sha256 FROM game_asset_delivery_links WHERE delivery_manifest_object_sha256 = ?1",
            params![sequence.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if delivery.as_ref().map(|value| value.0.as_str()) != Some(sequence.project_id.as_str())
        || delivery.as_ref().map(|value| value.1.as_str()) != Some(sequence.candidate_id.as_str())
        || delivery.as_ref().map(|value| value.2.as_str())
            != Some(sequence.source_artifact_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_DELIVERY_BINDING_MISMATCH"
                .to_owned(),
            message: "animated particle sequence delivery binding differs".to_owned(),
        });
    }
    let profile: Option<(String, String, String)> = connection
        .query_row(
            "SELECT project_id, vfx_profile_object_sha256, anchor_set_object_sha256 FROM fictional_energy_vfx_links WHERE delivery_manifest_object_sha256 = ?1",
            params![sequence.delivery_manifest_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    if profile.as_ref().map(|value| value.0.as_str()) != Some(sequence.project_id.as_str())
        || profile.as_ref().map(|value| value.1.as_str())
            != Some(sequence.vfx_profile_object_sha256.as_str())
        || profile.as_ref().map(|value| value.2.as_str())
            != Some(sequence.animated_socket_anchor_set_object_sha256.as_str())
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_PROFILE_BINDING_MISMATCH"
                .to_owned(),
            message: "animated particle sequence VFX profile/AnchorSet binding differs".to_owned(),
        });
    }
    let sample_time_ticks_json = canonical_json_string(&sequence.sample_time_ticks)?;
    if projection.sample_schedule_sha256 != sequence.sample_schedule_sha256
        || projection.sample_time_ticks != sequence.sample_time_ticks
        || projection.sample_count != sequence.sample_count
        || sequence.frames.len() != projection.frames.len()
        || sample_time_ticks_json.is_empty()
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_SAMPLE_BINDING_MISMATCH"
                .to_owned(),
            message: "animated particle sequence sample schedule differs from projection"
                .to_owned(),
        });
    }

    for frame in &sequence.frames {
        let projection_frame: Option<(i64, String, String, String, String)> = connection
            .query_row(
                "SELECT sample_time_ticks, canonical_sha256, socket_transform_inventory_sha256, socket_transform_readback_sha256, projection_key_sha256 FROM game_weapon_animated_glb_socket_transform_projection_frames WHERE projection_key_sha256 = ?1 AND frame_index = ?2",
                params![sequence.projection_key_sha256, frame.frame_index as i64],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
            )
            .optional()?;
        let Some((sample_time_ticks, canonical, inventory, readback, projection_key)) =
            projection_frame
        else {
            return Err(StoreError::Contract {
                code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_PROJECTION_FRAME_MISSING"
                    .to_owned(),
                message: "animated particle sequence projection frame is unavailable".to_owned(),
            });
        };
        if projection_key != sequence.projection_key_sha256
            || u64::try_from(sample_time_ticks).ok() != Some(frame.sample_time_ticks)
            || canonical != frame.projection_frame_canonical_sha256
            || inventory != frame.projection_socket_transform_inventory_sha256
            || readback != frame.projection_socket_transform_readback_sha256
        {
            return Err(StoreError::Contract {
                code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_PROJECTION_FRAME_BINDING_MISMATCH"
                    .to_owned(),
                message: "animated particle sequence frame differs from projection frame".to_owned(),
            });
        }

        let base: Option<(String, String, String, String, String, String, String, String, String)> =
            connection
                .query_row(
                    "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, camera_object_sha256, camera_identity_sha256, render_profile_sha256, render_worker_build_cohort_sha256 FROM fictional_energy_vfx_frame_links WHERE frame_key_sha256 = ?1",
                    params![frame.base_frame_key_sha256],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?)),
                )
                .optional()?;
        let bloom: Option<(String, String, String, String, String, String, String, String, String, String)> =
            connection
                .query_row(
                    "SELECT project_id, delivery_manifest_object_sha256, vfx_profile_object_sha256, source_candidate_id, source_artifact_sha256, base_frame_key_sha256, camera_object_sha256, camera_identity_sha256, render_profile_sha256, render_worker_build_cohort_sha256 FROM fictional_energy_vfx_bloom_frame_links WHERE bloom_key_sha256 = ?1",
                    params![frame.bloom_key_sha256],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?, row.get(8)?, row.get(9)?)),
                )
                .optional()?;
        let base_matches = base.as_ref().is_some_and(|value| {
            value.0 == sequence.project_id
                && value.1 == sequence.delivery_manifest_object_sha256
                && value.2 == sequence.vfx_profile_object_sha256
                && value.3 == sequence.candidate_id
                && value.4 == sequence.source_artifact_sha256
                && value.5 == sequence.camera_object_sha256
                && value.6 == sequence.camera_identity_sha256
                && value.7 == sequence.render_profile_sha256
                && value.8 == sequence.render_worker_build_cohort_sha256
        });
        let bloom_matches = bloom.as_ref().is_some_and(|value| {
            value.0 == sequence.project_id
                && value.1 == sequence.delivery_manifest_object_sha256
                && value.2 == sequence.vfx_profile_object_sha256
                && value.3 == sequence.candidate_id
                && value.4 == sequence.source_artifact_sha256
                && value.5 == frame.base_frame_key_sha256
                && value.6 == sequence.camera_object_sha256
                && value.7 == sequence.camera_identity_sha256
                && value.8 == sequence.render_profile_sha256
                && value.9 == sequence.render_worker_build_cohort_sha256
        });
        if !base_matches || !bloom_matches {
            return Err(StoreError::Contract {
                code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_PARTICLES_FRAME_BINDING_MISMATCH"
                    .to_owned(),
                message: "animated particle sequence base/Bloom binding differs".to_owned(),
            });
        }
    }
    Ok(())
}

fn fictional_energy_vfx_animated_socket_particles_sequence_reachable_hashes(
    connection: &Connection,
    sequence: &FictionalEnergyVfxAnimatedSocketParticlesSequence,
    sequence_receipt_object_sha256: Option<&str>,
) -> Result<Vec<String>, StoreError> {
    let receipt = match sequence_receipt_object_sha256 {
        Some(value) => value.to_owned(),
        None => connection.query_row(
            "SELECT sequence_receipt_object_sha256 FROM fictional_energy_vfx_animated_socket_particles_sequence_links WHERE sequence_key_sha256 = ?1",
            params![sequence.sequence_key_sha256],
            |row| row.get(0),
        )?,
    };
    let mut hashes = vec![
        receipt,
        sequence.delivery_manifest_object_sha256.clone(),
        sequence.source_artifact_sha256.clone(),
        sequence.projection_object_sha256.clone(),
        sequence.animated_artifact_sha256.clone(),
        sequence.animation_receipt_object_sha256.clone(),
        sequence.animated_socket_anchor_set_object_sha256.clone(),
        sequence.animation_clip_object_sha256.clone(),
        sequence.vfx_profile_object_sha256.clone(),
        sequence.camera_object_sha256.clone(),
    ];
    if let Some((derived_artifact, derived_receipt)) = connection
        .query_row(
            "SELECT derived_animated_socket_artifact_sha256, derived_animated_socket_receipt_object_sha256 FROM game_weapon_animated_glb_socket_transform_projection_links WHERE projection_key_sha256 = ?1",
            params![sequence.projection_key_sha256],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?
    {
        hashes.push(derived_artifact);
        hashes.push(derived_receipt);
    }
    if let Some((derived_artifact, derived_receipt)) = connection
        .query_row(
            "SELECT derived_animated_socket_artifact_sha256, receipt_object_sha256 FROM game_weapon_animated_glb_socket_materialization_links WHERE animated_socket_materialization_key_sha256 = ?1",
            params![sequence.animated_socket_materialization_key_sha256],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?
    {
        hashes.push(derived_artifact);
        hashes.push(derived_receipt);
    }
    for frame in &sequence.frames {
        hashes.extend([
            frame.render_set_object_sha256.clone(),
            frame.receipt_object_sha256.clone(),
            frame.particle_color_object_sha256.clone(),
            frame.particle_id_object_sha256.clone(),
            frame.particle_depth_object_sha256.clone(),
        ]);
    }
    hashes.sort();
    hashes.dedup();
    Ok(hashes)
}

fn validate_fictional_energy_vfx_animated_socket_attachment_receipt_bytes(
    bytes: &[u8],
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentRecord,
) -> Result<(), StoreError> {
    if bytes.is_empty() || bytes.len() as u64 > MAX_GAME_ASSET_DELIVERY_JSON_BYTES {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_RECEIPT_INVALID".to_owned(),
            message: "animated socket attachment receipt exceeds the bounded JSON budget"
                .to_owned(),
        });
    }
    let value: Value = serde_json::from_slice(bytes).map_err(|error| {
        StoreError::InvalidData(format!(
            "animated socket attachment receipt is not valid JSON: {error}"
        ))
    })?;
    let object = value.as_object().ok_or_else(|| {
        StoreError::InvalidData(
            "animated socket attachment receipt must be a JSON object".to_owned(),
        )
    })?;
    if object.get("schema_version").and_then(Value::as_str)
        != Some("FictionalEnergyVfxAnimatedSocketAttachmentReceipt@1")
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_RECEIPT_SCHEMA_MISMATCH"
                .to_owned(),
            message: "animated socket attachment receipt schema differs".to_owned(),
        });
    }
    if object.get("attachment_key_sha256").and_then(Value::as_str)
        != Some(attachment.attachment_key_sha256.as_str())
        || object.get("canonical_sha256").and_then(Value::as_str)
            != Some(attachment.canonical_sha256.as_str())
        || object.get("frame_count").and_then(Value::as_u64)
            != u64::try_from(attachment.frames.len()).ok()
        || object.get("frames").and_then(Value::as_array).map(Vec::len)
            != Some(attachment.frames.len())
        || object
            .get("frame_dependencies")
            .and_then(Value::as_array)
            .map(Vec::len)
            != Some(attachment.frames.len())
        || object
            .get("socket_nodes")
            .and_then(Value::as_array)
            .map(Vec::len)
            != Some(6)
        || object
            .get("runtime_write_performed")
            .and_then(Value::as_bool)
            != Some(true)
        || object.get("restart_hash_verified").and_then(Value::as_bool) != Some(true)
        || object.get("candidate_confirmed").and_then(Value::as_bool) != Some(false)
        || object.get("export_performed").and_then(Value::as_bool) != Some(false)
        || object
            .get("actual_engine_roundtrip")
            .and_then(Value::as_bool)
            != Some(false)
        || object.get("quality_status").and_then(Value::as_str) != Some("structural_only")
        || object.get("visual_quality_status").and_then(Value::as_str) != Some("NOT_PROVEN")
        || object
            .get("commercial_fps_quality_status")
            .and_then(Value::as_str)
            != Some("NOT_PROVEN")
        || object.get("human_review_status").and_then(Value::as_str) != Some("NOT_RUN")
        || object
            .get("commercial_engine_status")
            .and_then(Value::as_str)
            != Some("NOT_RUN")
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_RECEIPT_BINDING_MISMATCH"
                .to_owned(),
            message: "animated socket attachment receipt does not bind to its parent".to_owned(),
        });
    }
    Ok(())
}

