fn read_fictional_energy_vfx_animated_socket_attachment_v3_frames(
    connection: &Connection,
    attachment_key_sha256: &str,
) -> Result<Vec<FictionalEnergyVfxAnimatedSocketAttachmentV3FrameRecord>, StoreError> {
    let mut statement = connection.prepare(
        "SELECT attachment_key_sha256, schema_version, frame_index, sample_time_ticks, projection_frame_index, particle_sequence_frame_index, trail_frame_index, trail_bloom_frame_index, projection_frame_canonical_sha256, projection_socket_transform_inventory_sha256, projection_socket_transform_readback_sha256, particle_sequence_key_sha256, particle_sequence_frame_canonical_sha256, trail_sequence_key_sha256, trail_sequence_frame_canonical_sha256, trail_key_sha256, trail_inventory_sha256, trail_id_encoding_sha256, emitter_binding_sha256, trail_bloom_sequence_key_sha256, trail_bloom_sequence_frame_canonical_sha256, trail_bloom_key_sha256, trail_bloom_seed_sha256, base_frame_key_sha256, bloom_key_sha256, camera_object_sha256, camera_identity_sha256, render_profile_sha256, render_worker_build_cohort_sha256, canonical_sha256, created_at FROM fictional_energy_vfx_animated_socket_attachment_v3_frames WHERE attachment_key_sha256 = ?1 ORDER BY frame_index ASC",
    )?;
    let rows = statement.query_map(
        params![attachment_key_sha256],
        fictional_energy_vfx_animated_socket_attachment_v3_frame_from_row,
    )?;
    rows.collect::<Result<Vec<_>, _>>()
        .map_err(StoreError::Sqlite)
}

fn same_fictional_energy_vfx_animated_socket_attachment_v3(
    left: &FictionalEnergyVfxAnimatedSocketAttachmentV3Record,
    right: &FictionalEnergyVfxAnimatedSocketAttachmentV3Record,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    for frame in &mut left.frames {
        frame.created_at.clear();
        frame.canonical_sha256.clear();
    }
    for frame in &mut right.frames {
        frame.created_at.clear();
        frame.canonical_sha256.clear();
    }
    left == right
}

fn validate_fictional_energy_vfx_animated_socket_attachment_v3_receipt_bytes(
    bytes: &[u8],
    attachment: &FictionalEnergyVfxAnimatedSocketAttachmentV3Record,
) -> Result<(), StoreError> {
    if bytes.is_empty() || bytes.len() as u64 > MAX_GAME_ASSET_DELIVERY_JSON_BYTES {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_INVALID".to_owned(),
            message: "Attachment@3 receipt exceeds the bounded JSON budget".to_owned(),
        });
    }
    let value: Value = serde_json::from_slice(bytes).map_err(|error| {
        StoreError::InvalidData(format!("Attachment@3 receipt is not valid JSON: {error}"))
    })?;
    let canonical_bytes =
        canonical_json_bytes(&value).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if canonical_bytes != bytes {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_NOT_CANONICAL"
                .to_owned(),
            message: "Attachment@3 receipt bytes are not canonical JSON".to_owned(),
        });
    }
    let object = value.as_object().ok_or_else(|| {
        StoreError::InvalidData("Attachment@3 receipt must be a JSON object".to_owned())
    })?;
    let mut receipt_projection = serde_json::to_value(attachment)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if let Some(projection) = receipt_projection.as_object_mut() {
        projection.remove("attachment_receipt_object_sha256");
        projection.remove("attachment_receipt_canonical_sha256");
        projection.remove("canonical_sha256");
        projection.insert(
            "schema_version".to_owned(),
            Value::String("FictionalEnergyVfxAnimatedSocketAttachmentReceipt@3".to_owned()),
        );
        projection.insert("canonical_sha256".to_owned(), Value::String(String::new()));
    }
    let expected_receipt_canonical = canonical_json_hash(&receipt_projection);
    if object.get("schema_version").and_then(Value::as_str)
        != Some("FictionalEnergyVfxAnimatedSocketAttachmentReceipt@3")
        || object.get("attachment_key_sha256").and_then(Value::as_str)
            != Some(attachment.attachment_key_sha256.as_str())
        || object.get("canonical_sha256").and_then(Value::as_str)
            != Some(attachment.canonical_sha256.as_str())
        || object
            .get("attachment_canonical_sha256")
            .and_then(Value::as_str)
            != Some(attachment.canonical_sha256.as_str())
        || object
            .get("receipt_canonical_sha256")
            .and_then(Value::as_str)
            != Some(attachment.attachment_receipt_canonical_sha256.as_str())
        || attachment.attachment_receipt_canonical_sha256 != expected_receipt_canonical
        || object.get("frame_count").and_then(Value::as_u64) != Some(15)
        || object.get("frames").and_then(Value::as_array).map(Vec::len) != Some(15)
        || object
            .get("frame_dependencies")
            .and_then(Value::as_array)
            .map(Vec::len)
            != Some(15)
        || object
            .get("runtime_write_performed")
            .and_then(Value::as_bool)
            != Some(true)
        || object.get("restart_hash_verified").and_then(Value::as_bool) != Some(true)
        || object.get("candidate_confirmed").and_then(Value::as_bool) != Some(false)
        || object.get("version_created").and_then(Value::as_bool) != Some(false)
        || object.get("export_performed").and_then(Value::as_bool) != Some(false)
        || object
            .get("actual_engine_roundtrip")
            .and_then(Value::as_bool)
            != Some(false)
        || object
            .get("production_stage_advanced")
            .and_then(Value::as_bool)
            != Some(false)
        || object.get("quality_status").and_then(Value::as_str) != Some("structural_only")
        || object.get("visual_quality_status").and_then(Value::as_str) != Some("NOT_PROVEN")
        || object
            .get("commercial_fps_quality_status")
            .and_then(Value::as_str)
            != Some("NOT_PROVEN")
        || object.get("human_review_status").and_then(Value::as_str) != Some("NOT_RUN")
        || object
            .get("commercial_engine_status")
            .and_then(Value::as_str)
            != Some("NOT_RUN")
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_BINDING_MISMATCH"
                .to_owned(),
            message: "Attachment@3 receipt does not bind to its parent".to_owned(),
        });
    }
    let expected_frames = serde_json::to_value(&attachment.frames)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if object.get("frames") != Some(&expected_frames)
        || object.get("frame_dependencies") != Some(&expected_frames)
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_FRAME_MISMATCH"
                .to_owned(),
            message: "Attachment@3 receipt frame projection differs from the durable rows"
                .to_owned(),
        });
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_animated_socket_attachment_v3_receipt(
    connection: &Connection,
    receipt_object: &CasObjectRecord,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![receipt_object.sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if receipt_object.mime != GAME_ASSET_DELIVERY_JSON_MIME
        || receipt_object.kind != FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_KIND
        || receipt_object.size_bytes == 0
        || receipt_object.size_bytes > MAX_GAME_ASSET_DELIVERY_JSON_BYTES
        || !metadata.is_some_and(|(size, mime, kind, reachability)| {
            size == receipt_object.size_bytes as i64
                && mime == GAME_ASSET_DELIVERY_JSON_MIME
                && kind == FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_KIND
                && matches!(reachability.as_str(), "temporary" | "reachable")
        })
    {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_CAS_INVALID"
                .to_owned(),
            message: "Attachment@3 receipt CAS metadata differs".to_owned(),
        });
    }
    Ok(())
}

fn attachment_v3_parent_texts(
    connection: &Connection,
    table: &str,
    key_column: &str,
    key: &str,
    fields: &[&str],
) -> Result<Option<HashMap<String, String>>, StoreError> {
    let sql = format!(
        "SELECT {} FROM {} WHERE {} = ?1",
        fields.join(", "),
        table,
        key_column,
    );
    let result = connection
        .query_row(&sql, params![key], |row| {
            let mut values = HashMap::with_capacity(fields.len());
            for (index, field) in fields.iter().enumerate() {
                values.insert((*field).to_owned(), row.get(index)?);
            }
            Ok(values)
        })
        .optional()?;
    Ok(result)
}

