fn identity_lineage_closed_object<'a>(
    value: &'a Value,
    fields: &[&str],
    context: &str,
) -> Result<&'a serde_json::Map<String, Value>, StoreError> {
    let object = value.as_object().ok_or_else(|| {
        authoring_mesh_contract("AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID", context)
    })?;
    if object.len() != fields.len() || fields.iter().any(|field| !object.contains_key(*field)) {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_CLOSED_SCHEMA",
            context,
        ));
    }
    Ok(object)
}

fn identity_lineage_ids_array(
    value: &Value,
    key: &str,
    maximum: usize,
    context: &str,
) -> Result<Vec<String>, StoreError> {
    let values = value.get(key).and_then(Value::as_array).ok_or_else(|| {
        authoring_mesh_contract("AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID", context)
    })?;
    if values.len() > maximum {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_BUDGET_EXCEEDED",
            context,
        ));
    }
    let mut result = Vec::with_capacity(values.len());
    let mut seen = HashSet::new();
    for value in values {
        let id = value
            .as_str()
            .filter(|id| is_opaque_id(id))
            .ok_or_else(|| {
                authoring_mesh_contract("AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID", context)
            })?;
        if !seen.insert(id.to_owned()) {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_DUPLICATE_ID",
                context,
            ));
        }
        result.push(id.to_owned());
    }
    Ok(result)
}

fn identity_lineage_nullable_string(value: &Value, key: &str) -> Option<String> {
    match value.get(key) {
        Some(Value::Null) => None,
        Some(Value::String(value)) => Some(value.clone()),
        _ => None,
    }
}

fn validate_authoring_mesh_identity_lineage_payload(
    bytes: &[u8],
    record: &AuthoringMeshIdentityLineageDurableRecord,
) -> Result<(HashSet<String>, HashSet<String>), StoreError> {
    if bytes.is_empty() || bytes.len() as u64 > AUTHORING_MESH_IDENTITY_LINEAGE_MAX_BYTES {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
            "identity lineage payload exceeds the 1 MiB bound",
        ));
    }
    let value = durable_json(
        bytes,
        "AuthoringMeshIdentityLineage@1 must be a JSON object",
    )?;
    let object = identity_lineage_closed_object(
        &value,
        AUTHORING_MESH_IDENTITY_LINEAGE_PUBLIC_FIELDS,
        "identity lineage payload has missing or unknown top-level fields",
    )?;
    let canonical = canonical_hash_from_payload(
        &value,
        "AuthoringMeshIdentityLineage@1 canonical hash is invalid",
    )?;
    if canonical != record.identity_lineage_sha256
        || durable_text(&value, "schema_version") != Some("AuthoringMeshIdentityLineage@1")
        || durable_text(&value, "lineage_id") != Some(record.lineage_id.as_str())
        || durable_text(&value, "project_id") != Some(record.project_id.as_str())
        || durable_text(&value, "authoring_node_id") != Some(record.authoring_node_id.as_str())
        || durable_text(&value, "part_id") != Some(record.part_id.as_str())
        || durable_text(&value, "genesis_source_mesh_sha256")
            != Some(record.genesis_source_mesh_sha256.as_str())
        || durable_text(&value, "current_source_mesh_sha256")
            != Some(record.current_source_mesh_sha256.as_str())
        || durable_text(&value, "candidate_id") != Some(record.candidate_id.as_str())
        || durable_text(&value, "candidate_state_sha256")
            != Some(record.candidate_state_sha256.as_str())
        || identity_lineage_nullable_string(&value, "base_version_id") != record.base_version_id
        || identity_lineage_nullable_string(&value, "parent_lineage_object_sha256")
            != record.parent_lineage_object_sha256
        || identity_lineage_nullable_string(&value, "parent_lineage_sha256")
            != record.parent_lineage_sha256
        || value.get("revision_index").and_then(Value::as_u64) != Some(record.revision_index)
        || durable_text(&value, "revision_kind") != Some(record.revision_kind.as_str())
        || durable_text(&value, "operation_lineage_sha256")
            != Some(record.operation_lineage_sha256.as_str())
        || durable_text(&value, "source_program_object_sha256")
            != Some(record.source_program_object_sha256.as_str())
        || durable_text(&value, "source_program_sha256")
            != Some(record.source_program_sha256.as_str())
        || durable_text(&value, "source_artifact_object_sha256")
            != Some(record.source_artifact_object_sha256.as_str())
        || durable_text(&value, "source_artifact_sha256")
            != Some(record.source_artifact_sha256.as_str())
        || durable_text(&value, "source_artifact_readback_object_sha256")
            != Some(record.source_artifact_readback_object_sha256.as_str())
        || durable_text(&value, "source_artifact_readback_sha256")
            != Some(record.source_artifact_readback_sha256.as_str())
        || durable_text(&value, "identity_policy")
            != Some("runtime-owned-authored-ids-with-monotonic-tombstones@1")
        || durable_text(&value, "evaluated_identity_policy")
            != Some("non-bijective-derived-only-no-authoring-source-reversal@1")
        || durable_text(&value, "writer_policy") != Some("forgecad-runtime-only-state-writer@1")
        || durable_text(&value, "canonicalization_policy")
            != Some("canonical-json-sha256-excluding-canonical-sha256@1")
        || value
            .get("runtime_write_performed")
            .and_then(Value::as_bool)
            != Some(true)
        || value
            .get("persistent_user_data_touched")
            .and_then(Value::as_bool)
            != Some(true)
        || value.get("stage_advanced").and_then(Value::as_bool) != Some(false)
        || value.get("candidate_confirmed").and_then(Value::as_bool) != Some(false)
        || value.get("version_created").and_then(Value::as_bool) != Some(false)
        || value.get("export_performed").and_then(Value::as_bool) != Some(false)
        || durable_text(&value, "quality_status") != Some("structural_only")
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_BINDING_MISMATCH",
            "identity lineage payload differs from the Store-local binding",
        ));
    }

    let budgets = object
        .get("budgets")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                "identity lineage budgets are missing",
            )
        })?;
    if budgets.len() != 5
        || budgets.get("max_response_bytes").and_then(Value::as_u64) != Some(1_048_576)
        || budgets.get("max_elements").and_then(Value::as_u64) != Some(32_768)
        || budgets.get("max_tombstones").and_then(Value::as_u64) != Some(32_768)
        || budgets.get("max_parent_ids").and_then(Value::as_u64) != Some(8)
        || budgets.get("max_evaluated_ids").and_then(Value::as_u64) != Some(64)
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_BUDGET_INVALID",
            "identity lineage budget constants differ from the public contract",
        ));
    }

    let elements = object
        .get("elements")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                "identity lineage elements are missing",
            )
        })?;
    if elements.is_empty() || elements.len() > AUTHORING_MESH_IDENTITY_LINEAGE_MAX_ELEMENTS {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_BUDGET_EXCEEDED",
            "identity lineage element count is outside the public bound",
        ));
    }
    let mut active_ids = HashSet::new();
    for element in elements {
        let element = identity_lineage_closed_object(
            element,
            AUTHORING_MESH_IDENTITY_LINEAGE_ELEMENT_FIELDS,
            "identity lineage element shape is invalid",
        )?;
        let identity_id = element
            .get("identity_id")
            .and_then(Value::as_str)
            .filter(|id| is_opaque_id(id))
            .ok_or_else(|| {
                authoring_mesh_contract(
                    "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                    "identity lineage element identity_id is invalid",
                )
            })?;
        if !active_ids.insert(identity_id.to_owned()) {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_DUPLICATE_ID",
                "identity lineage active identity_id is duplicated",
            ));
        }
        let kind = element
            .get("element_kind")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                authoring_mesh_contract(
                    "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                    "identity lineage element kind is invalid",
                )
            })?;
        if !matches!(
            kind,
            "vertex" | "edge" | "half-edge" | "corner" | "face" | "loop" | "ring" | "boundary"
        ) {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                "identity lineage element kind is unsupported",
            ));
        }
        match element.get("source_element_id") {
            Some(Value::Null) => {}
            Some(Value::String(source)) if is_opaque_id(source) => {}
            _ => {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                    "identity lineage source_element_id is invalid",
                ));
            }
        }
        if !matches!(
            element.get("origin").and_then(Value::as_str),
            Some("authored" | "operation-derived" | "representation-derived")
        ) || !matches!(
            element.get("stability_status").and_then(Value::as_str),
            Some("cross-revision-stable" | "same-revision-only")
        ) || !is_sha256(
            element
                .get("operation_lineage_sha256")
                .and_then(Value::as_str)
                .unwrap_or_default(),
        ) || element
            .get("operation_lineage_sha256")
            .and_then(Value::as_str)
            != Some(record.operation_lineage_sha256.as_str())
            || !is_opaque_id(
                element
                    .get("role")
                    .and_then(Value::as_str)
                    .unwrap_or_default(),
            )
            || element
                .get("ordinal")
                .and_then(Value::as_u64)
                .is_none_or(|ordinal| ordinal > 32_767)
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                "identity lineage element metadata is invalid",
            ));
        }
        identity_lineage_ids_array(
            &Value::Object(element.clone()),
            "parent_identity_ids",
            8,
            "identity lineage element parent list is invalid",
        )?;
    }

    let tombstones = object
        .get("tombstones")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                "identity lineage tombstones are missing",
            )
        })?;
    if tombstones.len() > AUTHORING_MESH_IDENTITY_LINEAGE_MAX_ELEMENTS {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_BUDGET_EXCEEDED",
            "identity lineage tombstone count exceeds the public bound",
        ));
    }
    let mut tombstone_ids = HashSet::new();
    for tombstone in tombstones {
        let tombstone = identity_lineage_closed_object(
            tombstone,
            AUTHORING_MESH_IDENTITY_LINEAGE_TOMBSTONE_FIELDS,
            "identity lineage tombstone shape is invalid",
        )?;
        let identity_id = tombstone
            .get("identity_id")
            .and_then(Value::as_str)
            .filter(|id| is_opaque_id(id))
            .ok_or_else(|| {
                authoring_mesh_contract(
                    "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                    "identity lineage tombstone identity_id is invalid",
                )
            })?;
        if !tombstone_ids.insert(identity_id.to_owned()) || active_ids.contains(identity_id) {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_TOMBSTONE_REUSE",
                "identity lineage tombstone overlaps an active or duplicate identity",
            ));
        }
        if !matches!(
            tombstone.get("element_kind").and_then(Value::as_str),
            Some(
                "vertex" | "edge" | "half-edge" | "corner" | "face" | "loop" | "ring" | "boundary"
            )
        ) || tombstone
            .get("retired_revision_index")
            .and_then(Value::as_u64)
            .is_none_or(|revision| !(1..=1_000_000).contains(&revision))
            || !is_sha256(
                tombstone
                    .get("operation_lineage_sha256")
                    .and_then(Value::as_str)
                    .unwrap_or_default(),
            )
            || !matches!(
                tombstone.get("reason").and_then(Value::as_str),
                Some("deleted" | "collapsed" | "dissolved" | "replaced" | "merged")
            )
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                "identity lineage tombstone metadata is invalid",
            ));
        }
    }

    let correspondence = object
        .get("correspondence")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                "identity lineage correspondence is missing",
            )
        })?;
    if correspondence.len() > AUTHORING_MESH_IDENTITY_LINEAGE_MAX_ELEMENTS {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_BUDGET_EXCEEDED",
            "identity lineage correspondence count exceeds the public bound",
        ));
    }
    let mut correspondence_seen = HashSet::new();
    for item in correspondence {
        let item = identity_lineage_closed_object(
            item,
            AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_FIELDS,
            "identity lineage correspondence shape is invalid",
        )?;
        let canonical_item = canonical_json_bytes(&Value::Object(item.clone())).map_err(|_| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                "identity lineage correspondence cannot be canonicalized",
            )
        })?;
        if !correspondence_seen.insert(canonical_item) {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_DUPLICATE_CORRESPONDENCE",
                "identity lineage correspondence is duplicated",
            ));
        }
        if !matches!(
            item.get("kind").and_then(Value::as_str),
            Some(
                "preserved"
                    | "created"
                    | "retired"
                    | "one-to-many"
                    | "many-to-one"
                    | "many-to-many"
            )
        ) || !is_sha256(
            item.get("operation_lineage_sha256")
                .and_then(Value::as_str)
                .unwrap_or_default(),
        ) || item.get("operation_lineage_sha256").and_then(Value::as_str)
            != Some(record.operation_lineage_sha256.as_str())
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PAYLOAD_INVALID",
                "identity lineage correspondence metadata is invalid",
            ));
        }
        identity_lineage_ids_array(
            &Value::Object(item.clone()),
            "parent_identity_ids",
            8,
            "identity lineage correspondence parent list is invalid",
        )?;
        identity_lineage_ids_array(
            &Value::Object(item.clone()),
            "child_identity_ids",
            64,
            "identity lineage correspondence child list is invalid",
        )?;
    }
    Ok((active_ids, tombstone_ids))
}

fn validate_authoring_mesh_identity_lineage_record(
    record: &AuthoringMeshIdentityLineageDurableRecord,
) -> Result<(), StoreError> {
    let identifiers = [
        record.project_id.as_str(),
        record.authoring_node_id.as_str(),
        record.part_id.as_str(),
        record.lineage_id.as_str(),
        record.candidate_id.as_str(),
        record.canonical_mesh_id.as_str(),
        record.idempotency_key.as_str(),
    ];
    let hashes = [
        record.genesis_source_mesh_sha256.as_str(),
        record.current_source_mesh_sha256.as_str(),
        record.candidate_state_sha256.as_str(),
        record.canonical_mesh_object_sha256.as_str(),
        record.canonical_mesh_sha256.as_str(),
        record.operation_lineage_sha256.as_str(),
        record.source_program_object_sha256.as_str(),
        record.source_program_sha256.as_str(),
        record.source_artifact_object_sha256.as_str(),
        record.source_artifact_sha256.as_str(),
        record.source_artifact_readback_object_sha256.as_str(),
        record.source_artifact_readback_sha256.as_str(),
        record.operator_catalog_sha256.as_str(),
        record.readback_config_sha256.as_str(),
        record.evaluated_artifact_object_sha256.as_str(),
        record.evaluated_artifact_sha256.as_str(),
        record.evaluated_artifact_readback_object_sha256.as_str(),
        record.evaluated_artifact_readback_sha256.as_str(),
        record.identity_lineage_object_sha256.as_str(),
        record.identity_lineage_sha256.as_str(),
        record.request_input_sha256.as_str(),
    ];
    if record.schema_version != AUTHORING_MESH_IDENTITY_LINEAGE_DURABLE_RECORD_SCHEMA_VERSION
        || identifiers.iter().any(|value| !is_opaque_id(value))
        || hashes.iter().any(|value| !is_sha256(value))
        || record
            .base_version_id
            .as_deref()
            .is_some_and(|value| !is_opaque_id(value))
        || record
            .parent_lineage_object_sha256
            .as_deref()
            .is_some_and(|value| !is_sha256(value))
        || record
            .parent_lineage_sha256
            .as_deref()
            .is_some_and(|value| !is_sha256(value))
        || record.revision_index > 1_000_000
        || !matches!(
            record.revision_kind.as_str(),
            "genesis" | "preserving-edit" | "topology-edit"
        )
        || (record.revision_index == 0 && record.revision_kind != "genesis")
        || (record.revision_index > 0 && record.revision_kind == "genesis")
        || record.idempotency_key.len() > 128
        || !record
            .idempotency_key
            .as_bytes()
            .first()
            .is_some_and(u8::is_ascii_alphanumeric)
        || record.materialization_status != AUTHORING_MESH_IDENTITY_LINEAGE_DURABLE_RECORD_STATUS
        || (!record.canonical_sha256.is_empty() && !is_sha256(&record.canonical_sha256))
        || record.created_at.is_empty()
        || record.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "AuthoringMesh identity lineage durable record metadata is malformed".to_owned(),
        ));
    }
    if record.revision_index == 0
        && (record.parent_lineage_object_sha256.is_some() || record.parent_lineage_sha256.is_some())
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_PARENT_INVALID",
            "genesis identity lineage cannot have a parent",
        ));
    }
    if record.revision_index > 0
        && (record.parent_lineage_object_sha256.is_none() || record.parent_lineage_sha256.is_none())
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_PARENT_INVALID",
            "non-genesis identity lineage must bind a parent object and semantic hash",
        ));
    }
    Ok(())
}

fn authoring_mesh_identity_lineage_record_canonical_sha256(
    record: &AuthoringMeshIdentityLineageDurableRecord,
) -> Result<String, StoreError> {
    let mut value =
        serde_json::to_value(record).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    value["canonical_sha256"] = Value::String(String::new());
    Ok(canonical_json_hash(&value))
}

fn normalize_authoring_mesh_identity_lineage_record(
    record: &AuthoringMeshIdentityLineageDurableRecord,
) -> Result<AuthoringMeshIdentityLineageDurableRecord, StoreError> {
    validate_authoring_mesh_identity_lineage_record(record)?;
    let expected = authoring_mesh_identity_lineage_record_canonical_sha256(record)?;
    if !record.canonical_sha256.is_empty() && record.canonical_sha256 != expected {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_RECORD_CANONICAL_MISMATCH",
            "identity lineage Store row canonical hash is invalid",
        ));
    }
    let mut normalized = record.clone();
    normalized.canonical_sha256 = expected;
    Ok(normalized)
}

fn same_authoring_mesh_identity_lineage_record(
    left: &AuthoringMeshIdentityLineageDurableRecord,
    right: &AuthoringMeshIdentityLineageDurableRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

fn read_authoring_mesh_identity_lineage_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    project_id: &str,
    idempotency_key: &str,
) -> Result<Option<AuthoringMeshIdentityLineageDurableRecord>, StoreError> {
    transaction
        .query_row(
            "SELECT schema_version, project_id, authoring_node_id, part_id, lineage_id, genesis_source_mesh_sha256, current_source_mesh_sha256, candidate_id, candidate_state_sha256, base_version_id, canonical_mesh_id, canonical_mesh_object_sha256, canonical_mesh_sha256, parent_lineage_object_sha256, parent_lineage_sha256, revision_index, revision_kind, operation_lineage_sha256, source_program_object_sha256, source_program_sha256, source_artifact_object_sha256, source_artifact_sha256, source_artifact_readback_object_sha256, source_artifact_readback_sha256, operator_catalog_sha256, readback_config_sha256, evaluated_artifact_object_sha256, evaluated_artifact_sha256, evaluated_artifact_readback_object_sha256, evaluated_artifact_readback_sha256, identity_lineage_object_sha256, identity_lineage_sha256, request_input_sha256, idempotency_key, materialization_status, canonical_sha256, created_at FROM authoring_mesh_identity_lineage_durable_records WHERE project_id = ?1 AND idempotency_key = ?2",
            params![project_id, idempotency_key],
            |row| {
                let revision_index: i64 = row.get(15)?;
                let revision_index = u64::try_from(revision_index).map_err(|_| {
                    rusqlite::Error::FromSqlConversionFailure(
                        15,
                        rusqlite::types::Type::Integer,
                        "negative identity lineage revision index".into(),
                    )
                })?;
                Ok(AuthoringMeshIdentityLineageDurableRecord {
                    schema_version: row.get(0)?,
                    project_id: row.get(1)?,
                    authoring_node_id: row.get(2)?,
                    part_id: row.get(3)?,
                    lineage_id: row.get(4)?,
                    genesis_source_mesh_sha256: row.get(5)?,
                    current_source_mesh_sha256: row.get(6)?,
                    candidate_id: row.get(7)?,
                    candidate_state_sha256: row.get(8)?,
                    base_version_id: row.get(9)?,
                    canonical_mesh_id: row.get(10)?,
                    canonical_mesh_object_sha256: row.get(11)?,
                    canonical_mesh_sha256: row.get(12)?,
                    parent_lineage_object_sha256: row.get(13)?,
                    parent_lineage_sha256: row.get(14)?,
                    revision_index,
                    revision_kind: row.get(16)?,
                    operation_lineage_sha256: row.get(17)?,
                    source_program_object_sha256: row.get(18)?,
                    source_program_sha256: row.get(19)?,
                    source_artifact_object_sha256: row.get(20)?,
                    source_artifact_sha256: row.get(21)?,
                    source_artifact_readback_object_sha256: row.get(22)?,
                    source_artifact_readback_sha256: row.get(23)?,
                    operator_catalog_sha256: row.get(24)?,
                    readback_config_sha256: row.get(25)?,
                    evaluated_artifact_object_sha256: row.get(26)?,
                    evaluated_artifact_sha256: row.get(27)?,
                    evaluated_artifact_readback_object_sha256: row.get(28)?,
                    evaluated_artifact_readback_sha256: row.get(29)?,
                    identity_lineage_object_sha256: row.get(30)?,
                    identity_lineage_sha256: row.get(31)?,
                    request_input_sha256: row.get(32)?,
                    idempotency_key: row.get(33)?,
                    materialization_status: row.get(34)?,
                    canonical_sha256: row.get(35)?,
                    created_at: row.get(36)?,
                })
            },
        )
        .optional()
        .map_err(StoreError::from)
}

fn validate_authoring_mesh_identity_lineage_object(
    cas: &CasStore,
    object: &CasObjectRecord,
    require_reachable: bool,
) -> Result<Vec<u8>, StoreError> {
    validate_authoring_mesh_durable_json_object(
        cas,
        object,
        &object.sha256,
        AUTHORING_MESH_IDENTITY_LINEAGE_OBJECT_KIND,
        require_reachable,
    )
}

fn validate_authoring_mesh_identity_binding_object(
    cas: &CasStore,
    object: &CasObjectRecord,
    expected_kinds: &[&str],
    maximum_bytes: u64,
    require_reachable: bool,
) -> Result<Vec<u8>, StoreError> {
    let allowed = expected_kinds.iter().any(|kind| *kind == object.kind);
    let expected_mime = if matches!(
        object.kind.as_str(),
        "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
    ) {
        "model/gltf-binary"
    } else {
        "application/json"
    };
    if object.schema_version != "CasObject@1"
        || !is_sha256(&object.sha256)
        || !allowed
        || object.mime != expected_mime
        || object.size_bytes == 0
        || object.size_bytes > maximum_bytes
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || (require_reachable && object.reachability != "reachable")
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_CAS_METADATA_INVALID",
            "identity lineage CAS object metadata is missing, quarantined or incorrectly typed",
        ));
    }
    cas.read_verified_bounded(&object.sha256, maximum_bytes)
        .map_err(StoreError::from)
}

fn identity_lineage_object_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    sha256: &str,
    expected_kinds: &[&str],
    maximum_bytes: u64,
    require_reachable: bool,
) -> Result<(CasObjectRecord, Vec<u8>), StoreError> {
    let object = authoring_mesh_object_record_in_transaction(transaction, sha256)?;
    ensure_authoring_mesh_durable_json_object_row(transaction, &object, require_reachable)?;
    let bytes = validate_authoring_mesh_identity_binding_object(
        cas,
        &object,
        expected_kinds,
        maximum_bytes,
        require_reachable,
    )?;
    Ok((object, bytes))
}

fn validate_authoring_mesh_identity_canonical_payload(
    bytes: &[u8],
    record: &AuthoringMeshIdentityLineageDurableRecord,
) -> Result<(), StoreError> {
    let value = durable_json(bytes, "AuthoringMeshCanonical@1 is not closed JSON")?;
    let canonical =
        canonical_hash_from_payload(&value, "AuthoringMeshCanonical@1 canonical hash is invalid")?;
    if durable_text(&value, "schema_version") != Some("AuthoringMeshCanonical@1")
        || durable_text(&value, "canonical_mesh_id") != Some(record.canonical_mesh_id.as_str())
        || durable_text(&value, "project_id") != Some(record.project_id.as_str())
        || durable_text(&value, "candidate_id") != Some(record.candidate_id.as_str())
        || durable_text(&value, "candidate_state_sha256")
            != Some(record.candidate_state_sha256.as_str())
        || identity_lineage_nullable_string(&value, "base_version_id") != record.base_version_id
        || durable_text(&value, "authoring_node_id") != Some(record.authoring_node_id.as_str())
        || durable_text(&value, "part_id") != Some(record.part_id.as_str())
        || durable_text(&value, "source_program_object_sha256")
            != Some(record.source_program_object_sha256.as_str())
        || durable_text(&value, "source_program_sha256")
            != Some(record.source_program_sha256.as_str())
        || durable_text(&value, "source_artifact_object_sha256")
            != Some(record.source_artifact_object_sha256.as_str())
        || durable_text(&value, "source_artifact_sha256")
            != Some(record.source_artifact_sha256.as_str())
        || durable_text(&value, "source_artifact_readback_object_sha256")
            != Some(record.source_artifact_readback_object_sha256.as_str())
        || durable_text(&value, "source_artifact_readback_sha256")
            != Some(record.source_artifact_readback_sha256.as_str())
        || canonical != record.canonical_mesh_sha256
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_CANONICAL_BINDING_MISMATCH",
            "current canonical AuthoringMesh object differs from the identity lineage row",
        ));
    }
    Ok(())
}

fn validate_authoring_mesh_identity_evaluated_payload(
    bytes: &[u8],
    record: &AuthoringMeshIdentityLineageDurableRecord,
) -> Result<(), StoreError> {
    let value = durable_json(bytes, "AuthoringMeshArtifact@1 is not closed JSON")?;
    if durable_text(&value, "schema_version") != Some("AuthoringMeshArtifact@1")
        || durable_text(&value, "project_id") != Some(record.project_id.as_str())
        || durable_text(&value, "candidate_id") != Some(record.candidate_id.as_str())
        || durable_text(&value, "candidate_state_sha256")
            != Some(record.candidate_state_sha256.as_str())
        || durable_text(&value, "authoring_node_id") != Some(record.authoring_node_id.as_str())
        || durable_text(&value, "part_id") != Some(record.part_id.as_str())
        || durable_text(&value, "canonical_mesh_id") != Some(record.canonical_mesh_id.as_str())
        || durable_text(&value, "canonical_mesh_object_sha256")
            != Some(record.canonical_mesh_object_sha256.as_str())
        || durable_text(&value, "canonical_mesh_sha256")
            != Some(record.canonical_mesh_sha256.as_str())
        || durable_text(&value, "source_program_object_sha256")
            != Some(record.source_program_object_sha256.as_str())
        || durable_text(&value, "source_program_sha256")
            != Some(record.source_program_sha256.as_str())
        || durable_text(&value, "evaluated_artifact_object_sha256")
            != Some(record.source_artifact_object_sha256.as_str())
        || durable_text(&value, "evaluated_artifact_sha256")
            != Some(record.source_artifact_sha256.as_str())
        || durable_text(&value, "evaluated_artifact_readback_object_sha256")
            != Some(record.source_artifact_readback_object_sha256.as_str())
        || durable_text(&value, "evaluated_artifact_readback_sha256")
            != Some(record.source_artifact_readback_sha256.as_str())
        || canonical_hash_from_payload(&value, "AuthoringMeshArtifact@1 canonical hash is invalid")?
            != record.evaluated_artifact_sha256
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_EVALUATED_BINDING_MISMATCH",
            "evaluated AuthoringMesh sidecar differs from the identity lineage row",
        ));
    }
    Ok(())
}

fn validate_authoring_mesh_identity_readback_payload(
    bytes: &[u8],
    expected_semantic_sha256: &str,
    context: &str,
) -> Result<(), StoreError> {
    let value = durable_json(bytes, context)?;
    if let Some(canonical) = value.get("canonical_sha256").and_then(Value::as_str) {
        if !is_sha256(canonical) || canonical != expected_semantic_sha256 {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_READBACK_BINDING_MISMATCH",
                context,
            ));
        }
    }
    Ok(())
}

fn validate_authoring_mesh_identity_lineage_transition_relations(
    record: &AuthoringMeshIdentityLineageDurableRecord,
    previous_payload: &Value,
    current_payload: &Value,
    previous_active: &HashSet<String>,
    previous_tombstones: &HashSet<String>,
    current_active: &HashSet<String>,
    current_tombstones: &HashSet<String>,
) -> Result<(), StoreError> {
    let previous_object = previous_payload.as_object().ok_or_else(|| {
        authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_INVALID",
            "identity lineage immediate parent payload is not an object",
        )
    })?;
    let current_object = current_payload.as_object().ok_or_else(|| {
        authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_INVALID",
            "identity lineage current payload is not an object",
        )
    })?;
    if previous_object.get("lineage_id") != current_object.get("lineage_id")
        || previous_object.get("project_id") != current_object.get("project_id")
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_BINDING_MISMATCH",
            "identity lineage correspondence parent and child belong to different lineages",
        ));
    }
    let correspondence = current_object
        .get("correspondence")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_INVALID",
                "identity lineage correspondence is missing",
            )
        })?;
    // Historical preserving-edit payloads predating typed topology
    // correspondence may intentionally carry an empty correspondence list.
    // Keep those records readable; a topology-edit revision must provide the
    // explicit parent/child relation instead of relying on mesh diffs.
    if correspondence.is_empty() {
        if record.revision_kind == "topology-edit" {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_INVALID",
                "topology identity revision has no explicit correspondence",
            ));
        }
        return Ok(());
    }
    let mut correspondence_parent_ids = HashSet::new();
    let mut correspondence_child_ids = HashSet::new();
    let mut correspondence_retired_ids = HashSet::new();
    for item in correspondence {
        let item = identity_lineage_closed_object(
            item,
            AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_FIELDS,
            "identity lineage transition correspondence shape is invalid",
        )?;
        let kind = item.get("kind").and_then(Value::as_str).ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_INVALID",
                "identity lineage transition correspondence kind is missing",
            )
        })?;
        let parents = identity_lineage_ids_array(
            &Value::Object(item.clone()),
            "parent_identity_ids",
            8,
            "identity lineage transition correspondence parent list is invalid",
        )?;
        let children = identity_lineage_ids_array(
            &Value::Object(item.clone()),
            "child_identity_ids",
            64,
            "identity lineage transition correspondence child list is invalid",
        )?;
        let shape_valid = match kind {
            "preserved" => parents.len() == 1 && children.len() == 1 && parents[0] == children[0],
            "created" => parents.is_empty() && children.len() == 1,
            "retired" => !parents.is_empty() && children.is_empty(),
            "one-to-many" => parents.len() == 1 && children.len() >= 2,
            "many-to-one" => parents.len() >= 2 && children.len() == 1,
            "many-to-many" => parents.len() >= 2 && children.len() >= 2,
            _ => false,
        };
        if !shape_valid
            || !parents.iter().all(|id| previous_active.contains(id))
            || parents.iter().any(|id| previous_tombstones.contains(id))
            || !children.iter().all(|id| current_active.contains(id))
            || children.iter().any(|id| current_tombstones.contains(id))
            || (kind == "retired" && parents.iter().any(|id| !current_tombstones.contains(id)))
            || !is_sha256(
                item.get("operation_lineage_sha256")
                    .and_then(Value::as_str)
                    .unwrap_or_default(),
            )
            || item.get("operation_lineage_sha256").and_then(Value::as_str)
                != current_object
                    .get("operation_lineage_sha256")
                    .and_then(Value::as_str)
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_BINDING_MISMATCH",
                "identity lineage correspondence parent/child IDs or operation hash differ from the immediate revision",
            ));
        }
        if parents
            .iter()
            .any(|id| !correspondence_parent_ids.insert(id.clone()))
            || children
                .iter()
                .any(|id| !correspondence_child_ids.insert(id.clone()))
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_INVALID",
                "an identity appears in multiple transition correspondence relations",
            ));
        }
        for id in &parents {
            if kind == "retired" || current_tombstones.contains(id) {
                correspondence_retired_ids.insert(id.clone());
            }
        }
    }

    if record.revision_kind == "topology-edit"
        && current_active
            .difference(previous_active)
            .any(|identity_id| !correspondence_child_ids.contains(identity_id))
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_CORRESPONDENCE_INVALID",
            "a new topology identity has no explicit correspondence child relation",
        ));
    }

    let new_tombstones = current_tombstones
        .difference(previous_tombstones)
        .cloned()
        .collect::<HashSet<_>>();
    for identity_id in &new_tombstones {
        if !previous_active.contains(identity_id)
            || !correspondence_parent_ids.contains(identity_id)
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_RETIREMENT_MISMATCH",
                "a newly retired identity is not related to an immediate-parent active identity",
            ));
        }
    }
    for identity_id in previous_active {
        if !current_active.contains(identity_id)
            && !current_tombstones.contains(identity_id)
            && !correspondence_retired_ids.contains(identity_id)
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_RETIREMENT_MISMATCH",
                "an identity removed from the immediate parent has no correspondence or tombstone",
            ));
        }
    }
    let tombstones = current_object
        .get("tombstones")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_TOMBSTONE_INVALID",
                "identity lineage transition tombstones are missing",
            )
        })?;
    for tombstone in tombstones {
        let tombstone = identity_lineage_closed_object(
            tombstone,
            AUTHORING_MESH_IDENTITY_LINEAGE_TOMBSTONE_FIELDS,
            "identity lineage transition tombstone shape is invalid",
        )?;
        let identity_id = tombstone
            .get("identity_id")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                authoring_mesh_contract(
                    "AUTHORING_MESH_IDENTITY_LINEAGE_TOMBSTONE_INVALID",
                    "identity lineage transition tombstone identity is missing",
                )
            })?;
        if new_tombstones.contains(identity_id)
            && (tombstone
                .get("retired_revision_index")
                .and_then(Value::as_u64)
                != Some(record.revision_index)
                || tombstone
                    .get("operation_lineage_sha256")
                    .and_then(Value::as_str)
                    != Some(record.operation_lineage_sha256.as_str()))
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_TOMBSTONE_BINDING_MISMATCH",
                "new identity lineage tombstone does not bind the current revision and operation",
            ));
        }
    }
    Ok(())
}

fn ensure_authoring_mesh_identity_lineage_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    record: &AuthoringMeshIdentityLineageDurableRecord,
    require_reachable: bool,
) -> Result<Vec<String>, StoreError> {
    let candidate: Option<(String, Option<String>, String, Option<String>)> = transaction
        .query_row(
            "SELECT project_id, prepared_object_sha256, canonical_sha256, base_version_id FROM candidates WHERE candidate_id = ?1",
            params![record.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((candidate_project, prepared_artifact, candidate_state, base_version_id)) = candidate
    else {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_CANDIDATE_UNAVAILABLE",
            "candidate is unavailable for identity lineage",
        ));
    };
    if candidate_project != record.project_id
        || prepared_artifact.as_deref() != Some(record.source_artifact_object_sha256.as_str())
        || candidate_state != record.candidate_state_sha256
        || base_version_id != record.base_version_id
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_CANDIDATE_BINDING_MISMATCH",
            "candidate project, state, base version or source artifact differs",
        ));
    }

    let evidence: Option<(String, String, String, String, String, String, String)> = transaction
        .query_row(
            "SELECT project_id, geometry_program_sha256, geometry_program_object_sha256, operator_catalog_sha256, readback_config_sha256, artifact_object_sha256, artifact_readback_object_sha256 FROM geometry_candidate_evidence WHERE candidate_id = ?1 AND artifact_object_sha256 = ?2",
            params![record.candidate_id, record.source_artifact_object_sha256],
            |row| {
                Ok((
                    row.get(0)?,
                    row.get(1)?,
                    row.get(2)?,
                    row.get(3)?,
                    row.get(4)?,
                    row.get(5)?,
                    row.get(6)?,
                ))
            },
        )
        .optional()?;
    let Some((
        evidence_project,
        evidence_program,
        evidence_program_object,
        evidence_catalog,
        evidence_config,
        evidence_artifact,
        evidence_readback_object,
    )) = evidence
    else {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_EVIDENCE_UNAVAILABLE",
            "geometry candidate evidence is unavailable for identity lineage",
        ));
    };
    if evidence_project != record.project_id
        || evidence_program != record.source_program_sha256
        || evidence_program_object != record.source_program_object_sha256
        || evidence_catalog != record.operator_catalog_sha256
        || evidence_config != record.readback_config_sha256
        || evidence_artifact != record.source_artifact_object_sha256
        || evidence_readback_object != record.source_artifact_readback_object_sha256
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_EVIDENCE_BINDING_MISMATCH",
            "identity lineage source bindings differ from durable geometry evidence",
        ));
    }

    let (canonical_object, canonical_bytes) = identity_lineage_object_in_transaction(
        transaction,
        cas,
        &record.canonical_mesh_object_sha256,
        &[AUTHORING_MESH_CANONICAL_OBJECT_KIND],
        AUTHORING_MESH_IDENTITY_LINEAGE_MAX_BYTES,
        require_reachable,
    )?;
    validate_authoring_mesh_identity_canonical_payload(&canonical_bytes, record)?;

    let (_, program_bytes) = identity_lineage_object_in_transaction(
        transaction,
        cas,
        &record.source_program_object_sha256,
        &[AUTHORING_MESH_EDIT_GEOMETRY_PROGRAM_KIND],
        AUTHORING_MESH_IDENTITY_LINEAGE_MAX_BYTES,
        require_reachable,
    )?;
    if program_bytes.is_empty() {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_SOURCE_INVALID",
            "source geometry program bytes are empty",
        ));
    }
    let (_, source_artifact_bytes) = identity_lineage_object_in_transaction(
        transaction,
        cas,
        &record.source_artifact_object_sha256,
        &[
            AUTHORING_MESH_EDIT_GEOMETRY_ARTIFACT_KIND,
            "appearance-glb",
            "appearance-v2-glb",
        ],
        AUTHORING_MESH_DURABLE_GLTF_MAX_BYTES,
        require_reachable,
    )?;
    if source_artifact_bytes.is_empty() {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_SOURCE_INVALID",
            "source artifact bytes are empty",
        ));
    }
    let (_, source_readback_bytes) = identity_lineage_object_in_transaction(
        transaction,
        cas,
        &record.source_artifact_readback_object_sha256,
        &[AUTHORING_MESH_EDIT_ARTIFACT_READBACK_KIND],
        AUTHORING_MESH_IDENTITY_LINEAGE_MAX_BYTES,
        require_reachable,
    )?;
    validate_authoring_mesh_identity_readback_payload(
        &source_readback_bytes,
        &record.source_artifact_readback_sha256,
        "source artifact readback binding differs",
    )?;

    let evaluated_max =
        if record.evaluated_artifact_object_sha256 == record.source_artifact_object_sha256 {
            AUTHORING_MESH_DURABLE_GLTF_MAX_BYTES
        } else {
            AUTHORING_MESH_IDENTITY_LINEAGE_MAX_BYTES
        };
    let (evaluated_object, evaluated_bytes) = identity_lineage_object_in_transaction(
        transaction,
        cas,
        &record.evaluated_artifact_object_sha256,
        &[
            AUTHORING_MESH_ARTIFACT_OBJECT_KIND,
            AUTHORING_MESH_EDIT_GEOMETRY_ARTIFACT_KIND,
            "appearance-glb",
            "appearance-v2-glb",
        ],
        evaluated_max,
        require_reachable,
    )?;
    if evaluated_object.kind == AUTHORING_MESH_ARTIFACT_OBJECT_KIND {
        validate_authoring_mesh_identity_evaluated_payload(&evaluated_bytes, record)?;
    }
    let evaluated_readback_max = AUTHORING_MESH_IDENTITY_LINEAGE_MAX_BYTES;
    let (evaluated_readback_object, evaluated_readback_bytes) =
        identity_lineage_object_in_transaction(
            transaction,
            cas,
            &record.evaluated_artifact_readback_object_sha256,
            &[
                AUTHORING_MESH_EDIT_ARTIFACT_READBACK_KIND,
                "authoring-mesh-artifact-readback",
            ],
            evaluated_readback_max,
            require_reachable,
        )?;
    if evaluated_readback_object.mime == "application/json" {
        validate_authoring_mesh_identity_readback_payload(
            &evaluated_readback_bytes,
            &record.evaluated_artifact_readback_sha256,
            "evaluated artifact readback binding differs",
        )?;
    }

    let quality_object: Option<String> = transaction
        .query_row(
            "SELECT quality_report_object_sha256 FROM geometry_candidate_evidence WHERE candidate_id = ?1",
            params![record.candidate_id],
            |row| row.get(0),
        )
        .optional()?;
    let quality_object = quality_object.ok_or_else(|| {
        authoring_mesh_contract(
            "AUTHORING_MESH_IDENTITY_LINEAGE_EVIDENCE_UNAVAILABLE",
            "geometry evidence quality root is unavailable",
        )
    })?;
    let _ = identity_lineage_object_in_transaction(
        transaction,
        cas,
        &quality_object,
        &[AUTHORING_MESH_EDIT_QUALITY_KIND],
        AUTHORING_MESH_IDENTITY_LINEAGE_MAX_BYTES,
        require_reachable,
    )?;

    let mut roots = vec![
        canonical_object.sha256,
        record.source_program_object_sha256.clone(),
        record.source_artifact_object_sha256.clone(),
        record.source_artifact_readback_object_sha256.clone(),
        record.evaluated_artifact_object_sha256.clone(),
        record.evaluated_artifact_readback_object_sha256.clone(),
        quality_object,
    ];

    if record.revision_index > 0 {
        let previous_revision = i64::try_from(record.revision_index - 1).map_err(|_| {
            StoreError::InvalidData("identity lineage revision index is too large".to_owned())
        })?;
        let previous_idempotency: Option<String> = transaction
            .query_row(
                "SELECT idempotency_key FROM authoring_mesh_identity_lineage_durable_records WHERE project_id = ?1 AND lineage_id = ?2 AND revision_index = ?3",
                params![record.project_id, record.lineage_id, previous_revision],
                |row| row.get(0),
            )
            .optional()?;
        let previous_idempotency = previous_idempotency.ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PARENT_UNAVAILABLE",
                "non-genesis identity lineage parent revision is unavailable",
            )
        })?;
        let previous = read_authoring_mesh_identity_lineage_in_transaction(
            transaction,
            &record.project_id,
            &previous_idempotency,
        )?
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PARENT_UNAVAILABLE",
                "identity lineage parent row is unavailable",
            )
        })?;
        if previous.lineage_id != record.lineage_id
            || previous.genesis_source_mesh_sha256 != record.genesis_source_mesh_sha256
            || record.parent_lineage_object_sha256.as_deref()
                != Some(previous.identity_lineage_object_sha256.as_str())
            || record.parent_lineage_sha256.as_deref()
                != Some(previous.identity_lineage_sha256.as_str())
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PARENT_BINDING_MISMATCH",
                "identity lineage parent object or semantic hash differs",
            ));
        }
        let parent_object = authoring_mesh_object_record_in_transaction(
            transaction,
            &previous.identity_lineage_object_sha256,
        )?;
        let parent_bytes = validate_authoring_mesh_identity_lineage_object(
            cas,
            &parent_object,
            require_reachable,
        )?;
        let parent_canonical = canonical_hash_from_payload(
            &durable_json(&parent_bytes, "identity lineage parent payload is invalid")?,
            "identity lineage parent canonical hash is invalid",
        )?;
        if parent_canonical != previous.identity_lineage_sha256 {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_PARENT_TAMPERED",
                "identity lineage parent payload no longer matches its bound hash",
            ));
        }
        roots.push(previous.identity_lineage_object_sha256);
    }

    let previous_rows: Vec<(String, String)> = {
        let mut statement = transaction.prepare(
            "SELECT idempotency_key, identity_lineage_object_sha256 FROM authoring_mesh_identity_lineage_durable_records WHERE project_id = ?1 AND lineage_id = ?2 AND revision_index < ?3 ORDER BY revision_index ASC",
        )?;
        let rows = statement
            .query_map(
                params![
                    record.project_id,
                    record.lineage_id,
                    i64::try_from(record.revision_index).map_err(|_| StoreError::InvalidData(
                        "identity lineage revision index is too large".to_owned()
                    ))?
                ],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )?
            .collect::<Result<Vec<_>, _>>()?;
        rows
    };
    let current_identity_bytes = cas.read_verified_bounded(
        &record.identity_lineage_object_sha256,
        AUTHORING_MESH_IDENTITY_LINEAGE_MAX_BYTES,
    )?;
    let current_identity_payload = durable_json(
        &current_identity_bytes,
        "identity lineage current payload is invalid",
    )?;
    let current_ids =
        validate_authoring_mesh_identity_lineage_payload(&current_identity_bytes, record)?;
    for (previous_idempotency, previous_object_sha256) in previous_rows {
        let previous = read_authoring_mesh_identity_lineage_in_transaction(
            transaction,
            &record.project_id,
            &previous_idempotency,
        )?
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_HISTORY_CORRUPT",
                "identity lineage history row is unavailable",
            )
        })?;
        let previous_object =
            authoring_mesh_object_record_in_transaction(transaction, &previous_object_sha256)?;
        let previous_bytes = validate_authoring_mesh_identity_lineage_object(
            cas,
            &previous_object,
            require_reachable,
        )?;
        let (previous_active, previous_tombstones) =
            validate_authoring_mesh_identity_lineage_payload(&previous_bytes, &previous)?;
        if previous.revision_index.checked_add(1) == Some(record.revision_index) {
            let previous_payload = durable_json(
                &previous_bytes,
                "identity lineage immediate parent payload is invalid",
            )?;
            validate_authoring_mesh_identity_lineage_transition_relations(
                record,
                &previous_payload,
                &current_identity_payload,
                &previous_active,
                &previous_tombstones,
                &current_ids.0,
                &current_ids.1,
            )?;
        }
        if current_ids
            .0
            .iter()
            .any(|identity_id| previous_tombstones.contains(identity_id))
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_TOMBSTONE_REUSE",
                "a tombstoned identity was reused in a later lineage revision",
            ));
        }
        if previous_tombstones
            .iter()
            .any(|identity_id| !current_ids.1.contains(identity_id))
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_TOMBSTONE_REUSE",
                "identity lineage tombstones are not monotonic",
            ));
        }
        if previous.revision_index.checked_add(1) == Some(record.revision_index) {
            if current_ids
                .1
                .difference(&previous_tombstones)
                .any(|identity_id| !previous_active.contains(identity_id))
            {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_IDENTITY_LINEAGE_RETIREMENT_MISMATCH",
                    "a new tombstone does not retire an active identity from the immediate parent",
                ));
            }
            if previous_active.iter().any(|identity_id| {
                !current_ids.0.contains(identity_id) && !current_ids.1.contains(identity_id)
            }) {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_IDENTITY_LINEAGE_RETIREMENT_MISMATCH",
                    "an identity removed from the immediate parent has no monotonic tombstone",
                ));
            }
        }
        if record.genesis_source_mesh_sha256 != previous.genesis_source_mesh_sha256 {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_IDENTITY_LINEAGE_GENESIS_BINDING_MISMATCH",
                "identity lineage genesis source changed across revisions",
            ));
        }
        roots.push(previous_object_sha256);
    }
    roots.sort();
    roots.dedup();
    Ok(roots)
}

fn validate_authoring_mesh_identity_lineage_record_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    record: &AuthoringMeshIdentityLineageDurableRecord,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let identity_object = authoring_mesh_object_record_in_transaction(
        transaction,
        &record.identity_lineage_object_sha256,
    )?;
    let identity_bytes =
        validate_authoring_mesh_identity_lineage_object(cas, &identity_object, require_reachable)?;
    ensure_authoring_mesh_durable_json_object_row(
        transaction,
        &identity_object,
        require_reachable,
    )?;
    validate_authoring_mesh_identity_lineage_payload(&identity_bytes, record)?;
    ensure_authoring_mesh_identity_lineage_in_transaction(
        transaction,
        cas,
        record,
        require_reachable,
    )
    .map(|_| ())
}

fn authoring_mesh_contract(code: &str, message: &str) -> StoreError {
    StoreError::Contract {
        code: code.to_owned(),
        message: message.to_owned(),
    }
}

fn validate_authoring_mesh_topology_operation_proof(
    response: &Value,
    project_id: &str,
    source_candidate_id: &str,
    target_candidate_id: &str,
) -> Result<(), StoreError> {
    // Existing translate/single-face edit responses do not carry a topology
    // operation.  They are outside this branch and retain their historical
    // Store contract; only an explicit closed operation enters the proof gate.
    let Some(operation) = response.get("operation").and_then(Value::as_str) else {
        return Ok(());
    };
    if !AUTHORING_MESH_TOPOLOGY_EDIT_OPERATIONS.contains(&operation) {
        return Ok(());
    }
    if response.get("project_id").and_then(Value::as_str) != Some(project_id)
        || response.get("source_candidate_id").and_then(Value::as_str) != Some(source_candidate_id)
        || response.get("new_candidate_id").and_then(Value::as_str) != Some(target_candidate_id)
        || source_candidate_id == target_candidate_id
        || response.get("topology_edit").is_some()
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_TOPOLOGY_EDIT_BINDING_MISMATCH",
            "typed topology proof differs from its project/candidate binding or attempts an unmaterialized IdentityLineage claim",
        ));
    }
    let candidate = response
        .get("candidate")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_TOPOLOGY_EDIT_BINDING_MISMATCH",
                "typed topology edit has no staged candidate binding",
            )
        })?;
    if candidate.get("candidate_id").and_then(Value::as_str) != Some(target_candidate_id)
        || candidate.get("project_id").and_then(Value::as_str) != Some(project_id)
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_TOPOLOGY_EDIT_BINDING_MISMATCH",
            "typed topology edit staged candidate differs from its target binding",
        ));
    }
    let edited = response
        .get("edited_element_ids")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            authoring_mesh_contract(
                "AUTHORING_MESH_TOPOLOGY_EDIT_SCHEMA_INVALID",
                "typed topology edit has no edited-element object",
            )
        })?;
    let proof_value = edited.get("typed_operation_proof").ok_or_else(|| {
        authoring_mesh_contract(
            "AUTHORING_MESH_TOPOLOGY_EDIT_PROOF_MISSING",
            "typed topology edit has no source-element operation proof",
        )
    })?;
    let proof: AuthoringMeshTopologyOperationProof = serde_json::from_value(proof_value.clone())
        .map_err(|_| {
            authoring_mesh_contract(
                "AUTHORING_MESH_TOPOLOGY_EDIT_SCHEMA_INVALID",
                "typed topology operation proof contains unknown, missing or incorrectly typed fields",
            )
        })?;
    let namespace = "source-element-only-not-materialized-to-identity-lineage@1";
    if proof.schema_version != "AuthoringMeshTopologyOperationProof@1"
        || proof.operation != operation
        || proof.parent_revision > 1_000_000
        || proof.child_revision != proof.parent_revision.checked_add(1).unwrap_or_default()
        || !is_sha256(&proof.operation_lineage_sha256)
        || proof.identity_namespace_status != namespace
        || !is_sha256(&proof.canonical_sha256)
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_TOPOLOGY_EDIT_PROOF_INVALID",
            "typed topology operation proof metadata differs",
        ));
    }
    let mut canonical = proof_value.clone();
    canonical["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&canonical) != proof.canonical_sha256 {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_TOPOLOGY_EDIT_PROOF_CANONICAL_MISMATCH",
            "typed topology operation proof canonical hash differs",
        ));
    }
    let lists = [
        ("source_vertex_ids", &proof.source_vertex_ids),
        ("source_edge_ids", &proof.source_edge_ids),
        ("source_face_ids", &proof.source_face_ids),
        ("generated_vertex_ids", &proof.generated_vertex_ids),
        ("generated_edge_ids", &proof.generated_edge_ids),
        ("generated_loop_ids", &proof.generated_loop_ids),
        ("generated_face_ids", &proof.generated_face_ids),
        ("retired_vertex_ids", &proof.retired_vertex_ids),
        ("retired_edge_ids", &proof.retired_edge_ids),
        ("retired_loop_ids", &proof.retired_loop_ids),
        ("retired_face_ids", &proof.retired_face_ids),
    ];
    let mut source_ids = std::collections::BTreeSet::new();
    let mut generated_ids = std::collections::BTreeSet::new();
    let mut retired_ids = std::collections::BTreeSet::new();
    for (field, ids) in lists {
        let unique = ids.iter().collect::<std::collections::BTreeSet<_>>();
        if ids.len() > 64 || unique.len() != ids.len() || ids.iter().any(|id| !is_opaque_id(id)) {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_TOPOLOGY_EDIT_ID_SET_INVALID",
                "typed topology operation proof contains invalid or duplicate source-element IDs",
            ));
        }
        let target = if field.starts_with("source_") {
            &mut source_ids
        } else if field.starts_with("generated_") {
            &mut generated_ids
        } else {
            &mut retired_ids
        };
        for id in ids {
            if !target.insert(id.clone()) {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_TOPOLOGY_EDIT_ID_SET_INVALID",
                    "typed topology operation proof reuses an element ID across namespaces",
                ));
            }
        }
    }
    // A retired source element is intentionally present in both the source
    // inventory and the retired inventory: that is how the proof binds a
    // source edge/face/vertex to its tombstone.  Only generated IDs must be
    // disjoint from both inventories; allowing a generated ID to overlap a
    // source or retired ID would permit identity reuse in the child.
    if source_ids.iter().any(|id| generated_ids.contains(id))
        || generated_ids.iter().any(|id| retired_ids.contains(id))
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_TOPOLOGY_EDIT_TOMBSTONE_REUSE",
            "typed topology operation proof reuses a generated source-element ID",
        ));
    }
    for (field, expected) in [
        ("source_vertex_ids", &proof.source_vertex_ids),
        ("source_face_ids", &proof.source_face_ids),
        ("generated_vertex_ids", &proof.generated_vertex_ids),
        ("generated_edge_ids", &proof.generated_edge_ids),
        ("generated_loop_ids", &proof.generated_loop_ids),
        ("generated_face_ids", &proof.generated_face_ids),
    ] {
        let actual: Vec<String> = serde_json::from_value(
            edited.get(field).cloned().unwrap_or(Value::Null),
        )
        .map_err(|_| {
            authoring_mesh_contract(
                "AUTHORING_MESH_TOPOLOGY_EDIT_SCHEMA_INVALID",
                "edited-element generated ID set is malformed",
            )
        })?;
        if &actual != expected {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_TOPOLOGY_EDIT_PROOF_MISMATCH",
                "edited-element generated IDs differ from the typed operation proof",
            ));
        }
    }
    if proof.correspondence.len() != 1 {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_TOPOLOGY_EDIT_CORRESPONDENCE_INVALID",
            "typed topology edit must expose exactly one bounded correspondence",
        ));
    }
    let correspondence = &proof.correspondence[0];
    let expected_kind = if operation == "split_edge" {
        "one-to-many"
    } else {
        "many-to-one"
    };
    let same_ids = |left: &[String], right: &[String]| {
        left.iter().collect::<std::collections::BTreeSet<_>>()
            == right.iter().collect::<std::collections::BTreeSet<_>>()
    };
    let closed_mapping = match operation {
        "split_edge" => {
            same_ids(
                &correspondence.parent_source_element_ids,
                &proof.source_edge_ids,
            ) && same_ids(
                &correspondence.child_source_element_ids,
                &proof.generated_edge_ids,
            ) && correspondence.parent_source_element_ids.len() == 1
                && correspondence.child_source_element_ids.len() >= 2
                && same_ids(&proof.retired_edge_ids, &proof.source_edge_ids)
        }
        "collapse_edge" => {
            same_ids(
                &correspondence.parent_source_element_ids,
                &proof.source_vertex_ids,
            ) && correspondence.parent_source_element_ids.len() == 2
                && correspondence.child_source_element_ids.len() == 1
                && proof
                    .source_vertex_ids
                    .contains(&correspondence.child_source_element_ids[0])
                && proof.retired_vertex_ids.len() == 1
                && proof
                    .source_vertex_ids
                    .iter()
                    .any(|id| !proof.retired_vertex_ids.contains(id))
        }
        "dissolve_edge" => {
            same_ids(
                &correspondence.parent_source_element_ids,
                &proof.source_face_ids,
            ) && correspondence.parent_source_element_ids.len() >= 2
                && correspondence.child_source_element_ids.len() == 1
                && correspondence
                    .child_source_element_ids
                    .iter()
                    .all(|id| proof.generated_face_ids.contains(id))
                && proof
                    .source_face_ids
                    .iter()
                    .all(|id| proof.retired_face_ids.contains(id))
        }
        _ => unreachable!(),
    };
    if !AUTHORING_MESH_TOPOLOGY_CORRESPONDENCE_KINDS.contains(&correspondence.kind.as_str())
        || correspondence.kind != expected_kind
        || !closed_mapping
        || correspondence.operation_lineage_sha256 != proof.operation_lineage_sha256
        || correspondence.identity_namespace_status != namespace
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_TOPOLOGY_EDIT_CORRESPONDENCE_INVALID",
            "typed topology correspondence differs from the closed operation semantics",
        ));
    }
    if proof.tombstones.is_empty() {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_TOPOLOGY_EDIT_TOMBSTONE_INVALID",
            "typed topology operation must carry at least one tombstone",
        ));
    }
    let mut tombstone_ids = std::collections::BTreeSet::new();
    for item in &proof.tombstones {
        let retired_for_kind = match item.element_kind.as_str() {
            "vertex" => &proof.retired_vertex_ids,
            "edge" => &proof.retired_edge_ids,
            "loop" => &proof.retired_loop_ids,
            "face" => &proof.retired_face_ids,
            _ => {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_TOPOLOGY_EDIT_TOMBSTONE_INVALID",
                    "typed topology tombstone element kind is unsupported",
                ));
            }
        };
        if !is_opaque_id(&item.source_element_id)
            || !tombstone_ids.insert(item.source_element_id.clone())
            || !retired_for_kind.contains(&item.source_element_id)
            || generated_ids.contains(&item.source_element_id)
            || item.retired_revision_index != proof.child_revision
            || item.operation_lineage_sha256 != proof.operation_lineage_sha256
            || !matches!(
                item.reason.as_str(),
                "collapsed" | "dissolved" | "merged" | "replaced"
            )
        {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_TOPOLOGY_EDIT_TOMBSTONE_INVALID",
                "typed topology tombstone is not bound to one retired source element",
            ));
        }
    }
    let has_tombstone = |kind: &str, id: &str, reason: &str| {
        proof.tombstones.iter().any(|item| {
            item.element_kind == kind && item.source_element_id == id && item.reason == reason
        })
    };
    match operation {
        "split_edge" => {
            let Some(source_edge) = proof.source_edge_ids.first() else {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_TOPOLOGY_EDIT_TOMBSTONE_INVALID",
                    "split edge has no source edge to retire",
                ));
            };
            if !has_tombstone("edge", source_edge, "replaced") {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_TOPOLOGY_EDIT_TOMBSTONE_INVALID",
                    "split edge must retire its source edge as replaced",
                ));
            }
        }
        "collapse_edge" => {
            let Some(removed) = proof.retired_vertex_ids.first() else {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_TOPOLOGY_EDIT_TOMBSTONE_INVALID",
                    "collapse edge has no removed vertex to retire",
                ));
            };
            if !has_tombstone("vertex", removed, "collapsed")
                || !proof
                    .retired_edge_ids
                    .iter()
                    .any(|id| has_tombstone("edge", id, "collapsed"))
            {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_TOPOLOGY_EDIT_TOMBSTONE_INVALID",
                    "collapse edge must retire its removed vertex and source edges",
                ));
            }
        }
        "dissolve_edge" => {
            if !proof
                .retired_edge_ids
                .iter()
                .any(|id| has_tombstone("edge", id, "dissolved"))
                || !proof
                    .source_face_ids
                    .iter()
                    .all(|id| has_tombstone("face", id, "merged"))
            {
                return Err(authoring_mesh_contract(
                    "AUTHORING_MESH_TOPOLOGY_EDIT_TOMBSTONE_INVALID",
                    "dissolve edge must retire its source edge and merge its source faces",
                ));
            }
        }
        _ => unreachable!(),
    }
    Ok(())
}

fn native_high_contract(code: &str, message: &str) -> StoreError {
    StoreError::Contract {
        code: code.to_owned(),
        message: message.to_owned(),
    }
}

fn validate_native_high_durable_record(record: &NativeHighDurableRecord) -> Result<(), StoreError> {
    let identifiers = [
        record.project_id.as_str(),
        record.candidate_id.as_str(),
        record.source_canonical_mesh_id.as_str(),
        record.high_artifact_id.as_str(),
        record.link_id.as_str(),
        record.idempotency_key.as_str(),
    ];
    let hashes = [
        record.candidate_state_sha256.as_str(),
        record.source_canonical_mesh_object_sha256.as_str(),
        record.source_canonical_mesh_sha256.as_str(),
        record.detail_graph_object_sha256.as_str(),
        record.detail_graph_canonical_sha256.as_str(),
        record.high_mesh_artifact_object_sha256.as_str(),
        record.high_mesh_artifact_sha256.as_str(),
        record.high_artifact_object_sha256.as_str(),
        record.high_artifact_sha256.as_str(),
        record.high_artifact_readback_object_sha256.as_str(),
        record.high_artifact_readback_sha256.as_str(),
        record.link_object_sha256.as_str(),
        record.request_sha256.as_str(),
        record.input_sha256.as_str(),
        record.high_worker_build_cohort_sha256.as_str(),
        record.glb_worker_build_cohort_sha256.as_str(),
    ];
    if record.schema_version != NATIVE_HIGH_DURABLE_RECORD_SCHEMA_VERSION
        || identifiers.iter().any(|value| !is_opaque_id(value))
        || hashes.iter().any(|value| !is_sha256(value))
        || record
            .base_version_id
            .as_deref()
            .is_some_and(|value| !is_opaque_id(value))
        || record.idempotency_key.len() > 128
        || record.high_artifact_size_bytes == 0
        || record.high_artifact_size_bytes > NATIVE_HIGH_DURABLE_GLTF_MAX_BYTES
        || record.materialization_status != NATIVE_HIGH_DURABLE_RECORD_STATUS
        || (!record.canonical_sha256.is_empty() && !is_sha256(&record.canonical_sha256))
        || record.created_at.is_empty()
        || record.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "Native High durable record metadata is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn native_high_durable_record_canonical_sha256(
    record: &NativeHighDurableRecord,
) -> Result<String, StoreError> {
    let mut value =
        serde_json::to_value(record).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    value["canonical_sha256"] = Value::String(String::new());
    Ok(canonical_json_hash(&value))
}

fn normalize_native_high_durable_record(
    record: &NativeHighDurableRecord,
) -> Result<NativeHighDurableRecord, StoreError> {
    validate_native_high_durable_record(record)?;
    let expected = native_high_durable_record_canonical_sha256(record)?;
    if !record.canonical_sha256.is_empty() && record.canonical_sha256 != expected {
        return Err(native_high_contract(
            "NATIVE_HIGH_DURABLE_RECORD_CANONICAL_MISMATCH",
            "Native High durable record canonical hash is invalid",
        ));
    }
    let mut normalized = record.clone();
    normalized.canonical_sha256 = expected;
    Ok(normalized)
}

fn same_native_high_durable_record(
    left: &NativeHighDurableRecord,
    right: &NativeHighDurableRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

fn validate_native_high_cas_object(
    cas: &CasStore,
    object: &CasObjectRecord,
    expected_sha256: &str,
    expected_kind: &str,
    max_bytes: u64,
    require_reachable: bool,
) -> Result<Vec<u8>, StoreError> {
    if object.schema_version != "CasObject@1"
        || object.sha256 != expected_sha256
        || !is_sha256(&object.sha256)
        || object.mime
            != if expected_kind == PRODUCTION_WEAPON_HIGH_ARTIFACT_KIND {
                NATIVE_HIGH_DURABLE_GLTF_MIME
            } else {
                NATIVE_HIGH_DURABLE_JSON_MIME
            }
        || object.kind != expected_kind
        || object.size_bytes == 0
        || object.size_bytes > max_bytes
        || object.size_bytes > i64::MAX as u64
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || (require_reachable && object.reachability != "reachable")
        || object.created_at.is_empty()
        || object.created_at.len() > 64
    {
        return Err(native_high_contract(
            "NATIVE_HIGH_DURABLE_CAS_METADATA_INVALID",
            "Native High CAS metadata or binding differs",
        ));
    }
    cas.read_verified_bounded(expected_sha256, max_bytes)
        .map_err(StoreError::from)
}

fn ensure_native_high_cas_object_row(
    transaction: &rusqlite::Transaction<'_>,
    object: &CasObjectRecord,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let stored: Option<(i64, String, String, String)> = transaction
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![object.sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((size, mime, kind, reachability)) = stored else {
        return Err(native_high_contract(
            "NATIVE_HIGH_DURABLE_OBJECT_UNAVAILABLE",
            "Native High CAS object is not registered in SQLite",
        ));
    };
    if size != i64::try_from(object.size_bytes).unwrap_or(i64::MAX)
        || mime != object.mime
        || kind != object.kind
        || !matches!(reachability.as_str(), "temporary" | "reachable")
        || (require_reachable && reachability != "reachable")
    {
        return Err(native_high_contract(
            "NATIVE_HIGH_DURABLE_CAS_METADATA_INVALID",
            "Native High CAS metadata differs from SQLite or is not reachable",
        ));
    }
    Ok(())
}

fn validate_native_high_candidate_binding(
    transaction: &rusqlite::Transaction<'_>,
    record: &NativeHighDurableRecord,
) -> Result<(), StoreError> {
    let candidate: Option<(String, String, Option<String>)> = transaction
        .query_row(
            "SELECT project_id, canonical_sha256, base_version_id FROM candidates WHERE candidate_id = ?1",
            params![record.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;
    let Some((project_id, candidate_state_sha256, base_version_id)) = candidate else {
        return Err(native_high_contract(
            "NATIVE_HIGH_DURABLE_CANDIDATE_UNAVAILABLE",
            "Native High candidate is unavailable",
        ));
    };
    if project_id != record.project_id
        || candidate_state_sha256 != record.candidate_state_sha256
        || base_version_id != record.base_version_id
    {
        return Err(native_high_contract(
            "NATIVE_HIGH_DURABLE_CANDIDATE_BINDING_MISMATCH",
            "Native High record is not bound to the candidate current state",
        ));
    }
    let source: Option<(String, String, String, Option<String>, String, String, String)> =
        transaction
            .query_row(
                "SELECT project_id, candidate_id, candidate_state_sha256, base_version_id, canonical_mesh_id, canonical_mesh_object_sha256, canonical_mesh_sha256 FROM authoring_mesh_durable_records WHERE candidate_id = ?1 AND canonical_mesh_id = ?2",
                params![record.candidate_id, record.source_canonical_mesh_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?)),
            )
            .optional()?;
    let Some((
        source_project_id,
        source_candidate_id,
        source_state_sha256,
        source_base_version_id,
        source_mesh_id,
        source_object_sha256,
        source_mesh_sha256,
    )) = source
    else {
        return Err(native_high_contract(
            "NATIVE_HIGH_DURABLE_SOURCE_UNAVAILABLE",
            "Native High source canonical mesh is not an AuthoringMesh durable record",
        ));
    };
    if source_project_id != record.project_id
        || source_candidate_id != record.candidate_id
        || source_state_sha256 != record.candidate_state_sha256
        || source_base_version_id != record.base_version_id
        || source_mesh_id != record.source_canonical_mesh_id
        || source_object_sha256 != record.source_canonical_mesh_object_sha256
        || source_mesh_sha256 != record.source_canonical_mesh_sha256
    {
        return Err(native_high_contract(
            "NATIVE_HIGH_DURABLE_SOURCE_BINDING_MISMATCH",
            "Native High source canonical mesh differs from AuthoringMesh durable lineage",
        ));
    }
    Ok(())
}

fn read_native_high_durable_record_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    project_id: &str,
    idempotency_key: &str,
) -> Result<Option<NativeHighDurableRecord>, StoreError> {
    transaction
        .query_row(
            "SELECT schema_version, project_id, candidate_id, candidate_state_sha256, base_version_id, source_canonical_mesh_id, source_canonical_mesh_object_sha256, source_canonical_mesh_sha256, detail_graph_object_sha256, detail_graph_canonical_sha256, high_mesh_artifact_object_sha256, high_mesh_artifact_sha256, high_artifact_id, high_artifact_object_sha256, high_artifact_sha256, high_artifact_size_bytes, high_artifact_readback_object_sha256, high_artifact_readback_sha256, link_id, link_object_sha256, request_sha256, input_sha256, idempotency_key, high_worker_build_cohort_sha256, glb_worker_build_cohort_sha256, materialization_status, canonical_sha256, created_at FROM native_high_durable_links WHERE project_id = ?1 AND idempotency_key = ?2",
            params![project_id, idempotency_key],
            |row| {
                let high_artifact_size_bytes: i64 = row.get(15)?;
                Ok(NativeHighDurableRecord {
                    schema_version: row.get(0)?,
                    project_id: row.get(1)?,
                    candidate_id: row.get(2)?,
                    candidate_state_sha256: row.get(3)?,
                    base_version_id: row.get(4)?,
                    source_canonical_mesh_id: row.get(5)?,
                    source_canonical_mesh_object_sha256: row.get(6)?,
                    source_canonical_mesh_sha256: row.get(7)?,
                    detail_graph_object_sha256: row.get(8)?,
                    detail_graph_canonical_sha256: row.get(9)?,
                    high_mesh_artifact_object_sha256: row.get(10)?,
                    high_mesh_artifact_sha256: row.get(11)?,
                    high_artifact_id: row.get(12)?,
                    high_artifact_object_sha256: row.get(13)?,
                    high_artifact_sha256: row.get(14)?,
                    high_artifact_size_bytes: u64::try_from(high_artifact_size_bytes).map_err(|_| rusqlite::Error::FromSqlConversionFailure(15, rusqlite::types::Type::Integer, "negative Native High size".into()))?,
                    high_artifact_readback_object_sha256: row.get(16)?,
                    high_artifact_readback_sha256: row.get(17)?,
                    link_id: row.get(18)?,
                    link_object_sha256: row.get(19)?,
                    request_sha256: row.get(20)?,
                    input_sha256: row.get(21)?,
                    idempotency_key: row.get(22)?,
                    high_worker_build_cohort_sha256: row.get(23)?,
                    glb_worker_build_cohort_sha256: row.get(24)?,
                    materialization_status: row.get(25)?,
                    canonical_sha256: row.get(26)?,
                    created_at: row.get(27)?,
                })
            },
        )
        .optional()
        .map_err(StoreError::from)
}

fn authoring_mesh_v2_contract(code: &str, message: &str) -> StoreError {
    StoreError::Contract {
        code: code.to_owned(),
        message: message.to_owned(),
    }
}

fn validate_authoring_mesh_v2_durable_record(
    record: &AuthoringMeshV2DurableRecord,
) -> Result<(), StoreError> {
    if record.schema_version != AUTHORING_MESH_V2_DURABLE_RECORD_SCHEMA_VERSION
        || !is_opaque_id(&record.project_id)
        || !is_opaque_id(&record.mesh_id)
        || !is_opaque_id(&record.lineage_id)
        || !is_opaque_id(&record.revision_id)
        || record.parent_revision_ids.len() > 8
        || record
            .parent_revision_ids
            .iter()
            .any(|id| !is_opaque_id(id))
        || record
            .parent_revision_ids
            .iter()
            .collect::<BTreeSet<_>>()
            .len()
            != record.parent_revision_ids.len()
        || record
            .parent_revision_ids
            .iter()
            .any(|id| id == &record.revision_id)
        || !is_sha256(&record.revision_object_sha256)
        || !is_sha256(&record.revision_sha256)
        || !is_sha256(&record.request_input_sha256)
        || !is_opaque_id(&record.idempotency_key)
        || record.idempotency_key.len() > 128
        || record
            .operation_id
            .as_deref()
            .is_some_and(|value| !is_opaque_id(value))
        || record
            .operation_lineage_sha256
            .as_deref()
            .is_some_and(|value| !is_sha256(value))
        || !matches!(
            record.operation_kind.as_deref(),
            None | Some("split_edge")
                | Some("face_extrude")
                | Some("move_vertices")
                | Some("open_frame_notch")
                | Some("rear_stock_void_rail_bow")
                | Some("rear_stock_void_boundary_bridge")
        )
        || (record.operation_kind.is_some()
            && (record.operation_id.is_none() || record.operation_lineage_sha256.is_none()))
        || (record.operation_kind.is_none()
            && (record.operation_id.is_some() || record.operation_lineage_sha256.is_some()))
        || record.materialization_status != AUTHORING_MESH_V2_DURABLE_RECORD_STATUS
        || !is_sha256(&record.canonical_sha256)
        || record.created_at.is_empty()
        || record.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "AuthoringMesh@2 durable record metadata is malformed".to_owned(),
        ));
    }
    if record.revision_index == 0 && !record.parent_revision_ids.is_empty() {
        return Err(authoring_mesh_v2_contract(
            "AUTHORING_MESH_V2_GENESIS_PARENT_INVALID",
            "genesis revision cannot have a parent",
        ));
    }
    if record.revision_index > 0 && record.parent_revision_ids.is_empty() {
        return Err(authoring_mesh_v2_contract(
            "AUTHORING_MESH_V2_PARENT_REQUIRED",
            "non-genesis revision must have a parent",
        ));
    }
    Ok(())
}

fn authoring_mesh_v2_durable_record_canonical_sha256(
    record: &AuthoringMeshV2DurableRecord,
) -> Result<String, StoreError> {
    let mut value =
        serde_json::to_value(record).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    value["canonical_sha256"] = Value::String(String::new());
    Ok(canonical_json_hash(&value))
}

fn normalize_authoring_mesh_v2_durable_record(
    record: &AuthoringMeshV2DurableRecord,
) -> Result<AuthoringMeshV2DurableRecord, StoreError> {
    validate_authoring_mesh_v2_durable_record(record)?;
    let expected = authoring_mesh_v2_durable_record_canonical_sha256(record)?;
    if record.canonical_sha256 != expected {
        return Err(authoring_mesh_v2_contract(
            "AUTHORING_MESH_V2_RECORD_CANONICAL_MISMATCH",
            "AuthoringMesh@2 durable record canonical hash is invalid",
        ));
    }
    Ok(record.clone())
}

fn same_authoring_mesh_v2_durable_record(
    left: &AuthoringMeshV2DurableRecord,
    right: &AuthoringMeshV2DurableRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

fn validate_authoring_mesh_v2_revision_object(
    cas: &CasStore,
    object: &CasObjectRecord,
    expected_sha256: &str,
    require_reachable: bool,
) -> Result<Vec<u8>, StoreError> {
    if object.schema_version != "CasObject@1"
        || object.sha256 != expected_sha256
        || !is_sha256(&object.sha256)
        || object.mime != AUTHORING_MESH_V2_DURABLE_OBJECT_MIME
        || object.kind != AUTHORING_MESH_V2_REVISION_OBJECT_KIND
        || object.size_bytes == 0
        || object.size_bytes > AUTHORING_MESH_V2_DURABLE_MAX_BYTES
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || (require_reachable && object.reachability != "reachable")
        || object.created_at.is_empty()
        || object.created_at.len() > 64
    {
        return Err(authoring_mesh_v2_contract(
            "AUTHORING_MESH_V2_CAS_METADATA_INVALID",
            "AuthoringMesh@2 revision CAS metadata or binding differs",
        ));
    }
    cas.read_verified_bounded(expected_sha256, AUTHORING_MESH_V2_DURABLE_MAX_BYTES)
        .map_err(StoreError::from)
}

fn ensure_authoring_mesh_v2_object_row(
    transaction: &rusqlite::Transaction<'_>,
    object: &CasObjectRecord,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let stored: Option<(i64, String, String, String)> = transaction
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![object.sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((size, mime, kind, reachability)) = stored else {
        return Err(authoring_mesh_v2_contract(
            "AUTHORING_MESH_V2_OBJECT_UNAVAILABLE",
            "AuthoringMesh@2 revision CAS object is not registered",
        ));
    };
    if size != i64::try_from(object.size_bytes).unwrap_or(i64::MAX)
        || mime != object.mime
        || kind != object.kind
        || !matches!(reachability.as_str(), "temporary" | "reachable")
        || (require_reachable && reachability != "reachable")
    {
        return Err(authoring_mesh_v2_contract(
            "AUTHORING_MESH_V2_CAS_METADATA_INVALID",
            "AuthoringMesh@2 revision CAS metadata differs from SQLite",
        ));
    }
    Ok(())
}

fn validate_authoring_mesh_v2_revision_payload(
    bytes: &[u8],
    revision: &AuthoringMeshRevision,
    record: &AuthoringMeshV2DurableRecord,
) -> Result<(), StoreError> {
    let revision_value = serde_json::to_value(revision)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    let expected_bytes = canonical_json_bytes(&revision_value)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    if expected_bytes != bytes {
        return Err(authoring_mesh_v2_contract(
            "AUTHORING_MESH_V2_PAYLOAD_BYTES_MISMATCH",
            &format!(
                "AuthoringMesh@2 revision CAS bytes are not canonical typed revision bytes (cas={}, typed={})",
                sha256_hex(bytes),
                sha256_hex(&expected_bytes)
            ),
        ));
    }
    if record.mesh_id != revision.mesh_id.0
        || record.lineage_id != revision.lineage_id.0
        || record.revision_id != revision.revision_id.0
        || record.revision_index != revision.revision_index
        || record.parent_revision_ids
            != revision
                .parent_revision_ids
                .iter()
                .map(|id| id.0.clone())
                .collect::<Vec<_>>()
        || record.revision_sha256 != revision.canonical_sha256
    {
        return Err(authoring_mesh_v2_contract(
            "AUTHORING_MESH_V2_PAYLOAD_BINDING_MISMATCH",
            "AuthoringMesh@2 revision CAS payload differs from the durable row",
        ));
    }
    let operation = revision.operation.as_ref();
    let operation_kind = operation.map(|value| match &value.kind {
        AuthoringMeshTopologyOperationKind::SplitEdge => "split_edge",
        AuthoringMeshTopologyOperationKind::FaceExtrude => "face_extrude",
        AuthoringMeshTopologyOperationKind::MoveVertices => "move_vertices",
        AuthoringMeshTopologyOperationKind::OpenFrameNotch => "open_frame_notch",
        AuthoringMeshTopologyOperationKind::RearStockVoidRailBow => "rear_stock_void_rail_bow",
        AuthoringMeshTopologyOperationKind::RearStockVoidBoundaryBridge => {
            "rear_stock_void_boundary_bridge"
        }
    });
    if record.operation_id.as_deref() != operation.map(|value| value.operation_id.as_str())
        || record.operation_kind.as_deref() != operation_kind
        || record.operation_lineage_sha256.as_deref()
            != operation.map(|value| value.operation_lineage_sha256.as_str())
    {
        return Err(authoring_mesh_v2_contract(
            "AUTHORING_MESH_V2_OPERATION_BINDING_MISMATCH",
            "AuthoringMesh@2 operation metadata differs from the durable row",
        ));
    }
    Ok(())
}

fn validate_authoring_mesh_v2_parent_dag_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    record: &AuthoringMeshV2DurableRecord,
) -> Result<(), StoreError> {
    for parent_id in &record.parent_revision_ids {
        let parent: Option<(String, String, i64)> = transaction
            .query_row(
                "SELECT mesh_id, lineage_id, revision_index FROM authoring_mesh_v2_durable_records WHERE project_id = ?1 AND revision_id = ?2",
                params![record.project_id, parent_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .optional()?;
        let Some((mesh_id, lineage_id, revision_index)) = parent else {
            return Err(authoring_mesh_v2_contract(
                "AUTHORING_MESH_V2_PARENT_UNAVAILABLE",
                "revision parent is not durably materialized",
            ));
        };
        if mesh_id != record.mesh_id
            || lineage_id != record.lineage_id
            || revision_index < 0
            || u64::try_from(revision_index).unwrap_or(u64::MAX) >= record.revision_index
        {
            return Err(authoring_mesh_v2_contract(
                "AUTHORING_MESH_V2_DAG_INVALID",
                "revision parent is not an earlier revision in the same lineage",
            ));
        }
    }
    Ok(())
}

fn validate_authoring_mesh_v2_record_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    record: &AuthoringMeshV2DurableRecord,
    require_reachable: bool,
) -> Result<(), StoreError> {
    let object = transaction
        .query_row(
            "SELECT sha256, size_bytes, mime, kind, reachability, created_at FROM objects WHERE sha256 = ?1",
            params![record.revision_object_sha256],
            |row| {
                let size_bytes: i64 = row.get(1)?;
                Ok(CasObjectRecord {
                    schema_version: "CasObject@1".to_owned(),
                    sha256: row.get(0)?,
                    size_bytes: u64::try_from(size_bytes).map_err(|_| {
                        rusqlite::Error::FromSqlConversionFailure(
                            1,
                            rusqlite::types::Type::Integer,
                            "negative object size".into(),
                        )
                    })?,
                    mime: row.get(2)?,
                    kind: row.get(3)?,
                    reachability: row.get(4)?,
                    created_at: row.get(5)?,
                })
            },
        )
        .optional()?
        .ok_or_else(|| {
            authoring_mesh_v2_contract(
                "AUTHORING_MESH_V2_OBJECT_UNAVAILABLE",
                "AuthoringMesh@2 revision object is unavailable",
            )
        })?;
    let bytes = validate_authoring_mesh_v2_revision_object(
        cas,
        &object,
        &record.revision_object_sha256,
        require_reachable,
    )?;
    let payload: AuthoringMeshRevision = serde_json::from_slice(&bytes)
        .map_err(|error| StoreError::InvalidData(error.to_string()))?;
    validate_authoring_mesh_v2_revision_payload(&bytes, &payload, record)
}

fn read_authoring_mesh_v2_record_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    project_id: &str,
    idempotency_key: &str,
) -> Result<Option<AuthoringMeshV2DurableRecord>, StoreError> {
    transaction
        .query_row(
            "SELECT schema_version, project_id, mesh_id, lineage_id, revision_id, parent_revision_ids_json, revision_index, revision_object_sha256, revision_sha256, operation_id, operation_kind, operation_lineage_sha256, request_input_sha256, idempotency_key, materialization_status, canonical_sha256, created_at FROM authoring_mesh_v2_durable_records WHERE project_id = ?1 AND idempotency_key = ?2",
            params![project_id, idempotency_key],
            |row| {
                let parent_json: String = row.get(5)?;
                let parent_revision_ids = serde_json::from_str(&parent_json).map_err(|error| {
                    rusqlite::Error::FromSqlConversionFailure(
                        5,
                        rusqlite::types::Type::Text,
                        error.into(),
                    )
                })?;
                let revision_index: i64 = row.get(6)?;
                Ok(AuthoringMeshV2DurableRecord {
                    schema_version: row.get(0)?,
                    project_id: row.get(1)?,
                    mesh_id: row.get(2)?,
                    lineage_id: row.get(3)?,
                    revision_id: row.get(4)?,
                    parent_revision_ids,
                    revision_index: u64::try_from(revision_index).map_err(|_| {
                        rusqlite::Error::FromSqlConversionFailure(
                            6,
                            rusqlite::types::Type::Integer,
                            "negative revision index".into(),
                        )
                    })?,
                    revision_object_sha256: row.get(7)?,
                    revision_sha256: row.get(8)?,
                    operation_id: row.get(9)?,
                    operation_kind: row.get(10)?,
                    operation_lineage_sha256: row.get(11)?,
                    request_input_sha256: row.get(12)?,
                    idempotency_key: row.get(13)?,
                    materialization_status: row.get(14)?,
                    canonical_sha256: row.get(15)?,
                    created_at: row.get(16)?,
                })
            },
        )
        .optional()
        .map_err(StoreError::from)
}

fn validate_authoring_mesh_durable_record(
    record: &AuthoringMeshDurableRecord,
) -> Result<(), StoreError> {
    let identifiers = [
        record.project_id.as_str(),
        record.candidate_id.as_str(),
        record.canonical_mesh_id.as_str(),
        record.artifact_id.as_str(),
        record.link_id.as_str(),
        record.authoring_node_id.as_str(),
        record.part_id.as_str(),
        record.idempotency_key.as_str(),
    ];
    let hashes = [
        record.candidate_state_sha256.as_str(),
        record.canonical_mesh_object_sha256.as_str(),
        record.canonical_mesh_sha256.as_str(),
        record.artifact_object_sha256.as_str(),
        record.artifact_sha256.as_str(),
        record.artifact_readback_object_sha256.as_str(),
        record.artifact_readback_sha256.as_str(),
        record.link_object_sha256.as_str(),
        record.source_program_object_sha256.as_str(),
        record.source_program_sha256.as_str(),
        record.source_artifact_object_sha256.as_str(),
        record.source_artifact_sha256.as_str(),
        record.source_artifact_readback_object_sha256.as_str(),
        record.source_artifact_readback_sha256.as_str(),
        record.operator_catalog_sha256.as_str(),
        record.readback_config_sha256.as_str(),
        record.request_input_sha256.as_str(),
    ];
    if record.schema_version != AUTHORING_MESH_DURABLE_RECORD_SCHEMA_VERSION
        || identifiers.iter().any(|value| !is_opaque_id(value))
        || hashes.iter().any(|value| !is_sha256(value))
        || record
            .base_version_id
            .as_deref()
            .is_some_and(|value| !is_opaque_id(value))
        || record.idempotency_key.len() > 128
        || !record
            .idempotency_key
            .as_bytes()
            .first()
            .is_some_and(u8::is_ascii_alphanumeric)
        || record.materialization_status != AUTHORING_MESH_DURABLE_RECORD_STATUS
        || (!record.canonical_sha256.is_empty() && !is_sha256(&record.canonical_sha256))
        || record.created_at.is_empty()
        || record.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "AuthoringMesh durable record metadata is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn authoring_mesh_durable_record_canonical_sha256(
    record: &AuthoringMeshDurableRecord,
) -> Result<String, StoreError> {
    let mut value =
        serde_json::to_value(record).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    value["canonical_sha256"] = Value::String(String::new());
    Ok(canonical_json_hash(&value))
}

fn normalize_authoring_mesh_durable_record(
    record: &AuthoringMeshDurableRecord,
) -> Result<AuthoringMeshDurableRecord, StoreError> {
    validate_authoring_mesh_durable_record(record)?;
    let expected = authoring_mesh_durable_record_canonical_sha256(record)?;
    if !record.canonical_sha256.is_empty() && record.canonical_sha256 != expected {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_DURABLE_RECORD_CANONICAL_MISMATCH",
            "AuthoringMesh durable record canonical hash is invalid",
        ));
    }
    let mut normalized = record.clone();
    normalized.canonical_sha256 = expected;
    Ok(normalized)
}

fn same_authoring_mesh_durable_record(
    left: &AuthoringMeshDurableRecord,
    right: &AuthoringMeshDurableRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

