fn authoring_mesh_durable_object_record_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    sha256: &str,
) -> Result<CasObjectRecord, StoreError> {
    authoring_mesh_object_record_in_transaction(transaction, sha256)
}

fn validate_authoring_mesh_durable_json_object(
    cas: &CasStore,
    object: &CasObjectRecord,
    expected_sha256: &str,
    expected_kind: &str,
    require_reachable: bool,
) -> Result<Vec<u8>, StoreError> {
    if object.schema_version != "CasObject@1"
        || object.sha256 != expected_sha256
        || !is_sha256(&object.sha256)
        || object.mime != AUTHORING_MESH_DURABLE_OBJECT_MIME
        || object.kind != expected_kind
        || object.size_bytes == 0
        || object.size_bytes > AUTHORING_MESH_DURABLE_MAX_BYTES
        || !matches!(object.reachability.as_str(), "temporary" | "reachable")
        || (require_reachable && object.reachability != "reachable")
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_DURABLE_CAS_METADATA_INVALID",
            "AuthoringMesh durable CAS metadata or binding differs",
        ));
    }
    cas.read_verified_bounded(expected_sha256, AUTHORING_MESH_DURABLE_MAX_BYTES)
        .map_err(StoreError::from)
}

fn ensure_authoring_mesh_durable_json_object_row(
    transaction: &rusqlite::Transaction<'_>,
    object: &CasObjectRecord,
    require_reachable: bool,
) -> Result<(), StoreError> {
    ensure_authoring_mesh_cas_object_row(transaction, object, require_reachable)
}

fn canonical_hash_from_payload(value: &Value, context: &str) -> Result<String, StoreError> {
    let supplied = value
        .get("canonical_sha256")
        .and_then(Value::as_str)
        .filter(|value| is_sha256(value))
        .ok_or_else(|| {
            authoring_mesh_contract("AUTHORING_MESH_DURABLE_PAYLOAD_INVALID", context)
        })?;
    let mut normalized = value.clone();
    normalized["canonical_sha256"] = Value::String(String::new());
    if canonical_json_hash(&normalized) != supplied {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_DURABLE_PAYLOAD_CANONICAL_MISMATCH",
            context,
        ));
    }
    Ok(supplied.to_owned())
}

fn durable_json(bytes: &[u8], context: &str) -> Result<Value, StoreError> {
    let value: Value = serde_json::from_slice(bytes)
        .map_err(|_| authoring_mesh_contract("AUTHORING_MESH_DURABLE_PAYLOAD_INVALID", context))?;
    if !value.is_object() {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_DURABLE_PAYLOAD_INVALID",
            context,
        ));
    }
    Ok(value)
}

fn durable_text<'a>(value: &'a Value, key: &str) -> Option<&'a str> {
    value.get(key).and_then(Value::as_str)
}

fn validate_authoring_mesh_durable_canonical_payload(
    bytes: &[u8],
    record: &AuthoringMeshDurableRecord,
) -> Result<(), StoreError> {
    let value = durable_json(bytes, "AuthoringMeshCanonical@1 is not closed JSON")?;
    let canonical = canonical_hash_from_payload(&value, "AuthoringMeshCanonical@1 hash differs")?;
    if durable_text(&value, "schema_version") != Some("AuthoringMeshCanonical@1")
        || durable_text(&value, "canonical_mesh_id") != Some(record.canonical_mesh_id.as_str())
        || durable_text(&value, "project_id") != Some(record.project_id.as_str())
        || durable_text(&value, "candidate_id") != Some(record.candidate_id.as_str())
        || durable_text(&value, "candidate_state_sha256")
            != Some(record.candidate_state_sha256.as_str())
        || value.get("base_version_id")
            != Some(
                &record
                    .base_version_id
                    .clone()
                    .map(Value::String)
                    .unwrap_or(Value::Null),
            )
        || durable_text(&value, "source_program_object_sha256")
            != Some(record.source_program_object_sha256.as_str())
        || durable_text(&value, "source_program_sha256")
            != Some(record.source_program_sha256.as_str())
        || durable_text(&value, "source_artifact_object_sha256")
            != Some(record.source_artifact_object_sha256.as_str())
        || durable_text(&value, "source_artifact_sha256")
            != Some(record.source_artifact_sha256.as_str())
        || durable_text(&value, "source_artifact_readback_object_sha256")
            != Some(record.source_artifact_readback_object_sha256.as_str())
        || durable_text(&value, "source_artifact_readback_sha256")
            != Some(record.source_artifact_readback_sha256.as_str())
        || canonical != record.canonical_mesh_sha256
        || value
            .get("runtime_write_performed")
            .and_then(Value::as_bool)
            != Some(true)
        || value.get("stage_advanced").and_then(Value::as_bool) != Some(false)
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_DURABLE_CANONICAL_BINDING_MISMATCH",
            "AuthoringMeshCanonical@1 differs from the durable record",
        ));
    }
    Ok(())
}

