fn ensure_authoring_mesh_durable_lineage_in_transaction(
    transaction: &rusqlite::Transaction<'_>,
    cas: &CasStore,
    record: &AuthoringMeshDurableRecord,
    require_reachable: bool,
) -> Result<Vec<String>, StoreError> {
    let candidate: Option<(String, Option<String>, String, Option<String>)> = transaction
        .query_row(
            "SELECT project_id, prepared_object_sha256, canonical_sha256, base_version_id FROM candidates WHERE candidate_id = ?1",
            params![record.candidate_id],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((project_id, prepared_object_sha256, candidate_sha256, base_version_id)) = candidate
    else {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_DURABLE_CANDIDATE_NOT_FOUND",
            "candidate is unavailable for durable AuthoringMesh",
        ));
    };
    if project_id != record.project_id
        || prepared_object_sha256.as_deref() != Some(record.source_artifact_object_sha256.as_str())
        || candidate_sha256 != record.candidate_state_sha256
        || base_version_id != record.base_version_id
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_DURABLE_CANDIDATE_BINDING_MISMATCH",
            "candidate state, base version or source artifact differs",
        ));
    }
    let evidence: Option<(String, String, String, String, String, String)> = transaction
        .query_row(
            "SELECT project_id, geometry_program_sha256, geometry_program_object_sha256, operator_catalog_sha256, readback_config_sha256, artifact_readback_object_sha256 FROM geometry_candidate_evidence WHERE candidate_id = ?1 AND artifact_object_sha256 = ?2",
            params![record.candidate_id, record.source_artifact_object_sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?)),
        )
        .optional()?;
    let Some((
        evidence_project_id,
        program_sha256,
        program_object_sha256,
        catalog_sha256,
        readback_config_sha256,
        readback_object_sha256,
    )) = evidence
    else {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_DURABLE_EVIDENCE_NOT_FOUND",
            "geometry evidence is unavailable for durable AuthoringMesh",
        ));
    };
    if evidence_project_id != record.project_id
        || program_sha256 != record.source_program_sha256
        || program_object_sha256 != record.source_program_object_sha256
        || catalog_sha256 != record.operator_catalog_sha256
        || readback_config_sha256 != record.readback_config_sha256
        || readback_object_sha256 != record.source_artifact_readback_object_sha256
        || record.source_artifact_sha256 != record.source_artifact_object_sha256
        || record.artifact_readback_object_sha256 != record.source_artifact_readback_object_sha256
        || record.artifact_readback_sha256 != record.source_artifact_readback_sha256
    {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_DURABLE_EVIDENCE_BINDING_MISMATCH",
            "program, artifact or readback lineage differs",
        ));
    }
    let roots = vec![
        record.source_program_object_sha256.clone(),
        record.source_artifact_object_sha256.clone(),
        record.source_artifact_readback_object_sha256.clone(),
    ];
    for sha256 in &roots {
        let object = authoring_mesh_object_record_in_transaction(transaction, sha256)?;
        if require_reachable && object.reachability != "reachable" {
            return Err(authoring_mesh_contract(
                "AUTHORING_MESH_DURABLE_LINEAGE_UNREACHABLE",
                "durable AuthoringMesh source lineage is not reachable",
            ));
        }
        cas.read_verified_bounded(sha256, AUTHORING_MESH_DURABLE_GLTF_MAX_BYTES)
            .map_err(StoreError::from)?;
    }
    Ok(roots)
}

fn validate_authoring_mesh_projection_index(
    link: &AuthoringMeshProjectionIndexRecord,
) -> Result<(), StoreError> {
    // `artifact_id` is the projection payload's source-lineage identity while
    // `artifact_sha256` is the candidate's current artifact object hash. Do
    // not equate these fields: object/canonical hashes must not be forced into
    // a self-referential public durable-link shape.
    if link.schema_version != AUTHORING_MESH_PROJECTION_INDEX_SCHEMA_VERSION
        || !is_opaque_id(&link.mesh_id)
        || !is_opaque_id(&link.project_id)
        || !is_opaque_id(&link.candidate_id)
        || !is_sha256(&link.candidate_state_sha256)
        || !is_sha256(&link.artifact_id)
        || !is_sha256(&link.artifact_sha256)
        || !is_sha256(&link.artifact_readback_sha256)
        || !is_sha256(&link.program_sha256)
        || !is_sha256(&link.operator_catalog_sha256)
        || !is_sha256(&link.readback_config_sha256)
        || !is_opaque_id(&link.authoring_node_id)
        || !is_opaque_id(&link.part_id)
        || !is_sha256(&link.mesh_object_sha256)
        || !is_sha256(&link.mesh_sha256)
        || link.materialization_status != AUTHORING_MESH_DURABLE_STATUS
        || (!link.canonical_sha256.is_empty() && !is_sha256(&link.canonical_sha256))
        || link.created_at.is_empty()
        || link.created_at.len() > 64
    {
        return Err(StoreError::InvalidData(
            "AuthoringMesh durable link metadata is malformed".to_owned(),
        ));
    }
    Ok(())
}

fn authoring_mesh_projection_index_canonical_sha256(
    link: &AuthoringMeshProjectionIndexRecord,
) -> Result<String, StoreError> {
    let mut value =
        serde_json::to_value(link).map_err(|error| StoreError::InvalidData(error.to_string()))?;
    value["canonical_sha256"] = Value::String(String::new());
    Ok(canonical_json_hash(&value))
}

fn normalize_authoring_mesh_projection_index(
    link: &AuthoringMeshProjectionIndexRecord,
) -> Result<AuthoringMeshProjectionIndexRecord, StoreError> {
    validate_authoring_mesh_projection_index(link)?;
    let expected = authoring_mesh_projection_index_canonical_sha256(link)?;
    if !link.canonical_sha256.is_empty() && link.canonical_sha256 != expected {
        return Err(authoring_mesh_contract(
            "AUTHORING_MESH_PROJECTION_INDEX_CANONICAL_MISMATCH",
            "AuthoringMesh durable link canonical hash is invalid",
        ));
    }
    let mut normalized = link.clone();
    normalized.canonical_sha256 = expected;
    Ok(normalized)
}

fn same_authoring_mesh_projection_index(
    left: &AuthoringMeshProjectionIndexRecord,
    right: &AuthoringMeshProjectionIndexRecord,
) -> bool {
    let mut left = left.clone();
    let mut right = right.clone();
    left.created_at.clear();
    right.created_at.clear();
    left.canonical_sha256.clear();
    right.canonical_sha256.clear();
    left == right
}

