        || !is_opaque_id(&request.prepared_object_id)
        || !is_sha256(&request.prepared_object_sha256)
        || !is_opaque_id(&request.quality_report_id)
        || !is_opaque_id(&request.approval_receipt_id)
        || request.approval_summary.trim().is_empty()
