fn ensure_fictional_energy_vfx_animated_socket_trails_object(
    connection: &Connection,
    sha256: &str,
    expected_mime: &str,
    expected_kind: &str,
    max_bytes: i64,
) -> Result<(), StoreError> {
    ensure_fictional_energy_vfx_animated_socket_particles_object(
        connection,
        sha256,
        expected_mime,
        expected_kind,
        max_bytes,
    )
    .map_err(|_| StoreError::Contract {
        code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_CAS_OBJECT_INVALID".to_owned(),
        message: "animated socket trails CAS metadata is missing or differs".to_owned(),
    })
}

fn ensure_fictional_energy_vfx_animated_socket_trails_source_artifact(
    connection: &Connection,
    sha256: &str,
) -> Result<(), StoreError> {
    let metadata: Option<(i64, String, String, String)> = connection
        .query_row(
            "SELECT size_bytes, mime, kind, reachability FROM objects WHERE sha256 = ?1",
            params![sha256],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    if !metadata.is_some_and(|(size, mime, kind, reachability)| {
        size > 0
            && size <= 64 * 1024 * 1024
            && mime == "model/gltf-binary"
            && matches!(
                kind.as_str(),
                "geometry-glb" | "appearance-glb" | "appearance-v2-glb"
            )
            && matches!(reachability.as_str(), "temporary" | "reachable")
    }) {
        return Err(StoreError::Contract {
            code: "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_SOURCE_INVALID".to_owned(),
            message: "animated socket trails source artifact metadata is invalid".to_owned(),
        });
    }
    Ok(())
}

fn ensure_fictional_energy_vfx_animated_socket_trails_sequence_objects(
    connection: &Connection,
    sequence: &FictionalEnergyVfxAnimatedSocketTrailsSequence,
) -> Result<(), StoreError> {
    let json_limit = i64::try_from(MAX_GAME_ASSET_DELIVERY_JSON_BYTES).unwrap_or(i64::MAX);
    for (hash, mime, kind, max_bytes) in [
        (
            sequence.delivery_manifest_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            "game-asset-delivery-manifest",
            json_limit,
        ),
        (
            sequence.projection_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_KIND,
            i64::try_from(MAX_GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_BYTES)
                .unwrap_or(i64::MAX),
        ),
        (
            sequence.animated_artifact_sha256.as_str(),
            "model/gltf-binary",
            "mechanical-animation-glb",
            64 * 1024 * 1024,
        ),
        (
            sequence.animated_socket_anchor_set_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            GAME_WEAPON_ANCHOR_SET_KIND,
            json_limit,
        ),
        (
            sequence.animation_clip_object_sha256.as_str(),
            MECHANICAL_ANIMATION_CLIP_MIME,
            MECHANICAL_ANIMATION_CLIP_KIND,
            i64::try_from(MAX_MECHANICAL_ANIMATION_CLIP_BYTES).unwrap_or(i64::MAX),
        ),
        (
            sequence.animation_receipt_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            "mechanical-animation-glb-receipt",
            json_limit,
        ),
        (
            sequence.vfx_profile_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            FICTIONAL_ENERGY_VFX_PROFILE_KIND,
            json_limit,
        ),
        (
            sequence.camera_object_sha256.as_str(),
            GAME_ASSET_DELIVERY_JSON_MIME,
            FICTIONAL_ENERGY_VFX_CAMERA_KIND,
            json_limit,
        ),
    ] {
        ensure_fictional_energy_vfx_animated_socket_trails_object(
            connection, hash, mime, kind, max_bytes,
        )?;
    }
    ensure_fictional_energy_vfx_animated_socket_trails_source_artifact(
        connection,
        &sequence.source_artifact_sha256,
    )?;
    for frame in &sequence.frames {
        for (hash, mime, kind, max_bytes) in [
            (
                frame.render_set_object_sha256.as_str(),
                GAME_ASSET_DELIVERY_JSON_MIME,
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_RENDER_SET_KIND,
                json_limit,
            ),
            (
                frame.receipt_object_sha256.as_str(),
                GAME_ASSET_DELIVERY_JSON_MIME,
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_FRAME_RECEIPT_KIND,
                json_limit,
            ),
            (
                frame.trail_color_object_sha256.as_str(),
                "image/png",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_COLOR_KIND,
                MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES,
            ),
            (
                frame.trail_id_object_sha256.as_str(),
                "image/png",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_ID_KIND,
                MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES,
            ),
            (
                frame.trail_depth_object_sha256.as_str(),
                "image/png",
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_TRAILS_DEPTH_KIND,
                MAX_FICTIONAL_ENERGY_VFX_PNG_BYTES,
            ),
        ] {
            ensure_fictional_energy_vfx_animated_socket_trails_object(
                connection, hash, mime, kind, max_bytes,
            )?;
        }
    }
    Ok(())
}

