    fn test_root(label: &str) -> PathBuf {
        let root =
            std::env::temp_dir().join(format!("forgecad-store-test-{label}-{}", Uuid::new_v4()));
        fs::create_dir_all(&root).expect("test root");
        root
    }

    fn project(id: &str) -> ProjectRecord {
        ProjectRecord {
            schema_version: "Project@1".to_owned(),
            project_id: id.to_owned(),
            name: "Test project".to_owned(),
            policy: serde_json::json!({"scope":"test"}),
            created_at: "1".to_owned(),
            updated_at: "1".to_owned(),
            active_snapshot_revision: 0,
            head_snapshot_id: None,
            canonical_sha256: "a".repeat(64),
        }
    }

    fn authoring_mesh_projection_payload(link: &AuthoringMeshProjectionIndexRecord) -> Vec<u8> {
        let mut lineage = serde_json::json!({
            "project_id": link.project_id,
            "candidate_id": link.candidate_id,
            "artifact_id": link.artifact_id,
            "artifact_readback_sha256": link.artifact_readback_sha256,
            "program_sha256": link.program_sha256,
            "operator_catalog_sha256": link.operator_catalog_sha256,
            "readback_config_sha256": link.readback_config_sha256,
            "authoring_node_id": link.authoring_node_id,
            "part_id": link.part_id,
            "lineage_status": "candidate-program-artifact-readback-bound@1",
            "lineage_sha256": "",
        });
        lineage["lineage_sha256"] = Value::String(canonical_json_hash(&lineage));
        let mut payload = serde_json::json!({
            "schema_version": "AuthoringMesh@1",
            "mesh_id": link.mesh_id,
            "mesh_sha256": link.mesh_sha256,
            "scope": "single-authoring-mesh",
            "representation": "half-edge-authoring@1",
            "projection_kind": "runtime-derived-read-only-projection@1",
            "lineage": lineage,
            "mesh_identity_derivation": "runtime-derived-from-candidate-program-artifact-readback@1",
            "mesh_identity_sha256": "f".repeat(64),
            "identity_policy": "runtime-derived-original-evaluated-non-bijective@1",
            "original_identity": {},
            "evaluated_identity": {},
            "cross_version_stable": false,
            "counts": {},
            "vertices": [],
            "edges": [],
            "half_edges": [],
            "corners": [],
            "faces": [],
            "loops": [],
            "rings": [],
            "topology_policy": "bounded-half-edge-manifold-with-boundary@1",
            "topology": {},
            "authoring_mesh_policy_sha256": AUTHORING_MESH_DURABLE_POLICY_SHA256,
            "max_response_bytes": AUTHORING_MESH_DURABLE_MAX_BYTES,
            "runtime_write_performed": false,
            "persistent_user_data_touched": false,
            "quality_status": "structural_only",
            "canonical_sha256": "",
        });
        payload["canonical_sha256"] = Value::String({
            let mut canonical = payload.clone();
            canonical["canonical_sha256"] = Value::String(String::new());
            canonical_json_hash(&canonical)
        });
        canonical_json_bytes(&payload).expect("canonical authoring mesh projection payload")
    }

