    #[test]
    fn authoring_mesh_projection_index_is_atomic_replayed_conflicted_and_reachable() {
        let store = Store::memory().expect("store");
        let (link, object, source_hashes) = authoring_mesh_projection_fixture(&store);
        assert_eq!(table_count(&store, "authoring_mesh_projection_indexes"), 0);

        let mut public_named = link.clone();
        public_named.schema_version = "AuthoringMeshLink@1".to_owned();
        let public_error = store
            .record_authoring_mesh_projection_index(&public_named, &object.record)
            .expect_err("public link schema must not be accepted by the Store index");
        assert!(matches!(public_error, StoreError::InvalidData(_)));
        assert_eq!(table_count(&store, "authoring_mesh_projection_indexes"), 0);

        let (stored, replayed) = store
            .record_authoring_mesh_projection_index_with_replay(&link, &object.record)
            .expect("projection index");
        assert!(!replayed);
        assert_eq!(stored, link);
        assert_eq!(
            stored.schema_version,
            AUTHORING_MESH_PROJECTION_INDEX_SCHEMA_VERSION
        );
        assert_eq!(table_count(&store, "authoring_mesh_projection_indexes"), 1);
        for hash in source_hashes
            .iter()
            .chain(std::iter::once(&stored.mesh_object_sha256))
        {
            assert_eq!(
                store
                    .get_object(hash)
                    .expect("CAS row")
                    .expect("CAS object")
                    .reachability,
                "reachable",
                "linked CAS root must be reachable: {hash}"
            );
        }

        let (replayed_record, replayed) = store
            .record_authoring_mesh_projection_index_with_replay(&link, &object.record)
            .expect("same-key replay");
        assert!(replayed);
        assert_eq!(replayed_record, stored);
        assert_eq!(table_count(&store, "authoring_mesh_projection_indexes"), 1);

        let mut conflict = link.clone();
        conflict.authoring_node_id = "node-authoring-conflict".to_owned();
        conflict.canonical_sha256.clear();
        let conflict_payload = authoring_mesh_projection_payload(&conflict);
        let conflict_object = store
            .put_object(
                &conflict_payload,
                None,
                AUTHORING_MESH_DURABLE_OBJECT_MIME,
                AUTHORING_MESH_PROJECTION_OBJECT_KIND,
                "1",
            )
            .expect("conflict projection object");
        conflict.mesh_object_sha256 = conflict_object.record.sha256.clone();
        conflict.canonical_sha256 = authoring_mesh_projection_index_canonical_sha256(&conflict)
            .expect("conflict canonical hash");
        let conflict_error = store
            .record_authoring_mesh_projection_index(&conflict, &conflict_object.record)
            .expect_err("same candidate and mesh key must conflict");
        assert!(matches!(
            conflict_error,
            StoreError::Contract { code, .. }
                if code == "AUTHORING_MESH_PROJECTION_INDEX_CONFLICT"
        ));
        assert_eq!(table_count(&store, "authoring_mesh_projection_indexes"), 1);
        assert_eq!(
            store
                .get_object(&conflict_object.record.sha256)
                .expect("conflict CAS row")
                .expect("conflict CAS object")
                .reachability,
            "temporary",
            "failed conflict must not make the new CAS object reachable"
        );
    }

    #[test]
    fn authoring_mesh_projection_index_get_survives_restart_and_rejects_cas_tamper() {
        let root = test_root("authoring-mesh-projection-index-restart");
        let database = root.join("runtime.sqlite3");
        let (link, projection_path) = {
            let store = Store::open(&database).expect("store");
            let (link, object, _) = authoring_mesh_projection_fixture(&store);
            let recorded = store
                .record_authoring_mesh_projection_index(&link, &object.record)
                .expect("projection index");
            assert_eq!(recorded, link);
            (recorded, object.path)
        };

        let store = Store::open(&database).expect("reopened store");
        assert_eq!(
            store
                .get_authoring_mesh_projection_index(&link.candidate_id, &link.mesh_id)
                .expect("restart get"),
            Some(link.clone())
        );

        fs::write(&projection_path, b"{\"tampered\":true}").expect("tamper projection CAS");
        let error = store
            .get_authoring_mesh_projection_index(&link.candidate_id, &link.mesh_id)
            .expect_err("tampered CAS must fail closed");
        assert!(matches!(
            error,
            StoreError::Cas(CasError::HashMismatch { .. })
        ));
        drop(store);
        fs::remove_dir_all(root).expect("cleanup");
    }

    fn authoring_objects(
        store: &Store,
        suffix: &str,
    ) -> (CasObject, CasObject, CasObject, CasObject) {
        let artifact = store
            .put_object(
                format!("authoring-artifact-{suffix}").as_bytes(),
                None,
                "model/gltf-binary",
                AUTHORING_MESH_EDIT_GEOMETRY_ARTIFACT_KIND,
                "1",
            )
            .expect("authoring artifact");
        let program = store
            .put_object(
                format!("{{\"program\":\"{suffix}\"}}").as_bytes(),
                None,
                "application/json",
                AUTHORING_MESH_EDIT_GEOMETRY_PROGRAM_KIND,
                "1",
            )
            .expect("authoring program");
        let readback = store
            .put_object(
                format!("{{\"readback\":\"{suffix}\"}}").as_bytes(),
                None,
                "application/json",
                AUTHORING_MESH_EDIT_ARTIFACT_READBACK_KIND,
                "1",
            )
            .expect("authoring readback");
        let quality = store
            .put_object(
                format!("{{\"quality\":\"{suffix}\"}}").as_bytes(),
                None,
                "application/json",
                AUTHORING_MESH_EDIT_QUALITY_KIND,
                "1",
            )
            .expect("authoring quality");
        (artifact, program, readback, quality)
    }

