    #[test]
    fn fictional_energy_vfx_animated_socket_attachment_v3_receipt_projection_is_canonical_and_reachable(
    ) {
        let (attachment, receipt_bytes) =
            fictional_energy_vfx_animated_socket_attachment_v3_test_fixture();
        validate_fictional_energy_vfx_animated_socket_attachment_v3(&attachment)
            .expect("Attachment@3 record canonical projection");
        validate_fictional_energy_vfx_animated_socket_attachment_v3_receipt_bytes(
            &receipt_bytes,
            &attachment,
        )
        .expect("Attachment@3 receipt canonical projection");

        let mut tampered: Value = serde_json::from_slice(&receipt_bytes).expect("receipt JSON");
        tampered["receipt_canonical_sha256"] = Value::String("f".repeat(64));
        let tampered_bytes = canonical_json_bytes(&tampered).expect("tampered receipt JSON");
        assert!(matches!(
            validate_fictional_energy_vfx_animated_socket_attachment_v3_receipt_bytes(
                &tampered_bytes,
                &attachment,
            ),
            Err(StoreError::Contract { code, .. })
                if code == "FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_BINDING_MISMATCH"
        ));

        let store = Store::memory().expect("store");
        let receipt = store
            .put_object(
                &receipt_bytes,
                None,
                GAME_ASSET_DELIVERY_JSON_MIME,
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_KIND,
                "1",
            )
            .expect("Attachment@3 receipt CAS");
        assert_eq!(
            receipt.record.sha256,
            attachment.attachment_receipt_object_sha256
        );
        assert!(store
            .get_object(&attachment.attachment_key_sha256)
            .expect("Attachment@3 parent key lookup")
            .is_none());
        let mut connection = store.lock_connection().expect("connection");
        let transaction = connection.transaction().expect("transaction");
        mark_reachable_in_transaction(&transaction, &[receipt.record.sha256.clone()])
            .expect("receipt reachability");
        transaction.commit().expect("reachability commit");
        drop(connection);
        assert_eq!(
            store
                .get_object(&receipt.record.sha256)
                .expect("receipt metadata")
                .expect("receipt")
                .reachability,
            "reachable"
        );
    }

    #[test]
    fn fictional_energy_vfx_animated_socket_attachment_v3_requires_exact_fifteen_preroll_frames_and_retarget_fails_closed(
    ) {
        let (attachment, receipt_bytes) =
            fictional_energy_vfx_animated_socket_attachment_v3_test_fixture();
        let store = Store::memory().expect("store");
        let receipt = store
            .put_object(
                &receipt_bytes,
                None,
                GAME_ASSET_DELIVERY_JSON_MIME,
                FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_KIND,
                "1",
            )
            .expect("Attachment@3 receipt CAS");

        let mut bad_preroll = attachment.clone();
        bad_preroll.frames[0].projection_frame_index = 0;
        bad_preroll.frames[0].canonical_sha256 = {
            let mut canonical = bad_preroll.frames[0].clone();
            canonical.canonical_sha256.clear();
            canonical_json_hash(&serde_json::to_value(canonical).expect("frame canonical"))
        };
        bad_preroll.canonical_sha256 = {
            let mut canonical = bad_preroll.clone();
            canonical.attachment_receipt_object_sha256.clear();
            canonical.canonical_sha256.clear();
            canonical_json_hash(&serde_json::to_value(canonical).expect("parent canonical"))
        };
        assert!(store
            .record_fictional_energy_vfx_animated_socket_attachment_v3_link(
                &bad_preroll,
                &receipt.record,
            )
            .is_err());
        assert_eq!(
            table_count(
                &store,
                "fictional_energy_vfx_animated_socket_attachment_v3_links"
            ),
            0
        );

        let mut bad_count = attachment.clone();
        bad_count.frames.pop();
        assert!(validate_fictional_energy_vfx_animated_socket_attachment_v3(&bad_count).is_err());

        let mut retarget = attachment.clone();
        retarget.trail_sequence_key_sha256 = "e".repeat(64);
        retarget.canonical_sha256 = {
            let mut canonical = retarget.clone();
            canonical.attachment_receipt_object_sha256.clear();
            canonical.canonical_sha256.clear();
            canonical_json_hash(&serde_json::to_value(canonical).expect("retarget canonical"))
        };
        assert!(store
            .record_fictional_energy_vfx_animated_socket_attachment_v3_link(
                &retarget,
                &receipt.record,
            )
            .is_err());
        assert_eq!(
            table_count(
                &store,
                "fictional_energy_vfx_animated_socket_attachment_v3_links"
            ),
            0
        );
    }

    #[test]
    fn fictional_energy_vfx_animated_socket_attachment_v3_idempotence_conflict_and_closed_allowlist(
    ) {
        let (original, _) = fictional_energy_vfx_animated_socket_attachment_v3_test_fixture();
        let mut replay = original.clone();
        replay.created_at = "attachment-v3-replayed".to_owned();
        for frame in &mut replay.frames {
            frame.created_at = "attachment-v3-frame-replayed".to_owned();
        }
        assert!(same_fictional_energy_vfx_animated_socket_attachment_v3(
            &original, &replay
        ));

        let mut conflict = original.clone();
        conflict.appearance_artifact_sha256 = "a".repeat(64);
        assert!(!same_fictional_energy_vfx_animated_socket_attachment_v3(
            &original, &conflict
        ));

        assert!(temporary_reserved_object_metadata_is_allowed(
            GAME_ASSET_DELIVERY_JSON_MIME,
            FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_KIND,
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            "image/png",
            FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V3_RECEIPT_KIND,
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            GAME_ASSET_DELIVERY_JSON_MIME,
            "fictional-energy-vfx-animated-socket-attachment-v3-unknown",
            1,
        ));

        let store = Store::memory().expect("store");
        let connection = store.lock_connection().expect("connection");
        let parent_columns: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('fictional_energy_vfx_animated_socket_attachment_v3_links')",
                [],
                |row| row.get(0),
            )
            .expect("Attachment@3 parent schema");
        let frame_columns: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('fictional_energy_vfx_animated_socket_attachment_v3_frames')",
                [],
                |row| row.get(0),
            )
            .expect("Attachment@3 frame schema");
        assert_eq!(parent_columns, 70);
        assert_eq!(frame_columns, 31);
        assert!(attachment_v3_parent_texts(
            &connection,
            "game_weapon_animated_glb_socket_transform_projection_v2_links",
            "projection_key_sha256",
            &original.projection_key_sha256,
            &["projection_key_sha256"],
        )
        .expect("Projection@2 parent lookup column")
        .is_none());
        assert!(attachment_v3_parent_texts(
            &connection,
            "fictional_energy_vfx_animated_socket_particles_v2_projection_sequence_links",
            "sequence_key_sha256",
            &original.particle_sequence_key_sha256,
            &["sequence_key_sha256"],
        )
        .expect("Particles@2 parent lookup column")
        .is_none());
    }

