    fn transform_projection_hash(seed: u64) -> String {
        format!("{seed:064x}")
    }

    fn transform_projection_frame_canonical(
        frame: &GameWeaponAnimatedGlbSocketTransformProjectionFrame,
    ) -> String {
        let mut canonical = frame.clone();
        canonical.canonical_sha256.clear();
        canonical_json_hash(&serde_json::to_value(canonical).expect("projection frame canonical"))
    }

    fn transform_projection_canonical(
        projection: &GameWeaponAnimatedGlbSocketTransformProjection,
    ) -> String {
        let mut canonical = projection.clone();
        canonical.canonical_sha256.clear();
        canonical_json_hash(&serde_json::to_value(canonical).expect("projection canonical"))
    }

