        head_candidate.quality_report_id = Some("quality-geometry-head".to_owned());
        head_candidate.quality_hard_gate_passed = true;
        store
            .insert_candidate(&head_candidate)
            .expect("head candidate");
        store
            .insert_version(&DesignAssetVersionRecord {
                schema_version: "DesignAssetVersion@1".to_owned(),
                version_id: "version-geometry-head".to_owned(),
                project_id: project_id.to_owned(),
                parent_version_id: None,
                candidate_id: head_candidate.candidate_id.clone(),
                manifest_hash: "1".repeat(64),
                canonical_sha256: "2".repeat(64),
                created_at: "1".to_owned(),
            })
            .expect("head version");
        set_current_head(
            &store,
            project_id,
            "version-geometry-head",
            &head_candidate.candidate_id,
        );

        let (head_artifact, head_program, head_readback, head_quality) =
            geometry_prepare_objects(&store, "stale");
        let stale_request_sha256 = "5".repeat(64);
