    #[test]
    fn cas_reservation_keeps_shared_temporary_content_until_last_release() {
        let store = Store::memory().expect("store");
        let first_reservation = store.begin_cas_reservation();
        let second_reservation = store.begin_cas_reservation();
        let first = store
            .put_object_reserved(
                &first_reservation,
                b"shared-geometry-prepare-content",
                None,
                "application/json",
                AUTHORING_MESH_EDIT_QUALITY_KIND,
                "1",
            )
            .expect("first reserved object");
        let second = store
            .put_object_reserved(
                &second_reservation,
                b"shared-geometry-prepare-content",
                None,
                "application/json",
                AUTHORING_MESH_EDIT_QUALITY_KIND,
                "2",
            )
            .expect("second reserved object");
        assert!(first.created_new);
        assert!(!second.created_new);

        assert!(!store
            .release_cas_reservation_object(&first_reservation, &first, true)
            .expect("first release"));
        assert!(store
            .get_object(&first.record.sha256)
            .expect("shared object metadata")
            .is_some());
        assert!(store
            .release_cas_reservation_object(&second_reservation, &second, true)
            .expect("last release"));
        assert!(store
            .get_object(&first.record.sha256)
            .expect("removed shared object metadata")
            .is_none());
        assert!(!first.path.exists());
    }

