    #[test]
    fn fictional_energy_vfx_trails_bloom_store_roundtrips_and_is_idempotent() {
        let (store, link, owned_hashes) = trails_bloom_store_fixture();
        let recorded = store
            .record_fictional_energy_vfx_trails_bloom_frame_link(&link)
            .expect("record trails bloom link");
        assert_eq!(recorded, link);
        assert_eq!(
            store
                .get_fictional_energy_vfx_trails_bloom_frame_link(&link.trail_bloom_key_sha256)
                .expect("get trails bloom link"),
            Some(link.clone())
        );
        let mut replay = link.clone();
        replay.created_at = "2".to_owned();
        replay.canonical_sha256 = trails_bloom_link_canonical(&replay);
        assert_eq!(
            store
                .record_fictional_energy_vfx_trails_bloom_frame_link(&replay)
                .expect("idempotent replay"),
            link
        );
        let connection = store.lock_connection().expect("lock");
        for hash in owned_hashes {
            assert_eq!(
                connection
                    .query_row(
                        "SELECT reachability FROM objects WHERE sha256 = ?1",
                        params![hash],
                        |row| row.get::<_, String>(0),
                    )
                    .expect("owned object"),
                "reachable"
            );
        }
        assert!(
            connection
                .query_row(
                    "SELECT COUNT(*) FROM objects WHERE sha256 IN (?1, ?2, ?3)",
                    params![
                        link.base_frame_key_sha256,
                        link.bloom_key_sha256,
                        link.source_trail_key_sha256
                    ],
                    |row| row.get::<_, i64>(0),
                )
                .expect("parent keys are not CAS")
                == 0
        );
    }

    #[test]
    fn fictional_energy_vfx_trails_bloom_store_rejects_conflict_and_parent_mismatch() {
        let (store, link, _) = trails_bloom_store_fixture();
        store
            .record_fictional_energy_vfx_trails_bloom_frame_link(&link)
            .expect("record trails bloom link");

        let mut conflict = link.clone();
        conflict.sample_request_sha256 = trails_bloom_fixture_sha(30);
        conflict.canonical_sha256 = trails_bloom_link_canonical(&conflict);
        assert!(matches!(
            store.record_fictional_energy_vfx_trails_bloom_frame_link(&conflict),
            Err(StoreError::Contract { code, .. })
                if code == "FICTIONAL_ENERGY_VFX_TRAILS_BLOOM_FRAME_LINK_CONFLICT"
        ));

        let mut mismatch = link.clone();
        mismatch.camera_identity_sha256 = trails_bloom_fixture_sha(31);
        mismatch.canonical_sha256 = trails_bloom_link_canonical(&mismatch);
        assert!(matches!(
            store.record_fictional_energy_vfx_trails_bloom_frame_link(&mismatch),
            Err(StoreError::Contract { code, .. })
                if code == "FICTIONAL_ENERGY_VFX_TRAILS_BLOOM_BASE_FRAME_BINDING_MISMATCH"
        ));
        assert_eq!(
            table_count(&store, "fictional_energy_vfx_trails_bloom_frame_links"),
            1
        );
    }

