    #[test]
    fn fictional_energy_vfx_animated_socket_attachment_v2_migration_has_independent_parent_frames_and_exact_fks(
    ) {
        let store = Store::memory().expect("store");
        let connection = store.lock_connection().expect("connection");
        let parent_columns: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('fictional_energy_vfx_animated_socket_attachment_v2_links')",
                [],
                |row| row.get(0),
            )
            .expect("V2 parent columns");
        let frame_columns: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('fictional_energy_vfx_animated_socket_attachment_v2_frames')",
                [],
                |row| row.get(0),
            )
            .expect("V2 frame columns");
        assert_eq!(parent_columns, 35);
        assert_eq!(frame_columns, 22);
        for (column, target) in [
            (
                "delivery_manifest_object_sha256",
                "game_asset_delivery_links",
            ),
            ("candidate_id", "candidates"),
            (
                "animated_socket_materialization_key_sha256",
                "game_weapon_animated_glb_socket_materialization_links",
            ),
            (
                "projection_key_sha256",
                "game_weapon_animated_glb_socket_transform_projection_links",
            ),
            (
                "particle_sequence_key_sha256",
                "fictional_energy_vfx_animated_socket_particles_sequence_links",
            ),
            (
                "trail_sequence_key_sha256",
                "fictional_energy_vfx_animated_socket_trails_sequence_links",
            ),
            (
                "trail_bloom_sequence_key_sha256",
                "fictional_energy_vfx_animated_socket_trails_bloom_sequence_links",
            ),
            ("receipt_object_sha256", "objects"),
        ] {
            let count: i64 = connection
                .query_row(
                    "SELECT COUNT(*) FROM pragma_foreign_key_list('fictional_energy_vfx_animated_socket_attachment_v2_links') WHERE \"from\" = ?1 AND \"table\" = ?2",
                    params![column, target],
                    |row| row.get(0),
                )
                .expect("V2 exact parent FK");
            assert_eq!(count, 1, "missing V2 FK {column} -> {target}");
        }
        let child_parent_fk: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM pragma_foreign_key_list('fictional_energy_vfx_animated_socket_attachment_v2_frames') WHERE \"from\" = 'attachment_key_sha256' AND \"table\" = 'fictional_energy_vfx_animated_socket_attachment_v2_links'",
                [],
                |row| row.get(0),
            )
            .expect("V2 child parent FK");
        let parent_key_cas: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM objects WHERE sha256 = ?1",
                params!["0".repeat(64)],
                |row| row.get(0),
            )
            .expect("V2 parent key CAS");
        assert_eq!(child_parent_fk, 1);
        assert_eq!(parent_key_cas, 0);
    }

