    #[test]
    fn fictional_energy_vfx_animated_socket_attachment_v2_idempotence_and_closed_allowlist() {
        let original = fictional_energy_vfx_animated_socket_attachment_v2_test_record(2);
        let mut replay = original.clone();
        replay.created_at = "attachment-v2-replayed".to_owned();
        replay.canonical_sha256 =
            fictional_energy_vfx_animated_socket_attachment_v2_canonical(&replay);
        for frame in &mut replay.frames {
            frame.created_at = "frame-v2-replayed".to_owned();
            frame.canonical_sha256 =
                fictional_energy_vfx_animated_socket_attachment_v2_frame_canonical(frame);
        }
        replay.canonical_sha256 =
            fictional_energy_vfx_animated_socket_attachment_v2_canonical(&replay);
        assert!(same_fictional_energy_vfx_animated_socket_attachment_v2(
            &original, &replay,
        ));
        replay.trail_sequence_key_sha256 = "a".repeat(64);
        assert!(!same_fictional_energy_vfx_animated_socket_attachment_v2(
            &original, &replay,
        ));
        assert!(temporary_reserved_object_metadata_is_allowed(
            "application/json",
            FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_RECEIPT_KIND,
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            "application/octet-stream",
            FICTIONAL_ENERGY_VFX_ANIMATED_SOCKET_ATTACHMENT_V2_RECEIPT_KIND,
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            "application/json",
            "fictional-energy-vfx-animated-socket-attachment-v2-unknown",
            1,
        ));
    }

