    #[test]
    fn candidate_topology_quality_store_roundtrip_replay_and_reachability() {
        let (store, quality, report, reachable) = candidate_topology_quality_store_fixture();
        let (recorded, replayed) = store
            .record_candidate_topology_quality_with_replay(&quality, &report.record)
            .expect("record topology quality");
        assert!(!replayed);
        assert_eq!(recorded, quality);
        let mut replay = quality.clone();
        replay.created_at = "replay-created".to_owned();
        replay.canonical_sha256 = candidate_topology_quality_canonical(&replay);
        let (recorded_replay, replayed) = store
            .record_candidate_topology_quality_with_replay(&replay, &report.record)
            .expect("replay topology quality");
        assert!(replayed);
        assert_eq!(recorded_replay, quality);
        assert_eq!(
            store
                .get_candidate_topology_quality(&quality.topology_quality_id)
                .expect("get")
                .expect("quality"),
            quality
        );
        for hash in reachable {
            assert_eq!(
                store
                    .get_object(&hash)
                    .expect("object")
                    .expect("object")
                    .reachability,
                "reachable"
            );
        }
        assert!(store
            .get_object(&quality.topology_quality_id)
            .expect("parent key")
            .is_none());
    }

    #[test]
    fn candidate_topology_quality_store_requires_exact_inventory_and_authoring_status() {
        let (store, quality, report, _) = candidate_topology_quality_store_fixture();
        let mut reordered = quality.clone();
        reordered.part_ids.swap(0, 1);
        reordered.part_topology_snapshot_sha256s.swap(0, 1);
        reordered.canonical_sha256 = candidate_topology_quality_canonical(&reordered);
        assert!(matches!(
            store.record_candidate_topology_quality(&reordered, &report.record),
            Err(StoreError::Contract { code, .. }) if code == "CANDIDATE_TOPOLOGY_QUALITY_REPORT_BINDING_MISMATCH"
        ));
        let mut incomplete_authoring = quality;
        incomplete_authoring.authoring_topology_status = "complete".to_owned();
        incomplete_authoring.part_authoring_topology_sha256s[1] = None;
        incomplete_authoring.canonical_sha256 =
            candidate_topology_quality_canonical(&incomplete_authoring);
        assert!(matches!(
            store.record_candidate_topology_quality(&incomplete_authoring, &report.record),
            Err(StoreError::InvalidData(_))
        ));
        assert_eq!(table_count(&store, "candidate_topology_quality_links"), 0);
    }

    #[test]
    fn candidate_topology_quality_store_conflict_retarget_and_report_tamper_fail_closed() {
        let (store, quality, report, _) = candidate_topology_quality_store_fixture();
        store
            .record_candidate_topology_quality(&quality, &report.record)
            .expect("record topology quality");
        let mut conflict = quality.clone();
        conflict.request_sha256 = "4".repeat(64);
        conflict.canonical_sha256 = candidate_topology_quality_canonical(&conflict);
        let conflict_report_bytes =
            canonical_json_bytes(&serde_json::to_value(&conflict).expect("conflict report value"))
                .expect("conflict report bytes");
        let conflict_report = store
            .put_object(
                &conflict_report_bytes,
                None,
                CANDIDATE_TOPOLOGY_QUALITY_REPORT_MIME,
                CANDIDATE_TOPOLOGY_QUALITY_REPORT_KIND,
                "1",
            )
            .expect("conflict report");
        assert!(matches!(
            store.record_candidate_topology_quality(&conflict, &conflict_report.record),
            Err(StoreError::Contract { code, .. }) if code == "CANDIDATE_TOPOLOGY_QUALITY_CONFLICT"
        ));
        let connection = store.lock_connection().expect("lock");
        connection
            .execute(
                "UPDATE candidate_topology_quality_links SET payload_json = ?1 WHERE topology_quality_id = ?2",
                params!["{}", quality.topology_quality_id],
            )
            .expect("tamper payload");
        drop(connection);
        assert!(store
            .get_candidate_topology_quality(&quality.topology_quality_id)
            .is_err());
    }

