    #[test]
    fn game_weapon_animated_glb_socket_transform_projection_v2_rejects_input_schedule_and_roles_tamper(
    ) {
        let (store, mut input_tamper, _) = transform_projection_v2_fixture();
        input_tamper.input_sha256 = "f".repeat(64);
        input_tamper.canonical_sha256.clear();
        input_tamper.canonical_sha256 = canonical_json_hash(
            &serde_json::to_value(&input_tamper).expect("V2 input tamper canonical value"),
        );
        let input_object = put_transform_projection_v2_object(&store, &input_tamper);
        assert!(matches!(
            store.record_game_weapon_animated_glb_socket_transform_projection_v2(
                &input_tamper,
                &input_object.record,
            ),
            Err(StoreError::Contract { code, .. })
                if code == "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_INPUT_KEY_MISMATCH"
        ));
        assert_eq!(
            table_count(
                &store,
                "game_weapon_animated_glb_socket_transform_projection_v2_links",
            ),
            0
        );

        let (store, mut schedule_tamper, _) = transform_projection_v2_fixture();
        schedule_tamper.sample_time_ticks = vec![0, 10];
        schedule_tamper.sample_count = 2;
        schedule_tamper.frames[0].sample_time_ticks = 0;
        let mut second_frame = schedule_tamper.frames[0].clone();
        second_frame.frame_index = 1;
        second_frame.sample_time_ticks = 10;
        second_frame.source_animation_sample_sha256 = "a".repeat(64);
        second_frame.derived_socket_sample_sha256 = "b".repeat(64);
        second_frame.socket_transform_inventory_sha256 = schedule_tamper.frames[0]
            .socket_transform_inventory_sha256
            .clone();
        recanonicalize_transform_projection_v2_frame(&mut second_frame);
        schedule_tamper.frames = vec![schedule_tamper.frames[0].clone(), second_frame];
        schedule_tamper.sample_schedule_sha256 = "c".repeat(64);
        rekey_transform_projection_v2(&mut schedule_tamper);
        let schedule_object = put_transform_projection_v2_object(&store, &schedule_tamper);
        assert!(matches!(
            store.record_game_weapon_animated_glb_socket_transform_projection_v2(
                &schedule_tamper,
                &schedule_object.record,
            ),
            Err(StoreError::Contract { code, .. })
                if code == "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SAMPLE_SCHEDULE_HASH_MISMATCH"
        ));

        let (store, mut role_tamper, _) = transform_projection_v2_fixture();
        role_tamper.socket_roles_sha256 = "d".repeat(64);
        rekey_transform_projection_v2(&mut role_tamper);
        let role_object = put_transform_projection_v2_object(&store, &role_tamper);
        assert!(matches!(
            store.record_game_weapon_animated_glb_socket_transform_projection_v2(
                &role_tamper,
                &role_object.record,
            ),
            Err(StoreError::Contract { code, .. })
                if code == "GAME_WEAPON_ANIMATED_GLB_SOCKET_TRANSFORM_PROJECTION_V2_SOCKET_ROLES_HASH_MISMATCH"
        ));
    }

