        forged_part_id.canonical_sha256.clear();
        let mut canonical = forged_part_id.clone();
        canonical.receipt_object_sha256.clear();
        canonical.canonical_sha256.clear();
        forged_part_id.canonical_sha256 =
            canonical_json_hash(&serde_json::to_value(&canonical).expect("canonical value"));
