    #[test]
    fn production_weapon_form_quality_cross_view_aggregate_coverage_promotion_fail_closed() {
        let bundle = cross_view_structure_fixture();
        ensure_form_quality_cross_view_structure(&bundle).expect("valid CrossView fixture");

        let store = Store::memory().expect("CrossView migration store");
        assert_eq!(table_count(&store, "cross_view_evidence"), 0);
        assert_eq!(table_count(&store, "cross_view_evidence_cas_refs"), 0);
        let missing = CrossViewEvidenceRecord {
            bundle_object_sha256: "f".repeat(64),
            candidate_id: "candidate-cross-view".to_owned(),
            project_id: "project-cross-view".to_owned(),
            session_id: "session-cross-view".to_owned(),
            reference_canvas_sha256: "e".repeat(64),
            aggregate_status: "BLOCKED_REFERENCE_COVERAGE".to_owned(),
            hard_gate_passed: false,
            created_at: "1".to_owned(),
            updated_at: "1".to_owned(),
        };
        assert!(matches!(
            store.insert_cross_view_evidence(&missing),
            Err(StoreError::Contract { code, .. }) if code == "CROSS_VIEW_EVIDENCE_CAS_MISSING"
        ));
        assert_eq!(table_count(&store, "cross_view_evidence"), 0);
        assert_eq!(table_count(&store, "cross_view_evidence_cas_refs"), 0);

        let mut wrong_aggregate = bundle.clone();
        wrong_aggregate["aggregate_status"] = Value::String("QUALITY_TARGET_NOT_MET".to_owned());
        assert!(ensure_form_quality_cross_view_structure(&wrong_aggregate).is_err());

        let mut wrong_coverage = bundle.clone();
        wrong_coverage["coverage"]["hq_360_status"] = Value::String("eligible".to_owned());
        assert!(ensure_form_quality_cross_view_structure(&wrong_coverage).is_err());

        let mut wrong_promotion = bundle;
        wrong_promotion["promotion"]["confirm_allowed"] = Value::Bool(true);
        assert!(ensure_form_quality_cross_view_structure(&wrong_promotion).is_err());

        for kind in [
            "camera-calibration",
            "render-set-v2",
            "reference-comparison-report",
            "quality-report-v2",
            "cross-view-evidence-bundle",
        ] {
            assert!(temporary_reserved_object_metadata_is_allowed(
                "application/json",
                kind,
                1,
            ));
        }
        assert!(temporary_reserved_object_metadata_is_allowed(
            "image/png",
            "render-pass-part-id",
            1,
        ));
        assert!(temporary_reserved_object_metadata_is_allowed(
            "image/png",
            "reference-silhouette-mask-v1",
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            "application/json",
            "cross-view-evidence-unknown",
            1,
        ));
    }

    #[test]
    fn production_stage_transition_v3_roundtrip_replay_linked_query_and_reachability() {
        let (store, transition, receipt) = production_stage_v3_store_fixture();
        let (recorded, head, replayed) = store
            .record_production_stage_transition_v3_with_replay(&transition, &receipt.record)
            .expect("record V3 transition");
        assert!(!replayed);
        assert_eq!(recorded.transition_id, transition.transition_id);
        assert_eq!(recorded.receipt_object_sha256, receipt.record.sha256);
        assert_eq!(head.head_transition_id, transition.transition_id);
        assert_eq!(head.head_transition_sha256, transition.canonical_sha256);
        assert!(head.payload_json.len() >= 2);
        let mut runtime_head_canonical = head.clone();
        runtime_head_canonical.canonical_sha256.clear();
        assert_eq!(
            canonical_json_hash(
                &serde_json::to_value(runtime_head_canonical).expect("Runtime head canonical")
            ),
            head.canonical_sha256
        );
        assert_eq!(
            head.compatibility_projection.source_schema_version,
            "ProductionStageHead@3"
        );
        assert_eq!(
            head.compatibility_projection.projection_policy_sha256,
            sha256_hex(PRODUCTION_STAGE_V3_PROJECTION_POLICY.as_bytes())
        );
        assert_eq!(
            store
                .get_production_stage_transition_v3(&transition.transition_id)
                .expect("get V3 transition")
                .expect("V3 transition"),
            recorded
        );
        assert_eq!(
            store
                .get_production_stage_head_v3(
                    &transition.session_id,
                    &transition.project_id,
                    &transition.root_candidate_id,
                )
                .expect("get V3 head")
                .expect("V3 head"),
            head
        );
        assert_eq!(
            store
                .get_production_stage_head_transition_v3(
                    &transition.session_id,
                    &transition.project_id,
                    &transition.root_candidate_id,
                )
                .expect("get linked V3 transition")
                .expect("linked V3 transition"),
            recorded
        );
        let (replayed_record, replayed_head, replayed) = store
            .record_production_stage_transition_v3_with_replay(&transition, &receipt.record)
            .expect("replay V3 transition");
        assert!(replayed);
        assert_eq!(replayed_record, recorded);
        assert_eq!(replayed_head, head);
        assert_eq!(
            table_count(&store, "agentic_production_stage_transitions_v3"),
            1
        );
        assert_eq!(table_count(&store, "agentic_production_stage_heads_v3"), 1);
        assert_eq!(
            table_count(&store, "agentic_production_stage_transitions"),
            0
        );
        assert_eq!(
            table_count(&store, "agentic_production_stage_transitions_v2"),
            0
        );
        for hash in [
            receipt.record.sha256.as_str(),
            transition.root_artifact_sha256.as_str(),
            transition.reference_sha256.as_str(),
            transition.reference_canvas_object_sha256.as_str(),
            transition.design_spec_object_sha256.as_str(),
        ] {
            assert_eq!(
                store
                    .get_object(hash)
                    .expect("V3 object metadata")
                    .expect("V3 object")
                    .reachability,
                "reachable",
                "V3 object {hash} must be reachable"
            );
        }
        assert!(temporary_reserved_object_metadata_is_allowed(
            PRODUCTION_STAGE_TRANSITION_V3_MIME,
            PRODUCTION_STAGE_TRANSITION_V3_KIND,
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            PRODUCTION_STAGE_TRANSITION_V3_MIME,
            "agentic-production-stage-transition-v3-unknown",
            1,
        ));
    }

    #[test]
    fn production_stage_transition_v3_camera_edge_updates_head_and_preserves_history() {
        let (store, first, first_receipt, camera_rig, camera_lock) = {
            let (store, camera_lock, camera_rig, camera_receipt) =
                production_camera_lock_store_fixture();
            let first = store
                .get_production_stage_transition_v3("transition-production-stage-v3")
                .expect("first transition read")
                .expect("first transition");
            let first_receipt = store
                .get_object(&first.receipt_object_sha256)
                .expect("first receipt row")
                .expect("first receipt");
            let (camera_lock, _) = store
                .record_production_camera_lock(
                    &camera_lock,
                    &camera_rig.record,
                    &camera_receipt.record,
                )
                .expect("record camera lock");
            (store, first, first_receipt, camera_rig, camera_lock)
        };

        let mut camera_transition = first.clone();
        camera_transition.transition_id = "transition-production-stage-v3-camera".to_owned();
        camera_transition.previous_head_stage = PRODUCTION_STAGE_V3_CAMERA_FROM_STAGE.to_owned();
        camera_transition.from_stage = PRODUCTION_STAGE_V3_CAMERA_FROM_STAGE.to_owned();
        camera_transition.to_stage = PRODUCTION_STAGE_V3_CAMERA_TO_STAGE.to_owned();
        camera_transition.request_key_sha256 = "9".repeat(64);
        camera_transition.input_sha256 = "a".repeat(64);
        camera_transition.parent_transition_id = Some(first.transition_id.clone());
        camera_transition.parent_transition_sha256 = Some(first.canonical_sha256.clone());
        camera_transition.parent_transition_schema_version =
            Some(PRODUCTION_STAGE_V3_SCHEMA_VERSION.to_owned());
        camera_transition.camera_lock_id = Some(camera_lock.camera_lock_id.clone());
        camera_transition.camera_lock_canonical_sha256 = Some(camera_lock.canonical_sha256.clone());
        camera_transition.camera_rig_object_sha256 =
            Some(camera_lock.camera_rig_object_sha256.clone());
        camera_transition.camera_rig_canonical_sha256 =
            Some(camera_lock.camera_rig_canonical_sha256.clone());
        camera_transition.camera_lock_receipt_object_sha256 =
            Some(camera_lock.receipt_object_sha256.clone());
        camera_transition.camera_lock_source_transition_id = Some(first.transition_id.clone());
        camera_transition.camera_lock_source_transition_sha256 =
            Some(first.canonical_sha256.clone());
        let first_head =
            production_stage_head_v3_from_transition(&first).expect("first head projection");
        camera_transition.camera_lock_source_head_canonical_sha256 =
            Some(first_head.canonical_sha256);
        camera_transition.receipt_object_sha256.clear();
        camera_transition.canonical_sha256.clear();
        camera_transition.canonical_sha256 = canonical_json_hash(
            &serde_json::to_value(&camera_transition).expect("camera transition canonical"),
        );
        let camera_payload = production_stage_transition_v3_payload_json(&camera_transition)
            .expect("camera transition payload");
        let camera_receipt = store
            .put_object(
                camera_payload.as_bytes(),
                None,
                PRODUCTION_STAGE_TRANSITION_V3_MIME,
                PRODUCTION_STAGE_TRANSITION_V3_KIND,
                "2",
            )
            .expect("camera transition receipt");

        let (stored, head, replayed) = store
            .record_production_stage_transition_v3_with_replay(
                &camera_transition,
                &camera_receipt.record,
            )
            .expect("record camera-calibrated transition");
        assert!(!replayed);
        assert_eq!(stored.to_stage, PRODUCTION_STAGE_V3_CAMERA_TO_STAGE);
        assert_eq!(head.head_transition_id, camera_transition.transition_id);
        assert_eq!(
            head.head_transition_sha256,
            camera_transition.canonical_sha256
        );
        assert_eq!(head.camera_lock_id, camera_transition.camera_lock_id);
        assert_eq!(
            store
                .get_production_stage_head_v3(
                    &camera_transition.session_id,
                    &camera_transition.project_id,
                    &camera_transition.root_candidate_id,
                )
                .expect("camera head read")
                .expect("camera head"),
            head
        );
        assert_eq!(
            store
                .get_production_stage_transition_v3(&first.transition_id)
                .expect("historical first transition read")
                .expect("historical first transition"),
            first
        );
        assert_eq!(
            store
                .get_production_stage_transition_v3(&camera_transition.transition_id)
                .expect("camera transition read")
                .expect("camera transition"),
            stored
        );
        assert_eq!(
            store
                .get_production_camera_lock(&camera_lock.camera_lock_id)
                .expect("camera lock restart read")
                .expect("camera lock"),
            camera_lock
        );
        for hash in [
            camera_rig.record.sha256.as_str(),
            camera_lock.receipt_object_sha256.as_str(),
            camera_receipt.record.sha256.as_str(),
            first_receipt.sha256.as_str(),
        ] {
            assert_eq!(
                store
                    .get_object(hash)
                    .expect("camera edge object row")
                    .expect("camera edge object")
                    .reachability,
                "reachable",
                "camera edge object {hash} must be reachable"
            );
        }
        assert!(store
            .get_object(&first.transition_id)
            .expect("transition id is not CAS")
            .is_none());

        let (_replayed_record, replayed_head, replayed) = store
            .record_production_stage_transition_v3_with_replay(&first, &first_receipt)
            .expect("historical first transition replay");
        assert!(replayed);
        assert_eq!(replayed_head, head);
    }

    #[test]
    fn production_stage_transition_v3_rejects_blocked_optional_and_conflicting_inputs() {
        let (store, transition, receipt) = production_stage_v3_store_fixture();
        let mut blocked = transition.clone();
        blocked.gate_status = "fail".to_owned();
        blocked.status = "blocked".to_owned();
        let mut blocked_canonical = blocked.clone();
        blocked_canonical.receipt_object_sha256.clear();
        blocked_canonical.canonical_sha256.clear();
        blocked.canonical_sha256 = canonical_json_hash(
            &serde_json::to_value(blocked_canonical).expect("blocked canonical"),
        );
        let blocked_payload =
            production_stage_transition_v3_payload_json(&blocked).expect("blocked payload");
        let blocked_receipt = store
            .put_object(
                blocked_payload.as_bytes(),
                None,
                PRODUCTION_STAGE_TRANSITION_V3_MIME,
                PRODUCTION_STAGE_TRANSITION_V3_KIND,
                "1",
            )
            .expect("blocked receipt");
        assert!(matches!(
            store.record_production_stage_transition_v3(&blocked, &blocked_receipt.record),
            Err(StoreError::Contract { code, .. })
                if code == "PRODUCTION_STAGE_TRANSITION_V3_BLOCKED_INPUT"
        ));
        assert_eq!(
            table_count(&store, "agentic_production_stage_transitions_v3"),
            0
        );
        assert_eq!(table_count(&store, "agentic_production_stage_heads_v3"), 0);

        let mut optional = transition.clone();
        optional.quality_report_object_sha256 = Some("a".repeat(64));
        let mut optional_canonical = optional.clone();
        optional_canonical.receipt_object_sha256.clear();
        optional_canonical.canonical_sha256.clear();
        optional.canonical_sha256 = canonical_json_hash(
            &serde_json::to_value(optional_canonical).expect("optional canonical"),
        );
        let optional_payload =
            production_stage_transition_v3_payload_json(&optional).expect("optional payload");
        let optional_receipt = store
            .put_object(
                optional_payload.as_bytes(),
                None,
                PRODUCTION_STAGE_TRANSITION_V3_MIME,
                PRODUCTION_STAGE_TRANSITION_V3_KIND,
                "1",
            )
            .expect("optional receipt");
        assert!(matches!(
            store.record_production_stage_transition_v3(&optional, &optional_receipt.record),
            Err(StoreError::InvalidData(_)) | Err(StoreError::Contract { .. })
        ));
        assert_eq!(
            table_count(&store, "agentic_production_stage_transitions_v3"),
            0
        );

        store
            .record_production_stage_transition_v3(&transition, &receipt.record)
            .expect("initial V3 transition");
        let mut conflict = transition.clone();
        conflict.input_sha256 = "9".repeat(64);
        let mut conflict_canonical = conflict.clone();
        conflict_canonical.receipt_object_sha256.clear();
        conflict_canonical.canonical_sha256.clear();
        conflict.canonical_sha256 = canonical_json_hash(
            &serde_json::to_value(conflict_canonical).expect("conflict canonical"),
        );
        let conflict_payload =
            production_stage_transition_v3_payload_json(&conflict).expect("conflict payload");
        let conflict_receipt = store
            .put_object(
                conflict_payload.as_bytes(),
                None,
                PRODUCTION_STAGE_TRANSITION_V3_MIME,
                PRODUCTION_STAGE_TRANSITION_V3_KIND,
                "1",
            )
            .expect("conflict receipt");
        assert!(matches!(
            store.record_production_stage_transition_v3(&conflict, &conflict_receipt.record),
            Err(StoreError::Contract { code, .. })
                if code == "PRODUCTION_STAGE_TRANSITION_V3_IMMUTABLE_CONFLICT"
        ));

        let mut stale = transition.clone();
        stale.transition_id = "transition-production-stage-v3-stale".to_owned();
        let mut stale_canonical = stale.clone();
        stale_canonical.receipt_object_sha256.clear();
        stale_canonical.canonical_sha256.clear();
        stale.canonical_sha256 =
            canonical_json_hash(&serde_json::to_value(stale_canonical).expect("stale canonical"));
        let stale_payload =
            production_stage_transition_v3_payload_json(&stale).expect("stale payload");
        let stale_receipt = store
            .put_object(
                stale_payload.as_bytes(),
                None,
                PRODUCTION_STAGE_TRANSITION_V3_MIME,
                PRODUCTION_STAGE_TRANSITION_V3_KIND,
                "1",
            )
            .expect("stale receipt");
        assert!(matches!(
            store.record_production_stage_transition_v3(&stale, &stale_receipt.record),
            Err(StoreError::Contract { code, .. })
                if code == "PRODUCTION_STAGE_TRANSITION_V3_STALE_HEAD"
        ));
        assert_eq!(
            table_count(&store, "agentic_production_stage_transitions_v3"),
            1
        );
        assert_eq!(table_count(&store, "agentic_production_stage_heads_v3"), 1);
    }

    #[test]
    fn production_stage_transition_v3_restart_get_revalidates_durable_rows() {
        let root = test_root("production-stage-v3-restart");
        let database = root.join("store.sqlite");
        let cas = root.join("store.cas");
        let (store, transition, receipt) = production_stage_v3_store_fixture_with_store(
            Store::open_with_cas(&database, &cas).expect("V3 persistent store"),
        );
        let (recorded, head) = store
            .record_production_stage_transition_v3(&transition, &receipt.record)
            .expect("persist V3 transition");
        drop(store);
        let restarted = Store::open_with_cas(&database, &cas).expect("restart V3 store");
        assert_eq!(
            restarted
                .get_production_stage_transition_v3(&transition.transition_id)
                .expect("restart get V3 transition"),
            Some(recorded)
        );
        assert_eq!(
            restarted
                .get_production_stage_head_v3(
                    &transition.session_id,
                    &transition.project_id,
                    &transition.root_candidate_id,
                )
                .expect("restart get V3 head"),
            Some(head)
        );
        drop(restarted);
        fs::remove_dir_all(root).expect("V3 restart fixture cleanup");
    }

    #[test]
    fn production_stage_transition_v2_roundtrip_replay_and_v1_unchanged() {
        let (store, transition, receipt) = production_stage_v2_store_fixture();
        let v1_count_before = table_count(&store, "agentic_production_stage_transitions");
        let read_snapshot = |store: &Store| {
            let connection = store.lock_connection().expect("snapshot lock");
            let objects: (i64, i64, i64) = connection
                .query_row(
                    "SELECT COUNT(*), COALESCE(SUM(size_bytes), 0), COALESCE(SUM(CASE WHEN reachability = 'reachable' THEN 1 ELSE 0 END), 0) FROM objects",
                    [],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
                )
                .expect("object snapshot");
            let v2_rows: (i64, i64) = connection
                .query_row(
                    "SELECT (SELECT COUNT(*) FROM agentic_production_stage_transitions_v2), (SELECT COUNT(*) FROM agentic_production_stage_heads_v2)",
                    [],
                    |row| Ok((row.get(0)?, row.get(1)?)),
                )
                .expect("V2 row snapshot");
            (objects, v2_rows)
        };
        let (recorded, head, replayed) = store
            .record_production_stage_transition_v2_with_replay(&transition, &receipt.record)
            .expect("record V2 transition");
        assert!(!replayed);
        assert_eq!(recorded, transition);
        assert_eq!(head.head_transition_id, transition.transition_id);
        assert_eq!(
            table_count(&store, "agentic_production_stage_transitions"),
            v1_count_before
        );
        let before_historical_get = read_snapshot(&store);

        // Advance the historical V1 head after the immutable V2 transition
        // has committed.  V2 get must validate its parent transition and
        // receipt, but must not require that parent to remain the V1 head.
        {
            let connection = store.lock_connection().expect("V1 head lock");
            connection
                .execute(
                    "UPDATE agentic_production_stage_heads SET head_stage = 'gray-model', head_transition_id = 'transition-v2-gray', head_transition_sha256 = (SELECT canonical_sha256 FROM agentic_production_stage_transitions WHERE transition_id = 'transition-v2-gray'), updated_at = '2' WHERE session_id = ?1 AND project_id = ?2 AND candidate_id = ?3",
                    params![
                        transition.session_id,
                        transition.project_id,
                        transition.root_candidate_id,
                    ],
                )
                .expect("advance V1 head for historical-read regression");
        }
        let (replayed_record, replayed_head, replayed) = store
            .record_production_stage_transition_v2_with_replay(&transition, &receipt.record)
            .expect("replay V2 transition");
        assert!(replayed);
        assert_eq!(replayed_record, recorded);
        assert_eq!(replayed_head, head);
        assert_eq!(
            store
                .get_production_stage_transition_v2(&transition.transition_id)
                .expect("get V2 transition"),
            Some(transition.clone())
        );
        assert_eq!(read_snapshot(&store), before_historical_get);
        assert_eq!(
            store
                .get_production_stage_head_v2(
                    &transition.session_id,
                    &transition.project_id,
                    &transition.root_candidate_id,
                )
                .expect("get V2 head"),
            Some(head)
        );
        assert_eq!(read_snapshot(&store), before_historical_get);
        assert_eq!(
            store
                .get_object(&receipt.record.sha256)
                .expect("V2 receipt metadata")
                .expect("V2 receipt")
                .reachability,
            "reachable"
        );
        for hash in [
            transition.root_artifact_sha256.as_str(),
            transition.head_artifact_sha256.as_str(),
            transition.topology_quality_report_object_sha256.as_str(),
            transition
                .material_surface_quality_report_object_sha256
                .as_str(),
        ] {
            assert_eq!(
                store
                    .get_object(hash)
                    .expect("V2 ancestor metadata")
                    .expect("V2 ancestor object")
                    .reachability,
                "reachable",
                "V2 root {hash} must be reachable"
            );
        }
        assert!(temporary_reserved_object_metadata_is_allowed(
            PRODUCTION_STAGE_TRANSITION_V2_MIME,
            PRODUCTION_STAGE_TRANSITION_V2_KIND,
            1,
        ));
        assert!(!temporary_reserved_object_metadata_is_allowed(
            PRODUCTION_STAGE_TRANSITION_V2_MIME,
            "agentic-production-stage-transition-v2-unknown",
            1,
        ));
        assert!(store
            .get_object(&transition.root_candidate_id)
            .expect("V2 head key is not CAS")
            .is_none());
    }

    #[test]
    fn production_stage_transition_v2_conflict_stale_and_fk_fail_closed() {
        let (store, transition, receipt) = production_stage_v2_store_fixture();
        let mut invalid_parent = transition.clone();
        invalid_parent.transition_id = "transition-v2-missing-parent".to_owned();
        invalid_parent.parent_topology_transition_id = "transition-v2-no-parent".to_owned();
        invalid_parent.canonical_sha256.clear();
        invalid_parent.canonical_sha256 = canonical_json_hash(
            &serde_json::to_value(&invalid_parent).expect("invalid parent canonical"),
        );
        let invalid_payload = production_stage_transition_v2_payload_json(&invalid_parent)
            .expect("invalid parent payload");
        let invalid_receipt = store
            .put_object(
                invalid_payload.as_bytes(),
                None,
                PRODUCTION_STAGE_TRANSITION_V2_MIME,
                PRODUCTION_STAGE_TRANSITION_V2_KIND,
                "1",
            )
            .expect("invalid parent receipt");
        assert!(store
            .record_production_stage_transition_v2(&invalid_parent, &invalid_receipt.record)
            .is_err());
        assert_eq!(
            table_count(&store, "agentic_production_stage_transitions_v2"),
            0
        );
        assert_eq!(table_count(&store, "agentic_production_stage_heads_v2"), 0);

        store
            .record_production_stage_transition_v2(&transition, &receipt.record)
            .expect("initial V2 transition");
        let mut conflict = transition.clone();
        conflict.input_sha256 = "9".repeat(64);
        conflict.canonical_sha256.clear();
        conflict.canonical_sha256 =
            canonical_json_hash(&serde_json::to_value(&conflict).expect("conflict canonical"));
        let conflict_payload =
            production_stage_transition_v2_payload_json(&conflict).expect("conflict payload");
        let conflict_receipt = store
            .put_object(
                conflict_payload.as_bytes(),
                None,
                PRODUCTION_STAGE_TRANSITION_V2_MIME,
                PRODUCTION_STAGE_TRANSITION_V2_KIND,
                "1",
            )
            .expect("conflict receipt");
        assert!(matches!(
            store.record_production_stage_transition_v2(&conflict, &conflict_receipt.record),
            Err(StoreError::Contract { code, .. })
                if code == "PRODUCTION_STAGE_TRANSITION_V2_IMMUTABLE_CONFLICT"
        ));
        let mut stale = transition.clone();
        stale.transition_id = "transition-v2-stale".to_owned();
        stale.parent_topology_transition_id = transition.parent_topology_transition_id.clone();
        stale.canonical_sha256.clear();
        stale.canonical_sha256 =
            canonical_json_hash(&serde_json::to_value(&stale).expect("stale canonical"));
        let stale_payload =
            production_stage_transition_v2_payload_json(&stale).expect("stale payload");
        let stale_receipt = store
            .put_object(
                stale_payload.as_bytes(),
                None,
                PRODUCTION_STAGE_TRANSITION_V2_MIME,
                PRODUCTION_STAGE_TRANSITION_V2_KIND,
                "1",
            )
            .expect("stale receipt");
        assert!(matches!(
            store.record_production_stage_transition_v2(&stale, &stale_receipt.record),
            Err(StoreError::Contract { code, .. })
                if code == "PRODUCTION_STAGE_TRANSITION_V2_STALE_HEAD"
        ));
        assert_eq!(
            table_count(&store, "agentic_production_stage_transitions_v2"),
            1
        );
        assert_eq!(table_count(&store, "agentic_production_stage_heads_v2"), 1);
    }

